        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
        private static void AutoBootstrap()
        {
            SceneManager.sceneLoaded -= OnSceneLoaded;
            SceneManager.sceneLoaded += OnSceneLoaded;
            EnsureForScene(SceneManager.GetActiveScene());
        }

        private static void OnSceneLoaded(Scene scene, LoadSceneMode mode)
        {
            EnsureForScene(scene);
        }

        private static void EnsureForScene(Scene scene)
        {
            if (!string.Equals(scene.name, SceneName, System.StringComparison.Ordinal))
                return;

            if (FindAnyObjectByType<OrbiosisBootstrap>() != null)
                return;

            GameObject root = new GameObject("OrbiosisRoot");
            root.AddComponent<OrbiosisBootstrap>();
        }

        private void Awake()
        {
            if (!Application.isPlaying)
                return;

            EnsureVertical();
            EnsureCamera();
            EnsureEventSystem();
            bestScore = PlayerPrefs.GetInt(BestScoreKey, 0);
            ozParts = PlayerPrefs.GetInt(OzPartsKey, 0);
            coreShards = Mathf.Max(PlayerPrefs.GetInt(CoreShardsKey, DefaultTestCoreShards), DefaultTestCoreShards);
            PlayerPrefs.SetInt(CoreShardsKey, coreShards);
            soundEnabled = PlayerPrefs.GetInt(SoundEnabledKey, 1) != 0;
            musicEnabled = PlayerPrefs.GetInt(MusicEnabledKey, 1) != 0;
            testMode = PlayerPrefs.GetInt(TestModeKey, 0) != 0;
            ClearIncompleteTutorialPersistentUnlocks();
            hpLevel = PlayerPrefs.GetInt(HpLevelKey, 0);
            stationEvolutionLevel = Mathf.Clamp(PlayerPrefs.GetInt(StationEvolutionLevelKey, StationMinEvolutionLevel), StationMinEvolutionLevel, StationMaxEvolutionLevel);
            PlayerPrefs.SetInt(StationEvolutionLevelKey, stationEvolutionLevel);
            shieldLevel = PlayerPrefs.GetInt(ShieldLevelKey, 0);
            attackLevel = PlayerPrefs.GetInt(AttackLevelKey, 0);
            crafterOwned = PlayerPrefs.GetInt(CrafterOwnedKey, 0) != 0;
            generatorOwned = PlayerPrefs.GetInt(GeneratorOwnedKey, 0) != 0;
            repairOwned = PlayerPrefs.GetInt(RepairOwnedKey, 0) != 0;
            shieldDroneOwned = PlayerPrefs.GetInt(ShieldDroneOwnedKey, 0) != 0;
            collectorDroneOwned = PlayerPrefs.GetInt(CollectorDroneOwnedKey, 0) != 0;
            mineLayerDroneOwned = PlayerPrefs.GetInt(MineLayerDroneOwnedKey, 0) != 0;
            ozCoreMinerOwned = PlayerPrefs.GetInt(OzCoreMinerOwnedKey, 0) != 0;
            hiveDroneOwned = PlayerPrefs.GetInt(HiveDroneOwnedKey, 0) != 0;
            gladiatorDroneOwned = PlayerPrefs.GetInt(GladiatorDroneOwnedKey, 0) != 0;
            horizonDroneOwned = PlayerPrefs.GetInt(HorizonDroneOwnedKey, 0) != 0;
            tamerDroneOwned = PlayerPrefs.GetInt(TamerDroneOwnedKey, 0) != 0;
            queenDroneOwned = PlayerPrefs.GetInt(QueenDroneOwnedKey, 0) != 0;
            mimicDroneOwned = PlayerPrefs.GetInt(MimicDroneOwnedKey, 0) != 0;
            sniperDroneOwned = PlayerPrefs.GetInt(SniperDroneOwnedKey, 0) != 0;
            ozCoreMinerReturnAtUtc = ParseStoredUtc(PlayerPrefs.GetString(OzCoreMinerReturnAtKey, string.Empty));
            double nowUtc = GetUtcNowSeconds();
            ozCoreMinerCargoReady = ozCoreMinerOwned && ozCoreMinerReturnAtUtc > 0.0 && nowUtc >= ozCoreMinerReturnAtUtc;
            ozCoreMinerOnMission = ozCoreMinerOwned && ozCoreMinerReturnAtUtc > nowUtc;
            homingMissileModuleOwned = PlayerPrefs.GetInt(HomingMissileModuleOwnedKey, 0) != 0;
            laserModuleOwned = PlayerPrefs.GetInt(LaserModuleOwnedKey, 0) != 0;
            arcChainModuleOwned = PlayerPrefs.GetInt(ArcChainModuleOwnedKey, 0) != 0;
            railSpikeModuleOwned = PlayerPrefs.GetInt(RailSpikeModuleOwnedKey, 0) != 0;
            homingMissileModuleActive = homingMissileModuleOwned && PlayerPrefs.GetInt(HomingMissileModuleActiveKey, 1) != 0;
            laserModuleActive = laserModuleOwned && PlayerPrefs.GetInt(LaserModuleActiveKey, 1) != 0;
            arcChainModuleActive = arcChainModuleOwned && PlayerPrefs.GetInt(ArcChainModuleActiveKey, 1) != 0;
            railSpikeModuleActive = railSpikeModuleOwned && PlayerPrefs.GetInt(RailSpikeModuleActiveKey, 1) != 0;
            coreCannonActive = PlayerPrefs.GetInt(CoreCannonActiveKey, 1) != 0;
            coreForgeOwned = PlayerPrefs.GetInt(CoreForgeOwnedKey, 0) != 0;
            storageDepotOwned = PlayerPrefs.GetInt(StorageDepotOwnedKey, 0) != 0;
            droneUpgradePadOwned = PlayerPrefs.GetInt(DroneUpgradePadOwnedKey, 0) != 0;
            SetupAudio();
            BuildInterface();
            AppSettings.OnLanguageChanged += OnLanguageChanged;
            ShowMenu();
        }

#if UNITY_EDITOR
        private void OnEnable()
        {
            if (!Application.isPlaying)
                QueueEditableUiBuildIfNeeded();
        }

        private void OnValidate()
        {
            if (!Application.isPlaying)
                QueueEditableUiBuildIfNeeded();
        }

        private void QueueEditableUiBuildIfNeeded()
        {
            if (!editableUiAutoBuildInEditor || editableUiBuildQueued)
                return;
            if (gameObject == null || !gameObject.scene.IsValid() || !gameObject.scene.isLoaded)
                return;
            if (GetComponentInChildren<Canvas>(true) != null)
                return;

            editableUiBuildQueued = true;
            UnityEditor.EditorApplication.delayCall += BuildEditableUiIfStillNeeded;
        }

        private void BuildEditableUiIfStillNeeded()
        {
            editableUiBuildQueued = false;
            if (this == null || Application.isPlaying || !editableUiAutoBuildInEditor)
                return;
            if (gameObject == null || !gameObject.scene.IsValid() || !gameObject.scene.isLoaded)
                return;
            if (GetComponentInChildren<Canvas>(true) != null)
                return;

            RebuildEditableUiHierarchy();
        }
#endif

        private void OnDestroy()
        {
            AppSettings.OnLanguageChanged -= OnLanguageChanged;
        }

        private void OnLanguageChanged(GameLanguage language)
        {
            RefreshSettingsLabels();
            RefreshUpgradeLabels();
            RefreshStationControlLabels();
            RefreshOzCoreMinerSendLabel();
            if (menuHangarProfileRoot != null && menuHangarProfileRoot.gameObject.activeSelf)
                ShowMenuHangarProfile(menuHangarSelectedUpgradeIndex);
            if (droneUpgradeRoot != null && droneUpgradeRoot.gameObject.activeSelf)
                ShowDroneUpgradeWindow(selectedDroneUpgradeTarget);
            if (coreForgeModuleRoot != null && coreForgeModuleRoot.gameObject.activeSelf)
            {
                if (selectedCoreForgeModuleIndex >= 0)
                    ShowCoreForgeModuleDetail(selectedCoreForgeModuleIndex);
                else
                    ShowCoreForgeModuleSelection();
            }
            if (storageDepotWindowRoot != null && storageDepotWindowRoot.gameObject.activeSelf)
                RefreshStorageDepotWindow();
            if (tutorialResultOverlay != null && tutorialResultOverlay.activeSelf)
            {
                if (tutorialResultBodyText != null)
                    tutorialResultBodyText.text = L("tutorial_result.body");
                if (tutorialResultRewardText != null)
                    tutorialResultRewardText.text = L("tutorial_result.rewards");
            }
            if (state == GameState.Menu)
                UpdateGameTitlePosition();
        }

        [ContextMenu("Rebuild Editable UI Hierarchy")]
        public void RebuildEditableUiHierarchy()
        {
            if (Application.isPlaying)
                return;

            stationEvolutionLevel = Mathf.Clamp(stationEvolutionLevel, StationMinEvolutionLevel, StationMaxEvolutionLevel);
            BuildInterface();
#if UNITY_EDITOR
            UnityEditor.EditorUtility.SetDirty(this);
            UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(gameObject.scene);
#endif
        }

        private void Update()
        {
            if (!Application.isPlaying)
                return;

            EnsureVertical();
            EnsureEventSystemPeriodically();
            outpostDockReattachLockTimer = Mathf.Max(0f, outpostDockReattachLockTimer - Time.unscaledDeltaTime);
            UpdateStarBands();
            UpdateHangarRevealLayout();
            UpdatePlayfieldCameraLayout();
            UpdateBaseShipHullLayout();
            UpdateOutpostLayout();
            UpdateStoryDialogLayout();
            UpdateBaseHangarRevealTransition();
            UpdateOrb();
            UpdateCameraFollowOrb();
            UpdateExplosions();
            UpdateArcViews();
            UpdateCargoUnloadViews();
            UpdateMenuPresentation();

            if (stationControlOpen)
            {
                Time.timeScale = 0f;
                battleDraggedDroneTarget = DroneUpgradeTarget.None;
                HideDroneCommandVisuals();
                if (droneInfoRoot != null)
                    droneInfoRoot.gameObject.SetActive(false);
                UpdateGeneratorShieldChargeSound(false);
                return;
            }

            if (droneUpgradeRoot != null && droneUpgradeRoot.gameObject.activeSelf)
            {
                Time.timeScale = 0f;
                battleDraggedDroneTarget = DroneUpgradeTarget.None;
                HideDroneCommandVisuals();
                if (droneInfoRoot != null)
                    droneInfoRoot.gameObject.SetActive(false);
                UpdateGeneratorShieldChargeSound(false);
                return;
            }

            if (coreForgeModuleRoot != null && coreForgeModuleRoot.gameObject.activeSelf)
            {
                Time.timeScale = 0f;
                battleDraggedDroneTarget = DroneUpgradeTarget.None;
                HideDroneCommandVisuals();
                if (droneInfoRoot != null)
                    droneInfoRoot.gameObject.SetActive(false);
                UpdateGeneratorShieldChargeSound(false);
                return;
            }

            if (storageDepotWindowRoot != null && storageDepotWindowRoot.gameObject.activeSelf)
            {
                Time.timeScale = 0f;
                battleDraggedDroneTarget = DroneUpgradeTarget.None;
                HideDroneCommandVisuals();
                if (droneInfoRoot != null)
                    droneInfoRoot.gameObject.SetActive(false);
                UpdateGeneratorShieldChargeSound(false);
                return;
            }

            if (state == GameState.Menu && menuHangarOpen)
            {
                HandleStorageDepotClickInput();
                HandleMenuHangarDroneUpgradeInput();
                UpdateDroneUpgradePadDocking();
                UpdateCoreForgeModuleDocking();
                UpdateMenuHangarDroneCommands();
            }

            if (state != GameState.Playing || gameOver || transitioningToGame)
            {
                Time.timeScale = 1f;
                if (!(state == GameState.Menu && menuHangarOpen))
                {
                    battleDraggedDroneTarget = DroneUpgradeTarget.None;
                    HideDroneCommandVisuals();
                }
                if (droneInfoRoot != null)
                    droneInfoRoot.gameObject.SetActive(false);
                if (state != GameState.Menu && state != GameState.ModeSelect && state != GameState.StoryLevels && state != GameState.Bestiary)
                    UpdateGeneratorShieldChargeSound(false);
                return;
            }

            if (storyCinematicActive)
            {
                Time.timeScale = 1f;
                battleDraggedDroneTarget = DroneUpgradeTarget.None;
                HideDroneCommandVisuals();
                if (droneInfoRoot != null)
                    droneInfoRoot.gameObject.SetActive(false);
                UpdateGeneratorShieldChargeSound(false);
                return;
            }

            bool cameraInputConsumed = HandleHangarMouseWheelCamera();
            elapsed += Time.deltaTime;
            if (!cameraInputConsumed)
                HandleInput();
            UnloadCargoAtBase();
            UpdateDroneInfoPanel();
            UpdateCrafterDrone();
            UpdateDroneUpgradePadDocking();
            UpdateGeneratorDrone();
            UpdateRepairDrone();
            UpdateShieldDrone();
            UpdateCollectorDrone();
            UpdateMineLayerDrone();
            UpdateFriendlyMineLayerMines();
            UpdateHiveDrone();
            UpdateHiveMiniTurrets();
            UpdateGladiatorDrone();
            UpdateHorizonDrone();
            UpdateTamerDrone();
            UpdateQueenDrone();
            UpdateMimicDrone();
            UpdateSniperDrone();
            UpdateCoreForgeConversion();
            FireLoop();
            HomingMissileLoop();
            LaserModuleLoop();
            ArcChainModuleLoop();
            RailSpikeModuleLoop();
            UpdateProjectiles();
            UpdateEnemyProjectiles();
            UpdateHazards();
            UpdatePartDrops();
            SpawnLoop();
            score = Mathf.Max(score, Mathf.FloorToInt(elapsed * 10f));
            RefreshHud();
            UpdateBaseTab();
            UpdateShieldVisuals();
            Time.timeScale = ResolveGameplayTimeScale();
        }

        private void EnsureEventSystemPeriodically()
        {
            eventSystemGuardTimer -= Time.unscaledDeltaTime;
            if (eventSystemGuardTimer > 0f)
                return;

            eventSystemGuardTimer = 1f;
            EnsureEventSystem();
        }

        private static void EnsureVertical()
        {
#if UNITY_IOS
            MahjongGame.SceneOrientationPolicy.ApplyLandscapeOnly();
#else
            Screen.autorotateToPortrait = true;
            Screen.autorotateToPortraitUpsideDown = false;
            Screen.autorotateToLandscapeLeft = false;
            Screen.autorotateToLandscapeRight = false;
            Screen.orientation = ScreenOrientation.Portrait;
#endif
        }

        private static void EnsureCamera()
        {
            Camera camera = Camera.main != null ? Camera.main : FindAnyObjectByType<Camera>();
            if (camera == null)
            {
                GameObject cameraObject = new GameObject("Main Camera", typeof(Camera), typeof(AudioListener));
                cameraObject.tag = "MainCamera";
                camera = cameraObject.GetComponent<Camera>();
            }

            camera.clearFlags = CameraClearFlags.SolidColor;
            camera.backgroundColor = Space;
            camera.orthographic = true;
            camera.orthographicSize = 5f;
        }

        private static void EnsureEventSystem()
        {
            MahjongGame.EventSystemInputModeGuard.EnsureCompatibleEventSystems();
        }

        private static Vector2 GetReferenceResolution()
        {
#if UNITY_IOS
            return new Vector2(1600f, 900f);
#else
            return new Vector2(900f, 1600f);
#endif
        }

        private void BuildInterface()
        {
            Dictionary<string, EditableRectLayout> editableLayouts = CaptureEditableUiLayouts();
            DestroyExistingUiCanvases();

            GameObject canvasObject = new GameObject("Canvas", typeof(RectTransform), typeof(Canvas), typeof(CanvasScaler), typeof(GraphicRaycaster));
            canvasObject.transform.SetParent(transform, false);
            canvas = canvasObject.GetComponent<Canvas>();
            canvas.renderMode = RenderMode.ScreenSpaceOverlay;
            canvas.sortingOrder = 100;

            CanvasScaler scaler = canvasObject.GetComponent<CanvasScaler>();
            scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;
            scaler.referenceResolution = GetReferenceResolution();
            scaler.matchWidthOrHeight = 0f;

            RectTransform root = canvasObject.GetComponent<RectTransform>();
            Stretch(root);

            Image background = CreateImage(root, "Background", Space);
            Stretch(background.rectTransform);
            CreateSpaceParallax(root);

            playfield = CreatePanel(root, "Playfield", Color.clear);
            Stretch(playfield);
            UpdatePlayfieldCameraLayout();
            CreateBaseShipHull(playfield);
            BuildHangarScrollCatcher(root);

            RectTransform top = CreatePanel(root, "TopHud", Color.clear);
            topHudRoot = top;
            top.anchorMin = new Vector2(0f, 1f);
            top.anchorMax = new Vector2(1f, 1f);
            top.pivot = new Vector2(0.5f, 1f);
            top.sizeDelta = new Vector2(0f, 156f);
            top.anchoredPosition = Vector2.zero;

            healthFill = CreateCenterBar(top, "HealthBar", new Vector2(0.300f, 0.545f), new Vector2(0.700f, 0.635f), new Color(0.055f, 0.010f, 0.015f, 0.82f), Hazard, StatusBarHpResourcePath);
            shieldFill = CreateCenterBar(top, "ShieldBar", new Vector2(0.300f, 0.395f), new Vector2(0.700f, 0.485f), new Color(0.010f, 0.052f, 0.070f, 0.82f), Cyan, StatusBarShieldResourcePath);
            cargoFill = CreateCenterBar(top, "CargoBar", new Vector2(0.300f, 0.245f), new Vector2(0.700f, 0.335f), new Color(0.010f, 0.058f, 0.030f, 0.82f), new Color(0.25f, 1f, 0.44f, 1f), StatusBarPartsResourcePath);

            scoreText = CreateText(top, "Score", "0", 36f, FontStyles.Bold, Gold);
            scoreText.rectTransform.anchorMin = new Vector2(0.04f, 0.03f);
            scoreText.rectTransform.anchorMax = new Vector2(0.32f, 0.21f);
            scoreText.rectTransform.offsetMin = Vector2.zero;
            scoreText.rectTransform.offsetMax = Vector2.zero;

            partsText = CreateText(top, "OzParts", LF("hud.parts", 0), 21f, FontStyles.Bold, Gold);
            partsText.rectTransform.anchorMin = new Vector2(0.44f, 0.03f);
            partsText.rectTransform.anchorMax = new Vector2(0.70f, 0.21f);
            partsText.rectTransform.offsetMin = Vector2.zero;
            partsText.rectTransform.offsetMax = Vector2.zero;

            shieldText = CreateText(top, "Shield", LF("hud.shield", 0), 22f, FontStyles.Bold, Cyan);
            shieldText.rectTransform.anchorMin = new Vector2(0.75f, 0.03f);
            shieldText.rectTransform.anchorMax = new Vector2(0.98f, 0.21f);
            shieldText.rectTransform.offsetMin = Vector2.zero;
            shieldText.rectTransform.offsetMax = Vector2.zero;

            topStationButton = CreateButton(root, "TopStationButton", K("top.station"), new Vector2(0.5f, 0f), new Vector2(0.5f, 0f), Vector2.zero, new Vector2(148f, 44f), 18f, ShowStationControl);
            baseTabButton = CreateButton(root, "BaseHangarButton", K("top.base"), new Vector2(0.5f, 0f), new Vector2(0.5f, 0f), Vector2.zero, new Vector2(148f, 44f), 18f, ToggleBaseHangar);
            baseTabLabel = baseTabButton != null ? baseTabButton.GetComponentInChildren<TextMeshProUGUI>() : null;
            if (baseTabButton != null)
                baseTabButton.gameObject.SetActive(false);
            if (topStationButton != null)
                topStationButton.gameObject.SetActive(false);
            CreateBaseTabTutorialHint(root);
            topSettingsButton = CreateButton(top, "TopMenuButton", K("top.settings"), new Vector2(0.745f, -0.430f), new Vector2(0.960f, -0.140f), Vector2.zero, Vector2.zero, 20f, ShowSettings);

            RectTransform station = CreatePanel(playfield, "StationOrbit", new Color(0.02f, 0.10f, 0.15f, 0.42f));
            station.anchorMin = new Vector2(0.5f, 0.5f);
            station.anchorMax = new Vector2(0.5f, 0.5f);
            station.pivot = new Vector2(0.5f, 0.5f);
            station.sizeDelta = Vector2.one * OrbOrbitRingSize;
            station.anchoredPosition = Vector2.zero;
            station.gameObject.SetActive(false);
            orbitRing = station;

            orb = CreatePanel(playfield, "OrbStation", Color.clear);
            orb.anchorMin = new Vector2(0.5f, 0.5f);
            orb.anchorMax = new Vector2(0.5f, 0.5f);
            orb.pivot = new Vector2(0.5f, 0.5f);
            orb.sizeDelta = Vector2.one * OrbStationBattleSize;
            orb.anchoredPosition = Vector2.zero;
            bool hasOrbSprite = ApplyOrbEvolutionSprite(orb, CurrentStationEvolutionLevel());
            if (hasOrbSprite)
                appliedOrbEvolutionLevel = CurrentStationEvolutionLevel();

            shieldRing = CreateShieldBubble(orb, "ShieldBubble", OrbShieldBubbleBaseSize);
            shieldRing.anchorMin = new Vector2(0.5f, 0.5f);
            shieldRing.anchorMax = new Vector2(0.5f, 0.5f);
            shieldRing.pivot = new Vector2(0.5f, 0.5f);
            shieldRing.anchoredPosition = Vector2.zero;
            shieldRing.gameObject.SetActive(false);
            CreateOrbDamageCracks();

            RectTransform core = CreatePanel(orb, "LivingCore", Gold);
            core.anchorMin = new Vector2(0.5f, 0.5f);
            core.anchorMax = new Vector2(0.5f, 0.5f);
            core.pivot = new Vector2(0.5f, 0.5f);
            core.sizeDelta = new Vector2(24f, 24f);
