        private Dictionary<string, EditableRectLayout> CaptureEditableUiLayouts()
        {
            Canvas existingCanvas = GetComponentInChildren<Canvas>(true);
            if (existingCanvas == null)
                return null;

            RectTransform canvasRoot = existingCanvas.transform as RectTransform;
            if (canvasRoot == null)
                return null;

            Dictionary<string, EditableRectLayout> layouts = new Dictionary<string, EditableRectLayout>(StringComparer.Ordinal);
            RectTransform[] rects = existingCanvas.GetComponentsInChildren<RectTransform>(true);
            for (int i = 0; i < rects.Length; i++)
            {
                RectTransform rect = rects[i];
                if (rect == null || rect == canvasRoot)
                    continue;

                string path = GetEditableUiPath(canvasRoot, rect);
                if (string.IsNullOrEmpty(path) || layouts.ContainsKey(path))
                    continue;

                layouts.Add(path, EditableRectLayout.From(rect));
            }

            return layouts;
        }

        private void DestroyExistingUiCanvases()
        {
            Canvas[] existingCanvases = GetComponentsInChildren<Canvas>(true);
            for (int i = existingCanvases.Length - 1; i >= 0; i--)
            {
                Canvas existingCanvas = existingCanvases[i];
                if (existingCanvas == null)
                    continue;

                GameObject canvasObject = existingCanvas.gameObject;
                if (Application.isPlaying)
                    Destroy(canvasObject);
                else
                    DestroyImmediate(canvasObject);
            }
        }

        private void ApplyEditableUiLayouts(RectTransform canvasRoot, Dictionary<string, EditableRectLayout> layouts)
        {
            if (canvasRoot == null || layouts == null || layouts.Count == 0)
                return;

            RectTransform[] rects = canvasRoot.GetComponentsInChildren<RectTransform>(true);
            for (int i = 0; i < rects.Length; i++)
            {
                RectTransform rect = rects[i];
                if (rect == null || rect == canvasRoot)
                    continue;

                string path = GetEditableUiPath(canvasRoot, rect);
                if (!layouts.TryGetValue(path, out EditableRectLayout layout))
                    continue;

                layout.Apply(rect);
            }

            for (int i = 0; i < rects.Length; i++)
            {
                RectTransform rect = rects[i];
                if (rect == null || rect == canvasRoot)
                    continue;

                string path = GetEditableUiPath(canvasRoot, rect);
                if (!layouts.TryGetValue(path, out EditableRectLayout layout))
                    continue;

                rect.SetSiblingIndex(Mathf.Clamp(layout.SiblingIndex, 0, rect.parent.childCount - 1));
            }
        }

        private static string GetEditableUiPath(RectTransform root, RectTransform rect)
        {
            if (root == null || rect == null || rect == root)
                return string.Empty;

            List<string> segments = new List<string>(8);
            Transform current = rect;
            while (current != null && current != root)
            {
                segments.Add(current.name);
                current = current.parent;
            }

            if (current != root)
                return string.Empty;

            segments.Reverse();
            return string.Join("/", segments);
        }

