        private void BuildHangarScrollCatcher(RectTransform root)
        {
            RectTransform catcher = CreatePanel(root, "WorldScrollCatcher", new Color(0f, 0f, 0f, 0f));
            Stretch(catcher);
            Image image = catcher.GetComponent<Image>();
            if (image != null)
                image.raycastTarget = true;

            EventTrigger trigger = catcher.gameObject.AddComponent<EventTrigger>();
            EventTrigger.Entry scrollEntry = new EventTrigger.Entry
            {
                eventID = EventTriggerType.Scroll
            };
            scrollEntry.callback.AddListener(data =>
            {
                if (data is PointerEventData pointerData)
                    HandleExternalHangarScroll(pointerData.scrollDelta.y);
            });
            trigger.triggers.Add(scrollEntry);

            EventTrigger.Entry dragEntry = new EventTrigger.Entry
            {
                eventID = EventTriggerType.Drag
            };
            dragEntry.callback.AddListener(data =>
            {
                if (data is PointerEventData pointerData)
                    HandleExternalHangarDrag(pointerData);
            });
            trigger.triggers.Add(dragEntry);
        }

        private float MaxHangarRevealOffset()
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            float height = root != null ? root.rect.height : 1600f;
            float platformHeight = baseShipHull != null && baseShipHull.sizeDelta.y > 1f
                ? baseShipHull.sizeDelta.y
                : Mathf.Max(BaseShipMinWidth, (root != null ? root.rect.width : 900f) * BaseShipWidthScreenFraction) * BaseShipAspectRatio;
            float yOffsetFraction = Mathf.Lerp(BaseShipParkedYOffsetFraction, BaseShipDefenderYOffsetFraction, Mathf.SmoothStep(0f, 1f, baseShipDeploymentBlend));
            float revealForHangarBottom = platformHeight * yOffsetFraction;
            return Mathf.Max(height * HangarRevealScreenFraction, revealForHangarBottom);
        }

        private float MinForwardCameraOffset()
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            float height = root != null ? root.rect.height : 1600f;
            return -height * ForwardCameraScreenFraction;
        }

        private float MaxCameraRevealOffset()
        {
            return baseHangarExpanded || baseHangarRevealTransitioning ? MaxHangarRevealOffset() : 0f;
        }

        private Vector2 PlayfieldCameraOffset()
        {
            return new Vector2(0f, hangarRevealOffset);
        }

        private RectTransform WorldCoordinateRoot()
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            return playfield != null ? playfield : root;
        }

        private bool TryScreenPointToWorldLocalPoint(Vector2 screenPosition, out Vector2 localPoint)
        {
            localPoint = Vector2.zero;
            RectTransform world = WorldCoordinateRoot();
            return world != null && RectTransformUtility.ScreenPointToLocalPointInRectangle(world, screenPosition, null, out localPoint);
        }

        private bool TryScreenPointToVirtualPlayZone(Vector2 screenPosition, out Vector2 localPoint)
        {
            // The playfield RectTransform already carries the camera offset, so
            // input must stay in exact playfield-local coordinates.
            return TryScreenPointToWorldLocalPoint(screenPosition, out localPoint);
        }

        private void UpdateCameraFollowOrb()
        {
            if (manualCameraControlTimer > 0f)
            {
                manualCameraControlTimer = Mathf.Max(0f, manualCameraControlTimer - Time.deltaTime);
                return;
            }

            if (state != GameState.Playing || gameOver || transitioningToGame || storyCinematicActive || orb == null || !orb.gameObject.activeSelf)
                return;
            bool followOutpost = ShouldCameraFollowOutpost();
            if ((IsOrbHeldOnBaseShip() || orbDeploymentStage == OrbDeploymentStage.BaseHover) && !followOutpost)
                return;

            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return;

            float height = root.rect.height;
            float topDeadZone = height * 0.12f;
            float bottomDeadZone = -height * 0.14f;
            float focusY = followOutpost ? ResolveOutpostDockPosition().y : orbY;
            float orbScreenY = focusY + hangarRevealOffset;
            float desiredCamera = hangarRevealOffset;

            if (orbScreenY > topDeadZone)
                desiredCamera = topDeadZone - focusY;
            else if (orbScreenY < bottomDeadZone)
                desiredCamera = bottomDeadZone - focusY;
            else
                return;

            desiredCamera = Mathf.Clamp(desiredCamera, MinForwardCameraOffset(), MaxCameraRevealOffset());
            float nextCamera = Mathf.Lerp(hangarRevealOffset, desiredCamera, 1f - Mathf.Exp(-5.2f * Time.deltaTime));
            SetHangarRevealOffset(nextCamera);
        }

        private bool ShouldCameraFollowOutpost()
        {
            return outpostBuilt && !IsIncompleteTutorialRun() && state == GameState.Playing && (outpostHandleDragging || outpostDefenderMode || IsOrbDockedOnOutpost());
        }

        private void UpdatePlayfieldCameraLayout()
        {
            if (playfield == null)
                return;

            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            Vector2 size = root != null ? root.rect.size : new Vector2(900f, 1600f);
            Vector2 offset = PlayfieldCameraOffset();
            playfield.anchorMin = new Vector2(0.5f, 0.5f);
            playfield.anchorMax = new Vector2(0.5f, 0.5f);
            playfield.pivot = new Vector2(0.5f, 0.5f);
            playfield.sizeDelta = size;
            playfield.anchoredPosition = offset;
            playfield.localScale = Vector3.one * Mathf.Max(0.1f, tutorialCinematicPlayfieldZoom);
        }

        private void UpdateHangarRevealLayout()
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return;

            hangarRevealOffset = Mathf.Clamp(hangarRevealOffset, MinForwardCameraOffset(), MaxCameraRevealOffset());
            if (hangarRoot == null)
                return;

            float height = root.rect.height;
            hangarRoot.anchorMin = Vector2.zero;
            hangarRoot.anchorMax = Vector2.one;
            hangarRoot.offsetMin = Vector2.zero;
            hangarRoot.offsetMax = Vector2.zero;
            hangarRoot.anchoredPosition = new Vector2(0f, -height + hangarRevealOffset);
            hangarRoot.gameObject.SetActive(state == GameState.Playing || transitioningToGame || hangarRevealOffset > 0.5f);
        }

        private void SetHangarRevealOffset(float value)
        {
            hangarRevealOffset = Mathf.Clamp(value, MinForwardCameraOffset(), MaxCameraRevealOffset());
            UpdateHangarRevealLayout();
            UpdatePlayfieldCameraLayout();
            UpdateBaseShipHullLayout();
        }

        private void BeginBaseHangarRevealTransition(bool expanded)
        {
            baseHangarExpanded = expanded;
            baseHangarRevealTransitioning = true;
            baseHangarRevealTarget = expanded ? MaxHangarRevealOffset() : 0f;
        }

        private void ResetBaseHangarRevealImmediate()
        {
            baseHangarExpanded = false;
            baseHangarRevealTransitioning = false;
            baseHangarRevealTarget = 0f;
            SetHangarRevealOffset(0f);
        }

        private void UpdateBaseHangarRevealTransition()
        {
            if (!baseHangarRevealTransitioning)
                return;

            baseHangarRevealTarget = baseHangarExpanded ? MaxHangarRevealOffset() : 0f;
            float response = 1f - Mathf.Exp(-BaseHangarRevealResponse * Time.unscaledDeltaTime);
            float nextOffset = Mathf.Lerp(hangarRevealOffset, baseHangarRevealTarget, response);
            bool arrived = Mathf.Abs(nextOffset - baseHangarRevealTarget) <= BaseHangarRevealSnapDistance;
            if (arrived)
                nextOffset = baseHangarRevealTarget;

            SetHangarRevealOffset(nextOffset);

            if (arrived)
            {
                baseHangarRevealTransitioning = false;
                if (statusText != null && state == GameState.Playing)
                    statusText.text = baseHangarExpanded ? "HANGAR OPEN" : "HANGAR CLOSED";
            }
        }

