            {
                Sprite sprite = GetSpriteFromTextureResource(BaseShipHullSpriteResourcePath);
                if (sprite != null)
                {
                    baseShipHullHasIntegratedSlots = true;
                    image.sprite = sprite;
                    image.preserveAspect = true;
                    image.type = Image.Type.Simple;
                    image.color = Color.white;
                }
                else
