                    baseShipHullHasIntegratedSlots = false;
                    image.color = new Color(0.02f, 0.12f, 0.15f, 0.94f);
                    AddOutline(baseShipHull, new Color(0.18f, 0.82f, 0.94f, 0.52f), new Vector2(3f, -3f));
                }

                image.raycastTarget = false;
            }

            CreateBaseShipSlots(parent);
            CreateBaseShipHealthBar();
            UpdateBaseShipHullLayout();
        }

