                slot.anchorMax = new Vector2(0.5f, 0.5f);
                slot.pivot = new Vector2(0.5f, 0.5f);
                slot.sizeDelta = ResolveOutpostSlotSize(i);
                slot.gameObject.SetActive(false);

                Image image = slot.GetComponent<Image>();
                if (image != null)
                {
                    image.sprite = GetSpriteFromTextureResource(OutpostTowerSpriteResourcePath);
                    image.preserveAspect = true;
                    image.raycastTarget = false;
                    image.color = Color.white;
                }

                outpostSlots[i] = slot;
            }

            for (int i = 0; i < outpostEnergyLinks.Length; i++)
            {
                RectTransform link = CreatePanel(parent, "OutpostEnergyLink" + i, new Color(0.16f, 0.95f, 1f, 0.62f));
                link.anchorMin = new Vector2(0.5f, 0.5f);
                link.anchorMax = new Vector2(0.5f, 0.5f);
                link.pivot = new Vector2(0.5f, 0f);
                link.sizeDelta = new Vector2(4f, 1f);
                link.gameObject.SetActive(false);
                SetRaycastTarget(link, false);
                AddOutline(link, new Color(0.68f, 1f, 1f, 0.30f), new Vector2(1f, -1f));
                outpostEnergyLinks[i] = link;
            }

            for (int i = 0; i < outpostModuleStands.Length; i++)
            {
                RectTransform stand = CreateImage(parent, "OutpostModuleStand" + i, Color.white).rectTransform;
                stand.anchorMin = new Vector2(0.5f, 0.5f);
                stand.anchorMax = new Vector2(0.5f, 0.5f);
                stand.pivot = new Vector2(0.5f, 0.5f);
                stand.sizeDelta = ResolveBaseShipModuleStandSize(i) * 0.82f;
                stand.gameObject.SetActive(false);

                Image image = stand.GetComponent<Image>();
                if (image != null)
                {
                    image.sprite = GetSpriteFromTextureResource(ModuleSlotStandSpriteResourcePath);
                    image.type = Image.Type.Simple;
                    image.preserveAspect = true;
                    image.raycastTarget = false;
                    image.color = Color.white;
                }

                outpostModuleStands[i] = stand;
            }

            outpostHandle = CreatePanel(parent, "OutpostMoveHandle", new Color(0.020f, 0.145f, 0.165f, 0.92f));
            outpostHandle.anchorMin = new Vector2(0.5f, 0.5f);
            outpostHandle.anchorMax = new Vector2(0.5f, 0.5f);
            outpostHandle.pivot = new Vector2(0.5f, 0.5f);
            outpostHandle.sizeDelta = new Vector2(OutpostHandleWidth, OutpostHandleHeight);
            outpostHandle.gameObject.SetActive(false);
            AddOutline(outpostHandle, new Color(0.20f, 0.95f, 1f, 0.52f), new Vector2(1.5f, -1.5f));

            TextMeshProUGUI handleText = CreateText(outpostHandle, "Label", "OUTPOST", 16f, FontStyles.Bold, Cyan);
            handleText.rectTransform.anchorMin = Vector2.zero;
            handleText.rectTransform.anchorMax = Vector2.one;
            handleText.rectTransform.offsetMin = Vector2.zero;
            handleText.rectTransform.offsetMax = Vector2.zero;
            SetRaycastTarget(handleText.rectTransform, false);

            outpostLockButton = CreateButton(parent, "OutpostLockButton", "LOCK", new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(86f, OutpostHandleHeight), 15f, ToggleOutpostPositionLock);
            RectTransform lockRect = outpostLockButton.transform as RectTransform;
            if (lockRect != null)
                lockRect.gameObject.SetActive(false);
            outpostLockButtonText = outpostLockButton.GetComponentInChildren<TextMeshProUGUI>(true);
            if (outpostLockButtonText != null)
                outpostLockButtonText.alignment = TextAlignmentOptions.Center;
        }

        private void UpdateBaseShipHullLayout()
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null || baseShipHull == null)
                return;

            float width = Mathf.Max(BaseShipMinWidth, root.rect.width * BaseShipWidthScreenFraction);
            float height = width * BaseShipAspectRatio;
            baseShipHull.sizeDelta = new Vector2(width, height);
            float targetDeployment = ResolveBaseShipDeploymentTargetBlend();
            float response = targetDeployment > baseShipDeploymentBlend ? 4.4f : 3.8f;
            baseShipDeploymentBlend = Mathf.Lerp(baseShipDeploymentBlend, targetDeployment, 1f - Mathf.Exp(-response * Time.deltaTime));
            float yOffsetFraction = Mathf.Lerp(BaseShipParkedYOffsetFraction, BaseShipDefenderYOffsetFraction, Mathf.SmoothStep(0f, 1f, baseShipDeploymentBlend));
            baseShipHull.anchoredPosition = new Vector2(0f, -height * yOffsetFraction);
            bool tutorialHiddenBase = selectedMode == GameMode.Story && selectedStoryLevel == StoryLevel.Tutorial && !tutorialBaseRevealed && !menuHangarOpen;
            bool baseVisible = !tutorialHiddenBase && (state == GameState.Playing || transitioningToGame || menuHangarOpen);
            baseShipHull.gameObject.SetActive(baseVisible);
            UpdateBaseShipHealthBar(baseVisible);
            UpdateBaseShipSlotLayout();
            UpdateCoreForgeLayout(baseVisible);
            UpdateStorageDepotLayout(baseVisible);
            UpdateDroneUpgradePadLayout(baseVisible);

            Image image = baseShipHull.GetComponent<Image>();
            if (image == null)
                return;

            if (baseShipDamageFlashTimer > 0f)
            {
                baseShipDamageFlashTimer = Mathf.Max(0f, baseShipDamageFlashTimer - Time.deltaTime);
                float pulse = Mathf.Clamp01(baseShipDamageFlashTimer / HazardHitFeedbackSeconds);
                image.color = Color.Lerp(Color.white, new Color(1f, 0.42f, 0.32f, 1f), pulse * 0.55f);
            }
            else
            {
                image.color = Color.white;
            }
        }

        private void UpdateCoreForgeLayout(bool baseVisible)
        {
            if (coreForge == null || baseShipHull == null)
                return;

            bool visible = coreForgeOwned && baseVisible && (state == GameState.Playing || transitioningToGame || menuHangarOpen);
            coreForge.gameObject.SetActive(visible);
            if (!visible)
                return;

            coreForge.sizeDelta = new Vector2(CoreForgeSpriteSize, CoreForgeSpriteSize);
            float x = HasVisibleDroneUpgradePadAccess() ? -baseShipHull.sizeDelta.x * 0.13f : 0f;
            coreForge.anchoredPosition = new Vector2(x, baseShipHull.sizeDelta.y * 0.64f);
            float pulse = state == GameState.Playing ? 1f + Mathf.Sin(Time.time * 3.5f) * 0.025f : 1f;
            coreForge.localScale = Vector3.one * pulse;
            coreForge.localRotation = Quaternion.identity;
            coreForge.SetAsLastSibling();
        }

        private void UpdateStorageDepotLayout(bool baseVisible)
        {
            if (storageDepot == null || baseShipHull == null)
                return;

            bool visible = storageDepotOwned && baseVisible && (state == GameState.Playing || transitioningToGame || menuHangarOpen);
            storageDepot.gameObject.SetActive(visible);
            if (!visible)
                return;

            storageDepot.sizeDelta = new Vector2(StorageDepotSpriteSize, StorageDepotSpriteSize);
            float x = HasVisibleDroneUpgradePadAccess() ? -baseShipHull.sizeDelta.x * 0.13f : 0f;
            storageDepot.anchoredPosition = new Vector2(x, baseShipHull.sizeDelta.y * 0.705f);
            float pulse = state == GameState.Playing ? 1f + Mathf.Sin(Time.time * 2.8f) * 0.016f : 1f;
            storageDepot.localScale = Vector3.one * pulse;
            storageDepot.localRotation = Quaternion.identity;
            storageDepot.SetAsLastSibling();
        }

        private void UpdateDroneUpgradePadLayout(bool baseVisible)
        {
            if (droneUpgradePad == null || baseShipHull == null)
                return;

            bool visible = HasVisibleDroneUpgradePadAccess() && baseVisible && (state == GameState.Playing || transitioningToGame || menuHangarOpen);
            droneUpgradePad.gameObject.SetActive(visible);
            if (!visible)
                return;

            bool lowerOutpostPad = ShouldUseLowerOutpostPadLayout();
            float size = lowerOutpostPad ? DroneUpgradePadSpriteSize * 2.05f : DroneUpgradePadSpriteSize;
            droneUpgradePad.sizeDelta = new Vector2(size, size);
            droneUpgradePad.anchoredPosition = lowerOutpostPad
                ? ResolveMenuHangarDroneUpgradePadLocalPosition()
                : new Vector2(baseShipHull.sizeDelta.x * 0.13f, baseShipHull.sizeDelta.y * 0.55f);
            droneUpgradePad.localScale = Vector3.one;
            droneUpgradePad.localRotation = Quaternion.identity;
            droneUpgradePad.SetAsLastSibling();
        }

        private bool ShouldUseMenuHangarDroneUpgradePad()
        {
            return menuHangarOpen
                && state == GameState.Menu
                && !hangarRecoveryActive
                && !tutorialRepairHangarLessonActive
                && menuHangarProfileRoot != null
                && !menuHangarProfileRoot.gameObject.activeSelf;
        }

        private bool HasDroneUpgradePadAccess()
        {
            return droneUpgradePadOwned || testMode;
        }

        private bool HasVisibleDroneUpgradePadAccess()
        {
            return HasDroneUpgradePadAccess() && !IsIncompleteTutorialRun();
        }

        private bool ShouldUseLowerOutpostPadLayout()
        {
            return ShouldUseMenuHangarDroneUpgradePad()
                || (state == GameState.Playing
                    && !hangarRecoveryActive
                    && !tutorialRepairHangarLessonActive);
        }

        private Vector2 ResolveMenuHangarDroneUpgradePadLocalPosition()
        {
            if (baseShipHull == null)
                return Vector2.zero;

            return new Vector2(0f, baseShipHull.sizeDelta.y * 0.225f);
        }

        private void UpdateBaseShipHealthBar(bool baseVisible)
        {
            if (baseShipHealthFill == null || baseShipHealthRoot == null)
                return;

            bool layoutVisible = baseVisible && (state == GameState.Playing || transitioningToGame || menuHangarOpen);
            bool showHealth = layoutVisible && !menuHangarOpen && (state == GameState.Playing || transitioningToGame);
            baseShipHealthRoot.gameObject.SetActive(showHealth);
            if (!layoutVisible)
                return;

            if (baseShipHull != null)
            {
                float hullWidth = baseShipHull.rect.width > 1f ? baseShipHull.rect.width : baseShipHull.sizeDelta.x;
                float hullHeight = baseShipHull.rect.height > 1f ? baseShipHull.rect.height : baseShipHull.sizeDelta.y;
                float slotLineY = hullHeight * BaseShipSlotYFraction;
                baseShipHealthRoot.sizeDelta = new Vector2(Mathf.Clamp(hullWidth * 0.40f, 190f, 380f), Mathf.Clamp(hullHeight * 0.032f, 14f, 22f));
                baseShipHealthRoot.anchoredPosition = baseShipHull.anchoredPosition + new Vector2(0f, slotLineY - hullHeight * 0.080f);
                baseShipHealthRoot.SetAsLastSibling();
            }

            UpdateBaseTabButtonLayout(layoutVisible);

            if (!showHealth)
                return;

            float ratio = Mathf.Clamp01(baseShipHealth / (float)Mathf.Max(1, CurrentSharedMaxHealth()));
            SetCenteredBarFill(baseShipHealthFill, ratio);
            Image fillImage = baseShipHealthFill.GetComponent<Image>();
            if (fillImage != null)
            {
                Color low = new Color(1f, 0.16f, 0.10f, 0.94f);
                Color mid = new Color(1f, 0.78f, 0.18f, 0.94f);
                Color high = new Color(0.25f, 1f, 0.48f, 0.94f);
                Color color = ratio < 0.45f
                    ? Color.Lerp(low, mid, ratio / 0.45f)
                    : Color.Lerp(mid, high, (ratio - 0.45f) / 0.55f);
                if (ratio > 0f && ratio <= 0.25f)
                {
                    float pulse = 0.45f + Mathf.Abs(Mathf.Sin(Time.unscaledTime * 8.8f)) * 0.55f;
                    color = Color.Lerp(color, new Color(1f, 0.04f, 0.02f, 0.94f), 0.52f);
                    color.a = Mathf.Lerp(0.38f, 0.94f, pulse);
                }

                fillImage.color = color;
            }
        }

        private void UpdateBaseTabButtonLayout(bool baseVisible)
        {
            bool hasHealthAnchor = baseVisible && baseShipHealthRoot != null;
            if (!hasHealthAnchor)
                return;

            Vector2 healthSize = baseShipHealthRoot.sizeDelta;
            Vector2 buttonSize = new Vector2(
                Mathf.Clamp(healthSize.x * 0.46f, 136f, 174f),
                Mathf.Clamp(healthSize.y * 2.25f, 42f, 52f));
            float gap = Mathf.Clamp(healthSize.x * 0.040f, 12f, 20f);

            Button leftButton = menuHangarOpen ? menuHangarBackButton : baseTabButton;
            RectTransform baseRect = LayoutBaseSideButton(leftButton, healthSize, buttonSize, gap, -1f);
            LayoutBaseSideButton(topStationButton, healthSize, buttonSize, gap, 1f);

            if (baseTabHintRoot != null && baseRect != null)
            {
                baseTabHintRoot.anchorMin = baseRect.anchorMin;
                baseTabHintRoot.anchorMax = baseRect.anchorMax;
                baseTabHintRoot.pivot = new Vector2(0f, 0.5f);
                baseTabHintRoot.anchoredPosition = baseRect.anchoredPosition + new Vector2(buttonSize.x * 0.5f + 14f, 0f);
                baseTabHintRoot.SetAsLastSibling();
            }
        }

        private RectTransform LayoutBaseSideButton(Button button, Vector2 healthSize, Vector2 buttonSize, float gap, float side)
        {
            if (button == null)
                return null;

            RectTransform rect = button.transform as RectTransform;
            if (rect == null)
                return null;

            Vector2 healthCenter = ResolveBaseTabHealthAnchorPosition(rect);
            rect.anchorMin = new Vector2(0.5f, 0f);
            rect.anchorMax = new Vector2(0.5f, 0f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = buttonSize;
            rect.anchoredPosition = healthCenter + new Vector2(side * ((healthSize.x + buttonSize.x) * 0.5f + gap), 0f);
            rect.SetAsLastSibling();
            return rect;
        }

        private Vector2 ResolveBaseTabHealthAnchorPosition(RectTransform buttonRect)
        {
            if (baseShipHealthRoot == null)
                return Vector2.zero;

            RectTransform targetParent = buttonRect != null ? buttonRect.parent as RectTransform : null;
            RectTransform healthParent = baseShipHealthRoot.parent as RectTransform;
            if (targetParent == null || targetParent == healthParent)
                return baseShipHealthRoot.anchoredPosition;

            Vector2 parentLocal = targetParent.InverseTransformPoint(baseShipHealthRoot.TransformPoint(Vector3.zero));
            return new Vector2(parentLocal.x, parentLocal.y + targetParent.rect.height * 0.5f);
        }

        private float ResolveBaseShipDeploymentTargetBlend()
        {
            if (menuHangarOpen)
                return 1f;

            if (state != GameState.Playing && !transitioningToGame)
                return 0f;

            switch (orbDeploymentStage)
            {
                case OrbDeploymentStage.DockingToBase:
                case OrbDeploymentStage.Defender:
                    return outpostDefenderMode ? 0f : 1f;
                default:
                    return 0f;
            }
        }

        private void UpdateBaseShipSlotLayout()
        {
            bool tutorialHiddenBase = selectedMode == GameMode.Story && selectedStoryLevel == StoryLevel.Tutorial && !tutorialBaseRevealed && !menuHangarOpen;
            bool visible = !tutorialHiddenBase && !baseShipHullHasIntegratedSlots && (state == GameState.Playing || transitioningToGame || menuHangarOpen);
            for (int i = 0; i < baseShipSlotPlates.Length; i++)
            {
                RectTransform slot = baseShipSlotPlates[i];
                if (slot == null)
                    continue;

                slot.gameObject.SetActive(visible);
                slot.sizeDelta = ResolveBaseShipSlotPlateSize(i);
                slot.anchoredPosition = ResolveBaseShipSlotPosition(i);
                slot.localRotation = Quaternion.Euler(0f, 0f, (i - 2) * -2.5f);
                if (baseShipHull != null)
                    slot.SetSiblingIndex(baseShipHull.GetSiblingIndex() + 1 + i);

                Image image = slot.GetComponent<Image>();
                if (image != null)
                {
                    bool hot = IsOrbDockedOnBaseShip() && (i == 2 || IsBaseShipModuleSlotOccupied(i));
                    image.color = hot ? new Color(0.03f, 0.34f, 0.36f, 0.96f) : new Color(0.018f, 0.13f, 0.15f, 0.88f);
                }
            }

        }

        private Vector2 ResolveBaseShipSlotPlateSize(int slotIndex)
        {
            if (slotIndex == 2)
                return new Vector2(136f, 88f);

            return new Vector2(118f, 76f);
        }

        private bool IsBaseShipModuleSlotOccupied(int slotIndex)
        {
            switch (slotIndex)
            {
                case 0:
                    return IsHomingMissileModuleActive();
                case 1:
                    return IsLaserModuleActive();
                case 3:
                    return IsArcChainModuleActive();
                case 4:
                    return IsRailSpikeModuleActive();
                default:
                    return false;
            }
        }

        private Vector2 ResolveBaseShipSlotPosition(int slotIndex)
        {
            RectTransform world = WorldCoordinateRoot();
            if (world == null || baseShipHull == null)
                return new Vector2((slotIndex - 2) * 120f, -540f);

            float width = baseShipHull.sizeDelta.x;
            float height = baseShipHull.sizeDelta.y;
            float x = width * ResolveBaseShipSlotNormalizedX(slotIndex);
            float y = height * ResolveBaseShipSlotNormalizedY(slotIndex);
            return world.InverseTransformPoint(baseShipHull.TransformPoint(new Vector3(x, y, 0f)));
        }

        private static float ResolveBaseShipSlotNormalizedX(int slotIndex)
        {
            switch (Mathf.Clamp(slotIndex, 0, 4))
            {
                case 0:
                    return -0.380f;
                case 1:
                    return -0.201f;
                case 3:
                    return 0.201f;
                case 4:
                    return 0.380f;
                default:
                    return 0f;
            }
        }

        private static float ResolveBaseShipSlotNormalizedY(int slotIndex)
        {
            switch (Mathf.Clamp(slotIndex, 0, 4))
            {
                case 0:
                case 4:
                    return 0.910f;
                case 1:
                case 3:
                    return 0.916f;
                default:
                    return 0.929f;
            }
        }

        private Vector2 ResolveBaseShipDockPosition()
        {
            return ResolveBaseShipSlotPosition(2);
        }

        private void UpdateOutpostLayout()
        {
            if (playfield == null)
                return;

            outpostDamageFlashTimer = Mathf.Max(0f, outpostDamageFlashTimer - Time.deltaTime);
            bool visible = (outpostBuilt || outpostBuilding) && !IsIncompleteTutorialRun();
            if (targetOutpostY == 0f)
                targetOutpostY = ResolveDefaultOutpostY();
            bool shouldReturnHome = outpostBuilt && !outpostBuilding && !outpostDefenderMode && !outpostHandleDragging && !outpostPositionLocked;
            if (shouldReturnHome)
                targetOutpostY = ResolveDefaultOutpostY();
            targetOutpostY = ClampOutpostY(targetOutpostY);
            float outpostResponse = shouldReturnHome ? OutpostReturnResponse : 8.0f;
            outpostY = outpostY == 0f ? targetOutpostY : Mathf.Lerp(outpostY, targetOutpostY, 1f - Mathf.Exp(-outpostResponse * Time.deltaTime));
            SyncOrbWithMovingOutpost();

            for (int i = 0; i < outpostSlots.Length; i++)
            {
                RectTransform slot = outpostSlots[i];
                if (slot == null)
                    continue;

                bool slotVisible = visible;
                slot.gameObject.SetActive(slotVisible);
                if (!slotVisible)
                    continue;

                float buildScale = outpostBuilt ? 1f : Mathf.Lerp(0.45f, 1f, Mathf.Clamp01(outpostBuildProgress));
                slot.sizeDelta = ResolveOutpostSlotSize(i);
                slot.anchoredPosition = ResolveOutpostSlotPosition(i);
                slot.localScale = Vector3.one * buildScale;
                slot.localRotation = Quaternion.identity;
                if (i == 2)
                    slot.SetAsFirstSibling();
                else
                    slot.SetAsLastSibling();

                Image image = slot.GetComponent<Image>();
                if (image != null)
                {
                    bool hot = outpostBuilt && (i == 2 ? IsOrbDockedOnOutpost() : IsOutpostModuleSlotOccupied(i));
                    float alpha = outpostBuilt ? 1f : Mathf.Lerp(0.38f, 0.86f, Mathf.Clamp01(outpostBuildProgress));
                    float damagePulse = outpostDamageFlashTimer > 0f ? Mathf.Clamp01(outpostDamageFlashTimer / HazardHitFeedbackSeconds) : 0f;
                    Color normal = hot ? new Color(0.78f, 1f, 1f, alpha) : new Color(1f, 1f, 1f, alpha);
                    image.color = Color.Lerp(normal, new Color(1f, 0.30f, 0.18f, alpha), damagePulse * 0.62f);
                }
            }

            UpdateOutpostEnergyLinks(visible);

            if (outpostHandle != null)
            {
                bool handleVisible = visible && (IsOrbDockedOnOutpost() || outpostHandleDragging);
                outpostHandle.gameObject.SetActive(handleVisible);
                if (handleVisible)
                {
                    outpostHandle.anchoredPosition = ResolveOutpostHandlePosition();
                    outpostHandle.localScale = outpostHandleDragging ? Vector3.one * 1.08f : Vector3.one;
                    outpostHandle.SetAsLastSibling();
                }
            }

            UpdateOutpostLockButtonLayout();
        }

        private void UpdateOutpostLockButtonLayout()
        {
            if (outpostLockButton == null)
                return;

            RectTransform lockRect = outpostLockButton.transform as RectTransform;
            if (lockRect == null)
                return;

            bool visible = outpostBuilt && !IsIncompleteTutorialRun() && (IsOrbDockedOnOutpost() || outpostHandleDragging);
            lockRect.gameObject.SetActive(visible);
            if (!visible)
                return;

            lockRect.anchoredPosition = ResolveOutpostLockButtonPosition();
            lockRect.localScale = outpostPositionLocked ? Vector3.one * 1.06f : Vector3.one;
            lockRect.SetAsLastSibling();

            if (outpostLockButtonText != null)
            {
                outpostLockButtonText.text = outpostPositionLocked ? "LOCKED" : "LOCK";
                outpostLockButtonText.color = outpostPositionLocked ? Gold : Ink;
            }
        }

        private bool IsOutpostModuleSlotOccupied(int slotIndex)
        {
            switch (slotIndex)
            {
                case 0:
                    return IsHomingMissileModuleActive();
                case 1:
                    return IsLaserModuleActive();
                case 3:
                    return IsArcChainModuleActive();
                case 4:
                    return IsRailSpikeModuleActive();
                default:
                    return false;
            }
        }

        private Vector2 ResolveOutpostSlotPosition(int slotIndex)
        {
            return new Vector2((slotIndex - 2) * OutpostSlotSpacing, outpostY);
        }

        private Vector2 ResolveOutpostSlotSize(int slotIndex)
        {
            float size = slotIndex == 2 ? OutpostOrbSlotSize : OutpostTowerSize;
            return new Vector2(size, size);
        }

        private Vector2 ResolveOutpostDockPosition()
        {
            return ResolveOutpostSlotPosition(2) + new Vector2(0f, OutpostSlotMountYOffset);
        }

        private Vector2 ResolveOutpostModuleSlotPosition(int moduleIndex)
        {
            int slot = moduleIndex < 2 ? moduleIndex : moduleIndex + 1;
            return ResolveOutpostSlotPosition(slot) + ResolveOutpostModuleSlotOffset(moduleIndex);
        }

        private Vector2 ResolveOutpostModuleStandPosition(int moduleIndex)
        {
            return ResolveOutpostModuleSlotPosition(moduleIndex) + new Vector2(0f, -8f);
        }

        private static Vector2 ResolveOutpostModuleSlotOffset(int moduleIndex)
        {
            switch (moduleIndex)
            {
                case 0:
                    return new Vector2(6f, OutpostSlotMountYOffset);
                case 1:
                    return new Vector2(0f, OutpostSlotMountYOffset);
                case 2:
                    return new Vector2(0f, OutpostSlotMountYOffset);
                case 3:
                    return new Vector2(-6f, OutpostSlotMountYOffset);
                default:
                    return new Vector2(0f, OutpostSlotMountYOffset);
            }
        }

        private void UpdateOutpostEnergyLinks(bool outpostVisible)
        {
            bool visible = outpostVisible && outpostBuilt;
            for (int i = 0; i < outpostEnergyLinks.Length; i++)
            {
                RectTransform link = outpostEnergyLinks[i];
                if (link == null)
                    continue;

                link.gameObject.SetActive(visible);
                if (!visible)
                    continue;

                Vector2 from = ResolveOutpostSlotPosition(i);
                Vector2 to = ResolveOutpostSlotPosition(i + 1);
                Vector2 delta = to - from;
                float length = Mathf.Max(1f, delta.magnitude);
                Vector2 direction = delta / length;
                float pulse = 0.5f + Mathf.Sin(Time.time * 14f + i * 0.85f) * 0.5f;

                link.anchoredPosition = from;
                link.sizeDelta = new Vector2(Mathf.Lerp(3.2f, 6.2f, pulse), length);
                link.localRotation = Quaternion.Euler(0f, 0f, Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg - 90f);
                Image image = link.GetComponent<Image>();
                if (image != null)
                    image.color = Color.Lerp(new Color(0.08f, 0.72f, 1f, 0.34f), new Color(0.70f, 1f, 1f, 0.82f), pulse);
                link.SetAsFirstSibling();
            }
        }

        private void SyncOrbWithMovingOutpost()
        {
            if (!outpostDefenderMode || !outpostBuilt || state != GameState.Playing)
                return;

            Vector2 dock = ResolveOutpostDockPosition();
            targetLaneX = dock.x;
            targetOrbY = dock.y;

            if (orbDeploymentStage == OrbDeploymentStage.Defender)
            {
                laneX = dock.x;
                orbY = dock.y;
                if (orb != null)
                    orb.anchoredPosition = dock;
            }
        }

        private Vector2 ResolveOutpostHandlePosition()
        {
            return ResolveOutpostSlotPosition(2) - new Vector2(0f, OutpostOrbSlotSize * 0.5f + OutpostHandleHeight * 0.5f + OutpostHandleBelowCenterSlotPadding);
        }

        private Vector2 ResolveOutpostLockButtonPosition()
        {
            return ResolveOutpostHandlePosition() + new Vector2((OutpostHandleWidth + 92f) * 0.5f + 10f, 0f);
        }

        private void ToggleOutpostPositionLock()
        {
            if (!outpostBuilt)
                return;

            outpostPositionLocked = !outpostPositionLocked;
            if (outpostPositionLocked)
                targetOutpostY = outpostY;
            else if (!outpostDefenderMode && !outpostHandleDragging)
                targetOutpostY = ResolveDefaultOutpostY();

            if (statusText != null)
                statusText.text = outpostPositionLocked ? "OUTPOST LOCKED" : "OUTPOST UNLOCKED";
            UpdateOutpostLockButtonLayout();
        }

        private float ResolveDefaultOutpostY()
        {
            return ResolveBaseShipDockPosition().y + 290f;
        }

        private float ClampOutpostY(float y)
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return Mathf.Clamp(y, -120f, 520f);

            float min = ResolveDefaultOutpostY();
            float max = root.rect.height * 0.5f - 210f;
            if (max < min + 80f)
                max = min + 80f;
            return Mathf.Clamp(y, min, max);
        }

        private bool IsNearOutpostDockSlot(Vector2 point)
        {
            if (outpostDockReattachLockTimer > 0f)
                return false;

            return outpostBuilt && !IsIncompleteTutorialRun() && Vector2.Distance(point, ResolveOutpostDockPosition()) <= OutpostDockRadius;
        }

        private Vector2 ResolveActiveDefenseDockPosition()
        {
            return outpostDefenderMode && outpostBuilt ? ResolveOutpostDockPosition() : ResolveBaseShipDockPosition();
        }

        private Vector2 ResolveDockedModuleSlotPosition(int moduleIndex)
        {
            if (outpostDefenderMode && outpostBuilt)
                return ResolveOutpostModuleSlotPosition(moduleIndex);

            int slot = moduleIndex < 2 ? moduleIndex : moduleIndex + 1;
            return ResolveBaseShipSlotPosition(slot) + ResolveBaseShipModuleSlotOffset(moduleIndex);
        }

        private Vector2 ResolveDockedModuleStandPosition(int moduleIndex)
        {
            return ResolveDockedModuleSlotPosition(moduleIndex) + new Vector2(0f, BaseShipModuleStandYOffset);
        }

        private Vector2 ResolveDockedModuleStandLocalPosition(int moduleIndex)
        {
            if (baseShipHull == null)
                return Vector2.zero;

            int slot = moduleIndex < 2 ? moduleIndex : moduleIndex + 1;
            float width = baseShipHull.sizeDelta.x;
            float height = baseShipHull.sizeDelta.y;
            float x = width * ResolveBaseShipSlotNormalizedX(slot);
            float y = height * ResolveBaseShipSlotNormalizedY(slot) + BaseShipModuleStandYOffset;
            return new Vector2(x, y);
        }

        private bool IsOrbDockedOnBaseShip()
        {
            return state == GameState.Playing && orbDeploymentStage == OrbDeploymentStage.Defender && !outpostDefenderMode;
        }

        private bool IsOrbDockedOnOutpost()
        {
            return state == GameState.Playing && orbDeploymentStage == OrbDeploymentStage.Defender && outpostDefenderMode && outpostBuilt && !IsIncompleteTutorialRun();
        }

        private bool IsOrbHeldOnBaseShip()
        {
            return state == GameState.Playing && (orbDeploymentStage == OrbDeploymentStage.DockingToBase || orbDeploymentStage == OrbDeploymentStage.Defender || orbDeploymentStage == OrbDeploymentStage.LoadingToOrb);
        }

        private bool IsOrbBaseTransitionLocked()
        {
            return state == GameState.Playing && (orbDeploymentStage == OrbDeploymentStage.DockingToBase || orbDeploymentStage == OrbDeploymentStage.LoadingToOrb || orbDeploymentStage == OrbDeploymentStage.UndockingToHover);
        }

        private bool IsWeaponModuleBaseTargetState()
        {
            return menuHangarOpen || (state == GameState.Playing && (orbDeploymentStage == OrbDeploymentStage.DockingToBase || orbDeploymentStage == OrbDeploymentStage.Defender));
        }

        private bool IsWeaponModuleLoadingToOrb()
        {
            return state == GameState.Playing && orbDeploymentStage == OrbDeploymentStage.LoadingToOrb;
        }

        private bool IsNearBaseShipDockSlot(Vector2 point)
        {
            return Vector2.Distance(point, ResolveBaseShipDockPosition()) <= BaseShipDockRadius;
        }

        private void SetOrbDeploymentStage(OrbDeploymentStage stage)
        {
            orbDeploymentStage = stage;
        }

        private void EnterOrbDefenderMode()
        {
            if (state != GameState.Playing)
                return;

            outpostDefenderMode = false;
            SetOrbDeploymentStage(OrbDeploymentStage.DockingToBase);
            Vector2 dock = ResolveBaseShipDockPosition();
            targetLaneX = dock.x;
            targetOrbY = dock.y;
            pointerControl = false;
            pointerStartedOnOrbControl = false;
            outpostOrbUndockedThisGesture = false;
            outpostOrbLaunchPending = false;
            if (orb != null)
                orb.localRotation = Quaternion.identity;

            UpdateStationModules();
            if (statusText != null)
                statusText.text = "UNLOADING WEAPONS";
        }

        private void EnterOutpostDefenderMode()
        {
            if (state != GameState.Playing || !outpostBuilt)
                return;

            outpostDefenderMode = true;
            SetOrbDeploymentStage(OrbDeploymentStage.DockingToBase);
            Vector2 dock = ResolveOutpostDockPosition();
            targetLaneX = dock.x;
            targetOrbY = dock.y;
            pointerControl = false;
            pointerStartedOnOrbControl = false;
            outpostOrbUndockedThisGesture = false;
            outpostOrbLaunchPending = false;
            if (orb != null)
                orb.localRotation = Quaternion.identity;

            UpdateStationModules();
            if (statusText != null)
                statusText.text = L("status.outpost_unloading");
        }

        private void ExitOrbDefenderMode()
        {
            bool exitingOutpost = IsOrbDockedOnOutpost();
            if (!IsOrbDockedOnBaseShip() && !IsOrbDockedOnOutpost())
            {
                if (!IsOrbBaseTransitionLocked())
                    SetOrbDeploymentStage(OrbDeploymentStage.Flight);
                return;
            }

            SetOrbDeploymentStage(OrbDeploymentStage.LoadingToOrb);
            Vector2 dock = ResolveActiveDefenseDockPosition();
            targetLaneX = dock.x;
            targetOrbY = dock.y;
            pointerControl = false;
            pointerStartedOnOrbControl = false;
            outpostOrbUndockedThisGesture = exitingOutpost;
            outpostOrbLaunchPending = false;
            UpdateStationModules();
            if (statusText != null)
                statusText.text = "LOADING WEAPONS";
        }

        private void StartOutpostOrbPointerUndock(Vector2 localPoint, Vector2 limits)
        {
            if (!IsOrbDockedOnOutpost())
                return;

            Vector2 dock = ResolveOutpostDockPosition();
            Vector2 launchDirection = localPoint.y >= dock.y ? Vector2.up : Vector2.down;

            Vector2 launchTarget = dock + launchDirection * OutpostOrbLaunchDistance;
            launchTarget.x = Mathf.Clamp(launchTarget.x, -limits.x, limits.x);
            launchTarget.y = Mathf.Clamp(launchTarget.y, -limits.y, limits.y);

            outpostOrbUndockedThisGesture = true;
            outpostOrbLaunchPending = true;
            outpostOrbLaunchTarget = launchTarget;
            outpostDockReattachLockTimer = OutpostDockReattachLockSeconds;
            SetOrbDeploymentStage(OrbDeploymentStage.LoadingToOrb);
            targetLaneX = dock.x;
            targetOrbY = dock.y;
            pointerControl = false;
            pointerStartedOnOrbControl = false;
            UpdateStationModules();
            if (statusText != null)
                statusText.text = "LOADING WEAPONS";
        }

        private void RefreshFreeOrbDeploymentStage()
        {
            if (IsOrbDockedOnBaseShip() || IsOrbDockedOnOutpost() || IsOrbBaseTransitionLocked())
                return;

            if (pointerControl)
            {
                SetOrbDeploymentStage(OrbDeploymentStage.Flight);
                return;
            }

            float baseY = ResolveGameOrbY();
            bool atHoverPoint = Mathf.Abs(laneX) <= 42f && Mathf.Abs(orbY - baseY) <= 46f && Mathf.Abs(targetLaneX) <= 8f && Mathf.Abs(targetOrbY - baseY) <= 8f;
            SetOrbDeploymentStage(atHoverPoint ? OrbDeploymentStage.BaseHover : OrbDeploymentStage.Flight);
        }

        private Vector2 ResolveBaseShipModuleSize(int moduleIndex)
        {
            switch (moduleIndex)
            {
                case 0:
                    return new Vector2(94f, 118f);
                case 1:
                    return new Vector2(96f, 116f);
                case 2:
                    return new Vector2(102f, 108f);
                case 3:
                    return new Vector2(100f, 118f);
                default:
                    return new Vector2(96f, 114f);
            }
        }

        private static Vector2 ResolveBaseShipModuleSlotOffset(int moduleIndex)
        {
            return new Vector2(0f, BaseShipModuleMountYOffset);
        }

        private Vector2 ResolveBaseShipModuleStandSize(int moduleIndex)
        {
            switch (moduleIndex)
            {
                case 0:
                case 3:
                    return new Vector2(154f, 154f);
                case 1:
                case 2:
                    return new Vector2(148f, 148f);
                default:
                    return new Vector2(150f, 150f);
            }
        }

        private static Vector2 ResolveBaseShipModulePivot(int moduleIndex)
        {
            return ResolveOrbModulePivot(moduleIndex);
        }

        private static Vector2 ResolveOrbModulePivot(int moduleIndex)
        {
            switch (moduleIndex)
            {
                case 2:
                    return new Vector2(0.5f, 0.14f);
                default:
                    return new Vector2(0.5f, 0.18f);
            }
        }

        private Vector2 ResolveOrbModuleLocalPosition(int moduleIndex)
        {
            switch (moduleIndex)
            {
                case 0:
                    return new Vector2(0f, 34f);
                case 1:
                    return new Vector2(0f, -34f);
                case 2:
                    return new Vector2(38f, 0f);
                case 3:
                    return new Vector2(-38f, 0f);
                default:
                    return Vector2.zero;
            }
        }

        private Vector2 ResolveOrbModuleSize(int moduleIndex)
        {
            switch (moduleIndex)
            {
                case 0:
                    return new Vector2(28f, 42f);
                case 1:
                    return new Vector2(29f, 42f);
                case 2:
                    return new Vector2(37f, 46f);
                case 3:
                    return new Vector2(36f, 46f);
                default:
                    return new Vector2(32f, 44f);
            }
        }

        private float ResolveOrbModuleParkedZ(int moduleIndex)
        {
            switch (moduleIndex)
            {
                case 1:
                    return 180f;
                case 2:
                    return -90f;
                case 3:
                    return 90f;
                default:
                    return 0f;
            }
        }

        private Vector2 ResolveOrbModuleCanvasPosition(int moduleIndex)
        {
            RectTransform world = WorldCoordinateRoot();
            if (world == null || orb == null)
                return new Vector2(laneX, orbY) + ResolveOrbModuleLocalPosition(moduleIndex);

            return world.InverseTransformPoint(orb.TransformPoint(ResolveOrbModuleLocalPosition(moduleIndex)));
        }

