        private void UpdateStoryDialogLayout()
        {
            if (storyDialogRoot == null || canvas == null)
                return;

            RectTransform root = canvas.transform as RectTransform;
            if (root == null)
                return;

            float canvasWidth = Mathf.Max(1f, root.rect.width);
            float canvasHeight = Mathf.Max(1f, root.rect.height);
            bool narrow = canvasWidth < canvasHeight * 0.82f;

            float sideMargin = narrow ? Mathf.Clamp(canvasWidth * 0.035f, 18f, 34f) : Mathf.Clamp(canvasWidth * 0.075f, 44f, 120f);
            float topMargin = narrow ? Mathf.Clamp(canvasHeight * 0.035f, 28f, 58f) : Mathf.Clamp(canvasHeight * 0.060f, 44f, 86f);
            float bottomMargin = narrow ? Mathf.Clamp(canvasHeight * 0.105f, 88f, 150f) : Mathf.Clamp(canvasHeight * 0.070f, 52f, 96f);
            float panelWidth = Mathf.Max(320f, canvasWidth - sideMargin * 2f);
            float panelHeight = narrow ? Mathf.Max(520f, canvasHeight - topMargin - bottomMargin) : Mathf.Clamp(canvasHeight * 0.74f, 500f, 820f);
            if (!narrow)
                panelWidth = Mathf.Clamp(panelWidth, 760f, 1160f);
            float centerY = (bottomMargin - topMargin) * 0.5f;

            SetCenteredRect(storyDialogRoot, new Vector2(panelWidth, panelHeight), new Vector2(0f, centerY));

            float portraitWidth = narrow ? panelWidth * 0.385f : panelHeight * 0.275f;
            portraitWidth *= storyDialogPlayerSpeakerActive ? 1.06f : 1.04f;
            portraitWidth = Mathf.Clamp(portraitWidth, narrow ? 238f : 168f, narrow ? 366f : 248f);
            Vector2 portraitSize = storyDialogPlayerSpeakerActive
                ? new Vector2(portraitWidth, portraitWidth)
                : new Vector2(portraitWidth, portraitWidth * 1.08f);
            Vector2 portraitPos = narrow ? new Vector2(0f, panelHeight * 0.352f) : new Vector2(0f, panelHeight * 0.322f);
            SetCenteredRect(storyDialogPortraitFrame, portraitSize, portraitPos);

            if (storyDialogPortrait != null)
            {
                Stretch(storyDialogPortrait.rectTransform);
                float inset = storyDialogPlayerSpeakerActive
                    ? Mathf.Max(8f, portraitWidth * 0.105f)
                    : Mathf.Max(3f, portraitWidth * 0.030f);
                storyDialogPortrait.rectTransform.offsetMin = new Vector2(inset, inset);
                storyDialogPortrait.rectTransform.offsetMax = new Vector2(-inset, -inset);
            }
            if (storyDialogPortraitFrameOverlay != null)
            {
                Stretch(storyDialogPortraitFrameOverlay);
                storyDialogPortraitFrameOverlay.offsetMin = Vector2.zero;
                storyDialogPortraitFrameOverlay.offsetMax = Vector2.zero;
                storyDialogPortraitFrameOverlay.SetAsLastSibling();
            }

            Vector2 nameplateSize = new Vector2(Mathf.Clamp(panelWidth * 0.640f, narrow ? 455f : 360f, narrow ? 610f : 560f), Mathf.Clamp(panelHeight * 0.082f, narrow ? 82f : 50f, narrow ? 116f : 78f));
            Vector2 nameplatePos = new Vector2(0f, portraitPos.y - portraitSize.y * 0.5f - nameplateSize.y * 0.46f + (narrow ? 4f : 3f));
            SetCenteredRect(storyDialogSpeakerPlate, nameplateSize, nameplatePos);

            if (storyDialogSpeakerText != null)
            {
                SetCenteredRect(storyDialogSpeakerText.rectTransform, new Vector2(nameplateSize.x * 0.82f, nameplateSize.y * 0.74f), nameplatePos + new Vector2(0f, 1f));
                storyDialogSpeakerText.fontSizeMax = narrow ? 52f : 32f;
                storyDialogSpeakerText.fontSizeMin = narrow ? 34f : 21f;
            }

            Vector2 bodySize = new Vector2(panelWidth * (narrow ? 0.865f : 0.720f), panelHeight * (narrow ? 0.555f : 0.490f));
            Vector2 bodyPos = narrow ? new Vector2(0f, -panelHeight * 0.083f) : new Vector2(0f, -panelHeight * 0.100f);
            SetCenteredRect(storyDialogBodyPanel, bodySize, bodyPos);

            if (storyDialogBodyText != null)
            {
                SetCenteredRect(storyDialogBodyText.rectTransform, bodySize - new Vector2(104f, 112f), bodyPos + new Vector2(0f, -2f));
                storyDialogBodyText.fontSizeMax = narrow ? 72f : 46f;
                storyDialogBodyText.fontSizeMin = narrow ? 34f : 24f;
                storyDialogBodyText.alignment = TextAlignmentOptions.Center;
            }

            Vector2 buttonSize = new Vector2(Mathf.Clamp(panelWidth * 0.760f, narrow ? 470f : 320f, narrow ? 675f : 540f), Mathf.Clamp(panelHeight * 0.110f, narrow ? 112f : 58f, narrow ? 164f : 92f));
            SetCenteredRect(storyDialogButton != null ? storyDialogButton.transform as RectTransform : null, buttonSize, new Vector2(0f, -panelHeight * 0.405f));

            if (storyDialogButtonText != null)
            {
                storyDialogButtonText.fontSizeMax = narrow ? 50f : 28f;
                storyDialogButtonText.fontSizeMin = narrow ? 32f : 19f;
            }
        }

        private static void SetCenteredRect(RectTransform rect, Vector2 size, Vector2 position)
        {
            if (rect == null)
                return;

            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = size;
            rect.anchoredPosition = position;
            rect.localScale = Vector3.one;
        }

        private void BuildMenu(RectTransform root)
        {
            menuRoot = CreatePanel(root, "MenuRoot", Color.clear);
            Stretch(menuRoot);
            SetRaycastTarget(menuRoot, false);
            if (gameLogoRoot != null)
                gameLogoRoot.SetParent(menuRoot, false);
            if (gameTitleRoot != null)
                gameTitleRoot.SetParent(menuRoot, false);

            upgradeButtonRoot = CreateButton(menuRoot, "UpgradeButton", K("menu.technology"), new Vector2(0.070f, 0.735f), new Vector2(0.440f, 0.800f), Vector2.zero, Vector2.zero, 28f, ShowUpgrade).transform as RectTransform;
            Button ozCoreMinerSendButton = CreateButton(menuRoot, "OzCoreMinerSendButton", string.Empty, new Vector2(0.30f, 0.470f), new Vector2(0.70f, 0.530f), Vector2.zero, Vector2.zero, 21f, SendOzCoreMiner);
            ozCoreMinerSendButtonRoot = ozCoreMinerSendButton.transform as RectTransform;
            ozCoreMinerSendText = ozCoreMinerSendButton.GetComponentInChildren<TextMeshProUGUI>(true);
