        private void BuildModeSelectBlock(RectTransform parent, string name, string titleKey, string bodyKey, string subtitleKey, float yMin, float yMax, Color bodyColor, Color accentColor, bool interactive, UnityEngine.Events.UnityAction action)
        {
            GameObject go = new GameObject(name, typeof(RectTransform), typeof(CanvasRenderer), typeof(Image));
            go.transform.SetParent(parent, false);
            RectTransform rect = go.GetComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.070f, yMin);
            rect.anchorMax = new Vector2(0.930f, yMax);
            rect.offsetMin = Vector2.zero;
            rect.offsetMax = Vector2.zero;
            rect.localScale = Vector3.one;

            Image image = go.GetComponent<Image>();
            image.color = bodyColor;
            image.raycastTarget = interactive;
            if (ApplyUiSpriteFromTextureResource(rect, TechPanelSpriteResourcePath, false, interactive))
            {
                image.color = interactive ? Color.white : new Color(0.55f, 0.58f, 0.60f, 0.86f);
            }
            else
            {
                AddOutline(rect, accentColor, new Vector2(2f, -2f));
            }

            RectTransform tint = CreatePanel(rect, "Tint", bodyColor);
            tint.anchorMin = new Vector2(0.055f, 0.145f);
            tint.anchorMax = new Vector2(0.945f, 0.855f);
            tint.offsetMin = Vector2.zero;
            tint.offsetMax = Vector2.zero;
            SetRaycastTarget(tint, false);

            RectTransform topRail = CreatePanel(rect, "TopRail", accentColor);
            topRail.anchorMin = new Vector2(0.220f, 0.820f);
            topRail.anchorMax = new Vector2(0.780f, 0.838f);
            topRail.offsetMin = Vector2.zero;
            topRail.offsetMax = Vector2.zero;
            SetRaycastTarget(topRail, false);

            RectTransform bottomRail = CreatePanel(rect, "BottomRail", accentColor);
            bottomRail.anchorMin = new Vector2(0.260f, 0.160f);
            bottomRail.anchorMax = new Vector2(0.740f, 0.178f);
            bottomRail.offsetMin = Vector2.zero;
            bottomRail.offsetMax = Vector2.zero;
            SetRaycastTarget(bottomRail, false);

            Color titleColor = interactive ? Ink : new Color(0.70f, 0.74f, 0.76f, 1f);
            TextMeshProUGUI title = CreateText(rect, "Title", titleKey, 36f, FontStyles.Bold, titleColor);
            title.alignment = TextAlignmentOptions.Center;
            title.textWrappingMode = TextWrappingModes.Normal;
            title.rectTransform.anchorMin = new Vector2(0.095f, 0.565f);
            title.rectTransform.anchorMax = new Vector2(0.905f, 0.790f);
            title.rectTransform.offsetMin = Vector2.zero;
            title.rectTransform.offsetMax = Vector2.zero;

            if (!string.IsNullOrEmpty(bodyKey))
            {
                TextMeshProUGUI body = CreateText(rect, "Body", bodyKey, 21f, FontStyles.Bold, interactive ? MutedInk : new Color(0.58f, 0.62f, 0.64f, 1f));
                body.alignment = TextAlignmentOptions.Center;
                body.textWrappingMode = TextWrappingModes.Normal;
                body.rectTransform.anchorMin = new Vector2(0.110f, 0.330f);
                body.rectTransform.anchorMax = new Vector2(0.890f, 0.545f);
                body.rectTransform.offsetMin = Vector2.zero;
                body.rectTransform.offsetMax = Vector2.zero;
            }

            if (!string.IsNullOrEmpty(subtitleKey))
            {
                TextMeshProUGUI subtitle = CreateText(rect, "Subtitle", subtitleKey, 22f, FontStyles.Bold, interactive ? Gold : new Color(0.62f, 0.66f, 0.68f, 1f));
                subtitle.alignment = TextAlignmentOptions.Center;
                subtitle.rectTransform.anchorMin = new Vector2(0.110f, 0.205f);
                subtitle.rectTransform.anchorMax = new Vector2(0.890f, 0.305f);
                subtitle.rectTransform.offsetMin = Vector2.zero;
                subtitle.rectTransform.offsetMax = Vector2.zero;
            }

            if (interactive && action != null)
            {
                Button button = go.AddComponent<Button>();
                ColorBlock colors = button.colors;
                colors.normalColor = Color.white;
                colors.highlightedColor = new Color(0.86f, 0.96f, 1f, 1f);
                colors.pressedColor = new Color(0.66f, 0.82f, 0.92f, 1f);
                colors.colorMultiplier = 1f;
                button.colors = colors;
                button.targetGraphic = image;
                button.onClick.AddListener(PlayButtonClick);
                button.onClick.AddListener(action);
            }
        }

