        private static void ApplyTutorialIntroButtonTextStyle(Button button)
        {
            if (button == null)
                return;

            TextMeshProUGUI label = button.GetComponentInChildren<TextMeshProUGUI>(true);
            if (label == null)
                return;

            MahjongGame.LocalizedTextStyle.Apply(label);
            label.fontStyle = FontStyles.Bold;
        }

        private void BuildMenuHangarUpgradeButtons(RectTransform parent)
        {
            for (int i = 0; i < menuHangarUpgradeButtons.Length; i++)
            {
                int captured = i;
                Button button = CreateButton(parent, "HangarUpgradeButton" + i, K("hangar.upgrade"), new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(132f, 42f), 16f, () => ShowMenuHangarProfile(captured));
                button.gameObject.SetActive(false);
                menuHangarUpgradeButtons[i] = button;
            }
        }

