            hangarRecoveryOrbBarRoot.sizeDelta = new Vector2(86f, 22f);
            hangarRecoveryOrbBarRoot.anchoredPosition = new Vector2(0f, 54f);

            hangarRecoveryBarFill = CreateCenterBar(hangarRecoveryOrbBarRoot, "HangarRecoveryOrbBar", new Vector2(0f, 0.18f), new Vector2(1f, 0.58f), new Color(0.006f, 0.040f, 0.045f, 0.82f), new Color(0.22f, 1f, 0.86f, 0.92f));
