        private RectTransform CreateMenuHangarDoor(Transform parent, string name, bool mirrored)
        {
            RectTransform door = CreateImage(parent, name, Color.white).rectTransform;
            Image image = door.GetComponent<Image>();
            if (image != null)
            {
                image.sprite = GetSpriteFromTextureResource(MenuHangarDoorSpriteResourcePath);
                image.type = Image.Type.Simple;
                image.preserveAspect = false;
                image.raycastTarget = false;
            }

            door.anchorMin = new Vector2(0.5f, 0.5f);
            door.anchorMax = new Vector2(0.5f, 0.5f);
            door.pivot = new Vector2(0.5f, 0.5f);
            door.localScale = mirrored ? new Vector3(-1f, 1f, 1f) : Vector3.one;
            return door;
        }

