            RectTransform card = CreatePanel(stationControlRoot, "StationControlCard", new Color(0.018f, 0.046f, 0.068f, 0.98f));
            card.anchorMin = new Vector2(0.035f, 0.055f);
            card.anchorMax = new Vector2(0.965f, 0.945f);
            card.offsetMin = Vector2.zero;
            card.offsetMax = Vector2.zero;
            AddOutline(card, new Color(0.16f, 0.78f, 0.92f, 0.34f), new Vector2(1.2f, -1.2f));

            TextMeshProUGUI title = CreateText(card, "Title", K("station.title"), 34f, FontStyles.Bold, Ink);
            stationControlTitleRoot = title.rectTransform;
            title.alignment = TextAlignmentOptions.Center;

            stationControlBackButtonRoot = CreateButton(card, "CloseStationControl", K("common.back"), new Vector2(0.360f, 0.020f), new Vector2(0.640f, 0.090f), Vector2.zero, Vector2.zero, 19f, CloseStationControl).transform as RectTransform;

            stationControlOrbTabButton = CreateStationControlTabButton(card, "OrbTab", K("station.tab.orb"), new Vector2(0.070f, 0.835f), new Vector2(0.285f, 0.900f), ShowStationControlOrbTab);
            stationControlBaseTabButton = CreateStationControlTabButton(card, "BaseTab", K("station.tab.base"), new Vector2(0.295f, 0.835f), new Vector2(0.510f, 0.900f), ShowStationControlBaseTab);
            stationControlDronesTabButton = CreateStationControlTabButton(card, "DronesTab", K("station.tab.drones"), new Vector2(0.520f, 0.835f), new Vector2(0.735f, 0.900f), ShowStationControlDronesTab);
            stationControlModulesTabButton = CreateStationControlTabButton(card, "ModulesTab", K("station.tab.modules"), new Vector2(0.745f, 0.835f), new Vector2(0.930f, 0.900f), ShowStationControlModulesTab);

            TextMeshProUGUI header = CreateText(card, "Header", K("station.header"), 24f, FontStyles.Bold, Cyan);
            stationControlHeaderText = header;
            stationControlHeaderRoot = header.rectTransform;
            header.alignment = TextAlignmentOptions.Left;

            stationControlOrbPage = CreateStationControlPage(card, "OrbPage");
            stationControlBasePage = CreateStationControlPage(card, "BasePage");
            stationControlDronesPage = CreateStationControlPage(card, "DronesPage");
            stationControlModulesPage = CreateStationControlPage(card, "ModulesPage");
            stationControlDetailPage = CreateStationControlPage(card, "DetailPage");

            BuildStationCardCatalog();

            RefreshStationControlLabels();
            ShowStationControlTab(currentStationControlTab);
            LayoutStationControlTop();
            stationControlRoot.gameObject.SetActive(false);
        }

        private void LayoutStationControlTop()
        {
            LayoutRect(stationControlTitleRoot, new Vector2(0.080f, 0.955f), new Vector2(0.920f, 0.998f));
            LayoutRect(stationControlHeaderRoot, new Vector2(0.070f, 0.815f), new Vector2(0.930f, 0.855f));
            LayoutButtonRect(stationControlOrbTabButton, new Vector2(0.070f, 0.875f), new Vector2(0.285f, 0.940f));
            LayoutButtonRect(stationControlBaseTabButton, new Vector2(0.295f, 0.875f), new Vector2(0.510f, 0.940f));
            LayoutButtonRect(stationControlDronesTabButton, new Vector2(0.520f, 0.875f), new Vector2(0.735f, 0.940f));
            LayoutButtonRect(stationControlModulesTabButton, new Vector2(0.745f, 0.875f), new Vector2(0.930f, 0.940f));
            LayoutRect(stationControlOrbPage, new Vector2(0.070f, 0.105f), new Vector2(0.930f, 0.795f));
            LayoutRect(stationControlBasePage, new Vector2(0.070f, 0.105f), new Vector2(0.930f, 0.795f));
            LayoutRect(stationControlDronesPage, new Vector2(0.070f, 0.105f), new Vector2(0.930f, 0.795f));
            LayoutRect(stationControlModulesPage, new Vector2(0.070f, 0.105f), new Vector2(0.930f, 0.795f));
            LayoutRect(stationControlDetailPage, new Vector2(0.070f, 0.105f), new Vector2(0.930f, 0.795f));
        }

        private static void LayoutButtonRect(Button button, Vector2 anchorMin, Vector2 anchorMax)
        {
            if (button == null)
                return;

            LayoutRect(button.transform as RectTransform, anchorMin, anchorMax);
        }

        private static void LayoutRect(RectTransform rect, Vector2 anchorMin, Vector2 anchorMax)
        {
            if (rect == null)
                return;

            rect.anchorMin = anchorMin;
            rect.anchorMax = anchorMax;
            rect.offsetMin = Vector2.zero;
            rect.offsetMax = Vector2.zero;
            rect.anchoredPosition = Vector2.zero;
            rect.localScale = Vector3.one;
        }

        private void LayoutStationControlBackButton()
        {
            if (stationControlBackButtonRoot == null)
                return;

            stationControlBackButtonRoot.anchorMin = new Vector2(0.360f, 0.020f);
            stationControlBackButtonRoot.anchorMax = new Vector2(0.640f, 0.090f);
            stationControlBackButtonRoot.pivot = new Vector2(0.5f, 0.5f);
            stationControlBackButtonRoot.offsetMin = Vector2.zero;
            stationControlBackButtonRoot.offsetMax = Vector2.zero;
            stationControlBackButtonRoot.anchoredPosition = Vector2.zero;
            stationControlBackButtonRoot.localScale = Vector3.one;
            stationControlBackButtonRoot.SetAsLastSibling();
        }

