        private void CreateStationTaskRow(RectTransform parent, int index, string label, float yMax)
        {
            RectTransform row = CreatePanel(parent, "TaskRow" + index, new Color(0.008f, 0.075f, 0.102f, 0.76f));
            row.anchorMin = new Vector2(0f, yMax - 0.095f);
            row.anchorMax = new Vector2(1f, yMax);
            row.offsetMin = Vector2.zero;
            row.offsetMax = Vector2.zero;
            AddOutline(row, new Color(0.16f, 0.78f, 0.92f, 0.32f), new Vector2(1f, -1f));

            TextMeshProUGUI nameText = CreateText(row, "Name", label, 18f, FontStyles.Bold, Ink);
            nameText.alignment = TextAlignmentOptions.Left;
            nameText.rectTransform.anchorMin = new Vector2(0.04f, 0f);
            nameText.rectTransform.anchorMax = new Vector2(0.70f, 1f);
            nameText.rectTransform.offsetMin = Vector2.zero;
            nameText.rectTransform.offsetMax = Vector2.zero;

            int capturedIndex = index;
            Button priorityButton = CreateButton(row, "Priority", string.Empty, new Vector2(0.735f, 0.12f), new Vector2(0.975f, 0.88f), Vector2.zero, Vector2.zero, 18f, () => CycleStationTaskPriority(capturedIndex));
            stationTaskPriorityTexts[index] = priorityButton.GetComponentInChildren<TextMeshProUGUI>(true);
        }

        private void BuildStationCardCatalog()
        {
            RectTransform orbContent = CreateStationCardContent(stationControlOrbPage, "OrbCards", 2);
            CreateStationAssetCard(orbContent, 0, K("upgrade.station"), CurrentOrbStationSpriteResourcePath(), K("station.select"), () => ShowStationPriorityDetail(K("upgrade.station"), CurrentOrbStationSpriteResourcePath(), new StationPriorityOption(4, K("station.task.repair_orb")), new StationPriorityOption(6, K("station.task.generator_orb"))));
            CreateStationAssetCard(orbContent, 1, K("upgrade.core_cannon"), CoreCannonSpriteResourcePath, K("station.select"), () => ShowStationPriorityDetail(K("upgrade.core_cannon"), CoreCannonSpriteResourcePath, new StationPriorityOption(8, K("station.task.shield_base"))));

            int baseCount = 1 + (coreForgeOwned ? 1 : 0) + (storageDepotOwned ? 1 : 0) + (droneUpgradePadOwned ? 2 : 0);
            RectTransform baseContent = CreateStationCardContent(stationControlBasePage, "BaseCards", baseCount);
            int baseIndex = 0;
            CreateStationAssetCard(baseContent, baseIndex++, K("upgrade.base"), BaseShipHullSpriteResourcePath, K("station.select"), () => ShowStationPriorityDetail(K("upgrade.base"), BaseShipHullSpriteResourcePath));
            if (coreForgeOwned)
                CreateStationAssetCard(baseContent, baseIndex++, K("upgrade.core_forge"), CoreForgeSpriteResourcePath, K("station.select"), () => ShowStationPriorityDetail(K("upgrade.core_forge"), CoreForgeSpriteResourcePath));
            if (storageDepotOwned)
                CreateStationAssetCard(baseContent, baseIndex++, K("upgrade.storage_depot"), StorageDepotSpriteResourcePath, K("station.select"), () => ShowStationPriorityDetail(K("upgrade.storage_depot"), StorageDepotSpriteResourcePath));
            if (droneUpgradePadOwned)
            {
                CreateStationAssetCard(baseContent, baseIndex++, K("upgrade.drone_pad"), DroneUpgradePadSpriteResourcePath, K("station.select"), () => ShowStationPriorityDetail(K("upgrade.drone_pad"), DroneUpgradePadSpriteResourcePath));
                CreateStationAssetCard(baseContent, baseIndex++, K("upgrade.outpost_pad"), OutpostTowerSpriteResourcePath, K("station.select"), () => ShowStationPriorityDetail(K("upgrade.outpost_pad"), OutpostTowerSpriteResourcePath));
            }

            int droneCount = CountOwnedStationDrones();
            if (droneCount <= 0)
            {
                CreateStationEmptyMessage(stationControlDronesPage);
            }
            else
            {
                RectTransform droneContent = CreateStationCardContent(stationControlDronesPage, "DroneCards", droneCount);
                int droneIndex = 0;
                if (crafterOwned)
                    CreateStationAssetCard(droneContent, droneIndex++, K("upgrade.crafter"), CrafterDroneSpriteResourcePath, K("station.select"), () => ShowStationPriorityDetail(K("upgrade.crafter"), CrafterDroneSpriteResourcePath, new StationPriorityOption(0, K("station.task.crafter_repair")), new StationPriorityOption(1, K("station.task.crafter_generator")), new StationPriorityOption(2, K("station.task.crafter_shield")), new StationPriorityOption(3, K("station.task.crafter_collector"))));
                if (generatorOwned)
                    CreateStationAssetCard(droneContent, droneIndex++, K("upgrade.generator"), GeneratorDroneSpriteResourcePath, K("station.select"), () => ShowStationPriorityDetail(K("upgrade.generator"), GeneratorDroneSpriteResourcePath, new StationPriorityOption(6, K("station.task.generator_orb")), new StationPriorityOption(7, K("station.task.generator_drones"))));
                if (repairOwned)
                    CreateStationAssetCard(droneContent, droneIndex++, K("upgrade.repair"), RepairDroneSpriteResourcePath, K("station.select"), () => ShowStationPriorityDetail(K("upgrade.repair"), RepairDroneSpriteResourcePath, new StationPriorityOption(4, K("station.task.repair_orb")), new StationPriorityOption(5, K("station.task.repair_drones"))));
                if (shieldDroneOwned)
                    CreateStationAssetCard(droneContent, droneIndex++, K("upgrade.shield"), ShieldDroneSpriteResourcePath, K("station.select"), () => ShowStationPriorityDetail(K("upgrade.shield"), ShieldDroneSpriteResourcePath, new StationPriorityOption(8, K("station.task.shield_base"))));
                if (collectorDroneOwned)
                    CreateStationAssetCard(droneContent, droneIndex++, K("upgrade.collector"), CollectorDroneSpriteResourcePath, K("station.select"), () => ShowStationPriorityDetail(K("upgrade.collector"), CollectorDroneSpriteResourcePath));
                if (mineLayerDroneOwned)
                    CreateStationAssetCard(droneContent, droneIndex++, K("upgrade.mine_layer"), MineLayerDroneSpriteResourcePath, K("station.select"), () => ShowStationPriorityDetail(K("upgrade.mine_layer"), MineLayerDroneSpriteResourcePath));
                if (ozCoreMinerOwned)
                    CreateStationAssetCard(droneContent, droneIndex++, K("upgrade.core_miner"), OzCoreMinerDroneSpriteResourcePath, K("station.select"), () => ShowStationPriorityDetail(K("upgrade.core_miner"), OzCoreMinerDroneSpriteResourcePath));
                if (hiveDroneOwned)
                    CreateStationAssetCard(droneContent, droneIndex++, K("upgrade.hive"), HiveDroneSpriteResourcePath, K("station.select"), () => ShowStationPriorityDetail(K("upgrade.hive"), HiveDroneSpriteResourcePath));
                if (gladiatorDroneOwned)
                    CreateStationAssetCard(droneContent, droneIndex++, K("upgrade.gladiator"), GladiatorDroneSpriteResourcePath, K("station.select"), () => ShowStationPriorityDetail(K("upgrade.gladiator"), GladiatorDroneSpriteResourcePath));
                if (horizonDroneOwned)
                    CreateStationAssetCard(droneContent, droneIndex++, K("upgrade.horizon"), HorizonDroneSpriteResourcePath, K("station.select"), () => ShowStationPriorityDetail(K("upgrade.horizon"), HorizonDroneSpriteResourcePath));
                if (tamerDroneOwned)
                    CreateStationAssetCard(droneContent, droneIndex++, K("upgrade.tamer"), TamerDroneSpriteResourcePath, K("station.select"), () => ShowStationPriorityDetail(K("upgrade.tamer"), TamerDroneSpriteResourcePath));
                if (queenDroneOwned)
                    CreateStationAssetCard(droneContent, droneIndex++, K("upgrade.queen"), QueenDroneSpriteResourcePath, K("station.select"), () => ShowStationPriorityDetail(K("upgrade.queen"), QueenDroneSpriteResourcePath));
                if (mimicDroneOwned)
                    CreateStationAssetCard(droneContent, droneIndex++, K("upgrade.mimic"), MimicDroneSpriteResourcePath, K("station.select"), () => ShowStationPriorityDetail(K("upgrade.mimic"), MimicDroneSpriteResourcePath));
                if (sniperDroneOwned)
                    CreateStationAssetCard(droneContent, droneIndex++, K("upgrade.sniper"), SniperDroneSpriteResourcePath, K("station.select"), () => ShowStationPriorityDetail(K("upgrade.sniper"), SniperDroneSpriteResourcePath));
            }

            int moduleCount = CountOwnedStationModules();
            RectTransform moduleContent = CreateStationCardContent(stationControlModulesPage, "ModuleCards", moduleCount);
            int moduleIndex = 0;
            CreateStationModuleToggleCard(moduleContent, moduleIndex++, K("upgrade.core_cannon"), CoreCannonSpriteResourcePath, IsCoreCannonActive, SetCoreCannonActive);
            if (homingMissileModuleOwned)
                CreateStationModuleToggleCard(moduleContent, moduleIndex++, K("upgrade.missile"), HomingMissileModuleSpriteResourcePath, IsHomingMissileModuleActive, SetHomingMissileModuleActive);
            if (laserModuleOwned)
                CreateStationModuleToggleCard(moduleContent, moduleIndex++, K("upgrade.laser"), LaserModuleSpriteResourcePath, IsLaserModuleActive, SetLaserModuleActive);
            if (arcChainModuleOwned)
                CreateStationModuleToggleCard(moduleContent, moduleIndex++, K("upgrade.arc"), ArcChainModuleSpriteResourcePath, IsArcChainModuleActive, SetArcChainModuleActive);
            if (railSpikeModuleOwned)
                CreateStationModuleToggleCard(moduleContent, moduleIndex++, K("upgrade.rail"), RailSpikeModuleSpriteResourcePath, IsRailSpikeModuleActive, SetRailSpikeModuleActive);
        }

        private void RebuildStationCardCatalog()
        {
            ClearStationCatalogPage(stationControlOrbPage);
            ClearStationCatalogPage(stationControlBasePage);
            ClearStationCatalogPage(stationControlDronesPage);
            ClearStationCatalogPage(stationControlModulesPage);
            BuildStationCardCatalog();
        }

        private void ClearStationCatalogPage(RectTransform page)
        {
            if (page == null)
                return;

            for (int i = page.childCount - 1; i >= 0; i--)
                Destroy(page.GetChild(i).gameObject);
        }

        private int CountOwnedStationDrones()
        {
            int count = 0;
            if (crafterOwned) count++;
            if (generatorOwned) count++;
            if (repairOwned) count++;
            if (shieldDroneOwned) count++;
            if (collectorDroneOwned) count++;
            if (mineLayerDroneOwned) count++;
            if (ozCoreMinerOwned) count++;
            if (hiveDroneOwned) count++;
            if (gladiatorDroneOwned) count++;
            if (horizonDroneOwned) count++;
            if (tamerDroneOwned) count++;
            if (queenDroneOwned) count++;
            if (mimicDroneOwned) count++;
            if (sniperDroneOwned) count++;
            return count;
        }

        private int CountOwnedStationModules()
        {
            int count = 1;
            if (homingMissileModuleOwned) count++;
            if (laserModuleOwned) count++;
            if (arcChainModuleOwned) count++;
            if (railSpikeModuleOwned) count++;
            return count;
        }

        private void CreateStationEmptyMessage(RectTransform parent)
        {
            TextMeshProUGUI empty = CreateText(parent, "Empty", K("station.no_unlocked"), 22f, FontStyles.Bold, MutedInk);
            empty.alignment = TextAlignmentOptions.Center;
            empty.textWrappingMode = TextWrappingModes.Normal;
            Stretch(empty.rectTransform);
        }

        private RectTransform CreateStationCardContent(RectTransform parent, string name, int itemCount)
        {
            RectTransform scrollRoot = CreatePanel(parent, name + "Scroll", new Color(0f, 0f, 0f, 0f));
            Stretch(scrollRoot);

            ScrollRect scroll = scrollRoot.gameObject.AddComponent<ScrollRect>();
            scroll.horizontal = false;
            scroll.vertical = true;
            scroll.movementType = ScrollRect.MovementType.Clamped;
            scroll.inertia = true;

            RectTransform viewport = CreatePanel(scrollRoot, name + "Viewport", new Color(0f, 0f, 0f, 0f));
            Stretch(viewport);
            viewport.gameObject.AddComponent<RectMask2D>();

            RectTransform content = CreatePanel(viewport, name + "Content", new Color(0f, 0f, 0f, 0f));
            content.anchorMin = new Vector2(0f, 1f);
            content.anchorMax = new Vector2(1f, 1f);
            content.pivot = new Vector2(0.5f, 1f);
            content.offsetMin = new Vector2(0f, 0f);
            content.offsetMax = new Vector2(0f, 0f);
            content.sizeDelta = new Vector2(0f, Mathf.Max(1f, itemCount) * 94f);

            scroll.viewport = viewport;
            scroll.content = content;
            return content;
        }

        private void CreateStationAssetCard(RectTransform content, int index, string label, string spritePath, string buttonLabel, UnityEngine.Events.UnityAction action)
        {
            float top = index * 94f;
            RectTransform card = CreatePanel(content, "StationCard" + index, new Color(0.008f, 0.075f, 0.102f, 0.80f));
            card.anchorMin = new Vector2(0f, 1f);
            card.anchorMax = new Vector2(1f, 1f);
            card.pivot = new Vector2(0.5f, 1f);
            card.offsetMin = new Vector2(0f, -top - 84f);
            card.offsetMax = new Vector2(0f, -top);
            AddOutline(card, new Color(0.16f, 0.78f, 0.92f, 0.32f), new Vector2(1f, -1f));

            RectTransform portrait = CreateImage(card, "Portrait", Color.white).rectTransform;
            portrait.anchorMin = new Vector2(0.030f, 0.125f);
            portrait.anchorMax = new Vector2(0.210f, 0.875f);
            portrait.offsetMin = Vector2.zero;
            portrait.offsetMax = Vector2.zero;
            ApplyStationCardSprite(portrait, spritePath);

            TextMeshProUGUI nameText = CreateText(card, "Name", label, 20f, FontStyles.Bold, Ink);
            nameText.alignment = TextAlignmentOptions.Left;
            nameText.textWrappingMode = TextWrappingModes.Normal;
            nameText.rectTransform.anchorMin = new Vector2(0.245f, 0.08f);
            nameText.rectTransform.anchorMax = new Vector2(0.660f, 0.92f);
            nameText.rectTransform.offsetMin = Vector2.zero;
            nameText.rectTransform.offsetMax = Vector2.zero;

            CreateButton(card, "Select", buttonLabel, new Vector2(0.690f, 0.180f), new Vector2(0.970f, 0.820f), Vector2.zero, Vector2.zero, 17f, action);
        }

        private void CreateStationModuleToggleCard(RectTransform content, int index, string label, string spritePath, Func<bool> isActive, Action<bool> setActive)
        {
            float top = index * 94f;
            RectTransform card = CreatePanel(content, "ModuleCard" + index, new Color(0.008f, 0.075f, 0.102f, 0.80f));
            card.anchorMin = new Vector2(0f, 1f);
            card.anchorMax = new Vector2(1f, 1f);
            card.pivot = new Vector2(0.5f, 1f);
            card.offsetMin = new Vector2(0f, -top - 84f);
            card.offsetMax = new Vector2(0f, -top);
            AddOutline(card, new Color(0.16f, 0.78f, 0.92f, 0.32f), new Vector2(1f, -1f));

            RectTransform portrait = CreateImage(card, "Portrait", Color.white).rectTransform;
            portrait.anchorMin = new Vector2(0.030f, 0.125f);
            portrait.anchorMax = new Vector2(0.210f, 0.875f);
            portrait.offsetMin = Vector2.zero;
            portrait.offsetMax = Vector2.zero;
            ApplyStationCardSprite(portrait, spritePath);

            TextMeshProUGUI nameText = CreateText(card, "Name", label, 20f, FontStyles.Bold, Ink);
            nameText.alignment = TextAlignmentOptions.Left;
            nameText.textWrappingMode = TextWrappingModes.Normal;
            nameText.rectTransform.anchorMin = new Vector2(0.245f, 0.08f);
            nameText.rectTransform.anchorMax = new Vector2(0.610f, 0.92f);
            nameText.rectTransform.offsetMin = Vector2.zero;
            nameText.rectTransform.offsetMax = Vector2.zero;

            Button toggleButton = CreateButton(card, "ActiveToggle", string.Empty, new Vector2(0.630f, 0.180f), new Vector2(0.970f, 0.820f), Vector2.zero, Vector2.zero, 16f, () => { });
            TextMeshProUGUI toggleText = toggleButton.GetComponentInChildren<TextMeshProUGUI>(true);
            void RefreshToggle()
            {
                bool active = isActive != null && isActive();
                if (toggleText != null)
                {
                    toggleText.text = (active ? "[X] " : "[ ] ") + L("station.active");
                    toggleText.color = active ? Gold : MutedInk;
                }
            }

            toggleButton.onClick.AddListener(() =>
            {
                bool next = !(isActive != null && isActive());
                setActive?.Invoke(next);
                RefreshToggle();
            });
            RefreshToggle();
        }

        private void ApplyStationCardSprite(RectTransform portrait, string spritePath)
        {
            Image image = portrait != null ? portrait.GetComponent<Image>() : null;
            if (image == null)
                return;

            Sprite sprite = GetSpriteFromTextureResource(spritePath);
            if (sprite == null)
            {
                image.color = new Color(0.06f, 0.28f, 0.34f, 0.92f);
                return;
            }

            image.sprite = sprite;
            image.color = Color.white;
            image.preserveAspect = true;
            image.raycastTarget = false;
        }

        private void ShowStationPriorityDetail(string title, string spritePath, params StationPriorityOption[] options)
        {
            if (stationControlDetailPage == null)
                return;

            for (int i = stationControlDetailPage.childCount - 1; i >= 0; i--)
                Destroy(stationControlDetailPage.GetChild(i).gameObject);

            ShowStationCatalogPages(false);
            stationControlDetailPage.gameObject.SetActive(true);
            SetStationControlHeader(title);
            SetStationCloseButtonVisible(false);

            RectTransform portrait = CreateImage(stationControlDetailPage, "SelectedPortrait", Color.white).rectTransform;
            portrait.anchorMin = new Vector2(0.030f, 0.760f);
            portrait.anchorMax = new Vector2(0.230f, 0.985f);
            portrait.offsetMin = Vector2.zero;
            portrait.offsetMax = Vector2.zero;
            ApplyStationCardSprite(portrait, spritePath);

            TextMeshProUGUI nameText = CreateText(stationControlDetailPage, "SelectedName", title, 28f, FontStyles.Bold, Ink);
            nameText.alignment = TextAlignmentOptions.Left;
            nameText.textWrappingMode = TextWrappingModes.Normal;
            nameText.rectTransform.anchorMin = new Vector2(0.270f, 0.785f);
            nameText.rectTransform.anchorMax = new Vector2(0.970f, 0.965f);
            nameText.rectTransform.offsetMin = Vector2.zero;
            nameText.rectTransform.offsetMax = Vector2.zero;

            if (options == null || options.Length == 0)
            {
                TextMeshProUGUI empty = CreateText(stationControlDetailPage, "NoPriorities", K("station.no_priorities"), 22f, FontStyles.Bold, MutedInk);
                empty.alignment = TextAlignmentOptions.Center;
                empty.textWrappingMode = TextWrappingModes.Normal;
                empty.rectTransform.anchorMin = new Vector2(0.040f, 0.400f);
                empty.rectTransform.anchorMax = new Vector2(0.960f, 0.620f);
                empty.rectTransform.offsetMin = Vector2.zero;
                empty.rectTransform.offsetMax = Vector2.zero;
            }
            else
            {
                for (int i = 0; i < options.Length; i++)
                {
                    float yMax = 0.690f - i * 0.135f;
                    CreateStationTaskRow(stationControlDetailPage, options[i].Index, options[i].Label, yMax);
                }
            }

            CreateButton(stationControlDetailPage, "BackToCatalog", K("station.back_to_cards"), new Vector2(0.270f, 0.015f), new Vector2(0.730f, 0.090f), Vector2.zero, Vector2.zero, 18f, BackToStationCatalog);
            RefreshStationControlLabels();
        }

