        private void SetCoreCannonActive(bool active)
        {
            coreCannonActive = active;
            PlayerPrefs.SetInt(CoreCannonActiveKey, coreCannonActive ? 1 : 0);
            PlayerPrefs.Save();
            UpdateStationModules();
        }

