        private readonly struct StationPriorityOption
        {
            public readonly int Index;
            public readonly string Label;

            public StationPriorityOption(int index, string label)
            {
                Index = index;
                Label = label;
            }
        }

        private void BackToStationCatalog()
        {
            SetStationControlHeader(string.Empty);
            if (stationControlDetailPage != null)
                stationControlDetailPage.gameObject.SetActive(false);
            SetStationCloseButtonVisible(true);

            ShowStationCatalogPages(true);
            ShowStationControlTab(currentStationControlTab);
        }

        private void SetStationControlHeader(string value)
        {
            if (stationControlHeaderText == null)
                return;

            stationControlHeaderText.text = !string.IsNullOrEmpty(value) && value.StartsWith(LocalizationPrefix, StringComparison.Ordinal)
                ? GameLocalization.Text(value)
                : value;
        }

        private void SetStationCloseButtonVisible(bool visible)
        {
            if (stationControlBackButtonRoot != null)
                stationControlBackButtonRoot.gameObject.SetActive(visible);
        }

        private void ShowStationCatalogPages(bool visible)
        {
            if (stationControlOrbPage != null)
                stationControlOrbPage.gameObject.SetActive(visible && currentStationControlTab == UpgradeTab.Station);
            if (stationControlBasePage != null)
                stationControlBasePage.gameObject.SetActive(visible && currentStationControlTab == UpgradeTab.Base);
            if (stationControlDronesPage != null)
                stationControlDronesPage.gameObject.SetActive(visible && currentStationControlTab == UpgradeTab.Drones);
            if (stationControlModulesPage != null)
                stationControlModulesPage.gameObject.SetActive(visible && currentStationControlTab == UpgradeTab.Modules);
        }

        private void BuildUpgrade(RectTransform root)
        {
            upgradeRoot = CreatePanel(root, "UpgradeRoot", new Color(0.002f, 0.013f, 0.018f, 0.98f));
            Stretch(upgradeRoot);

            RectTransform card = CreatePanel(upgradeRoot, "UpgradeCard", new Color(0.004f, 0.026f, 0.034f, 0.985f));
            card.anchorMin = new Vector2(0.000f, 0.000f);
            card.anchorMax = new Vector2(1.000f, 1.000f);
            card.offsetMin = Vector2.zero;
            card.offsetMax = Vector2.zero;

            RectTransform ambientTop = CreatePanel(card, "AmbientTopGlow", new Color(0.020f, 0.135f, 0.155f, 0.34f));
            ambientTop.anchorMin = new Vector2(0f, 0.740f);
            ambientTop.anchorMax = new Vector2(1f, 0.880f);
            ambientTop.offsetMin = Vector2.zero;
            ambientTop.offsetMax = Vector2.zero;
            SetRaycastTarget(ambientTop, false);

            RectTransform ambientBottom = CreatePanel(card, "AmbientBottomGlow", new Color(0.010f, 0.105f, 0.125f, 0.28f));
            ambientBottom.anchorMin = new Vector2(0f, 0.000f);
            ambientBottom.anchorMax = new Vector2(1f, 0.130f);
            ambientBottom.offsetMin = Vector2.zero;
            ambientBottom.offsetMax = Vector2.zero;
            SetRaycastTarget(ambientBottom, false);

            RectTransform headerBar = CreatePanel(card, "HeaderBar", new Color(0.003f, 0.020f, 0.027f, 0.98f));
            headerBar.anchorMin = new Vector2(0.000f, 0.880f);
            headerBar.anchorMax = new Vector2(1.000f, 1.000f);
            headerBar.offsetMin = Vector2.zero;
            headerBar.offsetMax = Vector2.zero;
            SetRaycastTarget(headerBar, false);

            RectTransform headerLine = CreatePanel(card, "HeaderLine", new Color(0.12f, 0.82f, 0.92f, 0.24f));
            headerLine.anchorMin = new Vector2(0f, 0.880f);
            headerLine.anchorMax = new Vector2(1f, 0.883f);
            headerLine.offsetMin = Vector2.zero;
            headerLine.offsetMax = Vector2.zero;
            SetRaycastTarget(headerLine, false);

            TextMeshProUGUI title = CreateTechText(card, "Title", K("upgrade.title"), 44f, FontStyles.Bold, Ink);
            title.alignment = TextAlignmentOptions.Left;
            title.fontSizeMin = 34f;
            title.rectTransform.anchorMin = new Vector2(0.050f, 0.905f);
            title.rectTransform.anchorMax = new Vector2(0.540f, 0.975f);
