        private RectTransform CreateUpgradeSection(RectTransform parent, string name, string titleText, Vector2 anchorMin, Vector2 anchorMax)
        {
            RectTransform section = CreatePanel(parent, name, new Color(0.010f, 0.085f, 0.098f, 0.94f));
            section.anchorMin = anchorMin;
            section.anchorMax = anchorMax;
            section.offsetMin = Vector2.zero;
            section.offsetMax = Vector2.zero;
            AddOutline(section, new Color(0.18f, 0.90f, 1f, 0.24f), new Vector2(1f, -1f));

            RectTransform upperGlow = CreatePanel(section, "UpperGlow", new Color(0.045f, 0.205f, 0.230f, 0.46f));
            upperGlow.anchorMin = new Vector2(0f, 0.700f);
            upperGlow.anchorMax = new Vector2(1f, 1f);
            upperGlow.offsetMin = Vector2.zero;
            upperGlow.offsetMax = Vector2.zero;
            SetRaycastTarget(upperGlow, false);

            RectTransform lowerShade = CreatePanel(section, "LowerShade", new Color(0.002f, 0.018f, 0.026f, 0.36f));
            lowerShade.anchorMin = new Vector2(0f, 0f);
            lowerShade.anchorMax = new Vector2(1f, 0.260f);
            lowerShade.offsetMin = Vector2.zero;
            lowerShade.offsetMax = Vector2.zero;
            SetRaycastTarget(lowerShade, false);

            return section;
        }

