        private TextMeshProUGUI CreateBaseEquipmentUpgradeCard(RectTransform parent, string name, string titleText, string spriteResourcePath, string bodyText, Vector2 anchorMin, Vector2 anchorMax, UnityEngine.Events.UnityAction action)
        {
            Image panelImage = CreateImage(parent, name, new Color(0.018f, 0.095f, 0.120f, 0.88f));
            RectTransform panel = panelImage.rectTransform;
            panel.anchorMin = anchorMin;
            panel.anchorMax = anchorMax;
            panel.offsetMin = Vector2.zero;
            panel.offsetMax = Vector2.zero;
            AddOutline(panel, new Color(0.16f, 0.78f, 0.92f, 0.36f), new Vector2(2f, -2f));
            panelImage.raycastTarget = true;

            Button cardButton = panel.gameObject.AddComponent<Button>();
            ColorBlock colors = cardButton.colors;
            colors.normalColor = Color.white;
            colors.highlightedColor = new Color(0.82f, 0.98f, 1f, 1f);
            colors.pressedColor = new Color(0.60f, 0.78f, 0.90f, 1f);
            colors.colorMultiplier = 1f;
            cardButton.colors = colors;
            cardButton.targetGraphic = panelImage;
            cardButton.onClick.AddListener(PlayButtonClick);
            cardButton.onClick.AddListener(action);

            RectTransform portrait = CreateImage(panel, "Portrait", Color.white).rectTransform;
            portrait.anchorMin = new Vector2(0.055f, 0.30f);
            portrait.anchorMax = new Vector2(0.350f, 0.82f);
            portrait.offsetMin = Vector2.zero;
            portrait.offsetMax = Vector2.zero;
            ApplySpriteFromTextureResource(portrait, spriteResourcePath);
            SetRaycastTarget(portrait, false);

            TextMeshProUGUI title = CreateText(panel, "Title", titleText, 21f, FontStyles.Bold, Cyan);
            title.alignment = TextAlignmentOptions.Left;
            title.textWrappingMode = TextWrappingModes.Normal;
            title.rectTransform.anchorMin = new Vector2(0.38f, 0.70f);
            title.rectTransform.anchorMax = new Vector2(0.94f, 0.91f);
            title.rectTransform.offsetMin = Vector2.zero;
            title.rectTransform.offsetMax = Vector2.zero;
            title.raycastTarget = false;

            TextMeshProUGUI body = CreateText(panel, "Body", bodyText, 14f, FontStyles.Bold, MutedInk);
            body.alignment = TextAlignmentOptions.Left;
            body.textWrappingMode = TextWrappingModes.Normal;
            body.rectTransform.anchorMin = new Vector2(0.38f, 0.42f);
            body.rectTransform.anchorMax = new Vector2(0.94f, 0.68f);
            body.rectTransform.offsetMin = Vector2.zero;
            body.rectTransform.offsetMax = Vector2.zero;
            body.raycastTarget = false;

            Button button = CreateTechnologyButton(panel, "Buy" + name, string.Empty, new Vector2(0.38f, 0.13f), new Vector2(0.94f, 0.34f), 15f, action);
            return button.GetComponentInChildren<TextMeshProUGUI>(true);
        }

