        private void ShowStationUpgradeTab()
        {
            ShowUpgradeTab(UpgradeTab.Station);
        }

        private void ShowBaseUpgradeTab()
        {
            UpdateBaseUpgradePage();
            ShowUpgradeTab(UpgradeTab.Base);
        }

        private void ShowDronesUpgradeTab()
        {
            UpdateDroneUpgradePage();
            ShowUpgradeTab(UpgradeTab.Drones);
        }

        private void ShowModulesUpgradeTab()
        {
            UpdateModuleUpgradePage();
            ShowUpgradeTab(UpgradeTab.Modules);
        }

        private void ShowStationControlOrbTab()
        {
            ShowStationControlTab(UpgradeTab.Station);
        }

        private void ShowStationControlBaseTab()
        {
            ShowStationControlTab(UpgradeTab.Base);
        }

        private void ShowStationControlDronesTab()
        {
            ShowStationControlTab(UpgradeTab.Drones);
        }

        private void ShowStationControlModulesTab()
        {
