        }

        private void ShowStationControlTab(UpgradeTab tab)
        {
            currentStationControlTab = tab;
            if (stationControlDetailPage != null)
                stationControlDetailPage.gameObject.SetActive(false);
            SetStationControlHeader(string.Empty);
            SetStationCloseButtonVisible(true);

            if (stationControlOrbPage != null)
                stationControlOrbPage.gameObject.SetActive(tab == UpgradeTab.Station);
            if (stationControlBasePage != null)
                stationControlBasePage.gameObject.SetActive(tab == UpgradeTab.Base);
            if (stationControlDronesPage != null)
                stationControlDronesPage.gameObject.SetActive(tab == UpgradeTab.Drones);
            if (stationControlModulesPage != null)
                stationControlModulesPage.gameObject.SetActive(tab == UpgradeTab.Modules);

            SetUpgradeTabVisual(stationControlOrbTabButton, tab == UpgradeTab.Station);
            SetUpgradeTabVisual(stationControlBaseTabButton, tab == UpgradeTab.Base);
            SetUpgradeTabVisual(stationControlDronesTabButton, tab == UpgradeTab.Drones);
            SetUpgradeTabVisual(stationControlModulesTabButton, tab == UpgradeTab.Modules);
        }

        private void ShowUpgradeTab(UpgradeTab tab)
        {
            if (!CanOpenUpgradeTabDuringTutorial(tab))
            {
                UpgradeTab forcedTab = GetForcedTutorialUpgradeTab();
                if (forcedTab != tab && statusText != null)
                    statusText.text = "FOLLOW CURRENT TUTORIAL STEP";
                tab = forcedTab;
            }

            currentUpgradeTab = tab;
            if (upgradeStationPage != null)
                upgradeStationPage.gameObject.SetActive(tab == UpgradeTab.Station);
            if (upgradeBasePage != null)
                upgradeBasePage.gameObject.SetActive(tab == UpgradeTab.Base);
            if (upgradeDronesPage != null)
                upgradeDronesPage.gameObject.SetActive(tab == UpgradeTab.Drones);
            if (upgradeModulesPage != null)
                upgradeModulesPage.gameObject.SetActive(tab == UpgradeTab.Modules);

            SetUpgradeTabVisual(upgradeStationTabButton, tab == UpgradeTab.Station);
            SetUpgradeTabVisual(upgradeBaseTabButton, tab == UpgradeTab.Base);
            SetUpgradeTabVisual(upgradeDronesTabButton, tab == UpgradeTab.Drones);
            SetUpgradeTabVisual(upgradeModulesTabButton, tab == UpgradeTab.Modules);
            if (tab == UpgradeTab.Base)
                UpdateBaseUpgradePage();
            if (tab == UpgradeTab.Drones)
                UpdateDroneUpgradePage();
            if (tab == UpgradeTab.Modules)
                UpdateModuleUpgradePage();
        }

        private void ChangeBaseUpgradePage(int delta)
        {
            const int cardsPerPage = 1;
            int pageCount = Mathf.Max(1, Mathf.CeilToInt(baseUpgradeCards.Length / (float)cardsPerPage));
            baseUpgradePage = (baseUpgradePage + delta + pageCount) % pageCount;
            UpdateBaseUpgradePage();
        }

        private void UpdateBaseUpgradePage()
        {
            const int cardsPerPage = 1;
            int pageCount = Mathf.Max(1, Mathf.CeilToInt(baseUpgradeCards.Length / (float)cardsPerPage));
            baseUpgradePage = Mathf.Clamp(baseUpgradePage, 0, pageCount - 1);
            int firstIndex = baseUpgradePage * cardsPerPage;

            for (int i = 0; i < baseUpgradeCards.Length; i++)
            {
                if (baseUpgradeCards[i] != null)
                {
                    baseUpgradeCards[i].anchorMin = new Vector2(0.030f, 0.135f);
                    baseUpgradeCards[i].anchorMax = new Vector2(0.970f, 0.935f);
                    baseUpgradeCards[i].offsetMin = Vector2.zero;
                    baseUpgradeCards[i].offsetMax = Vector2.zero;
                    baseUpgradeCards[i].gameObject.SetActive(i >= firstIndex && i < firstIndex + cardsPerPage);
                }
            }

            if (baseUpgradePageText != null)
                baseUpgradePageText.text = LF("common.page", baseUpgradePage + 1, pageCount);
            if (baseUpgradePrevButton != null)
                baseUpgradePrevButton.gameObject.SetActive(pageCount > 1);
            if (baseUpgradeNextButton != null)
                baseUpgradeNextButton.gameObject.SetActive(pageCount > 1);
        }

        private void ChangeDroneUpgradePage(int delta)
        {
            const int cardsPerPage = 1;
            int pageCount = Mathf.Max(1, Mathf.CeilToInt(droneUpgradeCards.Length / (float)cardsPerPage));
            droneUpgradePage = (droneUpgradePage + delta + pageCount) % pageCount;
            UpdateDroneUpgradePage();
        }

        private void UpdateDroneUpgradePage()
        {
            if (tutorialRepairTechnologyLessonActive || tutorialShieldTechnologyLessonActive)
            {
                int focusedIndex = tutorialShieldTechnologyLessonActive ? 3 : 2;
                for (int i = 0; i < droneUpgradeCards.Length; i++)
                {
                    if (droneUpgradeCards[i] != null)
                    {
                        if (i == focusedIndex)
                        {
                            droneUpgradeCards[i].anchorMin = new Vector2(0.030f, 0.135f);
                            droneUpgradeCards[i].anchorMax = new Vector2(0.970f, 0.935f);
                            droneUpgradeCards[i].offsetMin = Vector2.zero;
                            droneUpgradeCards[i].offsetMax = Vector2.zero;
                        }
                        droneUpgradeCards[i].gameObject.SetActive(i == focusedIndex);
                    }
                }

                if (droneUpgradePageText != null)
                    droneUpgradePageText.text = tutorialShieldTechnologyLessonActive ? L("upgrade.shield") : L("upgrade.repair");
                if (droneUpgradePrevButton != null)
                    droneUpgradePrevButton.gameObject.SetActive(false);
                if (droneUpgradeNextButton != null)
                    droneUpgradeNextButton.gameObject.SetActive(false);
                return;
            }

            const int cardsPerPage = 1;
            int pageCount = Mathf.Max(1, Mathf.CeilToInt(droneUpgradeCards.Length / (float)cardsPerPage));
            droneUpgradePage = Mathf.Clamp(droneUpgradePage, 0, pageCount - 1);
            int firstIndex = droneUpgradePage * cardsPerPage;

            for (int i = 0; i < droneUpgradeCards.Length; i++)
            {
                if (droneUpgradeCards[i] != null)
                {
                    droneUpgradeCards[i].anchorMin = new Vector2(0.030f, 0.135f);
                    droneUpgradeCards[i].anchorMax = new Vector2(0.970f, 0.935f);
                    droneUpgradeCards[i].offsetMin = Vector2.zero;
                    droneUpgradeCards[i].offsetMax = Vector2.zero;
                    droneUpgradeCards[i].gameObject.SetActive(i >= firstIndex && i < firstIndex + cardsPerPage);
                }
            }

            if (droneUpgradePageText != null)
                droneUpgradePageText.text = LF("common.page", droneUpgradePage + 1, pageCount);
            if (droneUpgradePrevButton != null)
                droneUpgradePrevButton.gameObject.SetActive(pageCount > 1);
            if (droneUpgradeNextButton != null)
                droneUpgradeNextButton.gameObject.SetActive(pageCount > 1);
        }

        private void ChangeModuleUpgradePage(int delta)
        {
            const int cardsPerPage = 2;
            int pageCount = Mathf.Max(1, Mathf.CeilToInt(moduleUpgradeCards.Length / (float)cardsPerPage));
            moduleUpgradePage = (moduleUpgradePage + delta + pageCount) % pageCount;
            UpdateModuleUpgradePage();
        }

        private void UpdateModuleUpgradePage()
        {
            if (tutorialModulesTechnologyLessonActive)
            {
                Vector2[] mins =
                {
                    Vector2.zero,
                    new Vector2(0.045f, 0.515f),
                    new Vector2(0.515f, 0.515f),
                    new Vector2(0.045f, 0.165f),
                    new Vector2(0.515f, 0.165f)
                };
                Vector2[] maxs =
                {
                    Vector2.zero,
                    new Vector2(0.485f, 0.865f),
                    new Vector2(0.955f, 0.865f),
                    new Vector2(0.485f, 0.500f),
                    new Vector2(0.955f, 0.500f)
                };

                for (int i = 0; i < moduleUpgradeCards.Length; i++)
                {
                    if (moduleUpgradeCards[i] == null)
                        continue;

                    bool visible = i >= 1 && i <= 4;
                    if (visible)
                    {
                        moduleUpgradeCards[i].anchorMin = mins[i];
                        moduleUpgradeCards[i].anchorMax = maxs[i];
                        moduleUpgradeCards[i].offsetMin = Vector2.zero;
                        moduleUpgradeCards[i].offsetMax = Vector2.zero;
                    }
                    moduleUpgradeCards[i].gameObject.SetActive(visible);
                }

                if (moduleUpgradePageText != null)
                    moduleUpgradePageText.text = L("upgrade.modules");
                if (moduleUpgradePrevButton != null)
                    moduleUpgradePrevButton.gameObject.SetActive(false);
                if (moduleUpgradeNextButton != null)
                    moduleUpgradeNextButton.gameObject.SetActive(false);
                return;
            }

            const int cardsPerPage = 2;
            int pageCount = Mathf.Max(1, Mathf.CeilToInt(moduleUpgradeCards.Length / (float)cardsPerPage));
            moduleUpgradePage = Mathf.Clamp(moduleUpgradePage, 0, pageCount - 1);
            int firstIndex = moduleUpgradePage * cardsPerPage;

            for (int i = 0; i < moduleUpgradeCards.Length; i++)
            {
                if (moduleUpgradeCards[i] != null)
                    moduleUpgradeCards[i].gameObject.SetActive(i >= firstIndex && i < firstIndex + cardsPerPage);
            }

            if (moduleUpgradePageText != null)
                moduleUpgradePageText.text = LF("common.page", moduleUpgradePage + 1, pageCount);
            if (moduleUpgradePrevButton != null)
                moduleUpgradePrevButton.gameObject.SetActive(pageCount > 1);
            if (moduleUpgradeNextButton != null)
                moduleUpgradeNextButton.gameObject.SetActive(pageCount > 1);
        }

        private static void SetUpgradeTabVisual(Button button, bool active)
        {
            if (button == null)
                return;

            Image image = button.GetComponent<Image>();
            if (image != null)
                image.color = active ? Color.white : new Color(0.62f, 0.88f, 0.92f, 0.76f);

            Outline outline = button.GetComponent<Outline>();
            if (outline != null)
                outline.effectColor = active ? new Color(0.10f, 0.94f, 1f, 0.44f) : new Color(0.18f, 0.86f, 1f, 0.14f);

            Transform activeLine = button.transform.Find("ActiveLine");
            if (activeLine != null)
                activeLine.gameObject.SetActive(active);

            TextMeshProUGUI text = button.GetComponentInChildren<TextMeshProUGUI>(true);
            if (text != null)
                text.color = active ? Cyan : Ink;
        }

        private void BuildSettings(RectTransform root)
        {
            settingsRoot = CreatePanel(root, "SettingsRoot", new Color(0f, 0f, 0f, 0.62f));
            Stretch(settingsRoot);

            RectTransform card = CreatePanel(settingsRoot, "SettingsCard", new Color(0.018f, 0.046f, 0.068f, 0.98f));
            card.anchorMin = new Vector2(0.06f, 0.13f);
            card.anchorMax = new Vector2(0.94f, 0.88f);
            card.offsetMin = Vector2.zero;
            card.offsetMax = Vector2.zero;
            AddOutline(card, new Color(0.16f, 0.78f, 0.92f, 0.72f), new Vector2(3f, -3f));

            TextMeshProUGUI title = CreateText(card, "Title", K("settings.title"), 45f, FontStyles.Bold, Ink);
            title.rectTransform.anchorMin = new Vector2(0.08f, 0.84f);
            title.rectTransform.anchorMax = new Vector2(0.92f, 0.96f);
            title.rectTransform.offsetMin = Vector2.zero;
            title.rectTransform.offsetMax = Vector2.zero;

            Button soundButton = CreateButton(card, "SoundToggle", string.Empty, new Vector2(0.13f, 0.68f), new Vector2(0.87f, 0.77f), Vector2.zero, Vector2.zero, 34f, ToggleSound);
            soundToggleText = soundButton.GetComponentInChildren<TextMeshProUGUI>(true);

            Button musicButton = CreateButton(card, "MusicToggle", string.Empty, new Vector2(0.13f, 0.56f), new Vector2(0.87f, 0.65f), Vector2.zero, Vector2.zero, 34f, ToggleMusic);
            musicToggleText = musicButton.GetComponentInChildren<TextMeshProUGUI>(true);

            Button testButton = CreateButton(card, "TestToggle", string.Empty, new Vector2(0.13f, 0.44f), new Vector2(0.87f, 0.53f), Vector2.zero, Vector2.zero, 34f, ToggleTestMode);
            testToggleText = testButton.GetComponentInChildren<TextMeshProUGUI>(true);

            CreateButton(card, "ResetProgress", K("settings.reset"), new Vector2(0.13f, 0.32f), new Vector2(0.87f, 0.41f), Vector2.zero, Vector2.zero, 32f, ResetProgress);
            settingsReturnMenuButton = CreateButton(card, "ReturnMenu", K("settings.back_menu"), new Vector2(0.13f, 0.19f), new Vector2(0.87f, 0.28f), Vector2.zero, Vector2.zero, 28f, ReturnToGameMenuFromSettings);
            settingsBackPlatformButton = CreateButton(card, "ReturnMain", K("settings.back_platform"), new Vector2(0.13f, 0.19f), new Vector2(0.87f, 0.28f), Vector2.zero, Vector2.zero, 28f, BackToMain);
            settingsReturnMenuText = settingsReturnMenuButton.GetComponentInChildren<TextMeshProUGUI>(true);
            settingsBackPlatformText = settingsBackPlatformButton.GetComponentInChildren<TextMeshProUGUI>(true);
            CreateButton(card, "CloseSettings", K("common.back"), new Vector2(0.30f, 0.06f), new Vector2(0.70f, 0.15f), Vector2.zero, Vector2.zero, 30f, CloseSettings);
            RefreshSettingsLabels();
            settingsRoot.gameObject.SetActive(false);
        }

        private void BuildBestiary(RectTransform root)
        {
            bestiaryUi = OrbiosisBestiaryUI.Ensure(root, CloseBestiary);
