        private void TryStartPostTutorialOutpostPrompt()
        {
            if (!IsTutorialCompleted() || postTutorialOutpostPadLessonActive || postTutorialOutpostPadInstallSceneActive)
                return;
            if (droneUpgradePadOwned || PlayerPrefs.GetInt(PostTutorialOutpostPromptShownKey, 0) != 0)
                return;

            StartCoroutine(PostTutorialOutpostPromptRoutine());
        }

        private IEnumerator PostTutorialOutpostPromptRoutine()
        {
            postTutorialOutpostPadLessonActive = true;
            PlayerPrefs.SetInt(PostTutorialOutpostPromptShownKey, 1);
            PlayerPrefs.Save();

            yield return new WaitForSecondsRealtime(0.45f);
            if (state != GameState.Menu || !IsTutorialCompleted() || droneUpgradePadOwned)
            {
                postTutorialOutpostPadLessonActive = false;
                yield break;
            }

            ShowStoryDialog(L("speaker.crafter"), L("dialog.outpost_pad_intro_1"), L("dialog.next_button"));
            yield return WaitStoryDialogButton();
            ShowStoryDialog(L("speaker.crafter"), L("dialog.outpost_pad_intro_2"), L("dialog.open_technology"));
            yield return WaitStoryDialogButton();
            HideStoryDialog();

            currentUpgradeTab = UpgradeTab.Base;
            baseUpgradePage = 0;
            ShowUpgrade();
            ShowBaseUpgradeTab();
            RefreshUpgradeLabels();
            if (statusText != null)
                statusText.text = L("status.buy_outpost_pad");
        }

        private IEnumerator PostTutorialOutpostPadInstallRoutine()
        {
            if (postTutorialOutpostPadInstallSceneActive)
                yield break;

            postTutorialOutpostPadInstallSceneActive = true;
            postTutorialOutpostPadLessonActive = false;
            Time.timeScale = 1f;
            HideStoryDialog();
            HideRuntimeDrones();
            CleanupMenuDroneGhosts();
            UpdateCrafterCraftSound(false);
            UpdateGeneratorShieldChargeSound(false);
            if (upgradeRoot != null)
                upgradeRoot.gameObject.SetActive(false);
            if (settingsRoot != null)
                settingsRoot.gameObject.SetActive(false);
            if (stationControlRoot != null)
                stationControlRoot.gameObject.SetActive(false);
            if (bestiaryUi != null)
                bestiaryUi.Hide();

            state = GameState.Menu;
            menuHangarOpen = true;
            hangarRecoveryActive = false;
            baseHangarExpanded = true;
            baseHangarRevealTransitioning = false;
            SetHangarRevealOffset(MaxHangarRevealOffset());
            SetMenuVisible(false);
            SetGameplayHudVisible(false);
            if (gameTitleRoot != null)
                gameTitleRoot.gameObject.SetActive(false);
            if (gameLogoRoot != null)
                gameLogoRoot.gameObject.SetActive(false);
            if (menuHangarRoot != null)
                menuHangarRoot.gameObject.SetActive(true);
            if (menuHangarProfileRoot != null)
                menuHangarProfileRoot.gameObject.SetActive(false);

            UpdateBaseTab();
            UpdateDroneUpgradePadLayout(true);
            UpdateMenuHangarDisplay();

            Vector2 start = ResolveBaseShipDockPosition();
            Vector2 pad = ResolveDroneUpgradePadWorldPosition();
            Vector2 orbInstallPoint = pad + new Vector2(0f, 54f);
            laneX = start.x;
            orbY = start.y;
            targetLaneX = start.x;
            targetOrbY = start.y;
            orbScale = ResolveMenuHangarDockedOrbScale();
            targetOrbScale = orbScale;
            ApplyOrbScale();

            if (orb != null)
            {
                orb.gameObject.SetActive(true);
                orb.SetAsLastSibling();
            }
            if (crafterDrone != null)
            {
                crafterDrone.gameObject.SetActive(true);
                ApplySpriteFromTextureResource(crafterDrone, CrafterDroneSpriteResourcePath);
                crafterDrone.SetAsLastSibling();
            }
            if (droneUpgradePad != null)
            {
                droneUpgradePad.gameObject.SetActive(true);
                droneUpgradePad.SetAsLastSibling();
            }

            if (statusText != null)
                statusText.text = L("status.outpost_pad_installing");

            const float installSeconds = 3.4f;
            float t = 0f;
            while (t < installSeconds)
            {
                float p = Mathf.Clamp01(t / installSeconds);
                float eased = Mathf.SmoothStep(0f, 1f, p);
                Vector2 orbPoint = Vector2.Lerp(start, orbInstallPoint, Mathf.Clamp01(eased * 1.35f));
                laneX = orbPoint.x;
                orbY = orbPoint.y + Mathf.Sin(Time.unscaledTime * 4.2f) * 6f;
                targetLaneX = laneX;
                targetOrbY = orbY;
                float dockedScale = ResolveMenuHangarDockedOrbScale();
                orbScale = Mathf.Lerp(dockedScale, dockedScale * 0.82f, eased);
                targetOrbScale = orbScale;
                if (orb != null)
                {
                    orb.anchoredPosition = new Vector2(laneX, orbY);
                    orb.SetAsLastSibling();
                }
                ApplyOrbScale();

                float orbit = Time.unscaledTime * 4.6f;
                crafterPosition = pad + new Vector2(Mathf.Cos(orbit) * 92f, Mathf.Sin(orbit) * 46f - 12f);
                if (crafterDrone != null)
                {
                    crafterDrone.anchoredPosition = crafterPosition + WorkVibration(0.44f, 30f);
                    crafterDrone.localScale = Vector3.one * (1.18f + Mathf.Sin(Time.unscaledTime * 16f) * 0.04f);
                    FaceDroneToward(crafterDrone, crafterPosition, pad, Mathf.Sin(Time.unscaledTime * 44f) * 4f);
                    crafterDrone.SetAsLastSibling();
                }

                if (droneUpgradePad != null)
                {
                    float pulse = 1f + Mathf.Sin(Time.unscaledTime * 10.5f) * 0.045f;
                    float grow = Mathf.Lerp(0.42f, 1.0f, eased);
                    droneUpgradePad.localScale = Vector3.one * grow * pulse;
                    droneUpgradePad.SetAsLastSibling();
                }

                ShowCraftProgress(eased);
                UpdateCrafterCraftSound(true);
                t += Time.unscaledDeltaTime;
                yield return null;
            }

            if (droneUpgradePad != null)
            {
                droneUpgradePad.localScale = Vector3.one;
                droneUpgradePad.SetAsLastSibling();
            }
            HideCraftProgress();
            UpdateCrafterCraftSound(false);
            PlayerPrefs.SetInt(PostTutorialOutpostPadInstalledKey, 1);
            PlayerPrefs.Save();
            RefreshHud();
            RefreshUpgradeLabels();
            if (statusText != null)
                statusText.text = L("status.outpost_pad_installed");

            ShowStoryDialog(L("speaker.crafter"), L("dialog.outpost_pad_ready"), L("dialog.continue"));
            yield return WaitStoryDialogButton();
            HideStoryDialog();

            postTutorialOutpostPadInstallSceneActive = false;
            if (statusText != null)
                statusText.text = L("status.outpost_pad_installed");
            UpdateMenuHangarDisplay();
        }

        private void ToggleModeSelect()
        {
            if (state != GameState.Menu && state != GameState.ModeSelect && state != GameState.StoryLevels)
                return;

            if (!IsTutorialCompleted())
            {
                ShowTutorialIntroDialog();
                return;
            }

            ShowModeSelect();
        }

        private void ShowModeSelect()
        {
            if (!IsTutorialCompleted())
            {
                ShowTutorialIntroDialog();
                return;
            }

            modeSelectOpen = true;
            storyLevelsOpen = false;
            state = GameState.ModeSelect;
            if (startButtonRoot != null)
                startButtonRoot.gameObject.SetActive(false);
            if (modeSelectRoot != null)
                modeSelectRoot.gameObject.SetActive(true);
            if (storyLevelsRoot != null)
                storyLevelsRoot.gameObject.SetActive(false);
            if (statusText != null)
                statusText.text = L("status.choose_mode");
        }

