        private void ToggleBaseHangar()
        {
            if (!IsOrbDockedOnBaseShip())
            {
                if (statusText != null)
                    statusText.text = L("status.base_requires_orb");
                return;
            }
            if (selectedMode == GameMode.Story && selectedStoryLevel == StoryLevel.Tutorial)
            {
                bool tutorialAllowsBase = tutorialBaseHangarLessonActive || tutorialShieldHangarLessonActive || tutorialShieldAttachLessonActive;
                if (!tutorialAllowsBase)
                {
                    if (statusText != null)
                        statusText.text = L("status.hangar_locked_slots");
                    return;
                }
            }

            if (baseHangarExpanded)
                CloseHangar();
            else
                ShowHangar();
        }

        private void ShowMenuHangar()
        {
            if (state != GameState.Menu || transitioningToGame || menuHangarDoorAnimating)
                return;

            if (!IsTutorialCompleted())
            {
                if (statusText != null)
                    statusText.text = L("status.complete_tutorial");
                return;
            }

            if (menuHangarDoorRoutine != null)
                StopCoroutine(menuHangarDoorRoutine);
            menuHangarDoorRoutine = StartCoroutine(ShowMenuHangarRoutine());
        }

        private IEnumerator ShowMenuHangarRoutine()
        {
            menuHangarDoorAnimating = true;
            modeSelectOpen = false;
            storyLevelsOpen = false;
            pointerControl = false;
            pointerStartedOnUi = false;
            ResetHangarGesture();
            SetMenuVisible(false);
            if (gameTitleRoot != null)
                gameTitleRoot.gameObject.SetActive(false);
            if (gameLogoRoot != null)
                gameLogoRoot.gameObject.SetActive(false);
            if (menuBestText != null)
                menuBestText.gameObject.SetActive(false);
            if (menuHangarRoot != null)
                menuHangarRoot.gameObject.SetActive(false);

            LayoutMenuHangarDoors(0f);
            if (menuHangarDoorRoot != null)
            {
                menuHangarDoorRoot.gameObject.SetActive(true);
                menuHangarDoorRoot.SetAsLastSibling();
            }

            yield return AnimateMenuHangarDoors(0f, 1f, MenuHangarDoorCloseSeconds);
            yield return new WaitForSecondsRealtime(MenuHangarDoorHoldSeconds);

            menuHangarOpen = true;
            BeginBaseHangarRevealTransition(true);
            UpdateTopNavigationButtons();
            UpdateMenuHangarDisplay();
            yield return WaitForMenuHangarReveal(true);

            yield return AnimateMenuHangarDoors(1f, 0f, MenuHangarDoorOpenSeconds);

            if (menuHangarDoorRoot != null)
                menuHangarDoorRoot.gameObject.SetActive(false);
            if (menuHangarRoot != null)
                menuHangarRoot.gameObject.SetActive(true);

            menuHangarDoorAnimating = false;
            UpdateTopNavigationButtons();
            UpdateBaseTab();
            menuHangarDoorRoutine = null;
            if (statusText != null)
                statusText.text = "HANGAR";
        }

        private void CloseMenuHangar()
        {
            if (!menuHangarOpen || menuHangarDoorAnimating)
                return;

            if (menuHangarDoorRoutine != null)
                StopCoroutine(menuHangarDoorRoutine);
            menuHangarDoorRoutine = StartCoroutine(CloseMenuHangarRoutine());
        }

        private IEnumerator CloseMenuHangarRoutine()
        {
            menuHangarDoorAnimating = true;
            UpdateTopNavigationButtons();
            UpdateBaseTab();
            LayoutMenuHangarDoors(0f);
            if (menuHangarDoorRoot != null)
            {
                menuHangarDoorRoot.gameObject.SetActive(true);
                menuHangarDoorRoot.SetAsLastSibling();
            }

            yield return AnimateMenuHangarDoors(0f, 1f, MenuHangarDoorCloseSeconds);
            yield return new WaitForSecondsRealtime(MenuHangarDoorHoldSeconds);

            menuHangarOpen = false;
            hangarRecoveryActive = false;
            hangarRecoveryReturningToMenu = false;
            hangarRecoveryTimer = 0f;
            SyncOrbHealthFromBaseShip();
            StopDefeatFlowRoutines();
            HideHangarRecoveryEffects();
            if (menuHangarRoot != null)
                menuHangarRoot.gameObject.SetActive(false);
            if (gameTitleRoot != null)
                gameTitleRoot.gameObject.SetActive(true);
            if (gameLogoRoot != null)
                gameLogoRoot.gameObject.SetActive(true);
            if (menuBestText != null)
                menuBestText.gameObject.SetActive(true);
            UpdateTopNavigationButtons();
            SetMenuVisible(true);
            BeginBaseHangarRevealTransition(false);
            if (statusText != null)
                statusText.text = string.Empty;
            yield return WaitForMenuHangarReveal(false);

            yield return AnimateMenuHangarDoors(1f, 0f, MenuHangarDoorOpenSeconds);

            if (menuHangarDoorRoot != null)
                menuHangarDoorRoot.gameObject.SetActive(false);

            menuHangarDoorAnimating = false;
            menuHangarDoorRoutine = null;
        }

        private void StartFromMenuHangar()
        {
            if (!menuHangarOpen || menuHangarDoorAnimating)
                return;

            if (menuHangarDoorRoutine != null)
                StopCoroutine(menuHangarDoorRoutine);
            menuHangarDoorRoutine = StartCoroutine(CloseMenuHangarThenStartRoutine());
        }

        private IEnumerator CloseMenuHangarThenStartRoutine()
        {
            yield return CloseMenuHangarRoutine();
            ShowModeSelect();
        }

        private IEnumerator AnimateMenuHangarDoors(float fromClosed, float toClosed, float seconds)
        {
            float duration = Mathf.Max(0.01f, seconds);
            float elapsedSeconds = 0f;
            while (elapsedSeconds < duration)
            {
                elapsedSeconds += Time.unscaledDeltaTime;
                float t = Mathf.Clamp01(elapsedSeconds / duration);
                t = t * t * (3f - 2f * t);
                LayoutMenuHangarDoors(Mathf.Lerp(fromClosed, toClosed, t));
                yield return null;
            }

            LayoutMenuHangarDoors(toClosed);
        }

        private IEnumerator WaitForMenuHangarReveal(bool expanded)
        {
            float timeout = 1.15f;
            float elapsedSeconds = 0f;
            while (elapsedSeconds < timeout)
            {
                float target = expanded ? MaxHangarRevealOffset() : 0f;
                if (Mathf.Abs(hangarRevealOffset - target) <= BaseHangarRevealSnapDistance + 2f)
                    break;

                elapsedSeconds += Time.unscaledDeltaTime;
                yield return null;
            }
        }

        private void LayoutMenuHangarDoors(float closedFraction)
        {
            if (menuHangarDoorRoot == null || menuHangarLeftDoor == null || menuHangarRightDoor == null)
                return;

            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            Vector2 size = root != null ? root.rect.size : new Vector2(900f, 1600f);
            float doorWidth = Mathf.Max(size.x * 0.62f, 420f);
            float doorHeight = Mathf.Max(size.y * 1.14f, 1680f);
            ConfigureMenuHangarDoor(menuHangarLeftDoor, doorWidth, doorHeight);
            ConfigureMenuHangarDoor(menuHangarRightDoor, doorWidth, doorHeight);

            float leftClosedX = -doorWidth * 0.5f + MenuHangarDoorClosedOverlap * 0.5f;
            float rightClosedX = doorWidth * 0.5f - MenuHangarDoorClosedOverlap * 0.5f;
            float leftOpenX = -size.x * 0.5f - doorWidth * 0.62f;
            float rightOpenX = size.x * 0.5f + doorWidth * 0.62f;
            float t = Mathf.Clamp01(closedFraction);
            menuHangarLeftDoor.anchoredPosition = new Vector2(Mathf.Lerp(leftOpenX, leftClosedX, t), 0f);
            menuHangarRightDoor.anchoredPosition = new Vector2(Mathf.Lerp(rightOpenX, rightClosedX, t), 0f);
        }

        private static void ConfigureMenuHangarDoor(RectTransform door, float width, float height)
        {
            if (door == null)
                return;

            door.anchorMin = new Vector2(0.5f, 0.5f);
            door.anchorMax = new Vector2(0.5f, 0.5f);
            door.pivot = new Vector2(0.5f, 0.5f);
            door.sizeDelta = new Vector2(width, height);
        }

        private void ShowHangar()
        {
            if (state != GameState.Playing || gameOver || transitioningToGame)
                return;

            pointerControl = false;
            pointerStartedOnUi = false;
            pointerStartedOnOrbControl = false;
            crafterDragging = false;
            generatorDragging = false;
            repairDragging = false;
            shieldDroneDragging = false;
            collectorDroneDragging = false;
            ResetHangarGesture();

            if (droneInfoRoot != null)
                droneInfoRoot.gameObject.SetActive(false);
            BeginBaseHangarRevealTransition(true);
            UpdateBaseTab();
            if (statusText != null)
                statusText.text = "HANGAR OPENING";
        }

        private void CloseHangar()
        {
            BeginBaseHangarRevealTransition(false);
            UpdateBaseTab();
            if (statusText != null)
                statusText.text = "HANGAR CLOSING";
        }

        private void ResetHangarGesture()
        {
            hangarGestureTracking = false;
            hangarGestureStart = Vector2.zero;
            hangarGestureLast = Vector2.zero;
            hangarGestureUpTravel = 0f;
        }

        private void ResetHangarMouseCameraDrag()
        {
            hangarMouseCameraDragTracking = false;
            hangarMouseCameraLastPosition = Vector2.zero;
        }

        private void UpdateBaseTab()
        {
            bool modalOverlayActive = IsModalOverlayActive();
            bool visible = !modalOverlayActive && state == GameState.Playing && !gameOver && !transitioningToGame && !stationControlOpen && IsOrbDockedOnBaseShip();
            bool menuHangarControlsVisible = !modalOverlayActive && ShouldShowMenuHangarControls();
            if (!visible && !menuHangarOpen && (baseHangarExpanded || baseHangarRevealTransitioning))
                ResetBaseHangarRevealImmediate();

            if (baseTabButton != null)
                baseTabButton.gameObject.SetActive(visible);
            if (topStationButton != null)
                topStationButton.gameObject.SetActive(menuHangarControlsVisible || visible);
            if (baseTabLabel != null)
                baseTabLabel.text = baseHangarExpanded ? "CLOSE" : "BASE";

            UpdateBaseTabTutorialHint(visible && tutorialBaseHangarLessonActive && !baseHangarExpanded);
        }

        private bool ShouldShowMenuHangarControls()
        {
            return menuHangarOpen
                && !menuHangarDoorAnimating
                && menuHangarRoot != null
                && menuHangarRoot.gameObject.activeSelf;
        }

        private void CreateBaseTabTutorialHint(Transform parent)
        {
            baseTabHintRoot = CreatePanel(parent, "BaseTabTutorialHint", new Color(0.008f, 0.050f, 0.070f, 0.88f));
            baseTabHintRoot.anchorMin = new Vector2(0.5f, 0f);
            baseTabHintRoot.anchorMax = new Vector2(0.5f, 0f);
            baseTabHintRoot.pivot = new Vector2(0f, 0.5f);
            baseTabHintRoot.sizeDelta = new Vector2(238f, 52f);
            baseTabHintRoot.anchoredPosition = Vector2.zero;
            SetRaycastTarget(baseTabHintRoot, false);
            AddOutline(baseTabHintRoot, new Color(0.26f, 1f, 1f, 0.62f), new Vector2(2f, -2f));

            baseTabHintText = CreateText(baseTabHintRoot, "Text", "<<< OPEN BASE", 25f, FontStyles.Bold, Gold);
            Stretch(baseTabHintText.rectTransform);
            baseTabHintText.rectTransform.offsetMin = new Vector2(12f, 0f);
            baseTabHintText.rectTransform.offsetMax = new Vector2(-12f, 0f);
            baseTabHintText.fontSizeMin = 18f;
            baseTabHintText.fontSizeMax = 25f;
            baseTabHintRoot.gameObject.SetActive(false);
        }

        private void UpdateBaseTabTutorialHint(bool active)
        {
            if (baseTabHintRoot != null)
            {
                UpdateBaseTabButtonLayout(active);
                Vector2 layoutPosition = baseTabHintRoot.anchoredPosition;
                baseTabHintRoot.gameObject.SetActive(active);
                if (active)
                {
                    float pulse = 0.5f + Mathf.Sin(Time.unscaledTime * 8.0f) * 0.5f;
                    baseTabHintRoot.anchoredPosition = layoutPosition + new Vector2(pulse * 14f, 0f);
                    baseTabHintRoot.localScale = Vector3.one * (1f + pulse * 0.035f);
                    Image hintImage = baseTabHintRoot.GetComponent<Image>();
                    if (hintImage != null)
                        hintImage.color = Color.Lerp(new Color(0.008f, 0.050f, 0.070f, 0.82f), new Color(0.035f, 0.22f, 0.28f, 0.96f), pulse);
                    if (baseTabHintText != null)
                        baseTabHintText.color = Color.Lerp(Gold, Color.white, pulse * 0.55f);
                }
                else
                {
                    baseTabHintRoot.anchoredPosition = layoutPosition;
                    baseTabHintRoot.localScale = Vector3.one;
                }
            }

            if (baseTabButton != null && baseTabButton.targetGraphic != null)
            {
                float pulse = active ? 0.5f + Mathf.Sin(Time.unscaledTime * 10.0f) * 0.5f : 0f;
                baseTabButton.targetGraphic.color = active ? Color.Lerp(Color.white, new Color(0.62f, 1f, 1f, 1f), pulse) : Color.white;
            }
        }

        private float ResolveGameplayTimeScale()
        {
            if (baseHangarExpanded && IsOrbDockedOnBaseShip())
                return 1f;

            return crafterDragging || generatorDragging || repairDragging || shieldDroneDragging || collectorDroneDragging ? 0.18f : 1f;
        }

        private bool TryHandleHangarEntryGesture(RectTransform root)
        {
            if (state != GameState.Playing || gameOver || transitioningToGame || stationControlOpen)
            {
                ResetHangarGesture();
                return false;
            }

            if (!TryReadHangarGestureCentroid(out Vector2 centroid))
            {
                ResetHangarGesture();
                return false;
            }

            if (!hangarGestureTracking)
            {
                hangarGestureTracking = true;
                hangarGestureStart = centroid;
                hangarGestureLast = centroid;
                hangarGestureUpTravel = 0f;
                pointerControl = false;
                pointerStartedOnUi = false;
                crafterDragging = false;
                generatorDragging = false;
                repairDragging = false;
                shieldDroneDragging = false;
                collectorDroneDragging = false;
                return true;
            }

            Vector2 delta = centroid - hangarGestureStart;
            Vector2 frameDelta = centroid - hangarGestureLast;
            hangarGestureLast = centroid;
            hangarGestureUpTravel = Mathf.Max(0f, hangarGestureUpTravel + frameDelta.y - Mathf.Abs(frameDelta.x) * 0.18f);
            float verticalThreshold = Mathf.Max(HangarGestureMinScreenDistance, Screen.height * HangarGestureScreenDistanceFraction);
            float horizontalLimit = Mathf.Max(120f, Screen.width * HangarGestureMaxHorizontalFraction);
            if (Mathf.Abs(frameDelta.y) > Mathf.Abs(frameDelta.x) * 0.45f)
            {
                manualCameraControlTimer = 0.85f;
                SetHangarRevealOffset(hangarRevealOffset + frameDelta.y);
            }

            if ((delta.y >= verticalThreshold || hangarGestureUpTravel >= verticalThreshold) && Mathf.Abs(delta.x) <= horizontalLimit)
            {
                return true;
            }

            return true;
        }

        private bool HandleHangarMouseWheelCamera()
        {
            if (TryReadHangarKeyboardCameraDelta(out float keyboardDelta))
                return ApplyHangarCameraDelta(keyboardDelta, false);

            if (!TryReadHangarMouseWheelDelta(out float wheelDelta))
                return false;

            return ApplyHangarCameraDelta(wheelDelta, true);
        }

        private void HandleExternalHangarScroll(float scrollY)
        {
            if (Mathf.Abs(scrollY) < 0.01f)
                return;

            ApplyHangarCameraDelta(NormalizeMouseWheelRevealDelta(scrollY), true);
        }

        private void HandleExternalHangarDrag(PointerEventData pointerData)
        {
            ResetHangarMouseCameraDrag();
        }

        private bool ApplyHangarCameraDelta(float wheelDelta, bool fromWheel)
        {
            if (state != GameState.Playing || gameOver || transitioningToGame || stationControlOpen)
                return false;
            if (Time.frameCount == lastHangarCameraScrollFrame)
                return true;

            lastHangarCameraScrollFrame = Time.frameCount;
            if (fromWheel)
            {
                ResetHangarGesture();
                ResetHangarMouseCameraDrag();
            }
            ResetGameplayPointerInput();
            manualCameraControlTimer = 0.85f;
            SetHangarRevealOffset(hangarRevealOffset + wheelDelta);
            if (statusText != null)
                statusText.text = "CAMERA " + Mathf.RoundToInt(hangarRevealOffset) + " [" + Mathf.RoundToInt(MinForwardCameraOffset()) + "/" + Mathf.RoundToInt(MaxHangarRevealOffset()) + "]";
            return true;
        }

        private void ResetGameplayPointerInput()
        {
            pointerControl = false;
            pointerStartedOnUi = false;
            pointerStartedOnOrbControl = false;
            outpostOrbUndockedThisGesture = false;
            crafterDragging = false;
            generatorDragging = false;
            repairDragging = false;
            shieldDroneDragging = false;
            collectorDroneDragging = false;
            queenDroneDragging = false;
            mimicDroneDragging = false;
            sniperDroneDragging = false;
            HideMimicAimVisuals();
            HideSniperAimVisuals();
        }

        private static bool WasHangarDebugKeyPressed()
        {
#if ENABLE_INPUT_SYSTEM
            return Keyboard.current != null && Keyboard.current.hKey.wasPressedThisFrame;
#else
            return Input.GetKeyDown(KeyCode.H);
#endif
        }

        private static bool TryReadHangarMouseWheelDelta(out float delta)
        {
            delta = 0f;

#if ENABLE_INPUT_SYSTEM
            if (Mouse.current == null)
                return false;

            float scrollY = Mouse.current.scroll.ReadValue().y;
            if (Mathf.Abs(scrollY) < 0.01f)
                return false;

            delta = NormalizeMouseWheelRevealDelta(scrollY);
            return true;
#else
            float scrollY = Input.mouseScrollDelta.y;
            if (Mathf.Abs(scrollY) < 0.01f)
                return false;

            delta = NormalizeMouseWheelRevealDelta(scrollY);
            return true;
#endif
        }

        private bool TryReadHangarMouseDragDelta(out float delta)
        {
            delta = 0f;

#if ENABLE_INPUT_SYSTEM
            if (!IsCameraMouseControlPressed())
            {
                ResetHangarMouseCameraDrag();
                return false;
            }

            Vector2 position = Mouse.current.position.ReadValue();
            if (!hangarMouseCameraDragTracking)
            {
                hangarMouseCameraDragTracking = true;
                hangarMouseCameraLastPosition = position;
                return true;
            }

            float positionDelta = position.y - hangarMouseCameraLastPosition.y;
            float deviceDelta = Mouse.current.delta.ReadValue().y;
            delta = Mathf.Abs(positionDelta) > 0.01f ? positionDelta : deviceDelta;
            hangarMouseCameraLastPosition = position;
            return true;
#else
            if (!IsCameraMouseControlPressed())
            {
                ResetHangarMouseCameraDrag();
                return false;
            }

            Vector2 position = Input.mousePosition;
            if (!hangarMouseCameraDragTracking)
            {
                hangarMouseCameraDragTracking = true;
                hangarMouseCameraLastPosition = position;
                return true;
            }

            float positionDelta = position.y - hangarMouseCameraLastPosition.y;
            float axisDelta = Input.GetAxisRaw("Mouse Y") * 18f;
            delta = Mathf.Abs(positionDelta) > 0.01f ? positionDelta : axisDelta;
            hangarMouseCameraLastPosition = position;
            return true;
#endif
        }

        private static bool IsCameraMouseControlPressed()
        {
#if ENABLE_INPUT_SYSTEM
            if (Mouse.current == null)
                return false;

            return Mouse.current.rightButton.isPressed || Mouse.current.middleButton.isPressed;
#else
            return Input.GetMouseButton(1) || Input.GetMouseButton(2);
#endif
        }

        private static bool TryReadHangarKeyboardCameraDelta(out float delta)
        {
            delta = 0f;

#if ENABLE_INPUT_SYSTEM
            if (Keyboard.current == null)
                return false;

            if (Keyboard.current.pageUpKey.wasPressedThisFrame || Keyboard.current.upArrowKey.wasPressedThisFrame)
            {
                delta = -HangarMouseWheelRevealPixels;
                return true;
            }

            if (Keyboard.current.pageDownKey.wasPressedThisFrame || Keyboard.current.downArrowKey.wasPressedThisFrame)
            {
                delta = HangarMouseWheelRevealPixels;
                return true;
            }
#else
            if (Input.GetKeyDown(KeyCode.PageUp) || Input.GetKeyDown(KeyCode.UpArrow))
            {
                delta = -HangarMouseWheelRevealPixels;
                return true;
            }

            if (Input.GetKeyDown(KeyCode.PageDown) || Input.GetKeyDown(KeyCode.DownArrow))
            {
                delta = HangarMouseWheelRevealPixels;
                return true;
            }
#endif

            return false;
        }

        private static float NormalizeMouseWheelRevealDelta(float scrollY)
        {
            return -Mathf.Sign(scrollY) * HangarMouseWheelRevealPixels;
        }

        private static bool TryReadHangarGestureCentroid(out Vector2 centroid)
        {
            centroid = Vector2.zero;

#if ENABLE_INPUT_SYSTEM
            int touchCount = 0;
            Vector2 touchSum = Vector2.zero;
            if (Touchscreen.current != null)
            {
                foreach (var touch in Touchscreen.current.touches)
                {
                    if (!touch.press.isPressed)
                        continue;

                    touchSum += touch.position.ReadValue();
                    touchCount++;
                    if (touchCount >= 2)
                    {
                        centroid = touchSum / touchCount;
                        return true;
                    }
                }
            }

#else
            if (Input.touchCount >= 2)
            {
                centroid = (Input.GetTouch(0).position + Input.GetTouch(1).position) * 0.5f;
                return true;
            }
#endif

            return false;
        }

        private void CycleStationTaskPriority(int index)
        {
            if (index < 0 || index >= stationTaskPriorities.Length)
                return;

            stationTaskPriorities[index] = (stationTaskPriorities[index] + 1) % 5;
            RefreshStationControlLabels();
        }

        private void RefreshStationControlLabels()
        {
            for (int i = 0; i < stationTaskPriorityTexts.Length; i++)
            {
                TextMeshProUGUI text = stationTaskPriorityTexts[i];
                if (text == null)
                    continue;

                int value = stationTaskPriorities[i];
                text.text = value <= 0 ? L("common.off") : "P" + value;
                text.color = value <= 0 ? MutedInk : value == 1 ? Gold : Cyan;
            }
        }

        private int CurrentStationEvolutionLevel()
        {
            return Mathf.Clamp(stationEvolutionLevel, StationMinEvolutionLevel, StationMaxEvolutionLevel);
        }

        private string OrbStationEvolutionSpriteResourcePath(int evolutionLevel)
        {
            return OrbiosisOrbStationResources.GetBattleEvolutionResourcePath(evolutionLevel);
        }

        private string CurrentOrbStationSpriteResourcePath()
        {
            return OrbStationEvolutionSpriteResourcePath(CurrentStationEvolutionLevel());
        }

        private float CurrentOrbEvolutionScale()
        {
            return 1f + (CurrentStationEvolutionLevel() - 1) * 0.05f;
        }

        private float CurrentOrbBaseScale()
        {
            return CurrentOrbEvolutionScale();
        }

        private float ResolveMenuHangarDockedOrbScale()
        {
            Vector2 slotSize = ResolveBaseShipSlotPlateSize(2);
            float fitSize = slotSize.x * MenuHangarDockedOrbSlotFill;
            return Mathf.Clamp(fitSize / Mathf.Max(1f, OrbStationBattleSize), 1.70f, 2.20f);
        }

        private float ResolveBaseDockedOrbScale()
        {
            Vector2 slotSize = ResolveBaseShipSlotPlateSize(2);
            float fitSize = slotSize.x * BaseDockedOrbSlotFill;
            float slotScale = Mathf.Clamp(fitSize / Mathf.Max(1f, OrbStationBattleSize), 1.70f, 2.20f);
            return slotScale * CurrentOrbEvolutionScale();
        }

        private float ResolveOutpostDockedOrbScale()
        {
            float fitSize = OutpostOrbSlotSize * OutpostDockedOrbSlotFill;
            float scale = fitSize / Mathf.Max(1f, OrbStationBattleSize) * CurrentOrbEvolutionScale();
            return Mathf.Clamp(scale, 1.05f, 1.42f);
        }

        private float ResolveActiveDockedOrbScale()
        {
            return outpostDefenderMode && outpostBuilt ? ResolveOutpostDockedOrbScale() : ResolveBaseDockedOrbScale();
        }

        private int CurrentOrbModuleSlotCount(int evolutionLevel)
        {
            return Mathf.Clamp((evolutionLevel - 1) / 2, 0, 4);
        }

        private int CurrentFlightModuleSlotCount(int evolutionLevel)
        {
            return Mathf.Clamp((evolutionLevel - 2) / 2, 0, 4);
        }

        private void ApplyCurrentOrbEvolutionVisual()
        {
            if (orb != null)
            {
                bool applied = ApplyOrbEvolutionSprite(orb, CurrentStationEvolutionLevel());
                orb.sizeDelta = Vector2.one * OrbStationBattleSize;
                appliedOrbEvolutionLevel = CurrentStationEvolutionLevel();
                if (!applied && statusText != null)
                    statusText.text = L("status.evolution_fail");
            }
            if (!transitioningToGame)
            {
                bool menuLikeState = IsMenuLikeState();
                orbScale = (menuLikeState ? 2.35f : 1f) * CurrentOrbEvolutionScale();
                targetOrbScale = orbScale;
            }
            ApplyOrbScale();
        }

        private static bool ApplyOrbEvolutionSprite(RectTransform target, int evolutionLevel)
        {
            if (target == null)
                return false;

            Image image = target.GetComponent<Image>();
            if (image == null)
                return false;

            if (OrbiosisOrbStationResources.ApplyBattleEvolutionSprite(image, evolutionLevel))
                return true;

            Sprite fallback = GetSpriteFromTextureResource(OrbStationSpriteResourcePath);
            if (fallback == null)
                return false;

            image.enabled = true;
            image.sprite = fallback;
            image.overrideSprite = fallback;
            image.type = Image.Type.Simple;
            image.color = Color.white;
            image.preserveAspect = true;
            image.raycastTarget = false;
            return true;
        }

        private void RefreshStationEvolutionCard()
        {
            int level = CurrentStationEvolutionLevel();
            int nextLevel = Mathf.Min(StationMaxEvolutionLevel, level + 1);

            if (stationEvolutionCurrentOrb != null)
                ApplyOrbEvolutionSprite(stationEvolutionCurrentOrb, level);
            if (stationEvolutionNextOrb != null)
                ApplyOrbEvolutionSprite(stationEvolutionNextOrb, nextLevel);
            if (stationEvolutionCurrentLevelText != null)
                stationEvolutionCurrentLevelText.text = "LV " + level;
            if (stationEvolutionNextLevelText != null)
                stationEvolutionNextLevelText.text = level >= StationMaxEvolutionLevel ? "MAX" : "LV " + nextLevel;

            int currentHp = BaseHealth + (level - 1) * 20;
            int nextHp = BaseHealth + (nextLevel - 1) * 20;
            int currentStorage = BaseCarryCapacity + (level - 1) * 10;
            int nextStorage = BaseCarryCapacity + (nextLevel - 1) * 10;
            int currentOrbSlots = CurrentOrbModuleSlotCount(level);
            int nextOrbSlots = CurrentOrbModuleSlotCount(nextLevel);
            int currentFlightSlots = CurrentFlightModuleSlotCount(level);
            int nextFlightSlots = CurrentFlightModuleSlotCount(nextLevel);

            if (stationEvolutionStatsText != null)
            {
                stationEvolutionStatsText.text = LF(
                    "evolution.stats",
                    level,
                    nextLevel,
                    currentHp,
                    Mathf.Max(0, nextHp - currentHp),
                    currentStorage,
                    Mathf.Max(0, nextStorage - currentStorage),
                    currentOrbSlots,
                    Mathf.Max(0, nextOrbSlots - currentOrbSlots),
                    currentFlightSlots,
                    Mathf.Max(0, nextFlightSlots - currentFlightSlots));
            }
        }

        private int CurrentMaxHealth()
        {
            return BaseHealth + (CurrentStationEvolutionLevel() - 1) * 20;
        }

        private void SyncOrbHealthFromBaseShip()
        {
            int maxHealth = Mathf.Max(1, CurrentMaxHealth());
            health = Mathf.Clamp(Mathf.RoundToInt(baseShipHealth / (float)Mathf.Max(1, CurrentSharedMaxHealth()) * maxHealth), 0, maxHealth);
        }

        private int CurrentSharedMaxHealth()
        {
            return BaseShipMaxHealth + (outpostBuilt ? OutpostSharedHealthBonus : 0);
        }

        private void SetSharedHealthRatio(float ratio)
        {
            ratio = Mathf.Clamp01(ratio);
            baseShipHealth = Mathf.Clamp(Mathf.RoundToInt(CurrentSharedMaxHealth() * ratio), 0, CurrentSharedMaxHealth());
            SyncOrbHealthFromBaseShip();
        }

        private void SetSharedHealthFull()
        {
            baseShipHealth = CurrentSharedMaxHealth();
            health = CurrentMaxHealth();
        }

        private void ApplySharedHealthDamage(int damage, string message)
        {
            baseShipHealth = Mathf.Max(0, baseShipHealth - Mathf.Max(1, damage));
            if (outpostBuilt)
                outpostDamageFlashTimer = HazardHitFeedbackSeconds;
            CheckOutpostHealthBreak();
            SyncOrbHealthFromBaseShip();
            baseShipDamageFlashTimer = HazardHitFeedbackSeconds;
            if (statusText != null)
                statusText.text = message;
            RefreshHud();
            if (baseShipHealth <= 0)
                EndRun();
        }

        private bool TryRepairSharedHealthWithParts(ref float repairTimer, string repairSource, int hpPerPart = RepairHpPerPart, bool useUnscaledTime = false)
        {
            bool repaired = TryRepairWithParts(ref baseShipHealth, CurrentSharedMaxHealth(), ref repairTimer, repairSource, hpPerPart, useUnscaledTime);
            if (repaired)
                SyncOrbHealthFromBaseShip();
            return repaired;
        }

        private void AddOutpostSharedHealthSegment()
        {
            baseShipHealth = Mathf.Min(CurrentSharedMaxHealth(), baseShipHealth + OutpostSharedHealthBonus);
            SyncOrbHealthFromBaseShip();
            RefreshHud();
        }

        private void CheckOutpostHealthBreak()
        {
            if (!outpostBuilt || baseShipHealth > BaseShipMaxHealth)
                return;

            DestroyOutpostFromSharedDamage();
        }

        private void DestroyOutpostFromSharedDamage()
        {
            bool orbWasOnOutpost = IsOrbDockedOnOutpost() || (outpostDefenderMode && orbDeploymentStage == OrbDeploymentStage.DockingToBase);
            Vector2 dock = ResolveOutpostDockPosition();
            Vector2 launchTarget = dock + Vector2.up * OutpostOrbLaunchDistance;

            outpostBuilt = false;
            outpostBuilding = false;
            outpostDefenderMode = false;
            outpostHandleDragging = false;
            outpostPositionLocked = false;
            outpostBuildProgress = 0f;
            outpostDockReattachLockTimer = 0f;
            outpostOrbLaunchPending = false;
            outpostOrbUndockedThisGesture = false;
            sniperMountedOnOutpost = false;
            sniperOutpostSlotIndex = -1;
            sniperPendingOutpostDetach = false;
            baseShipHealth = Mathf.Clamp(baseShipHealth, 0, BaseShipMaxHealth);

            if (orbWasOnOutpost)
            {
                SnapWeaponModulesToOrb();
                SetOrbDeploymentStage(OrbDeploymentStage.Flight);
                targetLaneX = launchTarget.x;
                targetOrbY = launchTarget.y;
                pointerControl = false;
                pointerStartedOnOrbControl = false;
            }

            HideBaseModuleStands();
            SyncOrbHealthFromBaseShip();
            if (statusText != null)
                statusText.text = "OUTPOST DESTROYED";
        }

        private int CurrentMaxShield()
        {
            return BaseShield;
        }

        private int CurrentCarryCapacity()
        {
            if (testMode)
                return 9999;

            return BaseCarryCapacity + (CurrentStationEvolutionLevel() - 1) * 10 + (collectorDroneAttached ? CollectorAttachedCarryBonus : 0);
        }

        private void UnloadCargoAtBase()
        {
            if (carriedParts <= 0 || !IsOrbAtBase())
                return;
            if (tutorialMaterialLessonActive && tutorialMaterialDelivered + carriedParts >= tutorialMaterialTarget && !tutorialReturnPartsDialogConfirmed)
            {
                if (statusText != null)
                    statusText.text = tutorialReturnPartsDialogActive ? "CRAFTER MESSAGE" : "WAIT FOR CRAFTER";
                return;
            }
            if (tutorialMaterialLessonActive && tutorialReturnPartsDialogConfirmed)
            {
                if (!tutorialCargoTransferActive)
                    StartCoroutine(TutorialCargoTransferRoutine(carriedParts));
                return;
            }

            int unloaded = carriedParts;
            SpawnCargoUnloadViews(unloaded);
            ozParts += unloaded;
            carriedParts = 0;
            if (tutorialMaterialLessonActive)
                tutorialMaterialDelivered = Mathf.Min(tutorialMaterialTarget, tutorialMaterialDelivered + unloaded);
            if (tutorialMaterialDelivered >= tutorialMaterialTarget)
                tutorialManualReturnToBaseActive = false;
            UpdateTutorialMaterialCounter();
            PlayerPrefs.SetInt(OzPartsKey, ozParts);
            PlayerPrefs.Save();
            if (statusText != null)
                statusText.text = tutorialMaterialLessonActive
                    ? "BASE MATERIAL " + tutorialMaterialDelivered + "/" + tutorialMaterialTarget
                    : "UNLOADED " + unloaded + " OZPARTS";
            RefreshHud();
            RefreshUpgradeLabels();
        }

        private float CurrentFireInterval()
        {
            float rate = QueenBuffRate(coreCannon);
            return Mathf.Max(0.10f, (0.26f - attackLevel * 0.018f) / rate);
        }

        private float CurrentProjectileRadius()
        {
            return 12f + attackLevel * 1.25f;
        }

        private int UpgradeCost(int level, int baseCost)
        {
            return baseCost + level * 4;
        }

        private bool HasCoreShards(int cost)
        {
            return testMode || coreShards >= cost;
        }

        private void SpendCoreShards(int cost)
        {
            if (testMode || cost <= 0)
                return;

            coreShards = Mathf.Max(0, coreShards - cost);
            PlayerPrefs.SetInt(CoreShardsKey, coreShards);
        }

        private bool HasOzParts(int cost)
        {
            return testMode || ozParts >= cost;
        }

        private void SpendOzParts(int cost)
        {
            if (testMode || cost <= 0)
                return;

            ozParts = Mathf.Max(0, ozParts - cost);
            PlayerPrefs.SetInt(OzPartsKey, ozParts);
        }

        private void UpdateCoreForgeConversion()
        {
            if (!coreForgeOwned || testMode)
            {
                coreForgeConversionTimer = 0f;
                return;
            }

            if (ozParts < CoreForgePartsCost)
            {
                coreForgeConversionTimer = 0f;
                return;
            }

            coreForgeConversionTimer += Time.deltaTime;
            if (coreForgeConversionTimer < CoreForgeConversionSeconds)
                return;

            coreForgeConversionTimer = 0f;
            ozParts = Mathf.Max(0, ozParts - CoreForgePartsCost);
            coreShards += CoreForgeCoreReward;
            PlayerPrefs.SetInt(OzPartsKey, ozParts);
            PlayerPrefs.SetInt(CoreShardsKey, coreShards);
            PlayerPrefs.Save();
            if (statusText != null)
                statusText.text = LF("status.core_forge_converted", CoreForgePartsCost, CoreForgeCoreReward);
            RefreshHud();
            RefreshUpgradeLabels();
        }

        private void UpgradeHp()
        {
            if (BlockTutorialPurchaseUnless(tutorialEvolutionTechnologyLessonActive, "TUTORIAL: EVOLVE ORB FIRST"))
                return;

            int currentLevel = CurrentStationEvolutionLevel();
            if (currentLevel >= StationMaxEvolutionLevel)
            {
                if (statusText != null)
                    statusText.text = L("status.evolution_max");
                RefreshUpgradeLabels();
                return;
            }

            int cost = tutorialEvolutionTechnologyLessonActive ? 0 : UpgradeCost(currentLevel - 1, 6);
            if (!HasCoreShards(cost))
            {
                if (statusText != null)
                    statusText.text = L("status.not_enough_core");
                return;
            }

            SpendCoreShards(cost);
            stationEvolutionLevel = Mathf.Min(StationMaxEvolutionLevel, currentLevel + 1);
            SetSharedHealthFull();
            appliedOrbEvolutionLevel = -1;
            if (tutorialEvolutionTechnologyLessonActive)
                tutorialEvolutionTechnologyLessonActive = false;

            PlayerPrefs.SetInt(CoreShardsKey, coreShards);
            if (IsTutorialCompleted())
                PlayerPrefs.SetInt(StationEvolutionLevelKey, stationEvolutionLevel);
            PlayerPrefs.Save();

            ApplyCurrentOrbEvolutionVisual();
            RefreshHud();
            RefreshUpgradeLabels();
            if (statusText != null)
                statusText.text = LF("status.evolution_level", CurrentStationEvolutionLevel());
        }

