        private void SendOzCoreMiner()
        {
            if (!ozCoreMinerOwned)
            {
                if (statusText != null)
                    statusText.text = "BUY CORE MINER FIRST";
                return;
            }

            if (ozCoreMinerCargoReady)
            {
                ClaimOzCoreMinerCargo();
                return;
            }

            if (ozCoreMinerOnMission)
            {
                if (statusText != null)
                    statusText.text = "CORE MINER RETURNS IN " + FormatOzCoreMinerTimeRemaining();
                return;
            }

            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            Vector2 current = ozCoreMinerDrone != null && ozCoreMinerDrone.gameObject.activeSelf
                ? ozCoreMinerDrone.anchoredPosition
                : GetOzCoreMinerButtonAnchor();

            ozCoreMinerExitStart = current;
            ozCoreMinerExitTarget = GetRandomOzCoreMinerExitTarget(root);
            ozCoreMinerExitDirection = ozCoreMinerExitTarget - ozCoreMinerExitStart;
            if (ozCoreMinerExitDirection.sqrMagnitude < 16f)
                ozCoreMinerExitDirection = Vector2.up;
            ozCoreMinerExitDirection.Normalize();
            ozCoreMinerExitTimer = 0f;
            ozCoreMinerReturning = true;
            ozCoreMinerOnMission = true;
            ozCoreMinerCargoReady = false;
            ozCoreMinerReturnAtUtc = GetUtcNowSeconds() + OzCoreMinerMissionSeconds;
            PlayerPrefs.SetString(OzCoreMinerReturnAtKey, ozCoreMinerReturnAtUtc.ToString(System.Globalization.CultureInfo.InvariantCulture));
            PlayerPrefs.Save();
            if (statusText != null)
                statusText.text = L("status.core_miner_sent");
            RefreshUpgradeLabels();
        }

        private void ClaimOzCoreMinerCargo()
        {
            if (!ozCoreMinerCargoReady)
                return;

            ozCoreMinerCargoReady = false;
            ozCoreMinerOnMission = false;
            ozCoreMinerReturning = false;
            ozCoreMinerReturnAtUtc = 0.0;
            coreShards += OzCoreMinerReward;
            PlayerPrefs.SetInt(CoreShardsKey, coreShards);
            PlayerPrefs.DeleteKey(OzCoreMinerReturnAtKey);
            PlayerPrefs.Save();
            if (statusText != null)
                statusText.text = LF("status.core_collected", OzCoreMinerReward);
            RefreshHud();
            RefreshUpgradeLabels();
        }

        private void TryBuyUpgrade(int cost, System.Action apply)
        {
            if (!CanUseTechnologyNow())
            {
                if (statusText != null)
                    statusText.text = L("status.complete_tutorial");
                return;
            }

            if (!HasCoreShards(cost))
            {
                if (statusText != null)
                    statusText.text = L("status.not_enough_core");
                return;
            }

            SpendCoreShards(cost);
            apply?.Invoke();
            PlayerPrefs.Save();
            if (statusText != null)
                statusText.text = L("status.upgraded");
            RefreshHud();
            RefreshUpgradeLabels();
        }

