        private string FormatOzCoreMinerTimeRemaining()
        {
            double remaining = Mathf.Max(0f, (float)(ozCoreMinerReturnAtUtc - GetUtcNowSeconds()));
            int minutes = Mathf.FloorToInt((float)remaining / 60f);
            int seconds = Mathf.CeilToInt((float)remaining - minutes * 60f);
            if (seconds >= 60)
            {
                minutes++;
                seconds = 0;
            }

            return minutes.ToString("00") + ":" + seconds.ToString("00");
        }

        private static double ParseStoredUtc(string value)
        {
            if (string.IsNullOrWhiteSpace(value))
                return 0.0;

            return double.TryParse(value, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out double parsed)
                ? parsed
                : 0.0;
        }

        private static double GetUtcNowSeconds()
        {
            return (System.DateTime.UtcNow - new System.DateTime(1970, 1, 1, 0, 0, 0, System.DateTimeKind.Utc)).TotalSeconds;
        }

        private void ShowSettings()
        {
            if (state != GameState.Settings)
                stateBeforeSettings = state;
            state = GameState.Settings;
            modeSelectOpen = false;
            storyLevelsOpen = false;
            SetMenuVisible(false);
            SetGameplayHudVisible(false);
            if (upgradeRoot != null)
                upgradeRoot.gameObject.SetActive(false);
            if (settingsRoot != null)
                settingsRoot.gameObject.SetActive(true);
            if (bestiaryUi != null)
                bestiaryUi.Hide();
            if (statusText != null)
                statusText.text = "SETTINGS";
            RefreshSettingsLabels();
            RefreshSettingsNavigationButtons();
        }

        private void CloseSettings()
        {
            if (settingsRoot != null)
                settingsRoot.gameObject.SetActive(false);

            if (stateBeforeSettings == GameState.Playing && !gameOver)
            {
                state = GameState.Playing;
                SetGameplayHudVisible(true);
                if (statusText != null)
                    statusText.text = selectedMode == GameMode.Endless ? "ENDLESS DRIFT" : StoryRunTitle();
                return;
            }

            ShowMenu();
        }

        private void ReturnToGameMenuFromSettings()
        {
            ShowMenu();
        }

        private void RefreshSettingsNavigationButtons()
        {
            bool openedFromMainMenu = stateBeforeSettings == GameState.Menu
                || stateBeforeSettings == GameState.ModeSelect
                || stateBeforeSettings == GameState.StoryLevels;
            bool showBackPlatform = openedFromMainMenu && !transitioningToGame && !gameOver;

            if (settingsBackPlatformButton != null)
                settingsBackPlatformButton.gameObject.SetActive(showBackPlatform);
            if (settingsReturnMenuButton != null)
                settingsReturnMenuButton.gameObject.SetActive(!showBackPlatform);
        }

