        private UpgradeTab GetForcedTutorialUpgradeTab()
        {
            if (tutorialRepairTechnologyLessonActive || tutorialShieldTechnologyLessonActive)
                return UpgradeTab.Drones;
            if (tutorialModulesTechnologyLessonActive)
                return UpgradeTab.Modules;
            if (tutorialEvolutionTechnologyLessonActive)
                return UpgradeTab.Station;
            return currentUpgradeTab;
        }

        private bool CanOpenUpgradeTabDuringTutorial(UpgradeTab tab)
        {
            if (IsTutorialCompleted())
                return true;
            if (!IsTutorialTechnologyLessonActive())
                return false;
            return tab == GetForcedTutorialUpgradeTab();
        }

        private bool BlockTutorialPurchaseUnless(bool allowed, string requiredStep)
        {
            if (testMode)
                return false;

            if (IsTutorialCompleted())
                return false;
            if (!IsTutorialTechnologyLessonActive())
            {
                if (statusText != null)
                    statusText.text = L("status.complete_tutorial");
                return true;
            }
            if (allowed)
                return false;

            if (statusText != null)
                statusText.text = requiredStep;
            RefreshUpgradeLabels();
            return true;
        }

