        private void UpdateTopNavigationButtons()
        {
            bool modalOverlayActive = IsModalOverlayActive();
            bool menuContext = !modalOverlayActive && !stationControlOpen && (state == GameState.Menu || state == GameState.Settings || menuHangarOpen);
            if (topSettingsButton != null)
                topSettingsButton.gameObject.SetActive(menuContext);
            if (topStationButton != null)
            {
                bool baseContext = !modalOverlayActive && state == GameState.Playing && !gameOver && !transitioningToGame && !stationControlOpen && IsOrbDockedOnBaseShip();
                topStationButton.gameObject.SetActive(!modalOverlayActive && !stationControlOpen && (ShouldShowMenuHangarControls() || baseContext));
            }
        }

