        private void ApplyPrimaryTutorialMenuState()
        {
            bool tutorialComplete = IsTutorialCompleted();
            SetMenuButtonVisible(upgradeButtonRoot, tutorialComplete);
            SetMenuButtonVisible(ozCoreMinerSendButtonRoot, tutorialComplete && ozCoreMinerOwned);
            SetMenuButtonVisible(menuHangarButtonRoot, tutorialComplete);
            SetMenuButtonVisible(bestiaryButtonRoot, false);

            if (startButtonRoot != null && !modeSelectOpen && !storyLevelsOpen)
            {
                startButtonRoot.gameObject.SetActive(true);
                TextMeshProUGUI startText = startButtonRoot.GetComponentInChildren<TextMeshProUGUI>(true);
                if (startText != null)
                    startText.text = tutorialComplete ? L("menu.start") : L("tutorial_intro.title");
            }

            if (!tutorialComplete)
            {
                if (menuBestText != null)
                    menuBestText.gameObject.SetActive(false);
                if (ozCoreMinerDrone != null)
                    ozCoreMinerDrone.gameObject.SetActive(false);
                HideRuntimeDrones();
                HideCraftProgress();
                UpdateCrafterCraftSound(false);
                UpdateGeneratorShieldChargeSound(false);
            }
        }

