        private static void SetBarVisible(RectTransform fill, bool visible)
        {
            if (fill == null)
                return;

            Transform track = fill.parent;
            if (track != null && string.Equals(track.name, "Socket", System.StringComparison.Ordinal))
                track = track.parent;

            if (track != null)
                track.gameObject.SetActive(visible);
        }

        private void BeginRun(GameMode mode)
        {
            if (transitioningToGame)
                return;

            if (!IsTutorialCompleted() && (mode != GameMode.Story || selectedStoryLevel != StoryLevel.Tutorial))
            {
                ShowTutorialIntroDialog();
                return;
            }

            Time.timeScale = 1f;
            selectedMode = mode;
            modeSelectOpen = false;
            storyLevelsOpen = false;
            LaunchMenuDronesOut();
            HideRuntimeDrones();
            stationControlOpen = false;
            if (stationControlRoot != null)
                stationControlRoot.gameObject.SetActive(false);
            ResetRunData(false);
            ApplyStorageDepotStartParts();
            if (mode == GameMode.Story && selectedStoryLevel == StoryLevel.Tutorial && coreCannon != null)
                coreCannon.gameObject.SetActive(false);
            ResetBaseHangarRevealImmediate();
            SetGameplayHudVisible(true);
            if (upgradeRoot != null)
                upgradeRoot.gameObject.SetActive(false);
            if (settingsRoot != null)
                settingsRoot.gameObject.SetActive(false);
            if (storyLevelsRoot != null)
                storyLevelsRoot.gameObject.SetActive(false);
            if (gameOverOverlay != null)
                gameOverOverlay.SetActive(false);
            if (tutorialResultOverlay != null)
                tutorialResultOverlay.SetActive(false);
            StartCoroutine(StartRunRoutine(mode));
        }

        private void ApplyStorageDepotStartParts()
        {
            if (!storageDepotOwned || testMode)
                return;

            int previousParts = ozParts;
            ozParts = Mathf.Max(ozParts, StorageDepotStartParts);
            if (ozParts == previousParts)
                return;

            PlayerPrefs.SetInt(OzPartsKey, ozParts);
            PlayerPrefs.Save();
            RefreshHud();
            RefreshUpgradeLabels();
            if (statusText != null)
                statusText.text = LF("status.storage_start_parts", ozParts - previousParts);
        }

        private IEnumerator StartRunRoutine(GameMode mode)
        {
            transitioningToGame = true;
            state = GameState.Playing;
            if (statusText != null)
                statusText.text = mode == GameMode.Endless ? "ENDLESS DRIFT" : StoryRunTitle();

            float startY = orbY;
            float endY = ResolveGameOrbY();
            float startScale = orbScale;
            float endScale = CurrentOrbBaseScale();
            StartCoroutine(FlyMenuAwayRoutine());
            yield return FlyTitleIntoOrbRoutine();
            float duration = 0.86f;
            float t = 0f;
            while (t < duration)
            {
                t += Time.deltaTime;
                float p = Mathf.Clamp01(t / duration);
                float eased = Mathf.SmoothStep(0f, 1f, p);
                laneX = Mathf.Lerp(laneX, 0f, eased);
                targetLaneX = 0f;
                orbY = Mathf.Lerp(startY, endY, eased);
                targetOrbY = orbY;
                orbScale = Mathf.Lerp(startScale, endScale, eased);
                targetOrbScale = orbScale;
                ApplyOrbScale();
                yield return null;
            }

            orbY = endY;
            targetOrbY = endY;
            orbScale = endScale;
            targetOrbScale = endScale;
            ApplyOrbScale();
            spawnTimer = mode == GameMode.Endless ? 0.45f : 0.75f;
            formationTimer = mode == GameMode.Endless ? 0.35f : Mathf.Min(4.2f, FormationWarmupSeconds * 0.35f) + RandomRange(0.4f, 1.2f);
            specialMineTimer = mode == GameMode.Endless ? RandomRange(3.5f, 5.8f) : RandomRange(5.8f, 8.5f);
            forwardDefenseTimer = ForwardDefenseFirstDelay;
            storyWaveTimer = 0f;
            storyWaveBreakTimer = 0f;
            storyWaveIndex = mode == GameMode.Story ? 1 : 0;
            minesBossSpawnTimer = StoryMinesBossMineInterval();
            minesBossBaseY = StoryMinesBossSpawnY;
            minesBossTargetY = StoryMinesBossSpawnY;
            minesBossActive = false;
            minesBossBarrelIndex = 0;
            minesBossPhaseIndex = 0;
            minesBossPhaseTimer = 0f;
            minesBossDamageable = false;
            minesBossPhaseWaitingForClear = false;
            minesBossSpawnShakeTimer = 0f;
            minesBossShortCircuitTimer = 0f;
            transitioningToGame = false;

            if (mode == GameMode.Story && selectedStoryLevel == StoryLevel.Mines)
                StartCoroutine(StoryMinesIntroRoutine());
            else if (mode == GameMode.Story && selectedStoryLevel == StoryLevel.ForwardDefense)
                StartCoroutine(StoryForwardDefenseIntroRoutine());
            else if (mode == GameMode.Story && selectedStoryLevel == StoryLevel.Tutorial)
                StartCoroutine(StoryTutorialIntroRoutine());
        }

        private IEnumerator FlyTitleIntoOrbRoutine()
        {
            if (gameTitleText == null || gameTitleRoot == null)
                yield break;

            string title = "ORBIOSIS";
            Vector2 titleCenter = gameTitleRoot.anchoredPosition;
            gameTitleRoot.gameObject.SetActive(false);
            if (gameLogoRoot != null)
            {
                titleCenter = gameLogoRoot.anchoredPosition;
                gameLogoRoot.gameObject.SetActive(false);
            }

            RectTransform parent = canvas.transform as RectTransform;
            List<TextMeshProUGUI> letters = new List<TextMeshProUGUI>(title.Length);
            float spacing = 46f;
            float duration = 0.50f;
            float t = 0f;
            Vector2[] starts = new Vector2[title.Length];
            Vector2[] scatters = new Vector2[title.Length];

            for (int i = 0; i < title.Length; i++)
            {
                TextMeshProUGUI letter = CreateText(parent, "TitleLetter" + i, title[i].ToString(), 76f, FontStyles.Bold, Ink);
                RectTransform rect = letter.rectTransform;
                rect.anchorMin = new Vector2(0.5f, 0.5f);
                rect.anchorMax = new Vector2(0.5f, 0.5f);
                rect.pivot = new Vector2(0.5f, 0.5f);
                rect.sizeDelta = new Vector2(58f, 86f);
                starts[i] = titleCenter + new Vector2((i - (title.Length - 1) * 0.5f) * spacing, 0f);
                float side = i < title.Length * 0.5f ? -1f : 1f;
                scatters[i] = starts[i] + new Vector2(side * (42f + i * 5f), (i % 2 == 0 ? 34f : -28f));
                rect.anchoredPosition = starts[i];
                letters.Add(letter);
            }

            while (t < duration)
            {
                t += Time.deltaTime;
                float p = Mathf.Clamp01(t / duration);
                Vector2 target = new Vector2(laneX, orbY);

                for (int i = 0; i < letters.Count; i++)
                {
                    if (letters[i] == null)
                        continue;

                    RectTransform rect = letters[i].rectTransform;
                    if (p < 0.42f)
                    {
                        float outP = Mathf.SmoothStep(0f, 1f, p / 0.42f);
                        rect.anchoredPosition = Vector2.Lerp(starts[i], scatters[i], outP);
                    }
                    else
                    {
                        float inP = Mathf.SmoothStep(0f, 1f, (p - 0.42f) / 0.58f);
                        rect.anchoredPosition = Vector2.Lerp(scatters[i], target, inP);
                        rect.localScale = Vector3.one * Mathf.Lerp(1f, 0.25f, inP);
                    }
                }

                yield return null;
            }

            for (int i = 0; i < letters.Count; i++)
            {
                if (letters[i] != null)
                    Destroy(letters[i].gameObject);
            }
        }

        private IEnumerator FlyMenuAwayRoutine()
        {
            if (menuRoot == null)
                yield break;

            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            float width = root != null ? root.rect.width : 900f;
            float duration = 0.42f;
            float t = 0f;
            List<RectTransform> items = new List<RectTransform>();
            for (int i = 0; i < menuRoot.childCount; i++)
            {
                if (menuRoot.GetChild(i) is RectTransform child && child.gameObject.activeSelf)
                    items.Add(child);
            }

            Vector2[] startPositions = new Vector2[items.Count];
            for (int i = 0; i < items.Count; i++)
                startPositions[i] = items[i].anchoredPosition;

            while (t < duration)
            {
                t += Time.deltaTime;
                float p = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(t / duration));
                for (int i = 0; i < items.Count; i++)
                {
                    if (items[i] == null)
                        continue;

                    float direction = i % 2 == 0 ? -1f : 1f;
                    items[i].anchoredPosition = startPositions[i] + new Vector2(direction * (width * 0.75f + 260f) * p, 0f);
                }

                yield return null;
            }

            SetMenuVisible(false);
            for (int i = 0; i < items.Count; i++)
            {
                if (items[i] != null)
                    items[i].anchoredPosition = startPositions[i];
            }
        }

