        private void StopDefeatFlowRoutines()
        {
            if (defeatFlowRoutine != null)
            {
                StopCoroutine(defeatFlowRoutine);
                defeatFlowRoutine = null;
            }
            if (hangarRecoveryReturnRoutine != null)
            {
                StopCoroutine(hangarRecoveryReturnRoutine);
                hangarRecoveryReturnRoutine = null;
            }
        }

        private string StoryRunTitle()
        {
            if (selectedStoryLevel == StoryLevel.Mines)
                return "MINES - " + StoryDifficultyLabel(selectedStoryDifficulty) + " - WAVE " + Mathf.Clamp(storyWaveIndex, 1, StoryMinesWaveCount) + "/10";
            if (selectedStoryLevel == StoryLevel.ForwardDefense)
                return "FORWARD DEFENSE - " + StoryDifficultyLabel(selectedStoryDifficulty) + " - WAVE " + Mathf.Clamp(storyWaveIndex, 1, StoryForwardDefenseWaveCount) + "/" + StoryForwardDefenseWaveCount;

            return "TUTORIAL - FIRST SYMBIOSIS";
        }

        private static string StoryDifficultyLabel(StoryDifficulty difficulty)
        {
            switch (difficulty)
            {
                case StoryDifficulty.Medium:
                    return "MEDIUM";
                case StoryDifficulty.Hardcore:
                    return "HARDCORE";
                default:
                    return "EASY";
            }
        }

        private float StoryDifficultyMultiplier()
        {
            switch (selectedStoryDifficulty)
            {
                case StoryDifficulty.Medium:
                    return 1.05f;
                case StoryDifficulty.Hardcore:
                    return 1.42f;
                default:
                    return 0.62f;
            }
        }

        private float StoryMinesFirstWaveDelay()
        {
            switch (selectedStoryDifficulty)
            {
                case StoryDifficulty.Medium:
                    return StoryMinesFirstWaveDelayMedium;
                case StoryDifficulty.Hardcore:
                    return StoryMinesFirstWaveDelayHardcore;
                default:
                    return StoryMinesFirstWaveDelayEasy;
            }
        }

        private float StoryMinesWaveBreakSeconds()
        {
            switch (selectedStoryDifficulty)
            {
                case StoryDifficulty.Medium:
                    return StoryMinesWaveBreakMedium;
                case StoryDifficulty.Hardcore:
                    return StoryMinesWaveBreakHardcore;
                default:
                    return StoryMinesWaveBreakEasy;
            }
        }

        private float ResolveStoryMinesDifficulty()
        {
            float waveProgress = StoryMinesWaveCount <= 1 ? 0f : Mathf.Clamp01((storyWaveIndex - 1f) / (StoryMinesWaveCount - 1f));
            float withinWave = Mathf.Clamp01(storyWaveTimer / Mathf.Max(1f, StoryMinesWaveSeconds));
            return Mathf.Clamp01((0.08f + waveProgress * 0.58f + withinWave * 0.10f) * StoryDifficultyMultiplier());
        }

        private float StoryMinesFormationInterval(float difficulty)
        {
            switch (selectedStoryDifficulty)
            {
                case StoryDifficulty.Medium:
                    return Mathf.Lerp(4.2f, 2.9f, difficulty);
                case StoryDifficulty.Hardcore:
                    return Mathf.Lerp(3.4f, 2.2f, difficulty);
                default:
                    return Mathf.Lerp(4.9f, 3.45f, difficulty);
            }
        }

        private float StoryMinesSoloSpawnInterval(float difficulty)
        {
            switch (selectedStoryDifficulty)
            {
                case StoryDifficulty.Medium:
                    return Mathf.Lerp(3.8f, 2.8f, difficulty);
                case StoryDifficulty.Hardcore:
                    return Mathf.Lerp(2.9f, 2.0f, difficulty);
                default:
                    return Mathf.Lerp(5.0f, 3.7f, difficulty);
            }
        }

        private float StoryMinesSpecialMineInterval(float difficulty)
        {
            switch (selectedStoryDifficulty)
            {
                case StoryDifficulty.Medium:
                    return Mathf.Lerp(9.0f, 6.2f, difficulty);
                case StoryDifficulty.Hardcore:
                    return Mathf.Lerp(6.4f, 4.4f, difficulty);
                default:
                    return Mathf.Lerp(13.5f, 9.5f, difficulty);
            }
        }

        private bool StoryMinesAllowSoloSpawns()
        {
            switch (selectedStoryDifficulty)
            {
                case StoryDifficulty.Medium:
                    return storyWaveIndex >= 4;
                case StoryDifficulty.Hardcore:
                    return storyWaveIndex >= 3;
                default:
                    return storyWaveIndex >= 5;
            }
        }

        private bool StoryMinesAllowSpecialMine()
        {
            switch (selectedStoryDifficulty)
            {
                case StoryDifficulty.Medium:
                    return storyWaveIndex >= 4;
                case StoryDifficulty.Hardcore:
                    return storyWaveIndex >= 3;
                default:
                    return storyWaveIndex >= 6;
            }
        }

        private int StoryMinesFormationCount(float difficulty)
        {
            int baseCount;
            switch (selectedStoryDifficulty)
            {
                case StoryDifficulty.Medium:
                    baseCount = 5 + Mathf.FloorToInt(difficulty * 2.8f);
                    break;
                case StoryDifficulty.Hardcore:
                    baseCount = 6 + Mathf.FloorToInt(difficulty * 2.2f);
                    break;
                default:
                    baseCount = storyWaveIndex <= 2 ? 4 : 5 + Mathf.FloorToInt(difficulty * 1.8f);
                    break;
            }

            return Mathf.Clamp(baseCount, 3, 7);
        }

        private float StoryMinesBossMineInterval()
        {
            switch (selectedStoryDifficulty)
            {
                case StoryDifficulty.Medium:
                    return StoryMinesBossMineIntervalMedium;
                case StoryDifficulty.Hardcore:
                    return StoryMinesBossMineIntervalHardcore;
                default:
                    return StoryMinesBossMineIntervalEasy;
            }
        }

        private float StoryMinesBossMaxHealth()
        {
            switch (selectedStoryDifficulty)
            {
                case StoryDifficulty.Medium:
                    return StoryMinesBossHealthMedium;
                case StoryDifficulty.Hardcore:
                    return StoryMinesBossHealthHardcore;
                default:
                    return StoryMinesBossHealthEasy;
            }
        }

        private static Vector2 MinesBossUiSize(bool closeUp)
        {
            float width = closeUp ? MinesBossCloseUpWidth : MinesBossNormalWidth;
            return new Vector2(width, width / MinesBossSpriteAspectRatio);
        }

        private float StoryMinesBossPhaseY(int phase)
        {
            switch (Mathf.Clamp(phase, 0, StoryMinesBossPhaseCount))
            {
                case 1:
                    return 135f;
                case 2:
                    return 100f;
                case 3:
                    return StoryMinesBossCloseUpY;
                default:
                    return 170f;
            }
        }

