        private void EnsureStoryCinematicBoss(Vector2 size, Vector2 position)
        {
            if (storyCinematicBoss == null)
            {
                GameObject go = new GameObject("StoryMinesCarrierCinematic", typeof(RectTransform), typeof(CanvasRenderer), typeof(Image));
                go.transform.SetParent(playfield, false);
                storyCinematicBoss = go.GetComponent<RectTransform>();
                storyCinematicBoss.anchorMin = new Vector2(0.5f, 1f);
                storyCinematicBoss.anchorMax = new Vector2(0.5f, 1f);
                storyCinematicBoss.pivot = new Vector2(0.5f, 0.5f);

                Image image = go.GetComponent<Image>();
                image.raycastTarget = false;
                Sprite bossSprite = GetSpriteFromTextureResource(MinesBossSpriteResourcePath);
                if (bossSprite != null)
                {
                    image.sprite = bossSprite;
                    image.color = Color.white;
                    image.preserveAspect = true;
                }
                else
                {
                    image.color = new Color(0.20f, 0.02f, 0.04f, 0.92f);
                    AddOutline(storyCinematicBoss, new Color(1f, 0.12f, 0.08f, 0.65f), new Vector2(3f, -3f));
                }
            }

            storyCinematicBoss.sizeDelta = size;
            storyCinematicBoss.anchoredPosition = position;
            storyCinematicBoss.gameObject.SetActive(true);
            storyCinematicBoss.SetAsLastSibling();
        }

        private void CleanupStoryCinematicBoss()
        {
            if (storyCinematicBoss != null)
                Destroy(storyCinematicBoss.gameObject);

            storyCinematicBoss = null;
        }

        private IEnumerator MoveStoryCinematicBoss(Vector2 target, float duration)
        {
            if (storyCinematicBoss == null)
                yield break;

            Vector2 start = storyCinematicBoss.anchoredPosition;
            float t = 0f;
            while (t < duration)
            {
                t += Time.deltaTime;
                float p = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(t / duration));
                storyCinematicBoss.anchoredPosition = Vector2.Lerp(start, target, p);
                yield return null;
            }

            storyCinematicBoss.anchoredPosition = target;
        }

        private IEnumerator MoveMinesBoss(Vector2 target, float duration)
        {
            if (minesBoss == null)
                yield break;

            Vector2 start = minesBoss.anchoredPosition;
            float t = 0f;
            while (t < duration)
            {
                t += Time.deltaTime;
                float p = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(t / duration));
                minesBoss.anchoredPosition = Vector2.Lerp(start, target, p);
                yield return null;
            }

            minesBoss.anchoredPosition = target;
        }

        private IEnumerator StoryTutorialIntroRoutine()
        {
            storyCinematicActive = true;
            storyMinesWavesStarted = false;
            storyBossFinalWarningPlayed = false;
            storyDialogueAdvanceRequested = false;
            CleanupStoryCinematicBoss();
            CleanupTutorialCinematicObjects();
            SetTutorialPlayfieldZoom(1f);
            tutorialCoreCannonRevealed = false;
            tutorialCoreCannonManualAim = false;
            if (coreCannon != null)
                coreCannon.gameObject.SetActive(false);
            SetOrbDeploymentStage(OrbDeploymentStage.Flight);
            baseShipDeploymentBlend = 0f;
            ResetBaseHangarRevealImmediate();
            if (statusText != null)
                statusText.text = "TUTORIAL - RETREAT VECTOR";

            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            float width = root != null ? root.rect.width : 900f;
            float height = root != null ? root.rect.height : 1600f;
            float cinematicCenterY = height * 0.12f;
            Vector2 orbStart = new Vector2(0f, height * 0.42f);
            Vector2 orbMeet = new Vector2(0f, cinematicCenterY);
            Vector2[] droneStart =
            {
                new Vector2(-145f, -height * 0.38f),
                new Vector2(0f, -height * 0.44f),
                new Vector2(145f, -height * 0.38f)
            };
            Vector2[] droneMeet =
            {
                orbMeet + new Vector2(-110f, -96f),
                orbMeet + new Vector2(0f, -122f),
                orbMeet + new Vector2(110f, -96f)
            };

            PrepareTutorialCinematicDrone(crafterDrone, CrafterDroneSpriteResourcePath, droneStart[0], 1.12f);
            PrepareTutorialCinematicDrone(generatorDrone, GeneratorDroneSpriteResourcePath, droneStart[1], 1.08f);
            PrepareTutorialCinematicDrone(repairDrone, RepairDroneSpriteResourcePath, droneStart[2], 1.08f);

            laneX = 0f;
            targetLaneX = 0f;
            orbY = orbStart.y;
            targetOrbY = orbY;
            orbScale = 1.12f * CurrentOrbBaseScale();
            targetOrbScale = orbScale;
            ApplyOrbScale();

            Vector2[] enemyStarts =
            {
                new Vector2(-width * 0.36f, height * 0.60f),
                new Vector2(-width * 0.14f, height * 0.55f),
                new Vector2(width * 0.12f, height * 0.58f),
                new Vector2(width * 0.34f, height * 0.52f),
                new Vector2(-width * 0.30f, -height * 0.60f),
                new Vector2(-width * 0.06f, -height * 0.55f),
                new Vector2(width * 0.18f, -height * 0.58f),
                new Vector2(width * 0.38f, -height * 0.53f)
            };
            Vector2[] enemyEnds =
            {
                new Vector2(-230f, cinematicCenterY + 165f),
                new Vector2(-72f, cinematicCenterY + 195f),
                new Vector2(90f, cinematicCenterY + 178f),
                new Vector2(245f, cinematicCenterY + 138f),
                new Vector2(-235f, cinematicCenterY - 185f),
                new Vector2(-72f, cinematicCenterY - 210f),
                new Vector2(92f, cinematicCenterY - 193f),
                new Vector2(248f, cinematicCenterY - 160f)
            };

            for (int i = 0; i < enemyStarts.Length; i++)
                tutorialCinematicEnemies.Add(CreateTutorialCinematicEnemy("TutorialPincerMine" + i, enemyStarts[i], i));

            float retreatDuration = 5.4f;
            float t = 0f;
            while (t < retreatDuration)
            {
                t += Time.deltaTime;
                float p = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(t / retreatDuration));
                orbY = Mathf.Lerp(orbStart.y, orbMeet.y, p);
                targetOrbY = orbY;
                orbScale = Mathf.Lerp(1.12f, 0.92f, p) * CurrentOrbBaseScale();
                targetOrbScale = orbScale;
                ApplyOrbScale();

                MoveTutorialCinematicDrone(crafterDrone, Vector2.Lerp(droneStart[0], droneMeet[0], p), 1.12f, orbMeet);
                MoveTutorialCinematicDrone(generatorDrone, Vector2.Lerp(droneStart[1], droneMeet[1], p), 1.08f, orbMeet);
                MoveTutorialCinematicDrone(repairDrone, Vector2.Lerp(droneStart[2], droneMeet[2], p), 1.08f, orbMeet);

                for (int i = 0; i < tutorialCinematicEnemies.Count; i++)
                {
                    RectTransform enemy = tutorialCinematicEnemies[i];
                    if (enemy == null)
                        continue;

                    enemy.anchoredPosition = Vector2.Lerp(enemyStarts[i], enemyEnds[i], p);
                    enemy.Rotate(0f, 0f, (i % 2 == 0 ? -150f : 150f) * Time.deltaTime);
                }

                yield return null;
            }

            ShowStoryDialog(L("speaker.crafter"), L("dialog.tutorial_1"), null);
            yield return WaitStoryDialogSeconds(2.8f);
            ShowPlayerStoryDialog(L("dialog.tutorial_2"), null);
            yield return WaitStoryDialogSeconds(2.8f);
            ShowStoryDialog(L("speaker.repair"), L("dialog.tutorial_3"), null);
            yield return WaitStoryDialogSeconds(2.5f);
            ShowStoryDialog(L("speaker.crafter"), L("dialog.tutorial_4"), null);
            yield return WaitStoryDialogSeconds(2.5f);
            ShowPlayerStoryDialog(L("dialog.tutorial_first_symbiosis"), L("dialog.tutorial_first_symbiosis_button"));
            yield return WaitStoryDialogButton();
            HideStoryDialog();

            yield return MergeTutorialDronesIntoOrb(orbMeet, droneMeet);
            yield return RevealTutorialCoreCannonRoutine();

            ShowPlayerStoryDialog(L("dialog.tutorial_docked"), null);
            yield return WaitStoryDialogSeconds(1.35f);
            HideStoryDialog();

            yield return TutorialOrbVolleyRoutine(orbMeet);
            tutorialCannonSuppressed = true;
            coreCannonAimed = false;
            fireTimer = 999f;

            CleanupTutorialCinematicObjects();
            HideRuntimeDrones();

            SetOrbDeploymentStage(OrbDeploymentStage.Flight);
            baseShipDeploymentBlend = 0f;
            if (statusText != null)
                statusText.text = "SYMBIOSIS ONLINE - BASE SIGNAL FOUND";

            ShowStoryDialog(L("speaker.crafter"), L("dialog.tutorial_base_1"), null);
            yield return WaitStoryDialogSeconds(2.6f);
            ShowStoryDialog(L("speaker.crafter"), L("dialog.tutorial_base_2"), null);
            yield return WaitStoryDialogSeconds(3.0f);
            tutorialBaseRevealed = true;
            ShowStoryDialog(L("speaker.crafter"), L("dialog.tutorial_base_3"), L("dialog.tutorial_land_button"));
            yield return WaitStoryDialogButton();
            HideStoryDialog();

            storyCinematicActive = false;
            if (statusText != null)
                statusText.text = "DRAG ORB TO THE BASE DOCK";
            yield return WaitTutorialOrbDocked();

            storyCinematicActive = true;
            yield return TutorialRepairOrbitRoutine();

            ShowStoryDialog(L("speaker.crafter"), L("dialog.tutorial_takeoff_1"), L("dialog.tutorial_takeoff_button"));
            yield return WaitStoryDialogButton();
            HideStoryDialog();

            storyCinematicActive = false;
            BeginTutorialMaterialCollection();
            if (statusText != null)
                statusText.text = "ENEMY FORMATION ABOVE - PULL ORB UP";
            yield return WaitTutorialOrbUndocked();
            yield return TutorialMaterialCollectionRoutine();
        }

        private void PrepareTutorialCinematicDrone(RectTransform drone, string spritePath, Vector2 position, float scale)
        {
            if (drone == null)
                return;

            ApplySpriteFromTextureResource(drone, spritePath);
            drone.anchoredPosition = position;
            drone.localScale = Vector3.one * scale;
            drone.gameObject.SetActive(true);
            drone.SetAsLastSibling();
        }

        private static void MoveTutorialCinematicDrone(RectTransform drone, Vector2 position, float scale, Vector2 lookTarget)
        {
            if (drone == null)
                return;

            Vector2 previous = drone.anchoredPosition;
            drone.anchoredPosition = position;
            drone.localScale = Vector3.one * scale;
            FaceDroneToward(drone, previous, lookTarget, Mathf.Sin(Time.time * 16f) * 3.5f);
        }

        private RectTransform CreateTutorialCinematicEnemy(string name, Vector2 position, int variant)
        {
            RectTransform enemy = CreateImage(playfield, name, Color.white).rectTransform;
            enemy.anchorMin = new Vector2(0.5f, 0.5f);
            enemy.anchorMax = new Vector2(0.5f, 0.5f);
            enemy.pivot = new Vector2(0.5f, 0.5f);
            float size = variant % 3 == 0 ? 104f : variant % 3 == 1 ? 86f : 96f;
            enemy.sizeDelta = new Vector2(size, size);
            enemy.anchoredPosition = position;
            string spritePath = variant % 4 == 0 ? HeavyEnemyMineSpriteResourcePath : variant % 3 == 0 ? HomingEnemyMineSpriteResourcePath : EnemyMineSpriteResourcePath;
            if (!ApplySpriteFromTextureResource(enemy, spritePath))
                AddEnemyWingMarks(enemy);
            AddOutline(enemy, new Color(1f, 0.12f, 0.08f, 0.52f), new Vector2(3f, -3f));
            enemy.SetAsLastSibling();
            return enemy;
        }

        private IEnumerator MergeTutorialDronesIntoOrb(Vector2 orbPosition, Vector2[] droneStarts)
        {
            RectTransform[] drones = { crafterDrone, generatorDrone, repairDrone };
            float duration = 1.15f;
            float t = 0f;
            while (t < duration)
            {
                t += Time.deltaTime;
                float p = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(t / duration));
                for (int i = 0; i < drones.Length; i++)
                {
                    RectTransform drone = drones[i];
                    if (drone == null)
                        continue;

                    Vector2 start = i < droneStarts.Length ? droneStarts[i] : drone.anchoredPosition;
                    Vector2 orbit = new Vector2(Mathf.Cos((p * 5.2f) + i * 2.1f) * 34f, Mathf.Sin((p * 5.2f) + i * 2.1f) * 22f) * (1f - p);
                    drone.anchoredPosition = Vector2.Lerp(start, orbPosition, p) + orbit;
                    drone.localScale = Vector3.one * Mathf.Lerp(1.08f, 0.18f, p);
                    FaceDroneToward(drone, drone.anchoredPosition, orbPosition, 0f);
                    SpawnArcSegment(drone.anchoredPosition, orbPosition, 0.20f + p * 0.38f, 2.6f);
                }

                orbRepairFlashTimer = Mathf.Max(orbRepairFlashTimer, 0.32f);
                yield return null;
            }

            for (int i = 0; i < drones.Length; i++)
            {
                if (drones[i] != null)
                    drones[i].gameObject.SetActive(false);
            }
        }

        private IEnumerator RevealTutorialCoreCannonRoutine()
        {
            tutorialCoreCannonRevealed = true;
            if (coreCannon == null || orb == null)
                yield break;

            coreCannon.gameObject.SetActive(true);
            ApplySpriteFromTextureResource(coreCannon, CoreCannonSpriteResourcePath);
            BringCoreCannonToFront();

            float revealStartScale = Mathf.Max(0.1f, orbScale);
            float revealZoomScale = Mathf.Max(revealStartScale, 1.24f * CurrentOrbBaseScale());
            float playfieldStartZoom = tutorialCinematicPlayfieldZoom;
            float playfieldTargetZoom = 1.10f;
            Vector2 start = orb.anchoredPosition + new Vector2(0f, -8f) * Mathf.Max(0.1f, orbScale);
            Vector2 target = orb.anchoredPosition + CoreCannonCenterOffset * Mathf.Max(0.1f, orbScale);
            float duration = 0.72f;
            float t = 0f;
            while (t < duration)
            {
                t += Time.deltaTime;
                float p = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(t / duration));
                SetTutorialPlayfieldZoom(Mathf.Lerp(playfieldStartZoom, playfieldTargetZoom, p));
                SetTutorialOrbCannonZoom(Mathf.Lerp(revealStartScale, revealZoomScale, p));
                target = orb.anchoredPosition + CoreCannonCenterOffset * Mathf.Max(0.1f, orbScale);
                coreCannon.anchoredPosition = Vector2.Lerp(start, target, p);
                coreCannon.localRotation = Quaternion.identity;
                coreCannon.localScale = Vector3.one * Mathf.Max(0.1f, orbScale) * Mathf.Lerp(0.18f, 1.08f, p);
                Image image = coreCannon.GetComponent<Image>();
                if (image != null)
                    image.color = Color.Lerp(new Color(0.30f, 1f, 1f, 0.20f), Color.white, p);
                SpawnArcSegment(orb.anchoredPosition, coreCannon.anchoredPosition, 0.16f + p * 0.32f, 2.2f);
                orbRepairFlashTimer = Mathf.Max(orbRepairFlashTimer, 0.22f);
                yield return null;
            }

            coreCannon.anchoredPosition = target;
            coreCannon.localScale = Vector3.one * Mathf.Max(0.1f, orbScale);
            coreCannon.localRotation = Quaternion.identity;
            Image finalImage = coreCannon.GetComponent<Image>();
            if (finalImage != null)
                finalImage.color = Color.white;
            yield return new WaitForSeconds(0.18f);
        }

        private IEnumerator TutorialOrbVolleyRoutine(Vector2 origin)
        {
            float volleyZoomScale = Mathf.Max(orbScale, 1.24f * CurrentOrbBaseScale());
            for (float zoomT = 0f; zoomT < 0.22f; zoomT += Time.deltaTime)
            {
                SetTutorialOrbCannonZoom(Mathf.Lerp(orbScale, volleyZoomScale, Mathf.Clamp01(zoomT / 0.22f)));
                SetTutorialPlayfieldZoom(Mathf.Lerp(tutorialCinematicPlayfieldZoom, 1.10f, Mathf.Clamp01(zoomT / 0.22f)));
                yield return null;
            }

            SetTutorialOrbCannonZoom(volleyZoomScale);
            SetTutorialPlayfieldZoom(1.10f);
            tutorialCoreCannonManualAim = true;

            for (int i = tutorialCinematicEnemies.Count - 1; i >= 0; i--)
            {
                RectTransform enemy = tutorialCinematicEnemies[i];
                if (enemy == null)
                    continue;

                Vector2 target = enemy.anchoredPosition;
                Vector2 shotOrigin = origin;
                if (coreCannon != null && coreCannon.gameObject.activeSelf)
                {
                    yield return AimTutorialCoreCannonAt(target, 0.22f, volleyZoomScale);
                    shotOrigin = GetCoreCannonFireOrigin();
                }

                PlayCoreCannonShotSound();
                yield return TutorialCoreCannonShotRoutine(shotOrigin, target, volleyZoomScale);
                SpawnMineExplosion(target);
                PlayEnemyDeathSound();
                Destroy(enemy.gameObject);
                tutorialCinematicEnemies.RemoveAt(i);
                yield return new WaitForSeconds(0.18f);
            }

            yield return new WaitForSeconds(0.65f);
            for (float zoomT = 0f; zoomT < 0.25f; zoomT += Time.deltaTime)
            {
                SetTutorialPlayfieldZoom(Mathf.Lerp(tutorialCinematicPlayfieldZoom, 1f, Mathf.Clamp01(zoomT / 0.25f)));
                yield return null;
            }

            SetTutorialPlayfieldZoom(1f);
            tutorialCoreCannonManualAim = false;
        }

        private void SetTutorialOrbCannonZoom(float scale)
        {
            if (orb == null)
                return;

            orbScale = Mathf.Max(0.1f, scale);
            targetOrbScale = orbScale;
            ApplyOrbScale();
            if (coreCannon != null && coreCannon.gameObject.activeSelf)
                coreCannon.localScale = Vector3.one * orbScale;
        }

        private void SetTutorialPlayfieldZoom(float zoom)
        {
            tutorialCinematicPlayfieldZoom = Mathf.Clamp(zoom, 1f, 1.12f);
            UpdatePlayfieldCameraLayout();
        }

        private IEnumerator AimTutorialCoreCannonAt(Vector2 target, float duration, float zoomScale)
        {
            if (coreCannon == null || !coreCannon.gameObject.activeSelf)
                yield break;

            Vector2 modulePosition = GetCanvasLocalPosition(coreCannon);
            Vector2 direction = ResolveProjectileDirection(modulePosition, target);
            float desiredWorldZ = Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg - 90f;
            float desiredLocalZ = Mathf.DeltaAngle(0f, desiredWorldZ);

            float t = 0f;
            while (t < duration)
            {
                t += Time.deltaTime;
                SetTutorialOrbCannonZoom(zoomScale);
                modulePosition = GetCanvasLocalPosition(coreCannon);
                UpdateWeaponModuleAim(coreCannon, modulePosition, target, 0f, 5f, 11f, 0f, false);
                yield return null;
            }

            for (float holdT = 0f; holdT < 0.08f; holdT += Time.deltaTime)
            {
                SetTutorialOrbCannonZoom(zoomScale);
                coreCannon.localRotation = Quaternion.Euler(0f, 0f, desiredLocalZ);
                yield return null;
            }

            SetTutorialOrbCannonZoom(zoomScale);
            coreCannon.localRotation = Quaternion.Euler(0f, 0f, desiredLocalZ);
        }

        private IEnumerator TutorialCoreCannonShotRoutine(Vector2 from, Vector2 to, float zoomScale)
        {
            if (playfield == null)
                yield break;

            Vector2 direction = to - from;
            float distance = direction.magnitude;
            if (distance < 4f)
                yield break;

            Vector2 forward = direction / distance;
            RectTransform shot = CreatePanel(playfield, "TutorialCoreCannonShot", new Color(0.60f, 1f, 1f, 0.98f));
            shot.anchorMin = new Vector2(0.5f, 0.5f);
            shot.anchorMax = new Vector2(0.5f, 0.5f);
            shot.pivot = new Vector2(0.5f, 0.5f);
            shot.sizeDelta = new Vector2(18f, 54f);
            shot.anchoredPosition = from;
            shot.localRotation = Quaternion.Euler(0f, 0f, Mathf.Atan2(forward.y, forward.x) * Mathf.Rad2Deg - 90f);
            shot.SetAsLastSibling();

            Image image = shot.GetComponent<Image>();
            Sprite projectileSprite = GetSpriteFromTextureResource(OrbProjectileSpriteResourcePath);
            if (image != null)
            {
                if (projectileSprite != null)
                {
                    image.sprite = projectileSprite;
                    image.color = Color.white;
                    image.preserveAspect = true;
                }
                image.raycastTarget = false;
            }

            AddOutline(shot, new Color(1f, 0.88f, 0.30f, 0.52f), new Vector2(2f, -2f));

            float duration = Mathf.Clamp(distance / 1650f, 0.12f, 0.20f);
            float t = 0f;
            while (t < duration)
            {
                t += Time.deltaTime;
                SetTutorialOrbCannonZoom(zoomScale);
                float p = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(t / duration));
                shot.anchoredPosition = Vector2.Lerp(from, to, p);
                shot.localScale = Vector3.one * Mathf.Lerp(1.22f, 0.86f, p);
                yield return null;
            }

            if (shot != null)
                Destroy(shot.gameObject);
        }

        private void SpawnTutorialCoreCannonMuzzleFlash(Vector2 origin, Vector2 direction)
        {
            if (playfield == null)
                return;

            RectTransform flash = CreatePanel(playfield, "TutorialCoreCannonMuzzleFlash", new Color(1f, 0.88f, 0.26f, 0.92f));
            flash.anchorMin = new Vector2(0.5f, 0.5f);
            flash.anchorMax = new Vector2(0.5f, 0.5f);
            flash.pivot = new Vector2(0.5f, 0.5f);
            flash.sizeDelta = new Vector2(42f, 42f);
            flash.anchoredPosition = origin + direction * 8f;
            flash.localRotation = Quaternion.Euler(0f, 0f, Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg - 90f);
            flash.SetAsLastSibling();
            AddOutline(flash, new Color(0.42f, 1f, 1f, 0.55f), new Vector2(2f, -2f));

            arcViews.Add(new ArcView
            {
                Root = flash,
                Image = flash.GetComponent<Image>(),
                Lifetime = 0.12f,
                Age = 0f
            });
        }

        private IEnumerator WaitTutorialOrbDocked()
        {
            while (!IsOrbDockedOnBaseShip())
            {
                if (statusText != null)
                    statusText.text = "DRAG ORB TO THE BASE DOCK";
                yield return null;
            }

            Vector2 dock = ResolveBaseShipDockPosition();
            laneX = dock.x;
            targetLaneX = dock.x;
            orbY = dock.y;
            targetOrbY = dock.y;
            SetOrbDeploymentStage(OrbDeploymentStage.Defender);
            baseShipDeploymentBlend = 1f;
            orbScale = ResolveBaseDockedOrbScale();
            targetOrbScale = orbScale;
            ApplyOrbScale();
            if (statusText != null)
                statusText.text = "ORB LANDED - COMBAT SLOTS ONLINE";
        }

        private IEnumerator WaitTutorialOrbUndocked()
        {
            while (IsOrbDockedOnBaseShip() || IsOrbBaseTransitionLocked())
            {
                if (statusText != null)
                    statusText.text = "PULL ORB UP TO TAKE OFF";
                yield return null;
            }

            if (statusText != null)
                statusText.text = "TAKEOFF CONFIRMED - COLLECT PARTS";
        }

        private IEnumerator TutorialRepairOrbitRoutine()
        {
            Vector2 center = orb != null ? orb.anchoredPosition : ResolveBaseShipDockPosition();
            ShowStoryDialog(L("speaker.crafter"), L("dialog.tutorial_repair_1"), L("dialog.tutorial_repair_button"));
            yield return WaitStoryDialogButton();
            HideStoryDialog();

            const float duration = 5.0f;
            const float orbitRadiusX = 122f;
            const float orbitRadiusY = 84f;
            const float startAngle = -Mathf.PI * 0.72f;
            Vector2 startOffset = new Vector2(Mathf.Cos(startAngle) * orbitRadiusX, Mathf.Sin(startAngle) * orbitRadiusY);
            PrepareTutorialCinematicDrone(crafterDrone, CrafterDroneSpriteResourcePath, center + startOffset, 1.12f);
            if (repairDrone != null)
                repairDrone.gameObject.SetActive(false);
            float timer = 0f;
            while (timer < duration)
            {
                timer = Mathf.Min(duration, timer + Time.deltaTime);
                center = orb != null ? orb.anchoredPosition : center;
                float progress = Mathf.Clamp01(timer / duration);
                float angle = startAngle + progress * Mathf.PI * 2f;
                Vector2 orbitOffset = new Vector2(Mathf.Cos(angle) * orbitRadiusX, Mathf.Sin(angle) * orbitRadiusY);
                Vector2 repairTarget = center + orbitOffset;
                Vector2 inward = orbitOffset.sqrMagnitude > 0.01f ? -orbitOffset.normalized : Vector2.down;
                Vector2 workPoint = center - inward * 44f;

                if (crafterDrone != null)
                {
                    Vector2 previous = crafterDrone.anchoredPosition;
                    crafterDrone.anchoredPosition = repairTarget;
                    crafterDrone.localScale = Vector3.one * (1.12f + Mathf.Sin(progress * Mathf.PI) * 0.04f);
                    crafterDrone.gameObject.SetActive(true);
                    crafterDrone.SetAsLastSibling();
                    FaceDroneToward(crafterDrone, previous, center, 0f);
                    UpdateWeldSparks(true, crafterDrone.anchoredPosition, workPoint);
                }
                orbRepairFlashTimer = Mathf.Max(orbRepairFlashTimer, 0.35f);
                yield return null;
            }

            UpdateWeldSparks(false, Vector2.zero, Vector2.zero);
            if (crafterDrone != null)
                crafterDrone.gameObject.SetActive(false);
            if (statusText != null)
                statusText.text = "CRAFTER FIELD REPAIR COMPLETE";
            yield return new WaitForSeconds(0.45f);
        }

        private IEnumerator TutorialMaterialCollectionRoutine()
        {
            BeginTutorialMaterialCollection();
            while (tutorialMaterialDelivered < tutorialMaterialTarget)
            {
                EnsureTutorialMaterialPartsAvailable();
                if (statusText != null && !tutorialReturnPartsDialogActive)
                {
                    if (GetTutorialMaterialCollectedTotal() >= tutorialMaterialTarget && carriedParts > 0)
                        statusText.text = "PARTS COLLECTED - LAND ON BASE";
                    else if (carriedParts > 0)
                        statusText.text = "RETURN PARTS TO BASE";
                    else if (partDrops.Count > 0)
                        statusText.text = "COLLECT PARTS - THEN LAND ON BASE";
                    else
                        statusText.text = "DESTROY THE FORMATION - PARTS WILL STAY";
                }
                UpdateTutorialMaterialCounter();

                yield return null;
            }

            tutorialMaterialLessonActive = false;
            tutorialReturnPartsDialogActive = false;
            SetTutorialMaterialCounterVisible(false);
            CleanupTutorialMaterialEnemies();
            ShowStoryDialog(L("speaker.crafter"), L("dialog.tutorial_repair_done"), L("dialog.open_technology"));
            yield return WaitStoryDialogButton();
            HideStoryDialog();
            yield return TutorialRepairTechnologyRoutine();
        }

        private void BeginTutorialMaterialCollection()
        {
            if (tutorialMaterialLessonActive)
                return;

            tutorialMaterialLessonActive = true;
            tutorialCannonSuppressed = false;
            fireTimer = 0.12f;
            tutorialMaterialDelivered = 0;
            tutorialMaterialTarget = 10;
            tutorialReturnPartsDialogShown = false;
            tutorialReturnPartsDialogActive = false;
            tutorialReturnPartsDialogConfirmed = false;
            tutorialManualReturnToBaseActive = false;
            tutorialCargoTransferActive = false;
            carriedParts = 0;
            SetTutorialMaterialCounterVisible(true);
            UpdateTutorialMaterialCounter();
            if (statusText != null)
                statusText.text = "FORMATION ABOVE - TAKE OFF AND COLLECT PARTS";
            RefreshHud();

            SpawnTutorialMaterialEnemyWave(1);
        }

        private IEnumerator TutorialReturnPartsDialogRoutine()
        {
            tutorialReturnPartsDialogActive = true;
            yield return new WaitForSeconds(1f);
            ShowStoryDialog(L("speaker.crafter"), L("dialog.tutorial_return_parts"), L("dialog.tutorial_return_button"));
            yield return WaitStoryDialogButton();
            HideStoryDialog();
            tutorialReturnPartsDialogConfirmed = true;
            tutorialReturnPartsDialogActive = false;
            if (statusText != null)
                statusText.text = "RETURN PARTS TO BASE";
        }

        private IEnumerator TutorialCargoTransferRoutine(int unloaded)
        {
            tutorialCargoTransferActive = true;
            unloaded = Mathf.Max(0, unloaded);
            if (statusText != null)
                statusText.text = "TRANSFERRING PARTS TO BASE";
            UpdateTutorialMaterialCounter();

            yield return new WaitForSeconds(0.35f);
            SpawnCargoUnloadViews(unloaded);
            yield return new WaitForSeconds(1.55f);

            ozParts += unloaded;
            carriedParts = 0;
            tutorialMaterialDelivered = Mathf.Min(tutorialMaterialTarget, tutorialMaterialDelivered + unloaded);
            if (tutorialMaterialDelivered >= tutorialMaterialTarget)
                tutorialManualReturnToBaseActive = false;
            UpdateTutorialMaterialCounter();
            PlayerPrefs.SetInt(OzPartsKey, ozParts);
            PlayerPrefs.Save();
            if (statusText != null)
                statusText.text = "BASE MATERIAL " + tutorialMaterialDelivered + "/" + tutorialMaterialTarget;
            RefreshHud();
            RefreshUpgradeLabels();
            tutorialCargoTransferActive = false;
        }

        private IEnumerator TutorialRepairTechnologyRoutine()
        {
            tutorialRepairTechnologyLessonActive = true;
            crafterOwned = true;
            repairOwned = false;

            currentUpgradeTab = UpgradeTab.Drones;
            droneUpgradePage = 1;
            ShowUpgrade();
            ShowDronesUpgradeTab();
            RefreshUpgradeLabels();
            if (statusText != null)
                statusText.text = "TECHNOLOGY > DRONES > BUY REPAIR";

            while (tutorialRepairTechnologyLessonActive && !tutorialRepairHangarLessonActive)
            {
                if (statusText != null)
                    statusText.text = "BUY REPAIR DRONE - FREE";
                yield return null;
            }
        }

        private IEnumerator TutorialEnterRepairHangarRoutine()
        {
            tutorialRepairTechnologyLessonActive = false;
            tutorialRepairHangarLessonActive = true;
            if (upgradeRoot != null)
                upgradeRoot.gameObject.SetActive(false);
            for (int i = 0; i < menuHangarUpgradeButtons.Length; i++)
            {
                if (menuHangarUpgradeButtons[i] != null)
                    menuHangarUpgradeButtons[i].gameObject.SetActive(false);
            }
            if (menuHangarProfileRoot != null)
                menuHangarProfileRoot.gameObject.SetActive(false);
            yield return new WaitForSecondsRealtime(0.25f);

            EnterTutorialRepairHangar();
        }

        private void EnterTutorialRepairHangar()
        {
            Time.timeScale = 1f;
            state = GameState.Menu;
            gameOver = false;
            transitioningToGame = false;
            stationControlOpen = false;
            modeSelectOpen = false;
            storyLevelsOpen = false;
            storyCinematicActive = false;
            pointerControl = false;
            pointerStartedOnUi = false;
            ResetHangarGesture();
            ResetHangarMouseCameraDrag();
            CleanupHazards();
            CleanupTutorialMaterialEnemies();
            HideStoryDialog();
            HideRuntimeDrones();
            SetGameplayHudVisible(false);
            SetMenuVisible(false);
            if (gameTitleRoot != null)
                gameTitleRoot.gameObject.SetActive(false);
            if (gameLogoRoot != null)
                gameLogoRoot.gameObject.SetActive(false);
            if (menuBestText != null)
                menuBestText.gameObject.SetActive(false);
            if (upgradeRoot != null)
                upgradeRoot.gameObject.SetActive(false);
            if (settingsRoot != null)
                settingsRoot.gameObject.SetActive(false);
            if (stationControlRoot != null)
                stationControlRoot.gameObject.SetActive(false);
            if (bestiaryUi != null)
                bestiaryUi.Hide();

            menuHangarOpen = true;
            hangarRecoveryActive = false;
            hangarRecoveryTimer = 0f;
            hangarRecoveryReturningToMenu = false;
            hangarRecoveryCrafterOrbit = RandomRange(0f, Mathf.PI * 2f);
            baseHangarExpanded = true;
            baseHangarRevealTransitioning = false;
            SetHangarRevealOffset(MaxHangarRevealOffset());
            if (menuHangarRoot != null)
                menuHangarRoot.gameObject.SetActive(true);
            if (menuHangarProfileRoot != null)
                menuHangarProfileRoot.gameObject.SetActive(false);

            Vector2 repairCenter = ResolveBaseShipDockPosition();
            laneX = repairCenter.x;
            orbY = repairCenter.y;
            targetLaneX = laneX;
            targetOrbY = orbY;
            orbScale = ResolveMenuHangarDockedOrbScale();
            targetOrbScale = orbScale;
            ApplyOrbScale();
            if (orb != null)
            {
                orb.anchoredPosition = repairCenter;
                orb.localRotation = Quaternion.identity;
                orb.gameObject.SetActive(true);
            }

            SetSharedHealthRatio(0.42f);
            shield = 0;
            carriedParts = 0;
            crafterPosition = ResolveHangarDroneHomePosition(0) + new Vector2(0f, -42f);
            repairPosition = crafterPosition + new Vector2(52f, 12f);
            if (statusText != null)
                statusText.text = "HANGAR - CRAFTER BUILDS REPAIR";
            UpdateMenuHangarDisplay();
        }

        private void SpawnTutorialMaterialEnemyWave(int wave)
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            float height = root != null ? root.rect.height : 1600f;
            float stationY = orb != null ? orb.anchoredPosition.y : ResolveGameOrbY();
            float startY = Mathf.Clamp(stationY + 390f, height * 0.03f, height * 0.36f);
            Vector2[] formation =
            {
                new Vector2(-240f, 76f),
                new Vector2(-120f, 124f),
                new Vector2(0f, 148f),
                new Vector2(120f, 124f),
                new Vector2(240f, 76f),
                new Vector2(-190f, 0f),
                new Vector2(-64f, 30f),
                new Vector2(64f, 30f),
                new Vector2(190f, 0f),
                new Vector2(0f, -54f)
            };

            for (int i = 0; i < formation.Length; i++)
                SpawnTutorialMaterialEnemy(new Vector2(formation[i].x, startY + formation[i].y), wave + i);

            if (statusText != null)
                statusText.text = "FORMATION 10 - COLLECT PARTS FOR BASE";
        }

        private void SpawnTutorialMaterialEnemy(Vector2 position, int variant)
        {
            if (playfield == null)
                return;

            GameObject go = new GameObject("TutorialMaterialEnemy", typeof(RectTransform), typeof(CanvasRenderer), typeof(Image));
            go.transform.SetParent(playfield, false);
            RectTransform rect = go.GetComponent<RectTransform>();
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            float height = root != null ? root.rect.height : 1600f;
            rect.anchorMin = new Vector2(0.5f, 1f);
            rect.anchorMax = new Vector2(0.5f, 1f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = Vector2.one * (variant % 3 == 0 ? 92f : 82f);
            rect.anchoredPosition = position - new Vector2(0f, height * 0.5f);

            Image image = go.GetComponent<Image>();
            image.raycastTarget = false;
            Sprite mineSprite = GetSpriteFromTextureResource(variant % 3 == 0 ? HomingEnemyMineSpriteResourcePath : EnemyMineSpriteResourcePath);
            if (mineSprite != null)
            {
                image.sprite = mineSprite;
                image.color = Color.white;
                image.preserveAspect = true;
            }
            else
            {
                image.color = new Color(0.86f, 0.16f, 0.20f, 1f);
                AddEnemyWingMarks(rect);
            }

            AddOutline(rect, new Color(1f, 0.16f, 0.08f, 0.52f), new Vector2(3f, -3f));
            MarkBestiaryEncounter(OrbiosisBestiaryLibrary.EnemyMine);
            hazards.Add(new HazardView
            {
                Root = rect,
                Image = image,
                Radius = Mathf.Max(rect.sizeDelta.x, rect.sizeDelta.y) * 0.44f,
                Health = 8f,
                Speed = 13f,
                Spin = variant % 2 == 0 ? -95f : 95f,
                TutorialMaterialEnemy = true
            });
        }

        private int CountTutorialMaterialEnemies()
        {
            int count = 0;
            for (int i = 0; i < hazards.Count; i++)
            {
                if (hazards[i] != null && hazards[i].TutorialMaterialEnemy && hazards[i].Root != null)
                    count++;
            }
            return count;
        }

        private void SetTutorialMaterialCounterVisible(bool visible)
        {
            if (tutorialMaterialCounterRoot == null)
                return;

            tutorialMaterialCounterRoot.gameObject.SetActive(visible);
            if (visible)
            {
                tutorialMaterialCounterRoot.SetAsLastSibling();
                UpdateTutorialMaterialCounter();
            }
        }

        private void UpdateTutorialMaterialCounter()
        {
            if (tutorialMaterialCounterText == null)
                return;

            int delivered = Mathf.Clamp(GetTutorialMaterialCollectedTotal(), 0, tutorialMaterialTarget);
            int cargo = Mathf.Max(0, carriedParts);
            tutorialMaterialCounterText.text = LF("tutorial.material_counter", delivered, tutorialMaterialTarget, cargo);
        }

        private float StoryForwardDefenseFirstWaveDelay()
        {
            switch (selectedStoryDifficulty)
            {
                case StoryDifficulty.Medium:
                    return StoryForwardDefenseFirstWaveDelayMedium;
                case StoryDifficulty.Hardcore:
                    return StoryForwardDefenseFirstWaveDelayHardcore;
                default:
                    return StoryForwardDefenseFirstWaveDelayEasy;
            }
        }

        private float StoryForwardDefenseWaveBreakSeconds()
        {
            switch (selectedStoryDifficulty)
            {
                case StoryDifficulty.Medium:
                    return StoryForwardDefenseWaveBreakMedium;
                case StoryDifficulty.Hardcore:
                    return StoryForwardDefenseWaveBreakHardcore;
                default:
                    return StoryForwardDefenseWaveBreakEasy;
            }
        }

        private float ResolveStoryForwardDefenseDifficulty()
        {
            float waveProgress = StoryForwardDefenseWaveCount <= 1 ? 0f : Mathf.Clamp01((storyWaveIndex - 1f) / (StoryForwardDefenseWaveCount - 1f));
            float withinWave = Mathf.Clamp01(storyWaveTimer / Mathf.Max(1f, StoryForwardDefenseWaveSeconds));
            return Mathf.Clamp01((0.18f + waveProgress * 0.64f + withinWave * 0.13f) * StoryDifficultyMultiplier());
        }

        private float StoryForwardDefenseSpawnInterval(float difficulty)
        {
            switch (selectedStoryDifficulty)
            {
                case StoryDifficulty.Medium:
                    return Mathf.Lerp(3.15f, 2.25f, difficulty);
                case StoryDifficulty.Hardcore:
                    return Mathf.Lerp(2.45f, 1.55f, difficulty);
                default:
                    return Mathf.Lerp(4.10f, 2.90f, difficulty);
            }
        }

        private float StoryForwardDefenseSquadInterval(float difficulty)
        {
            switch (selectedStoryDifficulty)
            {
                case StoryDifficulty.Medium:
                    return Mathf.Lerp(6.6f, 4.8f, difficulty);
                case StoryDifficulty.Hardcore:
                    return Mathf.Lerp(5.1f, 3.6f, difficulty);
                default:
                    return Mathf.Lerp(8.0f, 5.9f, difficulty);
            }
        }

        private int GetTutorialMaterialCollectedTotal()
        {
            return Mathf.Clamp(tutorialMaterialDelivered, 0, tutorialMaterialTarget) + Mathf.Max(0, carriedParts);
        }

        private void EnsureTutorialMaterialPartsAvailable()
        {
            if (!tutorialMaterialLessonActive || CountTutorialMaterialEnemies() > 0)
                return;

            int available = Mathf.Clamp(tutorialMaterialDelivered, 0, tutorialMaterialTarget) + Mathf.Max(0, carriedParts);
            for (int i = 0; i < partDrops.Count; i++)
            {
                PartDropView part = partDrops[i];
                if (part != null && part.TutorialMaterialPart && part.Root != null)
                    available += Mathf.Max(1, part.Value);
            }

            int missing = tutorialMaterialTarget - available;
            if (missing <= 0)
                return;

            Vector2 center = orb != null ? orb.anchoredPosition : Vector2.zero;
            for (int i = 0; i < missing; i++)
            {
                float angle = (Mathf.PI * 2f * i) / Mathf.Max(1, missing);
                float radius = 64f + (i % 3) * 26f;
                Vector2 offset = new Vector2(Mathf.Cos(angle) * radius, Mathf.Sin(angle) * radius + 128f);
                SpawnPartDrop(center + offset);
            }

            if (statusText != null)
                statusText.text = "MISSING PARTS RECOVERED";
            UpdateTutorialMaterialCounter();
        }

        private void CleanupTutorialMaterialEnemies()
        {
            for (int i = hazards.Count - 1; i >= 0; i--)
            {
                HazardView hazard = hazards[i];
                if (hazard == null || !hazard.TutorialMaterialEnemy)
                    continue;

                if (hazard.Root != null)
                    Destroy(hazard.Root.gameObject);
                hazards.RemoveAt(i);
            }
        }

        private void CleanupTutorialCinematicObjects()
        {
            SetTutorialPlayfieldZoom(1f);
            tutorialCoreCannonManualAim = false;
            for (int i = 0; i < tutorialCinematicEnemies.Count; i++)
            {
                if (tutorialCinematicEnemies[i] != null)
                    Destroy(tutorialCinematicEnemies[i].gameObject);
            }
            tutorialCinematicEnemies.Clear();

        }

        private void ShowStoryDialog(string speaker, string body, string buttonLabel)
        {
            ShowStoryDialog(speaker, body, buttonLabel, false);
        }

        private void ShowPlayerStoryDialog(string body, string buttonLabel)
        {
            ShowStoryDialog(GetPlayerDialogName(), body, buttonLabel, true);
        }

        private void ShowStoryDialog(string speaker, string body, string buttonLabel, bool playerSpeaker)
        {
            if (storyDialogRoot == null)
                return;

            storyDialogueAdvanceRequested = false;
            storyDialogRoot.gameObject.SetActive(true);
            storyDialogRoot.SetAsLastSibling();
            UpdateTopNavigationButtons();
            UpdateBaseTab();
            if (storyDialogSpeakerText != null)
                storyDialogSpeakerText.text = speaker;

            ApplyStoryDialogPortrait(speaker, playerSpeaker);
            if (storyDialogButton != null)
            {
                storyDialogButton.gameObject.SetActive(false);
                storyDialogButton.interactable = false;
            }
            if (storyDialogButtonText != null)
                storyDialogButtonText.text = string.IsNullOrEmpty(buttonLabel) ? "..." : buttonLabel;

            if (storyDialogTypingRoutine != null)
                StopCoroutine(storyDialogTypingRoutine);
            storyDialogTypingRoutine = StartCoroutine(TypeStoryDialogText(body));
        }

        private void ApplyStoryDialogPortrait(string speaker, bool playerSpeaker)
        {
            if (storyDialogPortrait == null)
                return;

            storyDialogPlayerSpeakerActive = playerSpeaker;
            bool boss = !playerSpeaker && string.Equals(speaker, L("speaker.mine_carrier"), StringComparison.OrdinalIgnoreCase);
            bool orbSpeaker = !string.IsNullOrEmpty(speaker)
                && (speaker.ToUpperInvariant().Contains("ORB") || speaker.ToUpperInvariant().Contains("STATION"));
            string variant = playerSpeaker ? "neutral" : ResolveStoryDialogUiVariant(speaker);
            storyDialogUsesComponentFrame = ApplyStoryDialogComponent(storyDialogRoot, DialogueShellResourcePath, false, false);
            if (storyDialogUsesComponentFrame)
            {
                ApplyStoryDialogPortraitFrame(storyDialogPortraitFrame, false);
                ApplyStoryDialogPortraitFrame(storyDialogPortraitFrameOverlay, false);
                ApplyStoryDialogComponent(storyDialogSpeakerPlate, DialogueNameplateResourcePath, false, false);
                ApplyStoryDialogComponent(storyDialogBodyPanel, DialogueTextPanelResourcePath, false, false);
                ApplyStoryDialogComponent(storyDialogButton != null ? storyDialogButton.transform as RectTransform : null, DialogueAnswerButtonResourcePath, false, true);
            }
            else
            {
                ApplyStoryDialogUiPart(storyDialogRoot, variant, "panel", false, false);
                if (!ApplyStoryDialogPortraitFrame(storyDialogPortraitFrame, false))
                    ApplyStoryDialogUiPart(storyDialogPortraitFrame, variant, "portrait", false, false);
                if (!ApplyStoryDialogPortraitFrame(storyDialogPortraitFrameOverlay, false))
                    ApplyStoryDialogUiPart(storyDialogPortraitFrameOverlay, variant, "portrait", false, false);
                ApplyStoryDialogUiPart(storyDialogSpeakerPlate, variant, "nameplate", false, false);
                ApplyStoryDialogUiPart(storyDialogButton != null ? storyDialogButton.transform as RectTransform : null, variant, "button", false, true);
            }

            if (playerSpeaker)
                ApplyPlayerStoryDialogAvatarFrame();
            UpdateStoryDialogLayout();

            if (storyDialogSpeakerText != null)
                storyDialogSpeakerText.color = boss ? new Color(1f, 0.58f, 0.28f, 1f) : playerSpeaker ? Ink : Gold;

            Sprite sprite = playerSpeaker
                ? GetPlayerDialogAvatar()
                : GetSpriteFromTextureResource(boss ? MinesBossSpriteResourcePath : orbSpeaker ? OrbStationSpriteResourcePath : CrafterDroneSpriteResourcePath);
            if (sprite != null)
            {
                storyDialogPortrait.sprite = sprite;
                storyDialogPortrait.color = Color.white;
                storyDialogPortrait.preserveAspect = true;
                return;
            }

            storyDialogPortrait.sprite = null;
            storyDialogPortrait.color = boss ? Hazard : playerSpeaker ? Ink : Cyan;
        }

        private void ApplyPlayerStoryDialogAvatarFrame()
        {
            ApplyStoryDialogPortraitFrame(storyDialogPortraitFrame, false);
            ApplyStoryDialogPortraitFrame(storyDialogPortraitFrameOverlay, false);
        }

        private string GetPlayerDialogName()
        {
            PlayerProfile profile = GetCurrentPlayerProfile();
            return profile != null && !string.IsNullOrWhiteSpace(profile.DisplayName)
                ? profile.DisplayName.Trim()
                : L("speaker.player");
        }

        private Sprite GetPlayerDialogAvatar()
        {
            PlayerProfile profile = GetCurrentPlayerProfile();
            return ProfileAvatarResources.GetDisplaySprite(profile);
        }

        private static PlayerProfile GetCurrentPlayerProfile()
        {
            if (ProfileService.I == null)
                ProfileRuntimeBootstrap.EnsureServices();

            if (ProfileService.I != null && ProfileService.I.Current == null)
                ProfileRuntimeBootstrap.TryLoadCachedProfile();

            return ProfileService.I != null ? ProfileService.I.Current : null;
        }

        private static string ResolveStoryDialogUiVariant(string speaker)
        {
            if (string.Equals(speaker, GameLocalization.Text(K("speaker.mine_carrier")), StringComparison.OrdinalIgnoreCase))
                return "enemy";
            if (!string.IsNullOrEmpty(speaker) && speaker.ToUpperInvariant().Contains("DRONE"))
                return "ally";
            return "neutral";
        }

        private static bool ApplyStoryDialogComponent(RectTransform rect, string resourcePath, bool preserveAspect, bool raycastTarget)
        {
            if (rect == null)
                return false;

            Image image = rect.GetComponent<Image>();
            if (image == null)
                return false;

            Sprite sprite = GetSpriteFromTextureResource(resourcePath);
            if (sprite == null)
                return false;

            image.sprite = sprite;
            image.type = Image.Type.Simple;
            image.color = Color.white;
            image.preserveAspect = preserveAspect;
            image.raycastTarget = raycastTarget;
            return true;
        }

        private static bool ApplyStoryDialogPortraitFrame(RectTransform rect, bool raycastTarget)
        {
            if (ApplyUiSpriteFromTextureResource(rect, PlayerDialogueAvatarFrameResourcePath, true, raycastTarget))
                return true;

            return ApplyStoryDialogComponent(rect, DialoguePortraitFrameResourcePath, false, raycastTarget);
        }

        private static bool ApplyStoryDialogUiPart(RectTransform rect, string variant, string part, bool preserveAspect, bool raycastTarget)
        {
            if (rect == null)
                return false;

            Image image = rect.GetComponent<Image>();
            if (image == null)
                return false;

            Sprite sprite = GetSpriteFromTextureResource(DialogueUiPartResourcePrefix + variant + "_" + part);
            if (sprite == null)
                return false;

            image.sprite = sprite;
            image.type = Image.Type.Simple;
            image.color = Color.white;
            image.preserveAspect = preserveAspect;
            image.raycastTarget = raycastTarget;
            return true;
        }

        private IEnumerator TypeStoryDialogText(string body)
        {
            storyDialogTyping = true;
            storyDialogueAdvanceRequested = false;
            body ??= string.Empty;
            if (storyDialogBodyText != null)
            {
                ApplyStoryDialogBodyTextScale(body);
                storyDialogBodyText.text = body;
                storyDialogBodyText.ForceMeshUpdate();
                storyDialogBodyText.maxVisibleCharacters = 0;
            }
            SetStoryDialogButtonVisible(false);

            const float charactersPerSecond = 58f;
            float visibleCharacters = 0f;
            int lastCount = -1;
            while (visibleCharacters < body.Length)
            {
                if (storyDialogueAdvanceRequested)
                {
                    storyDialogueAdvanceRequested = false;
                    break;
                }

                visibleCharacters += Mathf.Max(1f, charactersPerSecond * Time.unscaledDeltaTime);
                int count = Mathf.Clamp(Mathf.CeilToInt(visibleCharacters), 0, body.Length);
                if (count != lastCount)
                {
                    if (storyDialogBodyText != null)
                        storyDialogBodyText.maxVisibleCharacters = count;
                    lastCount = count;
                }

                yield return null;
            }

            if (storyDialogBodyText != null)
            {
                storyDialogBodyText.text = body;
                storyDialogBodyText.maxVisibleCharacters = int.MaxValue;
            }

            storyDialogTyping = false;
            SetStoryDialogButtonVisible(true);
        }

        private void ApplyStoryDialogBodyTextScale(string body)
        {
            if (storyDialogBodyText == null)
                return;

            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            float canvasWidth = root != null ? Mathf.Max(1f, root.rect.width) : 1080f;
            float canvasHeight = root != null ? Mathf.Max(1f, root.rect.height) : 1920f;
            bool narrow = canvasWidth < canvasHeight * 0.82f;
            int visibleLength = CountStoryDialogVisibleCharacters(body);
            float maxSize = narrow
                ? visibleLength <= 58 ? 82f : visibleLength <= 92 ? 72f : 62f
                : visibleLength <= 58 ? 52f : visibleLength <= 92 ? 45f : 38f;

            storyDialogBodyText.enableAutoSizing = true;
            storyDialogBodyText.fontSizeMax = maxSize;
            storyDialogBodyText.fontSizeMin = narrow ? 34f : 24f;
            storyDialogBodyText.alignment = TextAlignmentOptions.Center;
        }

        private static int CountStoryDialogVisibleCharacters(string body)
        {
            if (string.IsNullOrEmpty(body))
                return 0;

            int count = 0;
            for (int i = 0; i < body.Length; i++)
            {
                if (!char.IsWhiteSpace(body[i]))
                    count++;
            }
            return count;
        }

        private void HideStoryDialog()
        {
            if (storyDialogTypingRoutine != null)
            {
                StopCoroutine(storyDialogTypingRoutine);
                storyDialogTypingRoutine = null;
            }
            storyDialogTyping = false;
            if (storyDialogRoot != null)
                storyDialogRoot.gameObject.SetActive(false);
            storyDialogueAdvanceRequested = false;
            UpdateTopNavigationButtons();
            UpdateBaseTab();
        }

        private void OnStoryDialogButton()
        {
            storyDialogueAdvanceRequested = true;
        }

        private IEnumerator WaitStoryDialogSeconds(float seconds)
        {
            while (storyDialogTyping)
                yield return null;

            storyDialogueAdvanceRequested = false;
            while (!storyDialogueAdvanceRequested)
                yield return null;
        }

        private IEnumerator WaitStoryDialogButton()
        {
            while (storyDialogTyping)
                yield return null;

            storyDialogueAdvanceRequested = false;
            while (!storyDialogueAdvanceRequested)
                yield return null;
        }

        private void SetStoryDialogButtonVisible(bool visible)
        {
            if (storyDialogButton == null)
                return;

            storyDialogButton.gameObject.SetActive(visible);
            storyDialogButton.interactable = visible;
        }

        private void ShowStoryWaveAnnouncement(int wave)
        {
            if (storyWaveBannerRoutine != null)
                StopCoroutine(storyWaveBannerRoutine);

            storyWaveBannerRoutine = StartCoroutine(StoryWaveBannerRoutine(wave));
        }

        private IEnumerator StoryWaveBannerRoutine(int wave)
        {
            if (storyWaveBannerRoot == null || storyWaveBannerText == null)
                yield break;

            storyWaveBannerRoot.gameObject.SetActive(true);
            storyWaveBannerRoot.SetAsLastSibling();
            int maxWave = selectedStoryLevel == StoryLevel.ForwardDefense ? StoryForwardDefenseWaveCount : StoryMinesWaveCount;
            storyWaveBannerText.text = "WAVE " + Mathf.Clamp(wave, 1, maxWave) + " / " + maxWave;
            storyWaveBannerText.color = Gold;

            float t = 0f;
            while (t < 1.6f)
            {
                t += Time.deltaTime;
                float pulse = 1f + Mathf.Sin(t * 10f) * 0.035f;
                storyWaveBannerRoot.localScale = Vector3.one * pulse;
                yield return null;
            }

            storyWaveBannerRoot.localScale = Vector3.one;
            storyWaveBannerRoot.gameObject.SetActive(false);
        }

        private void HideStoryWaveBanner()
        {
            if (storyWaveBannerRoutine != null)
            {
                StopCoroutine(storyWaveBannerRoutine);
                storyWaveBannerRoutine = null;
            }
            if (storyWaveBannerRoot != null)
            {
                storyWaveBannerRoot.localScale = Vector3.one;
                storyWaveBannerRoot.gameObject.SetActive(false);
            }
        }

