        private void CleanupHazards()
        {
            for (int i = hazards.Count - 1; i >= 0; i--)
            {
                if (hazards[i].Root != null)
                    Destroy(hazards[i].Root.gameObject);
            }

            hazards.Clear();

            for (int i = projectiles.Count - 1; i >= 0; i--)
            {
                if (projectiles[i].Root != null)
                    Destroy(projectiles[i].Root.gameObject);
            }

            projectiles.Clear();

            for (int i = enemyProjectiles.Count - 1; i >= 0; i--)
            {
                if (enemyProjectiles[i].Root != null)
                    Destroy(enemyProjectiles[i].Root.gameObject);
            }

            enemyProjectiles.Clear();

            for (int i = partDrops.Count - 1; i >= 0; i--)
            {
                if (partDrops[i].Root != null)
                    Destroy(partDrops[i].Root.gameObject);
            }

            partDrops.Clear();

            for (int i = cargoUnloadViews.Count - 1; i >= 0; i--)
            {
                if (cargoUnloadViews[i].Root != null)
                    Destroy(cargoUnloadViews[i].Root.gameObject);
            }

            cargoUnloadViews.Clear();
            CleanupFriendlyMineLayerMines();
            CleanupHiveMiniTurrets();
        }

        private void CleanupFriendlyMineLayerMines()
        {
            for (int i = friendlyMineLayerMines.Count - 1; i >= 0; i--)
            {
                if (friendlyMineLayerMines[i].Root != null)
                    Destroy(friendlyMineLayerMines[i].Root.gameObject);
            }

            friendlyMineLayerMines.Clear();
        }

        private void CleanupHiveMiniTurrets()
        {
            for (int i = hiveMiniTurrets.Count - 1; i >= 0; i--)
            {
                if (hiveMiniTurrets[i].Root != null)
                    Destroy(hiveMiniTurrets[i].Root.gameObject);
            }

            hiveMiniTurrets.Clear();
        }

        private void CleanupMinesBoss()
        {
            minesBossCracks.Clear();
            if (minesBoss != null)
                Destroy(minesBoss.gameObject);

            minesBoss = null;
            minesBossActive = false;
            minesBossSpawnShakeTimer = 0f;
            minesBossShortCircuitTimer = 0f;
