            minesBossPhaseIndex = 0;
            minesBossPhaseTimer = 0f;
            minesBossDamageable = false;
            minesBossPhaseWaitingForClear = false;
        }

        private void HandleInput()
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return;

            Vector2 limits = ResolveOrbMoveLimits(root);

            if (TryHandleHangarEntryGesture(root))
                return;

            bool pressed;
            bool held;
            bool released;
            Vector2 pointerPosition;
            float keyboard = 0f;
            ReadGameplayInput(out pressed, out held, out released, out pointerPosition, out keyboard);
            bool outpostOrbLaunchedThisFrame = false;

            if (pressed)
            {
                pointerStartedOnUi = IsPointerOverButton(pointerPosition);
                outpostHandleDragging = !pointerStartedOnUi && IsPointerOverOutpostHandle(pointerPosition);
                outpostOrbUndockedThisGesture = false;
                if (outpostHandleDragging)
                {
                    pointerControl = false;
                    pointerStartedOnOrbControl = false;
                    battleDraggedDroneTarget = DroneUpgradeTarget.None;
                    crafterDragging = false;
                    generatorDragging = false;
                    repairDragging = false;
                    shieldDroneDragging = false;
                    collectorDroneDragging = false;
                    queenDroneDragging = false;
                    mimicDroneDragging = false;
                    sniperDroneDragging = false;
                    return;
                }

                bool pointerStartedOnOrb = !pointerStartedOnUi && IsPointerOverOrbControlZone(pointerPosition);
                pointerStartedOnOrbControl = pointerStartedOnOrb;
                if (pointerStartedOnOrb && TryHandleOrbDoubleTap(pointerPosition))
                {
                    pointerControl = false;
                    pointerStartedOnOrbControl = false;
                    battleDraggedDroneTarget = DroneUpgradeTarget.None;
                    crafterDragging = false;
                    generatorDragging = false;
                    repairDragging = false;
                    shieldDroneDragging = false;
                    collectorDroneDragging = false;
                    queenDroneDragging = false;
                    mimicDroneDragging = false;
                    sniperDroneDragging = false;
                    return;
                }

                battleDraggedDroneTarget = ResolveBattleDraggedDroneTarget(pointerPosition);
                crafterDragging = battleDraggedDroneTarget == DroneUpgradeTarget.Crafter;
                if (crafterDragging)
                    CancelCrafterCurrentBuild();
                generatorDragging = battleDraggedDroneTarget == DroneUpgradeTarget.Generator;
                repairDragging = battleDraggedDroneTarget == DroneUpgradeTarget.Repair;
                shieldDroneDragging = battleDraggedDroneTarget == DroneUpgradeTarget.Shield;
                collectorDroneDragging = battleDraggedDroneTarget == DroneUpgradeTarget.Collector;
                queenDroneDragging = battleDraggedDroneTarget == DroneUpgradeTarget.Queen;
                mimicDroneDragging = battleDraggedDroneTarget == DroneUpgradeTarget.Mimic;
                sniperDroneDragging = battleDraggedDroneTarget == DroneUpgradeTarget.Sniper;
                bool draggingDrone = battleDraggedDroneTarget != DroneUpgradeTarget.None;
                bool freeOrbCanFollowPointer = !pointerStartedOnUi && !draggingDrone && !IsOrbDockedOnBaseShip() && !IsOrbDockedOnOutpost() && !IsOrbBaseTransitionLocked();
                bool dockedOrbCanBePulled = pointerStartedOnOrb && !pointerStartedOnUi && !draggingDrone && (IsOrbDockedOnBaseShip() || IsOrbDockedOnOutpost());
                pointerControl = freeOrbCanFollowPointer || dockedOrbCanBePulled;
            }

            if (outpostHandleDragging && held)
            {
                if (TryScreenPointToWorldLocalPoint(pointerPosition, out Vector2 localPoint))
                    targetOutpostY = ClampOutpostY(localPoint.y);
                if (statusText != null)
                    statusText.text = L("status.outpost_moving");
            }

            if (held && !outpostOrbUndockedThisGesture && !pointerControl && !pointerStartedOnUi && !crafterDragging && !generatorDragging && !repairDragging && !shieldDroneDragging && !collectorDroneDragging && !queenDroneDragging && !mimicDroneDragging && !sniperDroneDragging && !outpostHandleDragging && !IsOrbDockedOnBaseShip() && !IsOrbDockedOnOutpost() && !IsOrbBaseTransitionLocked())
                pointerControl = true;

            if (battleDraggedDroneTarget != DroneUpgradeTarget.None && held)
            {
                if (TryScreenPointToVirtualPlayZone(pointerPosition, out Vector2 localPoint))
                {
                    MoveBattleDraggedDroneToCommand(battleDraggedDroneTarget, localPoint);
                    if (battleDraggedDroneTarget == DroneUpgradeTarget.Sniper)
                        UpdateSniperAimCamera(pointerPosition);
                }
            }
            else if (battleDraggedDroneTarget == DroneUpgradeTarget.None)
            {
                HideDroneCommandVisuals();
            }

            if (pointerControl && held && !pointerStartedOnUi)
            {
                if (TryScreenPointToVirtualPlayZone(pointerPosition, out Vector2 localPoint))
                {
                    if (IsOrbDockedOnOutpost())
                    {
                        Vector2 dock = ResolveOutpostDockPosition();
                        if (!pointerStartedOnOrbControl)
                        {
                            targetLaneX = dock.x;
                            targetOrbY = dock.y;
                            if (statusText != null)
                                statusText.text = L("status.outpost_mode");
                        }
                        else
                        {
                            bool shouldUndockOutpostOrb = Vector2.Distance(localPoint, dock) >= OutpostOrbLaunchTriggerDistance;
                            if (shouldUndockOutpostOrb)
                            {
                                StartOutpostOrbPointerUndock(localPoint, limits);
                                outpostOrbLaunchedThisFrame = true;
                            }
                            else
                            {
                                targetLaneX = dock.x;
                                targetOrbY = dock.y;
                                if (statusText != null)
                                    statusText.text = L("status.outpost_mode");
                            }
                        }
                    }
                    else if (IsOrbDockedOnBaseShip())
                    {
                        Vector2 dock = ResolveActiveDefenseDockPosition();
                        if (localPoint.y >= dock.y + BaseShipUndockPullDistance && !tutorialBaseDefenseActive)
                            ExitOrbDefenderMode();
                        else
                        {
                            targetLaneX = dock.x;
                            targetOrbY = dock.y;
                            if (tutorialBaseDefenseActive && statusText != null)
                                statusText.text = L("status.base_defense_core");
                        }
                    }

                    if (!outpostOrbLaunchedThisFrame && !IsOrbDockedOnBaseShip() && !IsOrbBaseTransitionLocked())
                    {
                        SetOrbDeploymentStage(OrbDeploymentStage.Flight);
                        targetLaneX = Mathf.Clamp(localPoint.x, -limits.x, limits.x);
                        targetOrbY = Mathf.Clamp(localPoint.y, -limits.y, limits.y);
                    }
                }
            }

            bool inReturnZone = targetOrbY <= 0f && Mathf.Abs(targetLaneX) < root.rect.width * 0.30f;
            if (released || (battleDraggedDroneTarget != DroneUpgradeTarget.None && !held) || (outpostHandleDragging && !held) || (pointerControl && !held && inReturnZone))
            {
                Vector2 releasePoint = new Vector2(targetLaneX, targetOrbY);
                bool movingDockedOutpost = pointerControl && IsOrbDockedOnOutpost();
                bool shouldDockOutpost = pointerControl && !outpostOrbUndockedThisGesture && !IsOrbDockedOnBaseShip() && !IsOrbDockedOnOutpost() && !IsOrbBaseTransitionLocked() && IsNearOutpostDockSlot(releasePoint);
                bool shouldDockOrb = pointerControl && !shouldDockOutpost && !IsOrbDockedOnBaseShip() && !IsOrbBaseTransitionLocked() && IsNearBaseShipDockSlot(releasePoint);
                bool placedOnUpgradePad = TryHandleDroneUpgradePadDrop(pointerPosition);
                if (!placedOnUpgradePad)
                {
                    bool commandOverOrb = droneCommandActive && IsCommandOverOrb(droneCommandPosition);
                    if (generatorDragging)
                    {
                        if (!TryAssignGeneratorCommandTarget(droneCommandPosition))
                            TryLaunchGeneratorToOrb(commandOverOrb);
                    }
                    if (repairDragging)
                        TryLaunchRepairToOrb(commandOverOrb);
                    if (shieldDroneDragging)
                        TryLaunchShieldDroneToOrb(commandOverOrb);
                    if (collectorDroneDragging)
                        TryLaunchCollectorToOrb(commandOverOrb);
                }
                if (mimicDroneDragging)
                    TryAssignMimicCopy(pointerPosition);
                if (battleDraggedDroneTarget == DroneUpgradeTarget.Hive && !TryMountHiveOnOutpost())
                    StartHiveTemporaryCommand(droneCommandActive ? droneCommandPosition : hiveDronePosition);
                if (sniperDroneDragging)
                {
                    if (sniperMountedOnOutpost && sniperPendingOutpostDetach && !sniperAimingMode)
                        DetachSniperFromOutpost(sniperPendingOutpostDetachPosition);
                    else if (!TryMountSniperOnOutpost())
                        TryFireSniperShot();
                    BeginSniperAimCameraReturn();
                }
                crafterDragging = false;
                generatorDragging = false;
                repairDragging = false;
                shieldDroneDragging = false;
                collectorDroneDragging = false;
                queenDroneDragging = false;
                mimicDroneDragging = false;
                sniperDroneDragging = false;
                battleDraggedDroneTarget = DroneUpgradeTarget.None;
                HideDroneCommandVisuals();
                HideMimicAimVisuals();
                HideSniperAimVisuals();
                outpostHandleDragging = false;
                if (movingDockedOutpost)
                {
                    Vector2 dock = ResolveOutpostDockPosition();
                    targetLaneX = dock.x;
                    targetOrbY = dock.y;
                    SetOrbDeploymentStage(OrbDeploymentStage.Defender);
                }
                else if (shouldDockOutpost)
                    EnterOutpostDefenderMode();
                else if (shouldDockOrb)
                    EnterOrbDefenderMode();
                else if (pointerControl && !IsOrbDockedOnBaseShip() && !IsOrbBaseTransitionLocked())
                {
                    if (!tutorialManualReturnToBaseActive)
                    {
                        targetLaneX = 0f;
                        targetOrbY = ResolveGameOrbY();
                    }
                    SetOrbDeploymentStage(OrbDeploymentStage.Flight);
                }
                pointerControl = false;
                pointerStartedOnUi = false;
                pointerStartedOnOrbControl = false;
                outpostOrbUndockedThisGesture = false;
            }

            if (!pointerControl)
            {
                if (IsOrbHeldOnBaseShip())
                {
                    Vector2 dock = ResolveActiveDefenseDockPosition();
                    targetLaneX = dock.x;
                    targetOrbY = dock.y;
                }
                else if (orbDeploymentStage == OrbDeploymentStage.UndockingToHover)
                {
                    targetLaneX = 0f;
                    targetOrbY = ResolveGameOrbY();
                }
                else
                {
                    if (Mathf.Abs(keyboard) > 0.01f)
                    {
                        SetOrbDeploymentStage(OrbDeploymentStage.Flight);
                        targetLaneX = Mathf.Clamp(targetLaneX + keyboard * 760f * Time.deltaTime, -limits.x, limits.x);
                    }
                }
            }

            laneX = Mathf.Lerp(laneX, targetLaneX, 1f - Mathf.Exp(-12f * Time.deltaTime));
            orbY = Mathf.Lerp(orbY, targetOrbY, 1f - Mathf.Exp(-12f * Time.deltaTime));
            UpdateOrbBaseTransitionProgress();
            RefreshFreeOrbDeploymentStage();
        }

        private void UpdateOrbBaseTransitionProgress()
        {
            if (orbDeploymentStage != OrbDeploymentStage.UndockingToHover)
                return;

            Vector2 hover = new Vector2(0f, ResolveGameOrbY());
            if (Vector2.Distance(new Vector2(laneX, orbY), hover) > OrbUndockReadyDistance)
                return;

            laneX = hover.x;
            orbY = hover.y;
            targetLaneX = hover.x;
            targetOrbY = hover.y;
            SetOrbDeploymentStage(OrbDeploymentStage.BaseHover);
            if (statusText != null)
                statusText.text = "ORBITER READY";
        }

        private static bool IsPointerOverButton(Vector2 screenPosition)
        {
            EventSystem eventSystem = EventSystem.current;
            if (eventSystem == null)
                return false;

            PointerEventData pointerData = new PointerEventData(eventSystem)
            {
                position = screenPosition
            };

            List<RaycastResult> results = new List<RaycastResult>();
            eventSystem.RaycastAll(pointerData, results);
            for (int i = 0; i < results.Count; i++)
            {
                GameObject hit = results[i].gameObject;
                if (hit != null && hit.GetComponentInParent<Button>() != null)
                    return true;
            }

            return false;
        }

        private bool IsPointerOverCrafter(Vector2 screenPosition)
        {
            return crafterSpawnedThisRun && IsPointerOverDrone(screenPosition, crafterDrone);
        }

        private bool IsPointerOverGenerator(Vector2 screenPosition)
        {
            return !generatorAttached && !generatorFlyingToOrb && IsPointerOverDrone(screenPosition, generatorDrone);
        }

        private bool IsPointerOverRepair(Vector2 screenPosition)
        {
            return !repairAttached && !repairFlyingToOrb && IsPointerOverDrone(screenPosition, repairDrone);
        }

        private bool IsPointerOverShieldDrone(Vector2 screenPosition)
        {
            return shieldDroneSpawnedThisRun && !shieldDroneFlyingToOrb && IsPointerOverDrone(screenPosition, shieldDrone);
        }

        private bool IsPointerOverCollectorDrone(Vector2 screenPosition)
        {
            return collectorDroneSpawnedThisRun && !collectorDroneFlyingToOrb && IsPointerOverDrone(screenPosition, collectorDrone);
        }

        private bool IsPointerOverQueenDrone(Vector2 screenPosition)
        {
            return queenDroneSpawnedThisRun && IsPointerOverDrone(screenPosition, queenDrone);
        }

        private bool IsPointerOverMimicDrone(Vector2 screenPosition)
        {
            return mimicDroneSpawnedThisRun && mimicCooldownTimer <= 0f && mimicCopyTarget == MimicCopyTarget.None && IsPointerOverDrone(screenPosition, mimicDrone);
        }

        private bool IsPointerOverSniperDrone(Vector2 screenPosition)
        {
            return sniperDroneSpawnedThisRun && IsPointerOverDrone(screenPosition, sniperDrone);
        }

        private bool IsPointerOverOrb(Vector2 screenPosition)
        {
            if (orb == null || !orb.gameObject.activeSelf)
                return false;

            if (!TryScreenPointToWorldLocalPoint(screenPosition, out Vector2 localPoint))
                return false;

            float radius = Mathf.Max(44f, Mathf.Max(orb.sizeDelta.x, orb.sizeDelta.y) * 0.72f * Mathf.Max(0.6f, orbScale));
            if (shield > 0)
                radius += 12f;

            Vector2 orbCenter = IsOrbDockedOnOutpost() ? ResolveOutpostDockPosition() : orb.anchoredPosition;
            return Vector2.Distance(localPoint, orbCenter) <= radius;
        }

        private bool IsPointerOverOrbControlZone(Vector2 screenPosition)
        {
            if (orb == null || !orb.gameObject.activeSelf)
                return false;

            if (!TryScreenPointToWorldLocalPoint(screenPosition, out Vector2 localPoint))
                return false;

            float visualSize = Mathf.Max(orb.sizeDelta.x, orb.sizeDelta.y) * Mathf.Max(0.75f, orbScale);
            float radius = Mathf.Max(118f, visualSize * 1.18f);
            if (shield > 0)
                radius += 18f;
            if (IsOrbHeldOnBaseShip())
                radius = Mathf.Max(radius, 154f);

            Vector2 orbCenter = IsOrbDockedOnOutpost() ? ResolveOutpostDockPosition() : orb.anchoredPosition;
            return Vector2.Distance(localPoint, orbCenter) <= radius;
        }

        private bool IsCommandOverOrb(Vector2 localPoint)
        {
            if (orb == null || !orb.gameObject.activeSelf)
                return false;

            float radius = Mathf.Max(58f, Mathf.Max(orb.sizeDelta.x, orb.sizeDelta.y) * 0.72f * Mathf.Max(0.6f, orbScale));
            if (shield > 0)
                radius += 12f;

            return Vector2.Distance(localPoint, orb.anchoredPosition) <= radius;
        }

        private bool IsCommandOverDrone(Vector2 localPoint, RectTransform drone, float padding = 20f)
        {
            if (drone == null || !drone.gameObject.activeSelf)
                return false;

            float radius = Mathf.Max(42f, Mathf.Max(drone.sizeDelta.x, drone.sizeDelta.y) * 0.50f + padding);
            return Vector2.Distance(localPoint, GetCanvasLocalPosition(drone)) <= radius;
        }

        private bool IsPointerOverDrone(Vector2 screenPosition, RectTransform drone)
        {
            if (drone == null || !drone.gameObject.activeSelf)
                return false;

            if (!TryScreenPointToWorldLocalPoint(screenPosition, out Vector2 localPoint))
                return false;

            return Vector2.Distance(localPoint, drone.anchoredPosition) <= 46f;
        }

        private bool IsPointerOverStorageDepot(Vector2 screenPosition)
        {
            if (!storageDepotOwned || storageDepot == null || !storageDepot.gameObject.activeSelf)
                return false;

            if (!TryScreenPointToWorldLocalPoint(screenPosition, out Vector2 localPoint))
                return false;

            Vector2 center = GetCanvasLocalPosition(storageDepot);
            float radius = Mathf.Max(54f, Mathf.Min(storageDepot.sizeDelta.x, storageDepot.sizeDelta.y) * 0.42f);
            return Vector2.Distance(localPoint, center) <= radius;
        }

        private bool IsPointerOverOutpostHandle(Vector2 screenPosition)
        {
            if (!outpostBuilt || outpostHandle == null || !outpostHandle.gameObject.activeSelf)
                return false;

            if (!TryScreenPointToWorldLocalPoint(screenPosition, out Vector2 localPoint))
                return false;

            Vector2 handle = ResolveOutpostHandlePosition();
            return Mathf.Abs(localPoint.x - handle.x) <= OutpostHandleWidth * 0.58f &&
                   Mathf.Abs(localPoint.y - handle.y) <= OutpostHandleHeight * 0.85f;
        }

        private bool TryHandleDroneUpgradePadDrop(Vector2 screenPosition)
        {
            if (!HasVisibleDroneUpgradePadAccess() || droneUpgradePad == null || !droneUpgradePad.gameObject.activeSelf)
                return false;

            DroneUpgradeTarget target = CurrentDraggedDroneUpgradeTarget();
            bool battleCrafterPadCommand = target == DroneUpgradeTarget.Crafter
                && state == GameState.Playing
                && !menuHangarOpen
                && droneCommandActive
                && droneCommandMagnetToUpgradePad;
            if (battleCrafterPadCommand)
            {
                StartDroneUpgradePadDocking(target);
                if (statusText != null)
                    statusText.text = LF("status.drone_on_upgrade_pad", DroneUpgradeTargetName(target));
                return true;
            }

            if (target == DroneUpgradeTarget.None || (!IsPointerOverDroneUpgradePad(screenPosition) && !IsDroneUpgradeTargetOverPad(target) && !IsDroneCommandOverUpgradePad()))
                return false;

            StartDroneUpgradePadDocking(target);
            if (statusText != null)
                statusText.text = LF("status.drone_on_upgrade_pad", DroneUpgradeTargetName(target));
            return true;
        }

        private void StartDroneUpgradePadDocking(DroneUpgradeTarget target)
        {
            if (target == DroneUpgradeTarget.None)
                return;

            if (target == DroneUpgradeTarget.Crafter && state == GameState.Playing && !menuHangarOpen)
                CancelCrafterCurrentBuild();

            pendingDroneUpgradeTarget = target;
            menuHangarCommandStates.Remove(target);
            droneUpgradePadDocking = true;
            droneUpgradePadDockingHoldTimer = 0f;
            HideMenuHangarUpgradeButtons();
            MoveDraggedDroneToUpgradePad(target, GetDroneUpgradeTargetPosition(target));
            SetDroneUpgradeTargetVisualOnTop(target);
        }

        private void UpdateDroneUpgradePadDocking()
        {
            if (!droneUpgradePadDocking || pendingDroneUpgradeTarget == DroneUpgradeTarget.None)
                return;

            Vector2 padPosition = ResolveDroneUpgradePadWorldPosition();
            RectTransform drone = GetDroneUpgradeTargetRect(pendingDroneUpgradeTarget);
            if (drone == null)
            {
                FinishDroneUpgradePadDocking(false);
                return;
            }

            Vector2 current = GetDroneUpgradeTargetPosition(pendingDroneUpgradeTarget);
            Vector2 next = Vector2.MoveTowards(current, padPosition, DroneUpgradePadDockingSpeed * Time.unscaledDeltaTime);
            SetDroneUpgradeTargetPosition(pendingDroneUpgradeTarget, next);
            drone.anchoredPosition = next;
            drone.localScale = Vector3.one * ResolveMenuHangarDroneScale(pendingDroneUpgradeTarget);
            Vector2 faceTarget = (next - current).sqrMagnitude > 0.08f ? next : padPosition;
            FaceCommandedDroneToward(pendingDroneUpgradeTarget, drone, current, faceTarget);
            drone.SetAsLastSibling();

            if (Vector2.Distance(next, padPosition) > DroneUpgradePadDockingArriveDistance)
                return;

            SetDroneUpgradeTargetPosition(pendingDroneUpgradeTarget, padPosition);
            drone.anchoredPosition = padPosition;
            FaceCommandedDroneToward(pendingDroneUpgradeTarget, drone, padPosition, padPosition + Vector2.up * 140f);
            droneUpgradePadDockingHoldTimer += Time.unscaledDeltaTime;
            if (droneUpgradePadDockingHoldTimer < DroneUpgradePadDockingHoldSeconds)
                return;

            if (pendingDroneUpgradeTarget == DroneUpgradeTarget.Crafter && state == GameState.Playing && !menuHangarOpen)
            {
                crafterPosition = padPosition;
                crafterDrone.anchoredPosition = padPosition;
                TryStartOutpostBuild();
                FinishDroneUpgradePadDocking(false);
                return;
            }

            FinishDroneUpgradePadDocking(true);
        }

        private void FinishDroneUpgradePadDocking(bool openWindow)
        {
            DroneUpgradeTarget target = pendingDroneUpgradeTarget;
            droneUpgradePadDocking = false;
            droneUpgradePadDockingHoldTimer = 0f;
            pendingDroneUpgradeTarget = DroneUpgradeTarget.None;

            if (openWindow && target != DroneUpgradeTarget.None)
                ShowDroneUpgradeWindow(target);
        }

        private void StartCoreForgeModuleDocking()
        {
            if (!HasVisibleCoreForgeModuleUpgradeAccess() || !crafterOwned || crafterDrone == null)
                return;

            pendingDroneUpgradeTarget = DroneUpgradeTarget.Crafter;
            menuHangarCommandStates.Remove(DroneUpgradeTarget.Crafter);
            coreForgeModuleDocking = true;
            coreForgeModuleDockingHoldTimer = 0f;
            HideMenuHangarUpgradeButtons();
            MoveDraggedDroneToUpgradePad(DroneUpgradeTarget.Crafter, crafterPosition);
            SetDroneUpgradeTargetVisualOnTop(DroneUpgradeTarget.Crafter);
        }

        private void UpdateCoreForgeModuleDocking()
        {
            if (!coreForgeModuleDocking)
                return;

            if (!HasVisibleCoreForgeModuleUpgradeAccess() || crafterDrone == null)
            {
                FinishCoreForgeModuleDocking(false);
                return;
            }

            Vector2 forgePosition = ResolveCoreForgeWorldPosition();
            Vector2 current = crafterPosition;
            Vector2 next = Vector2.MoveTowards(current, forgePosition, DroneUpgradePadDockingSpeed * Time.unscaledDeltaTime);
            crafterPosition = next;
            crafterDrone.anchoredPosition = next;
            crafterDrone.localScale = Vector3.one * ResolveMenuHangarDroneScale(DroneUpgradeTarget.Crafter);
            Vector2 faceTarget = (next - current).sqrMagnitude > 0.08f ? next : forgePosition;
            FaceCommandedDroneToward(DroneUpgradeTarget.Crafter, crafterDrone, current, faceTarget);
            crafterDrone.SetAsLastSibling();

            if (Vector2.Distance(next, forgePosition) > DroneUpgradePadDockingArriveDistance)
                return;

            crafterPosition = forgePosition;
            crafterDrone.anchoredPosition = forgePosition;
            FaceCommandedDroneToward(DroneUpgradeTarget.Crafter, crafterDrone, forgePosition, forgePosition + Vector2.up * 120f);
            coreForgeModuleDockingHoldTimer += Time.unscaledDeltaTime;
            if (coreForgeModuleDockingHoldTimer < DroneUpgradePadDockingHoldSeconds)
                return;

            FinishCoreForgeModuleDocking(true);
        }

        private void FinishCoreForgeModuleDocking(bool openWindow)
        {
            coreForgeModuleDocking = false;
            coreForgeModuleDockingHoldTimer = 0f;
            pendingDroneUpgradeTarget = DroneUpgradeTarget.None;

            if (openWindow)
                ShowCoreForgeModuleUpgradeWindow();
        }

        private void ShowCoreForgeModuleUpgradeWindow()
        {
            if (coreForgeModuleRoot == null)
                return;

            selectedCoreForgeModuleIndex = -1;
            coreForgeModuleRoot.gameObject.SetActive(true);
            coreForgeModuleRoot.SetAsLastSibling();
            ShowCoreForgeModuleSelection();
            if (upgradeRoot != null)
                upgradeRoot.gameObject.SetActive(false);
            if (menuHangarProfileRoot != null)
                menuHangarProfileRoot.gameObject.SetActive(false);
            if (droneUpgradeRoot != null)
                droneUpgradeRoot.gameObject.SetActive(false);
            if (settingsRoot != null)
                settingsRoot.gameObject.SetActive(false);
            if (statusText != null)
                statusText.text = L("status.core_forge_modules");
            Time.timeScale = 0f;
        }

        private void ShowCoreForgeModuleSelection()
        {
            selectedCoreForgeModuleIndex = -1;
            if (coreForgeModuleSelectionPage != null)
                coreForgeModuleSelectionPage.gameObject.SetActive(true);
            if (coreForgeModuleDetailPage != null)
                coreForgeModuleDetailPage.gameObject.SetActive(false);
            RefreshCoreForgeModuleSelection();
        }

        private void RefreshCoreForgeModuleSelection()
        {
            for (int i = 0; i < coreForgeModuleSelectTexts.Length; i++)
            {
                if (coreForgeModuleSelectTexts[i] == null)
                    continue;

                int level = GetMenuHangarUpgradeLevel(i);
                coreForgeModuleSelectTexts[i].text = level >= HangarUpgradeMaxLevel
                    ? L("hangar.max")
                    : LF("core_forge.module_status", level, HangarUpgradeMaxLevel, MenuHangarUpgradeCost(i, level));
            }
        }

        private void ShowCoreForgeModuleDetail(int index)
        {
            selectedCoreForgeModuleIndex = Mathf.Clamp(index, 0, 3);
            if (coreForgeModuleSelectionPage != null)
                coreForgeModuleSelectionPage.gameObject.SetActive(false);
            if (coreForgeModuleDetailPage != null)
                coreForgeModuleDetailPage.gameObject.SetActive(true);

            ResolveMenuHangarProfileData(selectedCoreForgeModuleIndex, out string title, out string body, out string spritePath);
            if (coreForgeModuleTitleText != null)
                coreForgeModuleTitleText.text = title;
            if (coreForgeModuleBodyText != null)
                coreForgeModuleBodyText.text = BuildMenuHangarProfileBody(selectedCoreForgeModuleIndex, body);
            if (coreForgeModuleActionText != null)
                coreForgeModuleActionText.text = MenuHangarUpgradeActionLabel(selectedCoreForgeModuleIndex);

            Image portrait = coreForgeModulePortrait != null ? coreForgeModulePortrait.GetComponent<Image>() : null;
            if (portrait != null)
            {
                portrait.sprite = GetSpriteFromTextureResource(spritePath);
                portrait.color = Color.white;
                portrait.preserveAspect = true;
            }
        }

        private void UpgradeSelectedCoreForgeModule()
        {
            if (!IsTutorialCompleted())
            {
                if (statusText != null)
                    statusText.text = L("status.complete_tutorial");
                return;
            }

            int index = selectedCoreForgeModuleIndex;
            if (index < 0 || index > 3)
                return;

            int level = GetMenuHangarUpgradeLevel(index);
            if (level >= HangarUpgradeMaxLevel)
            {
                if (statusText != null)
                    statusText.text = L("status.technology_max");
                ShowCoreForgeModuleDetail(index);
                return;
            }

            int cost = MenuHangarUpgradeCost(index, level);
            if (!HasCoreShards(cost))
            {
                if (statusText != null)
                    statusText.text = L("status.not_enough_core");
                return;
            }

            SpendCoreShards(cost);
            SetMenuHangarUpgradeLevel(index, level + 1);
            PlayerPrefs.SetInt(CoreShardsKey, coreShards);
            PlayerPrefs.Save();
            RefreshUpgradeLabels();
            ShowCoreForgeModuleDetail(index);
            if (statusText != null)
                statusText.text = LF("status.upgraded_level", MenuHangarUpgradeShortName(index), level + 1);
        }

        private void CloseCoreForgeModuleWindow()
        {
            selectedCoreForgeModuleIndex = -1;
            if (coreForgeModuleRoot != null)
                coreForgeModuleRoot.gameObject.SetActive(false);
            StartMenuHangarReturnToParking(DroneUpgradeTarget.Crafter);
            Time.timeScale = 1f;
        }

        private void ShowStorageDepotWindow()
        {
            if (storageDepotWindowRoot == null)
                return;

            RefreshStorageDepotWindow();
            storageDepotWindowRoot.gameObject.SetActive(true);
            storageDepotWindowRoot.SetAsLastSibling();
            HideMenuHangarUpgradeButtons();
            Time.timeScale = 0f;
        }

        private void RefreshStorageDepotWindow()
        {
            if (storageDepotStockText == null)
                return;

            int displayParts = testMode ? 9999 : ozParts;
            int displayCore = testMode ? 9999 : coreShards;
            storageDepotStockText.text = LF("storage.stock", displayParts, displayCore, StorageDepotStartParts);
        }

        private void CloseStorageDepotWindow()
        {
            if (storageDepotWindowRoot != null)
                storageDepotWindowRoot.gameObject.SetActive(false);
            Time.timeScale = 1f;
        }

        private void HandleStorageDepotClickInput()
        {
            if (!storageDepotOwned || storageDepotWindowRoot == null || storageDepotWindowRoot.gameObject.activeSelf)
                return;
            if (menuHangarProfileRoot != null && menuHangarProfileRoot.gameObject.activeSelf)
                return;
            if (droneUpgradeRoot != null && droneUpgradeRoot.gameObject.activeSelf)
                return;
            if (coreForgeModuleRoot != null && coreForgeModuleRoot.gameObject.activeSelf)
                return;

            ReadGameplayInput(out bool pressed, out _, out _, out Vector2 pointerPosition, out _);
            if (!pressed || IsPointerOverButton(pointerPosition) || !IsPointerOverStorageDepot(pointerPosition))
                return;

            ShowStorageDepotWindow();
        }

        private void TryStartOutpostBuild()
        {
            if (outpostBuilt)
            {
                if (statusText != null)
                    statusText.text = L("status.outpost_ready");
                return;
            }

            if (outpostBuilding)
            {
                if (statusText != null)
                    statusText.text = L("status.outpost_building");
                return;
            }

            if (!HasOzParts(OutpostBuildPartsCost))
            {
                if (statusText != null)
                    statusText.text = LF("status.outpost_need_parts", OutpostBuildPartsCost);
                return;
            }

            SpendOzParts(OutpostBuildPartsCost);
            PlayerPrefs.SetInt(OzPartsKey, ozParts);
            PlayerPrefs.Save();
            outpostBuilding = true;
            outpostBuildProgress = 0f;
            outpostPositionLocked = false;
            targetOutpostY = ClampOutpostY(ResolveDefaultOutpostY());
            outpostY = targetOutpostY;
            RefreshHud();
            RefreshUpgradeLabels();
            if (statusText != null)
                statusText.text = LF("status.outpost_started", OutpostBuildPartsCost);
        }

        private DroneUpgradeTarget CurrentDraggedDroneUpgradeTarget()
        {
            if (battleDraggedDroneTarget != DroneUpgradeTarget.None)
                return battleDraggedDroneTarget;
            if (menuHangarDraggedUpgradeTarget != DroneUpgradeTarget.None)
                return menuHangarDraggedUpgradeTarget;
            if (crafterDragging)
                return DroneUpgradeTarget.Crafter;
            if (generatorDragging)
                return DroneUpgradeTarget.Generator;
            if (repairDragging)
                return DroneUpgradeTarget.Repair;
            if (shieldDroneDragging)
                return DroneUpgradeTarget.Shield;
            if (collectorDroneDragging)
                return DroneUpgradeTarget.Collector;

            return DroneUpgradeTarget.None;
        }

        private DroneUpgradeTarget ResolveBattleDraggedDroneTarget(Vector2 screenPosition)
        {
            if (IsBattleDroneCommandTargetActive(DroneUpgradeTarget.Crafter) && IsPointerOverDrone(screenPosition, crafterDrone))
                return DroneUpgradeTarget.Crafter;
            if (IsBattleDroneCommandTargetActive(DroneUpgradeTarget.Generator) && IsPointerOverDrone(screenPosition, generatorDrone))
                return DroneUpgradeTarget.Generator;
            if (IsBattleDroneCommandTargetActive(DroneUpgradeTarget.Repair) && IsPointerOverDrone(screenPosition, repairDrone))
                return DroneUpgradeTarget.Repair;
            if (IsBattleDroneCommandTargetActive(DroneUpgradeTarget.Shield) && IsPointerOverDrone(screenPosition, shieldDrone))
                return DroneUpgradeTarget.Shield;
            if (IsBattleDroneCommandTargetActive(DroneUpgradeTarget.Collector) && IsPointerOverDrone(screenPosition, collectorDrone))
                return DroneUpgradeTarget.Collector;
            if (IsBattleDroneCommandTargetActive(DroneUpgradeTarget.MineLayer) && IsPointerOverDrone(screenPosition, mineLayerDrone))
                return DroneUpgradeTarget.MineLayer;
            if (IsBattleDroneCommandTargetActive(DroneUpgradeTarget.Hive) && IsPointerOverDrone(screenPosition, hiveDrone))
                return DroneUpgradeTarget.Hive;
            if (IsBattleDroneCommandTargetActive(DroneUpgradeTarget.Gladiator) && IsPointerOverDrone(screenPosition, gladiatorDrone))
                return DroneUpgradeTarget.Gladiator;
            if (IsBattleDroneCommandTargetActive(DroneUpgradeTarget.Horizon) && IsPointerOverDrone(screenPosition, horizonDrone))
                return DroneUpgradeTarget.Horizon;
            if (IsBattleDroneCommandTargetActive(DroneUpgradeTarget.Tamer) && IsPointerOverDrone(screenPosition, tamerDrone))
                return DroneUpgradeTarget.Tamer;
            if (IsBattleDroneCommandTargetActive(DroneUpgradeTarget.Queen) && IsPointerOverDrone(screenPosition, queenDrone))
                return DroneUpgradeTarget.Queen;
            if (IsBattleDroneCommandTargetActive(DroneUpgradeTarget.Mimic) && IsPointerOverDrone(screenPosition, mimicDrone))
                return DroneUpgradeTarget.Mimic;
            if (IsBattleDroneCommandTargetActive(DroneUpgradeTarget.Sniper) && IsPointerOverDrone(screenPosition, sniperDrone))
                return DroneUpgradeTarget.Sniper;

            return DroneUpgradeTarget.None;
        }

        private bool IsBattleDroneCommandTargetActive(DroneUpgradeTarget target)
        {
            RectTransform rect = GetDroneUpgradeTargetRect(target);
            if (rect == null || !rect.gameObject.activeSelf)
                return false;

            switch (target)
            {
                case DroneUpgradeTarget.Crafter:
                    return crafterSpawnedThisRun;
                case DroneUpgradeTarget.Generator:
                    return generatorSpawnedThisRun && !generatorAttached && !generatorFlyingToOrb;
                case DroneUpgradeTarget.Repair:
                    return repairSpawnedThisRun && !repairAttached && !repairFlyingToOrb;
                case DroneUpgradeTarget.Shield:
                    return shieldDroneSpawnedThisRun && !shieldDroneFlyingToOrb;
                case DroneUpgradeTarget.Collector:
                    return collectorDroneSpawnedThisRun && !collectorDroneAttached && !collectorDroneFlyingToOrb;
                case DroneUpgradeTarget.MineLayer:
                    return mineLayerDroneSpawnedThisRun;
                case DroneUpgradeTarget.Hive:
                    return hiveDroneSpawnedThisRun;
                case DroneUpgradeTarget.Gladiator:
                    return gladiatorDroneSpawnedThisRun;
                case DroneUpgradeTarget.Horizon:
                    return horizonDroneSpawnedThisRun;
                case DroneUpgradeTarget.Tamer:
                    return tamerDroneSpawnedThisRun && !tamerDroneReturningToBase && tamerRechargeTimer <= 0f;
                case DroneUpgradeTarget.Queen:
                    return queenDroneSpawnedThisRun;
                case DroneUpgradeTarget.Mimic:
                    return mimicDroneSpawnedThisRun && mimicCooldownTimer <= 0f;
                case DroneUpgradeTarget.Sniper:
                    return sniperDroneSpawnedThisRun;
                default:
                    return false;
            }
        }

        private void MoveBattleDraggedDroneToCommand(DroneUpgradeTarget target, Vector2 commandPosition)
        {
            RectTransform drone = GetDroneUpgradeTargetRect(target);
            if (drone == null)
                return;

            Vector2 from = GetDroneUpgradeTargetPosition(target);
            float speed = ResolveDroneCommandMoveSpeed(target, false);
            commandPosition = ResolveBattleDroneCommandPosition(target, commandPosition);
            droneCommandPosition = commandPosition;
            droneCommandActive = true;
            UpdateDroneCommandVisuals(from, commandPosition, target);

            switch (target)
            {
                case DroneUpgradeTarget.Crafter:
                    crafterArrivingToWork = false;
                    MoveDroneTowardCommand(crafterDrone, ref crafterPosition, commandPosition, speed, Mathf.Sin(Time.time * 18f) * 2f);
                    break;
                case DroneUpgradeTarget.Generator:
                    generatorAttached = false;
                    generatorFlyingToOrb = false;
                    generatorChargeTarget = DroneChargeTarget.None;
                    generatorDroneChargeTimer = 0f;
                    MoveDroneTowardCommand(generatorDrone, ref generatorPosition, commandPosition, speed, Mathf.Sin(Time.time * 18f) * 2f);
                    break;
                case DroneUpgradeTarget.Repair:
                    repairAttached = false;
                    repairFlyingToOrb = false;
                    MoveDroneTowardCommand(repairDrone, ref repairPosition, commandPosition, speed, Mathf.Sin(Time.time * 18f) * 2f);
                    break;
                case DroneUpgradeTarget.Shield:
                    shieldDroneAttached = false;
                    shieldDroneFlyingToOrb = false;
                    MoveShieldDroneTowardCommand(shieldDrone, ref shieldDronePosition, commandPosition, speed, Mathf.Sin(Time.time * 18f) * 2f);
                    break;
                case DroneUpgradeTarget.Collector:
                    collectorDroneAttached = false;
                    collectorDroneFlyingToOrb = false;
                    MoveDroneTowardCommand(collectorDrone, ref collectorDronePosition, commandPosition, speed, Mathf.Sin(Time.time * 18f) * 2f);
                    break;
                case DroneUpgradeTarget.MineLayer:
                    MoveDroneTowardCommand(mineLayerDrone, ref mineLayerDronePosition, commandPosition, speed, Mathf.Sin(Time.time * 18f) * 2f);
                    break;
                case DroneUpgradeTarget.Hive:
                    hiveMiniTurretCraftProgress = 0f;
                    if (!TryResolveHiveOutpostMount(commandPosition, out _, out _))
                    {
                        hiveMountedOnOutpost = false;
                        hiveOutpostSlotIndex = -1;
                    }
                    MoveDroneTowardCommand(hiveDrone, ref hiveDronePosition, commandPosition, speed, Mathf.Sin(Time.time * 18f) * 2f);
                    FaceDroneToward(hiveDrone, hiveDronePosition, commandPosition, 0f);
                    break;
                case DroneUpgradeTarget.Gladiator:
                    MoveDroneTowardCommand(gladiatorDrone, ref gladiatorDronePosition, commandPosition, speed, Mathf.Sin(Time.time * 18f) * 2f);
                    break;
                case DroneUpgradeTarget.Horizon:
                    MoveDroneTowardCommand(horizonDrone, ref horizonDronePosition, commandPosition, speed, Mathf.Sin(Time.time * 18f) * 2f);
                    break;
                case DroneUpgradeTarget.Tamer:
                    tamerTargetIndex = -1;
                    tamerCaptureProgress = 0f;
                    MoveDroneTowardCommand(tamerDrone, ref tamerDronePosition, commandPosition, speed, Mathf.Sin(Time.time * 18f) * 2f);
                    break;
                case DroneUpgradeTarget.Queen:
                    MoveDroneTowardCommand(queenDrone, ref queenDronePosition, commandPosition, speed, Mathf.Sin(Time.time * 18f) * 2f);
                    break;
                case DroneUpgradeTarget.Mimic:
                    mimicAimPosition = commandPosition;
                    UpdateMimicAimVisuals(commandPosition);
                    break;
                case DroneUpgradeTarget.Sniper:
                    if (sniperAimingMode)
                    {
                        sniperPendingOutpostDetach = false;
                        sniperAimPosition = commandPosition;
                        UpdateSniperAimVisuals(commandPosition);
                    }
                    else
                    {
                        HideSniperAimVisuals();
                        if (sniperMountedOnOutpost)
                        {
                            sniperPendingOutpostDetach = true;
                            sniperPendingOutpostDetachPosition = commandPosition;
                            FaceSniperDroneToward(sniperDrone, sniperDronePosition, commandPosition);
                            break;
                        }

                        if (!TryResolveSniperOutpostMount(commandPosition, out _, out _))
                        {
                            sniperMountedOnOutpost = false;
                            sniperOutpostSlotIndex = -1;
                        }
                        sniperPendingOutpostDetach = false;
                        sniperHomePosition = commandPosition;
                        MoveSniperDroneTowardCommand(commandPosition, speed);
                    }
                    break;
            }

            drone.SetAsLastSibling();
        }

        private Vector2 ResolveBattleDroneCommandPosition(DroneUpgradeTarget target, Vector2 localPoint)
        {
            droneCommandMagnetToUpgradePad = false;
            if (target == DroneUpgradeTarget.Sniper)
                return ResolveSniperBaseZoneCommandPosition(localPoint);
            if (target == DroneUpgradeTarget.Hive && TryResolveHiveOutpostMount(localPoint, out _, out Vector2 hiveMountPosition))
                return hiveMountPosition;

            if (target == DroneUpgradeTarget.Crafter
                && state == GameState.Playing
                && !menuHangarOpen
                && HasVisibleDroneUpgradePadAccess()
                && droneUpgradePad != null
                && droneUpgradePad.gameObject.activeSelf)
            {
                Vector2 padPosition = ResolveDroneUpgradePadWorldPosition();
                float radius = Mathf.Max(DroneUpgradePadDropRadius, Mathf.Min(droneUpgradePad.rect.width, droneUpgradePad.rect.height) * 0.62f);
                if (Vector2.Distance(localPoint, padPosition) <= radius)
                {
                    droneCommandMagnetToUpgradePad = true;
                    return padPosition;
                }
            }

            return localPoint;
        }

        private Vector2 ResolveSniperBaseZoneCommandPosition(Vector2 localPoint)
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return localPoint;

            float zoneTop = ResolveSniperBaseZoneTop(root);
            sniperAimingMode = localPoint.y > zoneTop;
            if (sniperAimingMode)
            {
                CaptureSniperAimCameraOffset();
                if (TryFindSniperAimTarget(localPoint, out HazardView target, out Vector2 targetPosition))
                {
                    sniperLockedTarget = target;
                    return targetPosition;
                }

                sniperLockedTarget = null;
                return localPoint;
            }

            sniperLockedTarget = null;
            sniperAimCameraCaptured = false;
            if (!sniperMountedOnOutpost && TryResolveSniperOutpostMount(localPoint, out _, out Vector2 mountPosition))
                return mountPosition;

            float halfWidth = root.rect.width * 0.5f;
            float visibleBottom = -root.rect.height * 0.5f - hangarRevealOffset;
            float visibleTop = root.rect.height * 0.5f - hangarRevealOffset;
            float bottom = visibleBottom + SniperBaseZoneBottomPadding;
            float top = Mathf.Min(zoneTop, visibleTop - SniperBaseZoneTopPadding);
            if (top < bottom + 120f)
                top = zoneTop;

            float sidePadding = Mathf.Max(72f, root.rect.width * 0.075f);
            return new Vector2(
                Mathf.Clamp(localPoint.x, -halfWidth + sidePadding, halfWidth - sidePadding),
                Mathf.Clamp(localPoint.y, bottom, top));
        }

        private bool TryResolveSniperOutpostMount(Vector2 point, out int slotIndex, out Vector2 mountPosition)
        {
            slotIndex = -1;
            mountPosition = point;
            if (!outpostBuilt)
                return false;

            float bestDistance = SniperOutpostMountRadius;
            for (int i = 0; i < outpostSlots.Length; i++)
            {
                if (i == 2)
                    continue;

                Vector2 slotPosition = ResolveOutpostSlotPosition(i);
                float distance = Vector2.Distance(point, slotPosition);
                if (distance >= bestDistance)
                    continue;

                bestDistance = distance;
                slotIndex = i;
                mountPosition = ResolveSniperOutpostMountPosition(i);
            }

            return slotIndex >= 0;
        }

        private Vector2 ResolveSniperOutpostMountPosition(int slotIndex)
        {
            return ResolveOutpostSlotPosition(slotIndex) + new Vector2(0f, SniperOutpostMountYOffset);
        }

        private bool TryResolveHiveOutpostMount(Vector2 point, out int slotIndex, out Vector2 mountPosition)
        {
            slotIndex = -1;
            mountPosition = point;
            if (!outpostBuilt)
                return false;

            float bestDistance = HiveOutpostMountRadius;
            for (int i = 0; i < outpostSlots.Length; i++)
            {
                if (i == 2)
                    continue;

                Vector2 slotPosition = ResolveOutpostSlotPosition(i);
                float distance = Vector2.Distance(point, slotPosition);
                if (distance >= bestDistance)
                    continue;

                bestDistance = distance;
                slotIndex = i;
                mountPosition = ResolveHiveOutpostMountPosition(i);
            }

            return slotIndex >= 0;
        }

        private Vector2 ResolveHiveOutpostMountPosition(int slotIndex)
        {
            return ResolveOutpostSlotPosition(slotIndex) + new Vector2(0f, HiveOutpostMountYOffset);
        }

        private bool TryMountHiveOnOutpost()
        {
            if (!outpostBuilt || !hiveDroneSpawnedThisRun)
                return false;
            if (!TryResolveHiveOutpostMount(droneCommandActive ? droneCommandPosition : hiveDronePosition, out int slotIndex, out Vector2 mountPosition))
                return false;

            hiveMountedOnOutpost = true;
            hiveOutpostSlotIndex = slotIndex;
            hiveTemporaryCommandActive = false;
            hiveTemporaryCommandReturning = false;
            hiveTemporaryCommandHoldTimer = 0f;
            hiveMiniTurretCraftProgress = 0f;
            hiveDronePatrolTarget = mountPosition;
            if (hiveDrone != null)
                hiveDrone.SetAsLastSibling();
            if (statusText != null)
                statusText.text = "HIVE MOUNTED";
            return true;
        }

        private float ResolveSniperBaseZoneTop(RectTransform root)
        {
            if (outpostBuilt)
                return ResolveOutpostSlotPosition(2).y + OutpostOrbSlotSize * 0.5f + SniperBaseZoneTopPadding;

            if (baseShipHull != null)
                return ResolveBaseShipDockPosition().y + Mathf.Max(220f, baseShipHull.sizeDelta.y * 0.22f);

            return root.rect.height * 0.12f;
        }

        private bool TryFindSniperAimTarget(Vector2 aimPoint, out HazardView target, out Vector2 targetPosition)
        {
            target = null;
            targetPosition = aimPoint;

            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return false;

            float bestDistance = SniperTargetSnapRadius;
            for (int i = 0; i < hazards.Count; i++)
            {
                HazardView hazard = hazards[i];
                if (!IsValidSniperTarget(hazard))
                    continue;

                Vector2 hazardPosition = GetHazardCanvasPosition(hazard, root);
                float distance = Vector2.Distance(aimPoint, hazardPosition);
                if (distance >= bestDistance)
                    continue;

                bestDistance = distance;
                target = hazard;
                targetPosition = hazardPosition;
            }

            return target != null;
        }

        private bool TryMountSniperOnOutpost()
        {
            if (!outpostBuilt || !sniperDroneSpawnedThisRun || sniperAimingMode)
                return false;
            if (!TryResolveSniperOutpostMount(droneCommandActive ? droneCommandPosition : sniperDronePosition, out int slotIndex, out Vector2 mountPosition))
                return false;

            sniperMountedOnOutpost = true;
            sniperOutpostSlotIndex = slotIndex;
            sniperPendingOutpostDetach = false;
            sniperLockedTarget = null;
            sniperAimingMode = false;
            sniperRecoilOffset = Vector2.zero;
            sniperHomePosition = mountPosition;
            sniperDronePosition = mountPosition;
            if (sniperDrone != null)
            {
                sniperDrone.anchoredPosition = mountPosition;
                sniperDrone.localRotation = Quaternion.identity;
                sniperDrone.SetAsLastSibling();
            }
            if (statusText != null)
                statusText.text = "SNIPER MOUNTED";
            return true;
        }

        private void DetachSniperFromOutpost(Vector2 movePosition)
        {
            sniperMountedOnOutpost = false;
            sniperOutpostSlotIndex = -1;
            sniperPendingOutpostDetach = false;
            sniperLockedTarget = null;
            sniperAimingMode = false;
            sniperHomePosition = movePosition;
            HideSniperAimVisuals();
            if (statusText != null)
                statusText.text = "SNIPER MOVING";
        }

        private bool IsValidSniperTarget(HazardView hazard)
        {
            return hazard != null
                && hazard.Root != null
                && hazard.Root.gameObject.activeSelf
                && !hazard.ElectricDeathPending;
        }

        private void UpdateDroneCommandVisuals(Vector2 from, Vector2 to, DroneUpgradeTarget target)
        {
            if (droneCommandMarker != null)
            {
                droneCommandMarker.gameObject.SetActive(true);
                droneCommandMarker.anchoredPosition = to;
                float pulse = 1f + Mathf.Sin(Time.time * 13f) * 0.08f;
                droneCommandMarker.localScale = Vector3.one * pulse;
                Image markerImage = droneCommandMarker.GetComponent<Image>();
                if (markerImage != null)
                    markerImage.color = target == DroneUpgradeTarget.Sniper && sniperAimingMode
                        ? new Color(1f, 0.10f, 0.06f, 0.58f)
                        : new Color(1f, 0.82f, 0.18f, target == DroneUpgradeTarget.Sniper ? 0.38f : 0.46f);
                droneCommandMarker.SetAsLastSibling();
            }

            if (droneCommandLine == null)
                return;

            Vector2 direction = to - from;
            float length = direction.magnitude;
            if (length < 3f)
            {
                droneCommandLine.gameObject.SetActive(false);
                return;
            }

            droneCommandLine.gameObject.SetActive(true);
            droneCommandLine.anchoredPosition = from;
            droneCommandLine.sizeDelta = new Vector2(DroneCommandLineWidth + Mathf.Sin(Time.time * 24f) * 0.55f, length);
            droneCommandLine.localRotation = Quaternion.Euler(0f, 0f, Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg - 90f);
            Image lineImage = droneCommandLine.GetComponent<Image>();
            if (lineImage != null)
                lineImage.color = target == DroneUpgradeTarget.Sniper && sniperAimingMode
                    ? new Color(1f, 0.10f, 0.06f, 0.72f)
                    : new Color(1f, 0.82f, 0.18f, target == DroneUpgradeTarget.Sniper ? 0.52f : 0.72f);
            droneCommandLine.SetAsLastSibling();
        }

        private void FaceCommandedDroneToward(DroneUpgradeTarget target, RectTransform drone, Vector2 from, Vector2 commandPosition)
        {
            if (drone == null)
                return;

            float wobble = Mathf.Sin(Time.unscaledTime * 18f) * 2f;
            if (target == DroneUpgradeTarget.Shield)
                FaceShieldDroneToward(drone, from, commandPosition, wobble);
            else
                FaceDroneToward(drone, from, commandPosition, wobble);
        }

        private static void MoveDroneTowardCommand(RectTransform drone, ref Vector2 position, Vector2 target, float speed, float wobble = 0f)
        {
            Vector2 previous = position;
            position = Vector2.MoveTowards(position, target, Mathf.Max(1f, speed) * Time.deltaTime);
            if (drone != null)
                drone.anchoredPosition = position;

            Vector2 faceTarget = (position - previous).sqrMagnitude > 0.08f ? position : target;
            FaceDroneToward(drone, previous, faceTarget, wobble);
        }

        private void MoveSniperDroneTowardCommand(Vector2 target, float speed)
        {
            Vector2 previous = sniperDronePosition;
            sniperDronePosition = Vector2.MoveTowards(sniperDronePosition, target, Mathf.Max(1f, speed) * Time.deltaTime);
            if (sniperDrone != null)
                sniperDrone.anchoredPosition = ResolveSniperVisualPosition();

            Vector2 faceTarget = (sniperDronePosition - previous).sqrMagnitude > 0.08f ? sniperDronePosition : target;
            FaceSniperDroneToward(sniperDrone, previous, faceTarget, Mathf.Sin(Time.time * 18f) * 2f);
        }

        private static void MoveShieldDroneTowardCommand(RectTransform drone, ref Vector2 position, Vector2 target, float speed, float wobble = 0f)
        {
            Vector2 previous = position;
            position = Vector2.MoveTowards(position, target, Mathf.Max(1f, speed) * Time.deltaTime);
            if (drone != null)
                drone.anchoredPosition = position;

            Vector2 faceTarget = (position - previous).sqrMagnitude > 0.08f ? position : target;
            FaceShieldDroneToward(drone, previous, faceTarget, wobble);
        }

        private float ResolveDroneCommandMoveSpeed(DroneUpgradeTarget target, bool menuHangar)
        {
            float speed;
            switch (target)
            {
                case DroneUpgradeTarget.Generator:
                case DroneUpgradeTarget.Repair:
                case DroneUpgradeTarget.Collector:
                    speed = 260f;
                    break;
                case DroneUpgradeTarget.Shield:
                    speed = 238f;
                    break;
                case DroneUpgradeTarget.Crafter:
                case DroneUpgradeTarget.Horizon:
                case DroneUpgradeTarget.Tamer:
                    speed = 218f;
                    break;
                case DroneUpgradeTarget.MineLayer:
                case DroneUpgradeTarget.Hive:
                    speed = 194f;
                    break;
                case DroneUpgradeTarget.Gladiator:
                case DroneUpgradeTarget.Queen:
                    speed = 158f;
                    break;
                case DroneUpgradeTarget.Mimic:
                case DroneUpgradeTarget.Sniper:
                    speed = 205f;
                    break;
                default:
                    speed = DroneCommandMoveSpeed;
                    break;
            }

            return menuHangar ? speed * (MenuHangarDroneCommandMoveSpeed / DroneCommandMoveSpeed) : speed;
        }

        private void HideDroneCommandVisuals()
        {
            if (droneCommandMarker != null)
                droneCommandMarker.gameObject.SetActive(false);
            if (droneCommandLine != null)
                droneCommandLine.gameObject.SetActive(false);
        }

        private bool IsPointerOverDroneUpgradePad(Vector2 screenPosition)
        {
            if (droneUpgradePad == null || !droneUpgradePad.gameObject.activeInHierarchy)
                return false;

            if (!RectTransformUtility.ScreenPointToLocalPointInRectangle(droneUpgradePad, screenPosition, null, out Vector2 padLocalPoint))
                return false;

            Rect rect = droneUpgradePad.rect;
            float padding = Mathf.Max(36f, Mathf.Min(rect.width, rect.height) * 0.16f);
            return padLocalPoint.x >= rect.xMin - padding
                && padLocalPoint.x <= rect.xMax + padding
                && padLocalPoint.y >= rect.yMin - padding
                && padLocalPoint.y <= rect.yMax + padding;
        }

        private bool IsDroneUpgradeTargetOverPad(DroneUpgradeTarget target)
        {
            if (target == DroneUpgradeTarget.None || droneUpgradePad == null || !droneUpgradePad.gameObject.activeInHierarchy)
                return false;

            Vector2 padPosition = ResolveDroneUpgradePadWorldPosition();
            float radius = Mathf.Max(DroneUpgradePadDropRadius, Mathf.Min(droneUpgradePad.rect.width, droneUpgradePad.rect.height) * 0.42f);
            return Vector2.Distance(GetDroneUpgradeTargetPosition(target), padPosition) <= radius;
        }

        private bool IsDroneCommandOverUpgradePad()
        {
            if (!droneCommandActive || droneUpgradePad == null || !droneUpgradePad.gameObject.activeInHierarchy)
                return false;

            Vector2 padPosition = ResolveDroneUpgradePadWorldPosition();
            float radius = Mathf.Max(DroneUpgradePadDropRadius, Mathf.Min(droneUpgradePad.rect.width, droneUpgradePad.rect.height) * 0.50f);
            return Vector2.Distance(droneCommandPosition, padPosition) <= radius;
        }

        private bool HasVisibleCoreForgeModuleUpgradeAccess()
        {
            return IsTutorialCompleted()
                && coreForgeOwned
                && menuHangarOpen
                && state == GameState.Menu
                && coreForge != null
                && coreForge.gameObject.activeInHierarchy;
        }

        private float ResolveCoreForgeCommandRadius()
        {
            if (coreForge == null)
                return 120f;

            return Mathf.Max(112f, Mathf.Min(coreForge.rect.width, coreForge.rect.height) * 0.58f);
        }

        private bool IsDroneCommandOverCoreForge()
        {
            if (!droneCommandActive || !HasVisibleCoreForgeModuleUpgradeAccess())
                return false;

            return Vector2.Distance(droneCommandPosition, ResolveCoreForgeWorldPosition()) <= ResolveCoreForgeCommandRadius();
        }

        private Vector2 ResolveCoreForgeWorldPosition()
        {
            if (baseShipHull == null || coreForge == null)
                return Vector2.zero;

            return ResolveBaseShipLocalToWorldPoint(coreForge.anchoredPosition);
        }

        private Vector2 ResolveDroneUpgradePadWorldPosition()
        {
            if (baseShipHull == null || droneUpgradePad == null)
                return Vector2.zero;

            return ResolveBaseShipLocalToWorldPoint(droneUpgradePad.anchoredPosition);
        }

        private bool IsDroneUpgradeTargetUnderStationControl(DroneUpgradeTarget target)
        {
            return target != DroneUpgradeTarget.None
                && (target == menuHangarDraggedUpgradeTarget
                    || menuHangarCommandStates.ContainsKey(target)
                    || (droneUpgradePadDocking && target == pendingDroneUpgradeTarget)
                    || (coreForgeModuleDocking && target == DroneUpgradeTarget.Crafter)
                    || (coreForgeModuleRoot != null && coreForgeModuleRoot.gameObject.activeSelf && target == DroneUpgradeTarget.Crafter)
                    || (droneUpgradeRoot != null && droneUpgradeRoot.gameObject.activeSelf && target == selectedDroneUpgradeTarget));
        }

        private DroneUpgradeTarget ResolveMenuHangarDraggedUpgradeTarget(Vector2 screenPosition)
        {
            if (crafterOwned && IsPointerOverDrone(screenPosition, crafterDrone))
                return DroneUpgradeTarget.Crafter;
            if (generatorOwned && IsPointerOverDrone(screenPosition, generatorDrone))
                return DroneUpgradeTarget.Generator;
            if (repairOwned && IsPointerOverDrone(screenPosition, repairDrone))
                return DroneUpgradeTarget.Repair;
            if (shieldDroneOwned && IsPointerOverDrone(screenPosition, shieldDrone))
                return DroneUpgradeTarget.Shield;
            if (collectorDroneOwned && IsPointerOverDrone(screenPosition, collectorDrone))
                return DroneUpgradeTarget.Collector;
            if (ozCoreMinerOwned && IsPointerOverDrone(screenPosition, ozCoreMinerDrone))
                return DroneUpgradeTarget.OzCoreMiner;
            if (mineLayerDroneOwned && IsPointerOverDrone(screenPosition, mineLayerDrone))
                return DroneUpgradeTarget.MineLayer;
            if (hiveDroneOwned && IsPointerOverDrone(screenPosition, hiveDrone))
                return DroneUpgradeTarget.Hive;
            if (gladiatorDroneOwned && IsPointerOverDrone(screenPosition, gladiatorDrone))
                return DroneUpgradeTarget.Gladiator;
            if (horizonDroneOwned && IsPointerOverDrone(screenPosition, horizonDrone))
                return DroneUpgradeTarget.Horizon;
            if (tamerDroneOwned && IsPointerOverDrone(screenPosition, tamerDrone))
                return DroneUpgradeTarget.Tamer;
            if (queenDroneOwned && IsPointerOverDrone(screenPosition, queenDrone))
                return DroneUpgradeTarget.Queen;
            if (mimicDroneOwned && IsPointerOverDrone(screenPosition, mimicDrone))
                return DroneUpgradeTarget.Mimic;
            if (sniperDroneOwned && IsPointerOverDrone(screenPosition, sniperDrone))
                return DroneUpgradeTarget.Sniper;

            return DroneUpgradeTarget.None;
        }

