        private void MoveDraggedDroneToUpgradePad(DroneUpgradeTarget target, Vector2 padPosition)
        {
            switch (target)
            {
                case DroneUpgradeTarget.Crafter:
                    crafterArrivingToWork = false;
                    crafterPosition = padPosition;
                    if (crafterDrone != null)
                        crafterDrone.anchoredPosition = crafterPosition;
                    return;
                case DroneUpgradeTarget.Generator:
                    generatorAttached = false;
                    generatorFlyingToOrb = false;
                    generatorPosition = padPosition;
                    if (generatorDrone != null)
                        generatorDrone.anchoredPosition = generatorPosition;
                    return;
                case DroneUpgradeTarget.Repair:
                    repairAttached = false;
                    repairFlyingToOrb = false;
                    repairPosition = padPosition;
                    if (repairDrone != null)
                        repairDrone.anchoredPosition = repairPosition;
                    return;
                case DroneUpgradeTarget.Shield:
                    shieldDroneAttached = false;
                    shieldDroneFlyingToOrb = false;
                    shieldDronePosition = padPosition;
                    if (shieldDrone != null)
                        shieldDrone.anchoredPosition = shieldDronePosition;
                    return;
                case DroneUpgradeTarget.Collector:
                    collectorDroneAttached = false;
                    collectorDroneFlyingToOrb = false;
                    collectorDronePosition = padPosition;
                    if (collectorDrone != null)
                        collectorDrone.anchoredPosition = collectorDronePosition;
                    return;
                default:
                    SetDroneUpgradeTargetPosition(target, padPosition);
                    RectTransform drone = GetDroneUpgradeTargetRect(target);
                    if (drone != null)
                        drone.anchoredPosition = padPosition;
                    return;
            }
        }

        private bool TryRepairWithParts(ref int targetHealth, int maxHealth, ref float repairTimer, string repairSource, int hpPerPart = RepairHpPerPart, bool flashOrb = false)
        {
            if (targetHealth >= maxHealth)
            {
                repairTimer = 0f;
                return false;
            }

            bool tutorialFreeBaseRepair = IsTutorialShieldBaseRepairActive() && repairSource == "REPAIR BASE";
            if (!tutorialFreeBaseRepair && !HasOzParts(1))
            {
                repairTimer = 0f;
                if (statusText != null)
                    statusText.text = repairSource + " NEEDS OZPARTS";
                return false;
            }

            repairTimer += Time.deltaTime * QueenBuffRate(repairDrone);
            if (repairTimer < RepairPartInterval)
                return false;

            repairTimer = 0f;
            if (!tutorialFreeBaseRepair)
                SpendOzParts(1);
            int beforeHealth = targetHealth;
            targetHealth = Mathf.Min(maxHealth, targetHealth + Mathf.Max(1, hpPerPart));
            if (flashOrb && targetHealth > beforeHealth)
                orbRepairFlashTimer = 0.55f;
            PlayerPrefs.SetInt(OzPartsKey, ozParts);
            PlayerPrefs.Save();
            RefreshHud();
            RefreshUpgradeLabels();
            return true;
        }

        private bool IsTutorialShieldBaseRepairActive()
        {
            return tutorialShieldHangarLessonActive || tutorialShieldAttachLessonActive;
        }

        private Vector2 GetFreeDronePatrolTarget(RectTransform root, Vector2 currentPosition, ref Vector2 target, ref float timer, float bottomPadding, float topOffset, float xLimitFactor, float minHold = 1.4f, float maxHold = 3.2f)
        {
            if (root == null)
                return currentPosition;

            timer -= Time.deltaTime;
            bool needsNewTarget = timer <= 0f || Vector2.Distance(currentPosition, target) < 18f || !IsInsideFreeDroneZone(root, target, bottomPadding, topOffset, xLimitFactor);
            if (!needsNewTarget)
                return target;

            float halfWidth = root.rect.width * 0.5f;
            float xLimit = Mathf.Min(halfWidth * xLimitFactor, halfWidth - 34f);
            float bottomY = -root.rect.height * 0.5f + bottomPadding;
            float topY = ResolveGameOrbY() - topOffset;
            if (topY < bottomY + 24f)
                topY = bottomY + 24f;

            target = new Vector2(RandomRange(-xLimit, xLimit), RandomRange(bottomY, topY));
            timer = RandomRange(minHold, maxHold);
            return target;
        }

        private bool IsInsideFreeDroneZone(RectTransform root, Vector2 point, float bottomPadding, float topOffset, float xLimitFactor)
        {
            float halfWidth = root.rect.width * 0.5f;
            float xLimit = Mathf.Min(halfWidth * xLimitFactor, halfWidth - 34f);
            float bottomY = -root.rect.height * 0.5f + bottomPadding;
            float topY = Mathf.Max(bottomY + 24f, ResolveGameOrbY() - topOffset);
            return point.x >= -xLimit && point.x <= xLimit && point.y >= bottomY && point.y <= topY;
        }

        private Vector2 GetCrafterWorkHomePosition(RectTransform root)
        {
            if (root == null)
                return crafterPosition;

            return ResolveHangarDroneHomePosition(0, root);
        }

        private Vector2 ResolveHangarDroneHomePosition(int droneIndex, RectTransform root = null)
        {
            if (baseShipHull == null)
            {
                RectTransform fallbackRoot = root != null ? root : canvas != null ? canvas.transform as RectTransform : null;
                float bottomY = fallbackRoot != null ? -fallbackRoot.rect.height * 0.5f + 96f : -640f;
                return new Vector2((droneIndex - 1.5f) * 58f, bottomY);
            }

            switch (droneIndex)
            {
                case 1:
                    return ResolveBaseShipLocalToWorldPoint(new Vector2(-baseShipHull.sizeDelta.x * 0.13f, baseShipHull.sizeDelta.y * 0.50f));
                case 2:
                    return ResolveBaseShipLocalToWorldPoint(new Vector2(baseShipHull.sizeDelta.x * 0.13f, baseShipHull.sizeDelta.y * 0.50f));
                case 3:
                    return ResolveBaseShipLocalToWorldPoint(new Vector2(0f, baseShipHull.sizeDelta.y * 0.79f));
                case 4:
                    return ResolveBaseShipLocalToWorldPoint(new Vector2(-baseShipHull.sizeDelta.x * 0.24f, baseShipHull.sizeDelta.y * 0.70f));
                case 5:
                    return ResolveBaseShipLocalToWorldPoint(new Vector2(baseShipHull.sizeDelta.x * 0.26f, baseShipHull.sizeDelta.y * 0.62f));
                case 6:
                    return ResolveBaseShipLocalToWorldPoint(new Vector2(-baseShipHull.sizeDelta.x * 0.32f, baseShipHull.sizeDelta.y * 0.56f));
                case 7:
                    return ResolveBaseShipLocalToWorldPoint(new Vector2(baseShipHull.sizeDelta.x * 0.32f, baseShipHull.sizeDelta.y * 0.76f));
                case 8:
                    return ResolveBaseShipLocalToWorldPoint(new Vector2(0f, baseShipHull.sizeDelta.y * 0.92f));
                case 9:
                    return ResolveBaseShipLocalToWorldPoint(new Vector2(-baseShipHull.sizeDelta.x * 0.32f, baseShipHull.sizeDelta.y * 0.82f));
                case 10:
                    return ResolveBaseShipLocalToWorldPoint(new Vector2(baseShipHull.sizeDelta.x * 0.18f, baseShipHull.sizeDelta.y * 0.88f));
                case 11:
                    return ResolveBaseShipLocalToWorldPoint(new Vector2(0f, baseShipHull.sizeDelta.y * 0.40f));
                case 12:
                    return ResolveBaseShipLocalToWorldPoint(new Vector2(baseShipHull.sizeDelta.x * 0.28f, baseShipHull.sizeDelta.y * 0.42f));
                case 13:
                    return ResolveBaseShipLocalToWorldPoint(new Vector2(-baseShipHull.sizeDelta.x * 0.28f, baseShipHull.sizeDelta.y * 0.44f));
                default:
                    return ResolveBaseShipLocalToWorldPoint(new Vector2(0f, baseShipHull.sizeDelta.y * 0.57f));
            }
        }

        private Vector2 ResolveMenuHangarParkingPosition(int droneIndex, RectTransform root = null)
        {
            if (baseShipHull == null)
                return ResolveHangarDroneHomePosition(droneIndex, root);

            float width = baseShipHull.sizeDelta.x;
            float height = baseShipHull.sizeDelta.y;
            Vector2 local;
            switch (droneIndex)
            {
                case 0:
                    local = new Vector2(-width * 0.24f, height * 0.30f);
                    break;
                case 1:
                    local = new Vector2(width * 0.24f, height * 0.30f);
                    break;
                case 2:
                    local = new Vector2(-width * 0.12f, height * 0.41f);
                    break;
                case 3:
                    local = new Vector2(width * 0.12f, height * 0.41f);
                    break;
                case 4:
                    local = new Vector2(0f, height * 0.52f);
                    break;
                case 5:
                    local = new Vector2(-width * 0.32f, height * 0.50f);
                    break;
                case 6:
                    local = new Vector2(width * 0.32f, height * 0.50f);
                    break;
                case 7:
                    local = new Vector2(-width * 0.22f, height * 0.62f);
                    break;
                case 8:
                    local = new Vector2(width * 0.22f, height * 0.62f);
                    break;
                case 9:
                    local = new Vector2(-width * 0.34f, height * 0.70f);
                    break;
                case 10:
                    local = new Vector2(0f, height * 0.72f);
                    break;
                case 11:
                    local = new Vector2(width * 0.34f, height * 0.70f);
                    break;
                case 12:
                    local = new Vector2(-width * 0.14f, height * 0.82f);
                    break;
                case 13:
                    local = new Vector2(width * 0.14f, height * 0.82f);
                    break;
                default:
                    local = new Vector2(0f, height * 0.36f);
                    break;
            }

            return ResolveBaseShipLocalToWorldPoint(local);
        }

        private Vector2 ResolveHangarCargoBayPosition()
        {
            if (baseShipHull == null)
                return ResolveBaseShipDockPosition() + new Vector2(0f, -130f);

            return ResolveBaseShipLocalToWorldPoint(new Vector2(0f, baseShipHull.sizeDelta.y * 0.36f));
        }

        private Vector2 ResolveTutorialShieldCraftCenter()
        {
            if (baseShipHull == null)
                return ResolveBaseShipDockPosition() + new Vector2(0f, -260f);

            return ResolveBaseShipLocalToWorldPoint(new Vector2(0f, baseShipHull.sizeDelta.y * 0.24f));
        }

        private Vector2 ResolveHangarRecoveryOrbPosition()
        {
            return ResolveBaseShipDockPosition();
        }

        private Vector2 ResolveBaseRepairWorkPoint()
        {
            if (baseShipHull == null)
                return ResolveHangarCargoBayPosition();

            float side = Mathf.Sin(Time.time * 0.42f) >= 0f ? 1f : -1f;
            float y = Mathf.Lerp(baseShipHull.sizeDelta.y * 0.43f, baseShipHull.sizeDelta.y * 0.70f, Mathf.PingPong(Time.time * 0.24f, 1f));
            return ResolveBaseShipLocalToWorldPoint(new Vector2(baseShipHull.sizeDelta.x * 0.30f * side, y));
        }

        private bool IsOutpostNearBaseForRepair()
        {
            return outpostBuilt && Mathf.Abs(outpostY - ResolveDefaultOutpostY()) <= 34f;
        }

        private bool ShouldRepairOutpostWithRepairDrone()
        {
            return IsOutpostNearBaseForRepair()
                && baseShipHealth > BaseShipMaxHealth
                && baseShipHealth < CurrentSharedMaxHealth();
        }

        private Vector2 ResolveOutpostRepairWorkPoint()
        {
            int slot = Mathf.FloorToInt(Mathf.PingPong(Time.time * 0.65f, outpostSlots.Length - 0.01f));
            return ResolveOutpostSlotPosition(slot) + new Vector2(0f, OutpostSlotMountYOffset * 0.45f);
        }

        private Vector2 ResolveBaseShipLocalToWorldPoint(Vector2 localPoint)
        {
            RectTransform world = WorldCoordinateRoot();
            if (world == null || baseShipHull == null)
                return localPoint;

            return world.InverseTransformPoint(baseShipHull.TransformPoint(new Vector3(localPoint.x, localPoint.y, 0f)));
        }

        private Vector2 GetHangarDronePatrolTarget(RectTransform root, Vector2 currentPosition, ref Vector2 target, ref float timer, int droneIndex, float xRadius = 62f, float yRadius = 44f, float minHold = 1.3f, float maxHold = 3.1f)
        {
            Vector2 home = ResolveHangarDroneHomePosition(droneIndex, root);
            timer -= Time.deltaTime;
            bool needsNewTarget = timer <= 0f || Vector2.Distance(currentPosition, target) < 18f || Vector2.Distance(target, home) > Mathf.Max(xRadius, yRadius) * 1.65f;
            if (!needsNewTarget)
                return target;

            target = home + new Vector2(RandomRange(-xRadius, xRadius), RandomRange(-yRadius, yRadius));
            timer = RandomRange(minHold, maxHold);
            return target;
        }

        private Vector2 GetCompanionDronePatrolTarget(RectTransform root, Vector2 currentPosition, Vector2 anchor, ref Vector2 target, ref float timer)
        {
            if (root == null)
                return currentPosition;

            Vector2 hangarCenter = ResolveHangarDroneHomePosition(0, root);
            timer -= Time.deltaTime;
            bool needsNewTarget = timer <= 0f || Vector2.Distance(currentPosition, target) < 20f || Vector2.Distance(target, hangarCenter) > 150f;
            if (!needsNewTarget)
                return target;

            Vector2 offset = new Vector2(RandomRange(-78f, 78f), RandomRange(-54f, 48f));
            target = anchor + offset;
            timer = RandomRange(1.6f, 3.6f);
            return target;
        }

        private void ShowCraftProgress(float value)
        {
            if (craftFill == null)
                return;

            Transform track = craftFill.parent;
            if (track != null)
                track.gameObject.SetActive(true);
            UpdateStatusBarFill(craftFill, value, Gold, new Color(1f, 0.42f, 0.08f, 0.95f), false);
        }

        private void HideCraftProgress()
        {
            if (craftFill == null)
            {
                HideDroneCraftHolograms();
                return;
            }

            SetCenteredBarFill(craftFill, 0f);
            Transform track = craftFill.parent;
            if (track != null)
                track.gameObject.SetActive(false);
            HideDroneCraftHolograms();
        }

        private Vector2 GetCrafterBuildSlotPosition(CrafterBuildTarget target)
        {
            if (tutorialShieldHangarLessonActive && target == CrafterBuildTarget.Shield)
                return ResolveTutorialShieldCraftCenter();

            Vector2 station = ResolveDroneUpgradePadWorldPosition();
            return station == Vector2.zero ? crafterPosition : station;
        }

        private Vector2 GetCrafterBuildReleasePosition(CrafterBuildTarget target)
        {
            if (tutorialShieldHangarLessonActive && target == CrafterBuildTarget.Shield)
                return ResolveTutorialShieldCraftCenter() + new Vector2(0f, -74f);

            return ResolveCraftPlaceSpawnPosition(crafterPosition);
        }

        private Vector2 ResolveCraftPlaceSpawnPosition(Vector2 fallback)
        {
            Vector2 station = ResolveDroneUpgradePadWorldPosition();
            return station == Vector2.zero ? fallback : station;
        }

        private static int GetCrafterBuildHomeIndex(CrafterBuildTarget target)
        {
            switch (target)
            {
                case CrafterBuildTarget.Repair:
                    return 2;
                case CrafterBuildTarget.Generator:
                    return 1;
                case CrafterBuildTarget.Shield:
                    return 4;
                case CrafterBuildTarget.Collector:
                    return 3;
                case CrafterBuildTarget.MineLayer:
                    return 6;
                case CrafterBuildTarget.Hive:
                    return 7;
                case CrafterBuildTarget.Gladiator:
                    return 8;
                case CrafterBuildTarget.Horizon:
                    return 9;
                case CrafterBuildTarget.Tamer:
                    return 10;
                case CrafterBuildTarget.Queen:
                    return 11;
                case CrafterBuildTarget.Mimic:
                    return 12;
                case CrafterBuildTarget.Sniper:
                    return 13;
                default:
                    return 0;
            }
        }

        private Vector2 GetCrafterBuildOperatorPosition(CrafterBuildTarget target)
        {
            Vector2 slot = GetCrafterBuildSlotPosition(target);
            if (tutorialShieldHangarLessonActive && target == CrafterBuildTarget.Shield)
                return slot + new Vector2(Mathf.Sin(Time.time * 2.7f) * 70f, -58f + Mathf.Cos(Time.time * 2.7f) * 18f);

            float phase = Time.time * 2.25f + ((int)target * 0.38f);
            Vector2 orbit = new Vector2(Mathf.Sin(phase) * 92f, Mathf.Cos(phase) * 54f);
            return slot + orbit;
        }

        private void UpdateDroneCraftHologram(CrafterBuildTarget target, float progress)
        {
            RectTransform drone = null;
            string spritePath = null;
            bool alreadySpawned = false;
            switch (target)
            {
                case CrafterBuildTarget.Generator:
                    drone = generatorDrone;
                    spritePath = GeneratorDroneSpriteResourcePath;
                    alreadySpawned = generatorSpawnedThisRun;
                    break;
                case CrafterBuildTarget.Repair:
                    drone = repairDrone;
                    spritePath = RepairDroneSpriteResourcePath;
                    alreadySpawned = repairSpawnedThisRun;
                    break;
                case CrafterBuildTarget.Shield:
                    drone = shieldDrone;
                    spritePath = ShieldDroneSpriteResourcePath;
                    alreadySpawned = shieldDroneSpawnedThisRun;
                    break;
                case CrafterBuildTarget.Collector:
                    drone = collectorDrone;
                    spritePath = CollectorDroneSpriteResourcePath;
                    alreadySpawned = collectorDroneSpawnedThisRun;
                    break;
                case CrafterBuildTarget.MineLayer:
                    drone = mineLayerDrone;
                    spritePath = MineLayerDroneSpriteResourcePath;
                    alreadySpawned = mineLayerDroneSpawnedThisRun;
                    break;
                case CrafterBuildTarget.Hive:
                    drone = hiveDrone;
                    spritePath = HiveDroneSpriteResourcePath;
                    alreadySpawned = hiveDroneSpawnedThisRun;
                    break;
                case CrafterBuildTarget.Gladiator:
                    drone = gladiatorDrone;
                    spritePath = GladiatorDroneSpriteResourcePath;
                    alreadySpawned = gladiatorDroneSpawnedThisRun;
                    break;
                case CrafterBuildTarget.Horizon:
                    drone = horizonDrone;
                    spritePath = HorizonDroneSpriteResourcePath;
                    alreadySpawned = horizonDroneSpawnedThisRun;
                    break;
                case CrafterBuildTarget.Tamer:
                    drone = tamerDrone;
                    spritePath = TamerDroneSpriteResourcePath;
                    alreadySpawned = tamerDroneSpawnedThisRun;
                    break;
                case CrafterBuildTarget.Queen:
                    drone = queenDrone;
                    spritePath = QueenDroneSpriteResourcePath;
                    alreadySpawned = queenDroneSpawnedThisRun;
                    break;
                case CrafterBuildTarget.Mimic:
                    drone = mimicDrone;
                    spritePath = MimicDroneSpriteResourcePath;
                    alreadySpawned = mimicDroneSpawnedThisRun;
                    break;
                case CrafterBuildTarget.Sniper:
                    drone = sniperDrone;
                    spritePath = SniperDroneSpriteResourcePath;
                    alreadySpawned = sniperDroneSpawnedThisRun;
                    break;
            }

            if (drone == null || alreadySpawned)
                return;

            drone.gameObject.SetActive(true);
            ApplySpriteFromTextureResource(drone, spritePath);
            drone.anchoredPosition = GetCrafterBuildSlotPosition(target);
            float build = Mathf.SmoothStep(0f, 1f, progress);
            float pulse = 0.5f + Mathf.Sin(Time.time * 11f) * 0.5f;
            float finalScale = ResolveCrafterBuiltDroneScale(target);
            float scale = Mathf.Lerp(finalScale * 0.22f, finalScale, build) + pulse * Mathf.Lerp(0.055f, 0.015f, build);
            drone.localScale = Vector3.one * scale;
            drone.localRotation = Quaternion.Euler(0f, 0f, Mathf.Sin(Time.time * 8f) * 3.6f);
            Image image = drone.GetComponent<Image>();
            if (image != null)
            {
                Color greenBlink = Color.Lerp(new Color(0.18f, 1f, 0.34f, 0.48f), Color.white, build);
                greenBlink.g = 1f;
                greenBlink.a = Mathf.Lerp(0.42f, 1f, build) * Mathf.Lerp(0.55f, 1f, pulse);
                image.color = greenBlink;
            }
            drone.SetAsLastSibling();
        }

        private float ResolveCrafterBuiltDroneScale(CrafterBuildTarget target)
        {
            switch (target)
            {
                case CrafterBuildTarget.Hive:
                    return 1.02f;
                case CrafterBuildTarget.MineLayer:
                    return 1.06f;
                case CrafterBuildTarget.Tamer:
                    return 0.94f;
                case CrafterBuildTarget.Queen:
                    return 0.90f;
                case CrafterBuildTarget.Mimic:
                case CrafterBuildTarget.Sniper:
                    return 0.88f;
                default:
                    return 1.16f;
            }
        }

        private void HideDroneCraftHolograms()
        {
            HideDroneCraftHologram(generatorDrone, generatorSpawnedThisRun);
            HideDroneCraftHologram(repairDrone, repairSpawnedThisRun);
            HideDroneCraftHologram(shieldDrone, shieldDroneSpawnedThisRun);
            HideDroneCraftHologram(collectorDrone, collectorDroneSpawnedThisRun);
            HideDroneCraftHologram(mineLayerDrone, mineLayerDroneSpawnedThisRun);
            HideDroneCraftHologram(hiveDrone, hiveDroneSpawnedThisRun);
            HideDroneCraftHologram(gladiatorDrone, gladiatorDroneSpawnedThisRun);
            HideDroneCraftHologram(horizonDrone, horizonDroneSpawnedThisRun);
            HideDroneCraftHologram(tamerDrone, tamerDroneSpawnedThisRun);
            HideDroneCraftHologram(queenDrone, queenDroneSpawnedThisRun);
            HideDroneCraftHologram(mimicDrone, mimicDroneSpawnedThisRun);
            HideDroneCraftHologram(sniperDrone, sniperDroneSpawnedThisRun);
        }

        private static void HideDroneCraftHologram(RectTransform drone, bool spawned)
        {
            if (drone != null && !spawned)
                drone.gameObject.SetActive(false);
        }

        private static void ResetDroneImageColor(RectTransform drone)
        {
            if (drone == null)
                return;

            Image image = drone.GetComponent<Image>();
            if (image != null)
                image.color = Color.white;
        }

        private static Vector2 WorkVibration(float strength, float speed = 38f)
        {
            return new Vector2(Mathf.Sin(Time.time * speed) * strength, Mathf.Cos(Time.time * (speed * 0.77f)) * strength);
        }

        private static void FaceDroneToward(RectTransform drone, Vector2 from, Vector2 target, float wobble = 0f)
        {
            if (drone == null)
                return;

            Vector2 direction = target - from;
            if (direction.sqrMagnitude < 4f)
                return;

            float angle = Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg - 90f + DroneSpriteNoseOffset;
            float current = drone.localEulerAngles.z;
            float next = Mathf.LerpAngle(current, angle + wobble, 1f - Mathf.Exp(-6.5f * Time.deltaTime));
            drone.localRotation = Quaternion.Euler(0f, 0f, next);
        }

        private static void FaceSniperDroneToward(RectTransform drone, Vector2 from, Vector2 target, float wobble = 0f)
        {
            if (drone == null)
                return;

            Vector2 direction = target - from;
            if (direction.sqrMagnitude < 4f)
                return;

            float angle = Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg - 90f;
            float current = drone.localEulerAngles.z;
            float next = Mathf.LerpAngle(current, angle + wobble, 1f - Mathf.Exp(-8.5f * Time.deltaTime));
            drone.localRotation = Quaternion.Euler(0f, 0f, next);
        }

        private static void FaceOzCoreMinerToward(RectTransform drone, Vector2 from, Vector2 target, float wobble = 0f, float response = 8f)
        {
            if (drone == null)
                return;

            Vector2 direction = target - from;
            if (direction.sqrMagnitude < 4f)
                return;

            float angle = Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg + 90f;
            float current = drone.localEulerAngles.z;
            float next = Mathf.LerpAngle(current, angle + wobble, 1f - Mathf.Exp(-response * Time.unscaledDeltaTime));
            drone.localRotation = Quaternion.Euler(0f, 0f, next);
        }

        private static void SmoothMoveDroneToward(RectTransform drone, ref Vector2 position, Vector2 target, float response, float wobble = 0f)
        {
            Vector2 previous = position;
            position = Vector2.Lerp(position, target, 1f - Mathf.Exp(-response * Time.deltaTime));
            if (drone != null)
                drone.anchoredPosition = position;

            Vector2 faceTarget = (position - previous).sqrMagnitude > 1f ? position : target;
            FaceDroneToward(drone, previous, faceTarget, wobble);
        }

        private static void FaceShieldDroneToward(RectTransform drone, Vector2 from, Vector2 target, float wobble = 0f)
        {
            if (drone == null)
                return;

            Vector2 direction = target - from;
            if (direction.sqrMagnitude < 4f)
                return;

            float angle = Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg - 90f;
            float current = drone.localEulerAngles.z;
            float next = Mathf.LerpAngle(current, angle + wobble, 1f - Mathf.Exp(-6.5f * Time.deltaTime));
            drone.localRotation = Quaternion.Euler(0f, 0f, next);
        }

        private static void SmoothMoveShieldDroneToward(RectTransform drone, ref Vector2 position, Vector2 target, float response, float wobble = 0f)
        {
            Vector2 previous = position;
            position = Vector2.Lerp(position, target, 1f - Mathf.Exp(-response * Time.deltaTime));
            if (drone != null)
                drone.anchoredPosition = position;

            Vector2 faceTarget = (position - previous).sqrMagnitude > 1f ? position : target;
            FaceShieldDroneToward(drone, previous, faceTarget, wobble);
        }

        private Vector2 RepairWorkPosition(Vector2 center, ref float phase, float radius, float speed, float vibration, out bool paused)
        {
            phase += Time.deltaTime * speed;
            float cycle = Mathf.Repeat(phase, 4.0f);
            float loop = Mathf.Floor(phase / 4.0f);
            paused = cycle > 2.45f;
            float move = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(cycle / 2.45f));
            float angle = loop * 1.45f + move * 1.35f;
            Vector2 orbit = new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * radius;
            return center + orbit + WorkVibration(paused ? vibration * 1.45f : vibration * 0.45f, paused ? 46f : 18f);
        }

        private Vector2 OrbitWorkPosition(Vector2 center, ref float phase, float radius, float speed, float vibration)
        {
            bool paused;
            return RepairWorkPosition(center, ref phase, radius, speed, vibration, out paused);
        }

        private static Vector2 RepairContactPoint(Vector2 targetCenter, Vector2 repairPos, float radius)
        {
            Vector2 direction = repairPos - targetCenter;
            if (direction.sqrMagnitude < 0.1f)
                direction = Vector2.up;

            return targetCenter + direction.normalized * radius;
        }

        private void UpdateWeldSparks(bool active, Vector2 repairPos, Vector2 targetPos)
        {
            UpdateRepairWeldingSound(active);

            if (weldSparks == null)
                return;

            Vector2 direction = targetPos - repairPos;
            if (direction.sqrMagnitude < 0.1f)
                direction = Vector2.up;
            direction.Normalize();
            Vector2 normal = new Vector2(-direction.y, direction.x);
            float weldDistance = Vector2.Distance(repairPos, targetPos);
            Vector2 weldCenter = repairPos + direction * Mathf.Min(32f, weldDistance * 0.34f);

            for (int i = 0; i < weldSparks.Length; i++)
            {
                RectTransform spark = weldSparks[i];
                if (spark == null)
                    continue;

                spark.gameObject.SetActive(active);
                if (!active)
                    continue;

                float phase = Time.time * (18f + i * 2.7f) + i * 1.9f;
                float length = 7f + Mathf.Abs(Mathf.Sin(phase)) * 16f;
                float side = Mathf.Sin(phase * 1.3f) * (5f + i * 0.8f);
                float forward = Mathf.Cos(phase * 0.9f) * 8f;
                spark.anchoredPosition = weldCenter + normal * side + direction * forward;
                spark.sizeDelta = new Vector2(4f + i % 2 * 2f, length);
                spark.localRotation = Quaternion.Euler(0f, 0f, Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg - 90f + Mathf.Sin(phase) * 35f);

                Image image = spark.GetComponent<Image>();
                if (image != null)
                    image.color = i % 2 == 0 ? new Color(1f, 0.78f, 0.18f, 0.78f) : new Color(0.25f, 0.92f, 1f, 0.62f);
            }
        }

        private bool IsGeneratorChargeTargetValid()
        {
            switch (generatorChargeTarget)
            {
                case DroneChargeTarget.Crafter:
                    return crafterSpawnedThisRun && crafterDrone != null && crafterDrone.gameObject.activeSelf && crafterTempShield <= 0;
                case DroneChargeTarget.Repair:
                    return repairDrone != null && repairDrone.gameObject.activeSelf && !repairAttached && !repairFlyingToOrb && repairTempShield <= 0;
                case DroneChargeTarget.Generator:
                    return generatorTempShield <= 0;
                default:
                    return false;
            }
        }

        private DroneChargeTarget SelectGeneratorChargeTarget()
        {
            if (repairDrone != null && repairDrone.gameObject.activeSelf && !repairAttached && !repairFlyingToOrb && repairTempShield <= 0)
                return DroneChargeTarget.Repair;

            if (crafterSpawnedThisRun && crafterDrone != null && crafterDrone.gameObject.activeSelf && crafterTempShield <= 0)
                return DroneChargeTarget.Crafter;

            if (generatorTempShield <= 0)
                return DroneChargeTarget.Generator;

            return DroneChargeTarget.None;
        }

        private bool TryAssignGeneratorCommandTarget(Vector2 commandPosition)
        {
            if (!droneCommandActive || generatorDrone == null || !generatorDrone.gameObject.activeSelf)
                return false;

            if (repairDrone != null && repairDrone.gameObject.activeSelf && !repairAttached && !repairFlyingToOrb && IsCommandOverDrone(commandPosition, repairDrone))
            {
                generatorChargeTarget = DroneChargeTarget.Repair;
                generatorDroneChargeTimer = 0f;
                return true;
            }

            if (crafterSpawnedThisRun && crafterDrone != null && crafterDrone.gameObject.activeSelf && IsCommandOverDrone(commandPosition, crafterDrone))
            {
                generatorChargeTarget = DroneChargeTarget.Crafter;
                generatorDroneChargeTimer = 0f;
                return true;
            }

            if (IsCommandOverDrone(commandPosition, generatorDrone))
            {
                generatorChargeTarget = DroneChargeTarget.Generator;
                generatorDroneChargeTimer = 0f;
                return true;
            }

            return false;
        }

        private Vector2 GetGeneratorChargeTargetPosition()
        {
            switch (generatorChargeTarget)
            {
                case DroneChargeTarget.Crafter:
                    return crafterPosition;
                case DroneChargeTarget.Repair:
                    return repairPosition;
                case DroneChargeTarget.Generator:
                    return generatorPosition;
                default:
                    return generatorPosition;
            }
        }

        private void CompleteGeneratorDroneCharge()
        {
            switch (generatorChargeTarget)
            {
                case DroneChargeTarget.Repair:
                    repairTempShield = 1;
                    repairTempShieldTimer = 0f;
                    if (statusText != null)
                        statusText.text = "REPAIR SHIELDED";
                    break;
                case DroneChargeTarget.Crafter:
                    crafterTempShield = 1;
                    crafterTempShieldTimer = 0f;
                    if (statusText != null)
                        statusText.text = "CRAFTER SHIELDED";
                    break;
                case DroneChargeTarget.Generator:
                    generatorTempShield = 1;
                    generatorTempShieldTimer = 0f;
                    if (statusText != null)
                        statusText.text = "GENERATOR SHIELDED";
                    break;
            }

            generatorChargeTarget = DroneChargeTarget.None;
            generatorDroneChargeTimer = 0f;
        }

        private void UpdateCrafterDrone()
        {
            if (!crafterOwned || crafterDrone == null)
            {
                UpdateCrafterCraftSound(false);
                return;
            }

            if (!crafterSpawnedThisRun)
            {
                if (!IsOrbAtBase())
                {
                    UpdateCrafterCraftSound(false);
                    HideCraftProgress();
                    if (crafterDrone.gameObject.activeSelf)
                        crafterDrone.gameObject.SetActive(false);
                    if (crafterCraftProgress <= 0f && statusText != null)
                        statusText.text = "RETURN TO BASE TO BUILD CRAFTER";
                    return;
                }

                crafterPosition = ResolveCraftPlaceSpawnPosition(orb != null ? orb.anchoredPosition : new Vector2(laneX, orbY));
                crafterDrone.anchoredPosition = crafterPosition + WorkVibration(0.8f, 22f);
                crafterDrone.localRotation = Quaternion.Euler(0f, 0f, Mathf.Sin(Time.time * 38f) * 6f);
                if (!crafterDrone.gameObject.activeSelf)
                    crafterDrone.gameObject.SetActive(true);

                crafterCraftProgress = Mathf.Clamp01(crafterCraftProgress + Time.deltaTime / 4.2f);
                ShowCraftProgress(crafterCraftProgress);
                if (crafterCraftProgress >= 1f)
                    SpawnCrafterDrone();
                return;
            }

            if (crafterDragging)
            {
                UpdateCrafterCraftSound(false);
                return;
            }

            if (droneUpgradePadDocking && pendingDroneUpgradeTarget == DroneUpgradeTarget.Crafter && state == GameState.Playing && !menuHangarOpen)
            {
                UpdateCrafterCraftSound(false);
                HideCraftProgress();
                return;
            }

            if (outpostBuilding)
            {
                UpdateCrafterOutpostBuild();
                return;
            }

            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
            {
                UpdateCrafterCraftSound(false);
                return;
            }

            if (tutorialShieldHangarLessonActive && CanCrafterBuild(CrafterBuildTarget.Shield, true))
            {
                CraftCrafterTarget(CrafterBuildTarget.Shield);
                ApplyCrafterCraftingVisuals(GetCrafterBuildSlotPosition(CrafterBuildTarget.Shield), 0.85f, 86f);
                return;
            }

            if (crafterArrivingToWork)
            {
                UpdateCrafterCraftSound(false);
                HideCraftProgress();
                Vector2 home = GetCrafterWorkHomePosition(root);
                SmoothMoveDroneToward(crafterDrone, ref crafterPosition, home, 2.8f, Mathf.Sin(Time.time * 12f) * 2f);
                FaceDroneToward(crafterDrone, crafterPosition, home);
                crafterDrone.anchoredPosition = crafterPosition;
                if (Vector2.Distance(crafterPosition, home) <= 12f)
                {
                    crafterPosition = home;
                    crafterWorkPosition = home;
                    crafterPatrolTarget = home;
                    crafterArrivingToWork = false;
                }
                return;
            }

            bool crafterActiveWork = false;
            if (repairWorkingOnCrafter)
            {
                UpdateCrafterCraftSound(false);
                crafterDrone.anchoredPosition = crafterPosition + WorkVibration(0.8f, 28f);
                FaceDroneToward(crafterDrone, crafterPosition, repairPosition);
                return;
            }

            if (generatorChargeTarget == DroneChargeTarget.Crafter)
            {
                UpdateCrafterCraftSound(false);
                crafterDrone.anchoredPosition = crafterPosition + WorkVibration(0.6f, 24f);
                return;
            }

            CrafterBuildTarget buildTarget = SelectCrafterBuildTarget(true);
            if (buildTarget != CrafterBuildTarget.None)
            {
                CraftCrafterTarget(buildTarget);
                crafterActiveWork = true;
            }
            else if (SelectCrafterBuildTarget(false) != CrafterBuildTarget.None)
            {
                UpdateCrafterCraftSound(false);
                HideCraftProgress();
                if (statusText != null)
                    statusText.text = "CRAFTER NEEDS OZPARTS";

                Vector2 waitPoint = GetCrafterWorkHomePosition(root);
                SmoothMoveDroneToward(crafterDrone, ref crafterPosition, waitPoint, 2.0f);
            }
            else
            {
                UpdateCrafterCraftSound(false);
                Vector2 patrol = GetHangarDronePatrolTarget(root, crafterPosition, ref crafterPatrolTarget, ref crafterPatrolTimer, 0, 70f, 46f, 2.2f, 5.0f);
                SmoothMoveDroneToward(crafterDrone, ref crafterPosition, patrol, 1.75f);
            }

            if (crafterActiveWork)
                ApplyCrafterCraftingVisuals(GetCrafterBuildSlotPosition(buildTarget), 0.75f, 78f);
            else
            {
                crafterDrone.localScale = Vector3.one * 1.20f;
                crafterDrone.localRotation = Quaternion.identity;
                crafterDrone.anchoredPosition = crafterPosition;
            }
        }

        private void UpdateCrafterOutpostBuild()
        {
            if (crafterDrone == null)
                return;

            UpdateCrafterCraftSound(true);
            Vector2 pad = ResolveDroneUpgradePadWorldPosition();
            crafterPosition = Vector2.Lerp(crafterPosition, pad, 1f - Mathf.Exp(-10.0f * Time.deltaTime));
            crafterDrone.anchoredPosition = crafterPosition + WorkVibration(0.22f, 34f);
            crafterDrone.localScale = Vector3.one * (1.16f + Mathf.Sin(Time.time * 18f) * 0.035f);
            FaceDroneToward(crafterDrone, crafterPosition, ResolveOutpostDockPosition(), Mathf.Sin(Time.time * 42f) * 4f);

            outpostBuildProgress = Mathf.Clamp01(outpostBuildProgress + Time.deltaTime / OutpostBuildSeconds);
            ShowCraftProgress(outpostBuildProgress);
            if (statusText != null)
                statusText.text = LF("status.outpost_progress", Mathf.RoundToInt(outpostBuildProgress * 100f));

            if (outpostBuildProgress < 1f)
                return;

            outpostBuilding = false;
            outpostBuilt = true;
            outpostBuildProgress = 1f;
            outpostPositionLocked = false;
            AddOutpostSharedHealthSegment();
            UpdateCrafterCraftSound(false);
            HideCraftProgress();
            if (statusText != null)
                statusText.text = L("status.outpost_complete");
        }

        private void ApplyCrafterCraftingVisuals(Vector2 workTarget, float shakeStrength, float shakeSpeed)
        {
            if (crafterDrone == null)
                return;

            float pulse = 0.5f + Mathf.Sin(Time.time * 18f) * 0.5f;
            crafterDrone.anchoredPosition = crafterPosition + WorkVibration(shakeStrength, shakeSpeed);
            crafterDrone.localScale = Vector3.one * (1.20f + pulse * 0.08f);
            FaceDroneToward(crafterDrone, crafterPosition, workTarget, Mathf.Sin(Time.time * 64f) * 4.5f);
        }

        private CrafterBuildTarget SelectCrafterBuildTarget(bool requireParts)
        {
            if (tutorialShieldHangarLessonActive && CanCrafterBuild(CrafterBuildTarget.Shield, requireParts))
                return CrafterBuildTarget.Shield;

            for (int priority = 1; priority <= 4; priority++)
            {
                for (int i = 0; i < 5; i++)
                {
                    if (stationTaskPriorities[i] != priority)
                        continue;

                    CrafterBuildTarget target = i == 0 ? CrafterBuildTarget.Repair : i == 1 ? CrafterBuildTarget.Generator : i == 2 ? CrafterBuildTarget.Shield : i == 3 ? CrafterBuildTarget.Collector : CrafterBuildTarget.MineLayer;
                    if (!CanCrafterBuild(target, requireParts))
                        continue;

                    return target;
                }
            }

            if (CanCrafterBuild(CrafterBuildTarget.Hive, requireParts))
                return CrafterBuildTarget.Hive;
            if (CanCrafterBuild(CrafterBuildTarget.Gladiator, requireParts))
                return CrafterBuildTarget.Gladiator;
            if (CanCrafterBuild(CrafterBuildTarget.Horizon, requireParts))
                return CrafterBuildTarget.Horizon;
            if (CanCrafterBuild(CrafterBuildTarget.Tamer, requireParts))
                return CrafterBuildTarget.Tamer;
            if (CanCrafterBuild(CrafterBuildTarget.Queen, requireParts))
                return CrafterBuildTarget.Queen;
            if (CanCrafterBuild(CrafterBuildTarget.Mimic, requireParts))
                return CrafterBuildTarget.Mimic;
            if (CanCrafterBuild(CrafterBuildTarget.Sniper, requireParts))
                return CrafterBuildTarget.Sniper;

            return CrafterBuildTarget.None;
        }

        private bool CanCrafterBuild(CrafterBuildTarget target, bool requireParts)
        {
            switch (target)
            {
                case CrafterBuildTarget.Repair:
                    return repairOwned && !repairSpawnedThisRun && (!requireParts || HasOzParts(RepairCraftCost));
                case CrafterBuildTarget.Generator:
                    return generatorOwned && !generatorSpawnedThisRun && (!requireParts || HasOzParts(GeneratorCraftCost));
                case CrafterBuildTarget.Shield:
                    return shieldDroneOwned && !shieldDroneSpawnedThisRun && (!requireParts || tutorialShieldHangarLessonActive || HasOzParts(ShieldDroneCraftCost));
                case CrafterBuildTarget.Collector:
                    return collectorDroneOwned && !collectorDroneSpawnedThisRun && (!requireParts || HasOzParts(CollectorDroneCraftCost));
                case CrafterBuildTarget.MineLayer:
                    return mineLayerDroneOwned && !mineLayerDroneSpawnedThisRun;
                case CrafterBuildTarget.Hive:
                    return hiveDroneOwned && !hiveDroneSpawnedThisRun && (!requireParts || HasOzParts(HiveDroneCraftCost));
                case CrafterBuildTarget.Gladiator:
                    return gladiatorDroneOwned && !gladiatorDroneSpawnedThisRun && (!requireParts || HasOzParts(GladiatorDroneCraftCost));
                case CrafterBuildTarget.Horizon:
                    return horizonDroneOwned && !horizonDroneSpawnedThisRun && (!requireParts || HasOzParts(HorizonDroneCraftCost));
                case CrafterBuildTarget.Tamer:
                    return tamerDroneOwned && !tamerDroneSpawnedThisRun && (!requireParts || HasOzParts(TamerDroneCraftCost));
                case CrafterBuildTarget.Queen:
                    return queenDroneOwned && !queenDroneSpawnedThisRun && (!requireParts || HasOzParts(QueenDroneCraftCost));
                case CrafterBuildTarget.Mimic:
                    return mimicDroneOwned && !mimicDroneSpawnedThisRun && (!requireParts || HasOzParts(MimicDroneCraftCost));
                case CrafterBuildTarget.Sniper:
                    return sniperDroneOwned && !sniperDroneSpawnedThisRun && (!requireParts || HasOzParts(SniperDroneCraftCost));
                default:
                    return false;
            }
        }

        private bool HasCrafterBuildProgress(CrafterBuildTarget target)
        {
            switch (target)
            {
                case CrafterBuildTarget.Repair:
                    return repairCraftProgress > 0f;
                case CrafterBuildTarget.Generator:
                    return generatorCraftProgress > 0f;
                case CrafterBuildTarget.Shield:
                    return shieldDroneCraftProgress > 0f;
                case CrafterBuildTarget.Collector:
                    return collectorDroneCraftProgress > 0f;
                case CrafterBuildTarget.MineLayer:
                    return mineLayerDroneCraftProgress > 0f;
                case CrafterBuildTarget.Hive:
                    return hiveDroneCraftProgress > 0f;
                case CrafterBuildTarget.Gladiator:
                    return gladiatorDroneCraftProgress > 0f;
                case CrafterBuildTarget.Horizon:
                    return horizonDroneCraftProgress > 0f;
                case CrafterBuildTarget.Tamer:
                    return tamerDroneCraftProgress > 0f;
                case CrafterBuildTarget.Queen:
                    return queenDroneCraftProgress > 0f;
                case CrafterBuildTarget.Mimic:
                    return mimicDroneCraftProgress > 0f;
                case CrafterBuildTarget.Sniper:
                    return sniperDroneCraftProgress > 0f;
                default:
                    return false;
            }
        }

        private void CancelCrafterCurrentBuild()
        {
            generatorCraftProgress = 0f;
            repairCraftProgress = 0f;
            shieldDroneCraftProgress = 0f;
            collectorDroneCraftProgress = 0f;
            mineLayerDroneCraftProgress = 0f;
            hiveDroneCraftProgress = 0f;
            gladiatorDroneCraftProgress = 0f;
            horizonDroneCraftProgress = 0f;
            tamerDroneCraftProgress = 0f;
            queenDroneCraftProgress = 0f;
            mimicDroneCraftProgress = 0f;
            sniperDroneCraftProgress = 0f;
            HideCraftProgress();
            UpdateCrafterCraftSound(false);
        }

        private void CraftCrafterTarget(CrafterBuildTarget target)
        {
            UpdateCrafterCraftSound(true);
            crafterWorkPosition = GetCrafterBuildOperatorPosition(target);
            if (!HasCrafterBuildProgress(target) && Vector2.Distance(crafterPosition, crafterWorkPosition) > 72f)
            {
                Vector2 previous = crafterPosition;
                crafterPosition = Vector2.MoveTowards(crafterPosition, crafterWorkPosition, 245f * Time.deltaTime);
                crafterDrone.anchoredPosition = crafterPosition + WorkVibration(0.35f, 22f);
                crafterDrone.localScale = Vector3.one * 1.20f;
                FaceDroneToward(crafterDrone, previous, GetCrafterBuildSlotPosition(target), Mathf.Sin(Time.time * 18f) * 2f);
                HideCraftProgress();
                return;
            }

            if (target == CrafterBuildTarget.Repair)
            {
                if (repairCraftProgress <= 0f)
                    crafterWorkPosition = GetCrafterBuildOperatorPosition(target);
                repairCraftProgress = Mathf.Clamp01(repairCraftProgress + Time.deltaTime * QueenBuffRate(crafterDrone) / 5.6f);
                ShowCraftProgress(repairCraftProgress);
                UpdateDroneCraftHologram(target, repairCraftProgress);
                crafterPosition = Vector2.Lerp(crafterPosition, crafterWorkPosition, 1f - Mathf.Exp(-8.4f * Time.deltaTime));
                FaceDroneToward(crafterDrone, crafterPosition, GetCrafterBuildSlotPosition(target), Mathf.Sin(Time.time * 52f) * 7f);
                if (repairCraftProgress >= 1f)
                {
                    SpendOzParts(RepairCraftCost);
                    PlayerPrefs.SetInt(OzPartsKey, ozParts);
                    PlayerPrefs.Save();
                    SpawnRepairDrone(GetCrafterBuildReleasePosition(target));
                    UpdateCrafterCraftSound(false);
                    RefreshHud();
                    RefreshUpgradeLabels();
                }
                return;
            }

            if (target == CrafterBuildTarget.Generator)
