        private void SpawnCrafterDrone()
        {
            if (crafterDrone == null)
                return;

            crafterSpawnedThisRun = true;
            crafterArrivingToWork = true;
            crafterHealth = 35;
            crafterTempShield = 0;
            crafterTempShieldTimer = 0f;
            crafterCraftProgress = 1f;
            HideCraftProgress();
            crafterPosition = ResolveCraftPlaceSpawnPosition(orb != null ? orb.anchoredPosition : crafterPosition);
            crafterPatrolTarget = crafterPosition;
            crafterPatrolTimer = 0f;
            crafterDrone.anchoredPosition = crafterPosition;
            crafterDrone.localScale = Vector3.one;
            crafterDrone.gameObject.SetActive(true);
            if (statusText != null)
                statusText.text = "CRAFTER BUILT";
        }

        private void UpdateGeneratorDrone()
        {
            if (generatorDrone == null || !generatorDrone.gameObject.activeSelf)
            {
                UpdateGeneratorShieldChargeSound(false);
                return;
            }

            if (generatorDragging)
            {
                generatorChargeTarget = DroneChargeTarget.None;
                generatorDroneChargeTimer = 0f;
                UpdateGeneratorShieldChargeSound(false);
                return;
            }

            if (repairWorkingOnGenerator && !generatorAttached)
            {
                generatorDrone.anchoredPosition = generatorPosition + WorkVibration(0.8f, 28f);
                FaceDroneToward(generatorDrone, generatorPosition, repairPosition);
                UpdateGeneratorShieldChargeSound(false);
                return;
            }

            DroneChargeTarget neededDroneCharge = SelectGeneratorChargeTarget();
            bool hasDroneChargeWork = neededDroneCharge != DroneChargeTarget.None;
            bool hasOrbChargeWork = IsOrbAtBase() && shield < CurrentMaxShield();

            if (generatorFlyingToOrb && !hasOrbChargeWork)
            {
                generatorFlyingToOrb = false;
                generatorChargeTarget = hasDroneChargeWork ? neededDroneCharge : DroneChargeTarget.None;
                generatorDroneChargeTimer = 0f;
            }

            if (generatorAttached && !hasOrbChargeWork)
            {
                generatorAttached = false;
                generatorFlyingToOrb = false;
                generatorPosition = generatorDrone.anchoredPosition;
                generatorChargeTarget = hasDroneChargeWork ? neededDroneCharge : DroneChargeTarget.None;
                generatorDroneChargeTimer = 0f;
            }

            if (!generatorAttached && !generatorFlyingToOrb && hasOrbChargeWork)
                generatorFlyingToOrb = true;

            if (generatorFlyingToOrb)
            {
                SmoothMoveDroneToward(generatorDrone, ref generatorPosition, orb.anchoredPosition, 7f);
                UpdateGeneratorShieldChargeSound(false);
                if (Vector2.Distance(generatorPosition, orb.anchoredPosition) <= 34f)
                {
                    generatorFlyingToOrb = false;
                    generatorAttached = true;
                    generatorDrone.SetAsLastSibling();
                }
            }
            else if (generatorAttached)
            {
                if (!IsOrbAtBase() || shield >= CurrentMaxShield())
                {
                    generatorAttached = false;
                    generatorFlyingToOrb = false;
                    generatorPosition = generatorDrone.anchoredPosition;
                    UpdateGeneratorShieldChargeSound(false);
                    return;
                }

                generatorPosition = orb.anchoredPosition + WorkVibration(1.0f, 30f);
                generatorDrone.anchoredPosition = generatorPosition;
                generatorDrone.localRotation = Quaternion.Euler(0f, 0f, Mathf.Sin(Time.time * 22f) * 3f);
                if (shield < CurrentMaxShield())
                {
                    UpdateGeneratorShieldChargeSound(true);
                    shieldChargeTimer += Time.deltaTime * QueenBuffRate(generatorDrone);
                    if (shieldChargeTimer >= 2.4f)
                    {
                        shieldChargeTimer = 0f;
                        shield = Mathf.Min(CurrentMaxShield(), shield + 1);
                        RefreshHud();
                    }
                }
                else
                {
                    shieldChargeTimer = 0f;
                    UpdateGeneratorShieldChargeSound(false);
                }
            }
            else
            {
                RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
                if (root == null)
                {
                    UpdateGeneratorShieldChargeSound(false);
                    return;
                }

                Vector2 supportTarget;
                bool chargingDrone = false;
                bool chargingDroneNow = false;
                if (hasDroneChargeWork)
                {
                    if (generatorChargeTarget != neededDroneCharge || !IsGeneratorChargeTargetValid())
                    {
                        generatorDroneChargeTimer = 0f;
                        generatorChargeTarget = neededDroneCharge;
                    }

                    if (generatorChargeTarget != DroneChargeTarget.None)
                    {
                        Vector2 chargeTarget = GetGeneratorChargeTargetPosition();
                        Vector2 dockPoint = chargeTarget;
                        supportTarget = dockPoint;
                        chargingDrone = true;

                        if (Vector2.Distance(generatorPosition, dockPoint) <= 18f)
                        {
                            chargingDroneNow = true;
                            generatorDroneChargeTimer += Time.deltaTime * QueenBuffRate(generatorDrone);
                            if (generatorDroneChargeTimer >= 2.0f)
                                CompleteGeneratorDroneCharge();
                        }
                        else
                        {
                            generatorDroneChargeTimer = 0f;
                        }
                    }
                    else
                    {
                        bool crafterAvailable = crafterSpawnedThisRun && crafterDrone != null && crafterDrone.gameObject.activeSelf;
                        supportTarget = crafterAvailable
                            ? GetCompanionDronePatrolTarget(root, generatorPosition, crafterPosition, ref generatorPatrolTarget, ref generatorPatrolTimer)
                            : GetHangarDronePatrolTarget(root, generatorPosition, ref generatorPatrolTarget, ref generatorPatrolTimer, 1, 58f, 42f, 1.8f, 4.0f);
                    }
                }
                else
                {
                    generatorChargeTarget = DroneChargeTarget.None;
                    generatorDroneChargeTimer = 0f;
                    bool crafterAvailable = crafterSpawnedThisRun && crafterDrone != null && crafterDrone.gameObject.activeSelf;
                    supportTarget = crafterAvailable
                        ? GetCompanionDronePatrolTarget(root, generatorPosition, crafterPosition, ref generatorPatrolTarget, ref generatorPatrolTimer)
                        : GetHangarDronePatrolTarget(root, generatorPosition, ref generatorPatrolTarget, ref generatorPatrolTimer, 1, 58f, 42f, 1.8f, 4.0f);
                }

                SmoothMoveDroneToward(generatorDrone, ref generatorPosition, supportTarget, chargingDrone ? 5.4f : 2.25f, Mathf.Sin(Time.time * 20f) * 3f);
                if (chargingDrone)
                {
                    generatorDrone.anchoredPosition = generatorPosition + WorkVibration(0.8f, 26f);
                    generatorDrone.localRotation = Quaternion.Euler(0f, 0f, Mathf.Sin(Time.time * 22f) * 3f);
                }
                UpdateGeneratorShieldChargeSound(chargingDrone && chargingDroneNow);
            }
        }

        private void SpawnGeneratorDrone(Vector2 position)
        {
            if (generatorDrone == null)
                return;

            generatorSpawnedThisRun = true;
            generatorAttached = false;
            generatorDragging = false;
            generatorFlyingToOrb = false;
            generatorCraftProgress = 0f;
            HideCraftProgress();
            generatorHealth = 45;
            generatorTempShield = 0;
            generatorTempShieldTimer = 0f;
            generatorPosition = position;
            generatorPatrolTarget = generatorPosition;
            generatorPatrolTimer = 0f;
            generatorDrone.anchoredPosition = generatorPosition;
            ResetDroneImageColor(generatorDrone);
            generatorDrone.gameObject.SetActive(true);
            if (statusText != null)
                statusText.text = "GENERATOR BUILT";
        }

        private void UpdateRepairDrone()
        {
            if (repairDrone == null)
            {
                UpdateRepairWeldingSound(false);
                return;
            }

            if (!repairDrone.gameObject.activeSelf)
            {
                if (IsTutorialShieldBaseRepairActive() && repairOwned && baseShipHealth < CurrentSharedMaxHealth())
                {
                    repairSpawnedThisRun = true;
                    repairAttached = false;
                    repairFlyingToOrb = false;
                    repairDragging = false;
                    repairPosition = ResolveHangarDroneHomePosition(2);
                    repairPatrolTarget = repairPosition;
                    repairDrone.anchoredPosition = repairPosition;
                    ApplySpriteFromTextureResource(repairDrone, RepairDroneSpriteResourcePath);
                    ResetDroneImageColor(repairDrone);
                    repairDrone.gameObject.SetActive(true);
                }
                else
                {
                    UpdateRepairWeldingSound(false);
                    return;
                }
            }

            repairWorkingOnOrb = false;
            repairWorkingOnCrafter = false;
            repairWorkingOnGenerator = false;
            UpdateWeldSparks(false, Vector2.zero, Vector2.zero);

            if (repairDragging)
                return;

            if (generatorChargeTarget == DroneChargeTarget.Repair)
            {
                repairDrone.anchoredPosition = repairPosition + WorkVibration(0.6f, 24f);
                return;
            }

            if (IsTutorialShieldBaseRepairActive() && baseShipHealth < CurrentSharedMaxHealth())
            {
                repairAttached = false;
                repairFlyingToOrb = false;
                repairLeftBaseAttached = false;
                RepairBaseWithRepairDrone();
                repairDrone.anchoredPosition = repairPosition;
                return;
            }

            if (repairFlyingToOrb)
            {
                if (collectorDroneAttached || collectorDroneFlyingToOrb)
                {
                    repairFlyingToOrb = false;
                    if (statusText != null)
                        statusText.text = "SUPPORT SLOT BUSY";
                    return;
                }

                SmoothMoveDroneToward(repairDrone, ref repairPosition, orb.anchoredPosition, 7f);
                if (Vector2.Distance(repairPosition, orb.anchoredPosition) <= 34f)
                {
                    repairFlyingToOrb = false;
                    repairAttached = true;
                    repairLeftBaseAttached = false;
                    repairDrone.SetAsLastSibling();
                }
                return;
            }

            if (repairAttached)
            {
                if (!IsOrbAtBase())
                {
                    repairAttached = false;
                    repairFlyingToOrb = false;
                    repairLeftBaseAttached = false;
                    repairRepairTimer = 0f;
                    repairPosition = repairDrone.anchoredPosition;
                    repairPatrolTarget = repairPosition;
                    repairPatrolTimer = 0f;
                }
                else
                {
                    if (baseShipHealth < CurrentSharedMaxHealth())
                    {
                        bool repairOutpost = ShouldRepairOutpostWithRepairDrone();
                        Vector2 orbTarget = repairOutpost ? ResolveOutpostRepairWorkPoint() : orb.anchoredPosition;
                        Vector2 repairWorkTarget = orbTarget + Vector2.up * (repairOutpost ? 38f : 58f);
                        repairWorkingOnOrb = true;
                        bool paused = Mathf.PingPong(Time.time * 1.15f, 1f) > 0.58f;
                        repairPosition = Vector2.Lerp(repairPosition, orbTarget + WorkVibration(repairOutpost ? 0.62f : 0.42f, repairOutpost ? 18f : 12f), 1f - Mathf.Exp(-5.4f * Time.deltaTime));
                        UpdateWeldSparks(paused, repairPosition, repairWorkTarget);
                        repairDrone.anchoredPosition = repairPosition;
                        FaceDroneToward(repairDrone, repairPosition, repairWorkTarget, Mathf.Sin(Time.time * 44f) * 5f);
                        TryRepairSharedHealthWithParts(ref repairRepairTimer, "REPAIR", RepairHpPerPart / 2, true);
                        return;
                    }

                    if (baseShipHealth >= CurrentSharedMaxHealth())
                    {
                        Vector2 orbTarget = orb.anchoredPosition;
                        Vector2 repairWorkTarget = orbTarget + Vector2.up * 58f;
                        repairPosition = Vector2.Lerp(repairPosition, orbTarget + WorkVibration(0.25f, 7f), 1f - Mathf.Exp(-5.4f * Time.deltaTime));
                        repairDrone.anchoredPosition = repairPosition;
                        FaceDroneToward(repairDrone, repairPosition, repairWorkTarget, Mathf.Sin(Time.time * 44f) * 5f);
                        return;
                    }

                    repairAttached = false;
                    repairFlyingToOrb = false;
                    repairLeftBaseAttached = false;
                    repairRepairTimer = 0f;
                    repairPosition = repairDrone.anchoredPosition;
                }
            }

            if (IsTutorialShieldBaseRepairActive() && baseShipHealth < CurrentSharedMaxHealth())
            {
                RepairBaseWithRepairDrone();
            }
            else if (IsOrbAtBase() && baseShipHealth < CurrentSharedMaxHealth())
            {
                repairWorkingOnOrb = true;
                bool repairOutpost = ShouldRepairOutpostWithRepairDrone();
                Vector2 orbTarget = repairOutpost ? ResolveOutpostRepairWorkPoint() : orb.anchoredPosition;
                bool paused;
                repairPosition = Vector2.Lerp(repairPosition, RepairWorkPosition(orbTarget, ref repairOrbitPhase, repairOutpost ? 72f : 66f, 1.25f, repairOutpost ? 2.4f : 1.7f, out paused), 1f - Mathf.Exp(-4.4f * Time.deltaTime));
                FaceDroneToward(repairDrone, repairPosition, orbTarget, Mathf.Sin(Time.time * 44f) * 5f);
                UpdateWeldSparks(paused, repairPosition, orbTarget);
                if (Vector2.Distance(repairPosition, orbTarget) < 92f)
                    TryRepairSharedHealthWithParts(ref repairRepairTimer, "REPAIR", RepairHpPerPart, true);
            }
            else if (crafterSpawnedThisRun && crafterDrone != null && crafterDrone.gameObject.activeSelf && crafterHealth < 35)
            {
                repairWorkingOnCrafter = true;
                Vector2 target = crafterPosition;
                Vector2 workTarget = RepairContactPoint(target, repairPosition, 30f);
                bool paused;
                repairPosition = Vector2.Lerp(repairPosition, RepairWorkPosition(target, ref repairOrbitPhase, 54f, 1.45f, 2f, out paused), 1f - Mathf.Exp(-4.4f * Time.deltaTime));
                workTarget = RepairContactPoint(target, repairPosition, 30f);
                FaceDroneToward(repairDrone, repairPosition, workTarget, Mathf.Sin(Time.time * 48f) * 6f);
                UpdateWeldSparks(paused, repairPosition, workTarget);
                if (Vector2.Distance(repairPosition, workTarget) < 78f && TryRepairWithParts(ref crafterHealth, 35, ref repairRepairTimer, "REPAIR"))
                    crafterRepairFlashTimer = 0.55f;
            }
            else if (generatorDrone != null && generatorDrone.gameObject.activeSelf && !generatorAttached && generatorHealth < 45)
            {
                repairWorkingOnGenerator = true;
                Vector2 target = generatorPosition;
                Vector2 workTarget = RepairContactPoint(target, repairPosition, 30f);
                bool paused;
                repairPosition = Vector2.Lerp(repairPosition, RepairWorkPosition(target, ref repairOrbitPhase, 54f, 1.45f, 2f, out paused), 1f - Mathf.Exp(-4.4f * Time.deltaTime));
                workTarget = RepairContactPoint(target, repairPosition, 30f);
                FaceDroneToward(repairDrone, repairPosition, workTarget, Mathf.Sin(Time.time * 48f) * 6f);
                UpdateWeldSparks(paused, repairPosition, workTarget);
                if (Vector2.Distance(repairPosition, workTarget) < 78f && TryRepairWithParts(ref generatorHealth, 45, ref repairRepairTimer, "REPAIR"))
                    generatorRepairFlashTimer = 0.55f;
            }
            else if (IsOrbAtBase() && shieldDroneSpawnedThisRun && shieldDrone != null && shieldDrone.gameObject.activeSelf && shieldDroneHealth < ShieldDroneMaxHealth)
            {
                Vector2 target = shieldDronePosition;
                Vector2 workTarget = RepairContactPoint(target, repairPosition, 34f);
                bool paused;
                repairPosition = Vector2.Lerp(repairPosition, RepairWorkPosition(target, ref repairOrbitPhase, 58f, 1.35f, 2f, out paused), 1f - Mathf.Exp(-4.4f * Time.deltaTime));
                workTarget = RepairContactPoint(target, repairPosition, 34f);
                FaceDroneToward(repairDrone, repairPosition, workTarget, Mathf.Sin(Time.time * 48f) * 6f);
                UpdateWeldSparks(paused, repairPosition, workTarget);
                if (Vector2.Distance(repairPosition, workTarget) < 82f && TryRepairWithParts(ref shieldDroneHealth, ShieldDroneMaxHealth, ref repairRepairTimer, "REPAIR"))
                    shieldDroneRepairFlashTimer = 0.55f;
            }
            else if (IsOrbAtBase() && collectorDroneSpawnedThisRun && collectorDrone != null && collectorDrone.gameObject.activeSelf && !collectorDroneAttached && collectorDroneHealth < CollectorDroneMaxHealth)
            {
                Vector2 target = collectorDronePosition;
                Vector2 workTarget = RepairContactPoint(target, repairPosition, 30f);
                bool paused;
                repairPosition = Vector2.Lerp(repairPosition, RepairWorkPosition(target, ref repairOrbitPhase, 54f, 1.35f, 2f, out paused), 1f - Mathf.Exp(-4.4f * Time.deltaTime));
                workTarget = RepairContactPoint(target, repairPosition, 30f);
                FaceDroneToward(repairDrone, repairPosition, workTarget, Mathf.Sin(Time.time * 48f) * 6f);
                UpdateWeldSparks(paused, repairPosition, workTarget);
                if (Vector2.Distance(repairPosition, workTarget) < 80f && TryRepairWithParts(ref collectorDroneHealth, CollectorDroneMaxHealth, ref repairRepairTimer, "REPAIR"))
                    collectorDroneRepairFlashTimer = 0.55f;
            }
            else if ((tamerDroneReturningToBase || tamerRechargeTimer > 0f) && tamerDroneSpawnedThisRun && tamerDrone != null && tamerDrone.gameObject.activeSelf && tamerDroneHealth < TamerDroneMaxHealth)
            {
                Vector2 target = tamerDronePosition;
                Vector2 workTarget = RepairContactPoint(target, repairPosition, 32f);
                bool paused;
                repairPosition = Vector2.Lerp(repairPosition, RepairWorkPosition(target, ref repairOrbitPhase, 56f, 1.35f, 2f, out paused), 1f - Mathf.Exp(-4.4f * Time.deltaTime));
                workTarget = RepairContactPoint(target, repairPosition, 32f);
                FaceDroneToward(repairDrone, repairPosition, workTarget, Mathf.Sin(Time.time * 48f) * 6f);
                UpdateWeldSparks(paused, repairPosition, workTarget);
                if (Vector2.Distance(repairPosition, workTarget) < 82f && TryRepairWithParts(ref tamerDroneHealth, TamerDroneMaxHealth, ref repairRepairTimer, "REPAIR"))
                    tamerDroneRepairFlashTimer = 0.55f;
            }
            else if (mimicCooldownTimer > 0f && mimicDroneSpawnedThisRun && mimicDrone != null && mimicDrone.gameObject.activeSelf && mimicDroneHealth < MimicDroneMaxHealth)
            {
                Vector2 target = mimicDronePosition;
                Vector2 workTarget = RepairContactPoint(target, repairPosition, 32f);
                bool paused;
                repairPosition = Vector2.Lerp(repairPosition, RepairWorkPosition(target, ref repairOrbitPhase, 56f, 1.35f, 2f, out paused), 1f - Mathf.Exp(-4.4f * Time.deltaTime));
                workTarget = RepairContactPoint(target, repairPosition, 32f);
                FaceDroneToward(repairDrone, repairPosition, workTarget, Mathf.Sin(Time.time * 48f) * 6f);
                UpdateWeldSparks(paused, repairPosition, workTarget);
                if (Vector2.Distance(repairPosition, workTarget) < 82f)
                    TryRepairWithParts(ref mimicDroneHealth, MimicDroneMaxHealth, ref repairRepairTimer, "REPAIR");
            }
            else
            {
                RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
                if (root == null)
                    return;

                Vector2 patrol = GetHangarDronePatrolTarget(root, repairPosition, ref repairPatrolTarget, ref repairPatrolTimer, 2, 58f, 42f, 2.0f, 4.3f);
                SmoothMoveDroneToward(repairDrone, ref repairPosition, patrol, 2.05f);
            }

            repairDrone.anchoredPosition = repairPosition;
        }

        private void RepairBaseWithRepairDrone()
        {
            bool tutorialRepair = IsTutorialShieldBaseRepairActive();
            Vector2 wallTarget = ResolveBaseRepairWorkPoint();
            Vector2 workTarget = RepairContactPoint(wallTarget, repairPosition, 34f);
            bool paused;
            repairPosition = Vector2.Lerp(repairPosition, RepairWorkPosition(wallTarget, ref repairOrbitPhase, 62f, 1.05f, 1.9f, out paused), 1f - Mathf.Exp(-4.2f * Time.deltaTime));
            workTarget = RepairContactPoint(wallTarget, repairPosition, 34f);
            FaceDroneToward(repairDrone, repairPosition, workTarget, Mathf.Sin(Time.time * 46f) * 6f);
            UpdateWeldSparks(paused, repairPosition, workTarget);
            float repairRange = tutorialRepair ? 132f : 86f;
            bool repaired = false;
            if (Vector2.Distance(repairPosition, workTarget) < repairRange)
            {
                repaired = tutorialRepair
                    ? TryTutorialRepairBase(ref repairRepairTimer)
                    : TryRepairSharedHealthWithParts(ref repairRepairTimer, "REPAIR BASE");
            }
            if (repaired)
                baseShipDamageFlashTimer = Mathf.Max(baseShipDamageFlashTimer, 0.12f);
        }

        private bool TryTutorialRepairBase(ref float repairTimer)
        {
            if (baseShipHealth >= CurrentSharedMaxHealth())
            {
                repairTimer = 0f;
                return false;
            }

            repairTimer += Time.deltaTime;
            if (repairTimer < 0.45f)
                return false;

            repairTimer = 0f;
            baseShipHealth = Mathf.Min(CurrentSharedMaxHealth(), baseShipHealth + 110);
            SyncOrbHealthFromBaseShip();
            RefreshHud();
            return true;
        }

