        private void UpdateShieldDrone()
        {
            if (shieldDroneLaser != null)
                shieldDroneLaser.gameObject.SetActive(false);

            if (!shieldDroneOwned || !shieldDroneSpawnedThisRun || shieldDrone == null || !shieldDrone.gameObject.activeSelf)
                return;

            if (shieldDroneDragging)
                return;

            if (shieldDroneReadyPulseTimer > 0f)
                shieldDroneReadyPulseTimer = Mathf.Max(0f, shieldDroneReadyPulseTimer - Time.deltaTime);

            Vector2 target;
            if (shieldDroneFlyingToOrb)
            {
                target = ResolveShieldDroneGuardPosition();
                SmoothMoveShieldDroneToward(shieldDrone, ref shieldDronePosition, target, 8.5f);
                if (Vector2.Distance(shieldDronePosition, target) <= 28f)
                {
                    shieldDroneFlyingToOrb = false;
                    shieldDroneAttached = true;
                    shieldDroneReadyPulseTimer = 1.2f;
                    shieldDrone.SetAsLastSibling();
                }
            }
            else if (shieldDroneAttached)
            {
                target = ResolveShieldDroneGuardPosition();
                SmoothMoveShieldDroneToward(shieldDrone, ref shieldDronePosition, target, 9f, Mathf.Sin(Time.time * 14f) * 2f);
                FaceShieldDroneToward(shieldDrone, shieldDronePosition, shieldDronePosition + Vector2.up, Mathf.Sin(Time.time * 10f) * 2f);
                shieldDrone.SetAsLastSibling();
            }
            else
            {
                RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
                if (root == null)
                    return;

                if (tutorialShieldAttachLessonActive)
                {
                    target = ResolveHangarDroneHomePosition(4, root);
                    SmoothMoveShieldDroneToward(shieldDrone, ref shieldDronePosition, target, 3.6f, Mathf.Sin(Time.time * 10f) * 2f);
                    FaceShieldDroneToward(shieldDrone, shieldDronePosition, orb != null ? orb.anchoredPosition : shieldDronePosition + Vector2.up, Mathf.Sin(Time.time * 10f) * 2f);
                }
                else if (IsOrbAtBase())
                {
                    target = orb.anchoredPosition + Vector2.up * 116f + WorkVibration(0.55f, 12f);
                    SmoothMoveShieldDroneToward(shieldDrone, ref shieldDronePosition, target, 2.8f, Mathf.Sin(Time.time * 10f) * 2f);
                    FaceShieldDroneToward(shieldDrone, shieldDronePosition, shieldDronePosition + Vector2.up, Mathf.Sin(Time.time * 10f) * 2f);
                }
                else
                {
                    float y = ResolveGameOrbY() + 122f;
                    if (shieldDronePatrolTimer <= 0f || Mathf.Abs(shieldDronePosition.x - shieldDronePatrolTarget.x) < 18f)
                    {
                        float halfWidth = root.rect.width * 0.5f;
                        shieldDronePatrolTarget = new Vector2(RandomRange(-halfWidth * 0.46f, halfWidth * 0.46f), y + RandomRange(-18f, 26f));
                        shieldDronePatrolTimer = RandomRange(1.2f, 2.6f);
                    }

                    shieldDronePatrolTimer -= Time.deltaTime;
                    SmoothMoveShieldDroneToward(shieldDrone, ref shieldDronePosition, shieldDronePatrolTarget, 2.0f, Mathf.Sin(Time.time * 10f) * 2f);
                }
            }

            shieldDrone.anchoredPosition = shieldDronePosition;
            shieldDrone.localScale = Vector3.one * ResolveShieldDroneVisualScale();
            UpdateDroneDamageTint(shieldDrone, shieldDroneHealth, ShieldDroneMaxHealth);
            UpdateShieldDroneLaser();
        }

        private Vector2 ResolveShieldDroneGuardPosition()
        {
            if (orb == null)
                return shieldDronePosition + Vector2.up * 118f;

            return orb.anchoredPosition + Vector2.up * 124f + WorkVibration(0.85f, 14f);
        }

        private float ResolveShieldDroneVisualScale()
        {
            float baseScale = shieldDroneAttached || shieldDroneFlyingToOrb ? 1.20f : 1.08f;
            if (shieldDroneReadyPulseTimer <= 0f)
                return baseScale;

            float normalized = Mathf.Clamp01(shieldDroneReadyPulseTimer / 1.2f);
            float pulse = Mathf.Sin((1f - normalized) * Mathf.PI * 5f) * normalized;
            return baseScale + Mathf.Max(0f, pulse) * 0.18f;
        }

        private void SpawnShieldDrone(Vector2 position)
        {
            if (shieldDrone == null)
                return;

            shieldDroneSpawnedThisRun = true;
            shieldDroneAttached = false;
