            shieldDroneFlyingToOrb = false;
            shieldDroneCraftProgress = 0f;
            shieldDroneReadyPulseTimer = 1.2f;
            shieldDroneHealth = ShieldDroneMaxHealth;
            shieldDronePosition = position;
            shieldDronePatrolTarget = position;
            shieldDronePatrolTimer = 0f;
            ApplySpriteFromTextureResource(shieldDrone, ShieldDroneSpriteResourcePath);
            shieldDrone.anchoredPosition = shieldDronePosition;
            shieldDrone.localScale = Vector3.one * ResolveShieldDroneVisualScale();
            ResetDroneImageColor(shieldDrone);
