        private void TryLaunchShieldDroneToOrb(bool commandOverOrb = false)
        {
            if (shieldDrone == null || !shieldDrone.gameObject.activeSelf)
                return;

            if (!commandOverOrb && Vector2.Distance(shieldDrone.anchoredPosition, orb.anchoredPosition) > 110f)
                return;

            shieldDronePosition = shieldDrone.anchoredPosition;
            shieldDroneFlyingToOrb = true;
            shieldDroneAttached = false;
        }

        private void UpdateCollectorDrone()
        {
            if (collectorBeam != null)
                collectorBeam.gameObject.SetActive(false);

            if (!collectorDroneOwned || !collectorDroneSpawnedThisRun || collectorDrone == null || !collectorDrone.gameObject.activeSelf)
                return;

            if (collectorDroneDragging)
                return;

            if (collectorDroneFlyingToOrb)
            {
                Vector2 target = orb.anchoredPosition;
                SmoothMoveDroneToward(collectorDrone, ref collectorDronePosition, target, 6.8f, Mathf.Sin(Time.time * 16f) * 2f);
                if (Vector2.Distance(collectorDronePosition, target) <= 26f)
                {
                    collectorDroneFlyingToOrb = false;
                    collectorDroneAttached = true;
                    collectorDrone.SetAsLastSibling();
                    RefreshHud();
                }
            }
            else if (collectorDroneAttached)
            {
                collectorDronePosition = orb.anchoredPosition + WorkVibration(0.38f, 12f);
                collectorDrone.anchoredPosition = collectorDronePosition;
                collectorDrone.localRotation = Quaternion.Euler(0f, 0f, Mathf.Sin(Time.time * 16f) * 2.5f);
                collectorDrone.SetAsLastSibling();
                UpdateDroneDamageTint(collectorDrone, collectorDroneHealth, CollectorDroneMaxHealth);
                return;
            }
            else
            {
                RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
                if (root == null)
                    return;

                if (collectorCarriedParts >= CollectorCarryCapacity)
                {
                    Vector2 baseTarget = ResolveHangarDroneHomePosition(3, root);
                    SmoothMoveDroneToward(collectorDrone, ref collectorDronePosition, baseTarget, 2.8f, Mathf.Sin(Time.time * 12f) * 2f);
                    if (Vector2.Distance(collectorDronePosition, baseTarget) <= 28f)
                    {
                        int unloaded = collectorCarriedParts;
                        SpawnCargoUnloadViews(unloaded, collectorDronePosition, ResolveHangarCargoBayPosition());
                        ozParts += collectorCarriedParts;
                        collectorCarriedParts = 0;
                        PlayerPrefs.SetInt(OzPartsKey, ozParts);
                        PlayerPrefs.Save();
                        RefreshHud();
                        RefreshUpgradeLabels();
                    }
                }
                else if (TryFindCollectorPartTarget(out int partIndex, out Vector2 partPosition))
                {
                    SmoothMoveDroneToward(collectorDrone, ref collectorDronePosition, partPosition, 3.25f, Mathf.Sin(Time.time * 16f) * 2f);
                    float distance = Vector2.Distance(collectorDronePosition, partPosition);
                    if (distance <= CurrentCollectorAttractRange())
                    {
                        PartDropView part = partDrops[partIndex];
                        UpdateCollectorBeam(part.Root.anchoredPosition);
                        part.Root.anchoredPosition = Vector2.Lerp(part.Root.anchoredPosition, collectorDronePosition, 1f - Mathf.Exp(-8f * Time.deltaTime));
                        partPosition = part.Root.anchoredPosition;
                    }

                    if (Vector2.Distance(collectorDronePosition, partPosition) <= 24f)
                        CollectPartByCollector(partIndex);
                }
                else
                {
                    Vector2 patrol = GetCollectorPatrolTarget(root);
                    SmoothMoveDroneToward(collectorDrone, ref collectorDronePosition, patrol, 1.9f, Mathf.Sin(Time.time * 12f) * 2f);
                }
            }

            collectorDrone.anchoredPosition = collectorDronePosition;
            UpdateDroneDamageTint(collectorDrone, collectorDroneHealth, CollectorDroneMaxHealth);
        }

