        private void TryLaunchCollectorToOrb(bool commandOverOrb = false)
        {
            if (collectorDrone == null || !collectorDrone.gameObject.activeSelf)
                return;

            if (repairAttached || repairFlyingToOrb)
            {
                if (statusText != null)
                    statusText.text = "SUPPORT SLOT BUSY";
                return;
            }

            if (!commandOverOrb && Vector2.Distance(collectorDrone.anchoredPosition, orb.anchoredPosition) > 90f)
                return;

            collectorDronePosition = collectorDrone.anchoredPosition;
            collectorDroneFlyingToOrb = true;
            collectorDroneAttached = false;
        }

