        private void UpdateHiveDrone()
        {
            if (!hiveDroneOwned || !hiveDroneSpawnedThisRun || hiveDrone == null || !hiveDrone.gameObject.activeSelf)
                return;
            if (battleDraggedDroneTarget == DroneUpgradeTarget.Hive)
                return;

            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return;

            if (UpdateHiveTemporaryCommand(root))
                return;

            int slot = FindNextHiveMiniTurretSlot();
            bool canCraft = slot >= 0 && HasOzParts(HiveMiniTurretPartCost);
            Vector2 home = ResolveHiveDroneHomePosition(root);
            if (hiveMountedOnOutpost && outpostBuilt && Vector2.Distance(hiveDronePosition, home) > 18f)
            {
                hiveMiniTurretCraftProgress = 0f;
                MoveDroneTowardCommand(hiveDrone, ref hiveDronePosition, home, ResolveDroneCommandMoveSpeed(DroneUpgradeTarget.Hive, false), Mathf.Sin(Time.time * 12f) * 1.5f);
                hiveDrone.anchoredPosition = hiveDronePosition;
                hiveDrone.localScale = Vector3.one * 1.02f;
                UpdateDroneDamageTint(hiveDrone, hiveDroneHealth, HiveDroneMaxHealth);
                return;
            }

            if (!canCraft)
            {
                hiveMiniTurretCraftProgress = 0f;
                Vector2 patrol = hiveMountedOnOutpost && outpostBuilt
                    ? home
                    : GetHangarDronePatrolTarget(root, hiveDronePosition, ref hiveDronePatrolTarget, ref hiveDronePatrolTimer, 7, 58f, 36f, 1.1f, 2.6f);
                SmoothMoveDroneToward(hiveDrone, ref hiveDronePosition, patrol, hiveMountedOnOutpost ? 3.8f : 1.8f, Mathf.Sin(Time.time * 10f) * 2f);
                hiveDrone.anchoredPosition = hiveDronePosition;
                hiveDrone.localScale = Vector3.one * 1.02f;
                if (slot >= 0 && statusText != null)
                    statusText.text = "HIVE NEEDS OZPARTS";
                UpdateDroneDamageTint(hiveDrone, hiveDroneHealth, HiveDroneMaxHealth);
                return;
            }

            Vector2 buildPosition = ResolveHiveMiniTurretPosition(slot, root);
            Vector2 operatorPosition = home + new Vector2(0f, -46f);
            hiveMiniTurretCraftProgress = Mathf.Clamp01(hiveMiniTurretCraftProgress + Time.deltaTime * QueenBuffRate(hiveDrone) / HiveMiniTurretCraftSeconds);
            Vector2 previous = hiveDronePosition;
            SmoothMoveDroneToward(hiveDrone, ref hiveDronePosition, operatorPosition, 2.4f, Mathf.Sin(Time.time * 14f) * 2.5f);
            hiveDrone.anchoredPosition = hiveDronePosition + WorkVibration(0.65f, 52f);
            hiveDrone.localScale = Vector3.one * (1.03f + Mathf.Sin(Time.time * 22f) * 0.025f);
            Vector2 faceTarget = Vector2.Distance(hiveDronePosition, operatorPosition) > 20f ? operatorPosition : buildPosition;
            FaceDroneToward(hiveDrone, previous, faceTarget, Mathf.Sin(Time.time * 48f) * 4f);
            UpdateCrafterCraftSound(true);

            if (hiveMiniTurretCraftProgress >= 1f)
            {
                SpendOzParts(HiveMiniTurretPartCost);
                PlayerPrefs.SetInt(OzPartsKey, ozParts);
                PlayerPrefs.Save();
                Vector2 spawnPosition = hiveDrone != null ? hiveDrone.anchoredPosition + new Vector2(0f, -30f) : hiveDronePosition;
                SpawnHiveMiniTurret(slot, spawnPosition, buildPosition);
                hiveMiniTurretCraftProgress = 0f;
                RefreshHud();
                RefreshUpgradeLabels();
            }

            UpdateDroneDamageTint(hiveDrone, hiveDroneHealth, HiveDroneMaxHealth);
        }

        private Vector2 ResolveHiveDroneHomePosition(RectTransform root)
        {
            if (hiveMountedOnOutpost && outpostBuilt && hiveOutpostSlotIndex >= 0)
                return ResolveHiveOutpostMountPosition(hiveOutpostSlotIndex);

            return ResolveHangarDroneHomePosition(7, root) + new Vector2(0f, 34f);
        }

        private void StartHiveTemporaryCommand(Vector2 target)
        {
            if (!hiveDroneSpawnedThisRun || hiveDrone == null || !hiveDrone.gameObject.activeSelf)
                return;

            hiveMountedOnOutpost = false;
            hiveOutpostSlotIndex = -1;
            hiveTemporaryCommandActive = true;
            hiveTemporaryCommandReturning = false;
            hiveTemporaryCommandHoldTimer = 1.45f;
            hiveTemporaryCommandTarget = target;
            hiveMiniTurretCraftProgress = 0f;
            if (statusText != null)
                statusText.text = "HIVE MOVING";
        }

        private bool UpdateHiveTemporaryCommand(RectTransform root)
        {
            if (!hiveTemporaryCommandActive)
                return false;

            Vector2 target = hiveTemporaryCommandReturning ? ResolveHiveDroneHomePosition(root) : hiveTemporaryCommandTarget;
            Vector2 previous = hiveDronePosition;
            MoveDroneTowardCommand(hiveDrone, ref hiveDronePosition, target, ResolveDroneCommandMoveSpeed(DroneUpgradeTarget.Hive, false), Mathf.Sin(Time.time * 12f) * 1.5f);
            hiveDrone.anchoredPosition = hiveDronePosition;
            hiveDrone.localScale = Vector3.one * 1.02f;
            FaceDroneToward(hiveDrone, previous, target, 0f);
            UpdateDroneDamageTint(hiveDrone, hiveDroneHealth, HiveDroneMaxHealth);

            if (Vector2.Distance(hiveDronePosition, target) > 12f)
                return true;

            if (!hiveTemporaryCommandReturning)
            {
                hiveTemporaryCommandHoldTimer -= Time.deltaTime;
                if (hiveTemporaryCommandHoldTimer > 0f)
                    return true;

                hiveTemporaryCommandReturning = true;
                return true;
            }

            hiveTemporaryCommandActive = false;
            hiveTemporaryCommandReturning = false;
            hiveDronePatrolTarget = target;
            hiveDronePatrolTimer = 0f;
            return true;
        }

        private int FindNextHiveMiniTurretSlot()
        {
            for (int slot = 0; slot < HiveMiniTurretCapacity; slot++)
            {
                bool occupied = false;
                for (int i = 0; i < hiveMiniTurrets.Count; i++)
                {
                    if (hiveMiniTurrets[i].Slot == slot)
                    {
                        occupied = true;
                        break;
                    }
                }

                if (!occupied)
                    return slot;
            }

            return -1;
        }

        private Vector2 ResolveHiveMiniTurretPosition(int slot, RectTransform root)
        {
            float baseY = ResolveHiveMiniTurretAnchorY();

            float x = 0f;
            if (slot > 0)
            {
                int step = (slot + 1) / 2;
                int side = slot % 2 == 1 ? -1 : 1;
                x = side * step * HiveMiniTurretSpacing;
            }

            float y = baseY + HiveMiniTurretBuildYOffset;
            float halfWidth = root != null ? root.rect.width * 0.42f : 360f;
            return new Vector2(Mathf.Clamp(x, -halfWidth, halfWidth), y);
        }

        private float ResolveHiveMiniTurretAnchorY()
        {
            if (outpostBuilt)
                return ResolveOutpostSlotPosition(2).y;

            float baseY = ResolveGameOrbY();
            if (baseShipHull != null)
                baseY = Mathf.Max(baseY, ResolveBaseShipLocalToWorldPoint(new Vector2(0f, baseShipHull.sizeDelta.y * 0.90f)).y);

            return baseY;
        }

        private void SpawnHiveMiniTurret(int slot, Vector2 spawnPosition, Vector2 targetPosition)
        {
            if (playfield == null)
                return;

            GameObject go = new GameObject("HiveMiniTurret", typeof(RectTransform), typeof(CanvasRenderer), typeof(Image));
            go.transform.SetParent(playfield, false);
            RectTransform rect = go.GetComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = new Vector2(42f, 42f);
            rect.anchoredPosition = spawnPosition;

            Image image = go.GetComponent<Image>();
            Sprite sprite = GetSpriteFromTextureResource(HiveMiniTurretSpriteResourcePath);
            if (sprite != null)
            {
                image.sprite = sprite;
                image.color = Color.white;
                image.preserveAspect = true;
            }
            else
            {
                image.color = new Color(0.25f, 0.88f, 0.94f, 0.96f);
                AddOutline(rect, new Color(0.18f, 0.92f, 1f, 0.44f), new Vector2(1f, -1f));
            }
            image.raycastTarget = false;
            rect.SetAsLastSibling();

            hiveMiniTurrets.Add(new HiveMiniTurretView
            {
                Root = rect,
                Slot = slot,
                TargetPosition = targetPosition,
                Health = HiveMiniTurretMaxHealth,
                FireTimer = RandomRange(0.2f, HiveMiniTurretFireInterval)
            });

            if (statusText != null)
                statusText.text = "HIVE TURRET READY";
        }

        private void UpdateHiveMiniTurrets()
        {
            for (int i = hiveMiniTurrets.Count - 1; i >= 0; i--)
            {
                HiveMiniTurretView turret = hiveMiniTurrets[i];
                if (turret.Root == null)
                {
                    hiveMiniTurrets.RemoveAt(i);
                    continue;
                }

                Vector2 targetPosition = ResolveHiveMiniTurretPosition(turret.Slot, canvas != null ? canvas.transform as RectTransform : null);
                turret.TargetPosition = targetPosition;
                turret.Root.anchoredPosition = Vector2.Lerp(turret.Root.anchoredPosition, targetPosition, 1f - Mathf.Exp(-4.4f * Time.deltaTime));

                Vector2? target = FindNearestEnemyTarget(turret.Root.anchoredPosition, CurrentProjectileSpeed() * HiveMiniTurretProjectileSpeedMultiplier);
                bool hasTarget = target.HasValue && Vector2.Distance(turret.Root.anchoredPosition, target.Value) <= HiveMiniTurretRange;
                if (hasTarget)
                {
                    Vector2 direction = ResolveProjectileDirection(turret.Root.anchoredPosition, target.Value);
                    turret.Root.localRotation = Quaternion.Euler(0f, 0f, Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg - 90f);
                    turret.FireTimer -= Time.deltaTime;
                    if (turret.FireTimer <= 0f)
                    {
                        turret.FireTimer = HiveMiniTurretFireInterval;
                        PlayCoreCannonShotSound();
                        SpawnProjectile(turret.Root.anchoredPosition + direction * 24f, direction, HiveMiniTurretProjectileDamage, CurrentProjectileSpeed() * HiveMiniTurretProjectileSpeedMultiplier, CurrentProjectileRadius() * 0.72f, CurrentProjectileMaxDistance(turret.Root.anchoredPosition) * 0.78f, "HiveMiniShot");
                    }
                }
                else
                {
                    turret.FireTimer = Mathf.Min(turret.FireTimer, HiveMiniTurretFireInterval);
                    turret.Root.localRotation = Quaternion.Euler(0f, 0f, Mathf.Sin(Time.time * 3.2f + turret.Slot) * 4f);
                }
            }
        }

        private bool TryHitHiveMiniTurrets(Vector2 hazardPos, float hazardRadius, int damage)
        {
            for (int i = hiveMiniTurrets.Count - 1; i >= 0; i--)
            {
                HiveMiniTurretView turret = hiveMiniTurrets[i];
                if (turret == null || turret.Root == null)
                {
                    hiveMiniTurrets.RemoveAt(i);
                    continue;
                }

                if (Vector2.Distance(hazardPos, turret.Root.anchoredPosition) > hazardRadius + HiveMiniTurretHitRadius)
                    continue;

                turret.Health -= damage;
                if (turret.Health <= 0)
                {
                    PlayDroneBreakSound();
                    Destroy(turret.Root.gameObject);
                    hiveMiniTurrets.RemoveAt(i);
                    if (statusText != null)
                        statusText.text = "HIVE TURRET DOWN";
                }
                else
                {
                    Image image = turret.Root.GetComponent<Image>();
                    if (image != null)
                        image.color = Color.Lerp(Color.white, new Color(1f, 0.34f, 0.24f, 1f), 1f - Mathf.Clamp01(turret.Health / (float)HiveMiniTurretMaxHealth));
                    if (statusText != null)
                        statusText.text = "HIVE TURRET HIT";
                }

                return true;
            }

            return false;
        }

        private void SpawnGladiatorDrone(Vector2 position)
        {
            if (gladiatorDrone == null)
                return;

            gladiatorDroneSpawnedThisRun = true;
            gladiatorDroneCraftProgress = 0f;
            gladiatorDroneHealth = GladiatorDroneMaxHealth;
            gladiatorDronePosition = position;
            gladiatorDronePatrolTarget = position;
            gladiatorDronePatrolTimer = 0f;
            gladiatorStrikeTimer = 0.15f;
            gladiatorStrikeFlashTimer = 0f;
            ApplySpriteFromTextureResource(gladiatorDrone, GladiatorDroneSpriteResourcePath);
            gladiatorDrone.anchoredPosition = gladiatorDronePosition;
            gladiatorDrone.localScale = Vector3.one;
            ResetDroneImageColor(gladiatorDrone);
            gladiatorDrone.gameObject.SetActive(true);
            if (statusText != null)
                statusText.text = "GLADIATOR READY";
        }

        private void UpdateGladiatorDrone()
        {
            if (!gladiatorDroneOwned || !gladiatorDroneSpawnedThisRun || gladiatorDrone == null || !gladiatorDrone.gameObject.activeSelf)
                return;
            if (battleDraggedDroneTarget == DroneUpgradeTarget.Gladiator)
                return;

            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return;

            gladiatorStrikeTimer = Mathf.Max(0f, gladiatorStrikeTimer - Time.deltaTime * QueenBuffRate(gladiatorDrone));
            gladiatorStrikeFlashTimer = Mathf.Max(0f, gladiatorStrikeFlashTimer - Time.deltaTime);

            Vector2 guard = ResolveGladiatorGuardPosition(root);
            int targetIndex = FindNearestGladiatorTarget(guard, GladiatorAggroRange);
            if (targetIndex >= 0)
            {
                HazardView target = hazards[targetIndex];
                Vector2 targetPosition = target.Root != null ? target.Root.anchoredPosition : guard;
                Vector2 direction = targetPosition - guard;
                if (direction.sqrMagnitude < 1f)
                    direction = Vector2.up;
                direction.Normalize();

                Vector2 strikePoint = targetPosition - direction * 54f;
                gladiatorDronePosition = Vector2.Lerp(gladiatorDronePosition, strikePoint, 1f - Mathf.Exp(-12.0f * Time.deltaTime));
                gladiatorDrone.anchoredPosition = gladiatorDronePosition + WorkVibration(gladiatorStrikeFlashTimer > 0f ? 1.0f : 0.35f, 76f);
                FaceDroneToward(gladiatorDrone, gladiatorDronePosition, targetPosition, Mathf.Sin(Time.time * 38f) * 3.5f);

                if (gladiatorStrikeTimer <= 0f)
                {
                    gladiatorStrikeTimer = GladiatorStrikeInterval;
                    gladiatorStrikeFlashTimer = 0.18f;
                    PlayArcElectricSound();
                    StrikeWithGladiatorArc(targetPosition, direction);
                }
            }
            else
            {
                Vector2 patrol = GetHangarDronePatrolTarget(root, gladiatorDronePosition, ref gladiatorDronePatrolTarget, ref gladiatorDronePatrolTimer, 8, 46f, 28f, 1.35f, 2.8f);
                Vector2 target = Vector2.Lerp(guard, patrol, 0.32f);
                SmoothMoveDroneToward(gladiatorDrone, ref gladiatorDronePosition, target, 1.95f, Mathf.Sin(Time.time * 9f) * 2f);
                gladiatorDrone.anchoredPosition = gladiatorDronePosition;
                FaceDroneToward(gladiatorDrone, gladiatorDronePosition, guard + Vector2.up * 120f);
            }

            float strikePulse = gladiatorStrikeFlashTimer > 0f ? Mathf.Sin((1f - gladiatorStrikeFlashTimer / 0.18f) * Mathf.PI) * 0.12f : 0f;
            gladiatorDrone.localScale = Vector3.one * (1.02f + strikePulse);
            UpdateDroneDamageTint(gladiatorDrone, gladiatorDroneHealth, GladiatorDroneMaxHealth);
        }

        private void SpawnHorizonDrone(Vector2 position)
        {
            if (horizonDrone == null)
                return;

            horizonDroneSpawnedThisRun = true;
            horizonDroneCraftProgress = 0f;
            horizonDroneReturningToBase = false;
            horizonFuelTimer = HorizonFuelSeconds;
            horizonDroneHealth = HorizonDroneMaxHealth;
            horizonDronePosition = position;
            horizonDronePatrolTarget = position;
            horizonDronePatrolTimer = 0f;
            ApplySpriteFromTextureResource(horizonDrone, HorizonDroneSpriteResourcePath);
            horizonDrone.anchoredPosition = horizonDronePosition;
            horizonDrone.localScale = Vector3.one;
            ResetDroneImageColor(horizonDrone);
            horizonDrone.gameObject.SetActive(true);
            HideCraftProgress();
            if (statusText != null)
                statusText.text = "HORIZON RELAY READY";
        }

        private void UpdateHorizonDrone()
        {
            if (!horizonDroneOwned || !horizonDroneSpawnedThisRun || horizonDrone == null || !horizonDrone.gameObject.activeSelf)
                return;
            if (battleDraggedDroneTarget == DroneUpgradeTarget.Horizon)
                return;

            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return;

            Vector2 baseHome = ResolveHangarDroneHomePosition(9, root);
            if (horizonDroneReturningToBase || horizonFuelTimer <= 0f)
            {
                horizonDroneReturningToBase = true;
                horizonFuelTimer = Mathf.Max(0f, horizonFuelTimer);
                SmoothMoveDroneToward(horizonDrone, ref horizonDronePosition, baseHome, 2.55f, Mathf.Sin(Time.time * 10f) * 2f);
                horizonDrone.anchoredPosition = horizonDronePosition;
                horizonDrone.localScale = Vector3.one * (0.96f + Mathf.Sin(Time.time * 7.5f) * 0.018f);

                if (Vector2.Distance(horizonDronePosition, baseHome) <= 32f)
                {
                    horizonDronePosition = baseHome;
                    horizonDrone.anchoredPosition = horizonDronePosition + WorkVibration(0.22f, 8f);
                    FaceDroneToward(horizonDrone, horizonDronePosition, baseHome + Vector2.up * 80f);

                    if (HasOzParts(HorizonFuelPartCost))
                    {
                        SpendOzParts(HorizonFuelPartCost);
                        PlayerPrefs.SetInt(OzPartsKey, ozParts);
                        PlayerPrefs.Save();
                        RefreshHud();
                        RefreshUpgradeLabels();
                        horizonFuelTimer = HorizonFuelSeconds;
                        horizonDroneReturningToBase = false;
                        if (statusText != null)
                            statusText.text = "HORIZON REFUELED";
                    }
                    else if (statusText != null)
                    {
                        statusText.text = "HORIZON NEEDS OZPARTS";
                    }
                }
                else if (statusText != null)
                {
                    statusText.text = "HORIZON RETURNING";
                }

                UpdateDroneDamageTint(horizonDrone, horizonDroneHealth, HorizonDroneMaxHealth);
                return;
            }

            horizonFuelTimer = Mathf.Max(0f, horizonFuelTimer - Time.deltaTime);
            if (horizonFuelTimer <= 0f)
            {
                horizonDroneReturningToBase = true;
                if (statusText != null)
                    statusText.text = "HORIZON FUEL EMPTY";
                UpdateDroneDamageTint(horizonDrone, horizonDroneHealth, HorizonDroneMaxHealth);
                return;
            }

            Vector2 guard = ResolveHorizonGuardPosition(root);
            Vector2 patrol = GetHangarDronePatrolTarget(root, horizonDronePosition, ref horizonDronePatrolTarget, ref horizonDronePatrolTimer, 9, 84f, 46f, 1.25f, 2.9f);
            Vector2 target = Vector2.Lerp(guard, patrol, 0.36f);
            SmoothMoveDroneToward(horizonDrone, ref horizonDronePosition, target, 1.85f, Mathf.Sin(Time.time * 8.6f) * 2.2f);
            horizonDrone.anchoredPosition = horizonDronePosition + WorkVibration(0.34f, 10f);
            horizonDrone.localScale = Vector3.one * (1.0f + Mathf.Sin(Time.time * 5.4f) * 0.025f);
            FaceDroneToward(horizonDrone, horizonDronePosition, guard + Vector2.up * 160f, Mathf.Sin(Time.time * 6.2f) * 1.6f);
            UpdateDroneDamageTint(horizonDrone, horizonDroneHealth, HorizonDroneMaxHealth);
        }

        private Vector2 ResolveHorizonGuardPosition(RectTransform root)
        {
            float baseY = ResolveGameOrbY();
            if (baseShipHull != null)
                baseY = Mathf.Max(baseY, ResolveBaseShipLocalToWorldPoint(new Vector2(0f, baseShipHull.sizeDelta.y * 0.98f)).y);

            float maxY = root != null ? root.rect.height * 0.5f - 170f : 560f;
            return new Vector2(0f, Mathf.Min(baseY + HorizonGuardYOffset, maxY));
        }

        private bool IsHorizonRelayActive()
        {
            return IsPrimaryHorizonRelayActive() || IsMimicCopyActive(MimicCopyTarget.Horizon);
        }

        private bool IsPrimaryHorizonRelayActive()
        {
            return horizonDroneOwned
                && horizonDroneSpawnedThisRun
                && horizonDroneHealth > 0
                && horizonFuelTimer > 0f
                && !horizonDroneReturningToBase
                && horizonDrone != null
                && horizonDrone.gameObject.activeSelf;
        }

        private bool IsHazardInsideHorizonZone(HazardView hazard)
        {
            if (hazard == null || hazard.Root == null)
                return false;

            return IsHazardInsideHorizonZone(hazard, out _);
        }

        private bool IsHazardInsideHorizonZone(HazardView hazard, out float effectiveness)
        {
            effectiveness = 0f;
            if (hazard == null || hazard.Root == null)
                return false;

            if (IsPrimaryHorizonRelayActive() && Vector2.Distance(horizonDronePosition, hazard.Root.anchoredPosition) <= HorizonVisionRadius + hazard.Radius)
                effectiveness = Mathf.Max(effectiveness, 1f);
            if (IsMimicCopyActive(MimicCopyTarget.Horizon) && Vector2.Distance(mimicDronePosition, hazard.Root.anchoredPosition) <= HorizonVisionRadius * 0.82f + hazard.Radius)
                effectiveness = Mathf.Max(effectiveness, MimicEffectiveness());

            return effectiveness > 0f;
        }

        private float ResolveHorizonRangeForHazard(HazardView hazard, float baseRange)
        {
            return IsHazardInsideHorizonZone(hazard, out float effectiveness) ? baseRange + HorizonWeaponRangeBonus * effectiveness : baseRange;
        }

        private float CurrentCollectorAttractRange()
        {
            float bonus = IsPrimaryHorizonRelayActive() ? HorizonCollectorAttractRangeBonus : 0f;
            if (IsMimicCopyActive(MimicCopyTarget.Horizon))
                bonus = Mathf.Max(bonus, HorizonCollectorAttractRangeBonus * MimicEffectiveness());
            return CollectorAttractRange + bonus;
        }

        private void SpawnTamerDrone(Vector2 position)
        {
            if (tamerDrone == null)
                return;

            tamerDroneSpawnedThisRun = true;
            tamerDroneReturningToBase = false;
            tamerDroneCraftProgress = 0f;
            tamerCaptureProgress = 0f;
            tamerRechargeTimer = 0f;
            tamerTargetIndex = -1;
            tamerDroneHealth = TamerDroneMaxHealth;
            tamerDronePosition = position;
            tamerDronePatrolTarget = position;
            tamerDronePatrolTimer = 0f;
            ApplySpriteFromTextureResource(tamerDrone, TamerDroneSpriteResourcePath);
            tamerDrone.anchoredPosition = tamerDronePosition;
            tamerDrone.localScale = Vector3.one;
            ResetDroneImageColor(tamerDrone);
            tamerDrone.gameObject.SetActive(true);
            if (tamerCaptureBeam != null)
                tamerCaptureBeam.gameObject.SetActive(false);
            HideCraftProgress();
            if (statusText != null)
                statusText.text = "TAMER READY";
        }

        private void UpdateTamerDrone()
        {
            if (tamerCaptureBeam != null)
                tamerCaptureBeam.gameObject.SetActive(false);

            if (!tamerDroneOwned || !tamerDroneSpawnedThisRun || tamerDrone == null || !tamerDrone.gameObject.activeSelf)
                return;
            if (battleDraggedDroneTarget == DroneUpgradeTarget.Tamer)
                return;

            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return;

            Vector2 baseHome = ResolveHangarDroneHomePosition(10, root);
            if (tamerDroneReturningToBase || tamerRechargeTimer > 0f)
            {
                tamerTargetIndex = -1;
                tamerCaptureProgress = 0f;
                SmoothMoveDroneToward(tamerDrone, ref tamerDronePosition, baseHome, 2.6f, Mathf.Sin(Time.time * 10f) * 2f);
                tamerDrone.anchoredPosition = tamerDronePosition;
                tamerDrone.localScale = Vector3.one * (0.96f + Mathf.Sin(Time.time * 8f) * 0.018f);

                if (Vector2.Distance(tamerDronePosition, baseHome) <= 32f)
                {
                    tamerDroneReturningToBase = false;
                    tamerRechargeTimer = Mathf.Max(0f, tamerRechargeTimer - Time.deltaTime);
                    if (tamerRechargeTimer <= 0f && statusText != null)
                        statusText.text = "TAMER RECHARGED";
                }
                else if (statusText != null && tamerRechargeTimer > 0f)
                {
                    statusText.text = "TAMER RETURNING";
                }

                UpdateDroneDamageTint(tamerDrone, tamerDroneHealth, TamerDroneMaxHealth);
                return;
            }

            if (tamerTargetIndex < 0 || !IsValidTamerTarget(tamerTargetIndex, root))
            {
                tamerTargetIndex = FindTamerCaptureTarget(root);
                tamerCaptureProgress = 0f;
            }

            if (tamerTargetIndex >= 0)
            {
                HazardView target = hazards[tamerTargetIndex];
                Vector2 targetPos = GetHazardCanvasPosition(target, root);
                Vector2 capturePoint = targetPos - new Vector2(0f, 74f);
                tamerDronePosition = Vector2.Lerp(tamerDronePosition, capturePoint, 1f - Mathf.Exp(-3.8f * Time.deltaTime));
                tamerDrone.anchoredPosition = tamerDronePosition + WorkVibration(0.55f, 28f);
                FaceDroneToward(tamerDrone, tamerDronePosition, targetPos, Mathf.Sin(Time.time * 36f) * 3.5f);

                float distance = Vector2.Distance(tamerDronePosition, targetPos);
                if (distance <= TamerCaptureRange)
                {
                    if (tamerCaptureProgress <= 0f && !TrySpendTamerCapturePart())
                    {
                        tamerTargetIndex = -1;
                        tamerCaptureProgress = 0f;
                        Vector2 patrol = GetHangarDronePatrolTarget(root, tamerDronePosition, ref tamerDronePatrolTarget, ref tamerDronePatrolTimer, 10, 74f, 38f, 1.4f, 3.0f);
                        SmoothMoveDroneToward(tamerDrone, ref tamerDronePosition, patrol, 1.8f);
                        UpdateDroneDamageTint(tamerDrone, tamerDroneHealth, TamerDroneMaxHealth);
                        return;
                    }

                    target.TamerParalyzeTimer = TamerParalyzeHoldSeconds;
                    tamerCaptureProgress = Mathf.Clamp01(tamerCaptureProgress + Time.deltaTime * QueenBuffRate(tamerDrone) / TamerCaptureSeconds);
                    UpdateTamerCaptureBeam(targetPos, tamerCaptureProgress);
                    tamerDrone.localScale = Vector3.one * (1.0f + Mathf.Sin(Time.time * 18f) * 0.035f);

                    if (tamerCaptureProgress >= 1f)
                    {
                        ConvertHazardToFriendlySymbiote(tamerTargetIndex, root);
                        tamerTargetIndex = -1;
                        tamerCaptureProgress = 0f;
                        tamerRechargeTimer = TamerRechargeSeconds;
                        tamerDroneReturningToBase = true;
                        PlayArcElectricSound();
                        if (statusText != null)
                            statusText.text = "SYMBIOTE TAMED";
                    }
                }
            }
            else
            {
                Vector2 guard = ResolveTamerGuardPosition(root);
                Vector2 patrol = GetHangarDronePatrolTarget(root, tamerDronePosition, ref tamerDronePatrolTarget, ref tamerDronePatrolTimer, 10, 76f, 40f, 1.4f, 3.0f);
                Vector2 target = Vector2.Lerp(guard, patrol, 0.42f);
                SmoothMoveDroneToward(tamerDrone, ref tamerDronePosition, target, 1.75f, Mathf.Sin(Time.time * 8f) * 2f);
                tamerDrone.anchoredPosition = tamerDronePosition;
                FaceDroneToward(tamerDrone, tamerDronePosition, guard + Vector2.up * 120f);
            }

            UpdateDroneDamageTint(tamerDrone, tamerDroneHealth, TamerDroneMaxHealth);
        }

        private void SpawnQueenDrone(Vector2 position)
        {
            if (queenDrone == null)
                return;

            queenDroneSpawnedThisRun = true;
            queenDroneDragging = false;
            queenDroneCraftProgress = 0f;
            queenDroneHealth = QueenDroneMaxHealth;
            queenDronePosition = position;
            queenDroneSpinTimer = RandomRange(1.4f, 2.8f);
            queenDroneSpinDirection = RandomRange(0f, 1f) > 0.5f ? 1f : -1f;
            ApplySpriteFromTextureResource(queenDrone, QueenDroneSpriteResourcePath);
            queenDrone.anchoredPosition = queenDronePosition;
            queenDrone.localScale = Vector3.one;
            ResetDroneImageColor(queenDrone);
            queenDrone.gameObject.SetActive(true);
            HideCraftProgress();
            if (statusText != null)
                statusText.text = "HELIN COMMAND ONLINE";
        }

        private void UpdateQueenDrone()
        {
            if (!queenDroneOwned || !queenDroneSpawnedThisRun || queenDrone == null || !queenDrone.gameObject.activeSelf)
            {
                HideQueenBuffVisuals();
                return;
            }

            queenDroneSpinTimer -= Time.deltaTime;
            if (queenDroneSpinTimer <= 0f)
            {
                queenDroneSpinTimer = RandomRange(1.2f, 2.6f);
                queenDroneSpinDirection *= -1f;
            }

            float hover = Mathf.Sin(Time.time * 2.2f) * 4.5f;
            queenDrone.anchoredPosition = queenDronePosition + new Vector2(0f, hover);
            queenDrone.localScale = Vector3.one * (1.02f + Mathf.Sin(Time.time * 3.8f) * 0.018f);
            queenDrone.Rotate(0f, 0f, queenDroneSpinDirection * 10f * Time.deltaTime);
            UpdateDroneDamageTint(queenDrone, queenDroneHealth, QueenDroneMaxHealth);
            UpdateQueenBuffVisuals();
        }

        private void UpdateQueenBuffVisuals()
        {
            if (queenDrone == null || !queenDrone.gameObject.activeSelf)
            {
                HideQueenBuffVisuals();
                return;
            }

            if (queenAuraRing != null)
            {
                queenAuraRing.gameObject.SetActive(queenDroneDragging);
                queenAuraRing.anchoredPosition = queenDronePosition;
                queenAuraRing.sizeDelta = Vector2.one * (QueenDroneAuraRadius * 2f + Mathf.Sin(Time.time * 5.4f) * 8f);
                Image ringImage = queenAuraRing.GetComponent<Image>();
                if (ringImage != null)
                    ringImage.color = new Color(0.20f, 0.96f, 1f, queenDroneDragging ? 0.28f : 0f);
                queenAuraRing.SetAsLastSibling();
                queenDrone.SetAsLastSibling();
            }

            int linkIndex = 0;
            TryAddQueenBuffLink(crafterDrone, crafterSpawnedThisRun, ref linkIndex);
            TryAddQueenBuffLink(generatorDrone, generatorSpawnedThisRun && !generatorAttached && !generatorFlyingToOrb, ref linkIndex);
            TryAddQueenBuffLink(repairDrone, repairSpawnedThisRun && !repairAttached && !repairFlyingToOrb, ref linkIndex);
            TryAddQueenBuffLink(shieldDrone, shieldDroneSpawnedThisRun && !shieldDroneFlyingToOrb, ref linkIndex);
            TryAddQueenBuffLink(collectorDrone, collectorDroneSpawnedThisRun && !collectorDroneAttached && !collectorDroneFlyingToOrb, ref linkIndex);
            TryAddQueenBuffLink(mineLayerDrone, mineLayerDroneSpawnedThisRun, ref linkIndex);
            TryAddQueenBuffLink(hiveDrone, hiveDroneSpawnedThisRun, ref linkIndex);
            TryAddQueenBuffLink(gladiatorDrone, gladiatorDroneSpawnedThisRun, ref linkIndex);
            TryAddQueenBuffLink(horizonDrone, horizonDroneSpawnedThisRun, ref linkIndex);
            TryAddQueenBuffLink(tamerDrone, tamerDroneSpawnedThisRun, ref linkIndex);
            TryAddQueenBuffLink(coreCannon, IsCoreCannonActive() && coreCannon != null && coreCannon.gameObject.activeSelf, ref linkIndex);
            TryAddQueenBuffLink(homingMissileModule, IsHomingMissileModuleActive() && homingMissileModule != null && homingMissileModule.gameObject.activeSelf, ref linkIndex);
            TryAddQueenBuffLink(laserModule, IsLaserModuleActive() && laserModule != null && laserModule.gameObject.activeSelf, ref linkIndex);
            TryAddQueenBuffLink(arcChainModule, IsArcChainModuleActive() && arcChainModule != null && arcChainModule.gameObject.activeSelf, ref linkIndex);
            TryAddQueenBuffLink(railSpikeModule, IsRailSpikeModuleActive() && railSpikeModule != null && railSpikeModule.gameObject.activeSelf, ref linkIndex);

            for (int i = linkIndex; i < queenBuffLinks.Count; i++)
            {
                if (queenBuffLinks[i] != null)
                    queenBuffLinks[i].gameObject.SetActive(false);
            }
        }

        private void TryAddQueenBuffLink(RectTransform target, bool active, ref int linkIndex)
        {
            if (!active || target == null || !target.gameObject.activeSelf || !IsQueenBuffing(target))
                return;
            if (linkIndex >= QueenDroneMaxLinks)
                return;

            RectTransform link = GetQueenBuffLink(linkIndex++);
            UpdateQueenBuffLink(link, queenDronePosition, GetCanvasLocalPosition(target));
        }

        private RectTransform GetQueenBuffLink(int index)
        {
            while (queenBuffLinks.Count <= index)
            {
                RectTransform link = CreatePanel(playfield, "QueenBuffLink" + queenBuffLinks.Count, new Color(0.22f, 1f, 0.92f, 0.64f));
                link.anchorMin = new Vector2(0.5f, 0.5f);
                link.anchorMax = new Vector2(0.5f, 0.5f);
                link.pivot = new Vector2(0.5f, 0f);
                link.sizeDelta = new Vector2(2f, 1f);
                SetRaycastTarget(link, false);
                queenBuffLinks.Add(link);
            }

            return queenBuffLinks[index];
        }

        private void UpdateQueenBuffLink(RectTransform link, Vector2 from, Vector2 to)
        {
            if (link == null)
                return;

            Vector2 direction = to - from;
            float length = direction.magnitude;
            if (length < 1f)
            {
                link.gameObject.SetActive(false);
                return;
            }

            float pulse = 0.5f + Mathf.Sin(Time.time * 10f + length * 0.012f) * 0.5f;
            link.gameObject.SetActive(true);
            link.anchoredPosition = from;
            link.sizeDelta = new Vector2(Mathf.Lerp(1.4f, 3.2f, pulse), length);
            link.localRotation = Quaternion.Euler(0f, 0f, Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg - 90f);
            Image image = link.GetComponent<Image>();
            if (image != null)
                image.color = Color.Lerp(new Color(0.18f, 1f, 0.92f, 0.38f), new Color(1f, 0.78f, 0.22f, 0.70f), pulse);
            link.SetAsLastSibling();
            queenDrone.SetAsLastSibling();
        }

        private void HideQueenBuffVisuals()
        {
            if (queenAuraRing != null)
                queenAuraRing.gameObject.SetActive(false);
            for (int i = 0; i < queenBuffLinks.Count; i++)
            {
                if (queenBuffLinks[i] != null)
                    queenBuffLinks[i].gameObject.SetActive(false);
            }
        }

        private bool IsQueenBuffing(RectTransform target)
        {
            return queenDroneOwned
                && queenDroneSpawnedThisRun
                && queenDroneHealth > 0
                && queenDrone != null
                && queenDrone.gameObject.activeSelf
                && target != null
                && target.gameObject.activeSelf
                && Vector2.Distance(queenDronePosition, GetCanvasLocalPosition(target)) <= QueenDroneAuraRadius;
        }

        private float QueenBuffRate(RectTransform target)
        {
            return IsQueenBuffing(target) ? QueenDroneBuffMultiplier : 1f;
        }

        private void SpawnMimicDrone(Vector2 position)
        {
            if (mimicDrone == null)
                return;

            mimicDroneSpawnedThisRun = true;
            mimicDroneDragging = false;
            mimicDroneCraftProgress = 0f;
            mimicCooldownTimer = 0f;
            mimicActionTimer = 0f;
            mimicPulseTimer = 0f;
            mimicDroneHealth = MimicDroneMaxHealth;
            mimicHomePosition = position;
            mimicDronePosition = position;
            mimicAimPosition = position;
            mimicCopyTarget = MimicCopyTarget.None;
            mimicDrone.anchoredPosition = mimicDronePosition;
            mimicDrone.sizeDelta = new Vector2(98f, 118f);
            ApplySpriteFromTextureResource(mimicDrone, MimicDroneSpriteResourcePath);
            ResetDroneImageColor(mimicDrone);
            mimicDrone.gameObject.SetActive(true);
            HideMimicAimVisuals();
            if (statusText != null)
                statusText.text = "MIMIC READY";
        }

        private void UpdateMimicDrone()
        {
            if (!mimicDroneSpawnedThisRun || mimicDrone == null || !mimicDrone.gameObject.activeSelf)
                return;

            mimicCooldownTimer = Mathf.Max(0f, mimicCooldownTimer - Time.deltaTime);
            mimicPulseTimer += Time.deltaTime;

            if (mimicCooldownTimer > 0f)
            {
                HideMimicAimVisuals();
                mimicDronePosition = Vector2.Lerp(mimicDronePosition, mimicHomePosition, 1f - Mathf.Exp(-4.8f * Time.deltaTime));
                mimicDrone.anchoredPosition = mimicDronePosition + WorkVibration(0.45f, 10f);
                mimicDrone.localScale = Vector3.one * (0.92f + Mathf.Sin(mimicPulseTimer * 5f) * 0.035f);
                UpdateDroneDamageTint(mimicDrone, mimicDroneHealth, MimicDroneMaxHealth);
                return;
            }

            if (mimicDroneDragging)
                return;

            if (mimicCopyTarget == MimicCopyTarget.None)
            {
                HideMimicAimVisuals();
                mimicDronePosition = Vector2.Lerp(mimicDronePosition, mimicHomePosition, 1f - Mathf.Exp(-3.4f * Time.deltaTime));
                mimicDrone.anchoredPosition = mimicDronePosition + WorkVibration(0.35f, 8f);
                mimicDrone.localScale = Vector3.one * (1f + Mathf.Sin(mimicPulseTimer * 4.5f) * 0.025f);
                UpdateDroneDamageTint(mimicDrone, mimicDroneHealth, MimicDroneMaxHealth);
                return;
            }

            mimicDronePosition = Vector2.Lerp(mimicDronePosition, ResolveMimicCopyPosition(), 1f - Mathf.Exp(-3.0f * Time.deltaTime));
            mimicDrone.anchoredPosition = mimicDronePosition + WorkVibration(0.32f, 9f);
            mimicDrone.localScale = Vector3.one * (1.02f + Mathf.Sin(mimicPulseTimer * 6.5f) * 0.03f);
            mimicActionTimer = Mathf.Max(0f, mimicActionTimer - Time.deltaTime * QueenBuffRate(mimicDrone));

            switch (mimicCopyTarget)
            {
                case MimicCopyTarget.Generator:
                    UpdateMimicGeneratorCopy();
                    break;
                case MimicCopyTarget.Repair:
                    UpdateMimicRepairCopy();
                    break;
                case MimicCopyTarget.Shield:
                    UpdateMimicShieldCopy();
                    break;
                case MimicCopyTarget.Collector:
                    UpdateMimicCollectorCopy();
                    break;
                case MimicCopyTarget.MineLayer:
                    UpdateMimicMineLayerCopy();
                    break;
                case MimicCopyTarget.Hive:
                    UpdateMimicHiveCopy();
                    break;
                case MimicCopyTarget.Gladiator:
                    UpdateMimicGladiatorCopy();
                    break;
                case MimicCopyTarget.Horizon:
                    HideMimicAimVisuals();
                    break;
                case MimicCopyTarget.Tamer:
                    UpdateMimicTamerCopy();
                    break;
                default:
                    HideMimicAimVisuals();
                    break;
            }

            UpdateDroneDamageTint(mimicDrone, mimicDroneHealth, MimicDroneMaxHealth);
        }

        private Vector2 ResolveMimicCopyPosition()
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return mimicHomePosition;

            switch (mimicCopyTarget)
            {
                case MimicCopyTarget.Hive:
                    return ResolveHiveDroneHomePosition(root) + new Vector2(-62f, -26f);
                case MimicCopyTarget.Gladiator:
                    return ResolveGladiatorGuardPosition(root) + new Vector2(58f, -22f);
                case MimicCopyTarget.Horizon:
                    return ResolveHorizonGuardPosition(root) + new Vector2(-78f, -34f);
                case MimicCopyTarget.Tamer:
                    return ResolveTamerGuardPosition(root) + new Vector2(76f, -34f);
                case MimicCopyTarget.MineLayer:
                    return ResolveHangarDroneHomePosition(12, root) + new Vector2(-38f, 22f);
                default:
                    return mimicHomePosition;
            }
        }

        private void TryAssignMimicCopy(Vector2 pointerPosition)
        {
            if (!mimicDroneSpawnedThisRun || mimicCooldownTimer > 0f || mimicCopyTarget != MimicCopyTarget.None)
                return;

            MimicCopyTarget target = droneCommandActive ? FindMimicCopyTargetAtPosition(droneCommandPosition) : FindMimicCopyTarget(pointerPosition);
            if (target == MimicCopyTarget.None)
            {
                if (statusText != null)
                    statusText.text = "MIMIC NEEDS DRONE TARGET";
                return;
            }

            mimicCopyTarget = target;
            mimicActionTimer = 0f;
            ApplyMimicCopiedVisual(target);
            if (statusText != null)
                statusText.text = "MIMIC COPIED " + MimicCopyTargetName(target) + " 50%";
        }

        private MimicCopyTarget FindMimicCopyTarget(Vector2 pointerPosition)
        {
            if (IsPointerOverDrone(pointerPosition, generatorDrone) && generatorSpawnedThisRun && !generatorAttached && !generatorFlyingToOrb)
                return MimicCopyTarget.Generator;
            if (IsPointerOverDrone(pointerPosition, repairDrone) && repairSpawnedThisRun && !repairAttached && !repairFlyingToOrb)
                return MimicCopyTarget.Repair;
            if (IsPointerOverDrone(pointerPosition, shieldDrone) && shieldDroneSpawnedThisRun && !shieldDroneFlyingToOrb)
                return MimicCopyTarget.Shield;
            if (IsPointerOverDrone(pointerPosition, collectorDrone) && collectorDroneSpawnedThisRun && !collectorDroneFlyingToOrb)
                return MimicCopyTarget.Collector;
            if (IsPointerOverDrone(pointerPosition, mineLayerDrone) && mineLayerDroneSpawnedThisRun)
                return MimicCopyTarget.MineLayer;
            if (IsPointerOverDrone(pointerPosition, hiveDrone) && hiveDroneSpawnedThisRun)
                return MimicCopyTarget.Hive;
            if (IsPointerOverDrone(pointerPosition, gladiatorDrone) && gladiatorDroneSpawnedThisRun)
                return MimicCopyTarget.Gladiator;
            if (IsPointerOverDrone(pointerPosition, horizonDrone) && horizonDroneSpawnedThisRun)
                return MimicCopyTarget.Horizon;
            if (IsPointerOverDrone(pointerPosition, tamerDrone) && tamerDroneSpawnedThisRun)
                return MimicCopyTarget.Tamer;

            return MimicCopyTarget.None;
        }

        private MimicCopyTarget FindMimicCopyTargetAtPosition(Vector2 commandPosition)
        {
            if (IsCommandOverDrone(commandPosition, generatorDrone) && generatorSpawnedThisRun && !generatorAttached && !generatorFlyingToOrb)
                return MimicCopyTarget.Generator;
            if (IsCommandOverDrone(commandPosition, repairDrone) && repairSpawnedThisRun && !repairAttached && !repairFlyingToOrb)
                return MimicCopyTarget.Repair;
            if (IsCommandOverDrone(commandPosition, shieldDrone) && shieldDroneSpawnedThisRun && !shieldDroneFlyingToOrb)
                return MimicCopyTarget.Shield;
            if (IsCommandOverDrone(commandPosition, collectorDrone) && collectorDroneSpawnedThisRun && !collectorDroneFlyingToOrb)
                return MimicCopyTarget.Collector;
            if (IsCommandOverDrone(commandPosition, mineLayerDrone) && mineLayerDroneSpawnedThisRun)
                return MimicCopyTarget.MineLayer;
            if (IsCommandOverDrone(commandPosition, hiveDrone) && hiveDroneSpawnedThisRun)
                return MimicCopyTarget.Hive;
            if (IsCommandOverDrone(commandPosition, gladiatorDrone) && gladiatorDroneSpawnedThisRun)
                return MimicCopyTarget.Gladiator;
            if (IsCommandOverDrone(commandPosition, horizonDrone) && horizonDroneSpawnedThisRun)
                return MimicCopyTarget.Horizon;
            if (IsCommandOverDrone(commandPosition, tamerDrone) && tamerDroneSpawnedThisRun)
                return MimicCopyTarget.Tamer;

            return MimicCopyTarget.None;
        }

        private void ApplyMimicCopiedVisual(MimicCopyTarget target)
        {
            string spritePath = GetMimicTargetSpritePath(target);
            if (!string.IsNullOrEmpty(spritePath))
                ApplySpriteFromTextureResource(mimicDrone, spritePath);

            RectTransform source = GetMimicTargetRect(target);
            if (source != null)
                mimicDrone.sizeDelta = Vector2.Lerp(new Vector2(92f, 104f), source.sizeDelta, 0.72f);

            Image image = mimicDrone.GetComponent<Image>();
            if (image != null)
                image.color = new Color(0.62f, 1f, 0.70f, 0.96f);
        }

        private string GetMimicTargetSpritePath(MimicCopyTarget target)
        {
            switch (target)
            {
                case MimicCopyTarget.Crafter: return CrafterDroneSpriteResourcePath;
                case MimicCopyTarget.Generator: return GeneratorDroneSpriteResourcePath;
                case MimicCopyTarget.Repair: return RepairDroneSpriteResourcePath;
                case MimicCopyTarget.Shield: return ShieldDroneSpriteResourcePath;
                case MimicCopyTarget.Collector: return CollectorDroneSpriteResourcePath;
                case MimicCopyTarget.MineLayer: return MineLayerDroneSpriteResourcePath;
                case MimicCopyTarget.Hive: return HiveDroneSpriteResourcePath;
                case MimicCopyTarget.Gladiator: return GladiatorDroneSpriteResourcePath;
                case MimicCopyTarget.Horizon: return HorizonDroneSpriteResourcePath;
                case MimicCopyTarget.Tamer: return TamerDroneSpriteResourcePath;
                default: return MimicDroneSpriteResourcePath;
            }
        }

        private RectTransform GetMimicTargetRect(MimicCopyTarget target)
        {
            switch (target)
            {
                case MimicCopyTarget.Crafter: return crafterDrone;
                case MimicCopyTarget.Generator: return generatorDrone;
                case MimicCopyTarget.Repair: return repairDrone;
                case MimicCopyTarget.Shield: return shieldDrone;
                case MimicCopyTarget.Collector: return collectorDrone;
                case MimicCopyTarget.MineLayer: return mineLayerDrone;
                case MimicCopyTarget.Hive: return hiveDrone;
                case MimicCopyTarget.Gladiator: return gladiatorDrone;
                case MimicCopyTarget.Horizon: return horizonDrone;
                case MimicCopyTarget.Tamer: return tamerDrone;
                default: return null;
            }
        }

        private string MimicCopyTargetName(MimicCopyTarget target)
        {
            return target.ToString().ToUpperInvariant();
        }

        private bool IsMimicCopyActive(MimicCopyTarget target)
        {
            return mimicDroneSpawnedThisRun && mimicDrone != null && mimicDrone.gameObject.activeSelf && mimicCooldownTimer <= 0f && mimicCopyTarget == target;
        }

        private float MimicEffectiveness()
        {
            return MimicBaseEfficiency;
        }

        private void UpdateMimicAimVisuals(Vector2 targetPos)
        {
            if (mimicAimRing != null)
            {
                mimicAimRing.gameObject.SetActive(true);
                mimicAimRing.anchoredPosition = targetPos;
                mimicAimRing.sizeDelta = Vector2.one * (MimicAimRadius * 2f + Mathf.Sin(Time.time * 10f) * 8f);
                mimicAimRing.localScale = Vector3.one;
            }

            UpdateMimicLink(mimicDronePosition, targetPos, 0.66f);
        }

        private void UpdateMimicLink(Vector2 from, Vector2 to, float alpha)
        {
            if (mimicAimLink == null)
                return;

            Vector2 direction = to - from;
            float length = direction.magnitude;
            if (length < 1f)
                return;

            mimicAimLink.gameObject.SetActive(true);
            mimicAimLink.anchoredPosition = from;
            mimicAimLink.sizeDelta = new Vector2(3.2f + Mathf.Sin(Time.time * 24f) * 1.0f, length);
            mimicAimLink.localRotation = Quaternion.Euler(0f, 0f, Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg - 90f);
            Image image = mimicAimLink.GetComponent<Image>();
            if (image != null)
                image.color = new Color(0.26f, 1f, 0.42f, alpha);
        }

        private void HideMimicAimVisuals()
        {
            if (mimicAimRing != null)
                mimicAimRing.gameObject.SetActive(false);
            if (mimicAimLink != null)
                mimicAimLink.gameObject.SetActive(false);
        }

        private void ResetMimicAfterDeath()
        {
            mimicDroneDragging = false;
            mimicCooldownTimer = MimicDeathCooldownSeconds;
            mimicActionTimer = 0f;
            mimicDroneHealth = MimicDroneMaxHealth;
            mimicCopyTarget = MimicCopyTarget.None;
            mimicDronePosition = mimicHomePosition;
            mimicDrone.anchoredPosition = mimicDronePosition;
            mimicDrone.sizeDelta = new Vector2(98f, 118f);
            ApplySpriteFromTextureResource(mimicDrone, MimicDroneSpriteResourcePath);
            ResetDroneImageColor(mimicDrone);
            mimicDrone.gameObject.SetActive(true);
            HideMimicAimVisuals();
        }

        private void UpdateMimicHiveCopy()
        {
            Vector2? target = FindNearestEnemyTarget(mimicDronePosition, CurrentProjectileSpeed() * HiveMiniTurretProjectileSpeedMultiplier);
            if (!target.HasValue)
            {
                HideMimicAimVisuals();
                return;
            }

            UpdateMimicLink(mimicDronePosition, target.Value, 0.42f);
            if (mimicActionTimer > 0f)
                return;

            Vector2 direction = (target.Value - mimicDronePosition).normalized;
            SpawnProjectile(mimicDronePosition + direction * 24f, direction, HiveMiniTurretProjectileDamage * MimicEffectiveness(), CurrentProjectileSpeed() * HiveMiniTurretProjectileSpeedMultiplier, CurrentProjectileRadius() * 0.70f, CurrentProjectileMaxDistance(mimicDronePosition) * 0.72f, "MimicHiveShot");
            mimicActionTimer = HiveMiniTurretFireInterval / Mathf.Max(0.1f, MimicEffectiveness());
        }

        private void UpdateMimicGladiatorCopy()
        {
            if (mimicActionTimer > 0f)
                return;

            int targetIndex = FindNearestGladiatorTarget(mimicDronePosition, GladiatorAggroRange * 0.88f);
            if (targetIndex < 0)
            {
                HideMimicAimVisuals();
                return;
            }

            HazardView hazard = hazards[targetIndex];
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (hazard.Root == null || root == null)
                return;

            Vector2 targetPos = GetHazardCanvasPosition(hazard, root);
            UpdateMimicLink(mimicDronePosition, targetPos, 0.48f);
            Vector2 forward = (targetPos - mimicDronePosition).sqrMagnitude > 1f ? (targetPos - mimicDronePosition).normalized : Vector2.up;
            hazard.Health -= GladiatorStrikeDamage * MimicEffectiveness();
            hazard.Root.anchoredPosition += forward * (GladiatorKnockbackDistance * MimicEffectiveness());
            TriggerHazardHitFeedback(hazard);
            if (hazard.Health <= 0f)
            {
                ResolveHazardDestroyedByWeapon(hazard, targetPos);
                score += 14;
                if (hazard.Root != null)
                    Destroy(hazard.Root.gameObject);
                hazards.RemoveAt(targetIndex);
                RefreshHud();
            }
            mimicActionTimer = GladiatorStrikeInterval / Mathf.Max(0.1f, MimicEffectiveness());
        }

        private void UpdateMimicShieldCopy()
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return;

            int targetIndex = -1;
            Vector2 targetPos = Vector2.zero;
            float bestDistance = float.MaxValue;
            for (int i = 0; i < hazards.Count; i++)
            {
                HazardView hazard = hazards[i];
                if (hazard.Root == null || hazard.Symbiote || hazard.ElectricDeathPending)
                    continue;

                Vector2 hazardPos = GetHazardCanvasPosition(hazard, root);
                float distance = Vector2.Distance(mimicDronePosition, hazardPos);
                if (distance > ShieldDroneLaserRange * 0.82f || distance >= bestDistance)
                    continue;

                bestDistance = distance;
                targetIndex = i;
                targetPos = hazardPos;
            }

            if (targetIndex < 0)
            {
                HideMimicAimVisuals();
                return;
            }

            UpdateMimicLink(mimicDronePosition, targetPos, 0.58f);
            HazardView target = hazards[targetIndex];
            target.Health -= ShieldDroneLaserDps * MimicEffectiveness() * Time.deltaTime;
            if (target.Health > 0f)
                return;

            ResolveHazardDestroyedByWeapon(target, targetPos);
            score += 10;
            if (target.Root != null)
                Destroy(target.Root.gameObject);
            hazards.RemoveAt(targetIndex);
            RefreshHud();
        }

        private void UpdateMimicTamerCopy()
        {
            if (mimicActionTimer > 0f)
                return;

            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            int targetIndex = FindTamerCaptureTarget(root);
            if (targetIndex < 0)
            {
                HideMimicAimVisuals();
                return;
            }

            HazardView target = hazards[targetIndex];
            Vector2 targetPos = GetHazardCanvasPosition(target, root);
            if (Vector2.Distance(mimicDronePosition, targetPos) > TamerCaptureRange * 0.82f)
                return;

            UpdateMimicLink(mimicDronePosition, targetPos, 0.54f);
            target.TamerParalyzeTimer = Mathf.Max(target.TamerParalyzeTimer, TamerParalyzeHoldSeconds + 0.35f);
            target.Health -= CoreProjectileDamage * 0.42f * MimicEffectiveness();
            TriggerHazardHitFeedback(target);
            if (target.Health <= 0f)
            {
                ResolveHazardDestroyedByWeapon(target, targetPos);
                score += 12;
                if (target.Root != null)
                    Destroy(target.Root.gameObject);
                hazards.RemoveAt(targetIndex);
                RefreshHud();
            }
            mimicActionTimer = TamerCaptureSeconds / Mathf.Max(0.1f, MimicEffectiveness());
        }

        private void UpdateMimicGeneratorCopy()
        {
            HideMimicAimVisuals();
            if (shield >= CurrentMaxShield())
                return;

            mimicActionTimer += Time.deltaTime * QueenBuffRate(mimicDrone);
            if (mimicActionTimer < 2.4f / Mathf.Max(0.1f, MimicEffectiveness()))
                return;

            mimicActionTimer = 0f;
            shield = Mathf.Min(CurrentMaxShield(), shield + 1);
            RefreshHud();
        }

        private void UpdateMimicRepairCopy()
        {
            HideMimicAimVisuals();
            if (baseShipHealth < CurrentSharedMaxHealth())
                TryMimicRepairSharedHealthWithParts("MIMIC REPAIR");
        }

        private bool TryMimicRepairWithParts(ref int targetHealth, int maxHealth, string repairSource)
        {
            if (targetHealth >= maxHealth)
                return false;
            if (!HasOzParts(1))
            {
                if (statusText != null)
                    statusText.text = repairSource + " NEEDS OZPARTS";
                return false;
            }

            mimicActionTimer += Time.deltaTime * QueenBuffRate(mimicDrone);
            if (mimicActionTimer < RepairPartInterval / Mathf.Max(0.1f, MimicEffectiveness()))
                return false;

            mimicActionTimer = 0f;
            SpendOzParts(1);
            targetHealth = Mathf.Min(maxHealth, targetHealth + Mathf.Max(1, Mathf.RoundToInt(RepairHpPerPart * MimicEffectiveness())));
            PlayerPrefs.SetInt(OzPartsKey, ozParts);
            PlayerPrefs.Save();
            RefreshHud();
            RefreshUpgradeLabels();
            return true;
        }

        private void UpdateMimicCollectorCopy()
        {
            HideMimicAimVisuals();
            if (mimicActionTimer > 0f)
                return;

            int bestIndex = -1;
            float bestDistance = float.MaxValue;
            for (int i = 0; i < partDrops.Count; i++)
            {
                PartDropView part = partDrops[i];
                if (part.Root == null)
                    continue;

                float distance = Vector2.Distance(mimicDronePosition, part.Root.anchoredPosition);
                if (distance > CollectorAttractRange * 0.82f || distance >= bestDistance)
                    continue;

                bestDistance = distance;
                bestIndex = i;
            }

            if (bestIndex < 0)
                return;

            PartDropView target = partDrops[bestIndex];
            ozParts += Mathf.Max(1, Mathf.RoundToInt(target.Value * MimicEffectiveness()));
            PlayPartPickupSound();
            if (target.Root != null)
                Destroy(target.Root.gameObject);
            partDrops.RemoveAt(bestIndex);
            mimicActionTimer = MimicCopySupportInterval / Mathf.Max(0.1f, MimicEffectiveness());
            RefreshHud();
            RefreshUpgradeLabels();
        }

        private void UpdateMimicMineLayerCopy()
        {
            HideMimicAimVisuals();
            if (mimicActionTimer > 0f)
                return;

            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            int slot = FindNextMineLayerMissingSlot();
            if (slot < 0 || root == null || !HasOzParts(MineLayerMinePartCost))
                return;

            TryPlaceMineLayerMine(slot, ResolveMineLayerMinePosition(slot, root));
            mimicActionTimer = (MineLayerInstallSeconds + 1.2f) / Mathf.Max(0.1f, MimicEffectiveness());
        }

        private void SpawnSniperDrone(Vector2 position)
        {
            if (sniperDrone == null)
                return;

            sniperDroneSpawnedThisRun = true;
            sniperDroneDragging = false;
            sniperDroneCraftProgress = 0f;
            sniperDroneHealth = SniperDroneMaxHealth;
            sniperShotTimer = 0f;
            sniperHomePosition = position;
            sniperDronePosition = position;
            sniperAimPosition = position + Vector2.up * 260f;
            sniperRecoilOffset = Vector2.zero;
            sniperAimingMode = false;
            sniperMountedOnOutpost = false;
            sniperOutpostSlotIndex = -1;
            sniperPendingOutpostDetach = false;
            sniperPendingOutpostDetachPosition = Vector2.zero;
            sniperAimCameraCaptured = false;
            sniperAimCameraReturning = false;
            sniperAimReturnCameraOffset = hangarRevealOffset;
            sniperLockedTarget = null;
            sniperDrone.anchoredPosition = sniperDronePosition;
            sniperDrone.sizeDelta = new Vector2(82f, 148f);
            ApplySpriteFromTextureResource(sniperDrone, SniperDroneSpriteResourcePath);
            ResetDroneImageColor(sniperDrone);
            sniperDrone.gameObject.SetActive(true);
            HideSniperAimVisuals();
            if (statusText != null)
                statusText.text = "SNIPER READY";
        }

        private void UpdateSniperDrone()
        {
            if (!sniperDroneSpawnedThisRun || sniperDrone == null || !sniperDrone.gameObject.activeSelf)
                return;

            sniperShotTimer = Mathf.Max(0f, sniperShotTimer - Time.deltaTime * QueenBuffRate(sniperDrone));
            UpdateSniperRecoil();
            UpdateSniperAimCameraReturn();
            if (!sniperDroneDragging)
            {
                if (sniperMountedOnOutpost && outpostBuilt && sniperOutpostSlotIndex >= 0)
                    sniperHomePosition = ResolveSniperOutpostMountPosition(sniperOutpostSlotIndex);
                sniperDronePosition = Vector2.Lerp(sniperDronePosition, sniperHomePosition, 1f - Mathf.Exp(-3.5f * Time.deltaTime));
                sniperDrone.anchoredPosition = ResolveSniperVisualPosition() + WorkVibration(0.28f, 8f);
                sniperDrone.localScale = Vector3.one * (1f + Mathf.Sin(Time.time * 4.8f) * 0.02f);
                UpdateSniperCombat();
            }

            UpdateDroneDamageTint(sniperDrone, sniperDroneHealth, SniperDroneMaxHealth);
        }

        private void UpdateSniperRecoil()
        {
            sniperRecoilOffset = Vector2.Lerp(sniperRecoilOffset, Vector2.zero, 1f - Mathf.Exp(-SniperRecoilReturnSpeed * Time.deltaTime));
            if (sniperRecoilOffset.sqrMagnitude < 0.04f)
                sniperRecoilOffset = Vector2.zero;
        }

        private Vector2 ResolveSniperVisualPosition()
        {
            return sniperDronePosition + sniperRecoilOffset;
        }

        private void CaptureSniperAimCameraOffset()
        {
            sniperAimCameraReturning = false;
            if (sniperAimCameraCaptured)
                return;

            sniperAimCameraCaptured = true;
            sniperAimReturnCameraOffset = hangarRevealOffset;
        }

        private void BeginSniperAimCameraReturn()
        {
            if (!sniperAimCameraCaptured)
                return;

            sniperAimCameraCaptured = false;
            sniperAimCameraReturning = true;
            manualCameraControlTimer = 0.45f;
        }

        private void UpdateSniperAimCameraReturn()
        {
            if (!sniperAimCameraReturning || sniperDroneDragging)
                return;

            manualCameraControlTimer = Mathf.Max(manualCameraControlTimer, 0.20f);
            float nextCamera = Mathf.Lerp(hangarRevealOffset, sniperAimReturnCameraOffset, 1f - Mathf.Exp(-SniperAimCameraReturnSpeed * Time.deltaTime));
            SetHangarRevealOffset(nextCamera);
            if (Mathf.Abs(hangarRevealOffset - sniperAimReturnCameraOffset) <= 2f)
            {
                SetHangarRevealOffset(sniperAimReturnCameraOffset);
                sniperAimCameraReturning = false;
            }
        }

        private void UpdateSniperCombat()
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
            {
                HideSniperAimVisuals();
                return;
            }

            Vector2 targetPosition;
            if (IsValidSniperTarget(sniperLockedTarget))
            {
                targetPosition = GetHazardCanvasPosition(sniperLockedTarget, root);
                sniperAimPosition = targetPosition;
                sniperAimingMode = false;
                HideSniperAimVisuals();
                FaceSniperDroneToward(sniperDrone, sniperDronePosition, targetPosition, Mathf.Sin(Time.time * 8f) * 1.2f);
                TryFireSniperShotAt(targetPosition, "SNIPER LOCK");
                return;
            }

            sniperLockedTarget = null;
            sniperAimingMode = false;
            if (!TryFindNearestVisibleSniperTarget(root, out targetPosition))
            {
                HideSniperAimVisuals();
                return;
            }

            FaceSniperDroneToward(sniperDrone, sniperDronePosition, targetPosition, Mathf.Sin(Time.time * 8f) * 1.2f);
            TryFireSniperShotAt(targetPosition, "SNIPER AUTO");
        }

        private bool TryFindNearestVisibleSniperTarget(RectTransform root, out Vector2 targetPosition)
        {
            targetPosition = Vector2.zero;
            HazardView bestTarget = null;
            float bestDistance = float.MaxValue;

            for (int i = 0; i < hazards.Count; i++)
            {
                HazardView hazard = hazards[i];
                if (!IsValidSniperTarget(hazard))
                    continue;

                Vector2 hazardPosition = GetHazardCanvasPosition(hazard, root);
                if (!IsPointVisibleInCurrentCamera(hazardPosition, root))
                    continue;

                float distance = Vector2.Distance(sniperDronePosition, hazardPosition);
                if (distance >= bestDistance)
                    continue;

                bestDistance = distance;
                bestTarget = hazard;
                targetPosition = hazardPosition;
            }

            return bestTarget != null;
        }

        private bool IsPointVisibleInCurrentCamera(Vector2 point, RectTransform root)
        {
            if (root == null)
                return false;

            float screenY = point.y + hangarRevealOffset;
            float screenX = point.x;
            float margin = 64f;
            return screenX >= -root.rect.width * 0.5f - margin
                && screenX <= root.rect.width * 0.5f + margin
                && screenY >= -root.rect.height * 0.5f - margin
                && screenY <= root.rect.height * 0.5f + margin;
        }

        private void UpdateSniperAimCamera(Vector2 screenPosition)
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return;

            if (sniperAimingMode)
            {
                float desiredScreenY = root.rect.height * 0.22f;
                float desiredCamera = Mathf.Clamp(desiredScreenY - sniperAimPosition.y, MinForwardCameraOffset(), MaxCameraRevealOffset());
                float nextCamera = Mathf.Lerp(hangarRevealOffset, desiredCamera, 1f - Mathf.Exp(-8.0f * Time.deltaTime));
                manualCameraControlTimer = 0.35f;
                SetHangarRevealOffset(nextCamera);
                return;
            }

            float topEdge = Screen.height * SniperAimCameraEdgeFraction;
            float bottomEdge = Screen.height * (1f - SniperAimCameraEdgeFraction);
            float delta = 0f;
            if (screenPosition.y >= topEdge)
                delta = -SniperAimCameraSpeed * Time.deltaTime;
            else if (screenPosition.y <= bottomEdge)
                delta = SniperAimCameraSpeed * Time.deltaTime;

            if (Mathf.Abs(delta) < 0.01f)
                return;

            manualCameraControlTimer = 0.35f;
            SetHangarRevealOffset(Mathf.Clamp(hangarRevealOffset + delta, MinForwardCameraOffset(), MaxCameraRevealOffset()));
        }

        private void UpdateSniperAimVisuals(Vector2 targetPos)
        {
            if (sniperAimRing != null)
            {
                sniperAimRing.gameObject.SetActive(true);
                sniperAimRing.anchoredPosition = targetPos;
                sniperAimRing.sizeDelta = Vector2.one * (SniperAimRadius * 2f + Mathf.Sin(Time.time * 14f) * 7f);
            }

            UpdateSniperAimLine(sniperDronePosition, targetPos);
            FaceSniperDroneToward(sniperDrone, sniperDronePosition, targetPos, Mathf.Sin(Time.time * 18f) * 1.6f);
        }

        private void UpdateSniperAimLine(Vector2 from, Vector2 to)
        {
            if (sniperAimLine == null)
                return;

            Vector2 direction = to - from;
            float length = direction.magnitude;
            if (length < 1f)
                return;

            sniperAimLine.gameObject.SetActive(true);
            sniperAimLine.anchoredPosition = from;
            sniperAimLine.sizeDelta = new Vector2(2.8f + Mathf.Sin(Time.time * 28f) * 0.8f, length);
            sniperAimLine.localRotation = Quaternion.Euler(0f, 0f, Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg - 90f);
            Image image = sniperAimLine.GetComponent<Image>();
            if (image != null)
                image.color = new Color(1f, 0.08f, 0.04f, 0.58f);
        }

        private void HideSniperAimVisuals()
        {
            if (sniperAimRing != null)
                sniperAimRing.gameObject.SetActive(false);
            if (sniperAimLine != null)
                sniperAimLine.gameObject.SetActive(false);
        }

        private void TryFireSniperShot()
        {
            if (!sniperDroneSpawnedThisRun || sniperDrone == null || !sniperDrone.gameObject.activeSelf)
                return;

            if (!sniperAimingMode)
                return;

            TryFireSniperShotAt(sniperAimPosition, sniperLockedTarget != null ? "SNIPER LOCK" : "SNIPER SHOT");
        }

        private bool TryFireSniperShotAt(Vector2 targetPosition, string status)
        {
            if (!sniperDroneSpawnedThisRun || sniperDrone == null || !sniperDrone.gameObject.activeSelf)
                return false;
            if (sniperShotTimer > 0f)
                return false;

            sniperAimPosition = targetPosition;
            Vector2 direction = sniperAimPosition - sniperDronePosition;
            if (direction.sqrMagnitude < 64f * 64f)
            {
                if (statusText != null)
                    statusText.text = "SNIPER AIM TOO CLOSE";
                return false;
            }

            if (!HasOzParts(SniperShotPartCost))
            {
                if (statusText != null)
                    statusText.text = "SNIPER NEEDS OZPARTS";
                return false;
            }

            SpendOzParts(SniperShotPartCost);
            PlayerPrefs.SetInt(OzPartsKey, ozParts);
            PlayerPrefs.Save();
            PlayCoreCannonShotSound();
            FaceSniperDroneToward(sniperDrone, sniperDronePosition, sniperAimPosition, 0f);
            ApplySniperRecoil(direction.normalized);
            SpawnSniperProjectile(sniperDronePosition + direction.normalized * 58f, direction.normalized);
            sniperShotTimer = SniperShotInterval;
            if (statusText != null)
                statusText.text = status + "  -" + SniperShotPartCost + " PART";
            RefreshHud();
            RefreshUpgradeLabels();
            return true;
        }

        private void ApplySniperRecoil(Vector2 fireDirection)
        {
            if (fireDirection.sqrMagnitude < 0.01f)
                return;

            sniperRecoilOffset -= fireDirection.normalized * SniperRecoilDistance;
            sniperRecoilOffset = Vector2.ClampMagnitude(sniperRecoilOffset, SniperRecoilDistance * 1.35f);
            if (sniperDrone != null)
                sniperDrone.anchoredPosition = ResolveSniperVisualPosition();
        }

        private void SpawnSniperProjectile(Vector2 position, Vector2 direction)
        {
            GameObject go = new GameObject("SniperShot", typeof(RectTransform), typeof(CanvasRenderer), typeof(Image));
            go.transform.SetParent(playfield, false);

            RectTransform rect = go.GetComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = new Vector2(28f, 104f);
            rect.anchoredPosition = position;
            rect.localRotation = Quaternion.Euler(0f, 0f, Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg - 90f);

            Image image = go.GetComponent<Image>();
            Sprite projectileSprite = GetSpriteFromTextureResource(SniperProjectileSpriteResourcePath);
            if (projectileSprite != null)
            {
                image.sprite = projectileSprite;
                image.color = Color.white;
                image.preserveAspect = true;
            }
            else
            {
                image.color = new Color(1f, 0.86f, 0.24f, 0.98f);
                AddOutline(rect, new Color(0.28f, 1f, 1f, 0.44f), new Vector2(2f, -2f));
            }
            image.raycastTarget = false;

            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            float maxDistance = root != null ? root.rect.height * 2.35f : 2200f;
            projectiles.Add(new ProjectileView
            {
                Root = rect,
                Direction = direction.sqrMagnitude > 0.01f ? direction.normalized : Vector2.up,
                Speed = SniperProjectileSpeed,
                Radius = SniperProjectileRadius,
                MaxDistance = maxDistance,
                Damage = SniperShotDamage
            });
        }

        private Vector2 ResolveTamerGuardPosition(RectTransform root)
        {
            float baseY = ResolveGameOrbY();
            if (baseShipHull != null)
                baseY = Mathf.Max(baseY, ResolveBaseShipLocalToWorldPoint(new Vector2(0f, baseShipHull.sizeDelta.y * 0.96f)).y);

            float maxY = root != null ? root.rect.height * 0.5f - 210f : 520f;
            return new Vector2(0f, Mathf.Min(baseY + TamerGuardYOffset, maxY));
        }

        private int FindTamerCaptureTarget(RectTransform root)
        {
            int bestIndex = -1;
            float bestDistance = float.MaxValue;
            Vector2 guard = ResolveTamerGuardPosition(root);
            for (int i = hazards.Count - 1; i >= 0; i--)
            {
                if (!IsValidTamerTarget(i, root))
                    continue;

                HazardView hazard = hazards[i];
                Vector2 targetPos = GetHazardCanvasPosition(hazard, root);
                float distance = Vector2.Distance(guard, targetPos);
                if (distance > TamerCaptureRange || distance >= bestDistance)
                    continue;

                bestDistance = distance;
                bestIndex = i;
            }

            return bestIndex;
        }

        private bool IsValidTamerTarget(int index, RectTransform root)
        {
            if (root == null || index < 0 || index >= hazards.Count)
                return false;

            HazardView hazard = hazards[index];
            if (hazard.Root == null || hazard.Symbiote || hazard.ElectricDeathPending || hazard.BossPhaseMinion)
                return false;
            if (hazard.HeavyMineTier > 0 || hazard.SeekerMine || hazard.TutorialBaseDefenseEnemy)
                return false;
            if (hazard.Health > TamerTargetMaxHealth)
                return false;

            Vector2 targetPos = GetHazardCanvasPosition(hazard, root);
            return targetPos.y > ResolveGameOrbY() + 80f;
        }

        private bool TrySpendTamerCapturePart()
        {
            if (!HasOzParts(TamerCapturePartCost))
            {
                if (statusText != null)
                    statusText.text = "TAMER NEEDS OZPARTS";
                return false;
            }

            SpendOzParts(TamerCapturePartCost);
            PlayerPrefs.SetInt(OzPartsKey, ozParts);
            PlayerPrefs.Save();
            RefreshHud();
            RefreshUpgradeLabels();
            if (statusText != null)
                statusText.text = "TAMER CAPTURE";
            return true;
        }

        private void UpdateTamerCaptureBeam(Vector2 targetPos, float progress)
        {
            if (tamerCaptureBeam == null)
                return;

            Vector2 direction = targetPos - tamerDronePosition;
            float length = direction.magnitude;
            if (length < 1f)
                return;

            tamerCaptureBeam.gameObject.SetActive(true);
            tamerCaptureBeam.anchoredPosition = tamerDronePosition;
            tamerCaptureBeam.sizeDelta = new Vector2(Mathf.Lerp(4f, 9f, progress) + Mathf.Sin(Time.time * 34f) * 1.2f, length);
            tamerCaptureBeam.localRotation = Quaternion.Euler(0f, 0f, Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg - 90f);
            Image image = tamerCaptureBeam.GetComponent<Image>();
            if (image != null)
                image.color = new Color(0.22f, 1f, 0.86f, Mathf.Lerp(0.34f, 0.78f, progress));
            tamerCaptureBeam.SetAsLastSibling();
            if (tamerDrone != null)
                tamerDrone.SetAsLastSibling();
        }

        private void ConvertHazardToFriendlySymbiote(int index, RectTransform root)
        {
            if (index < 0 || index >= hazards.Count)
                return;

            HazardView hazard = hazards[index];
            if (hazard.Root == null)
                return;

            hazard.Symbiote = true;
            hazard.Homing = false;
            hazard.SeekerMine = false;
            hazard.SeekerTriggered = false;
            hazard.HeavyMineTier = 0;
            hazard.Health = 1f;
            hazard.Speed = Mathf.Max(110f, hazard.Speed * 0.45f);
            hazard.Spin = 72f;
            hazard.TamerParalyzeTimer = 0f;
            hazard.Root.name = "TamedSymbiote";
            hazard.Root.sizeDelta = Vector2.one * SymbiosisLinkSpriteSize;
            hazard.Radius = SymbiosisLinkSpriteSize * 0.58f;

            if (hazard.Image != null)
            {
                Sprite linkedSprite = GetSpriteFromTextureResource(SymbiosisLinkedSpriteResourcePath);
                if (linkedSprite != null)
                {
                    hazard.Image.sprite = linkedSprite;
                    hazard.Image.color = Color.white;
                    hazard.Image.preserveAspect = true;
                }
                else
                {
                    hazard.Image.sprite = GetShieldBubbleSprite();
                    hazard.Image.color = new Color(0.18f, 1f, 0.72f, 0.72f);
                    AddSymbioteLinkMarks(hazard.Root);
                }
            }

            PlayPartPickupSound();
        }

        private Vector2 ResolveGladiatorGuardPosition(RectTransform root)
        {
            float baseY = ResolveGameOrbY();
            if (baseShipHull != null)
                baseY = Mathf.Max(baseY, ResolveBaseShipLocalToWorldPoint(new Vector2(0f, baseShipHull.sizeDelta.y * 0.94f)).y);

            float maxY = root != null ? root.rect.height * 0.5f - 220f : 520f;
            return new Vector2(0f, Mathf.Min(baseY + GladiatorGuardYOffset, maxY));
        }

        private int FindNearestGladiatorTarget(Vector2 origin, float range)
        {
            int bestIndex = -1;
            float bestSqr = range * range;
            for (int i = hazards.Count - 1; i >= 0; i--)
            {
                HazardView hazard = hazards[i];
                if (hazard.Root == null || hazard.Symbiote)
                    continue;

                float sqr = (hazard.Root.anchoredPosition - origin).sqrMagnitude;
                if (sqr > bestSqr)
                    continue;

                bestSqr = sqr;
                bestIndex = i;
            }

            return bestIndex;
        }

        private void StrikeWithGladiatorArc(Vector2 targetPosition, Vector2 forward)
        {
            Vector2 arcCenter = gladiatorDronePosition + forward * 52f;
            for (int i = hazards.Count - 1; i >= 0; i--)
            {
                HazardView hazard = hazards[i];
                if (hazard.Root == null || hazard.Symbiote)
                    continue;

                Vector2 enemyPosition = hazard.Root.anchoredPosition;
                Vector2 toEnemy = enemyPosition - gladiatorDronePosition;
                if (Vector2.Distance(arcCenter, enemyPosition) > GladiatorStrikeRadius + hazard.Radius)
                    continue;
                if (toEnemy.sqrMagnitude > 1f && Vector2.Dot(forward, toEnemy.normalized) < 0.05f)
                    continue;

                DamageHazardByGladiator(i, forward);
            }

            if (statusText != null)
                statusText.text = "GLADIATOR STRIKE";
        }

        private void DamageHazardByGladiator(int index, Vector2 forward)
        {
            if (index < 0 || index >= hazards.Count)
                return;

            HazardView hazard = hazards[index];
            if (hazard.Root == null)
                return;

            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            Vector2 enemyPos = root != null ? GetHazardCanvasPosition(hazard, root) : hazard.Root.anchoredPosition;
            hazard.Health -= GladiatorStrikeDamage;
            TriggerHazardHitFeedback(hazard);
            if (hazard.Health > 0f)
            {
                Vector2 knockback = forward.sqrMagnitude > 0.01f ? forward.normalized : Vector2.up;
                hazard.Root.anchoredPosition += knockback * GladiatorKnockbackDistance;
                hazard.Velocity += knockback * 90f;
                return;
            }

            ResolveHazardDestroyedByWeapon(hazard, enemyPos);
            score += 20;
            RefreshHud();
            RefreshUpgradeLabels();
            Destroy(hazard.Root.gameObject);
            hazards.RemoveAt(index);
        }

        private void UpdateMineLayerDrone()
        {
            if (!mineLayerDroneOwned || !mineLayerDroneSpawnedThisRun || mineLayerDrone == null || !mineLayerDrone.gameObject.activeSelf)
                return;
            if (battleDraggedDroneTarget == DroneUpgradeTarget.MineLayer)
                return;

            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return;

            int missingSlot = FindNextMineLayerMissingSlot();
            bool canInstall = missingSlot >= 0 && HasOzParts(MineLayerMinePartCost);
            if (!canInstall)
            {
                mineLayerTargetSlot = -1;
                mineLayerInstallTimer = 0f;
                mineLayerInstallShakeTimer = 0f;
                Vector2 patrol = GetMineLayerHangarPatrolTarget(root);
                SmoothMoveDroneToward(mineLayerDrone, ref mineLayerDronePosition, patrol, MineLayerHangarResponse, Mathf.Sin(Time.time * 10f) * 2f);
                mineLayerDrone.anchoredPosition = mineLayerDronePosition + WorkVibration(0.45f, 12f);
                mineLayerDrone.localScale = Vector3.one * 1.02f;
                if (missingSlot >= 0 && statusText != null)
                    statusText.text = "MINE LAYER NEEDS OZPARTS";
                UpdateDroneDamageTint(mineLayerDrone, mineLayerDroneHealth, MineLayerDroneMaxHealth);
                return;
            }

            Vector2 minePosition = ResolveMineLayerMinePosition(missingSlot, root);
            Vector2 installPosition = ResolveMineLayerInstallPosition(missingSlot, root);
            float distance = Vector2.Distance(mineLayerDronePosition, installPosition);
            if (mineLayerTargetSlot != missingSlot)
            {
                mineLayerTargetSlot = missingSlot;
                mineLayerInstallTimer = 0f;
            }

            if (distance > 26f)
            {
                mineLayerInstallTimer = 0f;
                SmoothMoveDroneToward(mineLayerDrone, ref mineLayerDronePosition, installPosition, MineLayerTravelResponse, Mathf.Sin(Time.time * 10f) * 2f);
                mineLayerDrone.anchoredPosition = mineLayerDronePosition;
            }
            else
            {
                mineLayerInstallTimer += Time.deltaTime;
                mineLayerInstallShakeTimer = MineLayerInstallShakeSeconds;
                mineLayerDronePosition = Vector2.Lerp(mineLayerDronePosition, installPosition, 1f - Mathf.Exp(-MineLayerInstallHoldResponse * Time.deltaTime));
                float strength = Mathf.Lerp(1.5f, MineLayerInstallShakePixels, Mathf.Clamp01(mineLayerInstallTimer / MineLayerInstallSeconds));
                mineLayerDrone.anchoredPosition = mineLayerDronePosition + WorkVibration(strength, 74f);
                mineLayerDrone.localScale = Vector3.one * (1.05f + Mathf.Sin(Time.time * 28f) * 0.035f);
                FaceDroneToward(mineLayerDrone, mineLayerDronePosition, minePosition, Mathf.Sin(Time.time * 74f) * 5f);
                UpdateCrafterCraftSound(true);

                if (mineLayerInstallTimer >= MineLayerInstallSeconds)
                {
                    TryPlaceMineLayerMine(missingSlot, minePosition);
                    mineLayerInstallTimer = 0f;
                    mineLayerTargetSlot = -1;
                }
            }

            mineLayerInstallShakeTimer = Mathf.Max(0f, mineLayerInstallShakeTimer - Time.deltaTime);
            UpdateDroneDamageTint(mineLayerDrone, mineLayerDroneHealth, MineLayerDroneMaxHealth);
        }

        private Vector2 GetMineLayerHangarPatrolTarget(RectTransform root)
        {
            return GetHangarDronePatrolTarget(root, mineLayerDronePosition, ref mineLayerDronePatrolTarget, ref mineLayerDronePatrolTimer, 6, 72f, 34f, 1.0f, 2.4f);
        }

        private int FindNextMineLayerMissingSlot()
        {
            for (int slot = 0; slot < MineLayerMineCapacity; slot++)
            {
                if (!IsMineLayerSlotOccupied(slot))
                    return slot;
            }

            return -1;
        }

        private bool IsMineLayerSlotOccupied(int slot)
        {
            for (int i = 0; i < friendlyMineLayerMines.Count; i++)
            {
                FriendlyMineView mine = friendlyMineLayerMines[i];
                if (mine.Root != null && mine.Slot == slot)
                    return true;
            }

            return false;
        }

        private Vector2 ResolveMineLayerMinePosition(int slot, RectTransform root)
        {
            float width = root != null ? root.rect.width : 900f;
            float halfLine = Mathf.Min(MineLayerMineSpacing * (MineLayerMineCapacity - 1) * 0.5f, width * 0.44f);
            float spacing = MineLayerMineCapacity > 1 ? halfLine * 2f / (MineLayerMineCapacity - 1) : 0f;
            Vector2 center = ResolveMineLayerLineCenter(root);
            return center + new Vector2((slot - (MineLayerMineCapacity - 1) * 0.5f) * spacing, 0f);
        }

        private Vector2 ResolveMineLayerInstallPosition(int slot, RectTransform root)
        {
            return ResolveMineLayerMinePosition(slot, root) + new Vector2(0f, -64f);
        }

        private Vector2 ResolveMineLayerLineCenter(RectTransform root)
        {
            float height = root != null ? root.rect.height : 1600f;
            float dockY = ResolveBaseShipDockPosition().y;
            float minY = -height * 0.5f + 245f;
            float maxY = -height * 0.08f;
            return new Vector2(0f, Mathf.Clamp(dockY + 180f, minY, maxY));
        }

        private void TryPlaceMineLayerMine(int slot, Vector2 position)
        {
            if (slot < 0 || slot >= MineLayerMineCapacity || IsMineLayerSlotOccupied(slot))
                return;

            if (!HasOzParts(MineLayerMinePartCost))
            {
                if (statusText != null)
                    statusText.text = "MINE LAYER NEEDS OZPARTS";
                return;
            }

            SpendOzParts(MineLayerMinePartCost);
            PlayerPrefs.SetInt(OzPartsKey, ozParts);
            PlayerPrefs.Save();
            SpawnFriendlyMineLayerMine(slot, position);
            if (statusText != null)
                statusText.text = "MINE SET " + ActiveMineLayerMineCount() + "/" + MineLayerMineCapacity;
            RefreshHud();
            RefreshUpgradeLabels();
        }

        private void SpawnFriendlyMineLayerMine(int slot, Vector2 position)
        {
            if (playfield == null)
                return;

            GameObject go = new GameObject("FriendlyMineLayerMine", typeof(RectTransform), typeof(CanvasRenderer), typeof(Image));
            go.transform.SetParent(playfield, false);
            RectTransform rect = go.GetComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = new Vector2(MineLayerMineSize, MineLayerMineSize);
            rect.anchoredPosition = position;

            Image image = go.GetComponent<Image>();
            image.raycastTarget = false;
            image.color = Color.white;
            image.preserveAspect = true;
            Sprite sprite = GetSpriteFromTextureResource(FriendlyMineLayerSpriteResourcePath);
            if (sprite != null)
                image.sprite = sprite;
            else
                AddOutline(rect, new Color(0.15f, 1f, 0.92f, 0.65f), new Vector2(2f, -2f));

            friendlyMineLayerMines.Add(new FriendlyMineView
            {
                Root = rect,
                Image = image,
                Slot = slot,
                Position = position,
                ArmingTimer = 0.18f
            });
        }

        private int ActiveMineLayerMineCount()
        {
            int count = 0;
            for (int i = 0; i < friendlyMineLayerMines.Count; i++)
            {
                if (friendlyMineLayerMines[i].Root != null)
                    count++;
            }

            return count;
        }

        private void UpdateFriendlyMineLayerMines()
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return;

            for (int i = friendlyMineLayerMines.Count - 1; i >= 0; i--)
            {
                FriendlyMineView mine = friendlyMineLayerMines[i];
                if (mine.Root == null)
                {
                    friendlyMineLayerMines.RemoveAt(i);
                    continue;
                }

                mine.Position = ResolveMineLayerMinePosition(mine.Slot, root);
                mine.Root.anchoredPosition = mine.Position;
                mine.ArmingTimer = Mathf.Max(0f, mine.ArmingTimer - Time.deltaTime);
                float pulse = 0.5f + Mathf.Sin(Time.time * 9f + mine.Slot) * 0.5f;
                mine.Root.localScale = Vector3.one * (1f + pulse * 0.055f);
                mine.Root.localRotation = Quaternion.Euler(0f, 0f, Mathf.Sin(Time.time * 2.4f + mine.Slot) * 4f);
                if (mine.Image != null)
                    mine.Image.color = new Color(0.82f + pulse * 0.18f, 1f, 1f, mine.ArmingTimer > 0f ? 0.62f : 1f);

                if (mine.ArmingTimer > 0f)
                    continue;

                for (int h = hazards.Count - 1; h >= 0; h--)
                {
                    HazardView hazard = hazards[h];
                    if (hazard.Root == null || hazard.Symbiote)
                        continue;

                    Vector2 hazardPos = GetHazardCanvasPosition(hazard, root);
                    if (Vector2.Distance(mine.Position, hazardPos) > MineLayerMineTriggerRadius + hazard.Radius)
                        continue;

                    DetonateFriendlyMineLayerMine(i, mine.Position, root);
                    break;
                }
            }
        }

        private void DetonateFriendlyMineLayerMine(int mineIndex, Vector2 position, RectTransform root)
        {
            if (mineIndex < 0 || mineIndex >= friendlyMineLayerMines.Count)
                return;

            FriendlyMineView mine = friendlyMineLayerMines[mineIndex];
            if (mine.Root != null)
                Destroy(mine.Root.gameObject);
            friendlyMineLayerMines.RemoveAt(mineIndex);
            SpawnMineExplosion(position);
            PlayEnemyDeathSound();

            for (int i = hazards.Count - 1; i >= 0; i--)
            {
                HazardView hazard = hazards[i];
                if (hazard.Root == null)
                {
                    hazards.RemoveAt(i);
                    continue;
                }

                if (hazard.Symbiote)
                    continue;

                Vector2 hazardPos = GetHazardCanvasPosition(hazard, root);
                float distance = Vector2.Distance(position, hazardPos);
                if (distance > MineLayerMineBlastRadius + hazard.Radius)
                    continue;

                float falloff = 1f - Mathf.Clamp01(distance / Mathf.Max(1f, MineLayerMineBlastRadius)) * 0.42f;
                hazard.Health -= Mathf.Max(12f, MineLayerMineDamage * falloff);
                TriggerHazardHitFeedback(hazard);
                if (hazard.Health > 0f)
                    continue;

                ResolveHazardDestroyedByFriendlyMine(hazard, hazardPos);
                score += 16;
                if (hazard.Root != null)
                    Destroy(hazard.Root.gameObject);
                hazards.RemoveAt(i);
            }

            RefreshHud();
            RefreshUpgradeLabels();
        }

        private void ResolveHazardDestroyedByFriendlyMine(HazardView hazard, Vector2 enemyPos)
        {
            SpawnMineExplosion(enemyPos);
            if (hazard.TutorialMaterialEnemy)
            {
                SpawnPartDrop(enemyPos);
                return;
            }

            if (hazard.HeavyMineTier == 1)
            {
                SpawnHeavyMineSplit(enemyPos, 2, hazard.BossPhaseMinion);
                return;
            }

            if (hazard.HeavyMineTier == 2)
            {
                SpawnHeavyMineSplit(enemyPos, 3, hazard.BossPhaseMinion);
                return;
            }

            SpawnPartDrop(enemyPos);
        }

        private bool TryFindCollectorPartTarget(out int partIndex, out Vector2 position)
        {
            partIndex = -1;
            position = Vector2.zero;
            float bestDistance = float.MaxValue;
            for (int i = 0; i < partDrops.Count; i++)
            {
                PartDropView part = partDrops[i];
                if (part.Root == null || !IsPartInCollectorZone(part.Root.anchoredPosition))
                    continue;

                float distance = Vector2.Distance(collectorDronePosition, part.Root.anchoredPosition);
                if (distance >= bestDistance)
                    continue;

                bestDistance = distance;
                partIndex = i;
                position = part.Root.anchoredPosition;
            }

            return partIndex >= 0;
        }

        private bool IsPartInCollectorZone(Vector2 position)
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return false;

            float bottom = -root.rect.height * 0.5f + 70f;
            float top = IsHorizonRelayActive() ? root.rect.height * HorizonCollectorTopBonusFraction : 0f;
            float xLimit = root.rect.width * (IsHorizonRelayActive() ? 0.62f : 0.50f);
            return position.y >= bottom && position.y <= top && Mathf.Abs(position.x) <= xLimit;
        }

        private Vector2 GetCollectorPatrolTarget(RectTransform root)
        {
            return GetHangarDronePatrolTarget(root, collectorDronePosition, ref collectorDronePatrolTarget, ref collectorDronePatrolTimer, 3, 78f, 36f, 1.1f, 2.6f);
        }

        private void CollectPartByCollector(int index)
        {
            if (index < 0 || index >= partDrops.Count)
                return;

            PartDropView part = partDrops[index];
            collectorCarriedParts = Mathf.Min(CollectorCarryCapacity, collectorCarriedParts + Mathf.Max(1, part.Value));
            PlayPartPickupSound();
            if (part.Root != null)
                Destroy(part.Root.gameObject);
            partDrops.RemoveAt(index);
        }

        private void UpdateCollectorBeam(Vector2 targetPos)
        {
            if (collectorBeam == null)
                return;

            Vector2 direction = targetPos - collectorDronePosition;
            float length = direction.magnitude;
            if (length < 1f)
                return;

            collectorBeam.gameObject.SetActive(true);
            collectorBeam.anchoredPosition = collectorDronePosition;
            collectorBeam.sizeDelta = new Vector2(3.2f + Mathf.Sin(Time.time * 22f) * 1.0f, length);
            collectorBeam.localRotation = Quaternion.Euler(0f, 0f, Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg - 90f);
        }

        private void UpdateShieldDroneLaser()
        {
            if (shieldDroneLaser == null || shieldDrone == null)
                return;

            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return;

            int targetIndex = -1;
            Vector2 targetPos = Vector2.zero;
            float bestScore = float.MaxValue;
            float baseY = ResolveGameOrbY();
            float baseZoneTop = baseY + 285f;
            float baseZoneBottom = baseY - 110f;
            float baseZoneHalfWidth = root.rect.width * 0.48f;
            for (int i = 0; i < hazards.Count; i++)
            {
                HazardView hazard = hazards[i];
                if (hazard.Root == null || hazard.Symbiote || hazard.ElectricDeathPending)
                    continue;

                Vector2 hazardPos = hazard.Root.anchoredPosition;
                hazardPos.y += root.rect.height * 0.5f;
                float distance = Vector2.Distance(shieldDronePosition, hazardPos);
                bool inBaseZone = hazardPos.y >= baseZoneBottom && hazardPos.y <= baseZoneTop && Mathf.Abs(hazardPos.x) <= baseZoneHalfWidth;
                float allowedRange = inBaseZone ? ShieldDroneBaseZoneLaserRange : ShieldDroneLaserRange;
                if (distance > allowedRange)
                    continue;

                float score = inBaseZone ? distance * 0.55f : distance + 1000f;
                if (score < bestScore)
                {
                    bestScore = score;
                    targetIndex = i;
                    targetPos = hazardPos;
                }
            }

            if (targetIndex < 0)
                return;

            Vector2 direction = targetPos - shieldDronePosition;
            float length = direction.magnitude;
            if (length < 1f)
                return;

            shieldDroneLaser.gameObject.SetActive(true);
            shieldDroneLaser.anchoredPosition = shieldDronePosition;
            shieldDroneLaser.sizeDelta = new Vector2(4f + Mathf.Sin(Time.time * 24f) * 1.5f, length);
            shieldDroneLaser.localRotation = Quaternion.Euler(0f, 0f, Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg - 90f);

            HazardView target = hazards[targetIndex];
            target.Health -= ShieldDroneLaserDps * Time.deltaTime;
            if (target.Health > 0f)
                return;

            ResolveHazardDestroyedByWeapon(target, targetPos);
            score += 12;
            if (target.Root != null)
                Destroy(target.Root.gameObject);
            hazards.RemoveAt(targetIndex);
            RefreshHud();
        }

        private void TryLaunchRepairToOrb(bool commandOverOrb = false)
        {
            if (repairDrone == null || !repairDrone.gameObject.activeSelf)
                return;

            if (collectorDroneAttached || collectorDroneFlyingToOrb)
            {
                if (statusText != null)
                    statusText.text = "SUPPORT SLOT BUSY";
                return;
            }

            if (!commandOverOrb && Vector2.Distance(repairDrone.anchoredPosition, orb.anchoredPosition) > 90f)
                return;

            repairPosition = repairDrone.anchoredPosition;
            repairFlyingToOrb = true;
        }

        private void TryLaunchGeneratorToOrb(bool commandOverOrb = false)
        {
            if (generatorDrone == null || !generatorDrone.gameObject.activeSelf)
                return;

            if (!commandOverOrb && Vector2.Distance(generatorDrone.anchoredPosition, orb.anchoredPosition) > 90f)
                return;

            generatorPosition = generatorDrone.anchoredPosition;
            generatorFlyingToOrb = true;
        }

        private void UpdateDroneInfoPanel()
        {
            if (droneInfoRoot == null || droneInfoText == null)
                return;

            if (crafterDragging)
            {
                string task = repairOwned && !repairSpawnedThisRun ? "crafts Repair for " + RepairCraftCost + " OzParts" : generatorOwned && !generatorSpawnedThisRun ? "crafts Generator for " + GeneratorCraftCost + " OzParts" : mineLayerDroneOwned && !mineLayerDroneSpawnedThisRun ? "crafts Mine Layer" : shieldDroneOwned && !shieldDroneSpawnedThisRun ? "crafts Shield for " + ShieldDroneCraftCost + " OzParts" : collectorDroneOwned && !collectorDroneSpawnedThisRun ? "crafts Collector for " + CollectorDroneCraftCost + " OzParts" : "patrols and waits for build orders";
                ShowDroneInfo(CrafterDroneSpriteResourcePath, "CRAFTER DRONE\nHP " + crafterHealth + "/35   SHIELD " + crafterTempShield + "\nBuilds allied drones.\nCurrent: " + task);
                return;
            }

            if (generatorDragging)
            {
                ShowDroneInfo(GeneratorDroneSpriteResourcePath, "GENERATOR DRONE\nHP " + generatorHealth + "/45   SHIELD " + generatorTempShield + "\nOn base: charges Orb first.\nAway: shields drones.");
                return;
            }

            if (repairDragging)
            {
                ShowDroneInfo(RepairDroneSpriteResourcePath, "REPAIR DRONE\nHP " + repairHealth + "/40   SHIELD " + repairTempShield + "\nRepairs Orb and drones.\nOn Orb: half-strength repair.");
                return;
            }

            if (shieldDroneDragging)
            {
                ShowDroneInfo(ShieldDroneSpriteResourcePath, "SHIELD DRONE\nHP " + shieldDroneHealth + "/" + ShieldDroneMaxHealth + "\nBlocks hits in front of Orb.\nLaser cuts mines slowly.");
                return;
            }

            if (collectorDroneDragging)
            {
                ShowDroneInfo(CollectorDroneSpriteResourcePath, "COLLECTOR DRONE\nHP " + collectorDroneHealth + "/" + CollectorDroneMaxHealth + "   CARGO " + collectorCarriedParts + "/" + CollectorCarryCapacity + "\nCollects OzParts in lower field.\nOn Orb: +" + CollectorAttachedCarryBonus + " carry capacity.");
                return;
            }

            droneInfoRoot.gameObject.SetActive(false);
        }

        private void ShowDroneInfo(string spriteResourcePath, string text)
        {
            droneInfoRoot.gameObject.SetActive(true);
            droneInfoText.text = text;

            if (droneInfoPortrait == null)
                return;

            Sprite sprite = GetSpriteFromTextureResource(spriteResourcePath);
            if (sprite != null)
            {
                droneInfoPortrait.sprite = sprite;
                droneInfoPortrait.color = Color.white;
                droneInfoPortrait.enabled = true;
            }
            else
            {
                droneInfoPortrait.sprite = null;
                droneInfoPortrait.color = new Color(0.22f, 0.90f, 1f, 0.45f);
                droneInfoPortrait.enabled = true;
            }
        }

        private bool TryHandleOrbDoubleTap(Vector2 screenPosition)
        {
            return false;
