        private static void ReadGameplayInput(out bool pressed, out bool held, out bool released, out Vector2 pointerPosition, out float keyboard)
        {
            pressed = false;
            held = false;
            released = false;
            pointerPosition = Vector2.zero;
            keyboard = 0f;

#if ENABLE_INPUT_SYSTEM
            if (Touchscreen.current != null)
            {
                var touch = Touchscreen.current.primaryTouch;
                if (touch.press.isPressed)
                {
                    held = true;
                    pointerPosition = touch.position.ReadValue();
                }

                pressed = touch.press.wasPressedThisFrame;
                released = touch.press.wasReleasedThisFrame;
            }

            if (!held && Mouse.current != null)
            {
                held = Mouse.current.leftButton.isPressed;
                pressed = Mouse.current.leftButton.wasPressedThisFrame;
                released = Mouse.current.leftButton.wasReleasedThisFrame;
                pointerPosition = Mouse.current.position.ReadValue();
            }

            if (Keyboard.current != null)
            {
                if (Keyboard.current.leftArrowKey.isPressed || Keyboard.current.aKey.isPressed)
                    keyboard -= 1f;
                if (Keyboard.current.rightArrowKey.isPressed || Keyboard.current.dKey.isPressed)
                    keyboard += 1f;
            }
#else
            pressed = Input.GetMouseButtonDown(0);
            held = Input.GetMouseButton(0);
            released = Input.GetMouseButtonUp(0);
            pointerPosition = Input.mousePosition;
            keyboard = Input.GetAxisRaw("Horizontal");
#endif
        }

        private static Vector2 ResolveOrbMoveLimits(RectTransform root)
        {
            if (root == null)
                return new Vector2(500f, 760f);

            float x = Mathf.Max(220f, root.rect.width * 0.5f + 96f);
            float y = Mathf.Max(320f, root.rect.height * (0.5f + ForwardFlightScreenFraction));
            return new Vector2(x, y);
        }

        private void UpdateOrb()
        {
            if (orb == null)
                return;

            if (appliedOrbEvolutionLevel != CurrentStationEvolutionLevel())
                ApplyCurrentOrbEvolutionVisual();

            if (menuHangarOpen)
            {
                Vector2 dock = hangarRecoveryActive ? ResolveHangarRecoveryOrbPosition() : ResolveBaseShipDockPosition();
                laneX = Mathf.Lerp(laneX, dock.x, 1f - Mathf.Exp(-8.0f * Time.unscaledDeltaTime));
                orbY = Mathf.Lerp(orbY, dock.y, 1f - Mathf.Exp(-8.0f * Time.unscaledDeltaTime));
                targetLaneX = dock.x;
                targetOrbY = dock.y;
            }
            else if (!IsMenuLikeState() && IsOrbHeldOnBaseShip() && !pointerControl && !transitioningToGame)
            {
                Vector2 dock = ResolveActiveDefenseDockPosition();
                targetLaneX = dock.x;
                targetOrbY = dock.y;
            }
            else if (!IsMenuLikeState() && orbDeploymentStage == OrbDeploymentStage.UndockingToHover && !transitioningToGame)
            {
                targetLaneX = 0f;
                targetOrbY = ResolveGameOrbY();
            }

            if (menuHangarOpen)
            {
                // Position is handled above so the menu hangar can show the orb docked on the base.
            }
            else if (IsMenuLikeState())
                orbY = ResolveMenuOrbY() + Mathf.Sin(Time.unscaledTime * 1.65f) * 18f;
            else if (!transitioningToGame && !pointerControl && !IsOrbDockedOnBaseShip() && !IsOrbBaseTransitionLocked())
                orbY += Mathf.Sin(Time.unscaledTime * 2.15f) * 0.08f;

            orb.anchoredPosition = new Vector2(laneX, orbY);
            if (!transitioningToGame)
            {
                float desiredScale = menuHangarOpen
                    ? ResolveMenuHangarDockedOrbScale()
                    : (IsMenuLikeState() ? 2.35f * CurrentOrbEvolutionScale() : IsOrbHeldOnBaseShip() ? ResolveActiveDockedOrbScale() : CurrentOrbEvolutionScale());
                orbScale = Mathf.Lerp(orbScale, desiredScale, 1f - Mathf.Exp(-10f * Time.deltaTime));
                targetOrbScale = desiredScale;
            }

            ApplyOrbScale();
            bool menuLikeState = IsMenuLikeState();
            if (menuHangarOpen || IsOrbHeldOnBaseShip() || IsOrbBaseTransitionLocked())
                orb.localRotation = Quaternion.identity;
            else
                orb.Rotate(0f, 0f, (menuLikeState ? -28f : -145f) * Time.deltaTime);
            UpdateStationModules();
            UpdateOrbRepairFlash();

            if (orbitRing != null)
            {
                orbitRing.anchoredPosition = new Vector2(laneX, orbY);
                orbitRing.Rotate(0f, 0f, (menuLikeState ? 14f : 48f) * Time.deltaTime);
            }

            if (shieldRing != null)
            {
                bool menuGeneratorCharging = menuLikeState && (menuSceneStep == MenuSceneStep.GeneratorCharge || menuShieldTimer > 0f);
                if (!menuGeneratorCharging)
                UpdateShieldBubble(shieldRing, shield > 0, shield / (float)CurrentMaxShield(), OrbShieldBubbleBaseSize);
            }

            UpdateGameTitlePosition();
        }

        private void UpdateStationModules()
        {
            UpdateCoreCannonVisual();

            if (homingMissileModule == null || laserModule == null || arcChainModule == null || railSpikeModule == null)
            {
                BringCoreCannonToFront();
                return;
            }

            bool orbVisible = orb != null && orb.gameObject.activeSelf && ShouldShowStationWeapons();
            bool menuScan = IsWeaponMenuScanState();
            bool baseTarget = IsWeaponModuleBaseTargetState();

            if (baseTarget)
            {
                Vector2 missileSlot = ResolveDockedModuleSlotPosition(0);
                Vector2 laserSlot = ResolveDockedModuleSlotPosition(1);
                Vector2 arcSlot = ResolveDockedModuleSlotPosition(2);
                Vector2 railSlot = ResolveDockedModuleSlotPosition(3);
                bool readyToFire = IsOrbDockedOnBaseShip() || IsOrbDockedOnOutpost();
                bool hangarDisplay = menuHangarOpen;
                homingMissileModuleAimed = UpdateDockedWeaponModule(homingMissileModule, IsHomingMissileModuleActive() && orbVisible, 0, readyToFire && !hangarDisplay ? FindNearestMissileTarget(missileSlot) : null, 0f, 14f, 8.5f, 0f, hangarDisplay ? 0f : 7f, 1.1f);
                laserModuleAimed = UpdateDockedWeaponModule(laserModule, IsLaserModuleActive() && orbVisible, 1, readyToFire && !hangarDisplay ? FindLaserAimTarget(laserSlot) : null, 0f, 8f, 13f, 0f, hangarDisplay ? 0f : 7f, 1.1f);
                arcChainModuleAimed = UpdateDockedWeaponModule(arcChainModule, IsArcChainModuleActive() && orbVisible, 2, readyToFire && !hangarDisplay ? FindNearestArcTarget(arcSlot) : null, 0f, 12f, 9.5f, 0f, hangarDisplay ? 0f : 7f, 1.1f);
                railSpikeModuleAimed = UpdateDockedWeaponModule(railSpikeModule, IsRailSpikeModuleActive() && orbVisible, 3, readyToFire && !hangarDisplay ? FindNearestRailSpikeTarget(railSlot) : null, 0f, 8f, 12f, 0f, hangarDisplay ? 0f : 7f, 1.1f);
                UpdateBaseModuleStand(0, IsHomingMissileModuleActive() && orbVisible, homingMissileModule);
                UpdateBaseModuleStand(1, IsLaserModuleActive() && orbVisible, laserModule);
                UpdateBaseModuleStand(2, IsArcChainModuleActive() && orbVisible, arcChainModule);
                UpdateBaseModuleStand(3, IsRailSpikeModuleActive() && orbVisible, railSpikeModule);
                BringDockedWeaponModulesToFront();
                if (!readyToFire)
                {
                    homingMissileModuleAimed = false;
                    laserModuleAimed = false;
                    arcChainModuleAimed = false;
                    railSpikeModuleAimed = false;
                    if (laserModuleBeam != null)
                        laserModuleBeam.gameObject.SetActive(false);
                    TryCompleteBaseUnloadSequence();
                }
                BringCoreCannonToFront();
                return;
            }

            if (IsWeaponModuleLoadingToOrb())
            {
                HideBaseModuleStands();
                bool missileArrived = UpdateLoadingWeaponModuleToOrb(homingMissileModule, IsHomingMissileModuleActive() && orbVisible, 0);
                bool laserArrived = UpdateLoadingWeaponModuleToOrb(laserModule, IsLaserModuleActive() && orbVisible, 1);
                bool arcArrived = UpdateLoadingWeaponModuleToOrb(arcChainModule, IsArcChainModuleActive() && orbVisible, 2);
                bool railArrived = UpdateLoadingWeaponModuleToOrb(railSpikeModule, IsRailSpikeModuleActive() && orbVisible, 3);
                homingMissileModuleAimed = false;
                laserModuleAimed = false;
                arcChainModuleAimed = false;
                railSpikeModuleAimed = false;
                if (laserModuleBeam != null)
                    laserModuleBeam.gameObject.SetActive(false);
                if (missileArrived && laserArrived && arcArrived && railArrived)
                    BeginOrbUndockingToHover();
                BringCoreCannonToFront();
                return;
            }

            HideBaseModuleStands();
            bool missileVisible = IsHomingMissileModuleActive() && orbVisible;
            homingMissileModule.gameObject.SetActive(missileVisible);
            if (missileVisible)
            {
                AttachModuleToOrb(homingMissileModule, 0);
                homingMissileModule.anchoredPosition = ResolveOrbModuleLocalPosition(0);
                homingMissileModule.sizeDelta = ResolveOrbModuleSize(0);
                homingMissileModule.localScale = Vector3.one * (menuScan ? 0.72f : 1f);
                Vector2 modulePosition = GetCanvasLocalPosition(homingMissileModule);
                homingMissileModuleAimed = UpdateWeaponModuleAim(homingMissileModule, modulePosition, menuScan ? null : FindNearestMissileTarget(modulePosition), 0f, 14f, 8.5f, 0f, true, menuScan ? 34f : 10f, menuScan ? 1.45f : 1.25f);
            }
            else
            {
                homingMissileModuleAimed = false;
            }

            bool laserVisible = IsLaserModuleActive() && orbVisible;
            laserModule.gameObject.SetActive(laserVisible);
            if (laserVisible)
            {
                AttachModuleToOrb(laserModule, 1);
                laserModule.anchoredPosition = ResolveOrbModuleLocalPosition(1);
                laserModule.sizeDelta = ResolveOrbModuleSize(1);
                laserModule.localScale = Vector3.one * (menuScan ? 0.72f : 1f);
                Vector2 modulePosition = GetCanvasLocalPosition(laserModule);
                laserModuleAimed = UpdateWeaponModuleAim(laserModule, modulePosition, menuScan ? null : FindLaserAimTarget(modulePosition), 180f, 8f, 13f, 0f, true, menuScan ? 30f : 10f, menuScan ? 1.65f : 1.25f);
            }
            else
            {
                laserModuleAimed = false;
                if (laserModuleBeam != null)
                    laserModuleBeam.gameObject.SetActive(false);
            }

            bool arcVisible = IsArcChainModuleActive() && orbVisible;
            arcChainModule.gameObject.SetActive(arcVisible);
            if (arcVisible)
            {
                AttachModuleToOrb(arcChainModule, 2);
                arcChainModule.anchoredPosition = ResolveOrbModuleLocalPosition(2);
                arcChainModule.sizeDelta = ResolveOrbModuleSize(2);
                arcChainModule.localScale = Vector3.one * (menuScan ? 0.72f : 1f);
                Vector2 modulePosition = GetCanvasLocalPosition(arcChainModule);
                arcChainModuleAimed = UpdateWeaponModuleAim(arcChainModule, modulePosition, menuScan ? null : FindNearestArcTarget(modulePosition), -90f, 12f, 9.5f, 0f, true, menuScan ? 32f : 10f, menuScan ? 1.25f : 1.25f);
            }
            else
            {
                arcChainModuleAimed = false;
            }

            bool railVisible = IsRailSpikeModuleActive() && orbVisible;
            railSpikeModule.gameObject.SetActive(railVisible);
            if (railVisible)
            {
                AttachModuleToOrb(railSpikeModule, 3);
                railSpikeModule.anchoredPosition = ResolveOrbModuleLocalPosition(3);
                railSpikeModule.sizeDelta = ResolveOrbModuleSize(3);
                railSpikeModule.localScale = Vector3.one * (menuScan ? 0.72f : 1f);
                Vector2 modulePosition = GetCanvasLocalPosition(railSpikeModule);
                railSpikeModuleAimed = UpdateWeaponModuleAim(railSpikeModule, modulePosition, menuScan ? null : FindNearestRailSpikeTarget(modulePosition), 90f, 8f, 12f, 0f, true, menuScan ? 28f : 10f, menuScan ? 1.38f : 1.25f);
            }
            else
            {
                railSpikeModuleAimed = false;
            }

            BringCoreCannonToFront();
        }

        private void AttachModuleParent(RectTransform module, Transform parent)
        {
            if (module == null || parent == null || module.parent == parent)
                return;

            module.SetParent(parent, false);
        }

        private void AttachModuleToOrb(RectTransform module)
        {
            AttachModuleParent(module, orb);
            if (module != null)
            {
                module.anchorMin = new Vector2(0.5f, 0.5f);
                module.anchorMax = new Vector2(0.5f, 0.5f);
            }
        }

        private void AttachModuleToOrb(RectTransform module, int moduleIndex)
        {
            AttachModuleToOrb(module);
            if (module != null)
                module.pivot = ResolveOrbModulePivot(moduleIndex);
        }

        private void AttachModuleToBaseShip(RectTransform module, bool preserveCanvasPosition = false)
        {
            RectTransform root = WorldCoordinateRoot();
            Vector2 position = preserveCanvasPosition ? GetCanvasLocalPosition(module) : Vector2.zero;
            AttachModuleParent(module, root);
            if (module != null)
            {
                module.anchorMin = new Vector2(0.5f, 0.5f);
                module.anchorMax = new Vector2(0.5f, 0.5f);
                if (preserveCanvasPosition)
                    module.anchoredPosition = position;
            }
        }

        private void TryCompleteBaseUnloadSequence()
        {
            if (orbDeploymentStage != OrbDeploymentStage.DockingToBase)
                return;

            Vector2 dock = ResolveActiveDefenseDockPosition();
            bool orbArrived = Vector2.Distance(new Vector2(laneX, orbY), dock) <= WeaponModuleTransitionDistance;
            bool baseArrived = outpostDefenderMode || baseShipDeploymentBlend >= 0.94f;
            bool modulesArrived =
                IsWeaponModuleNearTarget(homingMissileModule, IsHomingMissileModuleActive(), ResolveDockedModuleSlotPosition(0)) &&
                IsWeaponModuleNearTarget(laserModule, IsLaserModuleActive(), ResolveDockedModuleSlotPosition(1)) &&
                IsWeaponModuleNearTarget(arcChainModule, IsArcChainModuleActive(), ResolveDockedModuleSlotPosition(2)) &&
                IsWeaponModuleNearTarget(railSpikeModule, IsRailSpikeModuleActive(), ResolveDockedModuleSlotPosition(3));

            if (!orbArrived || !baseArrived || !modulesArrived)
                return;

            laneX = dock.x;
            orbY = dock.y;
            targetLaneX = dock.x;
            targetOrbY = dock.y;
            SetOrbDeploymentStage(OrbDeploymentStage.Defender);
            orbScale = ResolveActiveDockedOrbScale();
            targetOrbScale = orbScale;
            ApplyOrbScale();
            if (statusText != null)
                statusText.text = outpostDefenderMode ? L("status.outpost_mode") : "DEFENDER MODE";
        }

        private void BeginOrbUndockingToHover()
        {
            if (orbDeploymentStage != OrbDeploymentStage.LoadingToOrb)
                return;

            SnapWeaponModulesToOrb();
            if (outpostOrbLaunchPending)
            {
                outpostOrbLaunchPending = false;
                if (outpostDefenderMode && outpostBuilt && !outpostPositionLocked)
                    targetOutpostY = ResolveDefaultOutpostY();
                outpostDefenderMode = false;
                SetOrbDeploymentStage(OrbDeploymentStage.Flight);
                targetLaneX = outpostOrbLaunchTarget.x;
                targetOrbY = outpostOrbLaunchTarget.y;
                if (statusText != null)
                    statusText.text = "ORBITER LAUNCHING";
                return;
            }

            if (outpostDefenderMode && outpostBuilt && !outpostPositionLocked)
                targetOutpostY = ResolveDefaultOutpostY();
            outpostDefenderMode = false;
            SetOrbDeploymentStage(OrbDeploymentStage.UndockingToHover);
            targetLaneX = 0f;
            targetOrbY = ResolveGameOrbY();
            if (statusText != null)
                statusText.text = "ORBITER LAUNCHING";
        }

        private void SnapWeaponModulesToOrb()
        {
            SnapWeaponModuleToOrb(homingMissileModule, IsHomingMissileModuleActive(), 0);
            SnapWeaponModuleToOrb(laserModule, IsLaserModuleActive(), 1);
            SnapWeaponModuleToOrb(arcChainModule, IsArcChainModuleActive(), 2);
            SnapWeaponModuleToOrb(railSpikeModule, IsRailSpikeModuleActive(), 3);
        }

        private void SnapWeaponModuleToOrb(RectTransform module, bool owned, int moduleIndex)
        {
            if (module == null || !owned)
                return;

            AttachModuleToOrb(module);
            module.anchoredPosition = ResolveOrbModuleLocalPosition(moduleIndex);
            module.sizeDelta = ResolveOrbModuleSize(moduleIndex);
            module.localScale = Vector3.one;
            module.localRotation = Quaternion.Euler(0f, 0f, ResolveOrbModuleParkedZ(moduleIndex));
        }

        private bool IsWeaponModuleNearTarget(RectTransform module, bool owned, Vector2 target)
        {
            if (!owned || module == null || !module.gameObject.activeSelf)
                return true;

            return Vector2.Distance(module.anchoredPosition, target) <= WeaponModuleTransitionDistance;
        }

        private bool UpdateLoadingWeaponModuleToOrb(RectTransform module, bool owned, int moduleIndex)
        {
            if (module == null)
                return true;

            module.gameObject.SetActive(owned && ShouldShowStationWeapons());
            if (!module.gameObject.activeSelf)
                return true;

            AttachModuleToBaseShip(module, true);
            Vector2 target = ResolveOrbModuleCanvasPosition(moduleIndex);
            float dt = WeaponModuleDeltaTime();
            float response = 1f - Mathf.Exp(-WeaponModuleOrbLoadResponse * dt);
            module.sizeDelta = Vector2.Lerp(module.sizeDelta, ResolveOrbModuleSize(moduleIndex), response);
            module.localScale = Vector3.one;
            module.anchoredPosition = Vector2.Lerp(module.anchoredPosition, target, response);
            UpdateWeaponModuleAim(module, module.anchoredPosition, null, ResolveOrbModuleParkedZ(moduleIndex), 10f, 8f, 0f, false, 0f, 1f);
            return Vector2.Distance(module.anchoredPosition, target) <= WeaponModuleTransitionDistance;
        }

        private bool UpdateDockedWeaponModule(RectTransform module, bool owned, int moduleIndex, Vector2? target, float parkedLocalZ, float aimTolerance, float response, float spriteForwardOffset = 0f, float scanAmplitude = 10f, float scanSpeed = 1.25f)
        {
            if (module == null)
                return false;

            module.gameObject.SetActive(owned && ShouldShowStationWeapons());
            if (!module.gameObject.activeSelf)
                return false;

            AttachModuleToBaseShip(module, true);
            module.pivot = ResolveBaseShipModulePivot(moduleIndex);
            module.sizeDelta = Vector2.Lerp(module.sizeDelta, ResolveBaseShipModuleSize(moduleIndex), 1f - Mathf.Exp(-WeaponModuleBaseUnloadResponse * WeaponModuleDeltaTime()));
            module.localScale = Vector3.one;
            Vector2 slot = ResolveDockedModuleSlotPosition(moduleIndex);
            module.anchoredPosition = IsOrbDockedOnOutpost()
                ? slot
                : Vector2.Lerp(module.anchoredPosition, slot, 1f - Mathf.Exp(-WeaponModuleBaseUnloadResponse * WeaponModuleDeltaTime()));
            return UpdateWeaponModuleAim(module, module.anchoredPosition, target, parkedLocalZ, aimTolerance, response, spriteForwardOffset, false, scanAmplitude, scanSpeed);
        }

        private void BringDockedWeaponModulesToFront()
        {
            if (homingMissileModule != null && homingMissileModule.gameObject.activeSelf)
                homingMissileModule.SetAsLastSibling();
            if (laserModule != null && laserModule.gameObject.activeSelf)
                laserModule.SetAsLastSibling();
            if (arcChainModule != null && arcChainModule.gameObject.activeSelf)
                arcChainModule.SetAsLastSibling();
            if (railSpikeModule != null && railSpikeModule.gameObject.activeSelf)
                railSpikeModule.SetAsLastSibling();
        }

        private void UpdateBaseModuleStand(int moduleIndex, bool visible, RectTransform module)
        {
            if (outpostDefenderMode && outpostBuilt)
            {
                UpdateOutpostModuleStand(moduleIndex, visible, module);
                return;
            }

            if (moduleIndex < 0 || moduleIndex >= baseModuleStands.Length)
                return;

            RectTransform stand = baseModuleStands[moduleIndex];
            if (stand == null)
                return;

            bool wasActive = stand.gameObject.activeSelf;
            stand.gameObject.SetActive(visible);
            if (!visible)
                return;

            Vector2 targetPosition = ResolveDockedModuleStandLocalPosition(moduleIndex);
            Vector2 targetSize = ResolveBaseShipModuleStandSize(moduleIndex);
            stand.anchorMin = new Vector2(0.5f, 0f);
            stand.anchorMax = new Vector2(0.5f, 0f);
            stand.pivot = new Vector2(0.5f, 0.5f);
            if (!wasActive)
            {
                stand.sizeDelta = targetSize;
                stand.anchoredPosition = targetPosition;
                stand.localScale = Vector3.one * BaseShipModuleStandMinScale;
            }

            stand.sizeDelta = Vector2.Lerp(stand.sizeDelta, targetSize, 1f - Mathf.Exp(-WeaponModuleBaseUnloadResponse * WeaponModuleDeltaTime()));
            stand.anchoredPosition = targetPosition;
            stand.localRotation = Quaternion.identity;
            float targetScale = ResolveBaseModuleStandScale(moduleIndex, module);
            stand.localScale = Vector3.Lerp(stand.localScale, Vector3.one * targetScale, 1f - Mathf.Exp(-8.5f * WeaponModuleDeltaTime()));
        }

        private void UpdateOutpostModuleStand(int moduleIndex, bool visible, RectTransform module)
        {
            if (moduleIndex < 0 || moduleIndex >= outpostModuleStands.Length)
                return;

            RectTransform stand = outpostModuleStands[moduleIndex];
            if (stand == null)
                return;

            bool wasActive = stand.gameObject.activeSelf;
            stand.gameObject.SetActive(visible);
            if (!visible)
                return;

            Vector2 targetPosition = ResolveOutpostModuleStandPosition(moduleIndex);
            Vector2 targetSize = ResolveBaseShipModuleStandSize(moduleIndex) * 0.78f;
            if (!wasActive)
            {
                stand.sizeDelta = targetSize;
                stand.anchoredPosition = targetPosition;
                stand.localScale = Vector3.one * BaseShipModuleStandMinScale;
            }

            stand.sizeDelta = Vector2.Lerp(stand.sizeDelta, targetSize, 1f - Mathf.Exp(-WeaponModuleBaseUnloadResponse * WeaponModuleDeltaTime()));
            stand.anchoredPosition = targetPosition;
            stand.localRotation = Quaternion.identity;
            float targetScale = IsOrbDockedOnOutpost() || module == null ? BaseShipModuleStandMaxScale : ResolveBaseModuleStandScale(moduleIndex, module);
            stand.localScale = Vector3.Lerp(stand.localScale, Vector3.one * targetScale, 1f - Mathf.Exp(-8.5f * WeaponModuleDeltaTime()));
            stand.SetAsLastSibling();
        }

        private float ResolveBaseModuleStandScale(int moduleIndex, RectTransform module)
        {
            if (IsOrbDockedOnBaseShip() || module == null)
                return BaseShipModuleStandMaxScale;

            float distance = Vector2.Distance(module.anchoredPosition, ResolveDockedModuleSlotPosition(moduleIndex));
            float progress = 1f - Mathf.Clamp01(distance / BaseShipModuleStandSpawnDistance);
            progress = Mathf.SmoothStep(0f, 1f, progress);
            return Mathf.Lerp(BaseShipModuleStandMinScale, BaseShipModuleStandMaxScale, progress);
        }

        private void HideBaseModuleStands()
        {
            for (int i = 0; i < baseModuleStands.Length; i++)
            {
                RectTransform stand = baseModuleStands[i];
                if (stand != null)
                    stand.gameObject.SetActive(false);
            }

            for (int i = 0; i < outpostModuleStands.Length; i++)
            {
                RectTransform stand = outpostModuleStands[i];
                if (stand != null)
                    stand.gameObject.SetActive(false);
            }
        }

        private void UpdateCoreCannonVisual()
        {
            if (coreCannon == null || orb == null)
                return;

            bool visible = IsCoreCannonActive() && orb.gameObject.activeSelf && ShouldShowStationWeapons();
            coreCannon.gameObject.SetActive(visible);
            if (!visible)
            {
                coreCannonAimed = false;
                return;
            }

            float level = Mathf.Clamp(attackLevel, 0, 12);
            coreCannon.sizeDelta = new Vector2(32f + level * 1.0f, 68f + level * 1.65f);
            coreCannon.anchoredPosition = orb.anchoredPosition + CoreCannonCenterOffset * Mathf.Max(0.1f, orbScale);
            coreCannon.localScale = Vector3.one * Mathf.Max(0.1f, orbScale);
            if (tutorialCoreCannonManualAim)
            {
                ApplyCoreCannonChargeTint();
                return;
            }

            Vector2 modulePosition = GetCanvasLocalPosition(coreCannon);
            Vector2? target = null;
            if (IsOrbAtBase() && !IsWeaponMenuScanState())
                target = FindNearestEnemyTarget(modulePosition, CurrentProjectileSpeed());

            if (target.HasValue)
                coreCannonAimed = UpdateWeaponModuleAim(coreCannon, modulePosition, target, 0f, 7f, 14f, 0f, false);
            else
            {
                coreCannon.localRotation = Quaternion.identity;
                coreCannonAimed = !IsOrbAtBase();
            }

            ApplyCoreCannonChargeTint();
        }

        private void ApplyCoreCannonChargeTint()
        {
            if (coreCannon == null)
                return;

            Image image = coreCannon.GetComponent<Image>();
            if (image != null)
            {
                float pulse = 0.5f + Mathf.Sin(Time.time * (4.5f + attackLevel * 0.15f)) * 0.5f;
                Color charged = new Color(0.72f, 1f, 1f, 1f);
                image.color = Color.Lerp(Color.white, charged, Mathf.Clamp01(attackLevel * 0.055f + pulse * 0.08f));
            }
        }

        private void BringCoreCannonToFront()
        {
            if (coreCannon == null)
                return;

            coreCannon.SetAsLastSibling();
        }

        private bool UpdateWeaponModuleAim(RectTransform module, Vector2 modulePosition, Vector2? target, float parkedLocalZ, float aimTolerance, float response, float spriteForwardOffset = 0f, bool compensateOrbRotation = true, float scanAmplitude = 10f, float scanSpeed = 1.25f)
        {
            if (module == null)
                return false;

            if (target.HasValue)
            {
                Vector2 direction = ResolveProjectileDirection(modulePosition, target.Value);
                float desiredWorldZ = Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg - 90f;
                float targetParentZ = compensateOrbRotation && orb != null ? orb.eulerAngles.z : 0f;
                float desiredLocalZ = Mathf.DeltaAngle(0f, desiredWorldZ - targetParentZ + spriteForwardOffset);
                float currentLocalZ = module.localEulerAngles.z;
                float nextLocalZ = Mathf.LerpAngle(currentLocalZ, desiredLocalZ, 1f - Mathf.Exp(-response * WeaponModuleDeltaTime()));
                module.localRotation = Quaternion.Euler(0f, 0f, nextLocalZ);

                float currentWorldZ = module.eulerAngles.z;
                float desiredModuleZ = desiredWorldZ + spriteForwardOffset;
                return Mathf.Abs(Mathf.DeltaAngle(currentWorldZ, desiredModuleZ)) <= aimTolerance;
            }

            float parkedZ = IsWeaponMenuScanState()
                ? GetOutwardMenuScanLocalZ(modulePosition, parkedLocalZ, spriteForwardOffset, compensateOrbRotation)
                : parkedLocalZ;
            parkedZ += GetWeaponIdleScanOffset(module, scanAmplitude, scanSpeed);
            parkedZ = Mathf.LerpAngle(module.localEulerAngles.z, parkedZ, 1f - Mathf.Exp(-3.8f * WeaponModuleDeltaTime()));
            module.localRotation = Quaternion.Euler(0f, 0f, parkedZ);
            return false;
        }

        private float GetOutwardMenuScanLocalZ(Vector2 modulePosition, float fallbackLocalZ, float spriteForwardOffset, bool compensateOrbRotation)
        {
            if (orb == null)
                return fallbackLocalZ;

            Vector2 orbPosition = GetCanvasLocalPosition(orb);
            Vector2 outward = modulePosition - orbPosition;
            if (outward.sqrMagnitude <= 1f)
                return fallbackLocalZ;

            float desiredWorldZ = Mathf.Atan2(outward.y, outward.x) * Mathf.Rad2Deg - 90f;
            float parentZ = compensateOrbRotation ? orb.eulerAngles.z : 0f;
            return Mathf.DeltaAngle(0f, desiredWorldZ - parentZ + spriteForwardOffset);
        }

        private float WeaponModuleDeltaTime()
        {
            return IsMenuLikeState() ? Time.unscaledDeltaTime : Time.deltaTime;
        }

        private bool IsMenuLikeState()
        {
            return state == GameState.Menu || state == GameState.ModeSelect || state == GameState.StoryLevels || state == GameState.Upgrade || state == GameState.Settings || state == GameState.Bestiary;
        }

        private bool IsWeaponMenuScanState()
        {
            return state == GameState.Menu || state == GameState.ModeSelect || state == GameState.StoryLevels;
        }

        private bool ShouldShowStationWeapons()
        {
            bool stationControlOpen = stationControlRoot != null && stationControlRoot.gameObject.activeSelf;
            if (!IsTutorialCompleted() && state != GameState.Playing)
                return false;
            if (selectedMode == GameMode.Story && selectedStoryLevel == StoryLevel.Tutorial && !tutorialCoreCannonRevealed)
                return false;
            return !hangarRecoveryActive && state != GameState.Upgrade && state != GameState.Settings && state != GameState.Bestiary && !stationControlOpen;
        }

        private float GetWeaponIdleScanOffset(RectTransform module, float amplitude, float speed)
        {
            if (module == null)
                return 0f;

            float phase = Mathf.Abs(module.GetSiblingIndex() % 997) * 0.017f;
            float clock = IsMenuLikeState() ? Time.unscaledTime : Time.time;
            float primary = Mathf.Sin(clock * speed + phase);
            float secondary = Mathf.Sin(clock * speed * 0.43f + phase * 1.7f) * 0.35f;
            return (primary + secondary) * amplitude;
        }

        private void UpdateOrbRepairFlash()
        {
            Image image = orb != null ? orb.GetComponent<Image>() : null;
            if (image == null)
                return;

            if (hangarRecoveryActive)
            {
                if (tutorialRepairHangarLessonActive)
                {
                    image.color = Color.white;
                    return;
                }

                float progress = Mathf.Clamp01(hangarRecoveryTimer / HangarRecoveryRebuildSeconds);
                float recoveryPulse = 0.5f + Mathf.Sin(Time.unscaledTime * 18f) * 0.5f;
                Color damaged = new Color(0.72f, 0.58f, 0.54f, 1f);
                Color rebuilding = Color.Lerp(damaged, new Color(0.45f, 1f, 0.78f, 1f), Mathf.Lerp(0.18f, 0.46f, recoveryPulse) * (1f - progress * 0.35f));
                image.color = Color.Lerp(rebuilding, Color.white, progress);
                return;
            }

            bool menuRepairing = (state == GameState.Menu || state == GameState.ModeSelect || state == GameState.StoryLevels) && menuSceneStep == MenuSceneStep.RepairOrbit;
            if (orbRepairFlashTimer > 0f)
                orbRepairFlashTimer -= Time.unscaledDeltaTime;

            if (!menuRepairing && orbRepairFlashTimer <= 0f)
            {
                image.color = Color.white;
                return;
            }

            float pulse = 0.5f + Mathf.Sin(Time.unscaledTime * 18f) * 0.5f;
            float strength = menuRepairing ? Mathf.Lerp(0.18f, 0.46f, pulse) : Mathf.Lerp(0.22f, 0.58f, pulse) * Mathf.Clamp01(orbRepairFlashTimer / 0.45f);
            image.color = Color.Lerp(Color.white, new Color(0.38f, 1f, 0.48f, 1f), strength);
        }

        private void UpdateShieldVisuals()
        {
            UpdateShieldBubble(shieldRing, shield > 0, shield / (float)CurrentMaxShield(), OrbShieldBubbleBaseSize);
            UpdateShieldBubble(crafterShieldRing, crafterTempShield > 0 && crafterSpawnedThisRun && crafterDrone != null && crafterDrone.gameObject.activeSelf, 1f, 66f);
            UpdateShieldBubble(generatorShieldRing, generatorTempShield > 0 && generatorDrone != null && generatorDrone.gameObject.activeSelf, 1f, 66f);
            UpdateShieldBubble(repairShieldRing, repairTempShield > 0 && repairDrone != null && repairDrone.gameObject.activeSelf, 1f, 66f);
            crafterRepairFlashTimer = Mathf.Max(0f, crafterRepairFlashTimer - Time.deltaTime);
            generatorRepairFlashTimer = Mathf.Max(0f, generatorRepairFlashTimer - Time.deltaTime);
            shieldDroneRepairFlashTimer = Mathf.Max(0f, shieldDroneRepairFlashTimer - Time.deltaTime);
            collectorDroneRepairFlashTimer = Mathf.Max(0f, collectorDroneRepairFlashTimer - Time.deltaTime);
            tamerDroneRepairFlashTimer = Mathf.Max(0f, tamerDroneRepairFlashTimer - Time.deltaTime);
            UpdateDroneDamageTint(crafterDrone, crafterHealth, 35, crafterRepairFlashTimer);
            UpdateDroneDamageTint(generatorDrone, generatorHealth, 45, generatorRepairFlashTimer);
            UpdateDroneDamageTint(repairDrone, repairHealth, 40);
            UpdateDroneDamageTint(shieldDrone, shieldDroneHealth, ShieldDroneMaxHealth, shieldDroneRepairFlashTimer);
            UpdateDroneDamageTint(collectorDrone, collectorDroneHealth, CollectorDroneMaxHealth, collectorDroneRepairFlashTimer);
            UpdateDroneDamageTint(mineLayerDrone, mineLayerDroneHealth, MineLayerDroneMaxHealth);
            UpdateDroneDamageTint(hiveDrone, hiveDroneHealth, HiveDroneMaxHealth);
            UpdateDroneDamageTint(gladiatorDrone, gladiatorDroneHealth, GladiatorDroneMaxHealth);
            UpdateDroneDamageTint(horizonDrone, horizonDroneHealth, HorizonDroneMaxHealth);
            UpdateDroneDamageTint(tamerDrone, tamerDroneHealth, TamerDroneMaxHealth, tamerDroneRepairFlashTimer);
            UpdateDroneDamageTint(queenDrone, queenDroneHealth, QueenDroneMaxHealth);
            UpdateDroneDamageTint(mimicDrone, mimicDroneHealth, MimicDroneMaxHealth);
            UpdateDroneDamageTint(sniperDrone, sniperDroneHealth, SniperDroneMaxHealth);
        }

        private static void UpdateDroneDamageTint(RectTransform drone, int healthValue, int maxHealth, float repairFlash = 0f)
        {
            if (drone == null)
                return;

            Image image = drone.GetComponent<Image>();
            if (image == null)
                return;

            if (!drone.gameObject.activeSelf)
            {
                image.color = Color.white;
                return;
            }

            float damage = 1f - Mathf.Clamp01(healthValue / (float)Mathf.Max(1, maxHealth));
            Color damageColor = Color.Lerp(Color.white, new Color(1f, 0.34f, 0.28f, 1f), damage * 0.72f);
            if (repairFlash <= 0f)
            {
                image.color = damageColor;
                return;
            }

            float pulse = 0.5f + Mathf.Sin(Time.time * 22f) * 0.5f;
            image.color = Color.Lerp(damageColor, new Color(0.38f, 1f, 0.48f, 1f), Mathf.Clamp01(repairFlash / 0.55f) * Mathf.Lerp(0.22f, 0.62f, pulse));
        }

        private void UpdateShieldBubble(RectTransform bubble, bool active, float power, float baseSize)
        {
            if (bubble == null)
                return;

            bubble.gameObject.SetActive(active);
            if (!active)
                return;

            float pulse = 1f + Mathf.Sin(Time.unscaledTime * 7.2f) * 0.055f;
            float powerScale = Mathf.Lerp(0.86f, 1.08f, Mathf.Clamp01(power));
            bubble.sizeDelta = Vector2.one * baseSize * powerScale;
            bubble.localScale = Vector3.one * pulse;
            bubble.Rotate(0f, 0f, 72f * Time.unscaledDeltaTime);

            Image image = bubble.GetComponent<Image>();
            if (image != null)
            {
                float alpha = Mathf.Lerp(0.18f, 0.38f, Mathf.Clamp01(power));
                image.color = new Color(0.32f, 0.92f, 1f, alpha);
            }
        }

        private void ApplyOrbScale()
        {
            Vector3 scale = Vector3.one * Mathf.Max(0.1f, orbScale);
            if (orb != null)
                orb.localScale = scale;
            if (orbitRing != null)
                orbitRing.localScale = scale;
            if (coreCannon != null)
                coreCannon.localScale = scale;
        }

        private void UpdateGameTitlePosition()
        {
            if (gameTitleRoot == null)
                return;

            bool menuLike = state == GameState.Menu;
            gameTitleRoot.gameObject.SetActive(menuLike);
            if (gameLogoRoot != null)
                gameLogoRoot.gameObject.SetActive(menuLike);
            if (!menuLike)
            {
                if (menuBestText != null)
                    menuBestText.gameObject.SetActive(false);
                return;
            }

            RectTransform canvasRect = canvas != null ? canvas.transform as RectTransform : null;
            Vector2 canvasSize = canvasRect != null ? canvasRect.rect.size : new Vector2(900f, 1600f);
            if (canvasSize.x <= 1f || canvasSize.y <= 1f)
                canvasSize = new Vector2(900f, 1600f);

            bool portrait = canvasSize.y > canvasSize.x * 1.05f;
            float logoAspect = 1672f / 697f;
            float logoWidth = portrait ? Mathf.Min(canvasSize.x * 0.78f, 740f) : Mathf.Min(canvasSize.x * 0.50f, 820f);
            float logoHeight = logoWidth / logoAspect;
            float logoX = 0f;
            float logoY = canvasSize.y * 0.5f - logoHeight * 0.5f - (portrait ? -40f : 8f);

            gameTitleRoot.anchoredPosition = new Vector2(logoX, logoY);
            if (gameLogoRoot != null)
            {
                gameLogoRoot.anchoredPosition = gameTitleRoot.anchoredPosition;
                gameLogoRoot.sizeDelta = new Vector2(logoWidth, logoHeight);
                gameLogoRoot.SetAsLastSibling();
            }
            if (menuBestText != null)
            {
                menuBestText.gameObject.SetActive(true);
                menuBestText.text = LF("menu.best", bestScore);
                menuBestText.rectTransform.anchoredPosition = gameTitleRoot.anchoredPosition + new Vector2(0f, -logoHeight * 0.52f - 28f);
            }
        }

        private void UpdateMenuPresentation()
        {
            if (tutorialBreakoutDroneCinematicActive)
            {
                if (menuBestText != null)
                    menuBestText.gameObject.SetActive(false);
                UpdateMenuDroneGhosts();
                return;
            }

            bool menuLike = IsMenuLikeState();
            if (!IsTutorialCompleted() && menuLike)
            {
                if (menuHangarOpen)
                    UpdateMenuHangarDisplay();
                else
                    ApplyPrimaryTutorialMenuState();
                UpdateMenuDroneGhosts();
                return;
            }

            if (transitioningToGame)
            {
                if (menuBestText != null)
                    menuBestText.gameObject.SetActive(false);
                UpdateMenuDroneGhosts();
                return;
            }

            if (!menuLike)
            {
                if (menuBestText != null)
                    menuBestText.gameObject.SetActive(false);
                CleanupMenuDroneGhosts();
                return;
            }

            if (state != GameState.Menu && state != GameState.ModeSelect && state != GameState.StoryLevels && menuBestText != null)
                menuBestText.gameObject.SetActive(false);

            UpdateMenuScene();
            if (menuHangarOpen)
                UpdateMenuHangarDisplay();
            else
                UpdateMenuOzCoreMiner();
            UpdateMenuDroneGhosts();
        }

        private void UpdateMenuOzCoreMiner()
        {
            bool activeMenu = (state == GameState.Menu || state == GameState.ModeSelect || state == GameState.StoryLevels) && !menuHangarOpen;
            if (ozCoreMinerDrone == null)
                return;

            if (!activeMenu || !ozCoreMinerOwned || !IsTutorialCompleted())
            {
                ozCoreMinerDrone.gameObject.SetActive(false);
                return;
            }

            double now = GetUtcNowSeconds();
            if (ozCoreMinerOnMission && ozCoreMinerReturnAtUtc > 0.0 && now >= ozCoreMinerReturnAtUtc)
            {
                ozCoreMinerOnMission = false;
                ozCoreMinerReturning = false;
                ozCoreMinerCargoReady = true;
                if (statusText != null)
                    statusText.text = "CORE MINER READY - CLICK TO COLLECT";
                RefreshUpgradeLabels();
            }

            if (ozCoreMinerCargoReady)
            {
                ozCoreMinerDrone.gameObject.SetActive(true);
                Vector2 buttonAnchor = GetOzCoreMinerButtonAnchor();
                Vector2 readyTarget = buttonAnchor + new Vector2(112f, 22f + Mathf.Sin(Time.unscaledTime * 4.2f) * 9f);
                Vector2 previousReady = ozCoreMinerPosition;
                if (ozCoreMinerPosition == Vector2.zero)
                    ozCoreMinerPosition = readyTarget;
                ozCoreMinerPosition = Vector2.Lerp(ozCoreMinerPosition, readyTarget, 1f - Mathf.Exp(-6.4f * Time.unscaledDeltaTime));
                ozCoreMinerDrone.anchoredPosition = ozCoreMinerPosition;
                float pulse = 1f + Mathf.Sin(Time.unscaledTime * 7.2f) * 0.075f;
                ozCoreMinerDrone.localScale = Vector3.one * pulse;
                FaceOzCoreMinerToward(ozCoreMinerDrone, previousReady, buttonAnchor, Mathf.Sin(Time.unscaledTime * 14f) * 2f);
                ozCoreMinerDrone.SetAsLastSibling();
                HandleMenuOzCoreMinerClick();
                RefreshOzCoreMinerSendLabel();
                return;
            }

            if (ozCoreMinerOnMission)
            {
                if (ozCoreMinerReturning)
                {
                    ozCoreMinerDrone.gameObject.SetActive(true);
                    ozCoreMinerExitTimer += Time.unscaledDeltaTime;
                    Vector2 previousPosition = ozCoreMinerPosition;
                    if (ozCoreMinerExitTimer < OzCoreMinerExitTurnSeconds)
                    {
                        float turnP = Mathf.Clamp01(ozCoreMinerExitTimer / OzCoreMinerExitTurnSeconds);
                        ozCoreMinerPosition = ozCoreMinerExitStart + ozCoreMinerExitDirection * (Mathf.Sin(turnP * Mathf.PI) * 8f);
                        FaceOzCoreMinerToward(ozCoreMinerDrone, ozCoreMinerPosition, ozCoreMinerPosition + ozCoreMinerExitDirection * 120f, Mathf.Sin(Time.unscaledTime * 18f) * 2.5f, 11f);
                    }
                    else
                    {
                        float p = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01((ozCoreMinerExitTimer - OzCoreMinerExitTurnSeconds) / OzCoreMinerExitFlySeconds));
                        ozCoreMinerPosition = Vector2.Lerp(ozCoreMinerExitStart, ozCoreMinerExitTarget, p);
                        FaceOzCoreMinerToward(ozCoreMinerDrone, previousPosition, ozCoreMinerPosition + ozCoreMinerExitDirection * 90f, Mathf.Sin(Time.unscaledTime * 16f) * 2f, 9f);
                        if (p >= 1f)
                        {
                            ozCoreMinerReturning = false;
                            ozCoreMinerDrone.gameObject.SetActive(false);
                        }
                    }
                    ozCoreMinerDrone.anchoredPosition = ozCoreMinerPosition;
                    float flightP = Mathf.Clamp01((ozCoreMinerExitTimer - OzCoreMinerExitTurnSeconds) / OzCoreMinerExitFlySeconds);
                    ozCoreMinerDrone.localScale = Vector3.one * Mathf.Lerp(1f, 0.78f, flightP);
                }
                else
                {
                    ozCoreMinerDrone.gameObject.SetActive(false);
                }

                RefreshOzCoreMinerSendLabel();
                return;
            }

            ozCoreMinerDrone.gameObject.SetActive(true);
            ozCoreMinerOrbitPhase += Time.unscaledDeltaTime * 0.92f;
            Vector2 buttonCenter = GetOzCoreMinerButtonAnchor();
            float sweep = Mathf.Sin(ozCoreMinerOrbitPhase * 1.45f);
            float knockPulse = Mathf.Pow(Mathf.Max(0f, Mathf.Sin(ozCoreMinerOrbitPhase * 2.15f)), 8f);
            Vector2 sideCenter = buttonCenter + new Vector2(sweep * 196f, 132f - knockPulse * 18f);
            Vector2 orbit = new Vector2(Mathf.Sin(ozCoreMinerOrbitPhase * 2.90f) * 12f, Mathf.Cos(ozCoreMinerOrbitPhase * 1.80f) * 10f);
            Vector2 previous = ozCoreMinerPosition;
            Vector2 target = sideCenter + orbit;
            if (ozCoreMinerPosition == Vector2.zero)
                ozCoreMinerPosition = target;
            ozCoreMinerPosition = Vector2.Lerp(ozCoreMinerPosition, target, 1f - Mathf.Exp(-5.2f * Time.unscaledDeltaTime));
            ozCoreMinerDrone.anchoredPosition = ozCoreMinerPosition;
            ozCoreMinerDrone.localScale = Vector3.one * (1f + knockPulse * 0.035f);
            Vector2 faceTarget = knockPulse > 0.18f ? buttonCenter : target;
            FaceOzCoreMinerToward(ozCoreMinerDrone, previous, faceTarget, Mathf.Sin(Time.unscaledTime * 8f) * 2.5f);
            ozCoreMinerDrone.SetAsLastSibling();
            HandleMenuOzCoreMinerClick();
            RefreshOzCoreMinerSendLabel();
        }

        private Vector2 GetOzCoreMinerButtonAnchor()
        {
            RectTransform buttonRoot = ozCoreMinerSendText != null ? ozCoreMinerSendText.transform.parent as RectTransform : null;
            RectTransform parent = buttonRoot != null ? buttonRoot.parent as RectTransform : null;
            if (buttonRoot == null || parent == null)
                return new Vector2(laneX, orbY - 230f);

            Vector2 anchorCenter = (buttonRoot.anchorMin + buttonRoot.anchorMax) * 0.5f;
            Vector2 parentPivot = parent.pivot;
            return new Vector2(
                (anchorCenter.x - parentPivot.x) * parent.rect.width + buttonRoot.anchoredPosition.x,
                (anchorCenter.y - parentPivot.y) * parent.rect.height + buttonRoot.anchoredPosition.y);
        }

        private Vector2 GetRandomOzCoreMinerExitTarget(RectTransform root)
        {
            float width = root != null ? root.rect.width : 900f;
            float height = root != null ? root.rect.height : 1600f;
            float halfWidth = width * 0.5f;
            float halfHeight = height * 0.5f;
            float margin = 190f;
            int edge = random.Next(0, 4);

            switch (edge)
            {
                case 0:
                    return new Vector2(-halfWidth - margin, RandomRange(-halfHeight * 0.28f, halfHeight * 0.42f));
                case 1:
                    return new Vector2(halfWidth + margin, RandomRange(-halfHeight * 0.28f, halfHeight * 0.42f));
                case 2:
                    return new Vector2(RandomRange(-halfWidth * 0.42f, halfWidth * 0.42f), halfHeight + margin);
                default:
                    return new Vector2(RandomRange(-halfWidth * 0.34f, halfWidth * 0.34f), -halfHeight - margin);
            }
        }

        private void HandleMenuOzCoreMinerClick()
        {
            bool pressed;
            bool held;
            bool released;
            Vector2 pointerPosition;
            float keyboard;
            ReadGameplayInput(out pressed, out held, out released, out pointerPosition, out keyboard);
            if (!pressed || IsPointerOverButton(pointerPosition) || !IsPointerOverDrone(pointerPosition, ozCoreMinerDrone))
                return;

            if (ozCoreMinerCargoReady)
            {
                ClaimOzCoreMinerCargo();
                return;
            }

            if (ozCoreMinerOwned && !ozCoreMinerOnMission)
                SendOzCoreMiner();
        }

        private void UpdateMenuHangarDisplay()
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return;

            HideCraftProgress();
            UpdateCrafterCraftSound(false);
            UpdateGeneratorShieldChargeSound(false);
            if (shieldDroneLaser != null)
                shieldDroneLaser.gameObject.SetActive(false);
            if (collectorBeam != null)
                collectorBeam.gameObject.SetActive(false);

            if (tutorialRepairHangarLessonActive)
            {
                UpdateTutorialRepairHangarScene(root);
                return;
            }

            if (hangarRecoveryActive)
            {
                UpdateHangarRecoveryScene(root);
                return;
            }

            SetHangarRecoveryBarVisible(false);

            PlaceMenuHangarDrone(DroneUpgradeTarget.Crafter, crafterDrone, crafterOwned, CrafterDroneSpriteResourcePath, ResolveMenuHangarParkingPosition(0, root), 1.34f, ref crafterPosition);
            PlaceMenuHangarDrone(DroneUpgradeTarget.Generator, generatorDrone, generatorOwned, GeneratorDroneSpriteResourcePath, ResolveMenuHangarParkingPosition(1, root), 1.22f, ref generatorPosition);
            PlaceMenuHangarDrone(DroneUpgradeTarget.Repair, repairDrone, repairOwned, RepairDroneSpriteResourcePath, ResolveMenuHangarParkingPosition(2, root), 1.20f, ref repairPosition);
            PlaceMenuHangarDrone(DroneUpgradeTarget.Shield, shieldDrone, shieldDroneOwned, ShieldDroneSpriteResourcePath, ResolveMenuHangarParkingPosition(4, root), 1.18f, ref shieldDronePosition);
            PlaceMenuHangarDrone(DroneUpgradeTarget.Collector, collectorDrone, collectorDroneOwned, CollectorDroneSpriteResourcePath, ResolveMenuHangarParkingPosition(3, root), 1.16f, ref collectorDronePosition);
            PlaceMenuHangarDrone(DroneUpgradeTarget.MineLayer, mineLayerDrone, mineLayerDroneOwned, MineLayerDroneSpriteResourcePath, ResolveMenuHangarParkingPosition(6, root), 1.06f, ref mineLayerDronePosition);
            PlaceMenuHangarDrone(DroneUpgradeTarget.OzCoreMiner, ozCoreMinerDrone, ozCoreMinerOwned, OzCoreMinerDroneSpriteResourcePath, ResolveMenuHangarParkingPosition(5, root), 0.92f, ref ozCoreMinerPosition);
            PlaceMenuHangarDrone(DroneUpgradeTarget.Hive, hiveDrone, hiveDroneOwned, HiveDroneSpriteResourcePath, ResolveMenuHangarParkingPosition(7, root), 1.02f, ref hiveDronePosition);
            PlaceMenuHangarDrone(DroneUpgradeTarget.Gladiator, gladiatorDrone, gladiatorDroneOwned, GladiatorDroneSpriteResourcePath, ResolveMenuHangarParkingPosition(8, root), 1.00f, ref gladiatorDronePosition);
            PlaceMenuHangarDrone(DroneUpgradeTarget.Horizon, horizonDrone, horizonDroneOwned, HorizonDroneSpriteResourcePath, ResolveMenuHangarParkingPosition(9, root), 1.00f, ref horizonDronePosition);
            PlaceMenuHangarDrone(DroneUpgradeTarget.Tamer, tamerDrone, tamerDroneOwned, TamerDroneSpriteResourcePath, ResolveMenuHangarParkingPosition(10, root), 0.94f, ref tamerDronePosition);
            PlaceMenuHangarDrone(DroneUpgradeTarget.Queen, queenDrone, queenDroneOwned, QueenDroneSpriteResourcePath, ResolveMenuHangarParkingPosition(11, root), 0.90f, ref queenDronePosition);
            PlaceMenuHangarDrone(DroneUpgradeTarget.Mimic, mimicDrone, mimicDroneOwned, MimicDroneSpriteResourcePath, ResolveMenuHangarParkingPosition(12, root), 0.88f, ref mimicDronePosition);
            PlaceMenuHangarDrone(DroneUpgradeTarget.Sniper, sniperDrone, sniperDroneOwned, SniperDroneSpriteResourcePath, ResolveMenuHangarParkingPosition(13, root), 0.88f, ref sniperDronePosition);

            if (!CanShowMenuHangarUpgradeButtons())
            {
                HideMenuHangarUpgradeButtons();
                return;
            }

            for (int i = 0; i < 4; i++)
            {
                if (menuHangarUpgradeButtons[i] != null)
                    menuHangarUpgradeButtons[i].gameObject.SetActive(false);
            }
            UpdateMenuHangarUpgradeButton(4, crafterOwned, crafterPosition, "CRAFTER");
            UpdateMenuHangarUpgradeButton(5, generatorOwned, generatorPosition, "GENERATOR");
            UpdateMenuHangarUpgradeButton(6, repairOwned, repairPosition, "REPAIR");
            UpdateMenuHangarUpgradeButton(7, shieldDroneOwned, shieldDronePosition, "SHIELD");
            UpdateMenuHangarUpgradeButton(8, collectorDroneOwned, collectorDronePosition, "COLLECTOR");
            UpdateMenuHangarUpgradeButton(9, ozCoreMinerOwned, ozCoreMinerPosition, "MINER");
            UpdateMenuHangarUpgradeButton(10, hiveDroneOwned, hiveDronePosition, "HIVE");
            UpdateMenuHangarUpgradeButton(11, gladiatorDroneOwned, gladiatorDronePosition, "GLADIATOR");
            UpdateMenuHangarUpgradeButton(12, horizonDroneOwned, horizonDronePosition, "HORIZON");
            UpdateMenuHangarUpgradeButton(13, tamerDroneOwned, tamerDronePosition, "TAMER");
        }

        private void HandleMenuHangarDroneUpgradeInput()
        {
            if (storageDepotWindowRoot != null && storageDepotWindowRoot.gameObject.activeSelf)
                return;

            if (!ShouldUseMenuHangarDroneUpgradePad() || (!HasVisibleDroneUpgradePadAccess() && !HasVisibleCoreForgeModuleUpgradeAccess()))
            {
                ClearMenuHangarDroneDragState();
                return;
            }

            if (droneUpgradePadDocking
                || coreForgeModuleDocking
                || (droneUpgradeRoot != null && droneUpgradeRoot.gameObject.activeSelf)
                || (coreForgeModuleRoot != null && coreForgeModuleRoot.gameObject.activeSelf)
                || (upgradeRoot != null && upgradeRoot.gameObject.activeSelf))
                return;

            bool pressed;
            bool held;
            bool released;
            Vector2 pointerPosition;
            float keyboard;
            ReadGameplayInput(out pressed, out held, out released, out pointerPosition, out keyboard);

            if (pressed)
            {
                if (IsPointerOverButton(pointerPosition))
                {
                    ClearMenuHangarDroneDragState();
                    return;
                }

                menuHangarDraggedUpgradeTarget = ResolveMenuHangarDraggedUpgradeTarget(pointerPosition);
                if (menuHangarDraggedUpgradeTarget != DroneUpgradeTarget.None)
                    menuHangarCommandStates.Remove(menuHangarDraggedUpgradeTarget);
                crafterDragging = menuHangarDraggedUpgradeTarget == DroneUpgradeTarget.Crafter;
                generatorDragging = menuHangarDraggedUpgradeTarget == DroneUpgradeTarget.Generator;
                repairDragging = menuHangarDraggedUpgradeTarget == DroneUpgradeTarget.Repair;
                shieldDroneDragging = menuHangarDraggedUpgradeTarget == DroneUpgradeTarget.Shield;
                collectorDroneDragging = menuHangarDraggedUpgradeTarget == DroneUpgradeTarget.Collector;
            }

            bool draggingDrone = menuHangarDraggedUpgradeTarget != DroneUpgradeTarget.None;
            if (!draggingDrone)
                return;

            if (held && TryScreenPointToWorldLocalPoint(pointerPosition, out Vector2 localPoint))
                UpdateMenuHangarDroneCommand(localPoint);

            if (released || !held)
            {
                TryResolveMenuHangarDroneCommand(pointerPosition);
                ClearMenuHangarDroneDragState();
            }
        }

        private void UpdateMenuHangarDroneCommand(Vector2 localPoint)
        {
            DroneUpgradeTarget target = menuHangarDraggedUpgradeTarget;
            if (target == DroneUpgradeTarget.None)
                return;

            Vector2 commandPosition = ResolveMenuHangarCommandPosition(localPoint);
            RectTransform drone = GetDroneUpgradeTargetRect(target);
            Vector2 dronePosition = GetDroneUpgradeTargetPosition(target);
            droneCommandPosition = commandPosition;
            droneCommandActive = true;
            UpdateDroneCommandVisuals(dronePosition, commandPosition, target);
            FaceCommandedDroneToward(target, drone, dronePosition, commandPosition);
        }

        private Vector2 ResolveMenuHangarCommandPosition(Vector2 localPoint)
        {
            droneCommandMagnetToUpgradePad = false;
            droneCommandMagnetToCoreForge = false;

            if (menuHangarDraggedUpgradeTarget == DroneUpgradeTarget.Crafter && HasVisibleCoreForgeModuleUpgradeAccess())
            {
                Vector2 forgePosition = ResolveCoreForgeWorldPosition();
                float forgeRadius = ResolveCoreForgeCommandRadius();
                if (Vector2.Distance(localPoint, forgePosition) <= forgeRadius)
                {
                    droneCommandMagnetToCoreForge = true;
                    return forgePosition;
                }
            }

            if (HasVisibleDroneUpgradePadAccess() && droneUpgradePad != null && droneUpgradePad.gameObject.activeSelf)
            {
                Vector2 padPosition = ResolveDroneUpgradePadWorldPosition();
                float radius = Mathf.Max(DroneUpgradePadDropRadius, Mathf.Min(droneUpgradePad.rect.width, droneUpgradePad.rect.height) * 0.48f);
                if (Vector2.Distance(localPoint, padPosition) <= radius)
                {
                    droneCommandMagnetToUpgradePad = true;
                    return padPosition;
                }
            }

            return localPoint;
        }

        private void TryResolveMenuHangarDroneCommand(Vector2 pointerPosition)
        {
            DroneUpgradeTarget target = menuHangarDraggedUpgradeTarget;
            if (target == DroneUpgradeTarget.None)
                return;

            bool commandOnPad = droneCommandActive && droneCommandMagnetToUpgradePad;
            bool commandOnForge = droneCommandActive && droneCommandMagnetToCoreForge;
            if (!droneCommandActive && TryScreenPointToWorldLocalPoint(pointerPosition, out Vector2 releasePoint))
            {
                Vector2 commandPosition = ResolveMenuHangarCommandPosition(releasePoint);
                droneCommandPosition = commandPosition;
                commandOnPad = droneCommandMagnetToUpgradePad;
                commandOnForge = droneCommandMagnetToCoreForge;
            }

            if (commandOnForge && target == DroneUpgradeTarget.Crafter)
            {
                StartCoreForgeModuleDocking();
                if (statusText != null)
                    statusText.text = L("status.core_forge_modules");
                return;
            }

            if (commandOnPad)
            {
                StartDroneUpgradePadDocking(target);
                if (statusText != null)
                    statusText.text = LF("status.drone_on_upgrade_pad", DroneUpgradeTargetName(target));
                return;
            }

            if (droneCommandActive)
                StartMenuHangarCommandMove(target, droneCommandPosition);
        }

        private void StartMenuHangarCommandMove(DroneUpgradeTarget target, Vector2 commandPosition)
        {
            if (target == DroneUpgradeTarget.None)
                return;

            Vector2 from = GetDroneUpgradeTargetPosition(target);
            bool hasWaypoint = TryResolveMenuHangarAvoidanceWaypoint(from, commandPosition, out Vector2 waypoint);
            menuHangarCommandStates[target] = new MenuHangarDroneCommandState
            {
                Target = commandPosition,
                Waypoint = waypoint,
                HasWaypoint = hasWaypoint,
                Returning = false,
                HoldTimer = 0f
            };
            HideMenuHangarUpgradeButtons();
            SetDroneUpgradeTargetVisualOnTop(target);
        }

        private void StartMenuHangarReturnToParking(DroneUpgradeTarget target)
        {
            if (target == DroneUpgradeTarget.None)
                return;

            Vector2 targetPosition = ResolveMenuHangarParkingPosition(target);
            Vector2 from = GetDroneUpgradeTargetPosition(target);
            bool hasWaypoint = TryResolveMenuHangarAvoidanceWaypoint(from, targetPosition, out Vector2 waypoint);
            menuHangarCommandStates[target] = new MenuHangarDroneCommandState
            {
                Target = targetPosition,
                Waypoint = waypoint,
                HasWaypoint = hasWaypoint,
                Returning = true,
                HoldTimer = 0f
            };
            HideMenuHangarUpgradeButtons();
            SetDroneUpgradeTargetVisualOnTop(target);
        }

        private void UpdateMenuHangarDroneCommands()
        {
            if (menuHangarCommandStates.Count == 0)
                return;

            List<DroneUpgradeTarget> targets = new List<DroneUpgradeTarget>(menuHangarCommandStates.Keys);
            for (int i = 0; i < targets.Count; i++)
            {
                DroneUpgradeTarget target = targets[i];
                if (!menuHangarCommandStates.TryGetValue(target, out MenuHangarDroneCommandState command))
                    continue;
                if (target == menuHangarDraggedUpgradeTarget)
                    continue;

                RectTransform drone = GetDroneUpgradeTargetRect(target);
                if (drone == null)
                {
                    menuHangarCommandStates.Remove(target);
                    continue;
                }

                if (command.Returning)
                {
                    command.Target = ResolveMenuHangarParkingPosition(target);
                    if (!command.HasWaypoint && TryResolveMenuHangarAvoidanceWaypoint(GetDroneUpgradeTargetPosition(target), command.Target, out Vector2 returnWaypoint))
                    {
                        command.Waypoint = returnWaypoint;
                        command.HasWaypoint = true;
                    }
                }

                Vector2 moveTarget = command.HasWaypoint ? command.Waypoint : command.Target;
                MoveMenuHangarDraggedDroneToCommand(target, moveTarget);
                if (Vector2.Distance(GetDroneUpgradeTargetPosition(target), moveTarget) <= 0.75f)
                {
                    SetDroneUpgradeTargetPosition(target, moveTarget);
                    drone.anchoredPosition = moveTarget;
                    if (command.HasWaypoint)
                    {
                        command.HasWaypoint = false;
                        command.HoldTimer = 0f;
                        menuHangarCommandStates[target] = command;
                    }
                    else if (command.Returning)
                    {
                        menuHangarCommandStates.Remove(target);
                    }
                    else
                    {
                        command.HoldTimer += Time.unscaledDeltaTime;
                        if (command.HoldTimer >= 0.75f)
                        {
                            command.Returning = true;
                            command.HoldTimer = 0f;
                            command.Target = ResolveMenuHangarParkingPosition(target);
                        }

                        menuHangarCommandStates[target] = command;
                    }
                }
                else
                {
                    menuHangarCommandStates[target] = command;
                }
            }
        }

        private bool TryResolveMenuHangarAvoidanceWaypoint(Vector2 from, Vector2 to, out Vector2 waypoint)
        {
            waypoint = Vector2.zero;
            float bestExtraDistance = float.PositiveInfinity;
            bool found = false;

            if (TryResolveObstacleAvoidanceWaypoint(from, to, coreForge, ResolveCoreForgeWorldPosition(), out Vector2 forgeWaypoint, out float forgeExtra))
            {
                waypoint = forgeWaypoint;
                bestExtraDistance = forgeExtra;
                found = true;
            }

            if (TryResolveObstacleAvoidanceWaypoint(from, to, droneUpgradePad, ResolveDroneUpgradePadWorldPosition(), out Vector2 padWaypoint, out float padExtra) && padExtra < bestExtraDistance)
            {
                waypoint = padWaypoint;
                found = true;
            }

            return found;
        }

        private bool TryResolveObstacleAvoidanceWaypoint(Vector2 from, Vector2 to, RectTransform obstacle, Vector2 center, out Vector2 waypoint, out float extraDistance)
        {
            waypoint = Vector2.zero;
            extraDistance = 0f;
            if (obstacle == null || !obstacle.gameObject.activeInHierarchy)
                return false;

            float radius = Mathf.Max(88f, Mathf.Min(obstacle.rect.width, obstacle.rect.height) * 0.62f);
            float safeRadius = radius + 46f;
            if (Vector2.Distance(from, center) <= safeRadius || Vector2.Distance(to, center) <= safeRadius)
                return false;

            if (DistancePointToSegment(center, from, to) > safeRadius)
                return false;

            Vector2 direction = to - from;
            if (direction.sqrMagnitude < 0.01f)
                return false;

            direction.Normalize();
            Vector2 perpendicular = new Vector2(-direction.y, direction.x);
            Vector2 candidateA = center + perpendicular * safeRadius;
            Vector2 candidateB = center - perpendicular * safeRadius;
            float distanceA = Vector2.Distance(from, candidateA) + Vector2.Distance(candidateA, to);
            float distanceB = Vector2.Distance(from, candidateB) + Vector2.Distance(candidateB, to);
            waypoint = distanceA <= distanceB ? candidateA : candidateB;
            extraDistance = Mathf.Min(distanceA, distanceB) - Vector2.Distance(from, to);
            return true;
        }

        private static float DistancePointToSegment(Vector2 point, Vector2 a, Vector2 b)
        {
            Vector2 segment = b - a;
            float lengthSq = segment.sqrMagnitude;
            if (lengthSq < 0.0001f)
                return Vector2.Distance(point, a);

            float t = Mathf.Clamp01(Vector2.Dot(point - a, segment) / lengthSq);
            return Vector2.Distance(point, a + segment * t);
        }

        private void MoveMenuHangarDraggedDroneToCommand(DroneUpgradeTarget target, Vector2 commandPosition)
        {
            RectTransform drone = GetDroneUpgradeTargetRect(target);
            if (drone == null)
                return;

            Vector2 from = GetDroneUpgradeTargetPosition(target);
            float speed = ResolveDroneCommandMoveSpeed(target, true);
            Vector2 next = Vector2.MoveTowards(from, commandPosition, speed * Time.unscaledDeltaTime);
            SetDroneUpgradeTargetPosition(target, next);
            drone.anchoredPosition = next;
            drone.localScale = Vector3.one * ResolveMenuHangarDroneScale(target);
            Vector2 faceTarget = (next - from).sqrMagnitude > 0.08f ? next : commandPosition;
            FaceCommandedDroneToward(target, drone, from, faceTarget);
            drone.SetAsLastSibling();
        }

        private Vector2 ResolveMenuHangarParkingPosition(DroneUpgradeTarget target)
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return GetDroneUpgradeTargetPosition(target);

            switch (target)
            {
                case DroneUpgradeTarget.Crafter:
                    return ResolveMenuHangarParkingPosition(0, root);
                case DroneUpgradeTarget.Generator:
                    return ResolveMenuHangarParkingPosition(1, root);
                case DroneUpgradeTarget.Repair:
                    return ResolveMenuHangarParkingPosition(2, root);
                case DroneUpgradeTarget.Collector:
                    return ResolveMenuHangarParkingPosition(3, root);
                case DroneUpgradeTarget.Shield:
                    return ResolveMenuHangarParkingPosition(4, root);
                case DroneUpgradeTarget.OzCoreMiner:
                    return ResolveMenuHangarParkingPosition(5, root);
                case DroneUpgradeTarget.MineLayer:
                    return ResolveMenuHangarParkingPosition(6, root);
                case DroneUpgradeTarget.Hive:
                    return ResolveMenuHangarParkingPosition(7, root);
                case DroneUpgradeTarget.Gladiator:
                    return ResolveMenuHangarParkingPosition(8, root);
                case DroneUpgradeTarget.Horizon:
                    return ResolveMenuHangarParkingPosition(9, root);
                case DroneUpgradeTarget.Tamer:
                    return ResolveMenuHangarParkingPosition(10, root);
                case DroneUpgradeTarget.Queen:
                    return ResolveMenuHangarParkingPosition(11, root);
                case DroneUpgradeTarget.Mimic:
                    return ResolveMenuHangarParkingPosition(12, root);
                case DroneUpgradeTarget.Sniper:
                    return ResolveMenuHangarParkingPosition(13, root);
                default:
                    return GetDroneUpgradeTargetPosition(target);
            }
        }

        private void ClearMenuHangarDroneDragState()
        {
            menuHangarDraggedUpgradeTarget = DroneUpgradeTarget.None;
            droneCommandActive = false;
            droneCommandMagnetToUpgradePad = false;
            droneCommandMagnetToCoreForge = false;
            crafterDragging = false;
            generatorDragging = false;
            repairDragging = false;
            shieldDroneDragging = false;
            collectorDroneDragging = false;
            queenDroneDragging = false;
            mimicDroneDragging = false;
            sniperDroneDragging = false;
            HideDroneCommandVisuals();
        }

        private bool CanShowMenuHangarUpgradeButtons()
        {
            return IsTutorialCompleted()
                && state == GameState.Menu
                && menuHangarOpen
                && !hangarRecoveryActive
                && !tutorialRepairHangarLessonActive
                && !storyCinematicActive
                && !transitioningToGame
                && menuHangarProfileRoot != null
                && !menuHangarProfileRoot.gameObject.activeSelf;
        }

        private void HideMenuHangarUpgradeButtons()
        {
            for (int i = 0; i < menuHangarUpgradeButtons.Length; i++)
            {
                if (menuHangarUpgradeButtons[i] != null)
                    menuHangarUpgradeButtons[i].gameObject.SetActive(false);
            }
        }

        private void UpdateHangarRecoveryScene(RectTransform root)
        {
            HideMenuHangarUpgradeButtons();
            if (menuHangarProfileRoot != null)
                menuHangarProfileRoot.gameObject.SetActive(false);

            HideDroneForRecovery(generatorDrone);
            if (!tutorialRepairHangarLessonActive)
                HideDroneForRecovery(repairDrone);
            HideDroneForRecovery(shieldDrone);
            HideDroneForRecovery(collectorDrone);
            HideDroneForRecovery(ozCoreMinerDrone);
            HideDroneForRecovery(hiveDrone);
            HideDroneForRecovery(gladiatorDrone);
            HideDroneForRecovery(horizonDrone);
            HideDroneForRecovery(tamerDrone);

            Vector2 center = ResolveHangarRecoveryOrbPosition();
            hangarRecoveryTimer += Time.unscaledDeltaTime;
            float rebuildSeconds = tutorialRepairHangarLessonActive ? 8.0f : HangarRecoveryRebuildSeconds;
            float progress = Mathf.Clamp01(hangarRecoveryTimer / rebuildSeconds);
            hangarRecoveryCrafterOrbit += Time.unscaledDeltaTime * Mathf.Lerp(2.6f, 1.35f, progress);
            UpdateHangarRecoveryBar(progress);

            if (crafterDrone != null)
            {
                crafterDrone.gameObject.SetActive(true);
                ApplySpriteFromTextureResource(crafterDrone, CrafterDroneSpriteResourcePath);
                float rx = 78f + Mathf.Sin(Time.unscaledTime * 1.9f) * 8f;
                float ry = 46f + Mathf.Cos(Time.unscaledTime * 1.3f) * 6f;
                Vector2 orbit = new Vector2(Mathf.Cos(hangarRecoveryCrafterOrbit) * rx, Mathf.Sin(hangarRecoveryCrafterOrbit) * ry);
                Vector2 target = center + orbit;
                if (crafterPosition == Vector2.zero)
                    crafterPosition = target;
                crafterPosition = Vector2.Lerp(crafterPosition, target, 1f - Mathf.Exp(-7.8f * Time.unscaledDeltaTime));
                crafterDrone.anchoredPosition = crafterPosition;
                crafterDrone.localScale = Vector3.one * 1.22f;
                FaceDroneToward(crafterDrone, crafterPosition, center, Mathf.Sin(Time.unscaledTime * 12f) * 3.5f);
                crafterDrone.SetAsLastSibling();
            }

            if (tutorialRepairHangarLessonActive && repairDrone != null)
            {
                repairDrone.gameObject.SetActive(true);
                ApplySpriteFromTextureResource(repairDrone, RepairDroneSpriteResourcePath);
                float repairAngle = -hangarRecoveryCrafterOrbit * 1.18f + Mathf.PI;
                Vector2 repairOrbit = new Vector2(Mathf.Cos(repairAngle) * 96f, Mathf.Sin(repairAngle) * 54f);
                Vector2 repairTarget = center + repairOrbit + new Vector2(0f, -22f);
                if (repairPosition == Vector2.zero)
                    repairPosition = repairTarget;
                Vector2 previous = repairPosition;
                repairPosition = Vector2.Lerp(repairPosition, repairTarget, 1f - Mathf.Exp(-8.4f * Time.unscaledDeltaTime));
                repairDrone.anchoredPosition = repairPosition;
                repairDrone.localScale = Vector3.one * 1.18f;
                FaceDroneToward(repairDrone, previous, center, Mathf.Sin(Time.unscaledTime * 18f) * 4f);
                UpdateWeldSparks(true, repairPosition, center + new Vector2(0f, -44f));
                repairDrone.SetAsLastSibling();
            }

            UpdateHangarRecoveryPad(center, progress);
            UpdateHangarRecoveryBeams(center, progress);
            UpdateHangarRecoverySparks(center, progress);
            UpdateOrbDamageCracks(progress);
            orbRepairFlashTimer = Mathf.Max(orbRepairFlashTimer, 0.25f);

            SetSharedHealthRatio(Mathf.Lerp(tutorialRepairHangarLessonActive ? 0.42f : 0.18f, 1f, progress));
            if (progress >= 1f)
            {
                SetSharedHealthFull();
                if (statusText != null)
                    statusText.text = tutorialRepairHangarLessonActive ? "REPAIR DRONE ONLINE - BASE RESTORED" : "ORB REBUILT";
                tutorialRepairHangarLessonActive = false;
                if (!hangarRecoveryReturningToMenu)
                {
                    hangarRecoveryReturningToMenu = true;
                    if (hangarRecoveryReturnRoutine != null)
                        StopCoroutine(hangarRecoveryReturnRoutine);
                    hangarRecoveryReturnRoutine = StartCoroutine(ReturnToMenuAfterHangarRecoveryRoutine());
                }
            }
            else if (statusText != null)
            {
                statusText.text = tutorialRepairHangarLessonActive
                    ? "REPAIR DRONE RESTORES BASE " + Mathf.RoundToInt(progress * 100f) + "%"
                    : "CRAFTER REBUILDS ORB " + Mathf.RoundToInt(progress * 100f) + "%";
            }
        }

        private void UpdateTutorialRepairHangarScene(RectTransform root)
        {
            HideMenuHangarUpgradeButtons();
            if (menuHangarProfileRoot != null)
                menuHangarProfileRoot.gameObject.SetActive(false);

            SetHangarRecoveryBarVisible(false);
            HideDroneForRecovery(generatorDrone);
            HideDroneForRecovery(shieldDrone);
            HideDroneForRecovery(collectorDrone);
            HideDroneForRecovery(ozCoreMinerDrone);
            HideDroneForRecovery(hiveDrone);
            HideDroneForRecovery(gladiatorDrone);
            HideDroneForRecovery(horizonDrone);
            HideDroneForRecovery(tamerDrone);

            Vector2 center = ResolveHangarCargoBayPosition();
            hangarRecoveryTimer += Time.unscaledDeltaTime;
            const float buildSeconds = 4.2f;
            const float repairSeconds = 3.0f;
            float buildProgress = Mathf.Clamp01(hangarRecoveryTimer / buildSeconds);
            float repairProgress = Mathf.Clamp01((hangarRecoveryTimer - buildSeconds) / repairSeconds);
            hangarRecoveryCrafterOrbit += Time.unscaledDeltaTime * 2.55f;

            if (hangarRecoveryBeams != null)
            {
                for (int i = 0; i < hangarRecoveryBeams.Length; i++)
                {
                    if (hangarRecoveryBeams[i] != null)
                        hangarRecoveryBeams[i].gameObject.SetActive(false);
                }
            }
            if (hangarRecoveryPadGlow != null)
                hangarRecoveryPadGlow.gameObject.SetActive(false);
            if (hangarRecoveryPadRing != null)
                hangarRecoveryPadRing.gameObject.SetActive(false);
            if (hangarRecoveryScanLine != null)
                hangarRecoveryScanLine.gameObject.SetActive(false);
            if (hangarRecoveryProgressArc != null)
                hangarRecoveryProgressArc.gameObject.SetActive(false);
            HideOrbDamageCracks();

            if (crafterDrone != null)
            {
                crafterDrone.gameObject.SetActive(true);
                ApplySpriteFromTextureResource(crafterDrone, CrafterDroneSpriteResourcePath);
                Vector2 buildPoint = ResolveHangarDroneHomePosition(0, root) + new Vector2(0f, -42f);
                Vector2 operatorTarget = hangarRecoveryTimer < buildSeconds
                    ? buildPoint + WorkVibration(1.3f, 32f)
                    : buildPoint + new Vector2(Mathf.Sin(Time.unscaledTime * 1.1f) * 18f, Mathf.Cos(Time.unscaledTime * 1.5f) * 8f);
                if (crafterPosition == Vector2.zero)
                    crafterPosition = operatorTarget;
                Vector2 previous = crafterPosition;
                crafterPosition = Vector2.Lerp(crafterPosition, operatorTarget, 1f - Mathf.Exp(-7.2f * Time.unscaledDeltaTime));
                crafterDrone.anchoredPosition = crafterPosition;
                crafterDrone.localScale = Vector3.one * (hangarRecoveryTimer < buildSeconds ? 1.45f : 1.30f);
                FaceDroneToward(crafterDrone, previous, hangarRecoveryTimer < buildSeconds ? buildPoint + Vector2.up * 60f : center, Mathf.Sin(Time.unscaledTime * 13f) * 3.5f);
                crafterDrone.SetAsLastSibling();

                if (hangarRecoveryTimer < buildSeconds)
                {
                    ShowCraftProgress(buildProgress);
                    UpdateCrafterCraftSound(true);
                    Vector2 sparkPoint = buildPoint + new Vector2(Mathf.Sin(Time.unscaledTime * 18f) * 18f, 42f + Mathf.Cos(Time.unscaledTime * 21f) * 10f);
                    UpdateWeldSparks(true, crafterPosition, sparkPoint);
                }
                else
                {
                    HideCraftProgress();
                    UpdateCrafterCraftSound(false);
                }
            }

            Vector2[] repairPoints =
            {
                center + new Vector2(-132f, 64f),
                center + new Vector2(132f, 66f),
                center + new Vector2(-96f, -18f),
                center + new Vector2(98f, -16f),
                center + new Vector2(0f, 92f)
            };
            float repairStep = Mathf.Clamp01(repairProgress) * repairPoints.Length;
            int repairIndex = Mathf.Clamp(Mathf.FloorToInt(repairStep), 0, repairPoints.Length - 1);
            float holdPhase = Mathf.Clamp01(repairStep - repairIndex);
            Vector2 workPoint = repairPoints[repairIndex];
            Vector2 approachDirection = (center - workPoint).sqrMagnitude > 0.01f ? (center - workPoint).normalized : Vector2.down;
            Vector2 repairTarget = workPoint + approachDirection * 58f + WorkVibration(0.28f, 9f);
            bool weldingActive = repairProgress > 0f && repairProgress < 0.98f && holdPhase > 0.12f;

            if (repairDrone != null)
            {
                bool repairing = hangarRecoveryTimer >= buildSeconds;
                repairDrone.gameObject.SetActive(repairing);
                ApplySpriteFromTextureResource(repairDrone, RepairDroneSpriteResourcePath);
                if (!repairing)
                {
                    repairPosition = ResolveHangarDroneHomePosition(0, root) + new Vector2(52f, 12f);
                    if (statusText != null)
                        statusText.text = "CRAFTER BUILDS REPAIR DRONE";
                }
                else if (repairPosition == Vector2.zero)
                {
                    repairPosition = ResolveHangarDroneHomePosition(0, root) + new Vector2(52f, 12f);
                }

                if (!repairing)
                {
                    SetSharedHealthRatio(Mathf.Lerp(0.42f, 0.56f, buildProgress));
                    orbRepairFlashTimer = 0f;
                    return;
                }

                Vector2 previous = repairPosition;
                repairPosition = Vector2.Lerp(repairPosition, repairTarget, 1f - Mathf.Exp(-6.0f * Time.unscaledDeltaTime));
                repairDrone.anchoredPosition = repairPosition;
                repairDrone.localScale = Vector3.one * 1.14f;
                FaceDroneToward(repairDrone, previous, workPoint, Mathf.Sin(Time.unscaledTime * 12f) * 2.2f);
                UpdateWeldSparks(weldingActive, repairPosition, workPoint);
                repairDrone.SetAsLastSibling();
            }

            SetSharedHealthRatio(Mathf.Lerp(0.56f, 1f, repairProgress));
            orbRepairFlashTimer = 0f;
            if (statusText != null)
                statusText.text = repairProgress < 1f
                    ? "REPAIR DRONE RESTORES BASE RING"
                    : "REPAIR DRONE ONLINE - BASE RESTORED";

            if (repairProgress < 1f)
                return;

            SetSharedHealthFull();
            tutorialRepairHangarLessonActive = false;
            UpdateWeldSparks(false, Vector2.zero, Vector2.zero);
            HideCraftProgress();
            UpdateCrafterCraftSound(false);
            if (!hangarRecoveryReturningToMenu)
            {
                hangarRecoveryReturningToMenu = true;
                if (hangarRecoveryReturnRoutine != null)
                    StopCoroutine(hangarRecoveryReturnRoutine);
                hangarRecoveryReturnRoutine = StartCoroutine(TutorialBeginWeaponModulesRoutine());
            }
        }

        private IEnumerator TutorialBeginWeaponModulesRoutine()
        {
            yield return new WaitForSecondsRealtime(0.8f);
            hangarRecoveryReturnRoutine = null;
            if (upgradeRoot != null)
                upgradeRoot.gameObject.SetActive(false);
            for (int i = 0; i < menuHangarUpgradeButtons.Length; i++)
            {
                if (menuHangarUpgradeButtons[i] != null)
                    menuHangarUpgradeButtons[i].gameObject.SetActive(false);
            }
            if (menuHangarProfileRoot != null)
                menuHangarProfileRoot.gameObject.SetActive(false);
            ShowStoryDialog(L("speaker.crafter"), L("dialog.modules_intro"), L("dialog.open_modules"));
            yield return WaitStoryDialogButton();
            HideStoryDialog();

            hangarRecoveryActive = false;
            hangarRecoveryReturningToMenu = false;
            tutorialModulesTechnologyLessonActive = true;
            currentUpgradeTab = UpgradeTab.Modules;
            moduleUpgradePage = 0;
            ShowUpgrade();
            ShowModulesUpgradeTab();
            RefreshUpgradeLabels();
            if (statusText != null)
                statusText.text = "BUY ALL WEAPON MODULES - FREE";
            CheckTutorialWeaponModulesComplete();
        }

        private void CheckTutorialWeaponModulesComplete()
        {
            if (!tutorialModulesTechnologyLessonActive)
                return;
            if (!(homingMissileModuleOwned && laserModuleOwned && arcChainModuleOwned && railSpikeModuleOwned))
                return;

            tutorialModulesTechnologyLessonActive = false;
            StartCoroutine(TutorialWeaponModulesInstalledRoutine());
        }

        private IEnumerator TutorialWeaponModulesInstalledRoutine()
        {
            yield return new WaitForSecondsRealtime(0.35f);
            Time.timeScale = 1f;
            state = GameState.Menu;
            SetGameplayHudVisible(false);
            SetMenuVisible(false);
            if (upgradeRoot != null)
                upgradeRoot.gameObject.SetActive(false);
            menuHangarOpen = true;
            hangarRecoveryActive = false;
            baseHangarExpanded = true;
            baseHangarRevealTransitioning = false;
            SetHangarRevealOffset(MaxHangarRevealOffset());
            if (menuHangarRoot != null)
                menuHangarRoot.gameObject.SetActive(true);
            UpdateMenuHangarDisplay();
            if (statusText != null)
                statusText.text = "WEAPON MODULES INSTALLED";
            ShowStoryDialog(L("speaker.crafter"), L("dialog.modules_ready"), L("dialog.continue"));
            yield return WaitStoryDialogButton();
            HideStoryDialog();

            yield return new WaitForSecondsRealtime(0.45f);
            ShowStoryDialog(L("speaker.crafter"), L("dialog.defense_intro"), L("dialog.to_defense"));
            yield return WaitStoryDialogButton();
            HideStoryDialog();

            yield return TutorialBaseDefenseRoutine();
        }

        private IEnumerator TutorialBaseDefenseRoutine()
        {
            Time.timeScale = 1f;
            state = GameState.Playing;
            storyCinematicActive = false;
            tutorialBaseDefenseActive = true;
            tutorialCannonSuppressed = false;
            menuHangarOpen = false;
            hangarRecoveryActive = false;
            baseHangarExpanded = false;
            baseHangarRevealTransitioning = false;
            SetGameplayHudVisible(true);
            SetMenuVisible(false);
            if (upgradeRoot != null)
                upgradeRoot.gameObject.SetActive(false);
            if (menuHangarRoot != null)
                menuHangarRoot.gameObject.SetActive(false);

            PrepareTutorialBaseDefenseState();
            Vector2 dock = ResolveBaseShipDockPosition();
            laneX = dock.x;
            targetLaneX = dock.x;
            orbY = dock.y;
            targetOrbY = dock.y;
            baseShipDeploymentBlend = 1f;
            pointerControl = false;
            SetOrbDeploymentStage(OrbDeploymentStage.Defender);
            orbScale = ResolveActiveDockedOrbScale();
            targetOrbScale = orbScale;
            ApplyOrbScale();
            UpdateStationModules();
            coreCannonAimed = true;
            fireTimer = 0.05f;
            formationTimer = 999f;
            spawnTimer = 999f;
            specialMineTimer = 999f;
            if (statusText != null)
                statusText.text = "BASE DEFENSE - FORMATION 1/3";

            for (int wave = 0; wave < 3; wave++)
            {
                SpawnTutorialBaseDefenseFormation(wave);
                if (statusText != null)
                    statusText.text = "BASE DEFENSE - FORMATION " + (wave + 1) + "/3";

                float clearTimer = 0f;
                while (clearTimer < 0.85f)
                {
                    clearTimer = CountTutorialBaseDefenseEnemies() > 0 ? 0f : clearTimer + Time.deltaTime;
                    yield return null;
                }

                yield return new WaitForSeconds(0.95f);
            }

            tutorialBaseDefenseActive = false;
            if (statusText != null)
                statusText.text = "BASE DEFENSE COMPLETE";
            ShowStoryDialog(L("speaker.crafter"), L("dialog.defense_done"), L("dialog.continue"));
            yield return WaitStoryDialogButton();
            HideStoryDialog();

            yield return TutorialBeginShieldDroneRoutine();
        }

        private IEnumerator TutorialFirstEvolutionRoutine()
        {
            int startEvolutionLevel = CurrentStationEvolutionLevel();
            if (startEvolutionLevel >= StationMaxEvolutionLevel)
                yield break;

            while (!IsOrbAtBase())
                yield return null;

            ShowStoryDialog(L("speaker.crafter"), L("dialog.evolution_intro"), L("dialog.open_station"));
            yield return WaitStoryDialogButton();
            HideStoryDialog();

