        private IEnumerator TutorialShieldBreakoutRoutine()
        {
            baseHangarExpanded = false;
            baseHangarRevealTransitioning = false;
            SetHangarRevealOffset(0f);
            UpdateBaseTab();

            while (IsOrbDockedOnBaseShip() || IsOrbBaseTransitionLocked())
            {
                if (statusText != null)
                    statusText.text = "LAUNCH ORB FROM BASE";
                yield return null;
            }

            ShowStoryDialog(L("speaker.crafter"), L("dialog.breakout_intro"), L("dialog.breakout_button"));
            yield return WaitStoryDialogButton();
            HideStoryDialog();

            spawnTimer = 999f;
            formationTimer = 999f;
            specialMineTimer = 999f;
            SpawnTutorialBreakoutFormation();
            if (statusText != null)
                statusText.text = "BREAK THE BLOCKADE";

            float clearTimer = 0f;
            while (clearTimer < 0.90f)
            {
                clearTimer = CountTutorialBaseDefenseEnemies() > 0 ? 0f : clearTimer + Time.deltaTime;
                yield return null;
            }

            yield return TutorialBreakoutDroneFarewellRoutine();
            yield return TutorialFinalResultRoutine();
        }

        private IEnumerator TutorialBreakoutDroneFarewellRoutine()
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            float height = root != null ? root.rect.height : 1600f;
            float width = root != null ? root.rect.width : 900f;
            Vector2 focus = Vector2.zero;

            storyCinematicActive = true;
            tutorialBreakoutDroneCinematicActive = true;
            pointerControl = false;
            pointerStartedOnUi = false;
            spawnTimer = 999f;
            formationTimer = 999f;
            specialMineTimer = 999f;
            HideRuntimeDrones();
            UpdateRepairWeldingSound(false);
            UpdateCrafterCraftSound(false);
            UpdateGeneratorShieldChargeSound(false);
            CleanupMenuDroneGhosts();
            CleanupHazards();

            if (statusText != null)
                statusText.text = "BREAKOUT CLEAR";

            float settle = 0f;
            while (settle < TutorialFinalSettleSeconds)
            {
                float p = Mathf.SmoothStep(0f, 1f, settle / TutorialFinalSettleSeconds);
                targetLaneX = Mathf.Lerp(targetLaneX, focus.x, p);
                targetOrbY = Mathf.Lerp(targetOrbY, focus.y, p);
                orbScale = Mathf.Lerp(orbScale, CurrentOrbBaseScale() * 1.12f, 1f - Mathf.Exp(-2.2f * Time.deltaTime));
                targetOrbScale = orbScale;
                ApplyOrbScale();
                settle += Time.deltaTime;
                yield return null;
            }
            targetLaneX = focus.x;
            targetOrbY = focus.y;

            SpawnTutorialFarewellDroneGroup(focus, width, height);
            yield return new WaitForSecondsRealtime(TutorialFinalFarewellHoldSeconds);

            ShowStoryDialog(L("speaker.crafter"), L("dialog.complete_1"), L("dialog.listen_button"));
            yield return WaitStoryDialogButton();
            ShowStoryDialog(L("speaker.crafter"), L("dialog.complete_2"), L("dialog.next_button"));
            yield return WaitStoryDialogButton();
            ShowPlayerStoryDialog(L("dialog.complete_player"), L("dialog.next_button"));
            yield return WaitStoryDialogButton();
            ShowStoryDialog(L("speaker.crafter"), L("dialog.complete_3"), L("dialog.accept_button"));
            yield return WaitStoryDialogButton();
            HideStoryDialog();

            ReleaseTutorialFarewellDroneGroup(width, height);
            if (statusText != null)
                statusText.text = "SCOUT DRONES DEPARTING";
            yield return new WaitForSecondsRealtime(TutorialFinalDroneDepartureSeconds);
            tutorialBreakoutDroneCinematicActive = false;
            storyCinematicActive = false;
            CleanupMenuDroneGhosts();
        }

        private IEnumerator TutorialFinalResultRoutine()
        {
            storyCinematicActive = true;
            pointerControl = false;
            pointerStartedOnUi = false;
            spawnTimer = 999f;
            formationTimer = 999f;
            specialMineTimer = 999f;
            if (statusText != null)
                statusText.text = L("status.tutorial_complete");

            float t = 0f;
            Vector2 end = new Vector2(0f, ResolveGameOrbY() + 56f);
            while (t < TutorialFinalReturnToBaseSeconds)
            {
                float p = Mathf.SmoothStep(0f, 1f, t / TutorialFinalReturnToBaseSeconds);
                targetLaneX = Mathf.Lerp(targetLaneX, end.x, p);
                targetOrbY = Mathf.Lerp(targetOrbY, end.y, p);
                t += Time.deltaTime;
                yield return null;
            }

            ShowTutorialResultOverlay();
        }

