        private void SpawnTutorialBaseDefenseFormation(int waveIndex)
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return;

            float halfWidth = Mathf.Min(405f, root.rect.width * 0.5f - 62f);
            float startY = -Mathf.Min(110f, root.rect.height * 0.16f);
            float columnWidth = waveIndex == 0 ? 70f : waveIndex == 1 ? 78f : 86f;
            float row = waveIndex == 0 ? 64f : waveIndex == 1 ? 60f : 56f;
            float difficulty = 0.18f + waveIndex * 0.08f;
            float speed = 104f + waveIndex * 10f;
            float size = 82f + waveIndex * 4f;
            SpawnTutorialBaseDefenseColumn(startY, halfWidth, columnWidth, row, difficulty, speed, size, waveIndex);
        }

        private void SpawnTutorialBaseDefenseColumn(float startY, float halfWidth, float columnWidth, float row, float difficulty, float speed, float size, int waveIndex)
        {
            int rows = waveIndex == 0 ? 7 : waveIndex == 1 ? 9 : 11;

            for (int r = 0; r < rows; r++)
            {
                float y = startY + r * row;
                int laneCount = ResolveTutorialColumnLaneCount(waveIndex, r);
                for (int lane = 0; lane < laneCount; lane++)
                {
                    float x = ResolveTutorialColumnLaneX(laneCount, lane, columnWidth);
                    int type = ResolveTutorialColumnMineType(waveIndex, r, lane, laneCount);
                    SpawnTutorialBaseDefenseHazard(Mathf.Clamp(x, -halfWidth, halfWidth), y, difficulty, speed, size, type);
                }
            }
        }

        private static int ResolveTutorialColumnLaneCount(int waveIndex, int row)
        {
            if (waveIndex == 0)
            {
                int[] pattern = { 1, 2, 3, 2, 3, 2, 1 };
                return pattern[Mathf.Clamp(row, 0, pattern.Length - 1)];
            }

            if (waveIndex == 1)
            {
                int[] pattern = { 1, 3, 2, 3, 3, 2, 3, 2, 1 };
                return pattern[Mathf.Clamp(row, 0, pattern.Length - 1)];
            }

            int[] finalPattern = { 1, 3, 2, 3, 4, 3, 2, 4, 3, 2, 1 };
            return finalPattern[Mathf.Clamp(row, 0, finalPattern.Length - 1)];
        }

        private static float ResolveTutorialColumnLaneX(int laneCount, int lane, float spacing)
        {
            return (lane - (laneCount - 1) * 0.5f) * spacing;
        }

        private static int ResolveTutorialColumnMineType(int waveIndex, int row, int lane, int laneCount)
        {
            bool center = laneCount % 2 == 1 && lane == laneCount / 2;
            if (waveIndex >= 2 && center && (row == 4 || row == 7))
                return 2;
            if (waveIndex >= 1 && (center || (row + lane) % 4 == 0))
                return 1;
            if (waveIndex >= 2 && laneCount >= 4 && (lane == 0 || lane == laneCount - 1) && row % 3 == 1)
                return 3;
            return 0;
        }

        private static int ResolveTutorialPackMineType(int pattern, int index)
        {
            switch (pattern % 7)
            {
                case 1:
                    return index == 0 ? 1 : 0;
                case 2:
                    return index == 3 ? 1 : 0;
                case 3:
                    return index == 0 || index == 5 ? 1 : 0;
                case 4:
                    return index == 3 ? 2 : index % 2 == 0 ? 1 : 0;
                case 5:
                    return index == 0 ? 2 : index == 4 || index == 5 ? 3 : 1;
                case 6:
                    return index == 0 ? 3 : index % 2 == 0 ? 1 : 0;
                default:
                    return index == 0 || index == 3 ? 1 : 0;
            }
        }

        private void SpawnTutorialBaseDefenseHazard(float x, float y, float difficulty, float speed, float size, int forcedMineType)
        {
            int before = hazards.Count;
            SpawnHazard(x, false, difficulty, y, speed, size, true, forcedMineType);
            if (hazards.Count <= before)
                return;

            HazardView hazard = hazards[hazards.Count - 1];
            hazard.TutorialBaseDefenseEnemy = true;
            hazard.Health = Mathf.Max(hazard.Health, forcedMineType == 2 ? 135f : forcedMineType == 1 ? 42f : 26f);
        }

        private int CountTutorialBaseDefenseEnemies()
        {
            int count = 0;
            for (int i = 0; i < hazards.Count; i++)
            {
                HazardView hazard = hazards[i];
                if (hazard != null && hazard.TutorialBaseDefenseEnemy && hazard.Root != null)
                    count++;
            }

            return count;
        }

        private void SpawnTutorialBreakoutFormation()
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return;

            float height = root.rect.height;
            float halfWidth = Mathf.Min(360f, root.rect.width * 0.5f - 72f);
            float stationY = ResolveGameOrbY();
            float startAbsoluteY = Mathf.Clamp(stationY + 520f, height * 0.12f, height * 0.40f);
            float baseY = startAbsoluteY - height * 0.5f;

            SpawnTutorialBreakoutPack(new Vector2(0f, baseY), halfWidth, 82f, 54f, 2);
            SpawnTutorialBreakoutPack(new Vector2(-148f, baseY + 188f), halfWidth, 74f, 52f, 4);
            SpawnTutorialBreakoutPack(new Vector2(148f, baseY + 188f), halfWidth, 74f, 52f, 5);
            SpawnTutorialBreakoutPack(new Vector2(-72f, baseY + 382f), halfWidth, 86f, 56f, 6);
            SpawnTutorialBreakoutPack(new Vector2(72f, baseY + 382f), halfWidth, 86f, 56f, 3);
            SpawnTutorialBreakoutPack(new Vector2(0f, baseY + 580f), halfWidth, 92f, 58f, 5);
        }

        private void SpawnTutorialBreakoutPack(Vector2 center, float halfWidth, float spacing, float row, int pattern)
        {
            Vector2[] offsets =
            {
                new Vector2(0f, 0f),
                new Vector2(-0.70f * spacing, row), new Vector2(0.70f * spacing, row),
                new Vector2(0f, row * 2f),
                new Vector2(-1.18f * spacing, row * 3f), new Vector2(1.18f * spacing, row * 3f)
            };

            for (int i = 0; i < offsets.Length; i++)
            {
                Vector2 pos = center + offsets[i];
                pos.x = Mathf.Clamp(pos.x, -halfWidth, halfWidth);
                SpawnTutorialBreakoutHazard(pos.x, pos.y, ResolveTutorialPackMineType(pattern, i));
            }
        }

        private void SpawnTutorialBreakoutHazard(float x, float y, int forcedMineType)
        {
            int before = hazards.Count;
            SpawnHazard(x, false, 0.26f, y, 1f, forcedMineType == 2 ? 90f : 78f, true, forcedMineType);
            if (hazards.Count <= before)
                return;

            HazardView hazard = hazards[hazards.Count - 1];
            hazard.TutorialBaseDefenseEnemy = true;
            hazard.Speed = 0f;
            hazard.Velocity = Vector2.zero;
            hazard.Health = Mathf.Max(hazard.Health, forcedMineType == 2 ? 150f : forcedMineType == 1 ? 52f : 34f);
        }

