        private void UpdateHangarRecoveryPad(Vector2 center, float progress)
        {
            float pulse = 0.5f + Mathf.Sin(Time.unscaledTime * 5.8f) * 0.5f;
            if (hangarRecoveryPadGlow != null)
            {
                hangarRecoveryPadGlow.gameObject.SetActive(true);
                hangarRecoveryPadGlow.anchoredPosition = center + new Vector2(0f, -4f);
                hangarRecoveryPadGlow.sizeDelta = new Vector2(172f, 172f);
                hangarRecoveryPadGlow.localRotation = Quaternion.identity;
                hangarRecoveryPadGlow.localScale = Vector3.one * (1.0f + pulse * 0.08f);
                Image image = hangarRecoveryPadGlow.GetComponent<Image>();
                if (image != null)
                    image.color = new Color(0.10f, 0.88f, 1f, Mathf.Lerp(0.035f, 0.10f, pulse));
                hangarRecoveryPadGlow.SetSiblingIndex(Mathf.Max(0, orb != null ? orb.GetSiblingIndex() - 1 : hangarRecoveryPadGlow.GetSiblingIndex()));
            }

            if (hangarRecoveryPadRing != null)
            {
                hangarRecoveryPadRing.gameObject.SetActive(true);
                hangarRecoveryPadRing.anchoredPosition = center + new Vector2(0f, -2f);
                hangarRecoveryPadRing.sizeDelta = new Vector2(132f, 132f);
                hangarRecoveryPadRing.localRotation = Quaternion.Euler(0f, 0f, Mathf.Sin(Time.unscaledTime * 1.2f) * 2.4f);
                hangarRecoveryPadRing.localScale = Vector3.one * (1.0f + pulse * 0.035f);
                Image image = hangarRecoveryPadRing.GetComponent<Image>();
                if (image != null)
                    image.color = new Color(0.08f, 0.92f, 1f, Mathf.Lerp(0.12f, 0.28f, pulse));
            }

            if (hangarRecoveryScanLine != null)
            {
                float sweep = Mathf.Sin(Time.unscaledTime * 2.8f);
                hangarRecoveryScanLine.gameObject.SetActive(true);
                hangarRecoveryScanLine.sizeDelta = new Vector2(108f, 3f);
                hangarRecoveryScanLine.anchoredPosition = center + new Vector2(0f, sweep * 42f);
                hangarRecoveryScanLine.localRotation = Quaternion.Euler(0f, 0f, 0f);
                hangarRecoveryScanLine.localScale = new Vector3(Mathf.Lerp(0.55f, 1.15f, 1f - Mathf.Abs(sweep)), 1f, 1f);
                Image image = hangarRecoveryScanLine.GetComponent<Image>();
                if (image != null)
                    image.color = new Color(0.54f, 1f, 1f, Mathf.Lerp(0.22f, 0.76f, 1f - Mathf.Abs(sweep)));
            }

            if (hangarRecoveryProgressArc != null)
            {
                float angle = Mathf.Lerp(-135f, 225f, progress) + Mathf.Sin(Time.unscaledTime * 4f) * 8f;
                float radiusX = 68f;
                float radiusY = 52f;
                hangarRecoveryProgressArc.gameObject.SetActive(true);
                hangarRecoveryProgressArc.anchoredPosition = center + new Vector2(Mathf.Cos(angle * Mathf.Deg2Rad) * radiusX, Mathf.Sin(angle * Mathf.Deg2Rad) * radiusY);
                hangarRecoveryProgressArc.localRotation = Quaternion.Euler(0f, 0f, angle + 90f);
                hangarRecoveryProgressArc.localScale = new Vector3(1f, Mathf.Lerp(0.55f, 1.42f, progress), 1f);
            }
        }

        private void UpdateHangarRecoveryBeams(Vector2 center, float progress)
        {
            if (hangarRecoveryBeams == null)
                return;

            Vector2 dronePosition = crafterDrone != null && crafterDrone.gameObject.activeSelf ? crafterDrone.anchoredPosition : center + new Vector2(70f, 0f);
            for (int i = 0; i < hangarRecoveryBeams.Length; i++)
            {
                RectTransform beam = hangarRecoveryBeams[i];
                if (beam == null)
                    continue;

                float phase = Time.unscaledTime * (3.2f + i * 0.35f) + i * 1.3f;
                float activePulse = Mathf.Clamp01(Mathf.Sin(phase) * 1.8f + 0.15f);
                bool active = activePulse > 0.28f && progress < 0.96f;
                beam.gameObject.SetActive(active);
                if (!active)
                    continue;

                Vector2 hit = center + new Vector2(Mathf.Cos(phase * 1.7f) * 34f, Mathf.Sin(phase * 1.13f) * 28f);
                Vector2 emitter = Vector2.Lerp(dronePosition, hit, 0.64f);
                PositionBeamBetween(beam, emitter, hit, Mathf.Lerp(0.12f, 0.46f, activePulse) * (1f - progress * 0.28f), 1.4f + activePulse * 2.0f);
            }
        }

        private static void PositionBeamBetween(RectTransform beam, Vector2 from, Vector2 to, float alpha, float width)
        {
            Vector2 delta = to - from;
            float length = Mathf.Max(1f, delta.magnitude);
            beam.anchoredPosition = (from + to) * 0.5f;
            beam.sizeDelta = new Vector2(width, length);
            beam.localRotation = Quaternion.Euler(0f, 0f, Mathf.Atan2(delta.y, delta.x) * Mathf.Rad2Deg - 90f);
            Image image = beam.GetComponent<Image>();
            if (image != null)
                image.color = new Color(0.34f, 1f, 1f, alpha);
        }

        private void UpdateHangarRecoverySparks(Vector2 center, float progress)
        {
            if (weldSparks == null)
                return;

            float fade = 1f - Mathf.Clamp01((progress - 0.82f) / 0.18f);
            for (int i = 0; i < weldSparks.Length; i++)
            {
                RectTransform spark = weldSparks[i];
                if (spark == null)
                    continue;

                float phase = Time.unscaledTime * (7.5f + i * 0.75f) + i * 1.77f;
                float angle = hangarRecoveryCrafterOrbit + i * Mathf.PI * 2f / weldSparks.Length + Mathf.Sin(phase) * 0.25f;
                float radius = Mathf.Lerp(26f, 54f, Mathf.PingPong(phase * 0.41f, 1f));
                spark.gameObject.SetActive(fade > 0.02f);
                spark.anchoredPosition = center + new Vector2(Mathf.Cos(angle) * radius, Mathf.Sin(angle) * radius * 0.72f);
                spark.localRotation = Quaternion.Euler(0f, 0f, angle * Mathf.Rad2Deg + 90f);
                spark.localScale = Vector3.one * Mathf.Lerp(0.48f, 1.05f, Mathf.PingPong(phase, 1f));
                Image image = spark.GetComponent<Image>();
                if (image != null)
                    image.color = i % 2 == 0 ? new Color(1f, 0.72f, 0.18f, 0.92f * fade) : new Color(0.28f, 1f, 1f, 0.86f * fade);
            }
        }

        private void UpdateOrbDamageCracks(float repairProgress)
        {
            if (orbDamageCracks == null)
                return;

            float alpha = 1f - Mathf.Clamp01((repairProgress - 0.65f) / 0.30f);
            for (int i = 0; i < orbDamageCracks.Length; i++)
            {
                RectTransform crack = orbDamageCracks[i];
                if (crack == null)
                    continue;

                crack.gameObject.SetActive(hangarRecoveryActive && alpha > 0.03f);
                Image image = crack.GetComponent<Image>();
                if (image != null)
                {
                    float flicker = 0.5f + Mathf.Sin(Time.unscaledTime * (18f + i * 2.1f)) * 0.5f;
                    image.color = new Color(1f, Mathf.Lerp(0.07f, 0.38f, flicker), 0.03f, Mathf.Lerp(0.42f, 0.95f, flicker) * alpha);
                }
            }
        }

        private void HideOrbDamageCracks()
        {
            if (orbDamageCracks == null)
                return;

            for (int i = 0; i < orbDamageCracks.Length; i++)
            {
                if (orbDamageCracks[i] != null)
                    orbDamageCracks[i].gameObject.SetActive(false);
            }
        }

        private void HideHangarRecoveryEffects()
        {
            SetHangarRecoveryBarVisible(false);
            HideOrbDamageCracks();

            if (weldSparks != null)
            {
                for (int i = 0; i < weldSparks.Length; i++)
                {
                    if (weldSparks[i] != null)
                        weldSparks[i].gameObject.SetActive(false);
                }
            }

            if (hangarRecoveryPadGlow != null)
                hangarRecoveryPadGlow.gameObject.SetActive(false);
            if (hangarRecoveryPadRing != null)
                hangarRecoveryPadRing.gameObject.SetActive(false);
            if (hangarRecoveryScanLine != null)
                hangarRecoveryScanLine.gameObject.SetActive(false);
            if (hangarRecoveryProgressArc != null)
                hangarRecoveryProgressArc.gameObject.SetActive(false);
            if (hangarRecoveryBeams != null)
            {
                for (int i = 0; i < hangarRecoveryBeams.Length; i++)
                {
                    if (hangarRecoveryBeams[i] != null)
                        hangarRecoveryBeams[i].gameObject.SetActive(false);
                }
            }
        }

        private void PlaceMenuHangarDrone(DroneUpgradeTarget upgradeTarget, RectTransform drone, bool owned, string spritePath, Vector2 target, float scale, ref Vector2 position)
        {
            if (drone == null)
                return;

            drone.gameObject.SetActive(owned);
            if (!owned)
                return;

            ApplySpriteFromTextureResource(drone, spritePath);
            if (IsDroneUpgradeTargetUnderStationControl(upgradeTarget))
            {
                drone.SetAsLastSibling();
                return;
            }

            if (position == Vector2.zero)
                position = target;

            Vector2 previous = position;
            position = Vector2.Lerp(position, target + WorkVibration(0.22f, 9f), 1f - Mathf.Exp(-7.4f * Time.unscaledDeltaTime));
            drone.anchoredPosition = position;
            drone.localScale = Vector3.one * scale;
            Vector2 faceTarget = (position - previous).sqrMagnitude > 0.08f ? position : ResolveHangarCargoBayPosition();
            FaceCommandedDroneToward(upgradeTarget, drone, previous, faceTarget);
            drone.SetAsLastSibling();
        }

        private void UpdateMenuHangarUpgradeButton(int index, bool visible, Vector2 playfieldPosition, string shortName)
        {
            if (index < 0 || index >= menuHangarUpgradeButtons.Length)
                return;

            Button button = menuHangarUpgradeButtons[index];
            if (button == null)
                return;

            button.gameObject.SetActive(visible && CanShowMenuHangarUpgradeButtons());
            if (!button.gameObject.activeSelf)
                return;

            RectTransform rect = button.transform as RectTransform;
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = new Vector2(index < 4 ? 118f : 132f, 40f);
            rect.anchoredPosition = playfieldPosition + PlayfieldCameraOffset() + new Vector2(0f, index < 4 ? -92f : -58f);
            rect.localScale = Vector3.one;

            TMP_Text label = button.GetComponentInChildren<TMP_Text>(true);
            if (label != null)
                label.text = L("hangar.upgrade");
            button.transform.SetAsLastSibling();
        }

        private void ShowMenuHangarProfile(int index)
        {
            if (menuHangarProfileRoot == null)
                return;

            DroneUpgradeTarget stationTarget = HangarIndexToDroneUpgradeTarget(index);
            if (stationTarget != DroneUpgradeTarget.None && menuHangarOpen && !droneUpgradePadDocking && (droneUpgradeRoot == null || !droneUpgradeRoot.gameObject.activeSelf))
            {
                StartDroneUpgradePadDocking(stationTarget);
                if (statusText != null)
                    statusText.text = LF("status.drone_on_upgrade_pad", DroneUpgradeTargetName(stationTarget));
                return;
            }

            menuHangarSelectedUpgradeIndex = index;
            string title;
            string body;
            string spritePath;
            ResolveMenuHangarProfileData(index, out title, out body, out spritePath);

            menuHangarProfileRoot.gameObject.SetActive(true);
            menuHangarProfileRoot.SetAsLastSibling();
            if (menuHangarProfileTitleText != null)
                menuHangarProfileTitleText.text = title;
            if (menuHangarProfileBodyText != null)
                menuHangarProfileBodyText.text = BuildMenuHangarProfileBody(index, body);
            if (menuHangarProfileActionText != null)
                menuHangarProfileActionText.text = MenuHangarUpgradeActionLabel(index);

            Image portrait = menuHangarProfilePortrait != null ? menuHangarProfilePortrait.GetComponent<Image>() : null;
            if (portrait != null)
            {
                portrait.sprite = GetSpriteFromTextureResource(spritePath);
                portrait.color = Color.white;
                portrait.preserveAspect = true;
            }

            for (int i = 0; i < menuHangarUpgradeButtons.Length; i++)
            {
                if (menuHangarUpgradeButtons[i] != null)
                    menuHangarUpgradeButtons[i].gameObject.SetActive(false);
            }
        }

