        private string BuildMenuHangarProfileBody(int index, string baseBody)
        {
            int level = GetMenuHangarUpgradeLevel(index);
            string next = level >= HangarUpgradeMaxLevel
                ? L("hangar.max_level")
                : LF("hangar.next_upgrade", MenuHangarUpgradeCost(index, level));
            return LF("hangar.body", baseBody, level, HangarUpgradeMaxLevel, next, coreShards);
        }

        private string MenuHangarUpgradeActionLabel(int index)
        {
            int level = GetMenuHangarUpgradeLevel(index);
            if (level >= HangarUpgradeMaxLevel)
                return L("hangar.max");

            return LF("hangar.action_upgrade", MenuHangarUpgradeCost(index, level));
        }

        private int GetMenuHangarUpgradeLevel(int index)
        {
            return Mathf.Clamp(PlayerPrefs.GetInt(HangarUpgradeLevelKeyPrefix + Mathf.Clamp(index, 0, 99), 0), 0, HangarUpgradeMaxLevel);
        }

        private void SetMenuHangarUpgradeLevel(int index, int level)
        {
            PlayerPrefs.SetInt(HangarUpgradeLevelKeyPrefix + Mathf.Clamp(index, 0, 99), Mathf.Clamp(level, 0, HangarUpgradeMaxLevel));
        }

        private static int MenuHangarUpgradeCost(int index, int level)
        {
            int familyBase = index < 4 ? 8 : 6;
            return familyBase + Mathf.Clamp(level, 0, HangarUpgradeMaxLevel) * (index < 4 ? 5 : 4);
        }

