        private void UpdateMenuDroneGhosts()
        {
            for (int i = menuDroneGhosts.Count - 1; i >= 0; i--)
            {
                MenuDroneGhostView ghost = menuDroneGhosts[i];
                if (ghost.Root == null)
                {
                    menuDroneGhosts.RemoveAt(i);
                    continue;
                }

                ghost.Age += Time.unscaledDeltaTime;
                float travel = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(ghost.Age / Mathf.Max(0.05f, ghost.Lifetime)));
                if (ghost.HoldAtEnd && ghost.Age >= ghost.Lifetime)
                {
                    float hover = Mathf.Sin((Time.unscaledTime + ghost.HoverPhase) * 2.4f) * 5.5f;
                    ghost.Root.anchoredPosition = ghost.End + new Vector2(Mathf.Sin((Time.unscaledTime + ghost.HoverPhase) * 1.3f) * 3.0f, hover);
                }
                else
                {
                    ghost.Root.anchoredPosition = Vector2.Lerp(ghost.Start, ghost.End, travel);
                }

                ghost.Root.Rotate(0f, 0f, ghost.SpinSpeed * Time.unscaledDeltaTime);
                Image image = ghost.Root.GetComponent<Image>();
                if (image != null)
                {
                    float fade = ghost.HoldAtEnd ? 1f : 1f - Mathf.Clamp01((ghost.Age - ghost.Lifetime * 0.72f) / (ghost.Lifetime * 0.28f));
                    image.color = new Color(1f, 1f, 1f, fade);
                }

                if (!ghost.HoldAtEnd && ghost.Age >= ghost.Lifetime)
                {
                    Destroy(ghost.Root.gameObject);
                    menuDroneGhosts.RemoveAt(i);
                }
            }
        }

        private void ResetMenuScene()
        {
            menuSceneStep = MenuSceneStep.None;
            menuSceneTimer = 0f;
            menuSceneOrbitAngle = 0f;
            menuShieldTimer = 0f;
            menuRepairDoneThisCycle = false;
            menuGeneratorDoneThisCycle = false;
            menuShieldDoneThisCycle = false;
            UpdateCrafterCraftSound(false);
            CleanupMenuDroneGhosts();
        }

        private void UpdateMenuScene()
        {
            bool activeScene = (state == GameState.Menu || state == GameState.ModeSelect || state == GameState.StoryLevels) && !menuHangarOpen;
            if (!activeScene || !IsTutorialCompleted())
            {
                HideRuntimeDrones();
                HideCraftProgress();
                UpdateCrafterCraftSound(false);
                UpdateGeneratorShieldChargeSound(false);
                return;
            }

            if (!crafterOwned)
            {
                HideRuntimeDrones();
                UpdateCrafterCraftSound(false);
                UpdateGeneratorShieldChargeSound(false);
                return;
            }

            if (menuSceneStep == MenuSceneStep.None)
            {
                if (menuSceneTimer < 0f)
                {
                    menuSceneTimer += Time.unscaledDeltaTime;
                    return;
                }

                menuSceneStep = MenuSceneStep.CrafterArrive;
                menuSceneTimer = 0f;
                menuRepairDoneThisCycle = false;
                menuGeneratorDoneThisCycle = false;
                menuShieldDoneThisCycle = false;
                Vector2 crafterStart = crafterDrone != null && crafterDrone.gameObject.activeSelf
                    ? crafterDrone.anchoredPosition
                    : new Vector2(laneX, orbY - 220f);
                PrepareMenuDrone(crafterDrone, CrafterDroneSpriteResourcePath, crafterStart, 1.45f);
                if (repairDrone != null)
                    repairDrone.gameObject.SetActive(false);
                if (generatorDrone != null)
                    generatorDrone.gameObject.SetActive(false);
                if (shieldDrone != null)
                    shieldDrone.gameObject.SetActive(false);
                if (shieldDroneLaser != null)
                    shieldDroneLaser.gameObject.SetActive(false);
            }

            menuSceneTimer += Time.unscaledDeltaTime;

            if (menuShieldTimer > 0f)
            {
                menuShieldTimer -= Time.unscaledDeltaTime;
                UpdateShieldBubble(shieldRing, true, 1f, 112f);
            }

            Vector2 orbCenter = new Vector2(laneX, orbY);
            Vector2 crafterWork = orbCenter + new Vector2(0f, -220f);
            bool menuCrafterCraftSound = false;
            bool menuGeneratorChargingSound = false;
            switch (menuSceneStep)
            {
                case MenuSceneStep.CrafterArrive:
                    MoveMenuDrone(crafterDrone, crafterWork, 1.55f, CrafterDroneSpriteResourcePath, 1.32f);
                    if (Vector2.Distance(crafterDrone.anchoredPosition, crafterWork) < 18f)
                    {
                        menuSceneStep = MenuSceneStep.WaitBeforeCraft;
                        menuSceneTimer = 0f;
                    }
                    break;

                case MenuSceneStep.WaitBeforeCraft:
                    HoverMenuCrafter(crafterWork, false);
                    if (menuSceneTimer >= 2.4f)
                    {
                        menuSceneStep = SelectNextMenuCraftStep();
                        menuSceneTimer = 0f;
                    }
                    break;

                case MenuSceneStep.CraftRepair:
                    menuCrafterCraftSound = true;
                    HoverMenuCrafter(crafterWork, true);
                    ShowCraftProgress(Mathf.Clamp01(menuSceneTimer / 4.8f));
                    if (menuSceneTimer >= 4.8f)
                    {
                        HideCraftProgress();
                        menuSceneStep = MenuSceneStep.RepairOrbit;
                        menuSceneTimer = 0f;
                        menuSceneOrbitAngle = 0f;
                        PrepareMenuDrone(repairDrone, RepairDroneSpriteResourcePath, crafterWork + new Vector2(44f, 4f), 1.25f);
                    }
                    break;

                case MenuSceneStep.RepairOrbit:
                    HoverMenuCrafter(crafterWork, false);
                    menuSceneOrbitAngle += Time.unscaledDeltaTime * Mathf.PI * 0.28f;
                    Vector2 repairTarget = orbCenter + new Vector2(Mathf.Cos(menuSceneOrbitAngle), Mathf.Sin(menuSceneOrbitAngle)) * 126f;
                    MoveMenuRepairDrone(repairTarget, orbCenter, 2.65f, 1.25f);
                    UpdateWeldSparks(true, repairDrone.anchoredPosition, orbCenter);
                    if (menuSceneOrbitAngle >= Mathf.PI * 4f)
                    {
                        UpdateWeldSparks(false, Vector2.zero, Vector2.zero);
                        menuRepairDoneThisCycle = true;
                        menuSceneStep = MenuSceneStep.RepairExit;
                        menuSceneTimer = 0f;
                        menuSceneExitTarget = RandomMenuExitTarget();
                    }
                    break;

                case MenuSceneStep.RepairExit:
                    HoverMenuCrafter(crafterWork, false);
                    MoveMenuDrone(repairDrone, menuSceneExitTarget, 0.85f, RepairDroneSpriteResourcePath, 1.25f);
                    if (menuSceneTimer >= 4.2f)
                    {
                        if (repairDrone != null)
                            repairDrone.gameObject.SetActive(false);
                        menuSceneStep = SelectNextMenuCraftStep();
                        menuSceneTimer = 0f;
                    }
                    break;

                case MenuSceneStep.CraftGenerator:
                    menuCrafterCraftSound = true;
                    HoverMenuCrafter(crafterWork, true);
                    ShowCraftProgress(Mathf.Clamp01(menuSceneTimer / 5.2f));
                    if (menuSceneTimer >= 5.2f)
                    {
                        HideCraftProgress();
                        menuSceneStep = MenuSceneStep.GeneratorDock;
                        menuSceneTimer = 0f;
                        PrepareMenuDrone(generatorDrone, GeneratorDroneSpriteResourcePath, crafterWork + new Vector2(44f, 4f), 1.25f);
                    }
                    break;

                case MenuSceneStep.GeneratorDock:
                    HoverMenuCrafter(crafterWork, false);
                    MoveMenuDrone(generatorDrone, orbCenter, 1.45f, GeneratorDroneSpriteResourcePath, 1.18f);
                    if (Vector2.Distance(generatorDrone.anchoredPosition, orbCenter) < 10f || menuSceneTimer >= 5.0f)
                    {
                        if (generatorDrone != null)
                        {
                            generatorDrone.anchoredPosition = orbCenter;
                            generatorDrone.localScale = Vector3.one * 1.05f;
                            generatorDrone.localRotation = Quaternion.identity;
                            generatorDrone.SetAsLastSibling();
                        }

                        menuSceneStep = MenuSceneStep.GeneratorCharge;
                        menuSceneTimer = 0f;
                    }
                    break;

                case MenuSceneStep.GeneratorCharge:
                    menuGeneratorChargingSound = true;
                    HoverMenuCrafter(crafterWork, false);
                    if (generatorDrone != null)
                    {
                        generatorDrone.gameObject.SetActive(true);
                        generatorDrone.anchoredPosition = orbCenter + WorkVibration(0.28f, 10f);
                        generatorDrone.localScale = Vector3.one * 1.05f;
                        generatorDrone.localRotation = Quaternion.Euler(0f, 0f, Mathf.Sin(Time.unscaledTime * 8f) * 3f);
                    }

                    float shieldCharge = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(menuSceneTimer / 5.8f));
                    UpdateShieldBubble(shieldRing, true, shieldCharge, 112f);
                    if (menuSceneTimer >= 5.8f)
                    {
                        menuShieldTimer = 4.0f;
                        menuGeneratorDoneThisCycle = true;
                        menuSceneStep = MenuSceneStep.GeneratorExit;
                        menuSceneTimer = 0f;
                        menuSceneExitTarget = RandomMenuExitTarget();
                    }
                    break;

                case MenuSceneStep.GeneratorExit:
                    HoverMenuCrafter(crafterWork, false);
                    MoveMenuDrone(generatorDrone, menuSceneExitTarget, 0.85f, GeneratorDroneSpriteResourcePath, 1.25f);
                    if (menuSceneTimer >= 4.2f)
                    {
                        if (generatorDrone != null)
                            generatorDrone.gameObject.SetActive(false);
                        menuSceneStep = SelectNextMenuCraftStep();
                        menuSceneTimer = 0f;
                    }
                    break;

                case MenuSceneStep.CraftShield:
                    menuCrafterCraftSound = true;
                    HoverMenuCrafter(crafterWork, true);
                    ShowCraftProgress(Mathf.Clamp01(menuSceneTimer / 5.0f));
                    if (menuSceneTimer >= 5.0f)
                    {
                        HideCraftProgress();
                        menuSceneStep = MenuSceneStep.ShieldDemo;
                        menuSceneTimer = 0f;
                        Vector2 shieldBuildPoint = crafterDrone != null && crafterDrone.gameObject.activeSelf ? crafterDrone.anchoredPosition : crafterWork;
                        PrepareMenuDrone(shieldDrone, ShieldDroneSpriteResourcePath, shieldBuildPoint, 0.55f);
                        menuShieldLaserTarget = RandomMenuExitTarget();
                    }
                    break;

                case MenuSceneStep.ShieldDemo:
                    HoverMenuCrafter(crafterWork, false);
                    float shieldArrive = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(menuSceneTimer / 2.4f));
                    float shieldAngle = Mathf.Lerp(-115f, 90f, shieldArrive) * Mathf.Deg2Rad;
                    Vector2 shieldPoint = orbCenter + new Vector2(Mathf.Cos(shieldAngle) * 142f, Mathf.Sin(shieldAngle) * 142f + 10f);
                    MoveMenuShieldDrone(shieldPoint, 2.25f, 1.22f, shieldArrive >= 0.96f ? menuShieldLaserTarget : orbCenter);
                    bool shieldReady = shieldArrive >= 0.96f && shieldDrone != null && Vector2.Distance(shieldDrone.anchoredPosition, shieldPoint) < 22f;
                    if (shieldReady)
                        UpdateMenuShieldLaser(menuShieldLaserTarget);
                    else if (shieldDroneLaser != null)
                        shieldDroneLaser.gameObject.SetActive(false);
                    if (menuSceneTimer >= 5.2f)
                    {
                        if (shieldDroneLaser != null)
                            shieldDroneLaser.gameObject.SetActive(false);
                        menuShieldDoneThisCycle = true;
                        menuSceneStep = MenuSceneStep.ShieldExit;
                        menuSceneTimer = 0f;
                    }
                    break;

                case MenuSceneStep.ShieldExit:
                    HoverMenuCrafter(crafterWork, false);
                    MoveMenuShieldDrone(menuShieldLaserTarget, 0.42f, 1.18f, menuShieldLaserTarget);
                    UpdateMenuShieldLaser(menuShieldLaserTarget);
                    if (menuSceneTimer >= 6.4f)
                    {
                        if (shieldDrone != null)
                            shieldDrone.gameObject.SetActive(false);
                        if (shieldDroneLaser != null)
                            shieldDroneLaser.gameObject.SetActive(false);
                        menuRepairDoneThisCycle = false;
                        menuGeneratorDoneThisCycle = false;
                        menuShieldDoneThisCycle = false;
                        menuSceneStep = MenuSceneStep.WaitBeforeCraft;
                        menuSceneTimer = 0f;
                    }
                    break;
            }
            UpdateCrafterCraftSound(menuCrafterCraftSound);
            UpdateGeneratorShieldChargeSound(menuGeneratorChargingSound);
        }

        private MenuSceneStep SelectNextMenuCraftStep()
        {
            if (repairOwned && !menuRepairDoneThisCycle)
                return MenuSceneStep.CraftRepair;
            if (generatorOwned && !menuGeneratorDoneThisCycle)
                return MenuSceneStep.CraftGenerator;
            if (shieldDroneOwned && !menuShieldDoneThisCycle)
                return MenuSceneStep.CraftShield;

            menuRepairDoneThisCycle = false;
            menuGeneratorDoneThisCycle = false;
            menuShieldDoneThisCycle = false;
            return MenuSceneStep.WaitBeforeCraft;
        }

        private void PrepareMenuDrone(RectTransform drone, string spritePath, Vector2 position, float scale)
        {
            if (drone == null)
                return;

            ApplySpriteFromTextureResource(drone, spritePath);
            drone.anchoredPosition = position;
            drone.localScale = Vector3.one * scale;
            drone.gameObject.SetActive(true);
        }

        private void MoveMenuDrone(RectTransform drone, Vector2 target, float response, string spritePath, float scale)
        {
            if (drone == null)
                return;

            if (!drone.gameObject.activeSelf)
            {
                PrepareMenuDrone(drone, spritePath, target, scale);
            }

            Vector2 previous = drone.anchoredPosition;
            drone.localScale = Vector3.one * scale;
            drone.anchoredPosition = Vector2.Lerp(previous, target, 1f - Mathf.Exp(-response * Time.unscaledDeltaTime));
            FaceDroneToward(drone, previous, drone.anchoredPosition + (drone.anchoredPosition - previous), Mathf.Sin(Time.unscaledTime * 18f) * 4f);
        }

        private void MoveMenuRepairDrone(Vector2 target, Vector2 workTarget, float response, float scale)
        {
            MoveMenuDrone(repairDrone, target, response, RepairDroneSpriteResourcePath, scale);
            if (repairDrone == null)
                return;

            FaceDroneToward(repairDrone, repairDrone.anchoredPosition, workTarget, Mathf.Sin(Time.unscaledTime * 12f) * 2.5f);
        }

        private void MoveMenuShieldDrone(Vector2 target, float response, float scale, Vector2 lookTarget)
        {
            if (shieldDrone == null)
                return;

            MoveMenuDrone(shieldDrone, target, response, ShieldDroneSpriteResourcePath, scale);
            FaceShieldDroneToward(shieldDrone, shieldDrone.anchoredPosition, lookTarget, Mathf.Sin(Time.unscaledTime * 10f) * 2f);
        }

        private void UpdateMenuShieldLaser(Vector2 target)
        {
            if (shieldDroneLaser == null || shieldDrone == null || !shieldDrone.gameObject.activeSelf)
                return;

            Vector2 origin = shieldDrone.anchoredPosition;
            Vector2 direction = target - origin;
            float length = direction.magnitude;
            if (length < 1f)
                return;

            shieldDroneLaser.gameObject.SetActive(true);
            shieldDroneLaser.anchoredPosition = origin;
            shieldDroneLaser.sizeDelta = new Vector2(4f + Mathf.Sin(Time.unscaledTime * 26f) * 1.4f, length);
            shieldDroneLaser.localRotation = Quaternion.Euler(0f, 0f, Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg - 90f);
        }

        private void HoverMenuCrafter(Vector2 point, bool crafting)
        {
            if (crafterDrone == null)
                return;

            float t = Time.unscaledTime;
            Vector2 localMotion = crafting
                ? new Vector2(Mathf.Sin(t * 42f) * 5.5f + Mathf.Sin(t * 11f) * 2.5f, Mathf.Cos(t * 37f) * 4.5f)
                : new Vector2(Mathf.Sin(t * 0.82f) * 42f, Mathf.Cos(t * 1.08f) * 18f + Mathf.Sin(t * 1.7f) * 5f);
            Vector2 target = point + localMotion;
            Vector2 previous = crafterDrone.anchoredPosition;

            MoveMenuDrone(crafterDrone, target, crafting ? 8.2f : 1.85f, CrafterDroneSpriteResourcePath, 1.45f);
            if (crafting)
            {
                Vector2 craftFocus = point + new Vector2(0f, 42f);
                FaceDroneToward(crafterDrone, previous, craftFocus, Mathf.Sin(t * 48f) * 8f);
            }
            else
            {
                FaceDroneToward(crafterDrone, previous, target + new Vector2(Mathf.Sin(t * 1.2f) * 18f, 24f), Mathf.Sin(t * 6f) * 3f);
            }
        }

        private Vector2 RandomMenuExitTarget()
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return new Vector2(laneX + 650f, orbY + 180f);

            float side = RandomRange(0f, 1f) > 0.5f ? 1f : -1f;
            return new Vector2(side * (root.rect.width * 0.58f + 150f), orbY + RandomRange(80f, 260f));
        }

        private void SpawnMenuDroneGhost(string spritePath, Vector2 offset)
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return;

            GameObject go = new GameObject("MenuDroneLaunch", typeof(RectTransform), typeof(CanvasRenderer), typeof(Image));
            go.transform.SetParent(root, false);
            RectTransform rect = go.GetComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = new Vector2(52f, 48f);
            rect.anchoredPosition = new Vector2(laneX, orbY) + offset;
            Image image = go.GetComponent<Image>();
            image.raycastTarget = false;
            Sprite sprite = GetSpriteFromTextureResource(spritePath);
            if (sprite != null)
            {
                image.sprite = sprite;
                image.color = Color.white;
                image.preserveAspect = true;
            }
            else
            {
                image.color = Cyan;
            }

            float side = RandomRange(0f, 1f) > 0.5f ? 1f : -1f;
            menuDroneGhosts.Add(new MenuDroneGhostView
            {
                Root = rect,
                Start = rect.anchoredPosition,
                End = new Vector2(side * (root.rect.width * 0.62f + 120f), orbY + RandomRange(80f, 260f)),
                Lifetime = RandomRange(1.6f, 2.3f),
                SpinSpeed = 80f
            });
        }

        private void SpawnTutorialFarewellDroneGroup(Vector2 focus, float width, float height)
        {
            string[] sprites =
            {
                ShieldDroneSpriteResourcePath,
                CrafterDroneSpriteResourcePath,
                RepairDroneSpriteResourcePath,
                GeneratorDroneSpriteResourcePath,
                CollectorDroneSpriteResourcePath,
                MineLayerDroneSpriteResourcePath,
                OzCoreMinerDroneSpriteResourcePath,
                CrafterDroneSpriteResourcePath,
                RepairDroneSpriteResourcePath,
                GeneratorDroneSpriteResourcePath,
                CollectorDroneSpriteResourcePath
            };

            Vector2[] offsets =
            {
                new Vector2(0f, 118f),
                new Vector2(-76f, 92f), new Vector2(76f, 92f),
                new Vector2(-126f, 32f), new Vector2(126f, 32f),
                new Vector2(-118f, -58f), new Vector2(118f, -58f),
                new Vector2(-52f, -118f), new Vector2(52f, -118f),
                new Vector2(-178f, -8f), new Vector2(178f, -8f)
            };

            for (int i = 0; i < sprites.Length; i++)
            {
                float lane = i - (sprites.Length - 1) * 0.5f;
                float scale = i == 0 ? 1.18f : i % 4 == 0 ? 1.06f : i % 3 == 0 ? 0.92f : 1.0f;
                Vector2 start = new Vector2(Mathf.Clamp(lane * 54f, -width * 0.38f, width * 0.38f), -height * 0.64f - i * 24f);
                SpawnTutorialFarewellDrone(sprites[i], start, focus + offsets[i], scale, 3.05f + i * 0.075f);
            }
        }

        private void SpawnTutorialFarewellDrone(string spritePath, Vector2 start, Vector2 end, float scale, float travelTime)
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return;

            GameObject go = new GameObject("TutorialFarewellDrone", typeof(RectTransform), typeof(CanvasRenderer), typeof(Image));
            go.transform.SetParent(root, false);
            RectTransform rect = go.GetComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = new Vector2(62f, 58f);
            rect.localScale = Vector3.one * scale;
            rect.anchoredPosition = start;
            rect.SetAsLastSibling();

            Image image = go.GetComponent<Image>();
            image.raycastTarget = false;
            Sprite sprite = GetSpriteFromTextureResource(spritePath);
            if (sprite != null)
            {
                image.sprite = sprite;
                image.color = Color.white;
                image.preserveAspect = true;
            }
            else
            {
                image.color = Cyan;
            }

            FaceDroneToward(rect, start, end, 0f);
            menuDroneGhosts.Add(new MenuDroneGhostView
            {
                Root = rect,
                Start = start,
                End = end,
                Lifetime = travelTime,
                HoldAtEnd = true,
                HoverPhase = RandomRange(0f, 6.28f),
                SpinSpeed = RandomRange(-10f, 10f)
            });
        }

        private void ReleaseTutorialFarewellDroneGroup(float width, float height)
        {
            for (int i = 0; i < menuDroneGhosts.Count; i++)
            {
                MenuDroneGhostView ghost = menuDroneGhosts[i];
                if (ghost == null || ghost.Root == null)
                    continue;

                float lane = i - (menuDroneGhosts.Count - 1) * 0.5f;
                float sidePush = Mathf.Sign(Mathf.Abs(lane) < 0.01f ? (i % 2 == 0 ? 1f : -1f) : lane);
                float x = Mathf.Clamp(lane * 58f + sidePush * RandomRange(95f, 230f), -width * 0.68f, width * 0.68f);
                float y = height * 0.62f + RandomRange(90f, 360f);
                Vector2 current = ghost.Root.anchoredPosition;
                ghost.Start = current;
                ghost.End = new Vector2(x, y);
                ghost.Age = 0f;
                ghost.Lifetime = RandomRange(1.65f, 2.45f);
                ghost.HoldAtEnd = false;
                ghost.SpinSpeed = RandomRange(-42f, 42f);
                FaceDroneToward(ghost.Root, current, ghost.End, 0f);
            }
        }

        private void CleanupMenuDroneGhosts()
        {
            for (int i = menuDroneGhosts.Count - 1; i >= 0; i--)
            {
                if (menuDroneGhosts[i].Root != null)
                    Destroy(menuDroneGhosts[i].Root.gameObject);
            }

            menuDroneGhosts.Clear();
        }

        private void LaunchMenuDronesOut()
        {
            LaunchMenuDroneOut(crafterDrone);
            LaunchMenuDroneOut(repairDrone);
            LaunchMenuDroneOut(generatorDrone);
            LaunchMenuDroneOut(shieldDrone);
            LaunchMenuDroneOut(collectorDrone);
            LaunchMenuDroneOut(ozCoreMinerDrone);
        }

        private void LaunchMenuDroneOut(RectTransform drone)
        {
            if (drone == null || !drone.gameObject.activeSelf)
                return;

            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return;

            Image source = drone.GetComponent<Image>();
            GameObject go = new GameObject("MenuDroneExit", typeof(RectTransform), typeof(CanvasRenderer), typeof(Image));
            go.transform.SetParent(root, false);
            RectTransform copy = go.GetComponent<RectTransform>();
            copy.anchorMin = new Vector2(0.5f, 0.5f);
            copy.anchorMax = new Vector2(0.5f, 0.5f);
            copy.pivot = new Vector2(0.5f, 0.5f);
            copy.sizeDelta = drone.sizeDelta;
            copy.anchoredPosition = drone.anchoredPosition;
            copy.localScale = drone.localScale;
            copy.localRotation = drone.localRotation;
            Image image = go.GetComponent<Image>();
            image.raycastTarget = false;
            if (source != null)
            {
                image.sprite = source.sprite;
                image.color = source.color;
                image.preserveAspect = source.preserveAspect;
            }

            menuDroneGhosts.Add(new MenuDroneGhostView
            {
                Root = copy,
                Start = copy.anchoredPosition,
                End = RandomMenuExitTarget(),
                Lifetime = 2.4f,
                SpinSpeed = 80f
            });
        }

