                repairDrone.gameObject.SetActive(false);
            if (shieldDrone != null)
                shieldDrone.gameObject.SetActive(false);
            if (shieldDroneLaser != null)
                shieldDroneLaser.gameObject.SetActive(false);
            if (collectorDrone != null)
                collectorDrone.gameObject.SetActive(false);
            if (collectorBeam != null)
                collectorBeam.gameObject.SetActive(false);
            if (mineLayerDrone != null)
                mineLayerDrone.gameObject.SetActive(false);
            if (ozCoreMinerDrone != null)
                ozCoreMinerDrone.gameObject.SetActive(false);
            if (hiveDrone != null)
                hiveDrone.gameObject.SetActive(false);
            if (gladiatorDrone != null)
                gladiatorDrone.gameObject.SetActive(false);
            if (horizonDrone != null)
                horizonDrone.gameObject.SetActive(false);
            if (tamerDrone != null)
                tamerDrone.gameObject.SetActive(false);
            if (tamerCaptureBeam != null)
                tamerCaptureBeam.gameObject.SetActive(false);
            if (queenDrone != null)
                queenDrone.gameObject.SetActive(false);
            HideQueenBuffVisuals();
            if (mimicDrone != null)
