        private float ResolveMenuOrbY()
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            float height = root != null ? root.rect.height : 1600f;
            return height * 0.18f;
        }

        private float ResolveGameOrbY()
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            float height = root != null ? root.rect.height : 1600f;
            return height * -0.339f;
        }

        private void SpawnLoop()
        {
            float difficulty = Mathf.Clamp01(elapsed / 70f);
            bool story = selectedMode == GameMode.Story;
            if (!story)
            {
                SpawnEndlessSpecialMineLoop(difficulty);
                SpawnForwardDefenseLoop(difficulty);
                formationTimer -= Time.deltaTime;
                if (formationTimer > 0f)
                    return;

                SpawnHazardFormation(difficulty, false);
                formationTimer = Mathf.Lerp(3.15f, 1.35f, difficulty) + RandomRange(-0.22f, 0.36f);
                return;
            }

            if (selectedStoryLevel == StoryLevel.Mines)
            {
                SpawnStoryMinesLoop(Mathf.Clamp01(elapsed / 70f));
                return;
            }
            if (selectedStoryLevel == StoryLevel.ForwardDefense)
            {
                SpawnStoryForwardDefenseLoop(Mathf.Clamp01(elapsed / 70f));
                return;
            }
        }

        private void SpawnForwardDefenseLoop(float difficulty)
        {
            if (elapsed < ForwardDefenseFirstDelay || minesBossActive || storyCinematicActive)
                return;

            forwardDefenseTimer -= Time.deltaTime;
            if (forwardDefenseTimer > 0f)
                return;

            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return;

            ForwardDefenseType type = ResolveForwardDefenseSpawnType(difficulty);
            float halfWidth = Mathf.Min(390f, root.rect.width * 0.5f - 64f);
            SpawnForwardDefenseUnit(type, RandomRange(-halfWidth, halfWidth), difficulty, ResolveEnemyFarSpawnY(95f));
            forwardDefenseTimer = Mathf.Lerp(ForwardDefenseSpawnMaxInterval, ForwardDefenseSpawnMinInterval, difficulty) + RandomRange(-0.55f, 0.85f);
        }

        private ForwardDefenseType ResolveForwardDefenseSpawnType(float difficulty)
        {
            double roll = random.NextDouble();
            if (elapsed > 48f && roll > 0.88)
                return ForwardDefenseType.CommandNode;
            if (elapsed > 34f && roll > 0.70)
                return ForwardDefenseType.InterceptorDrone;
            if (elapsed > 24f && roll > 0.52)
                return ForwardDefenseType.ShieldRelay;
            if (roll > 0.30 + difficulty * 0.16f)
                return ForwardDefenseType.PulseTurret;
            return ForwardDefenseType.SentinelScout;
        }

        private void SpawnForwardDefenseUnit(ForwardDefenseType type, float x, float difficulty, float y)
        {
            if (playfield == null)
                return;

            GameObject go = new GameObject("ForwardDefense_" + type, typeof(RectTransform), typeof(CanvasRenderer), typeof(Image));
            go.transform.SetParent(playfield, false);
            RectTransform rect = go.GetComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 1f);
            rect.anchorMax = new Vector2(0.5f, 1f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = ResolveForwardDefenseUnitSize(type);
            rect.anchoredPosition = new Vector2(x, y);

            Image image = go.GetComponent<Image>();
            image.raycastTarget = false;
            Sprite unitSprite = GetSpriteFromTextureResource(ResolveForwardDefenseUnitResourcePath(type));
            if (unitSprite != null)
            {
                image.sprite = unitSprite;
                image.overrideSprite = unitSprite;
                image.type = Image.Type.Simple;
                image.color = Color.white;
                image.preserveAspect = true;
            }
            else
            {
                image.color = ResolveForwardDefenseColor(type);
                AddForwardDefenseMarks(rect, type);
            }

            hazards.Add(new HazardView
            {
                Root = rect,
                Image = image,
                Radius = Mathf.Max(rect.sizeDelta.x, rect.sizeDelta.y) * 0.42f,
                Health = ResolveForwardDefenseHealth(type, difficulty),
                Speed = ResolveForwardDefenseSpeed(type, difficulty),
                Spin = type == ForwardDefenseType.PulseTurret || type == ForwardDefenseType.CommandNode ? 18f : 0f,
                ForwardDefense = type,
                ForwardAttackTimer = RandomRange(0.35f, 1.35f),
                ForwardPhase = RandomRange(0f, Mathf.PI * 2f),
                HorizontalSpeed = RandomRange(38f, 82f)
            });
        }

        private static Vector2 ResolveForwardDefenseUnitSize(ForwardDefenseType type)
        {
            switch (type)
            {
                case ForwardDefenseType.PulseTurret:
                    return new Vector2(128f, 74f);
                case ForwardDefenseType.ShieldRelay:
                    return new Vector2(108f, 108f);
                case ForwardDefenseType.InterceptorDrone:
                    return new Vector2(92f, 126f);
                case ForwardDefenseType.CommandNode:
                    return new Vector2(138f, 138f);
                default:
                    return new Vector2(82f, 96f);
            }
        }

        private static float ResolveForwardDefenseHealth(ForwardDefenseType type, float difficulty)
        {
            switch (type)
            {
                case ForwardDefenseType.PulseTurret:
                    return Mathf.Lerp(34f, 56f, difficulty);
                case ForwardDefenseType.ShieldRelay:
                    return Mathf.Lerp(48f, 74f, difficulty);
                case ForwardDefenseType.InterceptorDrone:
                    return Mathf.Lerp(30f, 48f, difficulty);
                case ForwardDefenseType.CommandNode:
                    return Mathf.Lerp(110f, 165f, difficulty);
                default:
                    return Mathf.Lerp(20f, 34f, difficulty);
            }
        }

        private static float ResolveForwardDefenseSpeed(ForwardDefenseType type, float difficulty)
        {
            switch (type)
            {
                case ForwardDefenseType.PulseTurret:
                    return Mathf.Lerp(46f, 74f, difficulty);
                case ForwardDefenseType.ShieldRelay:
                    return Mathf.Lerp(54f, 86f, difficulty);
                case ForwardDefenseType.InterceptorDrone:
                    return Mathf.Lerp(96f, 145f, difficulty);
                case ForwardDefenseType.CommandNode:
                    return Mathf.Lerp(34f, 55f, difficulty);
                default:
                    return Mathf.Lerp(130f, 190f, difficulty);
            }
        }

        private static Color ResolveForwardDefenseColor(ForwardDefenseType type)
        {
            switch (type)
            {
                case ForwardDefenseType.ShieldRelay:
                    return new Color(0.16f, 0.52f, 0.56f, 0.98f);
                case ForwardDefenseType.CommandNode:
                    return new Color(0.54f, 0.10f, 0.08f, 1f);
                default:
                    return new Color(0.62f, 0.12f, 0.10f, 1f);
            }
        }

        private static string ResolveForwardDefenseUnitResourcePath(ForwardDefenseType type)
        {
            switch (type)
            {
                case ForwardDefenseType.PulseTurret:
                    return ForwardDefensePulseTurretResourcePath;
                case ForwardDefenseType.ShieldRelay:
                    return ForwardDefenseShieldRelayResourcePath;
                case ForwardDefenseType.InterceptorDrone:
                    return ForwardDefenseInterceptorDroneResourcePath;
                case ForwardDefenseType.CommandNode:
                    return ForwardDefenseCommandNodeResourcePath;
                default:
                    return ForwardDefenseSentinelScoutResourcePath;
            }
        }

        private void AddForwardDefenseMarks(RectTransform parent, ForwardDefenseType type)
        {
            AddOutline(parent, new Color(1f, 0.16f, 0.08f, 0.55f), new Vector2(3f, -3f));

            RectTransform core = CreatePanel(parent, "DefenseCore", new Color(1f, 0.22f, 0.06f, 0.88f));
            core.anchorMin = new Vector2(0.5f, 0.5f);
            core.anchorMax = new Vector2(0.5f, 0.5f);
            core.pivot = new Vector2(0.5f, 0.5f);
            core.sizeDelta = type == ForwardDefenseType.CommandNode ? new Vector2(40f, 40f) : new Vector2(24f, 24f);
            core.anchoredPosition = Vector2.zero;
            SetRaycastTarget(core, false);

            if (type == ForwardDefenseType.ShieldRelay || type == ForwardDefenseType.CommandNode)
            {
                RectTransform ring = CreatePanel(parent, "DefenseRing", new Color(0.25f, 0.92f, 1f, type == ForwardDefenseType.ShieldRelay ? 0.34f : 0.18f));
                ring.anchorMin = new Vector2(0.5f, 0.5f);
                ring.anchorMax = new Vector2(0.5f, 0.5f);
                ring.pivot = new Vector2(0.5f, 0.5f);
                ring.sizeDelta = parent.sizeDelta * 0.86f;
                ring.anchoredPosition = Vector2.zero;
                SetRaycastTarget(ring, false);
                ring.SetAsFirstSibling();
            }
        }

        private void SpawnStoryMinesLoop(float baseDifficulty)
        {
            if (!storyMinesWavesStarted || minesBossDefeated)
                return;

            if (storyWaveIndex <= 0)
                storyWaveIndex = 1;

            float difficulty = ResolveStoryMinesDifficulty();

            if (storyWaveBreakTimer > 0f)
            {
                storyWaveBreakTimer = Mathf.Max(0f, storyWaveBreakTimer - Time.deltaTime);
                if (statusText != null)
                    statusText.text = "MINES - " + StoryDifficultyLabel(selectedStoryDifficulty) + " - WAVE " + storyWaveIndex + " IN " + Mathf.CeilToInt(storyWaveBreakTimer + 0.05f);
                return;
            }

            storyWaveTimer += Time.deltaTime;

            if (storyWaveIndex < StoryMinesWaveCount && storyWaveTimer >= StoryMinesWaveSeconds)
            {
                storyWaveIndex++;
                storyWaveTimer = 0f;
                storyWaveBreakTimer = StoryMinesWaveBreakSeconds();
                formationTimer = 0.45f;
                spawnTimer = StoryMinesSoloSpawnInterval(difficulty) * 0.85f;
                specialMineTimer = Mathf.Max(specialMineTimer, StoryMinesSpecialMineInterval(difficulty) * 0.75f);
                if (statusText != null)
                    statusText.text = "MINES - " + StoryDifficultyLabel(selectedStoryDifficulty) + " - WAVE " + storyWaveIndex + "/10";
                ShowStoryWaveAnnouncement(storyWaveIndex);
                return;
            }

            if (storyWaveIndex >= StoryMinesWaveCount && storyWaveTimer >= StoryMinesWaveSeconds)
            {
                if (!storyBossFinalWarningPlayed)
                {
                    StartCoroutine(StoryMinesFinalBossRoutine(difficulty));
                    return;
                }

                EnsureMinesBoss(false);
                UpdateMinesBossSpawner(difficulty);
                return;
            }

            if (StoryMinesAllowSpecialMine())
                SpawnStoryMinesSpecialMineLoop(difficulty);

            formationTimer -= Time.deltaTime;
            if (formationTimer <= 0f)
            {
                SpawnStoryMinesFormation(difficulty);
                formationTimer = StoryMinesFormationInterval(difficulty) + RandomRange(-0.45f, 0.75f);
                spawnTimer = Mathf.Max(spawnTimer, StoryMinesSoloSpawnInterval(difficulty) * 0.65f);
                return;
            }

            if (!StoryMinesAllowSoloSpawns())
                return;

            spawnTimer -= Time.deltaTime;
            if (spawnTimer > 0f)
                return;

            spawnTimer = StoryMinesSoloSpawnInterval(difficulty) + RandomRange(-0.25f, 0.45f);
            SpawnHazard(RandomRange(-365f, 365f), random.NextDouble() > 0.84, difficulty, ResolveEnemyFarSpawnY(90f));
        }

        private void SpawnStoryForwardDefenseLoop(float baseDifficulty)
        {
            if (!storyForwardDefenseWavesStarted || storyForwardDefenseComplete)
                return;

            if (storyWaveIndex <= 0)
                storyWaveIndex = 1;

            float difficulty = ResolveStoryForwardDefenseDifficulty();

            if (storyForwardDefenseFinalSpawned)
            {
                if (!HasActiveForwardDefenseHazards())
                    StartCoroutine(StoryForwardDefenseCompleteRoutine());
                return;
            }

            if (storyWaveBreakTimer > 0f)
            {
                storyWaveBreakTimer = Mathf.Max(0f, storyWaveBreakTimer - Time.deltaTime);
                if (statusText != null)
                    statusText.text = "FORWARD DEFENSE - " + StoryDifficultyLabel(selectedStoryDifficulty) + " - WAVE " + storyWaveIndex + " IN " + Mathf.CeilToInt(storyWaveBreakTimer + 0.05f);
                return;
            }

            storyWaveTimer += Time.deltaTime;

            if (storyWaveIndex < StoryForwardDefenseWaveCount && storyWaveTimer >= StoryForwardDefenseWaveSeconds)
            {
                storyWaveIndex++;
                storyWaveTimer = 0f;
                storyWaveBreakTimer = StoryForwardDefenseWaveBreakSeconds();
                spawnTimer = StoryForwardDefenseSpawnInterval(difficulty) * 0.70f;
                formationTimer = StoryForwardDefenseSquadInterval(difficulty) * 0.45f;
                if (statusText != null)
                    statusText.text = "FORWARD DEFENSE - " + StoryDifficultyLabel(selectedStoryDifficulty) + " - WAVE " + storyWaveIndex + "/" + StoryForwardDefenseWaveCount;
                ShowStoryWaveAnnouncement(storyWaveIndex);
                return;
            }

            if (storyWaveIndex >= StoryForwardDefenseWaveCount && storyWaveTimer >= StoryForwardDefenseWaveSeconds)
            {
                SpawnStoryForwardDefenseCommandNode(difficulty);
                return;
            }

            formationTimer -= Time.deltaTime;
            if (formationTimer <= 0f)
            {
                SpawnStoryForwardDefenseSquad(difficulty);
                formationTimer = StoryForwardDefenseSquadInterval(difficulty) + RandomRange(-0.35f, 0.65f);
                spawnTimer = Mathf.Max(spawnTimer, StoryForwardDefenseSpawnInterval(difficulty) * 0.55f);
                return;
            }

            spawnTimer -= Time.deltaTime;
            if (spawnTimer > 0f)
                return;

            SpawnForwardDefenseUnit(ResolveStoryForwardDefenseType(difficulty), RandomStoryForwardDefenseX(), difficulty, ResolveEnemyFarSpawnY(94f));
            spawnTimer = StoryForwardDefenseSpawnInterval(difficulty) + RandomRange(-0.25f, 0.45f);
        }

        private ForwardDefenseType ResolveStoryForwardDefenseType(float difficulty)
        {
            double roll = random.NextDouble();
            if (storyWaveIndex >= 5 && roll > 0.74)
                return ForwardDefenseType.InterceptorDrone;
            if (storyWaveIndex >= 3 && roll > 0.56)
                return ForwardDefenseType.ShieldRelay;
            if (storyWaveIndex >= 2 && roll > 0.30 + difficulty * 0.10f)
                return ForwardDefenseType.PulseTurret;
            return ForwardDefenseType.SentinelScout;
        }

        private void SpawnStoryForwardDefenseSquad(float difficulty)
        {
            float centerX = RandomStoryForwardDefenseX();
            float laneGap = Mathf.Lerp(92f, 132f, difficulty);
            int count = storyWaveIndex >= 5 ? 4 : storyWaveIndex >= 3 ? 3 : 2;
            ForwardDefenseType support = storyWaveIndex >= 4 && random.NextDouble() > 0.45 ? ForwardDefenseType.ShieldRelay : ForwardDefenseType.PulseTurret;

            for (int i = 0; i < count; i++)
            {
                float offset = (i - (count - 1) * 0.5f) * laneGap;
                ForwardDefenseType type = i == 0 && storyWaveIndex >= 5 ? ForwardDefenseType.InterceptorDrone : ResolveStoryForwardDefenseType(difficulty);
                if (i == count - 1 && storyWaveIndex >= 3)
                    type = support;

                SpawnForwardDefenseUnit(type, Mathf.Clamp(centerX + offset, -390f, 390f), difficulty, ResolveEnemyFarSpawnY(92f + i * 12f));
            }

            if (statusText != null)
                statusText.text = "FORWARD DEFENSE SQUAD";
        }

        private void SpawnStoryForwardDefenseCommandNode(float difficulty)
        {
            if (storyForwardDefenseFinalSpawned)
                return;

            CleanupHazards();
            storyForwardDefenseFinalSpawned = true;
            SpawnForwardDefenseUnit(ForwardDefenseType.CommandNode, 0f, Mathf.Clamp01(difficulty + 0.18f), ResolveEnemyFarSpawnY(112f));
            SpawnForwardDefenseUnit(ForwardDefenseType.ShieldRelay, -168f, difficulty, ResolveEnemyFarSpawnY(92f));
            SpawnForwardDefenseUnit(ForwardDefenseType.ShieldRelay, 168f, difficulty, ResolveEnemyFarSpawnY(92f));
            if (statusText != null)
                statusText.text = "COMMAND NODE ONLINE";
        }

        private float RandomStoryForwardDefenseX()
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            float halfWidth = root != null ? Mathf.Min(390f, root.rect.width * 0.5f - 64f) : 365f;
            return RandomRange(-halfWidth, halfWidth);
        }

        private bool HasActiveForwardDefenseHazards()
        {
            for (int i = 0; i < hazards.Count; i++)
            {
                HazardView hazard = hazards[i];
                if (hazard != null && hazard.ForwardDefense != ForwardDefenseType.None && hazard.Root != null)
                    return true;
            }

            return false;
        }

        private IEnumerator StoryForwardDefenseCompleteRoutine()
        {
            if (storyForwardDefenseComplete)
                yield break;

            storyForwardDefenseComplete = true;
            storyForwardDefenseWavesStarted = false;
            storyCinematicActive = true;
            HideStoryWaveBanner();
            CleanupHazards();
            score += StoryForwardDefenseScore;

            if (statusText != null)
                statusText.text = "FORWARD DEFENSE BROKEN";

            ShowStoryDialog("СТАНЦИЯ", "Первый слой обороны отключён. Коридор за минным фронтом открыт.", null);
            yield return WaitStoryDialogSeconds(2.1f);
            ShowPlayerStoryDialog("Значит, дальше нас ждёт не поле мин, а настоящая система обороны.", null);
            yield return WaitStoryDialogSeconds(2.0f);
            HideStoryDialog();

            storyCinematicActive = false;
            if (statusText != null)
                statusText.text = "FORWARD DEFENSE COMPLETE";
            RefreshHud();
        }

        private void SpawnStoryMinesFormation(float difficulty)
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return;

            float halfWidth = Mathf.Min(390f, root.rect.width * 0.5f - 54f);
            int formation = random.Next(0, 7);
            if (formation == lastFormation)
                formation = (formation + random.Next(1, 7)) % 7;
            lastFormation = formation;

            Vector2[] offsets = GetFormationOffsets(formation, difficulty, StoryMinesFormationCount(difficulty));
            float jitter = selectedStoryDifficulty == StoryDifficulty.Easy ? Mathf.Lerp(0.15f, 1.1f, difficulty) : Mathf.Lerp(0.35f, 1.8f, difficulty);
            float speed = selectedStoryDifficulty == StoryDifficulty.Easy
                ? Mathf.Lerp(112f, 188f, difficulty) + RandomRange(-4f, 7f)
                : Mathf.Lerp(135f, 238f, difficulty) + RandomRange(-6f, 9f);
            float size = selectedStoryDifficulty == StoryDifficulty.Easy ? RandomRange(78f, 86f) : RandomRange(82f, 92f);
            SpawnFormationOffsets(offsets, halfWidth, jitter, difficulty, speed, size);

            if (statusText != null)
                statusText.text = "MINES FORMATION";
        }

        private void SpawnStoryMinesSpecialMineLoop(float difficulty)
        {
            specialMineTimer -= Time.deltaTime;
            if (specialMineTimer > 0f)
                return;

            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            float halfWidth = root != null ? Mathf.Min(390f, root.rect.width * 0.5f - 58f) : 365f;
            bool heavy = storyWaveIndex >= 8 && random.NextDouble() > (selectedStoryDifficulty == StoryDifficulty.Easy ? 0.82 : 0.48);
            int forcedMineType = heavy ? 2 : 1;
            float size = forcedMineType == 2 ? RandomRange(96f, 106f) : RandomRange(78f, 88f);
            float speed = forcedMineType == 2
                ? Mathf.Lerp(62f, 92f, difficulty) + RandomRange(-4f, 6f)
                : Mathf.Lerp(78f, 118f, difficulty) + RandomRange(-6f, 8f);

            SpawnHazard(RandomRange(-halfWidth, halfWidth), false, difficulty, ResolveEnemyFarSpawnY(94f), speed, size, false, forcedMineType);
            specialMineTimer = StoryMinesSpecialMineInterval(difficulty) + RandomRange(0.5f, 2.0f);
        }

        private void SpawnEndlessSpecialMineLoop(float difficulty)
        {
            specialMineTimer -= Time.deltaTime;
            if (specialMineTimer > 0f)
                return;

            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            float halfWidth = root != null ? Mathf.Min(390f, root.rect.width * 0.5f - 58f) : 365f;
            int forcedMineType = random.NextDouble() < Mathf.Lerp(0.62f, 0.46f, difficulty) ? 1 : 2;
            float size = forcedMineType == 2 ? RandomRange(104f, 118f) : RandomRange(88f, 98f);
            float speed = forcedMineType == 2
                ? Mathf.Lerp(72f, 112f, difficulty) + RandomRange(-5f, 8f)
                : Mathf.Lerp(88f, 135f, difficulty) + RandomRange(-8f, 12f);

            SpawnHazard(RandomRange(-halfWidth, halfWidth), false, difficulty, ResolveEnemyFarSpawnY(94f), speed, size, false, forcedMineType);
            specialMineTimer = Mathf.Lerp(8.6f, 4.8f, difficulty) + RandomRange(-0.8f, 1.4f);
        }

        private void EnsureMinesBoss(bool closeUp)
        {
            if (minesBoss != null)
                return;

            GameObject go = new GameObject("MinesCarrierBoss", typeof(RectTransform), typeof(CanvasRenderer), typeof(Image));
            go.transform.SetParent(playfield, false);
            minesBoss = go.GetComponent<RectTransform>();
            minesBoss.anchorMin = new Vector2(0.5f, 1f);
            minesBoss.anchorMax = new Vector2(0.5f, 1f);
            minesBoss.pivot = new Vector2(0.5f, 0.5f);
            minesBoss.sizeDelta = MinesBossUiSize(closeUp);
            minesBossBaseY = closeUp ? StoryMinesBossCloseUpY : StoryMinesBossSpawnY;
            minesBossTargetY = minesBossBaseY;
            minesBoss.anchoredPosition = closeUp ? new Vector2(0f, 260f) : new Vector2(0f, StoryMinesBossSpawnY);

            Image image = go.GetComponent<Image>();
            image.raycastTarget = false;
            Sprite bossSprite = GetSpriteFromTextureResource(MinesBossSpriteResourcePath);
            if (bossSprite != null)
            {
                image.sprite = bossSprite;
                image.color = Color.white;
                image.preserveAspect = true;
            }
            else
            {
                image.color = new Color(0.20f, 0.02f, 0.04f, 0.92f);
                AddOutline(minesBoss, new Color(1f, 0.12f, 0.08f, 0.65f), new Vector2(3f, -3f));
            }

            minesBoss.SetAsFirstSibling();
            EnsureMinesBossCracks();
            minesBossActive = true;
            MarkBestiaryEncounter(OrbiosisBestiaryLibrary.MinesCarrier);
            minesBossSpawnTimer = 0.65f;
            if (minesBossMaxHealth <= 0f)
                minesBossMaxHealth = StoryMinesBossMaxHealth();
            if (minesBossHealth <= 0f)
                minesBossHealth = minesBossMaxHealth;
            if (statusText != null)
                statusText.text = "MINES BOSS - WAVE 10/10";
        }

        private void UpdateMinesBossSpawner(float difficulty)
        {
            if (!minesBossActive || minesBossDefeated || minesBoss == null)
                return;

            minesBossBaseY = Mathf.MoveTowards(minesBossBaseY, minesBossTargetY, 150f * Time.deltaTime);
            float hover = Mathf.Sin(Time.time * 1.7f) * 10f;
            Vector2 shake = Vector2.zero;
            if (minesBossSpawnShakeTimer > 0f)
            {
                minesBossSpawnShakeTimer = Mathf.Max(0f, minesBossSpawnShakeTimer - Time.deltaTime);
                float strength = Mathf.Clamp01(minesBossSpawnShakeTimer / StoryMinesBossSpawnShakeSeconds);
                shake = new Vector2(
                    Mathf.Sin(Time.time * 92f) * StoryMinesBossSpawnShakePixels * strength,
                    Mathf.Cos(Time.time * 77f) * StoryMinesBossSpawnShakePixels * 0.45f * strength);
            }

            minesBoss.anchoredPosition = new Vector2(Mathf.Sin(Time.time * 0.55f) * 34f, minesBossBaseY + hover) + shake;
            UpdateMinesBossHitTint();

            if (!minesBossDamageable)
            {
                UpdateMinesBossPhaseIntro(difficulty);
                return;
            }

            minesBossSpawnTimer -= Time.deltaTime;
            if (minesBossSpawnTimer > 0f)
                return;

            minesBossSpawnTimer = StoryMinesBossMineInterval() + RandomRange(-0.28f, 0.34f);
            Vector2 bossPos = minesBoss.anchoredPosition;
            float mineSize = Mathf.Lerp(88f, 112f, difficulty);
            float speed = Mathf.Lerp(175f, 335f, difficulty);
            int barrel = minesBossBarrelIndex % 3;
            minesBossBarrelIndex++;

            SpawnMinesBossBarrelMine(barrel, bossPos, difficulty, speed, mineSize);
            if (ShouldMinesBossDoubleFire())
                SpawnMinesBossBarrelMine(minesBossBarrelIndex++ % 3, bossPos, difficulty, speed, mineSize);

            minesBossSpawnShakeTimer = StoryMinesBossSpawnShakeSeconds;
        }

        private void UpdateMinesBossPhaseIntro(float difficulty)
        {
            if (minesBossPhaseWaitingForClear)
            {
                if (CountMinesBossPhaseMinions() > 0)
                {
                    if (statusText != null)
                        statusText.text = "CLEAR CARRIER FORMATION " + Mathf.Clamp(minesBossPhaseIndex + 1, 1, StoryMinesBossPhaseCount) + "/3";
                    return;
                }

                minesBossPhaseWaitingForClear = false;
                minesBossPhaseIndex++;
                minesBossTargetY = StoryMinesBossPhaseY(minesBossPhaseIndex);
                minesBossPhaseTimer = StoryMinesBossPhasePause;
                minesBossSpawnShakeTimer = StoryMinesBossSpawnShakeSeconds;

                if (minesBossPhaseIndex >= StoryMinesBossPhaseCount)
                {
                    minesBossDamageable = true;
                    minesBossTargetY = StoryMinesBossCloseUpY;
                    minesBossSpawnTimer = 1.65f;
                    if (statusText != null)
                        statusText.text = "CARRIER HULL EXPOSED";
                }

                return;
            }

            minesBossPhaseTimer -= Time.deltaTime;
            if (minesBossPhaseTimer > 0f)
                return;

            SpawnMinesBossPhaseParty(minesBossPhaseIndex, difficulty);
            minesBossPhaseWaitingForClear = true;
            minesBossSpawnShakeTimer = StoryMinesBossSpawnShakeSeconds;
            if (statusText != null)
                statusText.text = "CARRIER FORMATION " + Mathf.Clamp(minesBossPhaseIndex + 1, 1, StoryMinesBossPhaseCount) + "/3";
        }

        private int CountMinesBossPhaseMinions()
        {
            int count = 0;
            for (int i = 0; i < hazards.Count; i++)
            {
                HazardView hazard = hazards[i];
                if (hazard.Root != null && hazard.BossPhaseMinion)
                    count++;
            }

            return count;
        }

        private void SpawnMinesBossPhaseParty(int phase, float difficulty)
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return;

            float halfWidth = Mathf.Min(390f, root.rect.width * 0.5f - 54f);
            int[] mineTypes;
            int formation;
            switch (phase)
            {
                case 1:
                    mineTypes = new[] { 3, 1, 3, 1, 3, 3 };
                    formation = 3;
                    break;
                case 2:
                    mineTypes = new[] { 3, 1, 2, 3, 1, 3, 2 };
                    formation = 6;
                    break;
                default:
                    mineTypes = new[] { 3, 3, 3, 3, 3 };
                    formation = 1;
                    break;
            }

            Vector2[] offsets = GetFormationOffsets(formation, difficulty, mineTypes.Length);
            float minX = offsets[0].x;
            float maxX = offsets[0].x;
            for (int i = 1; i < offsets.Length; i++)
            {
                minX = Mathf.Min(minX, offsets[i].x);
                maxX = Mathf.Max(maxX, offsets[i].x);
            }

            float width = maxX - minX;
            float center = RandomRange(-halfWidth + width * 0.5f, halfWidth - width * 0.5f);
            Vector2 gateOrigin = GetMinesBossPhaseSpawnOrigin(phase);
            float startY = gateOrigin.y;
            float speed = Mathf.Lerp(118f, 205f, difficulty) + phase * 18f;
            float size = Mathf.Lerp(82f, 98f, difficulty);

            for (int i = 0; i < offsets.Length; i++)
            {
                int type = mineTypes[Mathf.Min(i, mineTypes.Length - 1)];
                float x = Mathf.Clamp(gateOrigin.x + (center * 0.18f) + offsets[i].x + RandomRange(-0.6f, 0.6f), -halfWidth, halfWidth);
                float y = startY - Mathf.Abs(offsets[i].y) * 0.28f - i * 5.5f;
                float mineSize = type == 2 ? size + 16f : type == 1 ? size + 6f : size;
                float mineSpeed = type == 2 ? speed * 0.70f : type == 1 ? speed * 0.88f : speed;
                SpawnHazard(x, false, difficulty, y, mineSpeed, mineSize, true, type, true);
            }
        }

        private Vector2 GetMinesBossPhaseSpawnOrigin(int phase)
        {
            int barrel = phase % 3;
            return (minesBoss != null ? minesBoss.anchoredPosition : Vector2.zero) + MinesBossBarrelSpawnLocalPosition(barrel) + new Vector2(0f, -18f);
        }

        private bool ShouldMinesBossDoubleFire()
        {
            switch (selectedStoryDifficulty)
            {
                case StoryDifficulty.Medium:
                    return minesBossHealth < minesBossMaxHealth * 0.55f && random.NextDouble() > 0.72;
                case StoryDifficulty.Hardcore:
                    return minesBossHealth < minesBossMaxHealth * 0.75f && random.NextDouble() > 0.50;
                default:
                    return minesBossHealth < minesBossMaxHealth * 0.35f && random.NextDouble() > 0.88;
            }
        }

        private void SpawnMinesBossBarrelMine(int barrel, Vector2 bossPos, float difficulty, float speed, float mineSize)
        {
            Vector2 barrelOffset = MinesBossBarrelSpawnLocalPosition(barrel);
            switch (barrel)
            {
                case 1:
                    SpawnHazard(bossPos.x + barrelOffset.x, false, difficulty, bossPos.y + barrelOffset.y, speed + 18f, mineSize + 4f, false, 1);
                    break;
                case 2:
                    SpawnHazard(bossPos.x + barrelOffset.x, false, difficulty, bossPos.y + barrelOffset.y, speed * 0.72f, mineSize + 14f, false, 2);
                    break;
                default:
                    SpawnHazard(bossPos.x + barrelOffset.x, false, difficulty, bossPos.y + barrelOffset.y, speed, mineSize, false, 3);
                    break;
            }
        }

        private Vector2 MinesBossBarrelLocalPosition(int barrel)
        {
            Vector2 size = minesBoss != null ? minesBoss.sizeDelta : MinesBossUiSize(true);
            switch (barrel)
            {
                case 1:
                    return new Vector2(0f, size.y * MinesBossGateCenterYFraction);
                case 2:
                    return new Vector2(size.x * MinesBossGateSideXFraction, size.y * MinesBossGateSideYFraction);
                default:
                    return new Vector2(-size.x * MinesBossGateSideXFraction, size.y * MinesBossGateSideYFraction);
            }
        }

        private Vector2 MinesBossBarrelSpawnLocalPosition(int barrel)
        {
            return MinesBossBarrelLocalPosition(barrel) + new Vector2(0f, MinesBossGateSpawnYOffset);
        }

        private void UpdateMinesBossHitTint()
        {
            if (minesBoss == null)
                return;

            Image image = minesBoss.GetComponent<Image>();
            if (image == null)
                return;

            float damage = minesBossDamageable ? 1f - Mathf.Clamp01(minesBossHealth / Mathf.Max(1f, minesBossMaxHealth)) : 0f;
            Color baseColor = minesBossDamageable
                ? Color.Lerp(Color.white, new Color(1f, 0.24f, 0.18f, 1f), damage * 0.78f)
                : Color.Lerp(Color.white, new Color(0.62f, 0.78f, 1f, 1f), 0.28f);

            if (minesBossHitFeedbackTimer > 0f)
            {
                minesBossHitFeedbackTimer = Mathf.Max(0f, minesBossHitFeedbackTimer - Time.deltaTime);
                float pulse = 0.5f + Mathf.Sin(Time.time * 36f) * 0.5f;
                baseColor = Color.Lerp(baseColor, new Color(1f, 0.36f, 0.26f, 1f), 0.24f + pulse * 0.32f);
            }

            baseColor.a = 1f;
            image.color = baseColor;
            UpdateMinesBossCrackState(damage);
            UpdateMinesBossShortCircuits(damage);
        }

        private void EnsureMinesBossCracks()
        {
            if (minesBoss == null || minesBossCracks.Count > 0)
                return;

            CreateMinesBossCrack(new Vector2(-155f, -60f), 86f, -34f);
            CreateMinesBossCrack(new Vector2(138f, -76f), 78f, 28f);
            CreateMinesBossCrack(new Vector2(-58f, -170f), 104f, 12f);
            CreateMinesBossCrack(new Vector2(74f, -154f), 92f, -18f);
            CreateMinesBossCrack(new Vector2(-220f, -210f), 76f, 40f);
            CreateMinesBossCrack(new Vector2(228f, -206f), 82f, -42f);
        }

        private void CreateMinesBossCrack(Vector2 position, float length, float angle)
        {
            RectTransform crack = CreatePanel(minesBoss, "BossHullCrack", new Color(1f, 0.09f, 0.04f, 0.82f));
            crack.anchorMin = new Vector2(0.5f, 0.5f);
            crack.anchorMax = new Vector2(0.5f, 0.5f);
            crack.pivot = new Vector2(0.5f, 0.5f);
            crack.anchoredPosition = position;
            crack.sizeDelta = new Vector2(4.5f, length);
            crack.localRotation = Quaternion.Euler(0f, 0f, angle);
            Image image = crack.GetComponent<Image>();
            if (image != null)
                image.raycastTarget = false;
            crack.gameObject.SetActive(false);
            minesBossCracks.Add(crack);
        }

        private void UpdateMinesBossCrackState(float damage)
        {
            for (int i = 0; i < minesBossCracks.Count; i++)
            {
                RectTransform crack = minesBossCracks[i];
                if (crack == null)
                    continue;

                bool visible = minesBossDamageable && damage >= 0.20f + i * 0.105f;
                crack.gameObject.SetActive(visible);
                if (!visible)
                    continue;

                Image image = crack.GetComponent<Image>();
                if (image != null)
                {
                    float flicker = 0.5f + Mathf.Sin(Time.time * (14f + i * 3.2f)) * 0.5f;
                    image.color = new Color(1f, Mathf.Lerp(0.05f, 0.30f, flicker), 0.03f, Mathf.Lerp(0.48f, 0.95f, damage));
                }
            }
        }

        private void UpdateMinesBossShortCircuits(float damage)
        {
            if (!minesBossDamageable || damage < 0.45f)
                return;

            minesBossShortCircuitTimer -= Time.deltaTime;
            if (minesBossShortCircuitTimer > 0f)
                return;

            minesBossShortCircuitTimer = Mathf.Lerp(1.15f, 0.34f, Mathf.Clamp01((damage - 0.45f) / 0.55f));
            Vector2 center = GetCanvasLocalPosition(minesBoss);
            center.y -= Mathf.Max(80f, minesBoss.sizeDelta.y * 0.30f);
            Vector2 from = center + new Vector2(RandomRange(-220f, 220f), RandomRange(-145f, 65f));
            Vector2 to = from + new Vector2(RandomRange(-46f, 46f), RandomRange(-38f, 42f));
            SpawnArcSegment(from, to, Mathf.Lerp(0.45f, 0.90f, damage), Mathf.Lerp(4.2f, 7.5f, damage));
        }

        private bool TryGetMinesBossTargetPosition(out Vector2 target)
        {
            target = Vector2.zero;
            if (!minesBossActive || minesBossDefeated || minesBoss == null)
                return false;

            target = MinesBossCanvasPoint(minesBossDamageable ? new Vector2(0f, -92f) : MinesBossBarrelSpawnLocalPosition(1));
            return true;
        }

        private bool TryHitMinesBoss(ProjectileView projectile)
        {
            if (projectile == null || projectile.Root == null)
                return false;
            if (!TryGetMinesBossTargetPosition(out Vector2 bossTarget))
                return false;

            Vector2 shotPos = projectile.Root.anchoredPosition;
            if (!IsMinesBossHitZone(shotPos, projectile.Radius))
                return false;

            if (!minesBossDamageable)
            {
                minesBossSpawnShakeTimer = Mathf.Max(minesBossSpawnShakeTimer, StoryMinesBossSpawnShakeSeconds * 0.45f);
                if (statusText != null)
                    statusText.text = L("status.carrier_gates_locked");
                return true;
            }

            DamageMinesBoss(projectile.ArcBall ? ArcChainDamage : CoreProjectileDamage);
            return true;
        }

        private Vector2 MinesBossCanvasPoint(Vector2 localPoint)
        {
            return GetCanvasLocalPosition(minesBoss) + localPoint;
        }

        private bool IsMinesBossHitZone(Vector2 shotPos, float projectileRadius)
        {
            if (minesBoss == null)
                return false;

            Vector2 local = shotPos - GetCanvasLocalPosition(minesBoss);
            float padding = projectileRadius + StoryMinesBossHullHitPadding;

            if (!minesBossDamageable)
            {
                return Vector2.Distance(local, MinesBossBarrelSpawnLocalPosition(0)) <= projectileRadius + StoryMinesBossGateHitRadius
                    || Vector2.Distance(local, MinesBossBarrelSpawnLocalPosition(1)) <= projectileRadius + StoryMinesBossGateHitRadius
                    || Vector2.Distance(local, MinesBossBarrelSpawnLocalPosition(2)) <= projectileRadius + StoryMinesBossGateHitRadius;
            }

            return PointInEllipse(local, new Vector2(0f, -96f), 172f + padding, 245f + padding)
                || PointInEllipse(local, new Vector2(-255f, -142f), 155f + padding, 118f + padding)
                || PointInEllipse(local, new Vector2(255f, -142f), 155f + padding, 118f + padding)
                || PointInEllipse(local, new Vector2(0f, 78f), 245f + padding, 122f + padding);
        }

        private static bool PointInEllipse(Vector2 point, Vector2 center, float radiusX, float radiusY)
        {
            if (radiusX <= 0f || radiusY <= 0f)
                return false;

            float x = (point.x - center.x) / radiusX;
            float y = (point.y - center.y) / radiusY;
            return x * x + y * y <= 1f;
        }

        private void DamageMinesBoss(float damage)
        {
            if (!minesBossActive || minesBossDefeated || minesBoss == null || !minesBossDamageable)
                return;

            minesBossHealth = Mathf.Max(0f, minesBossHealth - Mathf.Max(1f, damage));
            minesBossHitFeedbackTimer = HazardHitFeedbackSeconds;
            if (minesBossHealth > 0f)
            {
                if (statusText != null)
                {
                    int percent = Mathf.CeilToInt(minesBossHealth / Mathf.Max(1f, minesBossMaxHealth) * 100f);
                    statusText.text = "CARRIER HULL " + percent + "%";
                }

                return;
            }

            minesBossDefeated = true;
            minesBossActive = false;
            score += StoryMinesBossScore;
            StartCoroutine(StoryMinesBossDefeatedRoutine());
        }

        private IEnumerator StoryMinesBossDefeatedRoutine()
        {
            storyCinematicActive = true;
            storyMinesWavesStarted = false;
            HideStoryWaveBanner();
            if (statusText != null)
                statusText.text = "MINES CARRIER DESTROYED";

            yield return null;

            if (minesBoss != null)
            {
                Vector2 blastCenter = GetCanvasLocalPosition(minesBoss);
                blastCenter.y -= Mathf.Max(110f, minesBoss.sizeDelta.y * 0.36f);
                SpawnMineExplosion(blastCenter + new Vector2(-95f, 35f));
                SpawnMineExplosion(blastCenter + new Vector2(0f, -20f));
                SpawnMineExplosion(blastCenter + new Vector2(105f, 32f));
                PlayEnemyDeathSound();
            }

            CleanupHazards();
            ShowStoryDialog(L("speaker.mine_carrier"), L("dialog.mine_end"), null);
            yield return WaitStoryDialogSeconds(2.4f);
            ShowPlayerStoryDialog(L("dialog.mine_end_player"), null);
            yield return WaitStoryDialogSeconds(1.8f);
            HideStoryDialog();

            if (minesBoss != null)
                yield return MoveMinesBoss(new Vector2(0f, StoryMinesBossCloseUpY + 620f), 0.9f);

            bool mineLayerUnlocked = selectedMode == GameMode.Story && selectedStoryLevel == StoryLevel.Mines && selectedStoryDifficulty == StoryDifficulty.Hardcore && UnlockMineLayerDroneReward();

            CleanupMinesBoss();
            storyCinematicActive = false;
            if (statusText != null)
                statusText.text = mineLayerUnlocked ? L("status.mine_layer_unlocked") : L("status.mines_complete");
            RefreshHud();
            RefreshUpgradeLabels();
        }

        private bool UnlockMineLayerDroneReward()
        {
            PlayerPrefs.SetInt(StoryMinesHardcoreCompleteKey, 1);
            if (mineLayerDroneOwned)
            {
                PlayerPrefs.Save();
                return false;
            }

            mineLayerDroneOwned = true;
            PlayerPrefs.SetInt(MineLayerDroneOwnedKey, 1);
            PlayerPrefs.Save();
            if (statusText != null)
                statusText.text = L("status.mine_layer_unlocked");
            return true;
        }

        private void SpawnHazardFormation(float difficulty, bool story)
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return;

            float halfWidth = Mathf.Min(390f, root.rect.width * 0.5f - 54f);
            int formation = random.Next(0, 7);
            if (formation == lastFormation)
                formation = (formation + random.Next(1, 7)) % 7;
            lastFormation = formation;

            int maxCount = story ? Mathf.Clamp(4 + Mathf.FloorToInt(difficulty * 3.5f), 4, 7) : Mathf.Clamp(3 + Mathf.FloorToInt(elapsed / 18f), 3, 7);
            Vector2[] offsets = GetFormationOffsets(formation, difficulty, maxCount);
            float jitter = story ? Mathf.Lerp(0.5f, 2.4f, difficulty) : Mathf.Lerp(0.2f, 1.2f, difficulty);
            float formationSpeed = story ? Mathf.Lerp(165f, 295f, difficulty) + RandomRange(-8f, 8f) : Mathf.Lerp(145f, 285f, difficulty) + RandomRange(-5f, 7f);
            float formationSize = story ? RandomRange(88f, 96f) : RandomRange(84f, 92f);
            SpawnFormationOffsets(offsets, halfWidth, jitter, difficulty, formationSpeed, formationSize);

            if (statusText != null)
                statusText.text = "ENEMY FORMATION";
        }

        private static Vector2[] GetFormationOffsets(int formation, float difficulty, int maxCount)
        {
            float s = Mathf.Lerp(70f, 78f, difficulty);
            float y = Mathf.Lerp(56f, 66f, difficulty);
            Vector2[] offsets;

            switch (formation)
            {
                case 0:
                    offsets = new[]
                    {
                        new Vector2(0f, 0f), new Vector2(-s, 0f), new Vector2(s, 0f), new Vector2(-2f * s, 0f), new Vector2(2f * s, 0f), new Vector2(-3f * s, 0f), new Vector2(3f * s, 0f)
                    };
                    break;
                case 1:
                    offsets = new[]
                    {
                        new Vector2(0f, 0f), new Vector2(-s, 0f), new Vector2(s, 0f),
                        new Vector2(0f, y), new Vector2(-s, y), new Vector2(s, y), new Vector2(0f, 2f * y)
                    };
                    break;
                case 2:
                    offsets = new[]
                    {
                        new Vector2(0f, 0f),
                        new Vector2(-s, y), new Vector2(s, y),
                        new Vector2(-2f * s, 2f * y), new Vector2(2f * s, 2f * y),
                        new Vector2(-3f * s, 3f * y), new Vector2(3f * s, 3f * y)
                    };
                    break;
                case 3:
                    offsets = new[]
                    {
                        new Vector2(-0.5f * s, y), new Vector2(0.5f * s, y),
                        new Vector2(-1.5f * s, 0f), new Vector2(1.5f * s, 0f),
                        new Vector2(-1.5f * s, 2f * y), new Vector2(1.5f * s, 2f * y),
                        new Vector2(0f, 3f * y)
                    };
                    break;
                case 4:
                    offsets = new[]
                    {
                        new Vector2(0f, 0f), new Vector2(-s, 0.4f * y), new Vector2(s, 0.4f * y),
                        new Vector2(-2f * s, 1.4f * y), new Vector2(2f * s, 1.4f * y),
                        new Vector2(-3f * s, 2.2f * y), new Vector2(3f * s, 2.2f * y)
                    };
                    break;
                case 5:
                    offsets = new[]
                    {
                        new Vector2(-0.5f * s, 0f), new Vector2(0.5f * s, 0f), new Vector2(0f, y),
                        new Vector2(-1.5f * s, 0f), new Vector2(1.5f * s, 0f),
                        new Vector2(-s, y), new Vector2(s, y)
                    };
                    break;
                default:
                    offsets = new[]
                    {
                        new Vector2(0f, y), new Vector2(-s, 0f), new Vector2(s, 0f),
                        new Vector2(-2f * s, y), new Vector2(2f * s, y),
                        new Vector2(-s, 2f * y), new Vector2(s, 2f * y)
                    };
                    break;
            }

            int count = Mathf.Clamp(maxCount, 3, offsets.Length);
            if (count >= offsets.Length)
                return offsets;

            Vector2[] trimmed = new Vector2[count];
            for (int i = 0; i < count; i++)
                trimmed[i] = offsets[i];
            return trimmed;
        }

        private void SpawnFormationOffsets(Vector2[] offsets, float halfWidth, float jitter, float difficulty, float speed, float size)
        {
            if (offsets == null || offsets.Length == 0)
                return;

            float minX = offsets[0].x;
            float maxX = offsets[0].x;
            for (int i = 1; i < offsets.Length; i++)
            {
                minX = Mathf.Min(minX, offsets[i].x);
                maxX = Mathf.Max(maxX, offsets[i].x);
            }

            float mirror = random.NextDouble() > 0.5 ? 1f : -1f;
            float width = maxX - minX;
            float center = RandomRange(-halfWidth + width * 0.5f, halfWidth - width * 0.5f);
            float startY = ResolveEnemyFarSpawnY(94f);
            for (int i = 0; i < offsets.Length; i++)
            {
                float x = Mathf.Clamp(center + offsets[i].x * mirror + RandomRange(-jitter, jitter), -halfWidth, halfWidth);
                float y = startY + offsets[i].y;
                SpawnHazard(x, false, difficulty, y, speed, size, true);
            }
        }

        private float ResolveEnemyFarSpawnY(float baseY)
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            float height = root != null ? root.rect.height : 1600f;
            return baseY + height * EnemyFarSpawnScreenFraction;
        }

        private void FireLoop()
        {
            if (tutorialCannonSuppressed || !IsCoreCannonActive())
                return;

            fireTimer -= Time.deltaTime * QueenBuffRate(coreCannon);
            if (fireTimer > 0f || orb == null || playfield == null)
                return;

            fireTimer = CurrentFireInterval();
            Vector2 origin = GetCoreCannonFireOrigin();
            if (IsOrbAtBase())
            {
                Vector2? target = FindNearestEnemyTarget(origin, CurrentProjectileSpeed());
                if (!target.HasValue)
                    return;
                if (!coreCannonAimed)
                    return;

                PlayCoreCannonShotSound();
                SpawnProjectile(origin, GetCoreCannonDirection());
                return;
            }

            PlayCoreCannonShotSound();
            SpawnProjectile(origin, GetCoreCannonDirection());
        }

        private Vector2 GetCoreCannonFireOrigin()
        {
            if (coreCannon == null || !coreCannon.gameObject.activeSelf)
                return orb != null ? orb.anchoredPosition + new Vector2(0f, 33f) : new Vector2(0f, -250f);

            Vector2 direction = GetCoreCannonDirection();
            return GetCanvasLocalPosition(coreCannon) + direction * Mathf.Max(22f, coreCannon.sizeDelta.y * 0.42f);
        }

        private Vector2 GetCoreCannonDirection()
        {
            if (coreCannon == null)
                return Vector2.up;

            Vector3 up = coreCannon.TransformDirection(Vector3.up);
            Vector2 direction = new Vector2(up.x, up.y);
            return direction.sqrMagnitude > 0.01f ? direction.normalized : Vector2.up;
        }

        private bool HasWeaponModuleEquipped()
        {
            return IsHomingMissileModuleActive() || IsLaserModuleActive() || IsArcChainModuleActive() || IsRailSpikeModuleActive();
        }

        private void HomingMissileLoop()
        {
            if (!IsHomingMissileModuleActive() || homingMissileModule == null || !homingMissileModule.gameObject.activeSelf)
                return;

            homingMissileTimer -= Time.deltaTime * QueenBuffRate(homingMissileModule);
            if (homingMissileTimer > 0f)
                return;

            if (!homingMissileModuleAimed)
                return;

            Vector2 fireDirection = GetHomingMissileModuleFireDirection();
            Vector2 origin = GetCanvasLocalPosition(homingMissileModule) + fireDirection * 14f;
            Vector2? target = FindNearestMissileTarget(origin);
            if (!target.HasValue)
                return;
            if (!TryConsumeModuleShot("HOMING NEEDS OZPARTS"))
                return;

            homingMissileTimer = HomingMissileCooldown;
            PlayRocketShotSound();
            SpawnHomingMissile(origin, fireDirection);
        }

        private void LaserModuleLoop()
        {
            if (!IsLaserModuleActive() || laserModule == null || !laserModule.gameObject.activeSelf)
            {
                HideLaserModuleBeam();
                CoolLaserModule(false);
                return;
            }

            if (laserModuleOverheated)
            {
                HideLaserModuleBeam();
                CoolLaserModule(true);
                return;
            }

            Vector2 origin = GetCanvasLocalPosition(laserModule) + GetLaserModuleFireDirection() * 13f;
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
            {
                HideLaserModuleBeam();
                CoolLaserModule(false);
                return;
            }

            int targetIndex = ResolveLaserTargetIndex(origin, root, out Vector2 targetPos);
            if (targetIndex < 0)
            {
                HideLaserModuleBeam();
                CoolLaserModule(false);
                return;
            }

            HazardView target = hazards[targetIndex];
            if (target.Root == null)
            {
                laserTargetIndex = -1;
                HideLaserModuleBeam();
                CoolLaserModule(false);
                return;
            }

            laserModuleAmmoPulseTimer -= Time.deltaTime;
            if (laserModuleAmmoPulseTimer <= 0f)
            {
                if (!TryConsumeModuleShot("LASER NEEDS OZPARTS"))
                {
                    HideLaserModuleBeam();
                    CoolLaserModule(false);
                    return;
                }

                laserModuleAmmoPulseTimer = LaserModuleAmmoPulseInterval;
            }

            UpdateLaserModuleBeam(origin, targetPos);
            HeatLaserModule();
            DamageHazardByModule(targetIndex, LaserModuleDps * Time.deltaTime * QueenBuffRate(laserModule), root, 16);
            if (targetIndex >= hazards.Count || target.Root == null)
                laserTargetIndex = -1;
        }

        private void ArcChainModuleLoop()
        {
            if (!IsArcChainModuleActive() || arcChainModule == null || !arcChainModule.gameObject.activeSelf)
                return;

            arcChainTimer -= Time.deltaTime * QueenBuffRate(arcChainModule);
            if (arcChainTimer > 0f)
                return;

            if (!arcChainModuleAimed)
                return;

            Vector2 fireDirection = GetArcChainModuleFireDirection();
            Vector2 origin = GetCanvasLocalPosition(arcChainModule) + fireDirection * 18f;
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return;

            int targetIndex = FindNearestArcTargetIndex(origin, ArcChainRange);
            if (targetIndex < 0)
                return;
            if (!TryConsumeArcShot())
                return;

            arcChainTimer = ArcChainCooldown;
            PlayArcElectricSound();
            ResolveArcChainHit(targetIndex, origin, root);
        }

        private void RailSpikeModuleLoop()
        {
            if (!IsRailSpikeModuleActive() || railSpikeModule == null || !railSpikeModule.gameObject.activeSelf)
                return;

            railSpikeTimer -= Time.deltaTime * QueenBuffRate(railSpikeModule);
            if (railSpikeTimer > 0f)
                return;

            if (!railSpikeModuleAimed)
                return;

            Vector2 fireDirection = GetRailSpikeModuleFireDirection();
            Vector2 origin = GetCanvasLocalPosition(railSpikeModule) + fireDirection * 17f;
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return;

            if (!HasRailSpikeTargets(origin, fireDirection, root))
                return;
            if (!TryConsumeRailSpikeShot())
                return;

            railSpikeTimer = RailSpikeCooldown;
            PlayRailSpikeShotSound();
            ResolveRailSpikeHit(origin, fireDirection, root);
        }

        private Vector2 GetCanvasLocalPosition(RectTransform rect)
        {
            RectTransform world = WorldCoordinateRoot();
            if (world == null || rect == null)
                return Vector2.zero;

            return world.InverseTransformPoint(rect.TransformPoint(Vector3.zero));
        }

        private Vector2 GetHomingMissileModuleFireDirection()
        {
            if (homingMissileModule == null)
                return Vector2.up;

            Vector3 up = homingMissileModule.TransformDirection(Vector3.up);
            Vector2 direction = new Vector2(up.x, up.y);
            return direction.sqrMagnitude > 0.01f ? direction.normalized : Vector2.up;
        }

        private Vector2 GetLaserModuleFireDirection()
        {
            if (laserModule == null)
                return Vector2.down;

            Vector3 up = laserModule.TransformDirection(Vector3.up);
            Vector2 direction = new Vector2(up.x, up.y);
            return direction.sqrMagnitude > 0.01f ? direction.normalized : Vector2.down;
        }

        private Vector2 GetArcChainModuleFireDirection()
        {
            if (arcChainModule == null)
                return Vector2.right;

            Vector3 up = arcChainModule.TransformDirection(Vector3.up);
            Vector2 direction = new Vector2(up.x, up.y);
            return direction.sqrMagnitude > 0.01f ? direction.normalized : Vector2.right;
        }

        private Vector2 GetRailSpikeModuleFireDirection()
        {
            if (railSpikeModule == null)
                return Vector2.left;

            Vector3 up = railSpikeModule.TransformDirection(Vector3.up);
            Vector2 direction = new Vector2(up.x, up.y);
            return direction.sqrMagnitude > 0.01f ? direction.normalized : Vector2.left;
        }

        private bool TryConsumeModuleShot(string emptyMessage)
        {
            if (IsTutorialModuleAmmoFree())
                return true;

            if (moduleShotsUntilPartCost <= 0)
            {
                if (!HasOzParts(1))
                {
                    if (statusText != null)
                        statusText.text = emptyMessage;
                    return false;
                }

                SpendOzParts(1);
                moduleShotsUntilPartCost = Mathf.Max(1, ModuleShotsPerOzPart);
                PlayerPrefs.SetInt(OzPartsKey, ozParts);
                PlayerPrefs.Save();
                RefreshHud();
                RefreshUpgradeLabels();
            }

            moduleShotsUntilPartCost--;
            return true;
        }

        private bool TryConsumeArcShot()
        {
            if (IsTutorialModuleAmmoFree())
                return true;

            if (!HasOzParts(1))
            {
                if (statusText != null)
                    statusText.text = "ARC NEEDS OZPARTS";
                return false;
            }

            SpendOzParts(1);
            PlayerPrefs.SetInt(OzPartsKey, ozParts);
            PlayerPrefs.Save();
            RefreshHud();
            RefreshUpgradeLabels();
            return true;
        }

        private bool TryConsumeRailSpikeShot()
        {
            if (IsTutorialModuleAmmoFree())
                return true;

            if (!HasOzParts(1))
            {
                if (statusText != null)
                    statusText.text = "RAIL SPIKE NEEDS OZPARTS";
                return false;
            }

            SpendOzParts(1);
            PlayerPrefs.SetInt(OzPartsKey, ozParts);
            PlayerPrefs.Save();
            RefreshHud();
            RefreshUpgradeLabels();
            return true;
        }

        private bool IsTutorialModuleAmmoFree()
        {
            return selectedMode == GameMode.Story && selectedStoryLevel == StoryLevel.Tutorial;
        }

        private Vector2 ResolveProjectileDirection(Vector2 origin, Vector2 target)
        {
            Vector2 direction = target - origin;
            return direction.sqrMagnitude > 1f ? direction.normalized : Vector2.up;
        }

        private bool IsOrbAtBase()
        {
            if (IsOrbDockedOnBaseShip() || IsOrbDockedOnOutpost())
                return true;

            if (pointerControl)
                return false;

            float baseY = ResolveGameOrbY();
            return Mathf.Abs(laneX) <= 36f && Mathf.Abs(orbY - baseY) <= 42f;
        }

        private float CurrentProjectileSpeed()
        {
            return 1320f + attackLevel * 80f;
        }

        private float CurrentProjectileMaxDistance(Vector2 origin)
        {
            return BaseProjectileMaxDistance(origin) + (IsHorizonRelayActive() ? HorizonWeaponRangeBonus : 0f);
        }

        private float BaseProjectileMaxDistance(Vector2 origin)
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return CoreCannonFlightRange + (IsOrbAtBase() ? CoreCannonBaseRangeBonus : 0f) + attackLevel * 18f;

            float baseReach = CoreCannonFlightRange + (IsOrbAtBase() ? CoreCannonBaseRangeBonus : 0f);
            if (selectedMode == GameMode.Story && selectedStoryLevel == StoryLevel.Mines && minesBossActive && minesBossDamageable)
                baseReach = Mathf.Max(baseReach, CoreCannonFlightRange + CoreCannonBaseRangeBonus);
            return baseReach + attackLevel * 18f;
        }

        private static float ResolveForwardCombatTopY(RectTransform root)
        {
            if (root == null)
                return 1060f;

            return root.rect.height * (0.5f + ForwardFlightScreenFraction) + ForwardCombatProjectilePadding;
        }

        private Vector2? FindNearestEnemyTarget(Vector2 origin, float projectileSpeed)
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return null;

            float bestDistance = float.MaxValue;
            Vector2 bestTarget = Vector2.zero;
            bool found = false;

            for (int i = 0; i < hazards.Count; i++)
            {
                HazardView hazard = hazards[i];
                if (hazard.Root == null || hazard.Symbiote || hazard.ElectricDeathPending)
                    continue;

                Vector2 enemyPos = hazard.Root.anchoredPosition;
                enemyPos.y += root.rect.height * 0.5f;
                if (enemyPos.y <= origin.y)
                    continue;
                bool tutorialUpperTarget = hazard.TutorialMaterialEnemy || hazard.TutorialBaseDefenseEnemy;
                if (enemyPos.y > ResolveForwardCombatTopY(root) && !tutorialUpperTarget)
                    continue;

                float directDistance = Vector2.Distance(origin, enemyPos);
                float baseMaxDistance = BaseProjectileMaxDistance(origin);
                float maxDistance = tutorialUpperTarget ? root.rect.height * 1.12f : ResolveHorizonRangeForHazard(hazard, baseMaxDistance);
                if (directDistance > maxDistance)
                    continue;

                float travelTime = Mathf.Clamp(directDistance / Mathf.Max(1f, projectileSpeed), 0f, 0.65f);
                enemyPos += hazard.Velocity * travelTime;

                float distance = (enemyPos - origin).sqrMagnitude;
                if (distance >= bestDistance)
                    continue;

                bestDistance = distance;
                bestTarget = enemyPos;
                found = true;
            }

            if (minesBossDamageable && TryGetMinesBossTargetPosition(out Vector2 bossTarget))
            {
                float directDistance = Vector2.Distance(origin, bossTarget);
                if (directDistance <= CurrentProjectileMaxDistance(origin))
                {
                    float distance = (bossTarget - origin).sqrMagnitude;
                    if (distance < bestDistance)
                    {
                        bestDistance = distance;
                        bestTarget = bossTarget;
                        found = true;
                    }
                }
            }

            return found ? bestTarget : null;
        }

