                }
            }

            return found ? bestTarget : null;
        }

        private Vector2? FindNearestLaserTarget(Vector2 origin)
        {
            int index = FindNearestLaserTargetIndex(origin);
            if (index < 0)
                return null;

            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null || hazards[index].Root == null)
                return null;

            Vector2 enemyPos = hazards[index].Root.anchoredPosition;
            enemyPos.y += root.rect.height * 0.5f;
            return enemyPos;
        }

        private Vector2? FindLaserAimTarget(Vector2 origin)
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return null;

            int index = ResolveLaserTargetIndex(origin, root, out Vector2 targetPos);
            return index >= 0 ? targetPos : null;
        }

        private int ResolveLaserTargetIndex(Vector2 origin, RectTransform root, out Vector2 targetPos)
        {
            targetPos = Vector2.zero;
            int nearestIndex = FindNearestLaserTargetIndex(origin);
            if (nearestIndex < 0)
            {
                laserTargetIndex = -1;
                return -1;
            }

            if (!TryGetLaserTargetPosition(nearestIndex, root, out Vector2 nearestPos))
            {
                laserTargetIndex = -1;
                return -1;
            }

            float nearestDistance = Vector2.Distance(origin, nearestPos);
            bool hasLockedTarget = IsLaserTargetValid(laserTargetIndex, origin, root, out Vector2 lockedPos, out float lockedDistance);
            if (!hasLockedTarget || nearestDistance < lockedDistance * 0.74f)
            {
                laserTargetIndex = nearestIndex;
                targetPos = nearestPos;
                return laserTargetIndex;
            }

            targetPos = lockedPos;
            return laserTargetIndex;
        }

        private bool IsLaserTargetValid(int index, Vector2 origin, RectTransform root, out Vector2 targetPos, out float distance)
        {
            targetPos = Vector2.zero;
            distance = float.MaxValue;
            if (!TryGetLaserTargetPosition(index, root, out targetPos))
                return false;

            distance = Vector2.Distance(origin, targetPos);
            HazardView hazard = hazards[index];
            return distance <= ResolveHorizonRangeForHazard(hazard, LaserModuleRange) * 1.08f;
        }

        private bool TryGetLaserTargetPosition(int index, RectTransform root, out Vector2 targetPos)
        {
            targetPos = Vector2.zero;
            if (root == null || index < 0 || index >= hazards.Count)
                return false;

            HazardView hazard = hazards[index];
            if (hazard.Root == null || hazard.Symbiote)
                return false;

            targetPos = hazard.Root.anchoredPosition;
            targetPos.y += root.rect.height * 0.5f;
            return true;
        }

