        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return -1;

            int bestIndex = -1;
            float bestDistance = float.MaxValue;
            for (int i = 0; i < hazards.Count; i++)
            {
                HazardView hazard = hazards[i];
                if (hazard.Root == null || hazard.Symbiote)
                    continue;

                Vector2 enemyPos = hazard.Root.anchoredPosition;
                enemyPos.y += root.rect.height * 0.5f;
                float distance = Vector2.Distance(origin, enemyPos);
                float range = ResolveHorizonRangeForHazard(hazard, LaserModuleRange);
                if (distance > range || distance >= bestDistance)
                    continue;

                bestDistance = distance;
                bestIndex = i;
            }

            return bestIndex;
        }

