        private bool HasRailSpikeTargets(Vector2 origin, Vector2 direction, RectTransform root)
        {
            if (root == null || direction.sqrMagnitude <= 0.01f)
                return false;

            direction.Normalize();
            for (int i = 0; i < hazards.Count; i++)
            {
                HazardView hazard = hazards[i];
                if (hazard.Root == null || hazard.Symbiote || hazard.ElectricDeathPending)
                    continue;

                Vector2 enemyPos = GetHazardCanvasPosition(hazard, root);
                Vector2 toEnemy = enemyPos - origin;
                float along = Vector2.Dot(toEnemy, direction);
                float range = ResolveHorizonRangeForHazard(hazard, RailSpikeRange);
                if (along < 0f || along > range)
                    continue;

                Vector2 closest = origin + direction * along;
                float lineDistance = Vector2.Distance(enemyPos, closest);
                if (lineDistance <= RailSpikeLineRadius + hazard.Radius * 0.35f)
                    return true;
            }

            return false;
        }

        private void ResolveRailSpikeHit(Vector2 origin, Vector2 direction, RectTransform root)
        {
            if (root == null || direction.sqrMagnitude <= 0.01f)
                return;

            direction.Normalize();
            List<int> targetIndices = new List<int>(RailSpikeMaxTargets);
            List<float> targetDistances = new List<float>(RailSpikeMaxTargets);
            float farthestHit = 0f;

            for (int i = 0; i < hazards.Count; i++)
            {
                HazardView hazard = hazards[i];
                if (hazard.Root == null || hazard.Symbiote || hazard.ElectricDeathPending)
                    continue;

                Vector2 enemyPos = GetHazardCanvasPosition(hazard, root);
                Vector2 toEnemy = enemyPos - origin;
                float along = Vector2.Dot(toEnemy, direction);
                float range = ResolveHorizonRangeForHazard(hazard, RailSpikeRange);
                if (along < 0f || along > range)
                    continue;

                Vector2 closest = origin + direction * along;
                float lineDistance = Vector2.Distance(enemyPos, closest);
                if (lineDistance > RailSpikeLineRadius + hazard.Radius * 0.35f)
                    continue;

                int insertAt = targetDistances.Count;
                for (int j = 0; j < targetDistances.Count; j++)
                {
                    if (along < targetDistances[j])
                    {
                        insertAt = j;
                        break;
                    }
                }

                targetDistances.Insert(insertAt, along);
                targetIndices.Insert(insertAt, i);
                if (targetIndices.Count > RailSpikeMaxTargets)
                {
                    targetIndices.RemoveAt(targetIndices.Count - 1);
                    targetDistances.RemoveAt(targetDistances.Count - 1);
                }
            }

            for (int i = 0; i < targetDistances.Count; i++)
                farthestHit = Mathf.Max(farthestHit, targetDistances[i]);

            float railRange = RailSpikeRange + (IsHorizonRelayActive() ? HorizonWeaponRangeBonus : 0f);
            float beamLength = targetIndices.Count > 0 ? Mathf.Min(railRange, farthestHit + 90f) : railRange * 0.55f;
            SpawnRailSpikeView(origin, origin + direction * beamLength);

            for (int i = 0; i < targetIndices.Count - 1; i++)
            {
                for (int j = i + 1; j < targetIndices.Count; j++)
                {
                    if (targetIndices[j] > targetIndices[i])
                    {
                        int tempIndex = targetIndices[i];
                        targetIndices[i] = targetIndices[j];
                        targetIndices[j] = tempIndex;
                    }
                }
            }

            for (int i = 0; i < targetIndices.Count; i++)
                DamageHazardByModule(targetIndices[i], RailSpikeDamage, root, 24);
        }

        private Vector2 GetHazardCanvasPosition(HazardView hazard, RectTransform root)
        {
            Vector2 position = hazard.Root != null ? hazard.Root.anchoredPosition : Vector2.zero;
            if (root != null)
                position.y += root.rect.height * 0.5f;
            return position;
        }

        private void SpawnProjectile(Vector2 position, Vector2 direction)
        {
            SpawnProjectile(position, direction, CoreProjectileDamage, CurrentProjectileSpeed(), CurrentProjectileRadius(), CurrentProjectileMaxDistance(position), "OrbShot");
        }

        private void SpawnProjectile(Vector2 position, Vector2 direction, float damage, float speed, float radius, float maxDistance, string name)
        {
            GameObject go = new GameObject(name, typeof(RectTransform), typeof(CanvasRenderer), typeof(Image));
            go.transform.SetParent(playfield, false);

            RectTransform rect = go.GetComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = new Vector2(22f + attackLevel * 1.3f, 58f + attackLevel * 2.6f);
            rect.anchoredPosition = position;
            rect.localRotation = Quaternion.Euler(0f, 0f, Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg - 90f);

            Image image = go.GetComponent<Image>();
            Sprite projectileSprite = GetSpriteFromTextureResource(OrbProjectileSpriteResourcePath);
            if (projectileSprite != null)
            {
                image.sprite = projectileSprite;
                image.color = Color.white;
                image.preserveAspect = true;
            }
            else
            {
                image.color = new Color(0.36f, 0.95f, 1f, 0.96f);
                AddOutline(rect, new Color(1f, 0.88f, 0.35f, 0.42f), new Vector2(2f, -2f));
            }
            image.raycastTarget = false;

            projectiles.Add(new ProjectileView
            {
                Root = rect,
                Direction = direction.sqrMagnitude > 0.01f ? direction.normalized : Vector2.up,
                Speed = speed,
                Radius = radius,
                MaxDistance = maxDistance,
                Damage = damage
            });
        }

        private void SpawnEnemyProjectile(Vector2 position, Vector2 direction, ForwardDefenseType sourceType)
        {
            if (playfield == null)
                return;

            GameObject go = new GameObject("EnemyProjectile_" + sourceType, typeof(RectTransform), typeof(CanvasRenderer), typeof(Image));
            go.transform.SetParent(playfield, false);

            RectTransform rect = go.GetComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = ResolveEnemyProjectileSize(sourceType);
            rect.anchoredPosition = position;
            rect.localRotation = Quaternion.Euler(0f, 0f, Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg);

            Image image = go.GetComponent<Image>();
            Sprite projectileSprite = GetSpriteFromTextureResource(ResolveEnemyProjectileResourcePath(sourceType));
            if (projectileSprite != null)
            {
                image.sprite = projectileSprite;
                image.color = Color.white;
                image.preserveAspect = true;
            }
            else
            {
                image.color = new Color(1f, 0.18f, 0.04f, 0.95f);
                AddOutline(rect, new Color(1f, 0.78f, 0.12f, 0.38f), new Vector2(2f, -2f));
            }
            image.raycastTarget = false;

            enemyProjectiles.Add(new ProjectileView
            {
                Root = rect,
                Direction = direction.sqrMagnitude > 0.01f ? direction.normalized : Vector2.down,
                Speed = ResolveEnemyProjectileSpeed(sourceType),
                Radius = sourceType == ForwardDefenseType.ShieldRelay ? 34f : ForwardDefenseProjectileHitRadius,
                MaxDistance = ForwardDefenseProjectileRange,
                Damage = sourceType == ForwardDefenseType.ShieldRelay ? 0f : ResolveEnemyProjectileDamage(sourceType)
            });
        }

        private static Vector2 ResolveEnemyProjectileSize(ForwardDefenseType sourceType)
        {
            switch (sourceType)
            {
                case ForwardDefenseType.PulseTurret:
                    return new Vector2(96f, 38f);
                case ForwardDefenseType.ShieldRelay:
                    return new Vector2(88f, 88f);
                case ForwardDefenseType.InterceptorDrone:
                    return new Vector2(118f, 34f);
                case ForwardDefenseType.CommandNode:
                    return new Vector2(72f, 72f);
                default:
                    return new Vector2(54f, 26f);
            }
        }

        private static float ResolveEnemyProjectileSpeed(ForwardDefenseType sourceType)
        {
            switch (sourceType)
            {
                case ForwardDefenseType.PulseTurret:
                    return 360f;
                case ForwardDefenseType.ShieldRelay:
                    return 220f;
                case ForwardDefenseType.InterceptorDrone:
                    return 620f;
                case ForwardDefenseType.CommandNode:
                    return 285f;
                default:
                    return 520f;
            }
        }

        private static float ResolveEnemyProjectileDamage(ForwardDefenseType sourceType)
        {
            switch (sourceType)
            {
                case ForwardDefenseType.PulseTurret:
                    return ForwardDefenseProjectileDamage + 6;
                case ForwardDefenseType.InterceptorDrone:
                    return ForwardDefenseProjectileDamage + 4;
                case ForwardDefenseType.CommandNode:
                    return ForwardDefenseProjectileDamage + 2;
                default:
                    return ForwardDefenseProjectileDamage;
            }
        }

        private static string ResolveEnemyProjectileResourcePath(ForwardDefenseType sourceType)
        {
            switch (sourceType)
            {
                case ForwardDefenseType.PulseTurret:
                    return ForwardDefensePulseSlugResourcePath;
                case ForwardDefenseType.ShieldRelay:
                    return ForwardDefenseShieldPulseResourcePath;
                case ForwardDefenseType.InterceptorDrone:
                    return ForwardDefenseInterceptorLanceResourcePath;
                case ForwardDefenseType.CommandNode:
                    return ForwardDefenseCommandBeaconResourcePath;
                default:
                    return ForwardDefenseSentinelBoltResourcePath;
            }
        }

