        private void SpawnArcView(Vector2 from, Vector2 to, float alpha)
        {
            if (playfield == null)
                return;

            Vector2 direction = to - from;
            float length = direction.magnitude;
            if (length < 4f)
                return;

            Vector2 forward = direction / length;
            Vector2 normal = new Vector2(-forward.y, forward.x);
            int segments = Mathf.Clamp(Mathf.CeilToInt(length / 42f), 3, 8);
            Vector2 previous = from;
            for (int i = 1; i <= segments; i++)
            {
                float t = i / (float)segments;
                Vector2 point = Vector2.Lerp(from, to, t);
                if (i < segments)
                {
                    float jag = Mathf.Sin(Time.time * 37f + i * 2.31f + length * 0.013f) * 16f + RandomRange(-10f, 10f);
                    point += normal * jag;
                }

                SpawnArcSegment(previous, point, alpha * (i == segments ? 1f : 0.92f), i % 2 == 0 ? 2.4f : 3.4f);
                previous = point;
            }

            SpawnArcSegment(from, to, alpha * 0.28f, 1.2f);
        }

        private void SpawnRailSpikeView(Vector2 from, Vector2 to)
        {
            if (playfield == null)
                return;

            Vector2 direction = to - from;
            float length = direction.magnitude;
            if (length < 8f)
                return;

            SpawnRailSpikeSegment(from, to, 0.86f, 4.8f);
            SpawnRailSpikeSegment(from, to, 0.42f, 10.5f);
            SpawnRailSpikeRings(from, to);
        }

        private void SpawnRailSpikeSegment(Vector2 from, Vector2 to, float alpha, float width)
        {
            if (playfield == null)
                return;

            Vector2 direction = to - from;
            float length = direction.magnitude;
            if (length < 8f)
                return;

            RectTransform beam = CreatePanel(playfield, "RailSpikeBeam", new Color(1f, 0.82f, 0.20f, alpha));
            beam.anchorMin = new Vector2(0.5f, 0.5f);
            beam.anchorMax = new Vector2(0.5f, 0.5f);
            beam.pivot = new Vector2(0.5f, 0f);
            beam.sizeDelta = new Vector2(width, length);
            beam.anchoredPosition = from;
            beam.localRotation = Quaternion.Euler(0f, 0f, Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg - 90f);
            AddOutline(beam, new Color(1f, 0.98f, 0.48f, alpha * 0.62f), new Vector2(1.2f, -1.2f));

            arcViews.Add(new ArcView
            {
                Root = beam,
                Image = beam.GetComponent<Image>(),
                Lifetime = RailSpikeBeamLifetime,
                Age = 0f
            });
        }

        private void SpawnRailSpikeRings(Vector2 from, Vector2 to)
        {
            if (playfield == null)
                return;

            Vector2 direction = to - from;
            float length = direction.magnitude;
            if (length < 80f)
                return;

            Vector2 forward = direction / length;
            int ringCount = Mathf.Clamp(Mathf.FloorToInt(length / 145f), 3, 6);
            for (int i = 0; i < ringCount; i++)
            {
                float t = (i + 0.55f) / (ringCount + 0.15f);
                float pulse = Mathf.Sin(Time.time * 28f + i * 1.7f) * 2.5f;
                Vector2 position = from + forward * (length * t);
                SpawnRailSpikeRing(position, Mathf.Lerp(18f, 32f, t) + pulse, 0.62f - i * 0.045f);
            }
        }

        private void SpawnRailSpikeRing(Vector2 position, float size, float alpha)
        {
            RectTransform ring = CreatePanel(playfield, "RailSpikeRing", Color.clear);
            ring.anchorMin = new Vector2(0.5f, 0.5f);
            ring.anchorMax = new Vector2(0.5f, 0.5f);
            ring.pivot = new Vector2(0.5f, 0.5f);
            ring.sizeDelta = new Vector2(size, size);
            ring.anchoredPosition = position;
            ring.localRotation = Quaternion.Euler(0f, 0f, RandomRange(-18f, 18f));

            Image image = ring.GetComponent<Image>();
            if (image != null)
            {
                image.sprite = GetShieldBubbleSprite();
                image.color = new Color(1f, 0.78f, 0.14f, alpha);
                image.raycastTarget = false;
            }

            AddOutline(ring, new Color(1f, 1f, 0.62f, alpha * 0.70f), new Vector2(1.6f, -1.6f));
            arcViews.Add(new ArcView
            {
                Root = ring,
                Image = image,
                Lifetime = RailSpikeBeamLifetime * 1.12f,
                Age = 0f
            });
        }

        private void SpawnArcSegment(Vector2 from, Vector2 to, float alpha, float width)
        {
            if (playfield == null)
                return;

            Vector2 direction = to - from;
            float length = direction.magnitude;
            if (length < 4f)
                return;

            RectTransform arc = CreatePanel(playfield, "ArcChainBeam", new Color(0.34f, 0.96f, 1f, alpha));
            arc.anchorMin = new Vector2(0.5f, 0.5f);
            arc.anchorMax = new Vector2(0.5f, 0.5f);
            arc.pivot = new Vector2(0.5f, 0f);
            arc.sizeDelta = new Vector2(width, length);
            arc.anchoredPosition = from;
            arc.localRotation = Quaternion.Euler(0f, 0f, Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg - 90f);
            AddOutline(arc, new Color(1f, 1f, 1f, alpha * 0.55f), new Vector2(2f, -2f));

            arcViews.Add(new ArcView
            {
                Root = arc,
                Image = arc.GetComponent<Image>(),
                Lifetime = ArcViewLifetime,
                Age = 0f
            });
        }

        private void UpdateArcViews()
        {
            for (int i = arcViews.Count - 1; i >= 0; i--)
            {
                ArcView arc = arcViews[i];
                if (arc.Root == null)
                {
                    arcViews.RemoveAt(i);
                    continue;
                }

                arc.Age += Time.deltaTime;
                float t = Mathf.Clamp01(arc.Age / Mathf.Max(0.01f, arc.Lifetime));
                if (arc.Image != null)
                {
                    Color color = arc.Image.color;
                    color.a = Mathf.Lerp(0.92f, 0f, t);
                    arc.Image.color = color;
                }

                arc.Root.sizeDelta = new Vector2(5.5f + Mathf.Sin(Time.time * 80f) * 1.4f, arc.Root.sizeDelta.y);
                if (arc.Age >= arc.Lifetime)
                {
                    Destroy(arc.Root.gameObject);
                    arcViews.RemoveAt(i);
                }
            }
        }

        private void ClearArcViews()
        {
            for (int i = arcViews.Count - 1; i >= 0; i--)
            {
                if (arcViews[i].Root != null)
                    Destroy(arcViews[i].Root.gameObject);
            }

            arcViews.Clear();
        }

        private void HideLaserModuleBeam()
        {
            UpdateLaserModuleSound(false);
            if (laserModuleBeam != null)
                laserModuleBeam.gameObject.SetActive(false);
        }

        private void UpdateLaserModuleBeam(Vector2 origin, Vector2 target)
        {
            if (laserModuleBeam == null)
                return;

            Vector2 direction = target - origin;
            float length = direction.magnitude;
            if (length < 1f)
            {
                UpdateLaserModuleSound(false);
                return;
            }

            UpdateLaserModuleSound(true);
            laserModuleBeam.gameObject.SetActive(true);
            laserModuleBeam.anchoredPosition = origin;
            laserModuleBeam.sizeDelta = new Vector2(3.2f + Mathf.Sin(Time.time * 42f) * 1.1f, length);
            laserModuleBeam.localRotation = Quaternion.Euler(0f, 0f, Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg - 90f);
        }

        private void HeatLaserModule()
        {
            laserModuleHeat = Mathf.Min(LaserModuleOverheatSeconds, laserModuleHeat + Time.deltaTime);
            if (laserModuleHeat >= LaserModuleOverheatSeconds)
            {
                laserModuleHeat = LaserModuleOverheatSeconds;
                laserModuleOverheated = true;
                HideLaserModuleBeam();
                if (statusText != null)
                    statusText.text = "LASER OVERHEATED";
            }

            UpdateLaserModuleHeatTint();
        }

        private void CoolLaserModule(bool forcedCooldown)
        {
            if (laserModuleHeat <= 0f && !laserModuleOverheated)
            {
                UpdateLaserModuleHeatTint();
                return;
            }

            float fullCooldownRate = LaserModuleOverheatSeconds / Mathf.Max(0.1f, LaserModuleCooldownSeconds);
            float cooldownRate = forcedCooldown ? fullCooldownRate : fullCooldownRate * 0.42f;
            laserModuleHeat = Mathf.Max(0f, laserModuleHeat - cooldownRate * Time.deltaTime);

            if (laserModuleOverheated && laserModuleHeat <= 0.05f)
            {
                laserModuleHeat = 0f;
                laserModuleOverheated = false;
                if (statusText != null)
                    statusText.text = "LASER COOLED";
            }

            UpdateLaserModuleHeatTint();
        }

        private void UpdateLaserModuleHeatTint()
        {
            if (laserModule == null)
                return;

            Image image = laserModule.GetComponent<Image>();
            if (image == null)
                return;

            float heat = Mathf.Clamp01(laserModuleHeat / LaserModuleOverheatSeconds);
            Color normal = Color.white;
            Color hot = new Color(1f, 0.34f, 0.22f, 1f);
            image.color = Color.Lerp(normal, hot, heat * 0.78f);

            if (laserModuleOverheated)
            {
                float pulse = 0.5f + Mathf.Sin(Time.time * 18f) * 0.5f;
                image.color = Color.Lerp(image.color, new Color(1f, 0.08f, 0.04f, 1f), pulse * 0.35f);
            }
        }

        private void SpawnHazard(float x, bool symbiote, float difficulty, float y = 90f, float fixedSpeed = -1f, float fixedSize = -1f, bool formationMember = false, int forcedMineType = 0, bool bossPhaseMinion = false)
        {
            RectTransform root = canvas.transform as RectTransform;
            if (root == null)
                return;

            double mineRoll = random.NextDouble();
            bool heavyMine = !symbiote && (forcedMineType == 2 || (!formationMember && forcedMineType == 0 && mineRoll < HeavyMineSpawnChance));
            bool homingMine = !symbiote && !heavyMine && (forcedMineType == 1 || (!formationMember && forcedMineType == 0 && mineRoll < HeavyMineSpawnChance + HomingMineSpawnChance));
            GameObject go = new GameObject(symbiote ? "SymbioteLinkBonus" : heavyMine ? "HeavyEnemyMine" : homingMine ? "HomingEnemyMine" : "EnemyMine", typeof(RectTransform), typeof(CanvasRenderer), typeof(Image));
            go.transform.SetParent(playfield, false);
            RectTransform rect = go.GetComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 1f);
            rect.anchorMax = new Vector2(0.5f, 1f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            float mineSize = fixedSize > 0f ? fixedSize : RandomRange(84f, 108f);
            float homingMineSize = mineSize * 1.08f;
            float heavyMineSize = mineSize * 1.22f;
            rect.sizeDelta = symbiote ? new Vector2(SymbiosisLinkSpriteSize, SymbiosisLinkSpriteSize) : heavyMine ? new Vector2(heavyMineSize, heavyMineSize) : homingMine ? new Vector2(homingMineSize, homingMineSize) : new Vector2(mineSize, mineSize);
            rect.anchoredPosition = new Vector2(x, y);

            Image image = go.GetComponent<Image>();
            image.color = symbiote ? new Color(0.18f, 1f, 0.72f, 0.68f) : new Color(0.86f, 0.16f, 0.20f, 1f);
            image.raycastTarget = false;
            if (symbiote)
            {
                Sprite linkedSprite = GetSpriteFromTextureResource(SymbiosisLinkedSpriteResourcePath);
                if (linkedSprite != null)
                {
                    image.sprite = linkedSprite;
                    image.color = Color.white;
                    image.preserveAspect = true;
                }
                else
                {
                    image.sprite = GetShieldBubbleSprite();
                    image.type = Image.Type.Simple;
                    AddSymbioteLinkMarks(rect);
                }
            }
            else
            {
                Sprite mineSprite = GetSpriteFromTextureResource(heavyMine ? HeavyEnemyMineSpriteResourcePath : homingMine ? HomingEnemyMineSpriteResourcePath : EnemyMineSpriteResourcePath);
                if (mineSprite != null)
                {
                    image.sprite = mineSprite;
                    image.color = Color.white;
                    image.preserveAspect = true;
                }
                else
                {
                    AddEnemyWingMarks(rect);
                }
            }
            AddOutline(rect, symbiote ? new Color(0.32f, 1f, 0.82f, 0.68f) : new Color(1f, 0.10f, 0.08f, 0.48f), new Vector2(3f, -3f));

            bool homing = !formationMember && !symbiote && !homingMine && !heavyMine && (selectedMode == GameMode.Story || random.NextDouble() > 0.62);
            float speed = fixedSpeed > 0f
                ? fixedSpeed
                : symbiote ? Mathf.Lerp(92f, 150f, difficulty) + RandomRange(-8f, 14f) : Mathf.Lerp(150f, 310f, difficulty) + RandomRange(-20f, 35f);
            if (homingMine)
                speed *= 0.5f;
            if (heavyMine)
                speed *= HeavyMineSpeedMultiplier;
            if (!symbiote)
                MarkBestiaryEncounter(heavyMine ? OrbiosisBestiaryLibrary.HeavyMine : homingMine ? OrbiosisBestiaryLibrary.SeekerMine : OrbiosisBestiaryLibrary.EnemyMine);
            hazards.Add(new HazardView
            {
                Root = rect,
                Image = image,
                Radius = Mathf.Max(rect.sizeDelta.x, rect.sizeDelta.y) * (symbiote ? 0.58f : heavyMine ? 0.46f : homingMine ? 0.40f : 0.44f),
                Health = symbiote ? 1f : heavyMine ? HeavyMineHealth : homingMine ? HomingMineHealth : 10f,
                Speed = speed,
                Spin = formationMember ? 0f : symbiote ? RandomRange(38f, 72f) : RandomRange(-170f, 170f),
                Symbiote = symbiote,
                Homing = homing,
                HorizontalSpeed = homing ? Mathf.Lerp(38f, 92f, difficulty) + RandomRange(0f, 24f) : 0f,
                SeekerMine = homingMine,
                HeavyMineTier = heavyMine ? 1 : 0,
                BossPhaseMinion = bossPhaseMinion
            });
        }

