            RectTransform link = CreatePanel(parent, "LinkBeam", new Color(0.72f, 1f, 0.92f, 0.82f));
            link.anchorMin = new Vector2(0.5f, 0.5f);
            link.anchorMax = new Vector2(0.5f, 0.5f);
            link.pivot = new Vector2(0.5f, 0.5f);
            link.sizeDelta = new Vector2(5f, 42f);
