        private void SpawnHeavyMineSplit(Vector2 position, int childTier, bool bossPhaseMinion = false)
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            Vector2 anchoredPosition = root != null ? position - new Vector2(0f, root.rect.height * 0.5f) : position;
            int count = childTier == 2 ? 2 : 3;
            for (int i = 0; i < count; i++)
            {
                float angle = childTier == 2
                    ? (i == 0 ? 210f : 330f)
                    : Mathf.Lerp(200f, 340f, count <= 1 ? 0f : i / (float)(count - 1));
                Vector2 direction = new Vector2(Mathf.Cos(angle * Mathf.Deg2Rad), Mathf.Sin(angle * Mathf.Deg2Rad));
                SpawnHeavyMineChild(anchoredPosition, childTier, direction, bossPhaseMinion);
            }
        }

        private void SpawnHeavyMineChild(Vector2 position, int tier, Vector2 splitDirection, bool bossPhaseMinion = false)
        {
            if (playfield == null)
                return;

            GameObject go = new GameObject(tier == 2 ? "HeavyEnemyMineMedium" : "HeavyEnemyMineSmall", typeof(RectTransform), typeof(CanvasRenderer), typeof(Image));
            go.transform.SetParent(playfield, false);
            RectTransform rect = go.GetComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 1f);
            rect.anchorMax = new Vector2(0.5f, 1f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            float size = tier == 2 ? RandomRange(70f, 78f) : RandomRange(42f, 50f);
            rect.sizeDelta = new Vector2(size, size);
            rect.anchoredPosition = position;

            Image image = go.GetComponent<Image>();
            image.raycastTarget = false;
            Sprite mineSprite = GetSpriteFromTextureResource(HeavyEnemyMineSpriteResourcePath);
            if (mineSprite != null)
            {
                image.sprite = mineSprite;
                image.color = Color.white;
                image.preserveAspect = true;
            }
            else
            {
                image.color = tier == 2 ? new Color(1f, 0.68f, 0.12f, 1f) : new Color(1f, 0.82f, 0.18f, 1f);
                AddEnemyWingMarks(rect);
            }

            AddOutline(rect, new Color(1f, 0.66f, 0.12f, 0.48f), new Vector2(2f, -2f));
            MarkBestiaryEncounter(OrbiosisBestiaryLibrary.FragmentMine);
            hazards.Add(new HazardView
            {
                Root = rect,
                Image = image,
                Radius = Mathf.Max(rect.sizeDelta.x, rect.sizeDelta.y) * 0.44f,
                Health = tier == 2 ? HeavyMineMediumHealth : HeavyMineSmallHealth,
                Speed = tier == 2 ? HeavyMineMediumSpeed : HeavyMineSmallSpeed,
                Spin = tier == 2 ? RandomRange(-220f, 220f) : RandomRange(-360f, 360f),
                HeavyMineTier = tier,
                SplitDirection = splitDirection.sqrMagnitude > 0.01f ? splitDirection.normalized : Vector2.down,
                BossPhaseMinion = bossPhaseMinion
            });
        }

        private void UpdateProjectiles()
        {
            RectTransform root = canvas.transform as RectTransform;
            if (root == null)
                return;

            for (int i = projectiles.Count - 1; i >= 0; i--)
            {
                ProjectileView projectile = projectiles[i];
                if (projectile.Root == null)
                {
                    projectiles.RemoveAt(i);
                    continue;
                }

                if (projectile.Homing)
                    UpdateHomingProjectile(projectile);

                float step = projectile.Speed * Time.deltaTime;
                projectile.Root.anchoredPosition += projectile.Direction * step;
                projectile.Travelled += step;
                Vector2 position = projectile.Root.anchoredPosition;
                float horizontalLimit = root.rect.width * 0.58f + 140f;
                float topLimit = ResolveForwardCombatTopY(root) + 90f;
                float bottomLimit = root.rect.height * 0.58f + 140f;
                if (projectile.Travelled >= projectile.MaxDistance || Mathf.Abs(position.x) > horizontalLimit || position.y > topLimit || position.y < -bottomLimit)
                {
                    Destroy(projectile.Root.gameObject);
                    projectiles.RemoveAt(i);
                    continue;
                }

                if (TryHitEnemy(projectile))
                {
                    Destroy(projectile.Root.gameObject);
                    projectiles.RemoveAt(i);
                }
            }
        }

        private void UpdateEnemyProjectiles()
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null || orb == null)
                return;

            for (int i = enemyProjectiles.Count - 1; i >= 0; i--)
            {
                ProjectileView projectile = enemyProjectiles[i];
                if (projectile.Root == null)
                {
                    enemyProjectiles.RemoveAt(i);
                    continue;
                }

                float step = projectile.Speed * Time.deltaTime;
                projectile.Root.anchoredPosition += projectile.Direction * step;
                projectile.Root.Rotate(0f, 0f, 65f * Time.deltaTime);
                projectile.Travelled += step;

                Vector2 position = projectile.Root.anchoredPosition;
                float horizontalLimit = root.rect.width * 0.58f + 160f;
                float verticalLimit = root.rect.height * 0.58f + 160f;
                if (projectile.Travelled >= projectile.MaxDistance || Mathf.Abs(position.x) > horizontalLimit || Mathf.Abs(position.y) > verticalLimit)
                {
                    Destroy(projectile.Root.gameObject);
                    enemyProjectiles.RemoveAt(i);
                    continue;
                }

                if (projectile.Damage <= 0f)
                    continue;

                int damage = Mathf.Max(1, Mathf.RoundToInt(projectile.Damage));
                if (TryHitShieldDrone(position, projectile.Radius, damage)
                    || TryHitDrones(position, projectile.Radius, damage)
                    || TryHitOutpost(position, projectile.Radius, damage)
                    || TryHitBaseShip(position, projectile.Radius, damage)
                    || TryHitOrbWithEnemyProjectile(position, projectile.Radius, damage))
                {
                    Destroy(projectile.Root.gameObject);
                    enemyProjectiles.RemoveAt(i);
                }
            }
        }

        private bool TryHitOrbWithEnemyProjectile(Vector2 position, float radius, int damage)
        {
            if (orb == null || Vector2.Distance(orb.anchoredPosition, position) > radius + 25f)
                return false;

            if (ShouldOutpostAbsorbOrbHit())
            {
                ApplySharedHealthDamage(damage, "OUTPOST ABSORBED SHOT");
                return true;
            }

            if (shield > 0)
            {
                shield--;
                shieldChargeTimer = 0f;
                if (statusText != null)
                    statusText.text = "SHIELD ABSORBED SHOT";
                RefreshHud();
                return true;
            }

            ApplySharedHealthDamage(damage, "ENEMY SHOT HIT");
            return true;
        }

        private void UpdateHomingProjectile(ProjectileView projectile)
        {
            if (projectile.Root == null)
                return;

            Vector2? target = FindNearestMissileTarget(projectile.Root.anchoredPosition);
            if (!target.HasValue)
                return;

            Vector2 desired = ResolveProjectileDirection(projectile.Root.anchoredPosition, target.Value);
            Vector3 current = new Vector3(projectile.Direction.x, projectile.Direction.y, 0f);
            Vector3 next = Vector3.RotateTowards(current, new Vector3(desired.x, desired.y, 0f), projectile.HomingTurnRate * Time.deltaTime, 0f);
            if (next.sqrMagnitude <= 0.001f)
                return;

            projectile.Direction = new Vector2(next.x, next.y).normalized;
            projectile.Root.localRotation = Quaternion.Euler(0f, 0f, Mathf.Atan2(projectile.Direction.y, projectile.Direction.x) * Mathf.Rad2Deg - 90f);
        }

        private bool TryHitEnemy(ProjectileView projectile)
        {
            if (projectile.Root == null)
                return false;

            RectTransform root = canvas.transform as RectTransform;
            if (root == null)
                return false;

            Vector2 shotPos = projectile.Root.anchoredPosition;
            for (int i = hazards.Count - 1; i >= 0; i--)
            {
                HazardView hazard = hazards[i];
                if (hazard.Root == null || hazard.Symbiote)
                    continue;

                Vector2 enemyPos = hazard.Root.anchoredPosition;
                enemyPos.y += root.rect.height * 0.5f;
                if (Vector2.Distance(shotPos, enemyPos) > projectile.Radius + hazard.Radius)
                    continue;

                if (projectile.ArcBall)
                {
                    ResolveArcChainHit(i, shotPos, root);
                    return true;
                }

                DamageHazardByProjectile(i, projectile.Damage > 0f ? projectile.Damage : CoreProjectileDamage, root);
                return true;
            }

            if (TryHitMinesBoss(projectile))
                return true;

            return false;
        }

        private void DamageHazardByProjectile(int index, float damage, RectTransform root)
        {
            if (index < 0 || index >= hazards.Count)
                return;

            HazardView hazard = hazards[index];
            if (hazard.Root == null)
                return;

            Vector2 enemyPos = GetHazardCanvasPosition(hazard, root);
            if (hazard.ForwardShieldTimer > 0f)
            {
                damage *= 0.45f;
                if (statusText != null)
                    statusText.text = "DEFENSE SHIELD HIT";
            }

            hazard.Health -= damage;
            TriggerHazardHitFeedback(hazard);
            if (hazard.Health > 0f)
            {
                if (statusText != null && hazard.HeavyMineTier > 0)
                    statusText.text = "HEAVY ARMOR HIT";
                return;
            }

            ResolveHazardDestroyedByWeapon(hazard, enemyPos);
            score += 20;
            if (random.NextDouble() < CoreShardDropChance)
            {
                coreShards++;
                PlayerPrefs.SetInt(CoreShardsKey, coreShards);
                PlayerPrefs.Save();
                if (statusText != null)
                    statusText.text = "+1 CORE SHARD";
            }

            RefreshHud();
            RefreshUpgradeLabels();
            Destroy(hazard.Root.gameObject);
            hazards.RemoveAt(index);
        }

        private void ResolveArcChainHit(int firstIndex, Vector2 shotPos, RectTransform root)
        {
            List<int> targets = new List<int>(ArcChainMaxTargets);
            List<Vector2> targetPositions = new List<Vector2>(ArcChainMaxTargets);
            targets.Add(firstIndex);
            targetPositions.Add(GetHazardCanvasPosition(hazards[firstIndex], root));

            while (targets.Count < ArcChainMaxTargets)
            {
                int nextIndex = FindNextArcChainTarget(targetPositions[targetPositions.Count - 1], targets, root);
                if (nextIndex < 0)
                    break;

                targets.Add(nextIndex);
                targetPositions.Add(GetHazardCanvasPosition(hazards[nextIndex], root));
            }

            if (targetPositions.Count > 0)
                SpawnArcView(shotPos, targetPositions[0], 0.72f);
            for (int i = 1; i < targetPositions.Count; i++)
                SpawnArcView(targetPositions[i - 1], targetPositions[i], 0.86f);

            for (int i = 0; i < targets.Count; i++)
                DamageHazardByArc(targets[i], ArcChainDamage);
        }

        private int FindNextArcChainTarget(Vector2 from, List<int> usedIndices, RectTransform root)
        {
            int bestIndex = -1;
            float bestDistance = float.MaxValue;
            for (int i = 0; i < hazards.Count; i++)
            {
                if (usedIndices.Contains(i))
                    continue;

                HazardView hazard = hazards[i];
                if (hazard.Root == null || hazard.Symbiote)
                    continue;

                Vector2 enemyPos = GetHazardCanvasPosition(hazard, root);
                float distance = Vector2.Distance(from, enemyPos);
                if (distance > ArcChainJumpRange || distance >= bestDistance)
                    continue;

                bestDistance = distance;
                bestIndex = i;
            }

            return bestIndex;
        }

        private void DamageHazardByModule(int index, float damage, RectTransform root, int scoreValue)
        {
            if (index < 0 || index >= hazards.Count)
                return;

            HazardView hazard = hazards[index];
            if (hazard.Root == null)
                return;

            Vector2 enemyPos = GetHazardCanvasPosition(hazard, root);
            hazard.Health -= damage;
            TriggerHazardHitFeedback(hazard);
            if (hazard.Health > 0f)
                return;

            ResolveHazardDestroyedByWeapon(hazard, enemyPos);
            score += scoreValue;
            if (hazard.Root != null)
                Destroy(hazard.Root.gameObject);
            hazards.RemoveAt(index);
            RefreshHud();
            RefreshUpgradeLabels();
        }

        private void DamageHazardByArc(int index, float damage)
        {
            if (index < 0 || index >= hazards.Count)
                return;

            HazardView hazard = hazards[index];
            if (hazard.Root == null)
                return;

            hazard.Health -= damage;
            TriggerHazardHitFeedback(hazard);
            hazard.ElectricShockTimer = ArcShockSeconds;
            hazard.ElectricShockAge = 0f;
            hazard.ElectricAnchorPosition = hazard.Root.anchoredPosition;
            hazard.ElectricDeathPending = hazard.Health <= 0f;

            if (hazard.Image != null)
                hazard.Image.color = new Color(0.72f, 1f, 1f, 1f);
        }

        private void KillHazardByModule(int index, RectTransform root, int scoreValue)
        {
            if (index < 0 || index >= hazards.Count)
                return;

            HazardView hazard = hazards[index];
            if (hazard.Root == null)
                return;

            Vector2 enemyPos = GetHazardCanvasPosition(hazard, root);
            ResolveHazardDestroyedByWeapon(hazard, enemyPos);
            score += scoreValue;
            Destroy(hazard.Root.gameObject);
            hazards.RemoveAt(index);
            RefreshHud();
            RefreshUpgradeLabels();
        }

        private void ResolveHazardDestroyedByWeapon(HazardView hazard, Vector2 enemyPos)
        {
            SpawnMineExplosion(enemyPos);
            PlayEnemyDeathSound();
            if (hazard.TutorialMaterialEnemy)
            {
                SpawnPartDrop(enemyPos);
                return;
            }

            if (hazard.SeekerMine)
                ResolveMineDetonation(enemyPos, hazard);

            if (hazard.HeavyMineTier == 1)
            {
                SpawnHeavyMineSplit(enemyPos, 2, hazard.BossPhaseMinion);
                return;
            }

            if (hazard.HeavyMineTier == 2)
            {
                SpawnHeavyMineSplit(enemyPos, 3, hazard.BossPhaseMinion);
                return;
            }

            SpawnPartDrop(enemyPos);
        }

        private static void TriggerHazardHitFeedback(HazardView hazard)
        {
            if (hazard == null || hazard.Root == null)
                return;

            hazard.HitFeedbackTimer = HazardHitFeedbackSeconds;
            hazard.HitFeedbackAge = 0f;
        }

        private void SpawnPartDrop(Vector2 position)
        {
            GameObject go = new GameObject("OzPartDrop", typeof(RectTransform), typeof(CanvasRenderer), typeof(Image));
            go.transform.SetParent(playfield, false);

            RectTransform rect = go.GetComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = new Vector2(RandomRange(36f, 46f), RandomRange(36f, 46f));
            rect.anchoredPosition = position;

            Image image = go.GetComponent<Image>();
            Sprite partSprite = GetSpriteFromTextureResource(OzPartSpriteResourcePrefix + random.Next(0, 5));
            if (partSprite != null)
            {
                image.sprite = partSprite;
                image.color = Color.white;
                image.preserveAspect = true;
            }
            else
            {
                image.color = new Color(0.95f, 0.76f, 0.26f, 1f);
            }

            image.raycastTarget = false;
            if (partSprite == null)
                AddOutline(rect, new Color(0.24f, 0.90f, 1f, 0.45f), new Vector2(2f, -2f));

            partDrops.Add(new PartDropView
            {
                Root = rect,
                Value = 1,
                Radius = 38f,
                Lifetime = tutorialMaterialLessonActive ? -1f : 3f,
                FallSpeed = tutorialMaterialLessonActive ? 0f : RandomRange(95f, 140f),
                TutorialMaterialPart = tutorialMaterialLessonActive
            });

        }

        private void SpawnCargoUnloadViews(int count)
        {
            if (playfield == null || orb == null || count <= 0)
                return;

            Vector2 start = orb.anchoredPosition + new Vector2(0f, -8f);
            Vector2 target = ResolveHangarCargoBayPosition();
            SpawnCargoUnloadViews(count, start, target);
        }

        private void SpawnCargoUnloadViews(int count, Vector2 start, Vector2 target)
        {
            if (playfield == null || count <= 0)
                return;

            int visualCount = Mathf.Clamp(count, 3, 14);
            for (int i = 0; i < visualCount; i++)
            {
                GameObject go = new GameObject("CargoUnloadPart", typeof(RectTransform), typeof(CanvasRenderer), typeof(Image));
                go.transform.SetParent(playfield, false);

                RectTransform rect = go.GetComponent<RectTransform>();
                rect.anchorMin = new Vector2(0.5f, 0.5f);
                rect.anchorMax = new Vector2(0.5f, 0.5f);
                rect.pivot = new Vector2(0.5f, 0.5f);
                rect.sizeDelta = Vector2.one * RandomRange(24f, 34f);
                rect.anchoredPosition = start + new Vector2(RandomRange(-18f, 18f), RandomRange(-8f, 14f));
                rect.localRotation = Quaternion.Euler(0f, 0f, RandomRange(0f, 360f));

                Image image = go.GetComponent<Image>();
                Sprite partSprite = GetSpriteFromTextureResource(OzPartSpriteResourcePrefix + random.Next(0, 5));
                if (partSprite != null)
                {
                    image.sprite = partSprite;
                    image.color = Color.white;
                    image.preserveAspect = true;
                }
                else
                {
                    image.color = new Color(0.95f, 0.76f, 0.26f, 1f);
                    AddOutline(rect, new Color(0.24f, 0.90f, 1f, 0.45f), new Vector2(2f, -2f));
                }

                image.raycastTarget = false;
                float side = (i - (visualCount - 1) * 0.5f) / Mathf.Max(1f, visualCount - 1f);
                Vector2 scatter = new Vector2(side * RandomRange(70f, 125f) + RandomRange(-24f, 24f), RandomRange(48f, 96f));
                float delay = i * 0.045f + RandomRange(0f, 0.045f);
                float duration = RandomRange(0.58f, 0.86f);
                cargoUnloadViews.Add(new CargoUnloadView
                {
                    Root = rect,
                    Image = image,
                    Start = rect.anchoredPosition,
                    Control = Vector2.Lerp(start, target, 0.45f) + scatter,
                    End = target + new Vector2(RandomRange(-42f, 42f), RandomRange(-18f, 20f)),
                    Delay = delay,
                    Duration = duration,
                    Age = -delay,
                    Spin = RandomRange(-420f, 420f),
                    StartSize = rect.sizeDelta.x
                });
            }

            PlayPartPickupSound();
        }

        private void UpdateCargoUnloadViews()
        {
            for (int i = cargoUnloadViews.Count - 1; i >= 0; i--)
            {
                CargoUnloadView view = cargoUnloadViews[i];
                if (view.Root == null)
                {
                    cargoUnloadViews.RemoveAt(i);
                    continue;
                }

                view.Age += Time.deltaTime;
                if (view.Age < 0f)
                {
                    view.Root.gameObject.SetActive(false);
                    continue;
                }

                if (!view.Root.gameObject.activeSelf)
                    view.Root.gameObject.SetActive(true);

                float t = Mathf.Clamp01(view.Age / Mathf.Max(0.01f, view.Duration));
                float smooth = Mathf.SmoothStep(0f, 1f, t);
                Vector2 a = Vector2.Lerp(view.Start, view.Control, smooth);
                Vector2 b = Vector2.Lerp(view.Control, view.End, smooth);
                view.Root.anchoredPosition = Vector2.Lerp(a, b, smooth);
                view.Root.Rotate(0f, 0f, view.Spin * Time.deltaTime);
                float size = Mathf.Lerp(view.StartSize, view.StartSize * 0.46f, Mathf.Clamp01((t - 0.35f) / 0.65f));
                view.Root.sizeDelta = Vector2.one * size;

                if (view.Image != null)
                {
                    float alpha = 1f - Mathf.Clamp01((t - 0.74f) / 0.26f);
                    Color color = view.Image.color;
                    color.a = alpha;
                    view.Image.color = color;
                }

                if (t >= 1f)
                {
                    Destroy(view.Root.gameObject);
                    cargoUnloadViews.RemoveAt(i);
                }
            }
        }

        private void UpdatePartDrops()
        {
            RectTransform root = canvas.transform as RectTransform;
            if (root == null || orb == null)
                return;

            Vector2 orbPos = orb.anchoredPosition;
            for (int i = partDrops.Count - 1; i >= 0; i--)
            {
                PartDropView part = partDrops[i];
                if (part.Root == null)
                {
                    partDrops.RemoveAt(i);
                    continue;
                }

                if (!part.TutorialMaterialPart)
                {
                    part.Lifetime -= Time.deltaTime;
                    UpdatePartDropFadeWarning(part);
                    if (part.Lifetime <= 0f)
                    {
                        Destroy(part.Root.gameObject);
                        partDrops.RemoveAt(i);
                        continue;
                    }
                }
                else
                {
                    Image image = part.Root.GetComponent<Image>();
                    if (image != null)
                        image.color = Color.white;
                }

                part.Root.Rotate(0f, 0f, 90f * Time.deltaTime);
                if (!part.TutorialMaterialPart)
                    part.Root.anchoredPosition += Vector2.down * part.FallSpeed * Time.deltaTime;
                Vector2 partPos = part.Root.anchoredPosition;
                if (Vector2.Distance(orbPos, partPos) <= part.Radius + 21f)
                {
                    if (CollectPart(part))
                    {
                        Destroy(part.Root.gameObject);
                        partDrops.RemoveAt(i);
                    }
                    continue;
                }

                if (part.Root.anchoredPosition.y < -root.rect.height * 0.55f - 120f)
                {
                    if (part.TutorialMaterialPart)
                        continue;

                    Destroy(part.Root.gameObject);
                    partDrops.RemoveAt(i);
                }
            }
        }

        private bool CollectPart(PartDropView part)
        {
            int value = Mathf.Max(1, part.Value);
            int capacity = CurrentCarryCapacity();
            if (carriedParts >= capacity)
            {
                if (statusText != null)
                    statusText.text = "CARGO FULL";
                RefreshHud();
                return false;
            }

            carriedParts = Mathf.Min(capacity, carriedParts + value);
            if (tutorialMaterialLessonActive && !tutorialReturnPartsDialogShown && tutorialMaterialDelivered + carriedParts >= tutorialMaterialTarget)
            {
                tutorialReturnPartsDialogShown = true;
                tutorialManualReturnToBaseActive = true;
                StartCoroutine(TutorialReturnPartsDialogRoutine());
            }

            PlayPartPickupSound();
            RefreshHud();
            return true;
        }

        private bool TryMimicRepairSharedHealthWithParts(string repairSource)
        {
            bool repaired = TryMimicRepairWithParts(ref baseShipHealth, CurrentSharedMaxHealth(), repairSource);
            if (repaired)
            {
                SyncOrbHealthFromBaseShip();
                RefreshHud();
            }
            return repaired;
        }

        private void UpdatePartDropFadeWarning(PartDropView part)
        {
            if (part.Root == null)
                return;

            Image image = part.Root.GetComponent<Image>();
            if (image == null)
                return;

            float warning = Mathf.Clamp01((1.35f - part.Lifetime) / 1.35f);
            if (warning <= 0f)
            {
                image.color = Color.white;
                return;
            }

            float blinkSpeed = Mathf.Lerp(7f, 18f, warning);
            float alpha = Mathf.Lerp(0.28f, 1f, Mathf.PingPong(Time.time * blinkSpeed, 1f));
            image.color = new Color(1f, 1f, 1f, alpha);
        }

        private int ResolveHazardImpactDamage(HazardView hazard)
        {
            if (hazard != null && (hazard.SeekerMine || hazard.HeavyMineTier > 0))
                return Mathf.Max(1, Mathf.RoundToInt(hazard.Health));

            return EnemyDamage;
        }

        private int ResolveHazardExplosionDamage(HazardView hazard, float distance)
        {
            if (hazard != null && hazard.SeekerMine)
                return Mathf.Max(1, Mathf.RoundToInt(hazard.Health * HomingMineExplosionDamageFactor));

            float falloff = 1f - Mathf.Clamp01(distance / MineExplosionBlastRadius) * 0.55f;
            return Mathf.Max(EnemyDamage, Mathf.RoundToInt(MineExplosionDamage * falloff));
        }

        private bool TryAcquireSeekerMineTarget(HazardView hazard, Vector2 hazardPos)
        {
            if (hazard == null)
                return false;

            RectTransform bestTarget = null;
            Vector2 bestPosition = Vector2.zero;
            float bestDistance = float.MaxValue;

            TryConsiderSeekerTarget(orb, hazardPos, ref bestTarget, ref bestPosition, ref bestDistance);
            TryConsiderSeekerTarget(crafterDrone, hazardPos, ref bestTarget, ref bestPosition, ref bestDistance);
            TryConsiderSeekerTarget(generatorDrone, hazardPos, ref bestTarget, ref bestPosition, ref bestDistance);
            TryConsiderSeekerTarget(repairDrone, hazardPos, ref bestTarget, ref bestPosition, ref bestDistance);
            TryConsiderSeekerTarget(shieldDrone, hazardPos, ref bestTarget, ref bestPosition, ref bestDistance);
            TryConsiderSeekerTarget(collectorDrone, hazardPos, ref bestTarget, ref bestPosition, ref bestDistance);
            TryConsiderSeekerTarget(tamerDrone, hazardPos, ref bestTarget, ref bestPosition, ref bestDistance);
            TryConsiderSeekerTarget(hiveDrone, hazardPos, ref bestTarget, ref bestPosition, ref bestDistance);
            TryConsiderHiveMiniTurretTargets(hazardPos, ref bestTarget, ref bestPosition, ref bestDistance);

            if (bestTarget == null)
                return false;

            hazard.SeekerTarget = bestTarget;
            hazard.SeekerTargetPosition = bestPosition;
            return true;
        }

        private static void TryConsiderSeekerTarget(RectTransform target, Vector2 hazardPos, ref RectTransform bestTarget, ref Vector2 bestPosition, ref float bestDistance)
        {
            if (target == null || !target.gameObject.activeInHierarchy)
                return;

            Vector2 targetPosition = target.anchoredPosition;
            float distance = Vector2.Distance(hazardPos, targetPosition);
            if (distance > HomingMineTriggerRadius || distance >= bestDistance)
                return;

            bestTarget = target;
            bestPosition = targetPosition;
            bestDistance = distance;
        }

        private void TryConsiderHiveMiniTurretTargets(Vector2 hazardPos, ref RectTransform bestTarget, ref Vector2 bestPosition, ref float bestDistance)
        {
            for (int i = 0; i < hiveMiniTurrets.Count; i++)
            {
                HiveMiniTurretView turret = hiveMiniTurrets[i];
                if (turret == null)
                    continue;

                TryConsiderSeekerTarget(turret.Root, hazardPos, ref bestTarget, ref bestPosition, ref bestDistance);
            }
        }

        private void UpdateForwardDefenseHazard(HazardView hazard, Vector2 currentHazardPos, Vector2 orbPos)
        {
            if (hazard == null || hazard.Root == null)
                return;

            hazard.ForwardAttackTimer -= Time.deltaTime;
            hazard.ForwardBoostTimer = Mathf.Max(0f, hazard.ForwardBoostTimer - Time.deltaTime);
            hazard.ForwardShieldTimer = Mathf.Max(0f, hazard.ForwardShieldTimer - Time.deltaTime);
            float boost = hazard.ForwardBoostTimer > 0f ? 1.35f : 1f;
            Vector2 move = Vector2.down * hazard.Speed;

            switch (hazard.ForwardDefense)
            {
                case ForwardDefenseType.SentinelScout:
                    move.x = Mathf.Sin(Time.time * 2.8f + hazard.ForwardPhase) * hazard.HorizontalSpeed;
                    if (hazard.ForwardAttackTimer <= 0f)
                    {
                        SpawnEnemyProjectile(currentHazardPos, ResolveProjectileDirection(currentHazardPos, orbPos), ForwardDefenseType.SentinelScout);
                        hazard.ForwardAttackTimer = RandomRange(1.25f, 1.85f) / boost;
                    }
                    break;
                case ForwardDefenseType.PulseTurret:
                    move *= 0.42f;
                    if (hazard.ForwardAttackTimer <= 0f)
                    {
                        SpawnEnemyProjectile(currentHazardPos, ResolveProjectileDirection(currentHazardPos, orbPos), ForwardDefenseType.PulseTurret);
                        hazard.ForwardAttackTimer = RandomRange(2.45f, 3.25f) / boost;
                    }
                    break;
                case ForwardDefenseType.ShieldRelay:
                    move *= 0.62f;
                    ApplyForwardDefenseShieldRelay(hazard);
                    if (hazard.ForwardAttackTimer <= 0f)
                    {
                        SpawnEnemyProjectile(currentHazardPos, Vector2.down, ForwardDefenseType.ShieldRelay);
                        hazard.ForwardAttackTimer = ForwardDefenseShieldPulseInterval;
                    }
                    break;
                case ForwardDefenseType.InterceptorDrone:
                    if (hazard.ForwardDashTimer > 0f)
                    {
                        hazard.ForwardDashTimer -= Time.deltaTime;
                        move = ResolveProjectileDirection(currentHazardPos, orbPos) * Mathf.Max(520f, hazard.Speed * 3.8f);
                    }
                    else
                    {
                        move.x = Mathf.Sin(Time.time * 3.6f + hazard.ForwardPhase) * hazard.HorizontalSpeed * 1.35f;
                    }

                    if (hazard.ForwardAttackTimer <= 0f)
                    {
                        hazard.ForwardDashTimer = 0.65f;
                        SpawnEnemyProjectile(currentHazardPos, ResolveProjectileDirection(currentHazardPos, orbPos), ForwardDefenseType.InterceptorDrone);
                        hazard.ForwardAttackTimer = RandomRange(3.0f, 4.2f) / boost;
                    }
                    break;
                case ForwardDefenseType.CommandNode:
                    move *= 0.34f;
                    if (hazard.ForwardAttackTimer <= 0f)
                    {
                        ApplyForwardDefenseCommandPulse(currentHazardPos);
                        SpawnEnemyProjectile(currentHazardPos, ResolveProjectileDirection(currentHazardPos, orbPos), ForwardDefenseType.CommandNode);
                        hazard.ForwardAttackTimer = ForwardDefenseCommandPulseInterval;
                    }
                    break;
            }

            hazard.Root.anchoredPosition += move * Time.deltaTime;
        }

        private void ApplyForwardDefenseShieldRelay(HazardView source)
        {
            if (source == null || source.Root == null)
                return;

            for (int i = 0; i < hazards.Count; i++)
            {
                HazardView hazard = hazards[i];
                if (hazard == null || hazard == source || hazard.Root == null || hazard.ForwardDefense == ForwardDefenseType.None)
                    continue;

                if (Vector2.Distance(source.Root.anchoredPosition, hazard.Root.anchoredPosition) <= ForwardDefenseShieldRadius)
                    hazard.ForwardShieldTimer = 0.35f;
            }
        }

        private void ApplyForwardDefenseCommandPulse(Vector2 sourcePos)
        {
            for (int i = 0; i < hazards.Count; i++)
            {
                HazardView hazard = hazards[i];
                if (hazard == null || hazard.Root == null || hazard.ForwardDefense == ForwardDefenseType.None || hazard.ForwardDefense == ForwardDefenseType.CommandNode)
                    continue;

                if (Vector2.Distance(sourcePos, hazard.Root.anchoredPosition) <= ForwardDefenseShieldRadius * 1.2f)
                    hazard.ForwardBoostTimer = 4.0f;
            }
        }

        private static void UpdateHazardHitFeedback(HazardView hazard)
        {
            if (hazard == null || hazard.Root == null)
                return;

            if (hazard.HitFeedbackTimer <= 0f)
            {
                if (Mathf.Abs(hazard.HitFeedbackRotationOffset) > 0.001f)
                {
                    hazard.Root.Rotate(0f, 0f, -hazard.HitFeedbackRotationOffset);
                    hazard.HitFeedbackRotationOffset = 0f;
                }
                hazard.Root.localScale = Vector3.one;
                if (hazard.Image != null && !hazard.ElectricDeathPending)
                    hazard.Image.color = Color.white;
                return;
            }

            hazard.HitFeedbackTimer -= Time.deltaTime;
            hazard.HitFeedbackAge += Time.deltaTime;
            float t = Mathf.Clamp01(hazard.HitFeedbackTimer / HazardHitFeedbackSeconds);
            float shake = Mathf.Sin(hazard.HitFeedbackAge * 95f) * t;
            float rotationOffset = shake * 2.6f;
            hazard.Root.Rotate(0f, 0f, rotationOffset - hazard.HitFeedbackRotationOffset);
            hazard.HitFeedbackRotationOffset = rotationOffset;
            hazard.Root.localScale = new Vector3(
                1f + 0.035f * Mathf.Abs(shake),
                1f - 0.022f * Mathf.Abs(shake),
                1f);
            if (hazard.Image != null && !hazard.ElectricDeathPending)
            {
                Color flash = hazard.HeavyMineTier > 0 ? new Color(1f, 0.82f, 0.34f, 1f) : Color.white;
                hazard.Image.color = Color.Lerp(Color.white, flash, Mathf.Clamp01(t * 0.72f));
            }
        }

        private void UpdateHazards()
        {
            RectTransform root = canvas.transform as RectTransform;
            if (root == null || orb == null)
                return;

            Vector2 orbPos = orb.anchoredPosition;

            for (int i = hazards.Count - 1; i >= 0; i--)
            {
                HazardView hazard = hazards[i];
                if (hazard.Root == null)
                {
                    hazards.RemoveAt(i);
                    continue;
                }

                if (hazard.ElectricShockTimer > 0f)
                {
                    hazard.ElectricShockTimer -= Time.deltaTime;
                    hazard.ElectricShockAge += Time.deltaTime;
                    float shakeX = Mathf.Sin(Time.time * 96f + i * 1.7f) * 8f;
                    float shakeY = Mathf.Cos(Time.time * 83f + i * 2.3f) * 5f;
                    hazard.Root.anchoredPosition = hazard.ElectricAnchorPosition + new Vector2(shakeX, shakeY);
                    hazard.Root.Rotate(0f, 0f, Mathf.Sin(Time.time * 120f) * 8f);
                    if (hazard.Image != null)
                    {
                        float pulse = 0.5f + Mathf.Sin(Time.time * 42f) * 0.5f;
                        hazard.Image.color = Color.Lerp(Color.white, new Color(0.20f, 0.96f, 1f, 1f), pulse);
                    }

                    if (hazard.ElectricShockTimer <= 0f)
                    {
                        hazard.Root.anchoredPosition = hazard.ElectricAnchorPosition;
                        if (hazard.ElectricDeathPending)
                        {
                            KillHazardByModule(i, root, 18);
                            continue;
                        }

                        if (hazard.Image != null)
                            hazard.Image.color = Color.white;
                        hazard.ElectricDeathPending = false;
                    }

                    continue;
                }

                if (hazard.TamerParalyzeTimer > 0f)
                {
                    hazard.TamerParalyzeTimer -= Time.deltaTime;
                    hazard.Velocity = Vector2.zero;
                    hazard.Root.Rotate(0f, 0f, Mathf.Sin(Time.time * 68f + i) * 3.5f);
                    UpdateHazardHitFeedback(hazard);
                    if (hazard.Image != null && !hazard.ElectricDeathPending)
                    {
                        float pulse = 0.5f + Mathf.Sin(Time.time * 28f) * 0.5f;
                        hazard.Image.color = Color.Lerp(Color.white, new Color(0.22f, 1f, 0.86f, 1f), 0.30f + pulse * 0.38f);
                    }
                    continue;
                }

                Vector2 previousPosition = hazard.Root.anchoredPosition;
                Vector2 currentHazardPos = hazard.Root.anchoredPosition + new Vector2(0f, root.rect.height * 0.5f);
                if (hazard.ForwardDefense != ForwardDefenseType.None)
                {
                    UpdateForwardDefenseHazard(hazard, currentHazardPos, orbPos);
                }
                else if (hazard.SeekerMine)
                {
                    if (!hazard.SeekerTriggered && TryAcquireSeekerMineTarget(hazard, currentHazardPos))
                    {
                        hazard.SeekerTriggered = true;
                        hazard.Spin = HomingMineAttackSpin;
                        if (statusText != null)
                            statusText.text = L("status.seeker_mine_locked");
                    }

                    if (hazard.SeekerTriggered)
                    {
                        if (hazard.SeekerTarget != null && hazard.SeekerTarget.gameObject.activeInHierarchy)
                            hazard.SeekerTargetPosition = hazard.SeekerTarget.anchoredPosition;

                        Vector2 nextHazardPos = Vector2.MoveTowards(currentHazardPos, hazard.SeekerTargetPosition, HomingMineAttackSpeed * Time.deltaTime);
                        hazard.Root.anchoredPosition = nextHazardPos - new Vector2(0f, root.rect.height * 0.5f);
                    }
                    else
                    {
                        hazard.Root.anchoredPosition += Vector2.down * hazard.Speed * Time.deltaTime;
                    }
                }
                else if (hazard.HeavyMineTier == 3)
                {
                    Vector2 nextHazardPos = Vector2.MoveTowards(currentHazardPos, orbPos, hazard.Speed * Time.deltaTime);
                    hazard.Root.anchoredPosition = nextHazardPos - new Vector2(0f, root.rect.height * 0.5f);
                }
                else if (hazard.HeavyMineTier > 0)
                {
                    Vector2 drift = hazard.SplitDirection.sqrMagnitude > 0.01f ? hazard.SplitDirection * 0.38f : Vector2.zero;
                    Vector2 direction = (Vector2.down + drift).normalized;
                    hazard.Root.anchoredPosition += direction * hazard.Speed * Time.deltaTime;
                }
                else if (hazard.Homing)
                {
                    float x = Mathf.MoveTowards(hazard.Root.anchoredPosition.x, orb.anchoredPosition.x, hazard.HorizontalSpeed * Time.deltaTime);
                    hazard.Root.anchoredPosition = new Vector2(x, hazard.Root.anchoredPosition.y);
                    hazard.Root.anchoredPosition += Vector2.down * hazard.Speed * Time.deltaTime;
                }
                else
                {
                    hazard.Root.anchoredPosition += Vector2.down * hazard.Speed * Time.deltaTime;
                }
                if (hazard.Symbiote)
                {
                    Vector2 linkCenter = hazard.Root.anchoredPosition + new Vector2(0f, root.rect.height * 0.5f);
                    float linkDistance = Vector2.Distance(orbPos, linkCenter);
                    if (linkDistance <= SymbiosisLinkAttractRadius)
                    {
                        float pull = Mathf.Lerp(SymbiosisLinkAttractSpeed, SymbiosisLinkAttractSpeed * 0.42f, linkDistance / SymbiosisLinkAttractRadius);
                        Vector2 targetAnchoredPosition = orbPos - new Vector2(0f, root.rect.height * 0.5f);
                        hazard.Root.anchoredPosition = Vector2.MoveTowards(hazard.Root.anchoredPosition, targetAnchoredPosition, pull * Time.deltaTime);
                    }
                }

                hazard.Velocity = Time.deltaTime > 0f ? (hazard.Root.anchoredPosition - previousPosition) / Time.deltaTime : Vector2.down * hazard.Speed;
                hazard.Root.Rotate(0f, 0f, hazard.Spin * Time.deltaTime);
                UpdateHazardHitFeedback(hazard);
                if (hazard.Symbiote)
                    UpdateSymbioteLinkVisual(hazard);

                Vector2 hazardPos = hazard.Root.anchoredPosition;
                hazardPos.y += root.rect.height * 0.5f;
                int hazardDamage = ResolveHazardImpactDamage(hazard);
                if (!hazard.Symbiote && TryHitShieldDrone(hazardPos, hazard.Radius, hazardDamage))
                {
                    SpawnMineExplosion(hazardPos);
                    PlayEnemyDeathSound();
                    DropTutorialMaterialPartIfNeeded(hazard, hazardPos);
                    ResolveMineDetonation(hazardPos, hazard);
                    Destroy(hazard.Root.gameObject);
                    hazards.RemoveAt(i);
                    continue;
                }

                if (!hazard.Symbiote && hazard.ForwardDefense == ForwardDefenseType.None && !hazard.SeekerMine && Vector2.Distance(orbPos, hazardPos) <= MineProximityDetonationRadius)
                {
                    SpawnMineExplosion(hazardPos);
                    PlayEnemyDeathSound();
                    DropTutorialMaterialPartIfNeeded(hazard, hazardPos);
                    ResolveMineDetonation(hazardPos, hazard);
                    Destroy(hazard.Root.gameObject);
                    hazards.RemoveAt(i);
                    continue;
                }

                if (!hazard.Symbiote && TryHitDrones(hazardPos, hazard.Radius, hazardDamage))
                {
                    SpawnMineExplosion(hazardPos);
                    PlayEnemyDeathSound();
                    DropTutorialMaterialPartIfNeeded(hazard, hazardPos);
                    ResolveMineDetonation(hazardPos, hazard);
                    Destroy(hazard.Root.gameObject);
                    hazards.RemoveAt(i);
                    continue;
                }

                if (!hazard.Symbiote && TryHitOutpost(hazardPos, hazard.Radius, hazardDamage))
                {
                    SpawnMineExplosion(hazardPos);
                    PlayEnemyDeathSound();
                    DropTutorialMaterialPartIfNeeded(hazard, hazardPos);
                    ResolveMineDetonation(hazardPos, hazard);
                    Destroy(hazard.Root.gameObject);
                    hazards.RemoveAt(i);
                    continue;
                }

                if (!hazard.Symbiote && TryHitBaseShip(hazardPos, hazard.Radius, hazardDamage))
                {
                    SpawnMineExplosion(hazardPos);
                    PlayEnemyDeathSound();
                    DropTutorialMaterialPartIfNeeded(hazard, hazardPos);
                    ResolveMineDetonation(hazardPos, hazard);
                    Destroy(hazard.Root.gameObject);
                    hazards.RemoveAt(i);
                    continue;
                }

                float hitDistance = hazard.Symbiote ? 43f : hazard.Radius + 21f;
                if (Vector2.Distance(orbPos, hazardPos) <= hitDistance)
                {
                    if (!hazard.Symbiote)
                    {
                        SpawnMineExplosion(hazardPos);
                        PlayEnemyDeathSound();
                        DropTutorialMaterialPartIfNeeded(hazard, hazardPos);
                    }
                    ResolveHit(hazard);
                    Destroy(hazard.Root.gameObject);
                    hazards.RemoveAt(i);
                    continue;
                }

                if (hazard.Root.anchoredPosition.y < -root.rect.height - 140f)
                {
                    DropTutorialMaterialPartIfNeeded(hazard, new Vector2(hazard.Root.anchoredPosition.x, -root.rect.height * 0.42f));
                    Destroy(hazard.Root.gameObject);
                    hazards.RemoveAt(i);
                }
            }
        }

        private void DropTutorialMaterialPartIfNeeded(HazardView hazard, Vector2 position)
        {
            if (hazard == null || !hazard.TutorialMaterialEnemy || !tutorialMaterialLessonActive)
                return;

            SpawnPartDrop(position);
        }

