        private bool TryHitBaseShip(Vector2 hazardPos, float hazardRadius, int damage)
        {
            if (baseShipHull == null || !baseShipHull.gameObject.activeSelf || baseShipHealth <= 0)
                return false;

            if (!TryGetBaseShipBounds(out Rect bounds))
                return false;

            bounds.xMin -= hazardRadius + BaseShipHitRadiusPadding;
            bounds.xMax += hazardRadius + BaseShipHitRadiusPadding;
            bounds.yMin -= hazardRadius + BaseShipHitRadiusPadding;
            bounds.yMax += hazardRadius + BaseShipHitRadiusPadding;
            if (!bounds.Contains(hazardPos))
                return false;

            ApplyBaseShipDamage(damage, "BASE SHIP HIT");
            return true;
        }

        private bool TryHitOutpost(Vector2 hazardPos, float hazardRadius, int damage)
        {
            if (!outpostBuilt || baseShipHealth <= 0)
                return false;

            for (int i = 0; i < outpostSlots.Length; i++)
            {
                RectTransform slot = outpostSlots[i];
                if (slot == null || !slot.gameObject.activeSelf)
                    continue;

                float radius = Mathf.Max(42f, ResolveOutpostSlotSize(i).x * 0.46f);
                if (Vector2.Distance(hazardPos, ResolveOutpostSlotPosition(i)) > hazardRadius + radius)
                    continue;

                ApplySharedHealthDamage(damage, "OUTPOST HIT");
                return true;
            }

            return false;
        }

        private bool TryGetBaseShipBounds(out Rect bounds)
        {
            bounds = new Rect();
            RectTransform world = WorldCoordinateRoot();
            if (world == null || baseShipHull == null)
                return false;

            Vector3[] corners = new Vector3[4];
            baseShipHull.GetWorldCorners(corners);
            Vector2 min = world.InverseTransformPoint(corners[0]);
            Vector2 max = min;
            for (int i = 1; i < corners.Length; i++)
            {
                Vector2 point = world.InverseTransformPoint(corners[i]);
                min = Vector2.Min(min, point);
                max = Vector2.Max(max, point);
            }

            bounds = Rect.MinMaxRect(min.x, min.y, max.x, max.y);
            return true;
        }

        private void ApplyBaseShipDamage(int damage, string message)
        {
            ApplySharedHealthDamage(damage, message);
        }

        private bool ShouldOutpostAbsorbOrbHit()
        {
            return outpostBuilt && IsOrbDockedOnOutpost();
        }

        private bool TryHitShieldDrone(Vector2 hazardPos, float hazardRadius, int damage)
        {
            if (!shieldDroneSpawnedThisRun || shieldDrone == null || !shieldDrone.gameObject.activeSelf)
                return false;

            float protectRadius = shieldDroneAttached ? 42f : 30f;
            if (Vector2.Distance(hazardPos, shieldDronePosition) > hazardRadius + protectRadius)
                return false;

            if (tutorialShieldHangarLessonActive || tutorialShieldAttachLessonActive)
            {
                shieldDroneHealth = ShieldDroneMaxHealth;
                if (statusText != null)
                    statusText.text = "SHIELD DRONE TRAINING LINK";
                return true;
            }

            shieldDroneHealth -= damage;
            if (shieldDroneHealth <= 0)
            {
                PlayDroneBreakSound();
                shieldDrone.gameObject.SetActive(false);
                shieldDroneSpawnedThisRun = false;
                shieldDroneAttached = false;
                shieldDroneFlyingToOrb = false;
                shieldDroneDragging = false;
                shieldDroneHealth = ShieldDroneMaxHealth;
                if (shieldDroneLaser != null)
                    shieldDroneLaser.gameObject.SetActive(false);
                if (statusText != null)
                    statusText.text = "SHIELD DRONE DOWN";
            }
            else if (statusText != null)
            {
                statusText.text = "SHIELD DRONE HIT";
            }

            return true;
        }

        private void ResolveHit(HazardView hazard)
        {
            if (hazard.Symbiote)
            {
                score += 35;
                statusText.text = "+35 LINK BONUS";
                RefreshHud();
                return;
            }

            int damage = ResolveHazardImpactDamage(hazard);
            if (ShouldOutpostAbsorbOrbHit())
            {
                ApplySharedHealthDamage(damage, "OUTPOST ABSORBED HIT");
                return;
            }

            if (shield > 0)
            {
                shield--;
                shieldChargeTimer = 0f;
                statusText.text = "SHIELD ABSORBED IMPACT";
                RefreshHud();
                return;
            }

            ApplySharedHealthDamage(damage, "HULL DAMAGED");
        }

        private void ResolveMineDetonation(Vector2 explosionCenter, HazardView hazard)
        {
            if (orb == null)
                return;

            float distance = Vector2.Distance(orb.anchoredPosition, explosionCenter);
            bool damagedBaseShip = TryApplyBaseShipExplosionDamage(explosionCenter, hazard);
            if (distance > MineExplosionBlastRadius)
            {
                if (statusText != null)
                    statusText.text = damagedBaseShip ? "BASE SHIP BLASTED" : "MINE DETONATED";
                return;
            }

            int damage = ResolveHazardExplosionDamage(hazard, distance);
            if (ShouldOutpostAbsorbOrbHit())
            {
                ApplySharedHealthDamage(damage, "OUTPOST ABSORBED BLAST");
                return;
            }

            if (shield > 0)
            {
                shield--;
                shieldChargeTimer = 0f;
                if (statusText != null)
                    statusText.text = "MINE BLAST SHIELDED";
                RefreshHud();
                return;
            }

            ApplySharedHealthDamage(damage, "MINE DETONATED");
        }

        private bool TryApplyBaseShipExplosionDamage(Vector2 explosionCenter, HazardView hazard)
        {
            if (baseShipHull == null || !baseShipHull.gameObject.activeSelf || baseShipHealth <= 0)
                return false;
            if (!TryGetBaseShipBounds(out Rect bounds))
                return false;

            Vector2 nearest = new Vector2(Mathf.Clamp(explosionCenter.x, bounds.xMin, bounds.xMax), Mathf.Clamp(explosionCenter.y, bounds.yMin, bounds.yMax));
            float distance = Vector2.Distance(explosionCenter, nearest);
            if (distance > MineExplosionBlastRadius)
                return false;

            int damage = ResolveHazardExplosionDamage(hazard, distance);
            ApplyBaseShipDamage(damage, "BASE SHIP BLASTED");
            return true;
        }

        private void SpawnMineExplosion(Vector2 position)
        {
            if (playfield == null)
                return;

            GameObject go = new GameObject("MineExplosion", typeof(RectTransform), typeof(CanvasRenderer), typeof(Image));
            go.transform.SetParent(playfield, false);
            RectTransform root = go.GetComponent<RectTransform>();
            root.anchorMin = new Vector2(0.5f, 0.5f);
            root.anchorMax = new Vector2(0.5f, 0.5f);
            root.pivot = new Vector2(0.5f, 0.5f);
            root.sizeDelta = new Vector2(192f, 192f);
            root.anchoredPosition = position;

            Image image = go.GetComponent<Image>();
            image.raycastTarget = false;
            image.preserveAspect = true;
            image.color = Color.white;
            Sprite firstFrame = GetSpriteFromTextureResource(MineExplosionSpriteResourcePrefix + "0");
            if (firstFrame != null)
                image.sprite = firstFrame;

            explosions.Add(new ExplosionView
            {
                Root = root,
                Image = image,
                Lifetime = 0.42f,
                Age = 0f
            });
        }

        private void UpdateExplosions()
        {
            for (int i = explosions.Count - 1; i >= 0; i--)
            {
                ExplosionView explosion = explosions[i];
                if (explosion.Root == null)
                {
                    explosions.RemoveAt(i);
                    continue;
                }

                explosion.Age += Time.deltaTime;
                float t = Mathf.Clamp01(explosion.Age / Mathf.Max(0.01f, explosion.Lifetime));
                int frame = Mathf.Clamp(Mathf.FloorToInt(t * 6f), 0, 5);
                if (frame != explosion.Frame)
                {
                    explosion.Frame = frame;
                    if (explosion.Image != null)
                        explosion.Image.sprite = GetSpriteFromTextureResource(MineExplosionSpriteResourcePrefix + frame);
                }

                float pulse = 1f + Mathf.Sin(t * Mathf.PI) * 0.18f;
                explosion.Root.localScale = Vector3.one * pulse;
                explosion.Root.Rotate(0f, 0f, 36f * Time.deltaTime);
                if (explosion.Image != null)
                    explosion.Image.color = new Color(1f, 1f, 1f, Mathf.Clamp01((1f - t) * 1.25f));

                if (t >= 1f)
                {
                    Destroy(explosion.Root.gameObject);
                    explosions.RemoveAt(i);
                }
            }
        }

        private void EndRun()
        {
            if (gameOver)
                return;

            Time.timeScale = 1f;
            gameOver = true;
            state = GameState.GameOver;
            bestScore = Mathf.Max(bestScore, score);
            int convertedParts = testMode || storageDepotOwned ? 0 : ozParts;
            int convertedCore = convertedParts / OzPartsToCoreRate;
            if (convertedParts > 0)
            {
                ozParts = 0;
                if (convertedCore > 0)
                {
                    coreShards += convertedCore;
                    PlayerPrefs.SetInt(CoreShardsKey, coreShards);
                }

                PlayerPrefs.SetInt(OzPartsKey, ozParts);
                if (statusText != null)
                    statusText.text = "CONVERTED " + convertedParts + " PARTS TO " + convertedCore + " CORE";
            }
            PlayerPrefs.SetInt(BestScoreKey, bestScore);
            PlayerPrefs.Save();
            RefreshHud();
            RefreshUpgradeLabels();
            pendingDefeatConvertedCore = convertedCore;
            if (gameOverResultText != null)
                gameOverResultText.text = LF("gameover.result_core", score, bestScore, convertedCore);
            if (gameOverOverlay != null)
                gameOverOverlay.SetActive(true);
            if (defeatFlowRoutine != null)
            {
                StopCoroutine(defeatFlowRoutine);
                defeatFlowRoutine = null;
            }
        }

        private void EnterHangarRecoveryAfterDefeat(int convertedCore)
        {
            Time.timeScale = 1f;
            state = GameState.Menu;
            gameOver = false;
            transitioningToGame = false;
            stationControlOpen = false;
            modeSelectOpen = false;
            storyLevelsOpen = false;
            storyCinematicActive = false;
            storyMinesWavesStarted = false;
            pointerControl = false;
            pointerStartedOnUi = false;
            ResetHangarGesture();
            ResetHangarMouseCameraDrag();
            CleanupHazards();
            CleanupMinesBoss();
            CleanupStoryCinematicBoss();
            HideStoryDialog();
            HideRuntimeDrones();
            SetGameplayHudVisible(false);
            SetMenuVisible(false);
            if (gameTitleRoot != null)
                gameTitleRoot.gameObject.SetActive(false);
            if (gameLogoRoot != null)
                gameLogoRoot.gameObject.SetActive(false);
            if (menuBestText != null)
                menuBestText.gameObject.SetActive(false);
            if (upgradeRoot != null)
                upgradeRoot.gameObject.SetActive(false);
            if (settingsRoot != null)
                settingsRoot.gameObject.SetActive(false);
            if (stationControlRoot != null)
                stationControlRoot.gameObject.SetActive(false);
            if (bestiaryUi != null)
                bestiaryUi.Hide();
            if (gameOverOverlay != null)
                gameOverOverlay.SetActive(false);

            menuHangarOpen = true;
            hangarRecoveryActive = true;
            hangarRecoveryTimer = 0f;
            hangarRecoveryReturningToMenu = false;
            hangarRecoveryCrafterOrbit = RandomRange(0f, Mathf.PI * 2f);
            baseHangarExpanded = true;
            baseHangarRevealTransitioning = false;
            SetHangarRevealOffset(MaxHangarRevealOffset());
            if (menuHangarRoot != null)
                menuHangarRoot.gameObject.SetActive(true);
            if (menuHangarProfileRoot != null)
                menuHangarProfileRoot.gameObject.SetActive(false);

            Vector2 repairCenter = ResolveHangarRecoveryOrbPosition();
            laneX = repairCenter.x;
            orbY = repairCenter.y;
            targetLaneX = laneX;
            targetOrbY = orbY;
            orbScale = ResolveMenuHangarDockedOrbScale();
            targetOrbScale = orbScale;
            ApplyOrbScale();
            if (orb != null)
            {
                orb.anchoredPosition = repairCenter;
                orb.localRotation = Quaternion.identity;
                orb.gameObject.SetActive(true);
            }

            SetSharedHealthRatio(0.18f);
            shield = 0;
            carriedParts = 0;
            crafterPosition = repairCenter + new Vector2(96f, 0f);
            UpdateMenuHangarDisplay();
            if (statusText != null)
                statusText.text = convertedCore > 0 ? "CORE +" + convertedCore + "  ORB REBUILDING" : "ORB REBUILDING";
        }

        private void RefreshHud()
        {
            if (state == GameState.Playing || menuHangarOpen || hangarRecoveryActive)
                SyncOrbHealthFromBaseShip();

            if (scoreText != null)
                scoreText.text = score.ToString();
            if (partsText != null)
                partsText.text = testMode && state != GameState.Playing ? "PARTS INF" : state == GameState.Playing ? LF("hud.base", baseShipHealth, CurrentSharedMaxHealth()) : LF("hud.parts", ozParts);
            if (shieldText != null)
                shieldText.text = LF("hud.shield", shield);
            float healthRatio = state == GameState.Playing ? baseShipHealth / (float)CurrentSharedMaxHealth() : health / (float)CurrentMaxHealth();
            UpdateStatusBarFill(healthFill, healthRatio, Hazard, new Color(1f, 0.05f, 0.03f, 0.96f), true);
            UpdateBaseShipHealthBar(baseShipHull != null && baseShipHull.gameObject.activeSelf);
            UpdateStatusBarFill(shieldFill, shield / (float)CurrentMaxShield(), Cyan, new Color(0.04f, 0.24f, 0.72f, 0.92f), false);
            UpdateStatusBarFill(cargoFill, carriedParts / (float)CurrentCarryCapacity(), new Color(0.25f, 1f, 0.44f, 1f), new Color(0.08f, 0.36f, 0.16f, 0.92f), false);
        }

