        private void CreateSpaceParallax(RectTransform root)
        {
            parallaxLayers.Clear();
            CreateParallaxLayer(root, "SpaceBase", SpaceLoopBaseSpriteResourcePath, 18f, Color.white);
        }

        private void CreateParallaxLayer(RectTransform root, string name, string resourcePath, float speed, Color color)
        {
            Sprite sprite = GetSpriteFromTextureResource(resourcePath);
            if (sprite == null)
                return;

            RectTransform first = CreateParallaxImage(root, name + "A", sprite, color);
            RectTransform second = CreateParallaxImage(root, name + "B", sprite, color);
            parallaxLayers.Add(new ParallaxLayer
            {
                A = first,
                B = second,
                Speed = speed,
                Offset = RandomRange(0f, 0.5f),
                ResourcePath = resourcePath
            });
        }

        private static RectTransform CreateParallaxImage(RectTransform root, string name, Sprite sprite, Color color)
        {
            Image image = CreateImage(root, name, color);
            image.sprite = sprite;
            image.type = Image.Type.Simple;
            image.preserveAspect = false;
            image.raycastTarget = false;

            RectTransform rect = image.rectTransform;
            rect.anchorMin = new Vector2(0f, 0.5f);
            rect.anchorMax = new Vector2(1f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.offsetMin = Vector2.zero;
            rect.offsetMax = Vector2.zero;
            return rect;
        }

        private void UpdateStarBands()
        {
            RectTransform root = canvas != null ? canvas.transform as RectTransform : null;
            if (root == null)
                return;

            if (parallaxLayers.Count > 0)
            {
                UpdateSpaceParallax(root);
                return;
            }

            for (int i = 0; i < starBands.Count; i++)
            {
                RectTransform rect = starBands[i] != null ? starBands[i].rectTransform : null;
                if (rect == null)
                    continue;

                rect.anchoredPosition += Vector2.down * (95f + i * 19f) * Time.deltaTime;
                if (rect.anchoredPosition.y < -root.rect.height - 160f)
                    rect.anchoredPosition = new Vector2(RandomRange(-430f, 430f), 120f);
            }
        }

        private void UpdateSpaceParallax(RectTransform root)
        {
            float height = Mathf.Max(1f, root.rect.height);
            float width = Mathf.Max(1f, root.rect.width);
            for (int i = 0; i < parallaxLayers.Count; i++)
            {
                ParallaxLayer layer = parallaxLayers[i];
                layer.Offset = Mathf.Repeat(layer.Offset + layer.Speed * Time.deltaTime / height, 1f);
                float y = Mathf.Repeat(-layer.Offset * height + hangarRevealOffset * SpaceCameraParallaxFactor, height);
                if (y > 0f)
                    y -= height;
                LayoutParallaxTile(layer.A, width, height, y);
                LayoutParallaxTile(layer.B, width, height, y + height);
                parallaxLayers[i] = layer;
            }
        }

        private static void LayoutParallaxTile(RectTransform rect, float width, float height, float y)
        {
            if (rect == null)
                return;

            rect.sizeDelta = new Vector2(width, height + 2f);
            rect.anchoredPosition = new Vector2(0f, y);
        }

        private void BackToMain()
        {
            DoorFx doorFx = DoorFx.EnsureRuntime();
            if (doorFx != null && doorFx.isActiveAndEnabled && doorFx.IsReady())
            {
                doorFx.LoadScene(MainSceneName, OrbiosisDoorSpriteResourcePath);
                return;
            }

            SceneManager.LoadScene(MainSceneName);
        }

        private float RandomRange(float min, float max)
        {
            return min + (float)random.NextDouble() * (max - min);
        }

