        }

        private static bool ApplySpriteFromTextureResource(RectTransform rect, string resourcePath)
        {
            if (rect == null)
                return false;

            Image image = rect.GetComponent<Image>();
            if (image == null)
                return false;

            Sprite sprite = GetSpriteFromTextureResource(resourcePath);
            if (sprite == null)
                return false;

            image.sprite = sprite;
            image.color = Color.white;
            image.preserveAspect = true;
            image.raycastTarget = false;
            return true;
        }

        private static bool ApplyUiSpriteFromTextureResource(RectTransform rect, string resourcePath, bool preserveAspect = false, bool raycastTarget = false)
        {
            if (rect == null)
                return false;

            Image image = rect.GetComponent<Image>();
            if (image == null)
                return false;

            Sprite sprite = GetSpriteFromTextureResource(resourcePath);
            if (sprite == null)
                return false;

            image.sprite = sprite;
            image.overrideSprite = sprite;
            image.type = Image.Type.Simple;
            image.color = Color.white;
            image.preserveAspect = preserveAspect;
            image.raycastTarget = raycastTarget;
            return true;
        }

        private static Sprite GetSpriteFromTextureResource(string resourcePath)
        {
            if (resourceSpriteCache.TryGetValue(resourcePath, out Sprite cachedSprite) && cachedSprite != null)
                return cachedSprite;

            if (string.Equals(resourcePath, OrbStationSpriteResourcePath, System.StringComparison.Ordinal) && orbStationSprite != null)
                return orbStationSprite;

            Sprite directSprite = Resources.Load<Sprite>(resourcePath);
            if (directSprite == null)
                directSprite = Resources.Load<Sprite>(resourcePath + "_0");
            if (directSprite != null)
            {
                resourceSpriteCache[resourcePath] = directSprite;
                if (string.Equals(resourcePath, OrbStationSpriteResourcePath, System.StringComparison.Ordinal))
                    orbStationSprite = directSprite;
                return directSprite;
            }

            Texture2D texture = Resources.Load<Texture2D>(resourcePath);
            if (texture == null)
                return null;

            Sprite generatedSprite = Sprite.Create(texture, new Rect(0f, 0f, texture.width, texture.height), new Vector2(0.5f, 0.5f), 100f);
            generatedSprite.name = resourcePath.Replace("/", "_") + "_Sprite";
            resourceSpriteCache[resourcePath] = generatedSprite;
            if (string.Equals(resourcePath, OrbStationSpriteResourcePath, System.StringComparison.Ordinal))
                orbStationSprite = generatedSprite;
            return generatedSprite;
        }

        private static RectTransform CreateShieldBubble(Transform parent, string name, float size)
        {
            Image image = CreateImage(parent, name, new Color(0.32f, 0.92f, 1f, 0.28f));
            image.sprite = GetShieldBubbleSprite();
            image.type = Image.Type.Simple;
            image.raycastTarget = false;

            RectTransform rect = image.rectTransform;
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = Vector2.one * size;
            rect.anchoredPosition = Vector2.zero;
            rect.SetAsFirstSibling();
            return rect;
        }

        private static Sprite GetShieldBubbleSprite()
        {
            if (shieldBubbleSprite != null)
                return shieldBubbleSprite;

            const int size = 96;
            Texture2D texture = new Texture2D(size, size, TextureFormat.RGBA32, false);
            texture.name = "OrbiosisShieldBubble";
            texture.wrapMode = TextureWrapMode.Clamp;
            texture.filterMode = FilterMode.Bilinear;

            Vector2 center = new Vector2((size - 1) * 0.5f, (size - 1) * 0.5f);
            float radius = size * 0.47f;
            float innerRadius = size * 0.36f;
            float ringRadius = size * 0.43f;

            for (int y = 0; y < size; y++)
            {
                for (int x = 0; x < size; x++)
                {
                    float distance = Vector2.Distance(new Vector2(x, y), center);
                    float normalized = distance / radius;
                    float fill = Mathf.Clamp01(1f - normalized);
                    float ring = Mathf.Clamp01(1f - Mathf.Abs(distance - ringRadius) / 4.5f);
                    float inner = Mathf.Clamp01(1f - Mathf.Abs(distance - innerRadius) / 2.2f) * 0.32f;
                    float alpha = Mathf.Clamp01(fill * 0.16f + ring * 0.82f + inner);
                    if (normalized > 1f)
                        alpha = 0f;

                    texture.SetPixel(x, y, new Color(1f, 1f, 1f, alpha));
                }
            }

            texture.Apply(false, true);
            shieldBubbleSprite = Sprite.Create(texture, new Rect(0f, 0f, size, size), new Vector2(0.5f, 0.5f), 100f);
            shieldBubbleSprite.name = "OrbiosisShieldBubbleSprite";
            return shieldBubbleSprite;
        }

        private static RectTransform CreateCenterBar(Transform parent, string name, Vector2 anchorMin, Vector2 anchorMax, Color trackColor, Color fillColor, string fillSpriteResourcePath = null)
        {
            bool usesCapsuleStyle = !string.IsNullOrEmpty(fillSpriteResourcePath);
            RectTransform track = CreatePanel(parent, name, usesCapsuleStyle ? Color.clear : trackColor);
            track.anchorMin = anchorMin;
            track.anchorMax = anchorMax;
            track.offsetMin = Vector2.zero;
            track.offsetMax = Vector2.zero;
            SetRaycastTarget(track, false);

            if (usesCapsuleStyle)
            {
                Sprite capsule = GetStatusCapsuleSprite();
                RectTransform shadow = CreatePanel(track, "Shadow", new Color(0f, 0f, 0f, 0.34f));
                shadow.anchorMin = new Vector2(0.006f, -0.06f);
                shadow.anchorMax = new Vector2(0.994f, 0.94f);
                shadow.offsetMin = Vector2.zero;
                shadow.offsetMax = Vector2.zero;
                SetRaycastTarget(shadow, false);
                ApplySlicedSprite(shadow, capsule);

                RectTransform border = CreatePanel(track, "Border", new Color(fillColor.r, fillColor.g, fillColor.b, 0.54f));
                Stretch(border);
                ApplySlicedSprite(border, capsule);

                RectTransform rim = CreatePanel(track, "Rim", new Color(0.86f, 1f, 1f, 0.24f));
                rim.anchorMin = new Vector2(0.010f, 0.08f);
                rim.anchorMax = new Vector2(0.990f, 0.92f);
                rim.offsetMin = Vector2.zero;
                rim.offsetMax = Vector2.zero;
                SetRaycastTarget(rim, false);
                ApplySlicedSprite(rim, capsule);

                RectTransform body = CreatePanel(track, "Body", new Color(0.002f, 0.014f, 0.020f, 0.94f));
                body.anchorMin = new Vector2(0.028f, 0.18f);
                body.anchorMax = new Vector2(0.972f, 0.82f);
                body.offsetMin = Vector2.zero;
                body.offsetMax = Vector2.zero;
                SetRaycastTarget(body, false);
                ApplySlicedSprite(body, capsule);

                RectTransform socket = CreatePanel(track, "Socket", new Color(0f, 0f, 0f, 0.40f));
                socket.anchorMin = new Vector2(0.075f, 0.30f);
                socket.anchorMax = new Vector2(0.925f, 0.70f);
                socket.offsetMin = Vector2.zero;
                socket.offsetMax = Vector2.zero;
                SetRaycastTarget(socket, false);
                ApplySlicedSprite(socket, capsule);

                RectTransform capsuleFill = CreatePanel(socket, "Fill", fillColor);
                capsuleFill.offsetMin = Vector2.zero;
                capsuleFill.offsetMax = Vector2.zero;
                SetRaycastTarget(capsuleFill, false);
                ApplySlicedSprite(capsuleFill, capsule);

                RectTransform lowerShade = CreatePanel(socket, "LowerShade", new Color(0f, 0f, 0f, 0.20f));
                lowerShade.anchorMin = new Vector2(0.05f, 0.06f);
                lowerShade.anchorMax = new Vector2(0.95f, 0.36f);
                lowerShade.offsetMin = Vector2.zero;
                lowerShade.offsetMax = Vector2.zero;
                SetRaycastTarget(lowerShade, false);
                ApplySlicedSprite(lowerShade, capsule);

                RectTransform gloss = CreatePanel(socket, "Gloss", new Color(1f, 1f, 1f, 0.20f));
                gloss.anchorMin = new Vector2(0.06f, 0.60f);
                gloss.anchorMax = new Vector2(0.94f, 0.82f);
                gloss.offsetMin = Vector2.zero;
                gloss.offsetMax = Vector2.zero;
                SetRaycastTarget(gloss, false);
                ApplySlicedSprite(gloss, capsule);

                SetCenteredBarFill(capsuleFill, 1f);
                return capsuleFill;
            }

            AddOutline(track, new Color(fillColor.r, fillColor.g, fillColor.b, 0.35f), new Vector2(1.4f, -1.4f));

            RectTransform fill = CreatePanel(track, "Fill", fillColor);
            fill.offsetMin = Vector2.zero;
            fill.offsetMax = Vector2.zero;
            SetRaycastTarget(fill, false);

            RectTransform glow = CreatePanel(fill, "Glow", new Color(1f, 1f, 1f, 0.22f));
            glow.anchorMin = new Vector2(0f, 0.56f);
            glow.anchorMax = new Vector2(1f, 0.96f);
            glow.offsetMin = Vector2.zero;
            glow.offsetMax = Vector2.zero;
            SetRaycastTarget(glow, false);

            SetCenteredBarFill(fill, 1f);
            return fill;
        }

        private static void ApplySlicedSprite(RectTransform rect, Sprite sprite)
        {
            if (rect == null || sprite == null)
                return;

            Image image = rect.GetComponent<Image>();
            if (image == null)
                return;

            image.sprite = sprite;
            image.type = Image.Type.Sliced;
            image.preserveAspect = false;
            image.raycastTarget = false;
        }

        private static Sprite GetStatusCapsuleSprite()
        {
            if (statusCapsuleSprite != null)
                return statusCapsuleSprite;

            const int width = 96;
            const int height = 32;
            const int radius = height / 2 - 1;
            Texture2D texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
            texture.name = "OrbiosisStatusCapsule";
            texture.wrapMode = TextureWrapMode.Clamp;
            texture.filterMode = FilterMode.Bilinear;

            for (int y = 0; y < height; y++)
            {
                for (int x = 0; x < width; x++)
                {
                    float centerX = Mathf.Clamp(x, radius, width - radius - 1);
                    float distance = Vector2.Distance(new Vector2(x, y), new Vector2(centerX, radius));
                    float alpha = Mathf.Clamp01(radius + 0.5f - distance);
                    texture.SetPixel(x, y, new Color(1f, 1f, 1f, alpha));
                }
            }

            texture.Apply(false, true);
            statusCapsuleSprite = Sprite.Create(texture, new Rect(0f, 0f, width, height), new Vector2(0.5f, 0.5f), 100f, 0, SpriteMeshType.FullRect, new Vector4(radius, radius, radius, radius));
            statusCapsuleSprite.name = "OrbiosisStatusCapsuleSprite";
            return statusCapsuleSprite;
        }

        private static void SetCenteredBarFill(RectTransform fill, float value)
        {
            if (fill == null)
                return;

            float half = Mathf.Clamp01(value) * 0.5f;
            fill.anchorMin = new Vector2(0.5f - half, 0f);
            fill.anchorMax = new Vector2(0.5f + half, 1f);
            fill.offsetMin = Vector2.zero;
            fill.offsetMax = Vector2.zero;
        }

        private static void UpdateStatusBarFill(RectTransform fill, float value, Color normalColor, Color lowColor, bool blinkWhenLow)
        {
            if (fill == null)
                return;

            float ratio = Mathf.Clamp01(value);
            SetCenteredBarFill(fill, ratio);
            Image image = fill.GetComponent<Image>();
            if (image == null)
                return;

            Color color = Color.Lerp(lowColor, normalColor, Mathf.Clamp01(ratio * 1.8f));
            if (blinkWhenLow && ratio > 0f && ratio <= 0.25f)
            {
                float pulse = 0.45f + Mathf.Abs(Mathf.Sin(Time.unscaledTime * 8.8f)) * 0.55f;
                color = Color.Lerp(color, new Color(1f, 0.06f, 0.03f, normalColor.a), 0.55f);
                color.a = Mathf.Lerp(0.38f, normalColor.a, pulse);
            }

            image.color = color;
        }

        private static TextMeshProUGUI CreateText(Transform parent, string name, string value, float size, FontStyles style, Color color)
        {
            GameObject go = new GameObject(name, typeof(RectTransform), typeof(CanvasRenderer), typeof(TextMeshProUGUI));
            go.transform.SetParent(parent, false);
            TextMeshProUGUI text = go.GetComponent<TextMeshProUGUI>();
            text.text = value;
            text.fontSize = size;
            text.fontStyle = style;
            text.color = color;
            text.alignment = TextAlignmentOptions.Center;
            text.enableAutoSizing = true;
            text.fontSizeMin = Mathf.Max(16f, size * 0.62f);
            text.fontSizeMax = size;
            text.raycastTarget = false;
            MainLobbyButtonStyle.ApplyFont(text);
            BindLocalizedTextIfNeeded(text, value);
            return text;
        }

        private static TextMeshProUGUI CreateTechText(Transform parent, string name, string value, float size, FontStyles style, Color color)
        {
            GameObject go = new GameObject(name, typeof(RectTransform), typeof(CanvasRenderer), typeof(TextMeshProUGUI));
            go.transform.SetParent(parent, false);
            TextMeshProUGUI text = go.GetComponent<TextMeshProUGUI>();
            text.text = value;
