            text.fontSizeMax = size;
            text.characterSpacing = 2f;
            text.raycastTarget = false;
            MainLobbyButtonStyle.ApplyFont(text);
            BindLocalizedTextIfNeeded(text, value);
            return text;
        }

        private static string K(string suffix)
        {
            return LocalizationPrefix + suffix;
        }

        private static string L(string suffix)
        {
            return GameLocalization.Text(K(suffix));
        }

        private static string LF(string suffix, params object[] args)
        {
            return GameLocalization.Format(K(suffix), args);
        }

        private static void BindLocalizedTextIfNeeded(TMP_Text text, string value)
        {
            if (text == null || string.IsNullOrEmpty(value) || !value.StartsWith(LocalizationPrefix, StringComparison.Ordinal))
                return;

            LocalizedText localized = text.gameObject.GetComponent<LocalizedText>() ?? text.gameObject.AddComponent<LocalizedText>();
            localized.SetKey(value);
        }

