        private static void AddTechCorner(RectTransform parent, string name, Vector2 anchorMin, Vector2 anchorMax, Vector2 size)
        {
            RectTransform corner = CreatePanel(parent, name, new Color(0.16f, 0.92f, 1f, 0.56f));
            corner.anchorMin = anchorMin;
            corner.anchorMax = anchorMax;
            corner.pivot = new Vector2(anchorMin.x >= 1f ? 1f : anchorMax.x <= 0f ? 0f : 0.5f, anchorMin.y >= 1f ? 1f : anchorMax.y <= 0f ? 0f : 0.5f);
            corner.sizeDelta = size;
            corner.anchoredPosition = Vector2.zero;
            SetRaycastTarget(corner, false);
        }

        private Button CreateButton(Transform parent, string name, string label, Vector2 anchorMin, Vector2 anchorMax, Vector2 position, Vector2 size, float fontSize, UnityEngine.Events.UnityAction action)
        {
            GameObject go = new GameObject(name, typeof(RectTransform), typeof(CanvasRenderer), typeof(Image), typeof(Button));
            go.transform.SetParent(parent, false);
            RectTransform rect = go.GetComponent<RectTransform>();
            rect.anchorMin = anchorMin;
            rect.anchorMax = anchorMax;
            rect.pivot = new Vector2(anchorMax.x >= 1f ? 1f : anchorMin.x <= 0f ? 0f : 0.5f, 0.5f);
            rect.anchoredPosition = position;
            rect.sizeDelta = size;

            Image image = go.GetComponent<Image>();
            Sprite buttonSprite = GetSpriteFromTextureResource(UiButtonSpriteResourcePath);
            if (buttonSprite != null)
            {
                image.sprite = buttonSprite;
                image.color = Color.white;
                image.preserveAspect = false;
            }
            else
            {
                image.color = new Color(0.04f, 0.15f, 0.22f, 0.96f);
                AddOutline(rect, new Color(0.16f, 0.80f, 0.92f, 0.45f), new Vector2(2f, -2f));
            }

            Button button = go.GetComponent<Button>();
            ColorBlock colors = button.colors;
            colors.normalColor = Color.white;
            colors.highlightedColor = new Color(0.78f, 0.94f, 1f, 1f);
            colors.pressedColor = new Color(0.56f, 0.76f, 0.90f, 1f);
            colors.colorMultiplier = 1f;
            button.colors = colors;

            float buttonFontSize = Mathf.Max(fontSize, 18f);
            TextMeshProUGUI text = CreateText(go.transform, "Label", label, buttonFontSize, FontStyles.Bold, Ink);
            Stretch(text.rectTransform);
            text.rectTransform.offsetMin = new Vector2(8f, 0f);
            text.rectTransform.offsetMax = new Vector2(-8f, 0f);
            text.fontSizeMin = Mathf.Max(12f, buttonFontSize * 0.58f);
            text.fontSizeMax = buttonFontSize;
            button.onClick.AddListener(PlayButtonClick);
            button.onClick.AddListener(action);
            return button;
        }

        private Button CreateTechnologyButton(Transform parent, string name, string label, Vector2 anchorMin, Vector2 anchorMax, float fontSize, UnityEngine.Events.UnityAction action)
        {
            GameObject go = new GameObject(name, typeof(RectTransform), typeof(CanvasRenderer), typeof(Image), typeof(Button));
            go.transform.SetParent(parent, false);
            RectTransform rect = go.GetComponent<RectTransform>();
            rect.anchorMin = anchorMin;
            rect.anchorMax = anchorMax;
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.anchoredPosition = Vector2.zero;
            rect.sizeDelta = Vector2.zero;

            Image image = go.GetComponent<Image>();
            image.color = new Color(0.45f, 0.31f, 0.06f, 0.96f);
            if (!ApplyUiSpriteFromTextureResource(rect, TechGoldButtonSpriteResourcePath, false, true))
                AddOutline(rect, new Color(1f, 0.82f, 0.20f, 0.52f), new Vector2(1f, -1f));

            Button button = go.GetComponent<Button>();
            ColorBlock colors = button.colors;
            colors.normalColor = Color.white;
            colors.highlightedColor = new Color(1f, 0.94f, 0.72f, 1f);
            colors.pressedColor = new Color(0.92f, 0.72f, 0.36f, 1f);
            colors.colorMultiplier = 1f;
            button.colors = colors;
            button.targetGraphic = image;

            TextMeshProUGUI text = CreateTechText(go.transform, "Label", label, fontSize, FontStyles.Bold, Ink);
            text.enableAutoSizing = false;
            Stretch(text.rectTransform);
            text.rectTransform.offsetMin = new Vector2(18f, 0f);
            text.rectTransform.offsetMax = new Vector2(-18f, 0f);
            text.raycastTarget = false;
            button.onClick.AddListener(PlayButtonClick);
            button.onClick.AddListener(action);
            return button;
        }

        private Button CreateMinimalButton(Transform parent, string name, string label, Vector2 anchorMin, Vector2 anchorMax, float fontSize, UnityEngine.Events.UnityAction action)
        {
            GameObject go = new GameObject(name, typeof(RectTransform), typeof(CanvasRenderer), typeof(Image), typeof(Button));
            go.transform.SetParent(parent, false);
            RectTransform rect = go.GetComponent<RectTransform>();
            rect.anchorMin = anchorMin;
            rect.anchorMax = anchorMax;
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.anchoredPosition = Vector2.zero;
            rect.sizeDelta = Vector2.zero;

            Image image = go.GetComponent<Image>();
            image.color = new Color(0.006f, 0.034f, 0.044f, 0.96f);
            if (!ApplyUiSpriteFromTextureResource(rect, TechTabSpriteResourcePath, false, true))
                AddOutline(rect, new Color(0.18f, 0.86f, 1f, 0.18f), new Vector2(1f, -1f));

            Button button = go.GetComponent<Button>();
            ColorBlock colors = button.colors;
            colors.normalColor = Color.white;
            colors.highlightedColor = new Color(0.88f, 1f, 1f, 1f);
            colors.pressedColor = new Color(0.70f, 0.90f, 0.96f, 1f);
            colors.colorMultiplier = 1f;
            button.colors = colors;

            RectTransform activeLine = CreatePanel(go.transform, "ActiveLine", new Color(0.10f, 0.94f, 1f, 0.95f));
            activeLine.anchorMin = new Vector2(0.08f, 0f);
            activeLine.anchorMax = new Vector2(0.92f, 0.050f);
            activeLine.offsetMin = Vector2.zero;
            activeLine.offsetMax = Vector2.zero;
            activeLine.gameObject.SetActive(false);
            SetRaycastTarget(activeLine, false);

            TextMeshProUGUI text = CreateTechText(go.transform, "Label", label, fontSize, FontStyles.Bold, Ink);
            Stretch(text.rectTransform);
            text.rectTransform.offsetMin = new Vector2(6f, 0f);
            text.rectTransform.offsetMax = new Vector2(-6f, 0f);
            text.fontSizeMin = Mathf.Max(18f, fontSize * 0.74f);
            text.fontSizeMax = fontSize;
            button.onClick.AddListener(PlayButtonClick);
            button.onClick.AddListener(action);
            return button;
        }

        private static void AddOutline(RectTransform rect, Color color, Vector2 distance)
        {
            if (rect == null)
                return;

            Outline outline = rect.gameObject.GetComponent<Outline>();
            if (outline == null)
                outline = rect.gameObject.AddComponent<Outline>();

            outline.effectColor = color;
            outline.effectDistance = distance;
            outline.useGraphicAlpha = true;
        }

        private static void Stretch(RectTransform rect)
        {
            rect.anchorMin = Vector2.zero;
            rect.anchorMax = Vector2.one;
            rect.offsetMin = Vector2.zero;
            rect.offsetMax = Vector2.zero;
            rect.localScale = Vector3.one;
        }

        private static void SetRaycastTarget(RectTransform rect, bool value)
        {
            if (rect == null)
                return;

            Image image = rect.GetComponent<Image>();
            if (image != null)
                image.raycastTarget = value;
        }

        private static void UpdateSymbioteLinkVisual(HazardView hazard)
        {
            if (hazard == null || hazard.Root == null)
                return;

            float pulse = 1f + Mathf.Sin(Time.time * 8.4f) * 0.16f;
            hazard.Root.localScale = Vector3.one * pulse;

            Transform pulseTransform = hazard.Root.Find("LinkPulse");
            RectTransform pulseRect = pulseTransform as RectTransform;
            if (pulseRect != null)
            {
                pulseRect.localScale = Vector3.one * (1.05f + Mathf.Sin(Time.time * 6.2f) * 0.22f);
                Image pulseImage = pulseRect.GetComponent<Image>();
                if (pulseImage != null)
                    pulseImage.color = new Color(0.12f, 0.95f, 0.74f, 0.20f + Mathf.Sin(Time.time * 6.2f) * 0.08f);
            }

            Transform coreTransform = hazard.Root.Find("LinkCore");
            RectTransform coreRect = coreTransform as RectTransform;
            if (coreRect != null)
                coreRect.Rotate(0f, 0f, -180f * Time.deltaTime);
        }

